P.entries["subzone:bolgan-s-hole"] = {n="Пещера Болгана",s="Пещера Болгана — подземная пещера в южных утесах Деревни Гелкис в Пустошах. Это тайное святилище клана кентавров Гелкис, где живут их высшие вожди и хранятся священные реликвии земли.",h="Пещера Болгана — подземная пещера в южных утесах Деревни Гелкис в Пустошах.",kw={"bolgan's hole","centaur","desolace","gelkis","khan shaka","khan shodo","tears of theradras","пещера болгана","кентавр","пустоши","гелкис","вождь шак","хан шодо","слезы терадрас"},ang={["class:Shaman"]="Пещера мрачно показывает, как можно извратить поклонение земле, если связать его с жестоким наследием принцессы Терадрас, а не с природным равновесием духов."},sec={{t="Престол власти Гелкис",b="Пещера Болгана, глубоко вырубленная в скалистых обрывах над лагерем Гелкис, служит племени командным центром. Здесь вершит суд правящий хан, окруженный ветеранами-стражами и самыми влиятельными шаманами племени. Пещера дает естественную защиту от враждебных кланов, прежде всего от кровожадных кентавров Маграм на востоке."},{t="Слезы принцессы земли",b="Помимо военного значения, пещера имеет для Гелкис глубокий религиозный смысл. С сырых каменных стен растут светящиеся голубые минеральные образования — слезы Терадрас. Шаманы Гелкис неустанно собирают и охраняют эти кристаллы, почитая их как божественные дары, дающие подземную защиту принцессы Терадрас, первобытной элементальной матери расы кентавров."}},faq={{q="Где находится Пещера Болгана?",a="Пещера Болгана расположена в южной части Деревни Гелкис, среди холмов юга Пустошей.",al={"bolgans hole location","where is bolgan's hole","bolgan cave entrance","расположение пещеры болгана","где пещера болгана","вход в пещеру болгана"}},{q="Кто живет в Пещере Болгана?",a="В пещере обитает верхушка кентавров Гелкис, включая хана клана — например, вождя Шака, — а также их ближний круг защитников и мистических шаманов.",al={"who is in bolgan's hole","bolgans hole boss","gelkis khan location","кто в пещере болгана","босс пещеры болгана","где хан гелкис"}},{q="Что за светящиеся голубые кристаллы в пещере?",a="Эти кристаллы известны как слезы Терадрас. Гелкис почитают их как зримое воплощение благосклонности своей матери-земли и верят, что камни дают мистическую защиту тем, кто ими владеет.",al={"blue crystals in bolgan's hole","tears of theradras","bolgan's hole rocks","голубые кристаллы пещеры болгана","слезы терадрас","камни пещеры болгана"}},{q="Можно ли безопасно входить в Пещеру Болгана?",a="По умолчанию кентавры Гелкис внутри крайне враждебны к чужакам. Однако путники, примкнувшие к Гелкис и истребляющие их ненавистных соперников — клан Маграм, — могут заслужить право спокойно ходить по пещере.",al={"is bolgan's hole hostile","friendly to gelkis","can i go inside bolgans hole","враждебна ли пещера болгана","дружба с гелкис","можно ли войти в пещеру болгана"}}},fp="13,217,24.365.0,27.409.0,31.116.0,31.173.0,51.204.0,39.230.0"}
P.entries["subzone:bones-of-grakkarond"] = {n="Кости Граккаронда",s="Кости Граккаронда — скелет огромного бронзового дракона, выбеленный солнцем в центральной части Силитуса. Этот дракон, павший в древней Войне Зыбучих Песков, служит мрачным памятником, священным для стражей Анубисат киражей.",h="Кости Граккаронда — скелет огромного бронзового дракона, выбеленный солнцем в центральной части Силитуса.",kw={"anubisath","bones of grakkarond","bronze dragon","grakkarond","ossirian the unscarred","silithus","war of the shifting sands","анубисат","кости граккаронда","бронзовый дракон","граккаронд","оссириан неуязвимый","силитус","война зыбучих песков"},ang={["race:NightElf"]="Скелет — яркое напоминание о Войне Зыбучих Песков, когда кальдораи и четыре драконьих рода сражались бок о бок, чтобы отразить натиск киражей."},sec={{t="Памятник Зыбучих Песков",b="На продуваемых ветрами дюнах центрального Силитуса раскинулись исполинские ребра и череп Граккаронда, бронзового дракона, погибшего в древней Войне Зыбучих Песков. В том апокалиптическом сражении тысячу лет назад великого дракона сразил Оссириан Неуязвимый, воин-анубисат, возвышенный темными силами города-королевства. Для анубисатов этот боевой трофей — священное свидетельство их могущества над драконьими родами, оставленное нетронутым там, где дракон пал."}},faq={{q="Чьи это кости?",a="Это останки Граккаронда, великого бронзового дракона из бронзового драконьего рода. Он пал в битве с насекомоподобными силами Ан'Киража тысячу лет назад во время Войны Зыбучих Песков.",al={"who was grakkarond","what dragon died here","dragon skeleton silithus","кто такой граккаронд","какой дракон погиб здесь","скелет дракона силитус"}},{q="Кто убил Граккаронда?",a="Граккаронда убил воин-анубисат Оссириан Неуязвимый. Победа над бронзовым змеем принесла Оссириану огромную славу и темные дары от повелителей Ан'Киража.",al={"who killed the dragon","how did grakkarond die","кто убил дракона","как погиб граккаронд"}},{q="Почему анубисаты почитают это место?",a="Анубисаты считают скелет священным, потому что он напоминает об их решающей победе над могучим драконьим родом. Он стоит среди открытых дюн как торжествующий символ их силы против тех, кто пришел запечатать их.",al={"why are the bones sacred","anubisath bones","почему кости священны","кости анубисатов"}}},fp="19,269,32.494.0,22.205.0,22.185.0,39.228.0"}
P.entries["subzone:booty-bay"] = {n="Пиратская бухта",s="Пиратская бухта — раскинувшаяся пиратская гавань, встроенная в отвесные морские утесы на юге Тернистой долины; ею управляют Налетчики Черноводья из Картеля Хитрая Шестеренка. Сюда ведет сухопутный вход через раскрытую пасть туши гигантской акулы. Это строго охраняемый нейтральный порт, где Альянс и Орда соседствуют под бдительным надзором хорошо вооруженных гоблинов-громил.",h="Пиратская бухта — раскинувшаяся пиратская гавань, встроенная в отвесные морские утесы на юге Тернистой...",kw={"blackwater raiders","bloodsail buccaneers","booty bay","ratchet","revilgaz","salty sailor","seahorn","steamwheedle cartel","stranglethorn","налетчики черноводья","пираты кровавого паруса","пиратская бухта","кабестан","ревилгаз","соленый моряк","морской рог","картель хитрая шестеренка","тернистая долина"},ang={["class:Rogue"]="Пиратская бухта, известная как рай для негодяев, кишит связями в преступном мире, скупщиками краденого, запертыми сундуками и тайными информаторами, готовыми обменять секреты на золото.",["faction:Alliance"]="Далеко к югу от защищенных границ Штормграда Пиратская бухта предлагает путникам Альянса редкие нейтральные удобства, полетные маршруты и морской путь прямо в Калимдор."},sec={{t="Логово негодяев и наживы",b="Бухта Черноводья — так называлось человеческое поселение, позже захваченное троллями джунглей; еще до Первой войны ею завладели гоблины Картеля Хитрая Шестеренка. Сегодня это международный перекресток и пристанище для негодяев, изгоев и торговцев. Порт находится под надзором барона Ревилгаза и командира флота Морского Рога, которые наблюдают за ним с балконов Таверны «Соленый моряк». Формально здесь нет закона, но порядок строго соблюдается: любой может выпить, поторговать или нанять наемников, если соблюдает мир Картеля и платит портовые сборы."},{t="Опасности на воде",b="Оживленные причалы Пиратской бухты напрямую связывают Восточные королевства с Кабестаном через Великое море, делая ее важнейшим узлом торговли и путешествий между континентами. Однако огромное богатство привлекает неослабную враждебность. Главный враг города — Пираты Кровавого Паруса, агрессивный пиратский флот, который постоянно нападает на суда Черноводья, бороздит побережье Тернистой долины и замышляет полное разрушение и разграбление гоблинского порта."}},faq={{q="Кто правит Пиратской бухтой?",a="Портом правит барон Ревилгаз, видная фигура Картеля Хитрая Шестеренка, в тесном союзе с командиром флота Морским Рогом, тауреном, возглавляющим Налетчиков Черноводья. Оба руководят делами с верхних палуб Таверны «Соленый моряк», откуда видна гавань.",al={"booty bay leader","who is in charge of booty bay","booty bay boss","лидер пиратской бухты","кто правит пиратской бухтой","босс пиратской бухты"}},{q="Почему игроки Альянса и Орды могут находиться здесь вместе?",a="Пиратской бухтой управляет нейтральный Картель Хитрая Шестеренка, для которого выгода и торговля важнее вражды фракций. Картель строго соблюдает нейтралитет: рад любому, у кого есть деньги, и обрушивает элитных гоблинов-громил на всякого, кто глупо затеет драку.",al={"why is booty bay neutral","booty bay safe zone","can horde attack alliance here","почему пиратская бухта нейтральна","пиратская бухта безопасная зона","может ли орда напасть на альянс здесь"}},{q="Кто такие Пираты Кровавого Паруса?",a="Пираты Кровавого Паруса — соперничающий преступный синдикат, находящийся в ожесточенной войне с Налетчиками Черноводья. Они владеют кораблями вдоль южного побережья Тернистой долины и замышляют захватить Пиратскую бухту и ее прибыльную гавань.",al={"bloodsail pirates","why do bloodsail hate booty bay","bloodsail buccaneers lore","пираты кровавого паруса","почему пираты кровавого паруса ненавидят пиратскую бухту","предания пиратов кровавого паруса"}},{q="Куда плывет корабль из Пиратской бухты?",a="Пассажирский корабль с нижних причалов плывет через Великое море прямо в портовый город Кабестан в Степях, обеспечивая основной нейтральный путь между югом Восточных королевств и Калимдором.",al={"booty bay boat destination","where does the ship go","boat to kalimdor","куда плывет корабль из пиратской бухты","куда идет корабль","корабль в калимдор"}},{q="Что это за гигантская статуя у входа в бухту?",a="Огромная статуя неизвестного гоблина с распростертыми руками стоит на Острове Жанейро у входа в гавань. Она служит навигационным маяком и приветственным памятником для входящих торговых кораблей и пиратских команд.",al={"booty bay statue","colossus of booty bay","statue on the island","статуя пиратской бухты","колосс пиратской бухты","статуя на острове"}}},fp="9,361,30.568.0,20.455.0,20.281.0,55.273.0,33.237.0,38.224.0,56.223.0"}
P.entries["subzone:boulder-gor"] = {n="Камен'гор",s="Камен'гор — скалистый холм на западе Нагорья Арати, расположенный прямо к северу от разрушенного человеческого королевства Стромгард. Это действующий лагерь огров Тяжелого Кулака и их необычных союзников — лесных троллей Сухокожих.",h="Камен'гор — скалистый холм на западе Нагорья Арати, расположенный прямо к северу от разрушенного...",kw={"arathi highlands","boulder'gor","boulderfist","bouldergor","ogres","stromgarde","witherbark","нагорье арати","камен'гор","тяжелый кулак","огры","стромгард","сухокожие"},ang={["faction:Alliance"]="Для сил Альянса, стремящихся вернуть Стромгард, Камен'гор — серьезная угроза, затаившаяся прямо на северном пороге павшего королевства.",["race:Troll"]="Тролли Черного Копья, посетившие нагорье, не найдут здесь родства: лесные тролли Сухокожие из Камен'гора питают глубокую древнюю обиду на всех чужаков, включая другие племена троллей."},sec={{t="Логово огров и троллей",b="Камен'гор, поднимающийся к северу от рушащихся стен Крепости Стромгард, — крутой утес, принадлежащий клану Тяжелого Кулака. В его тени расположен курган Заставы Тяжелого Кулака, что делает его главным оплотом силы огров на нагорье. Необычно, что огры делят свои костры и укрепления с лесными троллями племени Сухокожих, включая зловещих заклинателей, которые добавляют темную магию к грубой силе клана. Это сотрудничество постоянно угрожает всем путникам на центральных дорогах Арати."},{t="Окрестные земли",b="Склоны вокруг Камен'гора смотрят на открытое нагорье западного Арати. Зажатый между руинами Стромгарда, куда проник Синдикат, и дикими стихийными местами равнин, Камен'гор остается хорошо охраняемым и враждебным оплотом племенной солидарности против странников как Альянса, так и Орды."}},faq={{q="Что такое Камен'гор?",a="Камен'гор — возвышенный холм и лагерь к северу от Крепости Стромгард на Нагорье Арати. Его густо населяют огры Тяжелого Кулака и лесные тролли Сухокожие.",al={"where is bouldergor","bouldergor info","what is this place","где камен'гор","камен'гор информация","что это за место"}},{q="Почему здесь лесные тролли живут рядом с ограми?",a="Тролли Сухокожие и огры Тяжелого Кулака поддерживают прагматичный союз в Арати. Обе стороны стремятся сохранить господство на нагорье и отражать соперников, сочетая тролльское колдовство теней с грубой силой огров.",al={"why are trolls here","witherbark ogre alliance","trolls and ogres","почему здесь тролли","союз сухокожих и огров","тролли и огры"}},{q="Какие значимые места находятся рядом с Камен'гором?",a="Камен'гор расположен прямо к северу от Крепости Стромгард, а курган огров — Застава Тяжелого Кулака — находится на самом холме.",al={"nearby places","what is next to bouldergor","landmarks","ближайшие места","что рядом с камен'гором","ориентиры"}},{q="Дружелюбен ли Камен'гор к Орде или Альянсу?",a="Ни к кому. Огры Тяжелого Кулака и тролли Сухокожие Камен'гора совершенно враждебны и к Альянсу, и к Орде и яростно защищают свой холм от чужаков.",al={"can i go there safely","is bouldergor hostile","безопасно ли туда идти","враждебен ли камен'гор"}}},fp="11,249,25.542.0,21.312.0,20.171.0,50.216.0,42.122.0,49.174.0"}
P.entries["subzone:boulder-lode-mine"] = {n="Каменный карьер",s="Каменный карьер — агрессивная выработка, прорезанная в холмах северо-востока Степей. Хотя орочьи знамена и сторожевые башни говорят о том, что место основала Орда, теперь им прочно завладела и управляет беспощадная Торговая Компания.",h="Каменный карьер — агрессивная выработка, прорезанная в холмах северо-востока Степей.",kw={"boss copperplug","boulder lode mine","dizzywig","miner's fortune","samophlange manual","the barrens","venture company","начальник медноклин","каменный карьер","головокружилкинс","богатство шахтера","руководство самофланца","степи","торговая компания"},ang={["faction:Horde"]="Вид Торговой Компании, хозяйничающей в укреплениях со знаменами Орды, — досадное напоминание о том, как агрессивно гоблинский картель вторгается в земли Калимдора.",["profession:Mining"]="Глубокие шахтные туннели врезаются прямо в сухие холмы и открывают богатые рудные жилы, которые Торговая Компания безжалостно истощает."},sec={{t="Корпоративные владения",b="Обветшалая орочья архитектура у входа в Каменный карьер указывает, что когда-то этот участок принадлежал Орде или был ею основан. Однако сегодня здесь кишат надсмотрщики и громилы Торговой Компании под руководством начальника Медноклина. Гоблинский синдикат разрабатывает каньон открытым способом, мало заботясь об окружающей природе и рабочих, и ищет лишь ценные минералы, драгоценные камни и промышленные механизмы."},{t="Самоцветы и схемы",b="Слух о богатствах, добытых в Каменном карьере, дошел до чужих ушей в Кабестане. Управляющий пристанью Головокружилкинс послал наемников прикарманить огромный изумруд, найденный, по слухам, в его туннелях, а инженеры, желающие разобраться в сложных гоблинских механизмах, знают, что начальник Медноклин хранит ключевые руководства по эксплуатации в своем лагере."}},faq={{q="Кто управляет Каменным карьером?",a="Карьером управляет Торговая Компания под непосредственной властью начальника Медноклина; его охраняют хорошо вооруженные корпоративные громилы и надсмотрщики.",al={"who runs boulder lode mine","boulder lode boss","who is in boulder lode","кто управляет каменным карьером","босс каменного карьера","кто в каменном карьере"}},{q="Принадлежал ли этот карьер изначально Орде?",a="Сохранившиеся орочьи постройки из дерева, сторожевые башни и обветшалые знамена Орды ясно указывают, что Орда первой основала или заняла это место, прежде чем туда пришла Торговая Компания и взяла его под контроль.",al={"orc banners at boulder lode","horde mine","why are there horde flags","орочьи знамена в каменном карьере","карьер орды","почему здесь флаги орды"}},{q="Почему Управляющий пристанью Головокружилкинс интересуется этим местом?",a="Головокружилкинс прослышал, что шахтер в Каменном карьере откопал необычайно крупный и ценный изумруд, и нанимает отчаянных наемников, чтобы они пробрались в туннели и украли его за долю прибыли.",al={"dizzywig mine quest","emerald quest barrens","miners fortune","задание головокружилкинса","задание с изумрудом степи","богатство шахтера"}},{q="Как начальник Медноклин связан с самофланцем?",a="У начальника Медноклина хранится важное руководство по эксплуатации загадочного механизма — самофланца, найденного неподалеку, а инженеры Кабестана посылают искателей приключений вернуть книгу и ее разрозненные страницы у его шайки.",al={"samophlange manual boulder lode","copperplug manual","rilli greasygob mine","руководство самофланца каменный карьер","руководство медноклина","рилли жирнотряп карьер"}}},fp="17,247,15.464.0,19.338.0,31.159.0,39.200.0,53.201.0,56.212.0"}
P.entries["subzone:boulderfist-hall"] = {n="Крепость Тяжелого Кулака",s="Крепость Тяжелого Кулака — сильно укрепленный курган огров в южных холмах Нагорья Арати, к северу от Моста Тандола. Это местный оплот огров Тяжелого Кулака, которые под командованием Кор'греша Холодной Ярости распространяют грубое влияние на соседние торговые пути и долины.",h="Крепость Тяжелого Кулака — сильно укрепленный курган огров в южных холмах Нагорья Арати, к северу от Моста...",kw={"arathi highlands","boulderfist","boulderfist hall","kor'gresh coldrage","ogre mound","phalanax","thandol span","нагорье арати","тяжелый кулак","крепость тяжелого кулака","кор'греш холодная ярость","курган огров","фаланакс","мост тандола"},ang={["faction:Alliance"]="Огры Тяжелого Кулака, расположенные прямо над Мостом Тандола, постоянно угрожают засадами курьерам и подкреплениям Альянса, идущим на север из Стальгорна в Арати.",["faction:Horde"]="Чтобы закрепиться на Нагорье Арати, нужно сломить независимую силу огров и расчистить южный хребет, обезопасив передвижения Орды из Павшего Молота."},sec={{t="Оплот грубой силы",b="Крепость Тяжелого Кулака, высеченная в скалистых южных утесах Нагорья Арати, — главный оплот клана Тяжелого Кулака в этом краю. За ее земляными валами и в глубоких пещерах огры-громилы и маги держат укрепленное поселение в двух шагах от Деревни Сухокожих и стратегического моста у Моста Тандола. В глубине кургана затаился их вождь в этой области, Кор'греш Холодная Ярость, вместе с такими стражами, как Фаланакс. Из этого оплота огры жестоко контролируют окрестные дороги, делая любой мирный путь между Арати и Болотиной опасным как для путников, так и для торговых караванов."}},faq={{q="Что такое Крепость Тяжелого Кулака?",a="Это укрепленный курган огров с комплексом пещер на юге Нагорья Арати, служащий базой клана Тяжелого Кулака на этой территории.",al={"what is this place","boulderfist mound","ogre cave arathi","что это за место","курган тяжелого кулака","пещера огров арати"}},{q="Кто правит Крепостью Тяжелого Кулака?",a="Оплотом руководит вождь огров Кор'греш Холодная Ярость, который управляет кланом из глубокой пещеры внутри кургана вместе с такими воинами, как Фаланакс.",al={"who leads boulderfist hall","ogre boss arathi","kor'gresh","кто возглавляет крепость тяжелого кулака","босс огров арати","кор'греш"}},{q="Почему это место стратегически важно?",a="Близость к Мосту Тандола позволяет ограм Тяжелого Кулака угрожать жизненно важному сухопутному пути, соединяющему Нагорье Арати с Каз Моданом, перекрывая движение и вступая в стычки с соседними троллями и путниками.",al={"why ogres here","thandol span danger","почему здесь огры","опасность моста тандола"}},{q="Союзны ли Тяжелый Кулак соседним троллям Сухокожим?",a="Нет. Огры Тяжелого Кулака и лесные тролли Деревни Сухокожих живут рядом, но остаются независимыми и враждебными силами, соперничающими за господство в Арати.",al={"ogres and trolls friends","witherbark alliance","огры и тролли друзья","союз сухокожих"}}},fp="16,315,27.633.0,25.157.0,27.153.0,45.217.0,61.182.0"}
P.entries["subzone:boulderfist-outpost"] = {n="Застава Тяжелого Кулака",s="Застава Тяжелого Кулака — укрепленный холм в глубине поселения огров Камен'гор на Нагорье Арати. Она служит внутренним логовом и местом содержания пленников, и в ней обитают свирепые огры Тяжелого Кулака и несколько троллей из племени Сухокожих.",h="Застава Тяжелого Кулака — укрепленный холм в глубине поселения огров Камен'гор на Нагорье Арати.",kw={"arathi","boulder'gor","boulderfist","captives","kovork","ogre mound","prisoners","witherbark","арати","камен'гор","тяжелый кулак","пленники","коворк","холм огров","сухокожие"},ang={["faction:Alliance"]="Разведчикам Альянса, путешествующим по Арати, следует обходить холм стороной: надсмотрщики Тяжелого Кулака внутри нападают на любого чужака без раздумий.",["faction:Horde"]="Огры Тяжелого Кулака не делают различий между фракциями и нападают на бродяг из Орды так же охотно, как и на их соперников из Альянса."},sec={{t="Оплот внутри холма",b="Застава Тяжелого Кулака, вырытая в земле и камне западной части Арати, является сердцем Камен'гора. Пока на поверхности поселением заправляют грубые надсмотрщики, внутри заставы сосредоточена основная сила клана, а также находится мрачное подземное убежище. Несколько троллей-знахарей из племени Сухокожих порой бродят здесь среди огров, что намекает на непрочное сотрудничество племен."}},faq={{q="Где находится Застава Тяжелого Кулака?",a="Застава Тяжелого Кулака — это внутренний холм в большом поселении огров Камен'гор, расположенном в западных просторах Нагорья Арати.",al={"boulderfist outpost location","where is boulderfist outpost","boulderfist mound entrance","где застава тяжелого кулака","расположение заставы тяжелого кулака","вход в холм тяжелого кулака"}},{q="Почему в заставе огров есть тролли?",a="Лесные тролли Сухокожие живут неподалеку, на Нагорье Арати, и порой делят землю с ограми Тяжелого Кулака. Несколько знахарей Сухокожих занимаются своим ремеслом в глубине заставы рядом с ограми.",al={"why are witherbark here","trolls in boulderfist","witherbark trolls arathi","почему здесь сухокожие","тролли у тяжелого кулака","тролли сухокожие арати"}},{q="Кто заточен на заставе?",a="Сейчас на заставе нет ни одного известного поименно пленника. Ее сырые коридоры принадлежат надсмотрщикам Тяжелого Кулака и нескольким знахарям Сухокожих, и любому, кто забредет внутрь, стоит ждать скорее битвы, чем спасения.",al={"boulderfist prisoners","who is trapped in boulderfist","captives in arathi ogres","пленники тяжелого кулака","кто заперт у тяжелого кулака","пленники огров арати"}},{q="Кто командует ограми на заставе?",a="Пока свирепые огры-надсмотрщики клана патрулируют внутреннюю часть, внутри кургана, как известно, скрывается исключительно яростный огр по имени Коворк, представляющий серьезную угрозу.",al={"kovork","boulderfist boss arathi","boulderfist rare","коворк","главарь тяжелого кулака арати","редкий огр тяжелого кулака"}}},fp="19,239,29.390.0,37.154.0,44.240.0,33.219.0,39.150.0"}
P.entries["subzone:boulderslide-cavern"] = {n="Пещера Камнепадов",s="Пещера Камнепадов — подземный лабиринт в самом конце Ущелья Камнепадов в Когтистых горах. Это главное логово и место раскопок местных кобольдов Камнепадов, которые одержимо роют туннели в поисках светящихся минеральных образований.",h="Пещера Камнепадов — подземный лабиринт в самом конце Ущелья Камнепадов в Когтистых горах.",kw={"boulderslide","cavern","earthen","goggeroc","kobold","resonite","stonetalon","камнепады","пещера","земельник","гоггерок","кобольд","резонит","когтистые горы"},ang={["class:Shaman"]="Кристаллы резонита и дремлющий земной элементаль Гоггерок откликаются на изначальную магию земли — эхо древних созидателей камня этого мира.",["profession:Mining"]="Пещера активно разрабатывается кланом Камнепадов, кобольды которого неустанно роют туннели в поисках светящихся жил магического резонита."},sec={{t="Раскопки резонита",b="Кобольды Камнепадов глубоко вгрызлись в скалы Когтистых гор и превратили Пещеру Камнепадов в свой оплот. В отличие от обычных вредителей, которые ищут лишь укрытие, эти кобольды лихорадочно добывают резонит — редкий светящийся фиолетовый кристалл, рассыпанный по камню. Кристаллы пульсируют остатками магии земли, и существа впадают в оборонительное неистовство при виде любого чужака, приблизившегося к их раскопкам."},{t="Спящий великан",b="В глубине пещер безрассудные раскопки вскрыли древние тайны. В подземной породе покоится резонитовый ларец с Гоггероком, дремлющим земным элементалем древних времен. Неустанные раскопки кобольдов вокруг этой таинственной реликвии грозят пробудить существо, наделенное изначальной магией камня, и внезапно подвергнуть опасности все ущелье."}},faq={{q="Что здесь добывают кобольды?",a="Кобольды добывают резонит — редкий фиолетовый кристалл, вросший в каменные стены пещеры. Минерал тихо гудит от слабых следов магии земли, поэтому он ценен, и кобольды фанатично охраняют свои тайники.",al={"what is resonite","purple crystals stonetalon","why are kobolds mining","что такое резонит","фиолетовые кристаллы когтистые горы","зачем кобольды копают"}},{q="Кто такой Гоггерок?",a="Гоггерок — древний земной элементаль, спящий в резонитовом ларце глубоко в пещере. Раскопки кобольдов вокруг его ложа грозят нарушить его многовековой сон.",al={"goggeroc lore","earthen in boulderslide","sleeping giant in cave","предания о гоггероке","земельник в камнепадах","спящий великан в пещере"}},{q="Где находится Пещера Камнепадов?",a="Вход в пещеру находится в дальнем конце Ущелья Камнепадов, среди скалистых гор на юге Когтистых гор, к северо-востоку от тропы в Степи.",al={"boulderslide cavern location","how to find boulderslide cavern","where is the cave","где пещера камнепадов","как найти пещеру камнепадов","где пещера"}},{q="Почему Орда интересуется этой пещерой?",a="Орда следит за пещерой, чтобы сдержать агрессивное нашествие кобольдов, расползающихся по ущелью, и из интереса к магическим свойствам добываемых ими кристаллов резонита.",al={"horde quests boulderslide","why send me to boulderslide","задания орды камнепадов","почему меня отправили в камнепады"}}},fp="19,271,16.421.0,20.353.1,33.236.0,16.188.0,37.176.0,43.185.0"}
P.entries["subzone:boulderslide-ravine"] = {n="Ущелье Камнепадов",s="Ущелье Камнепадов — суровый уединенный каньон среди центральных пиков Когтистых гор, куда ведет Паучий тракт. Почти не затронутое прямыми столкновениями Орды и Альянса, оно служит скалистым подходом к Пещере Камнепадов и остается домом для диких горных зверей.",h="Ущелье Камнепадов — суровый уединенный каньон среди центральных пиков Когтистых гор, куда ведет Паучий тракт.",kw={"boulderslide cavern","boulderslide ravine","cliff stormer","rams","stonetalon","webwinder path","пещера камнепадов","ущелье камнепадов","горный буревестник","бараны","когтистые горы","паучий тракт"},ang={["profession:Mining"]="Крутые скальные стены ущелья — надежное место, где можно заметить жилы минералов, обнаженные смещением горной породы.",["race:Tauren"]="Поблекшие рисунки в небольшой боковой пещере несут отчетливый отпечаток племенных знаков тауренов, намекая на пути предков через высоты Когтистых гор."},sec={{t="Тихий горный перевал",b="Ущелье Камнепадов, скрытое в стороне от Паучьего тракта, — узкая расщелина в скалах Когтистых гор. Пока лесорубы, ночные эльфы и Орда сражаются за древесину и священные рощи по всему региону, этот скалистый перевал остается относительно нетронутым военными силами. Дикие горные бараны и бродячие скальные звери, например горные буревестники, составляют местную фауну и пробираются по опасным уступам и отвесным каменным стенам. Старатели тоже присматривают за ущельем: на скалистых склонах, ведущих глубже к сети пещер, нередко встречаются богатые жилы."},{t="Следы в камне",b="Напротив входа в Пещеру Камнепадов находится небольшая тихая пещера с видом на ущелье. Она освещена грубыми факелами и заставлена обветшалыми бочками с припасами, а на ее внутренних стенах сохранились примитивные племенные рисунки. Грубые изображения удивительно похожи на древние узоры тауренов, что говорит о том, что коренные племена бродили по этим скалам или искали здесь временное укрытие задолго до того, как в горы пришли нынешние конфликты."}},faq={{q="Где находится Ущелье Камнепадов?",a="Ущелье Камнепадов находится в Когтистых горах. Чтобы добраться до него, нужно идти по Паучьему тракту в более высокие скалы.",al={"boulderslide ravine location","how to get to boulderslide ravine","where is boulderslide ravine","где ущелье камнепадов","как добраться до ущелья камнепадов","расположение ущелья камнепадов"}},{q="Какие существа обитают в Ущелье Камнепадов?",a="Ущелье населяют в основном местные животные, особенно горные бараны и опасные скальные охотники, такие как горные буревестники.",al={"boulderslide ravine mobs","what is in boulderslide ravine","существа ущелья камнепадов","что в ущелье камнепадов"}},{q="Что это за заброшенная пещера напротив Пещеры Камнепадов?",a="Напротив входа в пещеру находится небольшая ниша, освещенная факелами и заставленная старыми бочками. На каменных стенах видны племенные пиктограммы, похожие на традиционное искусство тауренов, что указывает на то, что ее использовали местные странники или охотники.",al={"abandoned cave boulderslide","cave in boulderslide ravine","tauren cave stonetalon","заброшенная пещера камнепадов","пещера в ущелье камнепадов","пещера тауренов когтистые горы"}},{q="Чем важно Ущелье Камнепадов?",a="Оно служит естественным подходом к Пещере Камнепадов — подземному логову глубоко в горах — и предлагает путникам, проходящим мимо, ценные выходы минералов.",al={"what is boulderslide ravine for","boulderslide ravine purpose","для чего ущелье камнепадов","назначение ущелья камнепадов"}}},fp="19,306,21.567.0,19.442.0,37.130.0,43.128.0,59.222.0,39.172.0"}
P.entries["subzone:brackenwall-village"] = {n="Деревня Гиблотопь",s="Деревня Гиблотопь — главный оплот Орды в Пылевых топях, расположенный среди болот в северо-западном углу области. Основанная уцелевшими ограми Каменного Молота после того, как драконы разорили их прежнее поселение на юге, деревня служит непрочным оплотом, окруженным шпионами Альянса, дезертирами и черным драконьим родом.",h="Деревня Гиблотопь — главный оплот Орды в Пылевых топях, расположенный среди болот в северо-западном углу...",kw={"brackenwall","draz'zilb","dustwallow","infiltrators","mok'morokk","ogres","paval reethe","stonemaul","гиблотопь","драз'зилб","пылевые топи","лазутчики","мок'морокк","огры","павал рит","каменный молот"},ang={["faction:Alliance"]="Гиблотопь лежит глубоко на вражеской территории, но расследования, связанные с пропавшим дипломатом и мятежными дезертирами из Терамора, приведут отважных агентов прямо к границе лагеря огров.",["faction:Horde"]="Гиблотопь — ваше единственное убежище и пункт полетов в топях; ее защита позволяет Орде сохранить важный наблюдательный пост и оборонительный фланг против Терамора."},sec={{t="Убежище Каменного Молота",b="Когда черные драконы-полукровки изгнали огров Каменного Молота из их древнего дома в Деревне Каменного Молота на юге болот, их предводитель, Властитель Мок'Морокк — преемник Рексара, — повел уцелевших на север, в трясину, где они построили Деревню Гиблотопь. Поселение, возведенное вокруг традиционных земляных курганов, хижин и старой сторожевой башни, дало израненному клану защищенное убежище. Хотя деревня союзна Орде, ее разъедает внутренний упадок: Мок'Морокк бездействует, копит припасы и отказывается противостоять угрозе со стороны драконов, а духовное и тактическое руководство кланом осталось за такими фигурами, как огр-маг Драз'Зилб, и посланниками Орды."},{t="Глаза в трясине",b="Помимо внутреннего разлада, Гиблотопь страдает от внешних угроз. Лазутчики из Терамора постоянно таятся в зарослях, наблюдая за передвижениями в деревне и докладывая в островную крепость. Тем временем Павал Рит, дезертир из Терамора, изгнанный из Разрушенной башни, подозревается в краже важных припасов с заставы. Между настороженными взглядами с востока и черными драконами, рыщущими на юге, Гиблотопь служит изолированным плацдармом Орды, который удерживает на расстоянии и Альянс, и выводок Ониксии."}},faq={{q="Почему здесь есть огры, союзные Орде?",a="Это огры Каменного Молота, почетный клан, принятый в современную Орду защитником Рексаром при основании Дуротара. Рексар стал их вождем, победив прежнего предводителя, и привязал клан к новой коалиции вождя Тралла, а затем передал власть Мок'Морокку.",al={"why horde ogres","stonemaul clan lore","who are these ogres","почему огры в орде","история клана каменного молота","кто эти огры"}},{q="Почему Каменный Молот поселился здесь, а не остался в старом доме?",a="Их родовое поселение на юге Пылевых топей было захвачено и уничтожено черным драконьим родом. Властитель Мок'Морокк повел уцелевших изгнанников на север, в болото, чтобы основать укрепленное убежище — Гиблотопь.",al={"what happened to stonemaul village","why brackenwall","ogre refugees","что случилось с деревней каменного молота","почему гиблотопь","огры беженцы"}},{q="Кто управляет Деревней Гиблотопь?",a="Деревней правит Властитель Мок'Морокк, однако его правление вызывает всеобщее недовольство. Вместо того чтобы сплотить свой народ, чтобы вернуть родные земли или сразиться с драконами, он трусливо прячется в деревне, а огр-маг Драз'Зилб и посланники Орды вынуждены справляться с повседневными кризисами.",al={"brackenwall leader","who runs brackenwall","mok'morokk","предводитель гиблотопи","кто правит гиблотопью","мок'морокк"}},{q="Почему за деревней следят шпионы из Терамора?",a="Несмотря на хрупкое перемирие между Тераморой и Оргриммаром, войска леди Джайны Праудмур внимательно следят за любыми передвижениями войск Орды в Пылевых топях. Лазутчики обходят границы Гиблотопи и докладывают о силе огров и действиях Орды.",al={"alliance spies dustwallow","theramore infiltrators","why is theramore watching","шпионы альянса пылевые топи","лазутчики терамора","почему терамор следит"}}},fp="19,343,23.633.0,15.527.1,47.294.0,71.229.0,40.263.0,50.262.0"}
P.entries["subzone:brackwell-pumpkin-patch"] = {n="Тыквенное поле Бреквеллов",s="Тыквенное поле Бреквеллов — захваченная ферма на юго-востоке Элвиннского леса. Когда-то здесь жила семья Бреквеллов, но поля и дом полностью заняло Братство Справедливости, устроив там укрытие. Это место встреч разбойников-заговорщиков и перевалочный пункт для контрабанды краденого золота.",h="Тыквенное поле Бреквеллов — захваченная ферма на юго-востоке Элвиннского леса.",kw={"brackwell","defias","elwynn","erlan drudgemoor","morgan the collector","princess","pumpkin patch","surena caledon","бреквелл","братство справедливости","элвиннский лес","эрлан драджмур","морган вымогатель","принцесса","тыквенное поле","сурена каледон"},ang={["class:Warlock"]="В хижине на ферме скрывается беглая ученица Сурена Каледон, чье украденное кровавое ожерелье необходимо для призыва демона бездны.",["faction:Alliance"]="Захваченное поле — одна из самых восточных действующих баз Братства Справедливости в Элвиннском лесу, прямая угроза соседним фермам и торговым путям."},sec={{t="Приют бандитов",b="Ферма Бреквеллов расположена к юго-востоку от Фермы Стоунфилдов и когда-то была плодородным участком элвиннских земель. Теперь законные владельцы бесследно исчезли: их изгнали или того хуже — по воле растущей волны преступности. В их отсутствие Братство Справедливости заняло крепкий дом и заросшие поля фермы. Это место служит убежищем и пунктом передачи, где разбойники собираются вдали от бдительных патрулей Златоземья. Видные заговорщики, например Морган Вымогатель, используют уединенное поле, чтобы получать партии незаконно добытого золота, украденного из рудников леса."},{t="Свиньи и темная магия",b="Братство Справедливости — не единственные нарушители спокойствия среди тыквенных плетей. Бреквеллы оставили огромную призовую свиноматку по кличке Принцесса, которая бродит по полю и постоянно терроризирует соседние угодья. Тем временем чердак фермерского дома и постройки скрывают опасные личные связи: бандит Эрлан Драджмур соблазнил Сурену Каледон, беглую ученицу чернокнижника, которая сбежала от своего наставника в Штормграде с украденным кровавым артефактом, и тем самым навлекла на укрытие внимание темных практиков."}},faq={{q="Что случилось с семьей Бреквеллов?",a="Их точная судьба неизвестна. Когда Братство Справедливости расширило свое присутствие на юго-востоке Элвиннского леса, Бреквеллам пришлось либо бежать, либо они были убиты, и тыквенные поля с фермерским домом достались бандитам.",al={"where are the brackwells","who lived at brackwell farm","brackwell family fate","где бреквеллы","кто жил на ферме бреквеллов","судьба семьи бреквеллов"}},{q="Почему Братство Справедливости использует эту ферму?",a="Ферма — укромная база близ границ леса. Она позволяет братству хранить награбленное и координировать контрабанду, например получать партии краденого золота из рудников через посыльных вроде Моргана Вымогателя, вдали от Стражи Штормграда.",al={"why are defias here","what are bandits doing at the pumpkin patch","defias at brackwell","почему здесь братство справедливости","что бандиты делают на тыквенном поле","братство справедливости у бреквеллов"}},{q="Кто такая Принцесса?",a="Принцесса — огромная призовая свинья, которую изначально выращивали Бреквеллы. Брошенная после падения фермы, она стала еще больше, регулярно вторгаясь на соседнюю Ферму Стоунфилдов и пожирая их лучший урожай.",al={"giant pig","princess pig","why is there a huge boar here","гигантская свинья","свинья принцесса","почему здесь огромный кабан"}},{q="Почему чернокнижники приходят на тыквенное поле?",a="Сурена Каледон, ученица штормградского учителя чернокнижников Гакина Темнопряда, украла мощное кровавое ожерелье и бежала на ферму, чтобы спрятаться вместе с возлюбленным — бандитом Братства Справедливости Эрланом Драджмуром. Гакин посылает сюда начинающих чернокнижников, чтобы они убили ее и вернули реликвию.",al={"warlock quest brackwell","surena caledon","gakin voidwalker quest","задание чернокнижника бреквелл","сурена каледон","задание гакина демон бездны"}}},fp="23,317,14.602.0,19.504.1,38.236.0,46.283.0,16.221.0,42.276.0"}
P.entries["subzone:brambleblade-ravine"] = {n="Ежевичная лощина",s="Ежевичная лощина — суровый каньон, врезающийся в северо-восточный край плато Красного Облака. Это укрепленное логово племени свинобразов Дыбогривов, которые постоянно нападают на соседний поселок тауренов — Лагерь Нараче. Сюда посылают молодых тауренов-воинов, чтобы они доказали свою силу и защитили родные земли от свирепых захватчиков.",h="Ежевичная лощина — суровый каньон, врезающийся в северо-восточный край плато Красного Облака.",kw={"brambleblade","bristleback","camp narache","mulgore","quilboar","ravine","red cloud mesa","thornmantle","ежевичная лощина","дыбогривы","лагерь нараче","мулгор","свинобразы","лощина","плато красного облака","терновая мантия"},ang={["faction:Horde"]="Уничтожение агрессивных Дыбогривов в Ежевичной лощине помогает укрепить ранние позиции Орды в Мулгоре.",["race:Tauren"]="Для молодых тауренов, взрослеющих в Лагере Нараче, удар по Ежевичной лощине — одно из первых испытаний боевой и духовной стойкости ради защиты племени."},sec={{t="Заноза в боку плато",b="Ежевичная лощина, врезанная в выжженную солнцем землю плато Красного Облака, заросла густым колючим терновником и усеяна лагерями свинобразов. Племя Дыбогривов использует эту природную крепость как плацдарм для набегов на Лагерь Нараче, угрожая безопасности молодых тауренов, вступающих во взрослую жизнь. Шаманы и воины Дыбогривов во главе с вождем Острым Бивнем Терновой Мантией живут в глубине лощины среди обученных боевых вепрей. Для Шу'хало удар в сердце каньона — важный обряд посвящения и суровая необходимость ради безопасности равнин."}},faq={{q="Что такое Ежевичная лощина?",a="Ежевичная лощина — каньон на северо-восточном краю плато Красного Облака в Мулгоре. Ее густо населяют свинобразы Дыбогривы, и это их местный оплот.",al={"brambleblade ravine","what is brambleblade ravine","brambleblade mulgore","ежевичная лощина","что такое ежевичная лощина","ежевичная лощина мулгор"}},{q="Почему свинобразы Дыбогривы нападают отсюда?",a="Дыбогривы крайне ревностно охраняют свои владения и считают присутствие тауренов посягательством на земли, которые они считают своими. Из Ежевичной лощины они часто совершают набеги на соседний Лагерь Нараче.",al={"why quilboar attacking","bristleback motives","quilboar camp narache","почему нападают свинобразы","мотивы дыбогривов","свинобразы лагерь нараче"}},{q="Кто возглавляет свинобразов в Ежевичной лощине?",a="Здешних свинобразов возглавляет вождь Острый Бивень Терновая Мантия — грозный предводитель, живущий в большой хижине в глубине лощины.",al={"brambleblade leader","quilboar boss mulgore","chief sharptusk thornmantle","предводитель ежевичной лощины","босс свинобразов мулгор","вождь острый бивень терновая мантия"}},{q="Почему молодые таурены идут в лощину?",a="Старейшины и вожди тауренов Лагеря Нараче поручают неопытным воинам войти в лощину, чтобы отразить угрозу Дыбогривов, сократить их численность и сразить их предводителей ради безопасности плато.",al={"tauren quests brambleblade","why go to brambleblade","camp narache quests","задания тауренов ежевичная лощина","зачем идти в ежевичную лощину","задания лагеря нараче"}}},fp="19,341,26.544.0,28.181.0,53.214.0,46.147.0,41.199.0"}
P.entries["subzone:bramblescar"] = {n="Ежевичный овраг",s="Ежевичный овраг — сильно укрепленное поселение свинобразов Иглогривых на юге Степей. Густой колючий терновник защищает лагерь, а его обитатели ведут жестокую войну с соперниками Дыбогривами через Золотой Путь.",h="Ежевичный овраг — сильно укрепленное поселение свинобразов Иглогривых на юге Степей.",kw={"agama'gor","barrens","bramblescar","bristleback","gold road","quilboar","razormane","агама'гор","степи","ежевичный овраг","дыбогривы","золотой путь","свинобразы","иглогривые"},ang={["faction:Horde"]="Защита Золотого Пути от набегов свинобразов из Ежевичного оврага крайне важна для безопасного сообщения между Перекрестком, Лагерем Таурахо и южной границей."},sec={{t="Колючий оплот",b="Ежевичный овраг, вырезанный в зазубренных гигантских зарослях юга Степей, служит важным оплотом свинобразов Иглогривых. Оборонительные заросли достаточно густы и остры, чтобы отпугнуть случайных путников, но свинобразы внутри далеко не мирны. Они крайне ревностно охраняют свои земли, враждебны к чужакам и постоянно вступают в стычки со всеми, кто приблизится к их границам, считая всех, кроме свинобразов, захватчиками земли, благословленной их древними кабаньими богами."},{t="Племенная кровная вражда",b="Ежевичный овраг в вечном напряжении лежит прямо напротив Агама'гора через Золотой Путь — лагеря соперничающего племени Дыбогривов. Две стороны ведут беспощадную племенную войну за господство над югом Степей. Отбиваясь от путников Орды на дороге и отражая набеги Дыбогривов, воины Иглогривых из Ежевичного оврага всегда настороже и готовы к насилию."}},faq={{q="Кто живет в Ежевичном овраге?",a="Ежевичный овраг населяет племя свинобразов Иглогривых, которые защищают свой заросший терновником лагерь как от соперников-свинобразов, так и от любых проезжих путников.",al={"who is here","bramblescar mobs","bramblescar quilboar","кто здесь","враги ежевичного оврага","свинобразы ежевичного оврага"}},{q="Почему здешние свинобразы сражаются друг с другом?",a="Иглогривые из Ежевичного оврага и свинобразы Дыбогривы по ту сторону дороги в Агама'горе — заклятые враги, ведущие жестокую территориальную кровную вражду за контроль над югом Степей.",al={"why are they at war","razormane vs bristleback","quilboar war","почему они воюют","иглогривые против дыбогривов","война свинобразов"}},{q="Где находится Ежевичный овраг?",a="Ежевичный овраг лежит на южных равнинах Степей, сразу к востоку от главного Золотого Пути, напротив Агама'гора.",al={"bramblescar location","where is bramblescar","how to find bramblescar","где ежевичный овраг","как найти ежевичный овраг","расположение ежевичного оврага"}},{q="Враждебны ли здешние свинобразы к Орде?",a="Да. Свинобразы Иглогривые считают Орду захватчиками, вторгшимися на их священные племенные земли, и нападут на любого путника, который подойдет близко.",al={"is bramblescar friendly","horde reputation bramblescar","дружелюбен ли ежевичный овраг","репутация орды ежевичный овраг"}}},fp="11,238,17.466.0,17.402.0,25.164.0,46.184.0,29.121.0,43.157.0"}
P.entries["subzone:brewnall-village"] = {n="Поселок Пивоваров",s="Поселок Пивоваров — небольшое поселение дворфов в Долине Промозглого Ветра близ входа в Гномреган. Основанный семьей Ячменовар, этот форпост служит испытательной площадкой для смелых пивоваренных опытов и местной обороны от диких зверей. Несмотря на название, он в основном представляет собой простой лагерь в заснеженных гномьих низинах Дун Морога.",h="Поселок Пивоваров — небольшое поселение дворфов в Долине Промозглого Ветра близ входа в Гномреган.",kw={"barleybrew","beer","brewnall","chill breeze valley","dun morogh","gnomeregan","stout","ячменовар","пиво","поселок пивоваров","долина промозглого ветра","дун морог","гномреган","стаут"},ang={["race:Dwarf"]="Для дворфов поиск Ячменоварами идеального рецепта — почетное дело, поддерживающее одну из лучших традиций Стальгорна.",["race:Gnome"]="Расположенный близ Гномрегана, поселок — неожиданный форпост дворфов в глубине гномьих долин западного Дун Морога."},sec={{t="Горькое пиво в долине",b="Поселок Пивоваров, укрывшийся в сугробах Долины Промозглого Ветра, лежит в самом сердце традиционных гномьих земель западного Дун Морога. Здесь живет клан Ячменовар — стойкие дворфы-пивовары, стремящиеся довести до совершенства старинные рецепты и сварить идеальный стаут. Хотя это место зовется поселком, оно состоит в основном из палаток и пивоваренного оборудования под открытым небом, а не из постоянных каменных построек. Между испытаниями опытных партий эля и защитой от свирепых местных волков и медведей Ячменовары сильно полагаются на странствующих горцев, которые добывают редкие ингредиенты и охраняют долину."}},faq={{q="Что такое Поселок Пивоваров?",a="Поселок Пивоваров — небольшой лагерь дворфов в Долине Промозглого Ветра в западном Дун Мороге, к востоку от Гномрегана. Это форпост, где клан Ячменовар экспериментирует с новыми рецептами пива и справляется с угрозой местных зверей.",al={"where is brewnall","what is brewnall village","brewnall info","где поселок пивоваров","что такое поселок пивоваров","поселок пивоваров информация"}},{q="Почему это поселок, если здесь нет домов?",a="Несмотря на название, это по сути лагерь под открытым небом из палаток и бочек с припасами. Ячменовары устроили здесь свое пивоварение на холоде, не строя настоящих каменных домов.",al={"why is it a camp","where are the houses","brewnall buildings","почему это лагерь","где дома","постройки поселка пивоваров"}},{q="Почему поселение дворфов находится на гномьей территории?",a="Хотя западная часть Дун Морога окружает Гномреган и населена в основном гномами, тесный союз Стальгорна и гномов делает совместные поселения обычным делом. Ячменовары обосновались здесь, в Долине Промозглого Ветра, чтобы заниматься своим ремеслом без помех.",al={"dwarves near gnomeregan","why are dwarves here","gnome territory dwarf camp","дворфы возле гномрегана","почему здесь дворфы","лагерь дворфов на гномьей земле"}},{q="С какими проблемами сталкиваются жители?",a="Лагерь часто подвергается нападениям агрессивных зверей долины, особенно скальных вепрей, медведей и ледяных волков. Кроме того, Ячменовары постоянно ищут редкие и экзотические ингредиенты, чтобы изобрести новые, лучшие сорта пива.",al={"brewnall quests","what do the barleybrews need","village problems","задания поселка пивоваров","что нужно ячменоварам","проблемы поселка"}}},fp="16,380,27.637.0,25.243.0,53.234.0,57.266.0,36.244.0"}
P.entries["subzone:brightwood-grove"] = {n="Светлая роща",s="Светлая роща — затененный лесной массив к западу от Темнолесья в Сумеречном лесу. Когда-то она была частью мирного сельского пейзажа региона, а теперь кишит свирепыми воргенами Ночной Погибели, которые устраивают стоянки среди разрушенных усадеб и нападают на любого путника, подошедшего слишком близко.",h="Светлая роща — затененный лесной массив к западу от Темнолесья в Сумеречном лесу.",kw={"brightwood grove","darkshire","duskwood","night watch","nightbane","wolf men","worgen","светлая роща","темнолесье","сумеречный лес","ночной дозор","ночная погибель","волколюди","воргены"},ang={["class:Hunter"]="Темные заросли рощи — суровая местность для выслеживания свирепых воргенов Ночной Погибели: здесь бдительность любого охотника проверяется засадами, подстерегающими за кромкой деревьев.",["faction:Alliance"]="Светлая роща находится прямо у ворот Темнолесья, поэтому уничтожение ее стай воргенов жизненно важно, чтобы осажденный город не оказался отрезан от запада."},sec={{t="Роща во мраке",b="Светлая роща, расположенная в виду границ Темнолесья, олицетворяет подкрадывающуюся опасность, угрожающую окраинам города. Усадьбы и изгороди, прежде обозначавшие границы мирных полей, лежат обрушенные и гнилые. На их месте воргены Ночной Погибели, бродящие по заросшим полянам, построили грубые лагеря. Близость этих волкоподобных тварей постоянно угрожает городу, и Ночному Дозору и проходящим мимо искателям приключений приходится непрерывно сокращать их число, пока поселение не было захвачено."}},faq={{q="Где находится Светлая роща?",a="Светлая роща находится в восточной части Сумеречного леса, к западу от города Темнолесье, вдоль главных троп.",al={"brightwood grove location","where is brightwood grove","brightwood duskwood","светлая роща где находится","где светлая роща","светлая роща сумеречный лес"}},{q="Какие существа обитают в Светлой роще?",a="Рощу наводнили свирепые воргены Ночной Погибели. Эти проклятые волколюди устроили грубые лагеря среди разрушенных построек и нападают на любого, кто приближается.",al={"monsters in brightwood grove","brightwood enemies","what lives in brightwood","монстры светлой рощи","враги светлой рощи","кто живет в светлой роще"}},{q="Почему роща опасна для Темнолесья?",a="Поскольку Светлая роща лежит сразу к западу от Темнолесья, агрессивные стаи воргенов, затаившиеся в зарослях, представляют непосредственную угрозу для городских патрулей, линий снабжения и любых путников, идущих по дороге.",al={"why is brightwood grove dangerous","darkshire brightwood threat","почему светлая роща опасна","угроза темнолесью из светлой рощи"}},{q="Есть ли в роще дружественные поселения?",a="Нет. Немногие каменные здания и фермы на окраинах рощи полностью лежат в руинах, брошенные на милость стихий и занятые бродячими воргенами.",al={"is anyone friendly in brightwood","brightwood town","есть ли в светлой роще друзья","город в светлой роще"}}},fp="16,279,17.516.0,26.111.0,40.174.0,40.207.0,48.152.0"}
P.entries["subzone:brill"] = {n="Брилл",s="Брилл — главное поселение Отрекшихся в сердце Тирисфальских лесов, расположенное к северу от Руин Лордерона. Когда-то это был процветающий человеческий город, а теперь он служит административным и военным центром для недавно пробудившейся нежити, выходящей за пределы Могильника.",h="Брилл — главное поселение Отрекшихся в сердце Тирисфальских лесов, расположенное к северу от Руин Лордерона.",kw={"brill","forsaken","gallows end","lordaeron","magistrate sevren","tirisfal glades","zeppelin","брилл","отрекшиеся","петля висельника","лордерон","мировой судья севрен","тирисфальские леса","дирижабль"},ang={["faction:Horde"]="Дирижабельная пристань за городом — главная связь северной Орды между Лордероном и союзными оплотами в Калимдоре и Восточных королевствах.",["race:Undead"]="Для Отрекшихся, выходящих из Могильника, Брилл — первый взгляд на цивилизацию и место, где можно начать доказывать верность Темной Госпоже."},sec={{t="От чумной земли до оплота",b="До Третьей войны Брилл был оживленной деревней под властью местной знати, например семей Баровых и Агамондов. Процветание закончилось, когда Кел'Тузад выбрал эту местность для первых опытов Культа Проклятых с Чумой нежизни. Разрушительная зараза прошла по населению так быстро, что местное ополчение было изгнано, а на месте остались огромные братские могилы.\n\nТеперь город отстроен Отрекшимися под руководством Мирового судьи Севрена и сохраняет обветшалую лордеронскую архитектуру под покровом мрачной целеустремленности. Брилл служит региональным командным центром и координирует оборону от вторжений Алого ордена, бродячих остатков Плети и местных зверей, искаженных некромантическим распадом."},{t="Перекресток северного Лордерона",b="Помимо местной обороны, Брилл — важный перекресток, связывающий Тирисфальские леса с остальной Ордой. Наверху гоблинская дирижаблная башня обеспечивает перелеты на юг, в Дуротар и в глубь Тернистой долины. В самом поселении Таверна «Петля висельника» служит не только мрачным приютом для путников, но и временной лабораторией, где пленных фанатиков Алого ордена допрашивают и подвергают испытаниям аптекарей."}},faq={{q="Кто правит Бриллом?",a="Мировой судья Севрен руководит гражданским управлением и местной обороной Брилла от имени леди Сильваны Ветрокрылой и Отрекшихся.",al={"brill leader","who is in charge of brill","magistrate of brill","глава брилла","кто управляет бриллом","судья брилла"}},{q="Почему за Бриллом такое огромное кладбище?",a="Кел'Тузад провел в Брилле одни из своих первых опытов на живых с Чумой нежизни. Зараза с ужасающей скоростью истребила местных людей, и потребовалось огромное кладбище, чтобы похоронить жертв до того, как они восстанут в рядах Плети.",al={"brill graveyard","cemetery near brill","why so many graves","кладбище брилла","кладбище рядом с бриллом","почему так много могил"}},{q="Для чего используется Таверна «Петля висельника»?",a="Помимо ночлега для усталых путников, подвал таверны служит базой для аптекарей, проводящих химические и токсикологические опыты над пленными фанатиками Алого ордена.",al={"gallows end","brill inn","what is happening in the brill tavern","петля висельника","таверна брилла","что происходит в таверне брилла"}},{q="Куда летают дирижабли с башни у Брилла?",a="Дирижабельная башня, которой управляют гоблинские экипажи, напрямую соединяет Лордерон с Калимдором у Оргриммара, а также с Лагерем Гром'гол в Тернистой долине на юге.",al={"brill zeppelin destinations","where do blimps go brill","brill flight paths","направления дирижаблей брилла","куда летают дирижабли из брилла","маршруты полета брилла"}}},fp="5,273,29.744.0,32.429.0,16.135.0,52.252.0,37.176.0,54.164.0"}
P.entries["subzone:brill-town-hall"] = {n="Ратуша Брилла",s="Ратуша Брилла — административное сердце поселения Брилл в центре Тирисфальских лесов. Как самое заметное здание города, она служит гражданской штаб-квартирой, из которой Отрекшиеся управляют своими местными владениями и координируют оборону лесов.",h="Ратуша Брилла — административное сердце поселения Брилл в центре Тирисфальских лесов.",kw={"brill","forsaken","lordaeron","magistrate sevren","sevren","tirisfal glades","town hall","брилл","отрекшиеся","лордерон","мировой судья севрен","севрен","тирисфальские леса","ратуша"},ang={["faction:Horde"]="Союзники Орды, прибывшие в Тирисфаль, могут посетить ратушу, чтобы понять, как Отрекшиеся поддерживают гражданскую власть и воинский порядок в своих мрачных землях.",["race:Undead"]="Для Отрекшихся, выходящих из Могильника, ратуша — первое знакомство со структурированным гражданским управлением во владениях королевы Сильваны, где местная оборона и усилия по возвращению земель организуются официально."},sec={{t="Гражданская резиденция Отрекшихся",b="Хотя большая часть Лордерона лежит в руинах, Ратуша Брилла остается действующим гражданским центром под властью нежити. Внутри Мировой судья Севрен руководит делами города со своей трибуны и раздает Отрекшимся искателям приключений важные поручения и указания. Помимо Логова Осквернителя на Нагорье Арати, это один из немногих известных в мире городских советов, которыми действительно управляют Отрекшиеся; он служит мрачной пародией и в то же время действующим продолжением муниципальной бюрократии старого Лордерона."}},faq={{q="Для чего нужна Ратуша Брилла?",a="Она служит местным органом власти поселения Брилл. Руководство Отрекшихся, в частности Мировой судья Севрен, использует здание для координации местной обороны, издания указов и распределения важных заданий среди путников и недавно пробудившейся нежити.",al={"brill town hall purpose","what is this building","why visit brill town hall","назначение ратуши брилла","что это за здание","зачем посещать ратушу брилла"}},{q="Кто здесь главный?",a="Мировой судья Севрен руководит ратушей со своей трибуны, ведая городскими делами от имени Отрекшихся и направляя действия в центральных Тирисфальских лесах.",al={"who runs brill town hall","brill town hall leader","who is the magistrate","кто управляет ратушей брилла","глава ратуши брилла","кто мировой судья"}},{q="Чем эта ратуша примечательна по сравнению с другими?",a="Ратуши обычно — наследие живых человеческих королевств. Ратуша Брилла примечательна тем, что это один из немногих действующих городских советов, которые содержат Отрекшиеся и которыми они управляют; ей подобно лишь такое место, как Логово Осквернителя в Арати.",al={"unique forsaken town hall","are there other forsaken town halls","уникальная ратуша отрекшихся","есть ли другие ратуши отрекшихся"}}},fp="15,278,26.509.0,37.251.0,22.176.0,49.226.0"}
P.entries["subzone:broken-hall"] = {n="Разрушенный зал",s="Разрушенный зал — затопленный внешний порог погруженного Храма Атал'Хаккара в Болоте Печали. Он был разрушен, когда великая аспект драконов Изера и ее стая утащили огромный зиккурат под воду, и теперь эти руины пусты: фанатики Атал'ай отступили в глубинные святилища.",h="Разрушенный зал — затопленный внешний порог погруженного Храма Атал'Хаккара в Болоте Печали.",kw={"atal'ai","broken hall","hall of masks","pool of tears","sunken temple","swamp of sorrows","temple of atal'hakkar","атал'ай","разрушенный зал","зал масок","озеро слез","затонувший храм","болото печали","храм атал'хаккара"},ang={["race:Troll"]="Для троллей, почитающих лоа, Разрушенный зал — мрачное напоминание о гибели фанатиков Атал'ай, которые пошли против своих соплеменников, чтобы служить Хаккару Свежевателю Душ."},sec={{t="Затопленный порог",b="Когда зеленые драконы обрушили свой гнев на жречество Атал'ай и погрузили их нечестивый зиккурат под Озеро Слез, сильнее всего пострадали внешние постройки. Пол Разрушенного зала полностью обрушился, и мутная болотная вода затопила помещение. Из-за разрушений и затопления тролли-культисты покинули этот входной зал и отошли вглубь комплекса. Искатели приключений, входящие в затонувший храм, должны пройти по этим пропитанным водой руинам, а затем подняться по лестнице к Залу Масок."}},faq={{q="Что такое Разрушенный зал?",a="Это самое внешнее входное помещение Храма Атал'Хаккара, расположенное сразу за затопленным подводным входом под Озером Слез.",al={"broken hall overview","what is this place","temple entrance hall","обзор разрушенного зала","что это за место","входной зал храма"}},{q="Почему Разрушенный зал затоплен и разрушен?",a="Зал был разрушен, когда зеленый драконий род утащил весь храм под воды болота, чтобы остановить призыв Бога крови Хаккара: пол обрушился, а зал оказался затоплен.",al={"why broken hall wet","why is broken hall submerged","who broke the hall","почему разрушенный зал мокрый","почему разрушенный зал затоплен","кто разрушил зал"}},{q="Живут ли в этом зале тролли Атал'ай?",a="Сам Разрушенный зал в основном заброшен. После затопления верхней части храма культисты Атал'ай отошли в более сухие и защищенные помещения в глубине комплекса.",al={"enemies in broken hall","is broken hall empty","враги в разрушенном зале","пуст ли разрушенный зал"}},{q="Куда ведет лестница в Разрушенном зале?",a="Подъем по каменной лестнице из затопленного Разрушенного зала приводит исследователей прямо в Зал Масок.",al={"broken hall stairs","broken hall exit","where to go from broken hall","лестница разрушенного зала","выход из разрушенного зала","куда идти из разрушенного зала"}}},fp="11,304,17.555.0,24.141.0,42.193.0,49.184.0,44.115.0"}
P.entries["subzone:broken-pillar"] = {n="Разбитая Колонна",s="Разбитая Колонна — группа обветшалых древних руин троллей, торчащих из дюн к югу от Прибамбасска. Это уединенный исследовательский пост гоблина-старателя и ученого Марвона Клепальщика, который изучает загадочные артефакты, погребенные под окрестными песками.",h="Разбитая Колонна — группа обветшалых древних руин троллей, торчащих из дюн к югу от Прибамбасска.",kw={"broken pillar","gadgetzan","gahz'ridian","marvon rivetseeker","ratchet","tanaris","troll ruins","разбитая колонна","прибамбасск","газ'ридианцы","марвон клепальщик","кабестан","танарис","руины троллей"},ang={["race:Gnome"]="Любопытство, движущее исследованиями Марвона Клепальщика в области неизвестных свойств реликвий, сродни стремлению гномов к науке, хотя методы его остаются сугубо гоблинскими.",["race:Troll"]="Рассыпающиеся колонны — торжественные памятники древней архитектуры троллей, напоминание об эпохе, когда власть империи над югом Калимдора еще не была разрушена временем и песком."},sec={{t="Выбеленный солнцем камень",b="Разбитая Колонна возвышается над песками к югу от Прибамбасска и к востоку от коварных Безбрежных Песков. Это остатки древней архитектуры троллей, давно поглощенные Танарисом. Несмотря на безлюдную местность и пустынных зверей, это место хранит редкие свидетельства о доисторических цивилизациях континента. Марвон Клепальщик, гоблин-исследователь родом из Кабестана, разбил одинокий лагерь у разрушенной каменной кладки, чтобы изучать любопытные реликвии газ'ридианцев, разбросанные по пустоши."}},faq={{q="Что такое Разбитая Колонна?",a="Разбитая Колонна — древние руины троллей в центральной части Танариса, к югу от Прибамбасска и к востоку от Безбрежных Песков. От первоначального сооружения осталось немного: обветшалые каменные колонны и обломки, наполовину погребенные в зыбучих дюнах.",al={"broken pillar tanaris","what is broken pillar","pillar ruins","разбитая колонна танарис","что такое разбитая колонна","руины колонны"}},{q="Кто разбил лагерь у Разбитой Колонны?",a="Марвон Клепальщик, любознательный гоблин-ученый и старатель из Кабестана, устроил среди руин одинокий исследовательский лагерь. Он изучает загадочные газ'ридианские украшения, погребенные по всей окрестной пустыне.",al={"who is at broken pillar","broken pillar npc","marvon rivetseeker location","кто у разбитой колонны","разбитая колонна персонажи","где марвон клепальщик"}},{q="Кто построил эти древние руины?",a="Каменная кладка выполнена в стиле древних троллей и относится к эпохам, когда империи троллей властвовали над югом Калимдора задолго до того, как пески пустыни поглотили эту область.",al={"who built broken pillar","broken pillar history","broken pillar origin","кто построил разбитую колонну","история разбитой колонны","происхождение разбитой колонны"}},{q="Что такое газ'ридианские реликвии?",a="Газ'ридианские реликвии — древние каменные артефакты и резные лики, погребенные в песках Танариса. Марвон Клепальщик изучает их из своего лагеря у Разбитой Колонны, стремясь раскрыть тайны и силу, заключенные в мастерстве исчезнувшей империи.",al={"gahzridian","what is gahzridian","marvon quest items","газ'ридианские реликвии","что такое газ'ридианцы","предметы марвона"}}},fp="13,279,18.526.0,26.242.0,35.228.0,34.177.0,28.228.0"}
P.entries["subzone:bronzebeard-encampment"] = {n="Лагерь Бронзоборода",s="Лагерь Бронзоборода — суровый дворфийский форпост на юге Силитуса, к востоку от громадной Стены Скарабея. В лагере работают выносливые исследователи и ученые из Лиги исследователей, и он служит опорной базой для изучения древних символов силитидов и тайн, скрытых под песками пустыни.",h="Лагерь Бронзоборода — суровый дворфийский форпост на юге Силитуса, к востоку от громадной Стены Скарабея.",kw={"bronzebeard encampment","deathclasp","explorers league","frankal stonebridge","glibb","rutgar glyphshaper","scarab wall","silithus","лагерь бронзоборода","смертоклещ","лига исследователей","франкал каменный мост","глибб","рутгар знакописец","стена скарабея","силитус"},ang={["faction:Alliance"]="Для путников Альянса, пересекающих мрачные просторы Силитуса, этот удаленный лагерь — желанный дружественный форпост далеко к югу от Крепости Кенария.",["race:Dwarf"]="Форпост показывает непреклонную стойкость Лиги исследователей и доказывает, что нет столь враждебной пустыни, которая остановила бы дворфов Стальгорна, ищущих историческую истину."},sec={{t="Опора среди зыбучих песков",b="Лагерь Бронзоборода, расположенный у безлюдных южных обрывов Силитуса, — редкое прибежище дворфийской стойкости во враждебной пустоши. Он основан под эгидой археологических изысканий Стальгорна и находится в виду высящейся Стены Скарабея. Здесь исследователи, такие как Рутгар Знакописец и Франкал Каменный Мост, терпели палящий зной, скорпидов и наступающие рои силитидов, чтобы изучать причудливые надписи и памятники, оставленные забытыми цивилизациями."},{t="Символы и отчаяние",b="Жизнь в лагере совсем не похожа на тихие раскопки. Угроза силитидов расползается из подземных ульев по пустошам, а опасные чудовища, вроде громадного скорпида Смертоклеща, бродят по ближним пескам, и форпосту приходится сочетать строгую науку с борьбой за выживание. Исследователи во многом полагаются на приходящих искателей приключений: те снимают копии малопонятных символов, расшифровывают древние языки насекомых и ищут пропавших товарищей, зашедших слишком глубоко в безумие пустыни."}},faq={{q="Где находится Лагерь Бронзоборода?",a="Лагерь находится на юге Силитуса, к востоку от огромной Стены Скарабея и к северу от южной горной гряды.",al={"where is bronzebeard encampment","bronzebeard camp location","how to find bronzebeard encampment","где лагерь бронзоборода","расположение лагеря бронзоборода","как найти лагерь бронзоборода"}},{q="Кто управляет Лагерем Бронзоборода?",a="В лагере работают члены и сотрудники дворфийской Лиги исследователей, в том числе исследователь символов Рутгар Знакописец, Франкал Каменный Мост и их спутник Глибб.",al={"who is at bronzebeard encampment","bronzebeard camp npcs","who leads bronzebeard camp","кто в лагере бронзоборода","персонажи лагеря бронзоборода","кто руководит лагерем бронзоборода"}},{q="Что изучают здесь дворфы?",a="Исследователи посвятили себя расшифровке древних каменных символов, изучению системы общения силитидов и раскрытию давно погребенных тайн юга Калимдора.",al={"why are dwarves in silithus","what is rutgar studying","purpose of bronzebeard encampment","зачем дворфы в силитусе","что изучает рутгар","цель лагеря бронзоборода"}},{q="Какие угрозы таятся рядом с лагерем?",a="Окрестную пустыню населяют агрессивные силитиды, песчаные скорпионы и печально известный гигантский скорпид Смертоклещ, Ужас Песков, чье гнездо находится неподалеку к юго-востоку.",al={"dangers near bronzebeard camp","deathclasp location","bronzebeard camp monsters","опасности возле лагеря бронзоборода","где смертоклещ","монстры лагеря бронзоборода"}}},fp="22,331,32.498.0,22.486.0,44.131.0,36.178.0,35.176.0,38.187.0"}
P.entries["subzone:browman-mill"] = {n="Мельница Бровача",s="Мельница Бровача — оскверненная лесопилка к северу от Часовни Последней Надежды в Восточных Чумных землях. Некогда она была важной частью лесной торговли Лордерона, а теперь кишит нежитью под железной пятой Плети. Ее прежний хозяин, Стивен Бровач, остался в смерти пленником своей разрушенной мастерской.",h="Мельница Бровача — оскверненная лесопилка к северу от Часовни Последней Надежды в Восточных Чумных землях.",kw={"abominations","banshees","browman mill","eastern plaguelands","light's hope chapel","lumber mill","scourge","stephen browman","поганища","банши","мельница бровача","восточные чумные земли","часовня последней надежды","лесопилка","плеть","стивен бровач"},ang={["class:Paladin"]="Оскверненные останки мельницы и измученные души, населяющие ее земли, воплощают все то, что священные ордена стремятся очистить в Лордероне.",["race:Undead"]="Порабощение Стивена Бровача — суровое напоминание о судьбе всех жертв Короля-лича, лишенных свободной воли, которую обрели Отрекшиеся."},sec={{t="Разрушенное ремесло",b="До Третьей войны Мельница Бровача снабжала окрестные города и усадьбы Лордерона, перерабатывая лес, заготовленный в богатых лесах Восточного Предела. Когда чума Плети прокатилась по королевству, мельница пала вместе с остальной провинцией. Сегодня гнилые бревна и разбитые колеса стоят без дела, а по периметру несут дозор поганища, банши и скелеты-воины. Близость к Часовне Последней Надежды делает ее постоянным угрожающим напоминанием о полчищах нежити, теснящихся у порога Серебряного Рассвета."},{t="Судьба надсмотрщика",b="Первоначальный владелец мельницы, Стивен Бровач, встретил ту же мрачную участь, что и множество простых жителей Лордерона. Он был убит, когда Плеть захватила усадьбу, и поднят из мертвых хищным вурдалаком. Лишенный человечности и порабощенный волей Короля-лича, Бровач остается в темных стенах своей бывшей мельницы, охраняя расщепленные руины дела всей своей жизни."}},faq={{q="Где находится Мельница Бровача?",a="Мельница Бровача находится на дальнем востоке Восточных Чумных земель, прямо к северу от Часовни Последней Надежды.",al={"browman mill location","where is browman mill","how to find browman mill","где мельница бровача","расположение мельницы бровача","как найти мельницу бровача"}},{q="Какие враги обитают на мельнице?",a="Территория наводнена силами Плети: громадными поганищами, воющими банши, скелетами и бродячими вурдалаками.",al={"browman mill mobs","who is at browman mill","what lives at browman mill","монстры мельницы бровача","кто на мельнице бровача","кто живет на мельнице бровача"}},{q="Кем был Стивен Бровач?",a="Стивен Бровач был прежним хозяином и управляющим лесопилки, человеком. Он был убит во время падения Лордерона и воскрешен вурдалаком-нежитью, обязанным охранять свое разрушенное здание.",al={"who is stephen browman","stephen browman lore","browman ghoul","кто такой стивен бровач","история стивена бровача","вурдалак бровач"}},{q="Чем Мельница Бровача опасна для путников?",a="Большое скопление сильной нежити делает ее смертельно опасной, особенно потому, что она находится совсем недалеко к северу от оплота Серебряного Рассвета — Часовни Последней Надежды.",al={"why is browman mill dangerous","threat of browman mill","чем опасна мельница бровача","угроза мельницы бровача"}}},fp="12,323,17.538.0,19.371.0,30.125.0,38.134.0,24.196.0,43.175.0"}
P.entries["subzone:burning-blade-coven"] = {n="Грот Пылающего Клинка",s="Грот Пылающего Клинка, спрятанный в северных скалах Долины Испытаний, — зараженная сеть пещер, угрожающая новейшим рекрутам Орды. Внутри таятся оскверненные культисты и призванные демоны, превратившие старую рудную пещеру в плацдарм темной магии прямо у порога Дуротара.",h="Грот Пылающего Клинка, спрятанный в северных скалах Долины Испытаний, — зараженная сеть пещер, угрожающая...",kw={"burning blade coven","demon","durotar","imps","thazz'ril","valley of trials","yarrog baneshadow","грот пылающего клинка","демон","дуротар","бесы","тазз'рил","долина испытаний","йоррог тень проклятия"},ang={["class:Warlock"]="Демонические бесы и темные ритуалы здесь — ранний предостерегающий пример того, что бывает, когда силой Скверны безрассудно пользуются в открытое неповиновение Орде.",["race:Orc"]="Присутствие культа Пылающего Клинка так близко к Долине Испытаний — невыносимое оскорбление для новой Орды Тралла и суровое напоминание о поклонении демонам, от которого орки стремились избавиться."},sec={{t="Тень над Испытательными землями",b="Пыльные красные горы, окружающие Долину Испытаний, когда-то были просто испытательной глушью для молодых орков и троллей Черного Копья, делавших первые шаги на службе Орде. Но недавно в северных пещерах начались темные ритуалы. Из входа в пещеру выбираются бесы и мелкие демоны, сея хаос и угрожая рекрутам. Под предводительством зловещего чернокнижника Йоррога Тень Проклятия культ Пылающего Клинка прочно обосновался в глубине, превратив обычное место обучения в поле боя с демонической порчей."},{t="Порча в скалах",b="Прежде чем демоны пустили корни, пещеры привлекли внимание местных надзирателей, надеявшихся добывать сырье для поселения. Штейгер Тазз'рил углубился в них для разведки руды, но был поспешно изгнан, бросив ценное снаряжение, когда культисты заявили о себе. Теперь разгром шабаша Тени Проклятия — главное испытание для будущих воинов, разбойников и заклинателей, прежде чем их сочтут готовыми отправиться в остальной Дуротар."}},faq={{q="Где находится Грот Пылающего Клинка?",a="Пещера расположена в высоких хребтах красной скалы прямо вдоль северного края Долины Испытаний в Дуротаре.",al={"coven location","where is burning blade coven","valley cave location","расположение грота","где грот пылающего клинка","пещера в долине"}},{q="Кто возглавляет здешних культистов?",a="Шабашем руководит чернокнижник по имени Йоррог Тень Проклятия, который направляет местные ритуалы и командует призванными демонами.",al={"coven leader","who leads burning blade coven","yarrog","предводитель грота","кто возглавляет грот пылающего клинка","йоррог"}},{q="Какие враги таятся внутри?",a="Пещера кишит одичавшими бесами, мелкими демонами-прислужниками и смертными служителями, примкнувшими к зловещему культу Пылающего Клинка.",al={"what mobs are in the cave","coven monsters","demons in valley of trials","какие монстры в пещере","монстры грота","демоны в долине испытаний"}},{q="Почему новобранцы идут в пещеру?",a="Отважиться спуститься в темные глубины пещеры, вернуть потерянные инструменты, например кирку штейгера Тазз'рила, и убить Йоррога Тень Проклятия — заключительный обряд посвящения для новых орков и троллей, прежде чем они покинут долину.",al={"why go to coven","coven purpose","coven final test","зачем идти в грот","цель грота","последнее испытание грота"}}},fp="19,297,33.554.0,23.490.0,41.117.0,28.118.0,34.127.0,37.216.0"}
P.entries["subzone:caer-darrow"] = {n="Каэр Дарроу",s="Каэр Дарроу — укрепленный остров на Озере Дарроумир в Западных Чумных землях. Прежде родовая резиденция знатного дома Баровых, замок на острове был тайно продан Кел'Тузаду и превращен в школу некромантии — Некроситет, а город на поверхности населили блуждающие призраки.",h="Каэр Дарроу — укрепленный остров на Озере Дарроумир в Западных Чумных землях.",kw={"barov","caer darrow","cult of the damned","darrowmere lake","gandling","runestone","sarkhoff","scholomance","spectral essence","барова","каэр дарроу","культ проклятых","озеро дарроумир","гандлинг","рунический камень","сарктофф","некроситет","призрачная эссенция"},ang={["faction:Alliance"]="Для Альянса Каэр Дарроу олицетворяет два глубоких предательства: засаду альтеракских корсаров во время Второй войны, раскрывшую измену короля Перенольда, и продажу дома Баровых их родового поместья Кел'Тузаду.",["race:Human"]="Путники-люди узнают остров как бывшую резиденцию дома Баровых, одного из богатейших знатных родов Лордерона, пока жадность не привела их к союзу с Культом Проклятых."},sec={{t="Наследие войны и предательства",b="Задолго до Плети Каэр Дарроу был стратегической крепостью Лордерона, где хранился древний эльфийский рунический камень. Во время Второй войны Орда разграбила крепость и раздробила рунический камень, чтобы создать Алтари Бурь Гул'дана. Когда лорд Утер Светоносный отплыл на помощь выжившим, его флот попал в засаду альтеракских корсаров — это предательство раскрыло измену Альтерака Альянсу."},{t="Падение дома Баровых",b="После Второй войны Каэр Дарроу был отстроен и стал роскошным поместьем семьи Баровых, владевшей обширными землями в окрестностях Брилла, Мельницы Таррен и Южнобережья. Отчаянно желая сохранить богатство и бессмертие по мере приближения старости, Баровы заключили сделку с Кел'Тузадом. Под крепостью укоренился Культ Проклятых и основал Некроситет. Еще до того, как Третья война охватила Лордерон, на слуг и жителей острова напустили предварительную чуму. Население погибло, проклятое вечно бродить по разрушенному замку подобием эха."}},faq={{q="Что такое Каэр Дарроу?",a="Каэр Дарроу — островная крепость на Озере Дарроумир в Западных Чумных землях. Когда-то гордое родовое поместье богатой семьи Баровых, ныне это жуткие руины, в катакомбах которых расположена некромантская академия — Некроситет.",al={"caer darrow overview","what is this place","caer darrow lore","каэр дарроу обзор","что это за место","предания каэр дарроу"}},{q="Почему город заброшен и разрушен?",a="Семья Баровых заключила сделку с Кел'Тузадом, отдав свое поместье Культу Проклятых в обмен на бессмертие. Культ использовал слуг замка для ранних некромантских опытов и в итоге выпустил смертоносную чуму на все поселение еще до начала более широкого вторжения в Лордерон.",al={"why is caer darrow destroyed","what happened to caer darrow","caer darrow history","почему каэр дарроу разрушен","что случилось с каэр дарроу","история каэр дарроу"}},{q="Почему я не вижу призраков в городе?",a="Убитые жители Каэр Дарроу остаются неупокоенными духами, застрявшими в своих последних мгновениях. Обычным зрением их не увидеть без особого магического зрения, например с помощью призрачной эссенции, которую дают духи Евы и Люсьена Сарктоффа.",al={"where are the ghosts","invisible people caer darrow","how to see ghosts","где призраки","невидимые люди каэр дарроу","как увидеть призраков"}},{q="Что за рунический камень здесь находился?",a="Во время Второй войны в Каэр Дарроу хранился древний рунический камень высших эльфов. Орда совершила набег на остров и раздробила священный камень на части, из которых Гул'дан создал Алтари Бурь, чтобы направлять магию в огров-магов.",al={"runestone at caer darrow","elven runestone","altar of storms stone","рунический камень каэр дарроу","эльфийский рунический камень","камень алтаря бурь"}},{q="Что находится под крепостью?",a="Под замком расположен Некроситет — штаб и учебная академия Культа Проклятых. Под руководством Темного магистра Гандлинга некроманты и аколиты изучают темные искусства и ставят опыты на мертвых.",al={"what is under caer darrow","what is in the basement","dungeon under caer darrow","что под каэр дарроу","что в подвале","подземелье под каэр дарроу"}}},fp="11,317,28.424.0,23.548.1,20.236.0,37.298.0,39.248.1,44.232.0,32.217.0"}
P.entries["subzone:calmbreeze-inn"] = {n="Таверна Тихого Бриза",s="Таверна Тихого Бриза — это основные заведения, предлагающие кров и услуги на Острове Зефрис; они есть и в Деревне Шен'дар, и в Валаанаре. Они служат важными местами отдыха для путников, исследующих остров, и приютили местных учителей ремесел, трактирщиков и исторические предметы.",h="Таверна Тихого Бриза — это основные заведения, предлагающие кров и услуги на Острове Зефрис; они есть и в...",kw={"calmbreeze inn","coriella calmbreeze","eldre'thalas","shen'dar village","valaanar","zephras isle","таверна тихого бриза","кориэлла тихий бриз","эльдре'талас","деревня шен'дар","валаанар","остров зефрис"},ang={["class:Rogue"]="Мириан Туманный Клинок обучает разбойников у очага таверны Тихого Бриза в Деревне Шен'дар.",["profession:Herbalism"]="Травники, посещающие Деревню Шен'дар, могут найти Халассу Папоротниковый Бриз в Таверне Тихого Бриза, чтобы отточить свое мастерство сбора."},sec={{t="Отдых на острове",b="Таверны Тихого Бриза дарят приют среди извилистых троп Острова Зефрис. В Деревне Шен'дар таверной управляет Кориэлла Тихий Бриз, и она служит центром, где собираются островные ремесленники, в том числе наставники по травничеству, снятию шкур и наложению чар. Напротив, в Валаанаре, другая Таверна Тихого Бриза принимает местных странников и хранит редкие диковины, в том числе звуковой кристалл с записью истории древнего восстания в Эльдре'Таласе."}},faq={{q="Где находятся таверны Тихого Бриза?",a="Таверны Тихого Бриза есть и в Деревне Шен'дар, и в Валаанаре на Острове Зефрис.",al={"calmbreeze inn location","where is calmbreeze inn","calmbreeze inn map","местонахождение таверны тихого бриза","где таверна тихого бриза","карта таверны тихого бриза"}},{q="Кто управляет таверной в Деревне Шен'дар?",a="Таверну в Деревне Шен'дар содержит трактирщица Кориэлла Тихий Бриз, оказывая гостеприимство и жителям острова, и путникам.",al={"calmbreeze innkeeper","who runs calmbreeze inn","трактирщик тихого бриза","кто управляет таверной тихого бриза"}},{q="Какие учителя есть в таверне?",a="В Деревне Шен'дар в таверне находятся Халасса Папоротниковый Бриз (травничество), Менделас Рваная Заплатка (снятие шкур), Насаланна Ветряная Песнь (наложение чар) и Мириан Туманный Клинок (обучение разбойников).",al={"calmbreeze trainers","shen'dar inn trainers","учителя таверны тихого бриза","учителя таверны шен'дар"}},{q="Что за звуковой кристалл наверху в Валаанаре?",a="Наверху в таверне Валаанара лежит звуковой кристалл с третьей частью записи «Восстание в Эльдре'Таласе», повествующей об исторических событиях древнего города высокорожденных.",al={"valaanar audio crystal","the rebellion in eldre'thalas crystal","звуковой кристалл валаанар","кристалл восстание в эльдре'таласе"}}},fp="14,286,16.458.0,38.92.0,37.139.0,38.183.0,53.166.0"}
P.entries["subzone:camp-aparaje"] = {n="Лагерь Апарахе",s="Лагерь Апарахе был когда-то мирной деревней таурен в восточных высотах Когтистых гор. Сегодня он захвачен враждебным Племенем Зловещего Тотема, которое перебило первых поселенцев и забрало поселение себе.",h="Лагерь Апарахе был когда-то мирной деревней таурен в восточных высотах Когтистых гор.",kw={"camp aparaje","grimtotem","grimtotem post","grundig darkcloud","kaya flathoof","makaba flathoof","stonetalon","лагерь апарахе","зловещий тотем","застава зловещего тотема","грундиг темное облако","кайя плоское копыто","макаба плоское копыто","когтистые горы"},ang={["faction:Horde"]="Изгнание Зловещего Тотема из Лагеря Апарахе — дело мести и защиты: вероломное племя должно быть наказано за убийство невинных подданных Орды в Когтистых горах.",["race:Tauren"]="Руины Лагеря Апарахе служат горьким напоминанием о жестокости племени Зловещего Тотема Магаты и доказывают, что не все дети Матери-Земли разделяют представление Кэрна Кровавого Копыта о чести и мире."},sec={{t="Трагическое падение",b="Лагерь Апарахе, расположенный среди скал Когтистых гор, основали мирные тауренны, желавшие спокойно жить в горах. Этот покой был нарушен, когда налетчики с Заставы Зловещего Тотема под предводительством Грундига Темное Облако устроили жестокое нападение без всякого повода. Жителей перебили или прогнали, а выжившие, такие как Макаба Плоское Копыто, остались оплакивать разрушение своего дома и страшиться за судьбу пленных сородичей."},{t="Во власти Зловещего Тотема",b="Now completely occupied by Grimtotem warriors, Camp Aparaje serves as a forward base of operations for the aggressive tribe in the region. Unlike typical Grimtotem settlements that fly blue markings, the great totem standing in Aparaje is carved with deep crimson paint."}},faq={{q="Кто раньше жил в Лагере Апарахе?",a="В Лагере Апарахе жили мирные тауренны, связанные с Ордой и племенем Кровавого Копыта, в том числе Макаба Плоское Копыто и его дочь Кайя, пока поселение не подверглось нападению.",al={"who lived here","camp aparaje original villagers","makaba flathoof village","кто здесь жил","первые жители лагеря апарахе","деревня макабы плоское копыто"}},{q="Почему лагерь враждебен игрокам Орды?",a="Деревню силой захватило Племя Зловещего Тотема — нетерпимый к чужакам и вероломный клан таурен, который отказывается подчиняться Кэрну Кровавому Копыту и нападает на чужаков, в том числе на членов Орды.",al={"why are tauren attacking me","who controls camp aparaje","why is camp aparaje red","почему на меня нападают таурены","кто контролирует лагерь апарахе","почему лагерь апарахе красный"}},{q="Кто возглавил нападение на Лагерь Апарахе?",a="Набегом руководил Грундиг Темное Облако, жестокий вождь Зловещего Тотема, действующий с Заставы Зловещего Тотема и стремящийся расширить власть своего племени над Когтистыми горами.",al={"who attacked aparaje","grundig darkcloud","who is the leader here","кто напал на апарахе","грундиг темное облако","кто здесь вождь"}},{q="Что стало с выжившими жителями?",a="Большинство жителей погибло во время набега. Некоторым удалось бежать, а других, например юную Кайю Плоское Копыто, захватили воины Зловещего Тотема и держат в плену на ближайшей Заставе Зловещего Тотема.",al={"kaya flathoof","where are the survivors","are there survivors","кайя плоское копыто","где выжившие","есть ли выжившие"}}},fp="12,250,17.458.0,20.270.0,33.176.0,41.205.0,36.169.0,41.186.0"}
P.entries["subzone:camp-e-thok"] = {n="Лагерь Э'Ток",s="Лагерь Э'Ток — поселение кентавров Галак на северо-западе Тысячи Игл. Агрессивное племя кентавров использует этот лагерь в каньоне как базу для засад на проезжающие караваны в русле реки внизу.",h="Лагерь Э'Ток — поселение кентавров Галак на северо-западе Тысячи Игл.",kw={"camp e'thok","centaur","ethok","galak","thousand needles","wizlo bearingshiner","лагерь э'ток","кентавр","э'ток","галак","тысяча игл","визло фингалет"},ang={["race:Tauren"]="Неослабевающая агрессия кентавров Галак в Лагере Э'Ток — постоянное напоминание о древней войне между тауренами и кентаврами на юге Калимдора."},sec={{t="Твердыня Галак",b="Лагерь Э'Ток, укрытый в суровых северо-западных землях Тысячи Игл, — ключевое поселение враждебных кентавров Галак. Как и их сородичи по всему Калимдору, Галак беспощадно хищны и нападают на любых путников, забредших в тень каньона. Лагерь известен набегами на торговые караваны, в частности засадой на гоблина Визло Фингалета и захватом его товаров, хотя его драгоценное устройство ускользнуло от них — его охранял свирепый питомец-пантера."}},faq={{q="Кто живет в Лагере Э'Ток?",a="Лагерь занят кланом кентавров Галак — агрессивным племенем, господствующим в частях северо-западной Тысячи Игл.",al={"who is in camp ethok","camp ethok inhabitants","who controls camp ethok","кто в лагере э'ток","жители лагеря э'ток","кто контролирует лагерь э'ток"}},{q="Что случилось здесь с Визло Фингалетом?",a="Торговый караван с гоблином Визло Фингалетом попал в засаду кентавров Галак из Лагеря Э'Ток. Они разграбили караван, но не смогли забрать драгоценное устройство Визло, поскольку оно было закреплено на ошейнике его свирепого питомца-пантеры.",al={"wizlo bearingshiner raid","goblin caravan attacked","what did centaur steal from wizlo","нападение на визло фингалета","нападение на гоблинский караван","что кентавры украли у визло"}},{q="Где находится Лагерь Э'Ток?",a="Лагерь Э'Ток расположен на северо-западе Тысячи Игл, у подножия стен каньона близ Высот Расколотого Копыта.",al={"camp ethok location","where is camp ethok","camp ethok map","местонахождение лагеря э'ток","где лагерь э'ток","карта лагеря э'ток"}}},fp="11,231,18.508.0,25.127.0,42.256.0,29.124.0"}
P.entries["subzone:camp-kosh"] = {n="Лагерь Кош",s="Лагерь Кош — стоянка огров на севере Бесплодных земель, где обитают агрессивные огры клана Гнилобрюхов. Расположенные у важных путей, эти громилы нападают на проезжающие караваны и подбирают все снаряжение, которое путники оставляют в суровой пустыне.",h="Лагерь Кош — стоянка огров на севере Бесплодных земель, где обитают агрессивные огры клана Гнилобрюхов.",kw={"badlands","camp kosh","dustbelcher","ogres","sigrun ironhew","uldaman","бесплодные земли","лагерь кош","гнилобрюхи","огры","сигрун рудотес","ульдаман"},ang={["faction:Alliance"]="Разведчикам Альянса, идущим северным перевалом к Тлеющему ущелью, следует быть настороже у Лагеря Кош: громилы охотно устраивают засады на проезжающие караваны снабжения.",["race:Dwarf"]="Огры-мародеры Лагеря Кош разграбили ценные пайки и запасы оружия, оставленные многострадальной экспедицией Сигрун Рудотес в Ульдаман."},sec={{t="Логово мародеров",b="Лагерь Кош, расположенный в северных пустошах Бесплодных земель, — самое северное поселение огров клана Гнилобрюхов, которые занимают и соседние лагеря: Бофф, Кагг и Вург. Огры здесь пользуются близостью дорог и грабят уязвимые линии снабжения, идущие к Каргату или на запад, в Тлеющее ущелье. Когда дворфийские старатели во главе с Сигрун Рудотес были вынуждены бежать с раскопок в Ульдамане, громилы Лагеря Кош быстро разграбили их брошенные повозки и утащили в свой пыльный лагерь ценные запасы еды и оружие."}},faq={{q="Кто живет в Лагере Кош?",a="Лагерь Кош населяют огры клана Гнилобрюхов — племя жестоких огров, контролирующее несколько небольших лагерей в засушливых Бесплодных землях.",al={"camp kosh mobs","who is at camp kosh","ogres camp kosh","монстры лагеря кош","кто в лагере кош","огры лагерь кош"}},{q="Почему Лагерь Кош находится здесь?",a="Северное положение позволяет ограм клана Гнилобрюхов устраивать засады на караваны снабжения и неосторожных путников, идущих между Тлеющим ущельем, Ульдаманом и заставой Орды Каргат.",al={"why camp kosh","camp kosh location","почему лагерь кош","местонахождение лагеря кош"}},{q="Что огры украли у дворфов?",a="Когда дворфийская экспедиция Сигрун Рудотес отступила перед опасностями Ульдамана, она бросила в пустыне повозки с припасами. Огры Лагеря Кош обшарили обломки и унесли ящики с продовольствием и партии оружия.",al={"dwarf supplies camp kosh","sigrun ironhew supplies","uldaman wagons","припасы дворфов лагерь кош","припасы сигрун рудотес","повозки ульдамана"}}},fp="9,250,19.583.0,23.138.0,30.177.0,42.227.0"}
P.entries["subzone:camp-mojache"] = {n="Лагерь Мохаче",kw={"braves","camp mojache","feralas","flight master","gordunni","tauren","wildwind lake","woodpaw","воины","лагерь мохаче","фералас","распорядитель полетов","гордунни","таурены","штормовое озеро","лесная лапа"},ang={["faction:Horde"]="Мохаче — единственный укрепленный оплот Орды в Фераласе и ваше единственное убежище, где можно отдохнуть, пополнить припасы и быстро перебраться через глубокий лес.",["race:Tauren"]="Лагерь Мохаче — самый дальний южный предел традиционных ремесел и поселений вашего народа в Калимдоре, где в глубине тропического леса сохраняется гармония."},sec={{t="Оплот тауренов в тропическом лесу",b="Situated in eastern Feralas along a swift-flowing stream that feeds Wildwind Lake, Camp Mojache is a tauren settlement built to secure a foothold in the wild southern forest. While the dense jungle holds perilous threats—from savage wildlife to Gordunni ogres and aggressive Woodpaw gnolls—the camp stands as an island of safety. Equipped with lodging, trade masters, and a wind rider roost, it serves as the vital logistical hub for Horde champions operating in the region."},{t="Пограничная застава",b="Охотники и воины лагеря известны отвагой и толстыми шкурами и постоянно бдительны перед набегами из окрестных дебрей. Для Орды удержание Мохаче необходимо, чтобы распространять влияние на Фералас и сдерживать как ночных эльфов с побережья, так и темные силы, таящиеся в Забытом Городе."}},faq={{q="Что такое Лагерь Мохаче?",a="Camp Mojache is the main Horde base of operations in Feralas. Built and maintained predominantly by the tauren, it straddles a stream emptying into Wildwind Lake and offers resting facilities, trade supplies, and flight transport.",al={"camp mojache purpose","what is this camp","tauren town feralas","лагерь мохаче назначение","что за лагерь","город тауренов фералас"}},{q="Кто возглавляет и защищает лагерь?",a="Поселение охраняют опытные воины-таурены, отражающие вторжения местных стай зверей, огров Гордунни и агрессивных гноллов Лесной Лапы, которые бродят в лесу к западу.",al={"camp mojache guards","who defends mojache","who is in charge of camp mojache","стража лагеря мохаче","кто защищает мохаче","кто главный в лагере мохаче"}},{q="Куда летает местный распорядитель полетов?",a="С насеста наездников на ветрах в лагере можно долететь до крупных центров — Громового Утеса, Перекрестка в Степях, Деревни Ночных Охотников в Пустошах — и до соседних застав, например Прибамбасска в Танарисе.",al={"camp mojache flight paths","where can i fly from camp mojache","полеты из лагеря мохаче","куда лететь из лагеря мохаче"}},{q="Какие главные угрозы окружают Лагерь Мохаче?",a="В окрестных лесах обитают клан гноллов Лесной Лапы на западе, территориальные огры Гордунни на севере и юге, а также силы Альянса, действующие с далекого западного побережья из Крепости Оперенной Луны.",al={"feralas danger camp mojache","threats near camp mojache","enemies near mojache","опасности фераласа лагерь мохаче","угрозы возле лагеря мохаче","враги возле мохаче"}}},fp="12,306,34.478.0,16.347.0,21.230.0,30.191.0,42.204.0,41.210.0"}
P.entries["subzone:camp-narache"] = {n="Лагерь Нараче",s="Лагерь Нараче — уединенная деревня на плато Красного Облака в южном Мулгоре. Это родной дом племени Соколиного Ветра и место, где молодые таурены начинают обучение. Лагерь, укрытый высоко над равнинами, хранит древние традиции и постоянно защищается от свинобразов и остаточной угрозы кентавров.",h="Лагерь Нараче — уединенная деревня на плато Красного Облака в южном Мулгоре.",kw={"bristleback","greatmother hawkwind","hawkwind","mulgore","narache","red cloud mesa","spirit lounge","tauren","дыбогрив","великая мать соколиный ветер","соколиный ветер","мулгор","нараче","плато красного облака","дух-зал","таурены"},ang={["class:Shaman"]="Молодые шаманы делают здесь первые шаги по духовному пути и проходят испытания, чтобы получить Тотем земли и напрямую говорить со стихиями плато.",["race:Tauren"]="Для тауренов Лагерь Нараче означает конец детства — священная земля, где вы проходите первые обряды охоты и настраиваетесь на духов предков под бдительным взором старейшин Соколиного Ветра."},sec={{t="Сердце племени Соколиного Ветра",b="Лагерь Нараче, расположенный на северном краю возвышенного плато Красного Облака, — главное поселение племени Соколиного Ветра. Деревня состоит из нескольких больших шатров из шкур и павильонов, среди которых общий шатер для раненых воинов, оружейная, пекарня и дух-зал для медитации и общения с предками. В центре лагеря стоят в кругу старейшины племени и наставники путей, а почтенная Великая Мать Соколиный Ветер по-прежнему дает советы и направляет новообращенную молодежь, когда та становится защитниками Матери-Земли."},{t="Испытательное место под угрозой",b="Хотя лагерь Нараче защищен отвесными обрывами плато, здесь не прекращаются беспокойства. Дыбогривы из Ежевичной лощины постоянно вторгаются в земли племени Соколиного Ветра, а разведчики кентавров маячат вдали. Молодые охотники, шаманы, друиды и воины доказывают здесь свою доблесть: истребляют агрессивных местных зверей, защищают деревенский колодец и отбивают набеги свинобразов, а затем спускаются по большой тропе в широкие долины Мулгора."}},faq={{q="Что такое Лагерь Нараче?",a="Лагерь Нараче — стартовая деревня молодых тауренов на плато Красного Облака в южном Мулгоре. Это главный стан племени Соколиного Ветра и убежище, где начинающие охотники, воины, друиды и шаманы осваивают свое ремесло, прежде чем отправиться в Деревню Кровавого Копыта и Громовой Утес.",al={"what is camp narache","narache lore","tauren starting town","что такое лагерь нараче","предания нараче","стартовая деревня тауренов"}},{q="Кто возглавляет деревню?",a="Вождь Соколиный Ветер ведет воинов племени и координирует оборону плато вместе с почитаемой старейшиной племени — Великой Матерью Соколиный Ветер. Наставники и старейшины племени собираются в центре лагеря, чтобы обучать юных искателей приключений.",al={"who leads camp narache","camp narache chief","hawkwind leader","кто возглавляет лагерь нараче","вождь лагеря нараче","вождь соколиный ветер"}},{q="Какие угрозы нависают над лагерем?",a="Стан постоянно тревожат дыбогривы, действующие из Ежевичной лощины на востоке. Помимо диких боевых вепрей и долгоножек, бродящих по окрестным утесам, постоянная опасность хищных банд кентавров держит воинов Соколиного Ветра настороже.",al={"camp narache enemies","who attacks camp narache","mesa threats","враги лагеря нараче","кто нападает на лагерь нараче","угрозы плато"}},{q="Легко ли путникам покинуть плато?",a="Плато Красного Облака со всех сторон ограничено отвесными обрывами. Единственный спуск на большие равнины Мулгора идет по охраняемой горной тропе на север, за которой следят воины Соколиного Ветра, чтобы враждебные звери и свинобразы не нападали на путников из засады.",al={"leaving red cloud mesa","exit camp narache","path off the mesa","покинуть плато красного облака","выход из лагеря нараче","тропа с плато"}}},fp="12,358,27.590.0,29.487.0,21.318.0,22.237.0,32.285.0,36.250.0"}
P.entries["subzone:camp-taurajo"] = {n="Лагерь Таурахо",s="Лагерь Таурахо — тихое поселение тауренов в южных Степях, прямо у горного прохода на запад, в Мулгор. Это важное пограничное убежище, где усталые странники найдут таверну, припасы, наставников по профессиям и воздушное сообщение между равнинами и центральным Калимдором.",h="Лагерь Таурахо — тихое поселение тауренов в южных Степях, прямо у горного прохода на запад, в Мулгор.",kw={"barrens","bloodhoof village","camp taurajo","mulgore pass","southern barrens","taurajo","tauren outpost","степи","деревня кровавого копыта","лагерь таурахо","проход мулгора","южные степи","таурахо","застава тауренов"},ang={["faction:Horde"]="Лагерь Таурахо защищает важный сухопутный перекресток и пункт полетов, тесно связывая Мулгор с остальным центральным Калимдором под властью Орды.",["race:Tauren"]="Для тауренов, впервые покидающих Мулгор, Лагерь Таурахо — первое дружественное убежище на суровых равнинах Степей."},sec={{t="Рубеж Красных скал",b="Лагерь Таурахо, расположенный у восточного входа в проход к Мулгору, часто становится первым знакомством со Степями для молодых тауренов, покидающих Деревню Кровавого Копыта. Окруженный сухим кустарником и неприступными плато, лагерь служит и заставой, и торговым центром. Здесь находят приют охотники, кожевники и травники, а также есть воздушное сообщение с Громовым Утесом, Перекрестком и Заставой Вольного Ветра дальше на юге."}},faq={{q="Что такое Лагерь Таурахо?",a="Лагерь Таурахо — застава и поселение тауренов в южных Степях, важный пункт на пути между родным Мулгором и засушливыми кустарниковыми землями Степей.",al={"camp taurajo overview","what is taurajo","taurajo lore","обзор лагеря таурахо","что такое таурахо","предания таурахо"}},{q="Куда ведет дорога на запад?",a="Грунтовая тропа на запад от Лагеря Таурахо ведет через горный проход в Мулгор, прямо к Деревне Кровавого Копыта и Громовому Утесу.",al={"taurajo west pass","road west of camp taurajo","path to mulgore","западный проход таурахо","дорога на запад от лагеря таурахо","путь в мулгор"}},{q="Куда летают наездники на ветрах из Лагеря Таурахо?",a="Местный распорядитель полетов управляет маршрутами виверн, которые напрямую соединяют лагерь с Перекрестком на севере, Громовым Утесом на западе и Заставой Вольного Ветра в Тысяче Игл на юге.",al={"taurajo flight master","taurajo flight paths","flight connections taurajo","распорядитель полетов таурахо","полеты из таурахо","воздушное сообщение таурахо"}}},fp="12,303,25.441.0,21.173.0,30.146.0,47.189.0"}
P.entries["subzone:camp-wurg"] = {n="Лагерь Вург",s="Лагерь Вург — стоянка огров в засушливых просторах Бесплодных земель. Это одна из застав, занятых территориальными ограми клана Гнилобрюхов, которые властвуют в восточных долинах.",h="Лагерь Вург — стоянка огров в засушливых просторах Бесплодных земель.",kw={"badlands","boss tho'grun","camp boff","camp cagg","camp kosh","camp wurg","dustbelcher","ogre","wurg","бесплодные земли","босс тхо'грун","лагерь бофф","лагерь кэгг","лагерь кош","лагерь вург","гнилобрюхи","огр","вург"},sec={{t="Оплот клана Гнилобрюхов",b="Лагерь Вург, затерянный среди скал Бесплодных земель, — один из четырех главных лагерей огров клана Гнилобрюхов наряду с Лагерем Кэгг, Лагерем Бофф и Лагерем Кош. Стоящие здесь огры яростно охраняют свою суровую территорию, добывая что можно в неприветливых пустынных пустошах. Рядовые громилы и надсмотрщики живут у грубых костров и шкур Вурга, а их вождь, Босс Тхо'грун, постоянного места здесь не имеет и бродит по тропам Бесплодных земель, присматривая за всеми своими лагерями."}},faq={{q="Кто живет в Лагере Вург?",a="Лагерь Вург населяют огры клана Гнилобрюхов — свирепое и территориальное племя, основавшее поселения по всем Бесплодным землям.",al={"camp wurg mobs","who is at camp wurg","who lives here","существа лагеря вург","кто в лагере вург","кто здесь живет"}},{q="Где находится предводитель лагеря?",a="Предводитель огров клана Гнилобрюхов, Босс Тхо'грун, не сидит на месте в Лагере Вург. Он обходит открытые тропы Бесплодных земель между Вургом, Кэггом, Бофф и Кошем.",al={"camp wurg boss","boss thogrun location","who leads camp wurg","босс лагеря вург","где босс тхо'грун","кто возглавляет лагерь вург"}},{q="Какие еще лагеря принадлежат этому племени?",a="Огры клана Гнилобрюхов владеют четырьмя главными оплотами в Бесплодных землях: Лагерем Вург, Лагерем Кэгг, Лагерем Бофф и Лагерем Кош.",al={"dustbelcher camps","other ogre camps badlands","ogre settlements badlands","лагеря гнилобрюхов","другие лагеря огров бесплодные земли","поселения огров бесплодные земли"}}},fp="9,193,24.521.0,23.132.0,32.175.0,38.119.0"}
P.entries["subzone:canals-stormwind-city"] = {n="Каналы (Штормград)",s="Каналы — сеть облицованных камнем водных путей, пронизывающих Штормград и разделяющих его кварталы. Это тихие тропы для пешеходов и рыболовов, скрывающие тайные опасности и вход в городскую тюрьму.",h="Каналы — сеть облицованных камнем водных путей, пронизывающих Штормград и разделяющих его кварталы.",kw={"canal district","canals","crocolisk","gallina","sewers","stockade","stormwind","waterways","квартал каналов","каналы","кроколиск","галлина","канализация","тюрьма","штормград","водные пути"},ang={["faction:Alliance"]="Каналы — свидетельство восстановления столицы Альянсом Лордерона, который превратил забитые телами руины Первой войны обратно в оживленный живописный город.",["profession:Cooking"]="Тихие берега каналов дают поварам удобные места, чтобы учиться ловить свежую рыбу, не покидая безопасных стен столицы."},sec={{t="Артерии столицы",b="Каналы соединяют и определяют кварталы Штормграда, отделяя шумные рынки Торгового квартала от старых переулков Старого города, соборных садов и Квартала Дворфов. Каменные мосты, арки и набережные обрамляют тихие заведения, такие как винодельня Галлины, швейные мастерские и спокойные жилые дома. Помимо торговцев и рыболовов-любителей, воды скрывают укрепленный вход в Тюрьму, где ниже уровня улиц содержатся самые опасные преступники и мятежники Штормграда."},{t="Мрачная история и таящиеся тени",b="Спокойная гладь каналов скрывает жестокое прошлое. После разорения Штормграда в Первую войну каналы нашли забитыми обломками, бревнами и телами убитых защитников. Когда Альянс Лордерона освободил руины, солдаты выполнили мрачную работу: расчистили каналы и похоронили мертвых, и только потом началось восстановление. Сегодня каналы очищены и восстановлены, но в глубинах сохраняется тайна: в городе ходят слухи о гигантском кроколиске-альбиносе, затаившемся под доками."}},faq={{q="Что случилось с каналами во время Первой войны?",a="Когда Орочья Орда захватила и разорила Штормград в Первую войну, каналы оказались полны битого камня, бревен и гниющих тел. Войскам Альянса Лордерона, отвоевавшим город, пришлось тщательно вычистить каналы и подобающе похоронить павших, прежде чем город смогли отстроить.",al={"canal history","canals first war","stormwind sack canals","история каналов","каналы первая война","разорение штормграда каналы"}},{q="Правда ли, что в каналах Штормграда живет чудовище?",a="Наверняка не скажет никто. Упорные городские легенды говорят о гигантском белом кроколиске, затаившемся в каналах. Стража и жители часто считают это трактирной болтовней, но слухи не стихают, а искателей приключений предупреждают не падать в воду.",al={"stormwind crocodile","canal alligator","sewer beast","white crocolisk","крокодил штормграда","аллигатор в каналах","чудовище канализации","белый кроколиск"}},{q="Где находится вход в Тюрьму?",a="Вход в Тюрьму находится на самом северном отрезке канала, окружающего Квартал магов, и его усиленно охраняет городская стража Штормграда.",al={"where is stockade","stockade entrance","how to get to stockade","где тюрьма","вход в тюрьму","как попасть в тюрьму"}},{q="Можно ли проплыть по каналам, чтобы добраться по Штормграду?",a="Проплыть по каналам вполне возможно, но чтобы выбраться обратно на улицу, нужно найти каменные лестницы или причалы вдоль набережных.",al={"swimming in canals","travel by water stormwind","water route stormwind","плавание в каналах","путь по воде штормград","водный маршрут штормград"}}},fp="23,257,23.546.0,38.519.0,49.299.0,50.245.0,46.151.0,63.154.0"}
P.entries["subzone:canals-undercity"] = {n="Каналы (Подгород)",s="Каналы образуют мутный кольцевой ров, который вьется между отдельными кварталами Подгорода. Они заполнены не чистой водой, а неестественной ядовитой зеленой слизью и служат одновременно канализацией и мрачным символом подземной крепости Отрекшихся.",h="Каналы образуют мутный кольцевой ров, который вьется между отдельными кварталами Подгорода.",kw={"canals","fishing","forsaken","green slime","lordaeron","sludge","toxic","undercity","каналы","рыбалка","отрекшиеся","зеленая слизь","лордерон","жижа","яд","подгород"},ang={["class:Shaman"]="Стихии почти не властны над загрязненной грязью, наполняющей водные пути Подгорода, поэтому обычные заклинания, например хождение по воде, полностью перестают действовать.",["race:Undead"]="Для Отрекшихся зловонные каналы совершенно безвредны для их нежизни: они служат рвом и стоком химических отходов, подходящим для их подземного владения."},sec={{t="Ядовитый ров",b="Каналы вырублены в подземных глубинах под руинами Лордерона. Они окружают сердце Подгорода и разделяют его кварталы широкими протоками вялой зеленой жижи. Если в городах смертных по улицам течет чистая речная вода, то Отрекшиеся заполнили эти каменные русла промышленными отходами, химическими стоками и алхимическими отбросами. Жидкость слабо и болезненно светится и испускает зловонные пары, поэтому пройти по ней обычными магическими способами, например хождением по воде, невозможно. Несмотря на смертоносность жижи, отчаянные рыболовы порой вытаскивают из грязи странные, оскверненные диковинки."}},faq={{q="Что за зеленая жидкость в каналах?",a="Это алхимическая жижа из ядовитых стоков, побочных продуктов чумы и промышленных отходов, которая скапливается в дренажной системе Подгорода. В отличие от чистой воды, она заметно осквернена и зловонна.",al={"undercity green water","what is the slime in undercity","green slime river","зеленая вода подгорода","что за слизь в подгороде","река зеленой слизи"}},{q="Можно ли ловить рыбу в каналах Подгорода?",a="Да, терпеливые рыболовы могут забросить удочку в жижу. Помимо больной, зараженной рыбы, порой удается вытащить выброшенный хлам, в том числе старые человеческие черепа из павшего прошлого Лордерона.",al={"fishing undercity","can you fish here","fishing in green slime","рыбалка подгород","можно ли здесь ловить рыбу","рыбалка в зеленой слизи"}},{q="Почему хождение по воде не работает на каналах?",a="Густая химическая жижа не ведет себя как обычная вода. Из-за ее мерзкой вязкости и неестественного состава шаманы и другие заклинатели не могут удержать поверхностное натяжение с помощью обычной магии хождения по воде.",al={"water walking undercity","shaman water walking bug","why cant i walk on water undercity","хождение по воде подгород","шаман хождение по воде баг","почему нельзя идти по воде в подгороде"}}},fp="18,261,12.614.0,39.201.0,37.192.0,45.217.0"}
P.entries["subzone:cape-of-stranglethorn"] = {n="Мыс Тернистой долины",s="Мыс Тернистой долины — выжженная солнцем южная оконечность Тернистой долины, которая тянется на юг от Арены Гурубаши до прибрежных утесов. Центром региона служит обширный пиратский порт Пиратская бухта, а сам он — поле боя гоблинов, Пиратов Кровавого Паруса, древних троллей джунглей и наступающих диких зверей.",h="Мыс Тернистой долины — выжженная солнцем южная оконечность Тернистой долины, которая тянется на юг от Арены...",kw={"baron revilgaz","blackwater raiders","bloodsail buccaneers","booty bay","cape of stranglethorn","gurubashi arena","south seas","stranglethorn vale","барон ревилгаз","налетчики черноводья","пираты кровавого паруса","пиратская бухта","мыс тернистой долины","арена гурубаши","южные моря","тернистая долина"},ang={["class:Rogue"]="Мыс — приют корсаров, негодяев и головорезов: здесь множество возможностей обчистить карманы, наладить прибрежную контрабанду или стравить Налетчиков Черноводья с Пиратами Кровавого Паруса.",["profession:Cooking"]="Окрестные Южные моря и прибрежные воды дают ценные места для рыбалки и редкие рецепты, которые продают только рыботорговцы и портовые повара Пиратской бухты."},sec={{t="Край континента",b="К югу от древнего колизея Арена Гурубаши густые джунгли сменяются побережьем, известным как Мыс Тернистой долины. Мыс усеян руинами поселений троллей, такими как Руины Жубуваля и Руины Абораза, и давно вышел из-под власти империи Гурубаши. Сегодня на его пляжах, в бухтах и на лесных полянах встречаются опасные хищники, лагеря мурлоков и враждующие пиратские команды, сражающиеся за торговые пути и зарытую добычу."},{t="Пиратская бухта и война корсаров",b="Главная сила на мысе — Налетчики Черноводья, которыми из пиратского города Пиратская бухта руководят барон Ревилгаз и командир флота Морской Рог. Эта нейтральная гавань, высеченная прямо в скалах южной бухты, связывает Восточные королевства с Калимдором паровыми судами до Кабестана. Однако власть гоблинов остается шаткой. Пираты Кровавого Паруса действуют у южных отмелей и дальних островов, грабят линии снабжения и открыто замышляют свергнуть Пиратскую бухту и захватить полное господство над Южными морями."}},faq={{q="Чем отличаются Тернистая долина и Мыс Тернистой долины?",a="Мыс Тернистой долины — это южная часть более крупной Тернистой долины, включающая земли и побережья к югу от Арены Гурубаши до Пиратской бухты.",al={"cape vs vale","stranglethorn geography","where is the cape","мыс и долина","география тернистой долины","где находится мыс"}},{q="Кто правит Мысом Тернистой долины?",a="Единой власти над всем мысом нет. Пиратской бухтой и окрестными водами управляют барон Ревилгаз и поддерживаемые гоблинами Налетчики Черноводья, а Пираты Кровавого Паруса, наги и остатки троллей контролируют отдельные пляжи и внутренние руины.",al={"who leads booty bay","cape ruler","who controls the cape","кто правит пиратской бухтой","правитель мыса","кто управляет мысом","кто контролирует мыс"}},{q="Могут ли Орда и Альянс пользоваться Пиратской бухтой?",a="Да. Пиратская бухта — открытый нейтральный порт, который содержит Картель Хитрая Шестеренка. Пока путники держат оружие в ножнах и соблюдают мир в черте города, искатели приключений и Альянса, и Орды могут пользоваться ее причалами, торговцами, распорядителем полетов и аукционом.",al={"is booty bay neutral","alliance horde booty bay","can horde enter booty bay","нейтральна ли пиратская бухта","альянс орда пиратская бухта","может ли орда войти в пиратскую бухту"}},{q="Что такое Арена Гурубаши?",a="Арена Гурубаши — древняя тролльская бойцовская яма у северного края мыса, где собираются бойцы, чтобы испытать себя.",al={"gurubashi chest","arena rules","pvp arena stranglethorn","сундук гурубаши","правила арены","пвп арена тернистая долина"}},{q="Как путники добираются между мысом и Калимдором?",a="Гоблинский пароход регулярно ходит между причалами Пиратской бухты и портовым городом Кабестан в Степях. Это одно из немногих пассажирских сообщений через океан по Южным морям.",al={"boat to ratchet","kalimdor transport","booty bay boat","корабль в кабестан","транспорт в калимдор","корабль пиратская бухта"}}},fp="21,323,21.466.0,31.516.0,80.184.0,36.256.0,42.271.0,28.132.0,51.196.0"}
P.entries["subzone:capital-gardens"] = {n="Центральный сад",s="Центральный сад — западное крыло древних эльфийских руин Забытого Города в Фераласе. Некогда это был безмятежный ухоженный парк кальдораев-аристократов, а теперь он превратился в зачумленный лес, где бродят оскверненные древни, призраки и остатки Шен'дралар.",h="Центральный сад — западное крыло древних эльфийских руин Забытого Города в Фераласе.",kw={"athenaeum","capital gardens","dire maul west","eldre'thalas","feralas","immol'thar","shen'dralar","атенеум","центральный сад","забытый город запад","эльдре'талас","фералас","имол'тар","шен'дралар"},ang={["class:Mage"]="Несмотря на упадок, в саду есть пути к Атенеуму — одному из величайших хранилищ магической теории эпохи до Раскола, уцелевших в Калимдоре.",["race:NightElf"]="Для ночных эльфов прогулка по оскверненным плитам Центрального сада — тяжкое напоминание о гордыне высокорожденных и катастрофической цене тяги к магии."},sec={{t="Заброшенное убежище",b="Десять тысячелетий назад Эльдре'Талас был одной из сверкающих жемчужин империи кальдораев. Центральный сад служил его внешним кварталом: пышная зачарованная флора и величественные мраморные террасы, где высокорожденные чародеи спорили и отдыхали. После Великого Раскола анклав пришел в отчаянное положение. Лишившись Источника Вечности, Шен'дралар обратились к темной магии, чтобы поддерживать бессмертие, и позволили саду засохнуть. Сегодня серые искривленные ветви и оскверненные древни наполняют разрушенные дворы, а остаточная магическая порча не дает лесу по-настоящему исцелиться."},{t="Атенеум и тюрьма",b="За заросшими аллеями и враждебными древнями Центральный сад ведет вглубь оплота Шен'дралар. Тропы приводят прямо ко Двору высокорожденных и в Атенеум — сохранившуюся библиотеку, где хранятся вековые магические знания и забытые трактаты. Еще глубже находится Тюрьма Имол'тара, где уцелевшие эльфы заточили демона, чтобы черпать его силу. Этот отчаянный поступок исказил окрестные сады и превратил их в нынешний кошмар."}},faq={{q="Что такое Центральный сад?",a="Центральный сад — западное крыло Забытого Города, расположенное среди руин Эльдре'Таласа в центре Фераласа. Когда-то это был нетронутый общественный парк и место проживания городской элиты высокорожденных.",al={"what is capital gardens","dire maul west gardens","eldre'thalas park","что такое центральный сад","западные сады забытого города","парк эльдре'таласа"}},{q="Почему здесь осквернены деревья и древни?",a="После уничтожения Источника Вечности уцелевшие Шен'дралар поддерживали себя, высасывая темную энергию Скверны из призванного демона Имол'тара. Возникшая утечка нестабильной магии медленно исказила местные растения и ввергла живущих здесь древней в неистовое безумие.",al={"why are ancients evil here","what happened to the trees","why is it blighted","почему древни злые","что случилось с деревьями","почему здесь все заражено"}},{q="Куда ведет эта область?",a="Сад ведет вглубь западной части Забытого Города: ко Двору высокорожденных, ученому Атенеуму и внутреннему святилищу, где заключен демон Имол'тар.",al={"what connects to capital gardens","where does it go","что связано с центральным садом","куда ведет"}},{q="Остались ли в саду дружелюбные эльфы?",a="Большинство высокорожденных, бродящих по тропам, — враждебные духи или обезумевшие защитники. Однако в соседнем Атенеуме еще живут некоторые ученые Шен'дралар, готовые обменять древние знания или потерянные либрамы эльфов.",al={"any allies inside","who lives in capital gardens","союзники внутри","кто живет в центральном саду"}}},fp="15,263,19.609.0,28.475.1,28.195.0,46.280.0,26.182.0,49.232.0"}
P.entries["subzone:cathedral-square"] = {n="Соборная площадь",s="Соборная площадь — духовное и общественное сердце Штормграда, над которым возвышается величественный Собор Света. Помимо того что это место поклонения и молитвы, на оживленной площади расположены городские учреждения: ратуша, городской приют и региональная штаб-квартира Серебряного Рассвета.",h="Соборная площадь — духовное и общественное сердце Штормграда, над которым возвышается величественный Собор...",kw={"argent dawn","cathedral of light","cathedral square","city hall","holy district","orphanage","paladin","priest","stormwind","серебряный рассвет","собор света","соборная площадь","ратуша","священный квартал","приют","паладин","жрец","штормград"},ang={["class:Paladin"]="Для паладинов Соборная площадь — источник веры и долга: здесь живут наставники, даются священные обеты и работают оружейники, создающие снаряжение для священных воинов.",["class:Priest"]="Тихие залы и высокие шпили площади дают жрецам спокойное убежище, где можно говорить со Светом, продолжать духовные занятия и заботиться о жителях Штормграда."},sec={{t="Священный квартал",b="Соборная площадь лежит к северо-западу от Торгового квартала и к юго-востоку от Квартала Дворфов и служит средоточием веры в Королевстве Штормград. Над ней возвышается Собор Света — главное святилище последователей Света во всем Азероте. Жрецы, паладины и целители собираются здесь, чтобы учиться, молиться и тренироваться. Горожане, паломники и местные школьники во главе с учительницей Данной часто собираются на площади для бесед и размышлений."},{t="Общественное сердце и священный орден",b="Квартал отведен не только для молитв: это один из самых оживленных общественных центров столицы. На площади находятся Штормградский приют и ратуша, определяющие административную жизнь королевства. Вдоль улиц выстроились оружейники и кузнецы, работающие для священных воинов, например «Праведные доспехи» и «Справедливые булавы». Здесь также располагается опорный пункт Серебряного Рассвета в Штормграде: вербовщики и представители координируют помощь и собирают защитников против надвигающейся угрозы Плети в северных королевствах."}},faq={{q="Что такое Соборная площадь?",a="Соборная площадь — крупный квартал Штормграда с центром в Соборе Света. Это одновременно духовный центр для служителей Света и важный общественный центр, где находятся ратуша, местный приют и различные лавки.",al={"cathedral district","holy district","what is this place","соборный квартал","священный квартал","что это за место"}},{q="Кто обучается на Соборной площади?",a="Жрецы и паладины Альянса приходят на Соборную площадь и в Собор Света, чтобы совершенствовать свои умения и изучать священные учения. Здесь же медики и сиделки учатся у учителей первой помощи.",al={"class trainers here","who trains here","paladin priest trainers","учителя классов здесь","кто здесь учит","учителя паладинов и жрецов"}},{q="Почему здесь расположен Серебряный Рассвет?",a="Серебряный Рассвет держит на Соборной площади видное представительство, чтобы набирать способных защитников и координировать материальную поддержку из Штормграда для своего неустанного похода против Плети в Чумных землях.",al={"argent dawn stormwind","argent dawn presence","серебряный рассвет штормград","присутствие серебряного рассвета"}},{q="Куда ведет Соборная площадь?",a="Мосты и тропы вдоль каналов соединяют Соборную площадь с оживленным Торговым кварталом на юго-востоке, промышленным Кварталом Дворфов на северо-западе и тихими садами Парка на юго-западе.",al={"connected districts","where does this go","соседние кварталы","куда это ведет"}}},fp="16,300,17.492.0,26.571.0,25.241.0,31.201.0,36.216.0,33.205.0"}
P.entries["subzone:cauldron"] = {n="Котлован",s="Котлован — огромный открытый карьер в центре Тлеющего ущелья. Этим пылающим карьером управляет клан Черного Железа: день и ночь здесь трудятся сломленные рабы под надзором жестоких надсмотрщиков и бродящих элементалей.",h="Котлован — огромный открытый карьер в центре Тлеющего ущелья.",kw={"cauldron","dark iron","excavation","magma elementals","quarry","searing gorge","slave workers","slaves","котлован","черное железо","раскопки","элементали магмы","карьер","тлеющее ущелье","рабы-работники","рабы"},ang={["profession:Mining"]="Огромные механические землечерпалки и террасы открытого карьера Котлована показывают промышленный размах раскопок Черного Железа, врезанных прямо в нестабильную вулканическую кору.",["race:Dwarf"]="Видя безнравственность дворфов Черного Железа, которые используют разумных пленников как расходный, сломленный рабочий скот среди огненных элементалей, дворфы Стальгорна испытывают глубокое отвращение."},sec={{t="Расплавленный карьер",b="Котлован, глубоко врезанный в выжженную землю Тлеющего ущелья, был укреплен после катастрофического призыва Рагнароса императором Даграном Тауриссаном. Огромные дымящие землеройные машины Черного Железа окружают стены каньона, соскребая породу и руду с тлеющего камня. В его пылающих расщелинах рядом с надсмотрщиками Черного Железа бродят живые огненные элементали и элементали магмы, а из глубин горы непрерывно поднимается подземный жар."},{t="Сломленные работники",b="Глубоко в карьере плененные рабы выносят жестокие бесконечные смены под плетью надсмотрщиков Черного Железа. Сломленные изнурительным трудом, нестерпимой жарой и мучениями, многие из них совершенно обезумели. Они больше не отличают друга от врага и яростно набрасываются на любых чужаков, нарушающих их труд, — даже на тех, кто мог бы дать им шанс на свободу."}},faq={{q="Что такое Котлован?",a="Котлован — огромный открытый рудник и карьер в центре Тлеющего ущелья. Построенный и укрепленный кланом Черного Железа, он служит промышленным центром добычи камня и руды в крайне нестабильных вулканических условиях.",al={"the cauldron lore","what is the cauldron","searing gorge quarry","предания котлована","что такое котлован","карьер тлеющего ущелья"}},{q="Кто управляет раскопками?",a="Весь участок контролирует клан Черного Железа. Он руководит работами с помощью тяжелых экскаваторов и вооруженных надсмотрщиков, жестоко удерживая власть над карьером и его работниками.",al={"who runs the cauldron","cauldron masters","кто управляет котлованом","хозяева котлована"}},{q="Почему рабы нападают на искателей приключений, которые пытаются помочь?",a="Рабы сломлены жестокими мучениями, слепящим жаром и безжалостным изнурением. Доведенные до безумия хозяевами и тяжким существованием, они в своем расстроенном рассудке видят в любой помехе их работе угрозу и нападают на всех поблизости.",al={"why are slaves hostile","slave workers attacking","can you free the slaves","почему рабы враждебны","рабы нападают","можно ли освободить рабов"}},{q="Какие существа обитают в карьере?",a="Помимо надсмотрщиков Черного Железа и их порабощенных работников, в огненных расщелинах Котлована кишат неукротимые огненные элементали и элементали магмы, порожденные вулканической природой ущелья.",al={"cauldron mobs","what is in the cauldron","monsters in cauldron","существа котлована","что в котловане","монстры в котловане"}}},fp="8,243,17.465.0,20.403.0,21.253.0,28.169.0,53.254.0,44.188.0"}
P.entries["subzone:cavern-of-mists"] = {n="Пещера Туманов",s="Пещера Туманов — обширная внешняя прихожая, ведущая в глубины Пещер Стенаний. Ее центральное озеро и висящий туман, питаемые подземными гейзерами, пробивающимися сквозь камень, скрывают странных мутировавших животных, бродящих у самого входа в портал.",h="Пещера Туманов — обширная внешняя прихожая, ведущая в глубины Пещер Стенаний.",kw={"barrens","cavern of mists","geysers","threshadons","trigore the lasher","wailing caverns","степи","пещера туманов","гейзеры","жесткозубы","тригор хлестун","пещеры стенаний"},ang={["class:Druid"]="Искаженные животные, процветающие в густых парах, первыми показывают друидам Кенария, как глубоко общение Наралекса с Изумрудным Сном сбилось с пути.",["faction:Horde"]="Пещера лежит в самом сердце Степей, и истребление хищных зверей, таящихся в этих туманах, крайне важно для защиты торговых путей и застав вокруг Перекрестка."},sec={{t="Порог Кошмара",b="Прежде чем спуститься к самому сердцу Пещер Стенаний, путникам нужно пройти через Пещеру Туманов. В воздухе постоянно висит густой теплый пар, питаемый природными гейзерами, бьющими из пола пещеры в глубокое центральное озеро. Хотя это лишь вход, он далеко не мирный. По уступам и водам бродят стаи ящеров, змей, слизней и полуводных жесткозубов, а также известные звери вроде гидры Тригора Хлестуна. Это дает искателям приключений зловещее представление о неестественном росте, гнездящемся глубже внизу."}},faq={{q="Где находится Пещера Туманов?",a="Пещера Туманов — внешняя система пещер Пещер Стенаний, расположенная к юго-западу от Перекрестка в Степях. Это неинстансовая зона, которую игроки должны пройти, чтобы добраться до самого портала в подземелье.",al={"cavern of mists location","where is cavern of mists","wailing caverns entrance cave","где пещера туманов","расположение пещеры туманов","вход в пещеры стенаний"}},{q="Почему она называется Пещерой Туманов?",a="Действующие гейзеры постоянно бьют из каменного пола, питая центральное озеро и наполняя подземный воздух плотным влажным туманом.",al={"why misty","cavern of mists name origin","почему туманная","происхождение названия пещеры туманов"}},{q="Какие существа здесь обитают?",a="В пещере обитают ящеры, слизни, ветряные змеи, змеи, жабы и жесткозубы в озере, а иногда здесь замечают редкую гидру Тригора Хлестуна.",al={"mobs in cavern of mists","cavern of mists monsters","монстры в пещере туманов","существа пещеры туманов"}},{q="Кто такой Тригор Хлестун?",a="Тригор Хлестун — опасная редкая гидра, которую иногда можно встретить плавающей рядом с жесткозубами в центральном озере пещеры.",al={"trigore","hydra rare wailing caverns","тригор","редкая гидра пещеры стенаний"}}},fp="15,268,30.540.0,29.223.0,37.134.0,25.180.0,26.141.0"}
P.entries["subzone:caverns-of-time"] = {n="Пещеры Времени",s="Пещеры Времени, скрытые в восточных утесах Танариса, — мистическое логово Ноздорму и бронзового драконьего рода. В их извилистых глубинах драконы следят за хрупкими путями времени Азерота и охраняют их от любого вторжения смертных и вмешательства во время.",h="Пещеры Времени, скрытые в восточных утесах Танариса, — мистическое логово Ноздорму и бронзового драконьего...",kw={"anachronos","bronze dragonflight","caverns of time","nozdormu","tanaris","temporal","timeways","анахронос","бронзовый драконий род","пещеры времени","ноздорму","танарис","временной","пути времени"},ang={["class:Mage"]="Временная магия, пропитывающая пещеры, намного превосходит хрономантию смертных и дает смиряющее представление о силах, лежащих за пределами управления тайной магией.",["race:NightElf"]="Кальдораи хорошо помнят древние союзы с Аспектами драконов и считают поручение Ноздорму необходимым для сохранения жизни мира."},sec={{t="Извилистые пути времени",b="Пещеры Времени, глубоко врезанные под пустынные утесы, — средоточие, где сходятся потоки истории. Ноздорму Вневременной и его бронзовый драконий род, наделенные силой титанами на заре мира, служат вечными стражами этих коридоров. Внутри время течет непредсказуемо: сквозь скрытые разломы проскальзывают отблески прошлого и будущего, а реликвии далеких эпох разбросаны по пескам. Великий змей Анахронос охраняет вход, а младшие бронзовые драконы патрулируют извилистый спуск, яростно защищая единственную истинную линию времени."},{t="Сокровищница эпох",b="Помимо того что пещеры — перекресток прошлого и будущего, они служат причудливым хранилищем. За тысячелетия бронзовый драконий род собрал исторические осколки со всего Азерота: древние постройки дворфов, сторожевую башню Лордерона, покои вождей орочьих кланов и доспехи времен первых королей Стромгарда. Но хотя порой путники осмеливаются проскользнуть мимо стражей, чтобы взглянуть на эти чудеса, внутренние врата остаются плотно закрытыми в ожидании дня, когда драконий род сочтет вмешательство смертных необходимым."}},faq={{q="Можно ли сейчас войти в Пещеры Времени?",a="Вы можете пройти по длинному извилистому туннелю в главный зал, но сами исторические порталы остаются запечатанными. Будьте осторожны рядом с драконами, патрулирующими вход: старый бронзовый дракон Анахронос равнодушен к путникам, но его спутники нападут на любого смертного, подошедшего слишком близко.",al={"can i enter caverns of time","how to enter caverns of time","is caverns of time open","можно ли войти в пещеры времени","как попасть в пещеры времени","открыты ли пещеры времени"}},{q="Кто правит Пещерами Времени?",a="Пещеры принадлежат Ноздорму Вневременному, Аспекту драконов, наделенному титанами властью над временем. Повседневная опека и охрана входа часто ложатся на его главного отпрыска Анахроноса и стражей бронзового драконьего рода.",al={"who leads caverns of time","caverns of time boss","who lives in caverns of time","кто руководит пещерами времени","босс пещер времени","кто живет в пещерах времени"}},{q="Почему внутри стоят случайные здания и артефакты?",a="Ноздорму веками каталогизировал и собирал материальные реликвии из всей истории Азерота. По пещерам разбросаны неуместные сокровища, включая целую сторожевую башню Лордерона, дворфийскую архитектуру, постройки орков и оружие давно забытых королевств смертных.",al={"why are there human towers in caverns of time","artifacts in caverns of time","почему в пещерах времени башни людей","артефакты в пещерах времени"}},{q="Какова цель бронзового драконьего рода здесь?",a="Их священный долг, данный титанами, — охранять течение времени и сохранять целостность истории. Они следят за тем, чтобы вмешательство смертных или внешние потрясения не разрушили события, определяющие облик мира.",al={"what do bronze dragons do here","bronze flight purpose","что здесь делают бронзовые драконы","цель бронзового драконьего рода"}}},fp="15,275,20.575.0,15.538.0,46.315.0,35.254.0,52.279.0,52.219.0"}
P.entries["subzone:chamber-of-atonement"] = {n="Палата Искупления",s="Палата Искупления — мрачный входной зал крыла Кладбища в Монастыре Алого ордена. Здесь, под каменными арками с железными цепями, Алый орден подвергает пленных нежить и других мнимых еретиков жестокому допросу и пыткам, прежде чем бросить их останки в двор за ним.",h="Палата Искупления — мрачный входной зал крыла Кладбища в Монастыре Алого ордена.",kw={"chamber of atonement","forlorn cloister","graveyard","interrogator vishas","scarlet monastery","torture","vorrel sengutz","палата искупления","покинутый двор","кладбище","дознаватель вишас","монастырь алого ордена","пытки","воррель сенгутц"},ang={["class:Priest"]="Осквернение священных обетов нигде не заметно так, как здесь, где дознаватели ордена превращают святую дисциплину в физическую бойню и садистские муки.",["race:Undead"]="Палата Искупления олицетворяет вершину жестокости Алого ордена по отношению к вашему народу: здесь пленных Отрекшихся, как Ворреля Сенгутца, систематически пытают за сам факт их существования."},sec={{t="Зал агонии",b="Палата Искупления, служащая порогом Покинутого двора, далеко не убежище мирной молитвы. Алый орден превратил величественный вход в дом боли, оснастив его дыбами, кандалами и горящими жаровнями. Ревностные инквизиторы используют эти орудия, чтобы вырывать признания и мучить пленных, считая мучительную боль единственным достойным покаянием для нечестивых существ. В палате постоянно звучат крики проклятых, а правят там жестокие надсмотрщики, следящие, чтобы вошедшие редко выходили целыми."},{t="Владения дознавателя",b="Палатой заведует Дознаватель Вишас, один из самых садистских мастеров принуждения в Ордене. Вишас с отвратительной гордостью ломает волю каждого, кто пересек границы монастыря. Среди его любимых жертв — пленный Отрекшийся Воррель Сенгутц, который уже много недель терпит муки от рук Вишаса. Жестокость, царящая в этих стенах, доказывает чужакам, что крестовый поход Алого ордена за чистоту выродился в безудержный садизм."}},faq={{q="Для чего используется Палата Искупления?",a="Это крыло допросов и пыток Алого ордена внутри крыла Кладбища в монастыре. Пленных, в основном Отрекшихся и других мнимых врагов, здесь допрашивают, ломают и пытают жестокими орудиями, а затем выбрасывают их тела на кладбище.",al={"chamber purpose","why are there torture devices here","what happens in chamber of atonement","назначение палаты","почему здесь орудия пыток","что происходит в палате искупления"}},{q="Кто управляет этой палатой?",a="Помещением командует Дознаватель Вишас, садистский палач Алого ордена, известный тем, что наслаждается страданиями своих жертв.",al={"who is the boss here","chamber of atonement leader","who runs the torture chamber","кто здесь главный","глава палаты искупления","кто управляет пыточной"}},{q="Куда ведет это помещение?",a="Это крайний зал крыла Кладбища, который ведет прямо в Покинутый двор — кладбище под открытым небом, где обитают павшие рыцари ордена и беспокойные мертвецы.",al={"chamber exits","where does chamber of atonement go","next area after atonement","выходы из палаты","куда ведет палата искупления","следующая зона после палаты искупления"}},{q="Кто здесь содержится в плену?",a="Пленный Отрекшийся по имени Воррель Сенгутц заточен и уже много недель подряд подвергается пыткам Дознавателя Вишаса в этой палате.",al={"who is prisoner here","vorrel sengutz","tortured prisoner","кто здесь пленник","воррель сенгутц","замученный пленник"}}},fp="20,317,15.566.0,25.480.0,42.292.0,26.157.0,26.171.0,31.128.0"}
P.entries["subzone:charred-vale"] = {n="Обугленная долина",s="Обугленная долина — тлеющая долина на юго-западе Когтистых гор, разоренная бездумной вырубкой лесов и машинами Торговой Компании. Когда-то это было процветающее убежище для древней и химер, а теперь здесь бушует пламя, бродят элементали и обитают враждебные гарпии.",h="Обугленная долина — тлеющая долина на юго-западе Когтистых гор, разоренная бездумной вырубкой лесов и...",kw={"blackened ancient","bloodfury","charred vale","chimaera","fire elemental","stonetalon","sun rock retreat","venture company","почерневший древень","кровавая ярость","обугленная долина","химера","элементаль огня","когтистые горы","приют у солнечного камня","торговая компания"},ang={["class:Druid"]="Опустошение здесь служит суровым предостережением о том, что бывает, когда природное равновесие разрушено безудержной жадностью, и делает долину главной целью усилий по восстановлению.",["faction:Horde"]="Действуя из Приюта у Солнечного Камня, силы Орды тесно сотрудничают с союзниками из Круга Кенария, чтобы сдержать неистовство элементалей и отбросить оскверняющие последствия деятельности Торговой Компании."},sec={{t="Выжженный лес",b="Не так давно эта юго-западная котловина была цветущим горным лесом, который охраняли величавые древни и в котором жили местные химеры и гарпии. Его гибель началась с прибытия Торговой Компании. Жадные гоблины вырубили лес подчистую взрывными машинами, осквернив стражей и пробудив неистовых элементалей огня. Хотя древни в конце концов отогнали гоблинов, земля осталась разрушенной, опаленной огнем и оскверненной тем, какие мерзкие устройства оставили отступающие лесорубы."},{t="Борьба за возрождение",b="Сегодня почерневшие древни слепо бродят в дыму и пепле рядом с разъяренными элементалями. Гарпии Кровавой Ярости гнездятся среди обугленных стволов, защищая остатки своей территории. Несмотря на враждебность долины, друиды из Приюта у Солнечного Камня отказываются покидать эти земли: они отправляют путников сеять зачарованные семена и врачевать оскверненных древней, упорно стремясь вернуть выжженную землю к жизни."}},faq={{q="Почему Обугленная долина охвачена огнем?",a="Причиной опустошения стала безжалостная вырубка леса Торговой Компанией. Ее разрушительные машины и хищническая вырубка разгневали изначальных духов земли и выпустили на волю элементалей огня, которые разошлись по всей долине.",al={"why is it burning","who burned charred vale","what happened to charred vale","почему горит","кто сжег обугленную долину","что случилось с обугленной долиной"}},{q="Сможет ли лес Обугленной долины когда-нибудь восстановиться?",a="Друиды-таурены из соседнего Приюта у Солнечного Камня верят, что сможет. Они поручают путникам успокаивать обезумевших древней и сажать зачарованные семена земли среди пепла, надеясь вырастить зеленые ростки из погубленной почвы.",al={"is charred vale healing","druids charred vale","исцеление обугленной долины","друиды обугленная долина"}},{q="Какие существа обитают в Обугленной долине?",a="Котловина кишит враждебными духами огня, почерневшими мстительными древними, обожженными василисками и дикими химерами. Кроме того, ее терзают гарпии Кровавой Ярости.",al={"monsters in charred vale","what lives in charred vale","монстры обугленной долины","кто живет в обугленной долине"}},{q="Как называлась Обугленная долина до пожара?",a="Ее первоначальное название забыто, но задолго до появления гоблинских топоров она славилась как пышный лесной заповедник.",al={"charred vale old name","original name of charred vale","старое название обугленной долины","изначальное название обугленной долины"}}},fp="12,275,19.499.0,20.411.0,32.249.0,48.216.0,40.172.0,50.122.0"}
P.entries["subzone:chill-breeze-valley"] = {n="Долина Промозглого Ветра",s="Долина Промозглого Ветра — суровый заснеженный проход на западе Дун Морога, соединяющий поселение дворфов Каранос с осажденным городом Гномреган. Главная тропа оживленна и хорожена молодыми путниками и беженцами, но в глухих закоулках таятся опасные звери и кровавые логова.",h="Долина Промозглого Ветра — суровый заснеженный проход на западе Дун Морога, соединяющий поселение дворфов...",kw={"caves","chill breeze valley","dun morogh","gnomeregan","kharanos","t-shaped","wendigo","пещеры","долина промозглого ветра","дун морог","гномреган","каранос","t-образная","вендиго"},ang={["race:Dwarf"]="Горцы и молодые дворфы-охотники проверяют свою доблесть, истребляя свирепых вендиго, которые угрожают важному проходу между центральной частью Дун Морога и западным нагорьем.",["race:Gnome"]="Для гномов-беженцев, спасающихся от последствий катастрофы в Гномрегане и бегущих в безопасный Каранос и Стальгорн, первым важным шагом становится выживание на хищных окраинах Долины Промозглого Ветра."},sec={{t="Перекресток снега и когтей",b="Долина Промозглого Ветра образует T-образное ущелье среди гор западного Дун Морога. По главной тропе с востока на запад постоянно идут начинающие дворфы и гномы, направляясь между Караносом и окрестностями Гномрегана. Но свернуть в боковой отрог долины, идущий с севера на юг, — совсем другое дело. Эти сумрачные места, усеянные пятнами крови и растерзанными тушами, скрывают свирепых хищников, прежде всего диких вендиго, обитающих в глубоких ледяных пещерах и нападающих на любого, кто неосторожно забредет на их охотничьи угодья."}},faq={{q="Где находится Долина Промозглого Ветра?",a="Долина Промозглого Ветра расположена на западе Дун Морога, прямо между оживленным горным центром Караносом на востоке и технологическим гномьим городом Гномреганом на западе.",al={"chill breeze valley location","where is chill breeze valley","chill breeze valley map","где долина промозглого ветра","расположение долины промозглого ветра","карта долины промозглого ветра"}},{q="Почему путешествовать по долине так опасно?",a="Хотя главная тропа между Караносом и Гномреганом относительно безопасна и людна, северный и южный отроги долины — охотничьи угодья хищных зверей. Снег там залит кровью и усеян растерзанными тушами, а ведут эти следы к пещерам, где живут злобные, охраняющие свою территорию вендиго.",al={"chill breeze valley monsters","dangers in chill breeze valley","why are there bones here","монстры долины промозглого ветра","опасности долины промозглого ветра","почему здесь кости"}},{q="Какие звери устроили здесь свои логова?",a="В глубине долины обитают свирепые вендиго, в том числе особенно крупные элитные вожаки, которые сделали несколько пещер своими личными логовами.",al={"wendigo in chill breeze valley","what lives in chill breeze valley","вендиго в долине промозглого ветра","кто живет в долине промозглого ветра"}}},fp="19,303,30.543.0,37.192.0,49.302.0,42.178.0"}
P.entries["subzone:chillwind-camp"] = {n="Лагерь Промозглого Ветра",s="Лагерь Промозглого Ветра расположен у южного прохода из Альтеракских гор в Западные Чумные земли. Его удерживает отряд Альянса вместе с Серебряным Рассветом, и он служит последним безопасным плацдармом перед оскверненными руинами Лордерона. Из этого ненадежного форпоста командиры направляют удары по близлежащим оплотам Плети и чумным котлам.",h="Лагерь Промозглого Ветра расположен у южного прохода из Альтеракских гор в Западные Чумные земли.",kw={"alterac mountains","andorhal","argent dawn","ashlam valorfist","cauldrons","chillwind camp","chillwind point","western plaguelands","альтеракские горы","андорал","серебряный рассвет","ашлам смелонрав","котлы","лагерь промозглого ветра","берег промозглого ветра","западные чумные земли"},ang={["class:Paladin"]="Многообещающих паладинов направляет сюда лорд Грейсон Тенелом из Штормграда, чтобы они помогли командиру Смелонраву и обрушили священный гнев Серебряной Длани на ряды нежити.",["faction:Alliance"]="Лагерь Промозглого Ветра — авангард усилий Альянса по возвращению северного Лордерона. Он дает надежное убежище, перелеты на грифонах и боевые приказы против Плети."},sec={{t="На краю порчи",b="Tucked into the rocky pass descending from Chillwind Point, Chillwind Camp is the first line of defense and primary base of operations for Alliance forces pushing into the Western Plaguelands. Though physically separated from the worst of the corruption by the high mountain ridges, the dead chill of the north hangs heavily over the tents and palisades. Under Commander Ashlam Valorfist, a sparse garrison of soldiers, scouts, and Argent Dawn specialists attempts to contain the horrors lingering along the King's Road and gather the intelligence necessary to reclaim Lordaeron's fallen fields."},{t="Война на истощение",b="Не имея постоянной армии для полномасштабного штурма Андорала или некромантской крепости Некроситет, Лагерь Промозглого Ветра во многом полагается на независимых героев и наемников. Операции здесь сводятся к точечным партизанским ударам: сбору разведданных о Культе Проклятых, уничтожению алхимических чумных котлов, отравляющих почву, и защите путей снабжения до восточных застав вроде Часовни Последней Надежды. Плеть занимает руины к северу, а Отрекшиеся укрепляют западную границу, и защитникам лагеря остается лишь не дать проходу быть захваченным."}},faq={{q="Для чего нужен Лагерь Промозглого Ветра?",a="Лагерь Промозглого Ветра — главный южный оплот Альянса и Серебряного Рассвета на границе Западных Чумных земель. Он служит надежной базой для партизанских атак на Плеть в Андорале и уничтожения чумных котлов в регионе.",al={"why is chillwind camp here","purpose of chillwind","what is chillwind camp","зачем нужен лагерь промозглого ветра","назначение лагеря промозглого ветра","что такое лагерь промозглого ветра"}},{q="Как добраться до Лагеря Промозглого Ветра из Южнобережья?",a="Из Южнобережья в Предгорьях Хилсбрада идите на север по дороге, на перекрестке поверните на восток и следуйте вдоль реки на север, к горному проходу Альтерака. Если пройти на запад через высокое ущелье, вы выйдете к Берегу Промозглого Ветра и спуститесь прямо в лагерь.",al={"how to get to chillwind camp","directions to chillwind","path to chillwind","как добраться до лагеря промозглого ветра","дорога к лагерю промозглого ветра","путь к лагерю промозглого ветра"}},{q="Что является аналогом этого форпоста у Орды?",a="Аналог Орды — Бастион, расположенный на западной границе между Тирисфальскими лесами и Западными Чумными землями. Оба форпоста служат укрепленными плацдармами для походов против местной Плети.",al={"horde chillwind camp","horde version of chillwind","is there a horde chillwind","лагерь промозглого ветра орды","версия орды лагеря промозглого ветра","есть ли лагерь у орды"}},{q="Кто командует силами Лагеря Промозглого Ветра?",a="Гарнизоном Лагеря Промозглого Ветра руководит командир Ашлам Смелонрав, координируя добровольцев Альянса, Рыцарей Серебряной Длани и представителей Серебряного Рассвета в операциях среди окрестных руин и оскверненных ферм.",al={"chillwind camp leader","who is in charge of chillwind camp","commander of chillwind","командир лагеря промозглого ветра","кто главный в лагере промозглого ветра","командир лагеря"}}},fp="14,373,22.595.0,18.620.0,38.269.0,48.271.0,45.221.0,42.213.0"}
P.entries["subzone:chillwind-point"] = {kw={"alterac","bath'rah","chillwind","chillwind point","hillsbrad","plaguelands","troll ruins","windwatcher","альтерак","бат'ра","промозглый ветер","берег промозглого ветра","хилсбрад","чумные земли","руины троллей","ветростраж"},ang={["class:Shaman"]="Дикие, сжатые в узком проходе порывы ветра делают Берег Промозглого Ветра местом средоточия стихий и привлекают тех, кто хочет учиться у отшельника Бат'ры Ветростража.",["faction:Alliance"]="Эти древние руины к югу от пограничного поста Лагеря Промозглого Ветра отмечают переход между спорными предгорьями и жуткими землями Чумных земель."},sec={{t="Горький перекресток",b="Perched on the borderlands where Hillsbrad gives way to Alterac and the plagued north, Chillwind Point looks out over the mountain ravine leading directly into the Western Plaguelands. Long before Lordaeron claimed these passes, ancient trolls built stone structures upon these heights, the remnants of which still stand weather-beaten against the elements. Today, cold winds blow south through the ravine, carrying the chill of the fallen north into the foothill valleys below."},{t="Ветростраж",b="Несмотря на суровую открытость и близость к землям, опустошенным Плетью, Берег Промозглого Ветра не совсем безлюден. Древняя кладка дает приют Бат'ру Ветростражу, троллю-отшельнику из джунглей, который общается с яростными ветрами, несущимися через ущелье. Путники и шаманы, идущие на север, часто ищут его уединенный лагерь среди руин, чтобы узнать тайны горных течений."}},faq={{q="Что такое Берег Промозглого Ветра?",a="Берег Промозглого Ветра — древние руины троллей на высоком возвышении над проходом между Хилсбрадом, Альтераком и Западными Чумными землями. Свое название он получил от пронизывающих сквозняков, постоянно свистящих в соседнем ущелье.",al={"chillwind point overview","where is chillwind point","what is this place","обзор берега промозглого ветра","где берег промозглого ветра","что это за место"}},{q="Берег Промозглого Ветра и Лагерь Промозглого Ветра — это одно и то же?",a="Нет, хотя их часто путают. Лагерь Промозглого Ветра — укрепленный форпост Альянса и Серебряного Рассвета чуть севернее, за границей, в Западных Чумных землях, а Берег Промозглого Ветра — руины троллей на возвышении немного южнее.",al={"chillwind point vs camp","chillwind camp difference","is this chillwind camp","берег промозглого ветра или лагерь","разница с лагерем промозглого ветра","это лагерь промозглого ветра"}},{q="Кто живет на Берегу Промозглого Ветра?",a="Единственный обитатель руин — Бат'ра Ветростраж, дружелюбный тролль из джунглей, изучающий ветра и помогающий искателям стихий и шаманам, отважившимся пройти через горный перевал.",al={"who is here","who is the troll","bathrah","кто здесь","кто этот тролль","бат'ра"}},{q="Почему здесь так холодно?",a="Берег находится вплотную к узкому горному ущелью, которое направляет ледяные сквозняки с высоких северных областей и оскверненных просторов Западных Чумных земель вниз, в нижние предгорья.",al={"why is it chilly","chill winds","freezing wind","почему холодно","промозглые ветра","ледяной ветер"}}},fp="15,354,19.478.0,15.392.0,24.235.0,46.238.0,29.177.0,23.203.0"}
P.entries["subzone:circle-of-aquementas"] = {n="Круг Аквементаса",s="Круг Аквементаса — загадочное кольцо вертикально стоящих камней на восточном побережье Танариса, к югу от Бухты Сорванных Парусов. Это место ритуалов, где путники могут призвать духа стихии Аквементаса.",h="Круг Аквементаса — загадочное кольцо вертикально стоящих камней на восточном побережье Танариса, к югу от...",kw={"aquementas","circle of aquementas","elemental","lost rigger cove","standing stones","tanaris","аквементас","круг аквементаса","элементаль","бухта сорванных парусов","стоячие камни","танарис"},ang={["class:Shaman"]="Способность круга концентрировать первозданную энергию и удерживать духа стихии делает его любопытным местом для любого шамана, бродящего по побережью Танариса."},sec={{t="Кольцо у моря",b="Круг Аквементаса, укрытый на продуваемом ветрами восточном побережье Танариса, тихо стоит к югу от пиратского оплота в Бухте Сорванных Парусов. Выветренные вертикальные камни, расставленные кольцом, гудят энергией стихий на фоне пустынного берега. Он служит средоточием для призыва Аквементаса, существа стихий, связанного с древним артефактом. Хотя окрестные пляжи кишат разбойниками Южных морей и бродячими морскими тварями, сам круг остается торжественным островком ритуальной силы среди дюн."}},faq={{q="Что такое Круг Аквементаса?",a="Это круговое расположение вертикально стоящих камней на юго-восточном побережье Танариса, служащее для призыва существа стихий Аквементаса.",al={"what is this stone ring","circle of aquementas purpose","standing stones tanaris","что это за каменное кольцо","назначение круга аквементаса","стоячие камни танарис"}},{q="Где находится круг?",a="Круг лежит на восточном берегу Танариса, прямо к югу от утесов и входа в Бухту Сорванных Парусов.",al={"where is circle of aquementas","how to find circle of aquementas","circle of aquementas location","где круг аквементаса","как найти круг аквементаса","расположение круга аквементаса"}},{q="Кто такой Аквементас?",a="Аквементас — дух стихии, связанный с древней цепочкой заданий о странных артефактах; его призывают прямо в круг камней.",al={"who is aquementas","aquementas lore","кто такой аквементас","предания об аквементасе"}},{q="Охраняют ли круг пираты?",a="Хотя пираты Южных морей бродят неподалеку от Бухты Сорванных Парусов и по окрестному берегу, сам круг — в основном уединенное место для призыва.",al={"are there pirates here","southsea pirates near circle","есть ли здесь пираты","пираты южных морей у круга"}}},fp="20,246,17.546.0,33.154.0,28.119.0,18.139.0,33.146.0"}
P.entries["subzone:circle-of-east-binding"] = {n="Восточный круг Обуздания",kw={"arathi highlands","circle of east binding","cresting exile","cresting goliath","cresting guardian","elementals","hammerfall","stone of east binding","нагорье арати","восточный круг обуздания","изгнанник прибоя","голиаф прибоя","страж прибоя","элементали","павший молот","камень восточного обуздания"},ang={["class:Shaman"]="Камни Обуздания в Арати — грубые или древние методы подавления стихий, резко контрастирующие со стремлением шамана к равновесию стихий и единению с ними.",["faction:Horde"]="Беспокойные водные духи вокруг круга, расположенного недалеко от Павшего Молота, постоянно досаждают патрулям и обозам Орды в этих землях."},sec={{t="Восточный оплот",b="Восточный круг Обуздания, расположенный среди суровых нагорий к востоку от Стромгарда, — одно из нескольких древних мест силы, разбросанных по котловине Арати. В его центре стоит Камень Восточного Обуздания — загадочный монумент, излучающий мощную магию стихий. Вихрящиеся водные элементали, известные как изгнанники прибоя, бродят по окрестной земле и яростно защищают камень от любых смертных, осмелившихся приблизиться."},{t="Заточение стихий",b="Камни по всему Арати — не просто природные аномалии: это древние обуздывающие обереги, призванные подавлять и удерживать неукротимые силы стихий. Беспокойные водные духи вокруг восточного круга выдают напряжение этих оберегов: существа, привлеченные магией камня или плененные ею, нападают на путников и искателей приключений на соседней дороге к Павшему Молоту."}},faq={{q="Где находится Восточный круг Обуздания?",a="Восточный круг Обуздания находится в восточной части Нагорья Арати, к югу от главной дороги и чуть к юго-западу от лагеря Орды Павший Молот.",al={"east binding location","where is circle of east binding","circle of east binding map","где восточный круг обуздания","восточный круг обуздания расположение","восточный круг обуздания карта","камень восточного обуздания"}},{q="Какие существа здесь обитают?",a="Круг наводнили агрессивные водные элементали — изгнанники прибоя, неустанно охраняющие Камень Восточного Обуздания.",al={"east binding mobs","what monsters are at east binding","cresting exiles","монстры восточного обуздания","какие монстры у восточного круга","изгнанники прибоя"}},{q="Почему в нагорье водные элементали?",a="Камни, разбросанные по Арати, служат древними оковами для стихий. Присутствие здесь водных элементалей говорит о том, что через камень восточного оплота удерживается или притягивается водная энергия стихий.",al={"why water elementals arathi","east binding elemental lore","почему водные элементали в арати","элементали восточного обуздания","предания восточного круга"}},{q="Для чего нужен Камень Восточного Обуздания?",a="Камень Восточного Обуздания входит в единую сеть камней Обуздания по всему Нагорью Арати, созданную, чтобы закреплять, направлять и запирать неукротимых элементалей.",al={"stone of east binding purpose","what does east binding stone do","назначение камня восточного обуздания","что делает камень восточного обуздания"}}},fp="22,286,16.417.0,22.389.0,44.169.0,30.124.0,48.219.0,49.180.0"}
P.entries["subzone:circle-of-inner-binding"] = {n="Внутренний Круг Обуздания",s="Внутренний Круг Обуздания — древнее кольцо ритуальных камней в южных холмах Нагорья Арати, к востоку от Крепости Стромгард. Круг охраняют враждебные элементали земли; здесь находится Камень Внутреннего Обуздания — самая мощная печать, удерживающая пленную принцессу стихий Мизраэль глубоко под землей.",h="Внутренний Круг Обуздания — древнее кольцо ритуальных камней в южных холмах Нагорья Арати, к востоку от...",kw={"arathi highlands","circle of inner binding","earth elementals","myzrael","rumbling exile","stone of inner binding","stromgarde keep","нагорье арати","внутренний круг обуздания","элементали земли","мизраэль","грохочущий изгнанник","камень внутреннего обуздания","крепость стромгард"},ang={["class:Mage"]="Геометрическое расположение камней образует сложное, долговечное поле удержания, способное направлять и закреплять огромное подземное магическое давление.",["class:Shaman"]="Необузданная энергия земли во Внутреннем Круге Обуздания говорит о древних, прочных узах стихий, но неестественное волнение местных духов земли предупреждает о порче под почвой."},sec={{t="Главная печать",b="Внутренний Круг Обуздания, расположенный на плато к югу от главной дороги, удерживает сильнейший из древних оберегов, запечатывающих Мизраэль под Арати. Высокие плиты окружают центральный Камень Внутреннего Обуздания, гудящий плотной геомагической силой. Огромные грохочущие элементали земли неустанно обходят камни — их влечет резонанс места, или они связаны как стражи. Несмотря на эти мощные обереги, трещины во внутренней печати позволяют пленнице под Нагорьем телепатически тянуться к людям и шептать мольбы о свободе ничего не подозревающим странникам, берущим в руки осколки ее камня."}},faq={{q="Для чего нужен Внутренний Круг Обуздания?",a="В Круге находится Камень Внутреннего Обуздания — главный и сильнейший оберег, удерживающий подземную тюрьму Мизраэль. Он действует вместе с другими кругами стихий по всему Нагорью Арати, не давая существу вырваться на поверхность.",al={"why is this circle here","what does the inner binding do","circle of inner binding lore","зачем здесь круг","что делает внутренний круг обуздания","предания внутреннего круга обуздания"}},{q="Какие существа охраняют этот круг?",a="Круг тщательно охраняют могучие элементали земли, главным образом грохочущие изгнанники. Эти каменные исполины яростно нападают на всех, кто приближается к ритуальным камням.",al={"what enemies are here","inner binding mobs","rumbling exile","какие враги здесь","монстры внутреннего обуздания","грохочущий изгнанник"}},{q="Кто шепчет через камень?",a="Голос, доносящийся через осколок Обуздания, принадлежит Мизраэль — древней и могущественной принцессе стихий, заточенной глубоко под землей. Ее разум сумел пробиться сквозь треснувшую печать и достичь умов смертных.",al={"who talks to you here","myzrael voice","whispering stone","кто здесь говорит","голос мизраэль","шепчущий камень"}},{q="Где находится Внутренний Круг Обуздания?",a="Он находится в южной части Нагорья Арати, на возвышенном гребне к востоку от разрушенной цитадели — Крепости Стромгард.",al={"inner binding location","where is circle of inner binding","how to find inner binding","где внутренний круг обуздания","расположение внутреннего круга обуздания","как найти внутренний круг"}}},fp="23,327,13.590.0,51.274.0,33.169.0,36.239.0,45.152.0"}
P.entries["subzone:circle-of-west-binding"] = {n="Западный Круг Обуздания",s="Западный Круг Обуздания — одно из нескольких древних ритуальных мест, разбросанных по Нагорью Арати, близ Стены Торадина. В центре этого магического кольца стоит Камень Западного Обуздания; кольцо наводнили связанные с ним огненные элементали.",h="Западный Круг Обуздания — одно из нескольких древних ритуальных мест, разбросанных по Нагорью Арати, близ...",kw={"arathi highlands","burning exile","circle of west binding","elemental","ruul onestone","stone of west binding","thoradin's wall","нагорье арати","пылающий изгнанник","западный круг обуздания","элементаль","руул одинокий камень","камень западного обуздания","стена торадина"},ang={["class:Mage"]="Камни Обуздания в Арати позволяют магам понять, как древние маги и шаманы закрепляли и усмиряли элементалей иных миров.",["class:Shaman"]="Неукротимое присутствие пылающих изгнанников свидетельствует о сохраняющемся стихийном беспокойстве, связанном с этими древними краеугольными камнями Арати."},sec={{t="Западный краеугольный камень",b="Западный Круг Обуздания, укрытый у суровых склонов близ Стены Торадина, входит в обширную сеть ритуальных мест Нагорья Арати. В его сердце стоит Камень Западного Обуздания — древняя реликвия, связанная с удержанием стихий. Земля кишит пылающими изгнанниками — неукротимыми огненными элементалями, неустанно охраняющими границы, из-за чего любой подход к камню опасен для путников, идущих по западным равнинам."}},faq={{q="Что такое Западный Круг Обуздания?",a="Это древнее ритуальное место в западной части Нагорья Арати, близ Стены Торадина. Здесь находится Камень Западного Обуздания, который яростно охраняют враждебные огненные элементали.",al={"circle of west binding","stone of west binding","west binding circle","западный круг обуздания","камень западного обуздания","круг западного обуздания"}},{q="Почему здесь огненные элементали?",a="Пылающие изгнанники обитают у Камня Западного Обуздания и охраняют его. Это стихийные силы, привлеченные древними магическими средоточиями по всему Нагорью Арати или связанные с ними.",al={"burning exiles arathi","why fire elementals west binding","elementals circle of west binding","пылающие изгнанники арати","почему огненные элементали у западного обуздания","элементали западного круга обуздания"}},{q="Кто такой Руул Одинокий Камень?",a="Руул Одинокий Камень — маг-огр из клана Тяжелый Кулак, бродящий по этому месту; это редкий и опасный громила, а не знаток камня Обуздания.",al={"ruul onestone","ruul","dwarf at west binding","руул одинокий камень","руул","дворф у западного обуздания"}}},fp="22,253,20.472.0,35.174.0,35.173.0,21.132.0"}
P.entries["subzone:clean-zone"] = {n="Чистая зона",s="Чистая зона — укрепленный дезактивационный анклав в разрушенном городе Гномреган, сразу за верхним Залом Шестеренок. Это единственное безопасное место в зараженном радиацией комплексе, где незараженные гномьи силы удерживают позиции против троггов и лепрогномов. Здесь полевые медики, техники и особые машины «Чистер» дают передышку и позволяют собирать вещи среди радиоактивных руин.",h="Чистая зона — укрепленный дезактивационный анклав в разрушенном городе Гномреган, сразу за верхним Залом...",kw={"clean zone","dormitory","gnomeregan","hall of gears","radiation","sparklematic 5200","tink sprocketwhistle","troggs","чистая зона","общежитие","гномреган","зал шестеренок","радиация","чистер 5200","звяк пружиносвист","трогги"},ang={["profession:Engineering"]="Действующие устройства «Чистер 5200» и торговец Звяк Пружиносвист делают этот лагерь важным местом, где в зараженном хламе можно искать редкие схемы и механические детали.",["race:Gnome"]="Для гномов стоять в Чистой зоне — это и мрачное напоминание о падении родного дома, и упрямый маяк надежды, что технологии Гномрегана еще можно отвоевать у троггов."},sec={{t="Бастион среди шлака",b="Хотя большая часть Гномрегана пала жертвой катастрофического выброса радиоактивных отходов, устроенного Меггакрутом, Чистая зона осталась нетронутой. Расположенная между кишащим троггами Общежитием внизу и спорными коридорами Зала Шестеренок наверху, она служит укрепленной передовой базой. Стойкие гномы-защитники, техники и полевые медики день и ночь удерживают баррикады, обеспечивая экспедициям Альянса надежный плацдарм, где можно перегруппироваться, залечить раны и починить механизмы."},{t="Чистер 5200",b="Помимо роли военного оплота, Чистая зона — центр сбора вещей утраченной столицы. Гномьи инженеры установили устройства «Чистер 5200», чтобы химически очищать и отмывать покрытые грязью реликвии, вынесенные из радиоактивных недр города. Техники и торговцы вроде Звяка Пружиносвиста обрабатывают эти добытые шестеренки и безделушки, снаряжая искателей приключений и изучая остаточное токсичное заражение, терзающее глубокие туннели."}},faq={{q="Почему эта область не заражена радиацией, как остальной Гномреган?",a="The Clean Zone houses gnomes who remain unaffected by the radiation that devastated Gnomeregan. The account does not explain exactly why this small area escaped contamination.",al={"why clean zone not irradiated","why safe here","clean zone radiation","почему чистая зона не заражена","почему здесь безопасно","радиация чистая зона"}},{q="Что делают машины «Чистер 5200»?",a="«Чистер 5200» — особые гномьи устройства для стирки и дезактивации. Искатели приключений могут загружать в них покрытые грязью предметы, добытые у троггов и прокаженных, смывая радиоактивную грязь и обнаруживая полезные руды, самоцветы, монеты или инженерные диковинки.",al={"sparklematic 5200","what are sparklematics","clean grime","чистер 5200","что такое чистер","очистка от грязи"}},{q="Кто управляет Чистой зоной и защищает ее?",a="Периметр удерживает особый отряд незараженных гномьих стражей, полевых медиков и техников. Они отражают набеги троггов из Общежития и лепрогномов, спускающихся с верхних уровней, чтобы сохранить пункт сбора в безопасности.",al={"who is in clean zone","clean zone guards","who holds clean zone","кто в чистой зоне","стражи чистой зоны","кто удерживает чистую зону"}},{q="Можно ли здесь безопасно отдохнуть или починить снаряжение?",a="Да. Чистая зона служит действующим полевым лагерем в глубине Гномрегана: здесь есть инженерные материалы, ремонт у торговца Звяка Пружиносвиста и даже работающий почтовый ящик для искателей приключений, действующих за линией фронта.",al={"repairs clean zone","can you rest in clean zone","mailbox in gnomeregan","ремонт чистая зона","можно ли отдохнуть в чистой зоне","почтовый ящик в гномрегане"}}},fp="10,424,21.486.0,21.438.0,59.175.0,42.263.0,40.249.0,39.232.0"}
P.entries["subzone:cleft"] = {n="Расселина",s="Расселина — темная лощина к северо-западу от Доланаара в Тельдрассиле. Когда-то это был тихий уголок ветвей, но теперь его заняли порченые фурболги из племени Седой Сосны, превратившие его в оплот для засад на путников на главной дороге к Дарнассу.",h="Расселина — темная лощина к северо-западу от Доланаара в Тельдрассиле.",kw={"cleft","darnassus","dolanaar","furbolg","gnarlpine","moon priestess amara","расселина","дарнасс","доланаар","фурболг","седая сосна","жрица луны амара"},ang={["class:Druid"]="Порченые фурболги из племени Седой Сосны угрожают безопасности путников на дороге к Дарнассу.",["race:NightElf"]="Для ночных эльфов Расселина — горькая трагедия: они видят, как их давние союзники-фурболги впадают в безумие и нападают на путников."},sec={{t="Логово порчи",b="Расселина, расположенная у дороги между Доланааром и Дарнассом, стала одним из самых опасных логовищ на мировом древе. Обезумев от мерзкой порчи, расползающейся по Тельдрассилу, местные фурболги из племени Седой Сосны укрепили эту лощину. Из этого оплота обезумевшие звери терроризируют окрестные дороги, угрожая отрезать Доланаар от столицы."},{t="Засадники на дороге",b="Угроза, исходящая от Расселины, стала столь серьезной, что жрица Луны Амара и ее часовые были вынуждены выставить оборонительный дозор на дороге у входа в нее. Очистка Расселины необходима Часовым, чтобы обезопасить главную артерию, соединяющую деревни Тельдрассила с Дарнассом."}},faq={{q="Что такое Расселина?",a="Расселина — логово фурболгов в ветвях Тельдрассила, к северо-западу от Доланаара, вдоль главной дороги к Дарнассу.",al={"what is the cleft","the cleft teldrassil","cleft location","что такое расселина","расселина тельдрассил","где расселина"}},{q="Кто контролирует Расселину?",a="Ее занимают враждебные фурболги из племени Седой Сосны, ставшие жертвами ползучей порчи Тельдрассила.",al={"who lives in the cleft","cleft enemies","who rules the cleft","кто живет в расселине","враги расселины","кто правит расселиной"}},{q="Почему здесь сражаются ночные эльфы?",a="Фурболги из племени Седой Сосны в Расселине устраивают засады на путников на дороге к Дарнассу. Жрица Луны Амара и Часовые стремятся сохранить эту дорогу безопасной.",al={"why attack the cleft","cleft night elf quests","road to darnassus","зачем нападать на расселину","задания ночных эльфов расселина","дорога к дарнассу"}},{q="Связана ли Расселина с Расселиной Теней?",a="Нет. Несмотря на сходное название, эта Расселина — пещера фурболгов в Тельдрассиле, а Расселина Теней — темная подземная пещера в столице Орды, Оргриммаре.",al={"cleft of shadow connection","cleft vs cleft of shadow","связь с расселиной теней","расселина и расселина теней"}}},fp="5,265,19.366.0,21.295.1,18.143.0,23.104.0,38.157.0,44.185.0"}
P.entries["subzone:cleft-of-shadow"] = {n="Расселина Теней",s="Расселина Теней, скрытая глубоко в подземных пещерах под Оргриммаром, служит обителью для мастеров скрытности, колдовства и демонологии. Вдали от гордого воинского духа верхних районов Тралла она остается необходимым убежищем для разбойников, чернокнижников и магов, действующих в тени Орды.",h="Расселина Теней, скрытая глубоко в подземных пещерах под Оргриммаром, служит обителью для мастеров...",kw={"arcane enclave","cleft of shadow","darkfire enclave","mage","orgrimmar","ragefire chasm","rogue","shadowswift brotherhood","warlock","тайный анклав","расселина теней","анклав темного огня","маг","оргриммар","огненная пропасть","разбойник","братство теневой стремительности","чернокнижник"},ang={["class:Rogue"]="Братство Теневой Стремительности собирается здесь вместе с торговцами ядами и взломщиками замков, превращая этот темный закуток в главное логово лазутчиков Орды.",["class:Warlock"]="Анклав Темного Огня дарует чернокнижникам Орды законное место, где можно призывать демонов и подчинять энергию Скверны под Оргриммаром, не вызывая немедленного гнева шаманов и воинов."},sec={{t="Подземное убежище",b="Хотя новая Орда Тралла чтит честь, шаманизм и силу оружия, практичное руководство требует места для более тонких искусств. Расселина Теней, высеченная в сырых каменных пещерах под столицей, вмещает Братство Теневой Стремительности разбойников, Анклав Темного Огня чернокнижников и ученых Тайного анклава. Этот темный квартал, удаленный от повседневной суеты районов долины, позволяет мастерам ядов, энергии Скверны и тайной магии заниматься своим ремеслом вдали от посторонних глаз, оставаясь под надзором руководства Оргриммара."},{t="Опасный порог",b="Помимо роли центра тайного обучения и источника магических реагентов, Расселина Теней напрямую ведет в Огненную пропасть. Эта огненная сеть вулканических пещер пронизывает землю под самим Оргриммаром и постоянно угрожает безопасности, привлекая к краю пещеры и отважных защитников, и зловещих сектантов."}},faq={{q="Почему чернокнижников и разбойников держат здесь, под землей?",a="Тралл стремится сохранить единство Орды на основе почетных традиций шаманов и воинов. Пользу чернокнижников и разбойников признают, но их методам не доверяет большая часть орков. Содержание их в подземных пещерах позволяет держать опасную магию Скверны и незаконные дела под сдерживанием и надзором.",al={"why cleft of shadow","why warlocks underground orgrimmar","cleft of shadow lore","почему расселина теней","почему чернокнижники под землей оргриммар","предания расселины теней"}},{q="Какие основные учителя и услуги есть в Расселине Теней?",a="Пещера служит главным центром Оргриммара для учителей разбойников, чернокнижников и магов. Здесь также есть поставщики ядов, торговцы реагентами и продавцы волшебных палочек и посохов.",al={"trainers in cleft of shadow","who is in cleft of shadow","учителя в расселине теней","кто в расселине теней"}},{q="Что за вход на дне пещеры?",a="Пропасть, уходящая в пол пещеры, ведет в Огненную пропасть — опасную подземную сеть лавовых туннелей под Оргриммаром, где кишат трогги, пылающие элементали и отступники-сектанты.",al={"dungeon in cleft of shadow","cleft cave entrance","what instance is here","подземелье в расселине теней","вход в пещеру расселины","какой тут инстанс"}}},fp="15,315,24.573.0,21.326.0,50.318.0,69.162.0,49.191.0"}
P.entries["subzone:cliffspring-falls"] = {n="Водопад Скалистый",s="Водопад Скалистый — драматичное начало важной для Темных берегов Реки Скалистой, что низвергается с восточных утесов в прибрежный лес. Долгое время он считался главным источником чистой питьевой воды в регионе, но недавно его воды заразила мерзкая, расползающаяся порча. Подземную пещеру, питающую водопад, наводнили враждебные наги и темные сектанты Сумеречного Молота.",h="Водопад Скалистый — драматичное начало важной для Темных берегов Реки Скалистой, что низвергается с восточных...",kw={"auberdine","cliffspring falls","cliffspring river","cliffwater falls","darkshore","felwood","naga","twilight's hammer","water corruption","аубердин","водопад скалистый","река скалистая","темные берега","оскверненный лес","наги","сумеречный молот","порча воды"},ang={["class:Druid"]="Друиды Круга Кенария пристально следят за рекой, стараясь выявить и исцелить неестественную гниль, грозящую задушить дикую природу.",["race:NightElf"]="Для кальдораев Аубердина порча Водопада Скалистого — экологический и духовный кризис: она оскверняет жизненно важные воды, питающие древние леса Темных берегов."},sec={{t="Оскверненный источник",b="Водопад Скалистый изливается из пещер высоко в скалистых обрывах на восточной границе Темных берегов и питает Реку Скалистую, что течет на запад через лес и впадает в море. Издавна этот поток давал самую чистую питьевую воду для поселений ночных эльфов. Но недавно вода стала мутной и гнилой, принося болезни и экологический упадок всему бассейну реки. Исследователи-натуралисты обнаружили, что пещеры у истоков водопада захвачены мерзкими нагами и темными сектантами, которые плетут заговоры во мраке, пока демоническая порча из соседнего Оскверненного леса грозит просочиться сквозь горную породу."}},faq={{q="Что такое Водопад Скалистый?",a="Водопад Скалистый — большой водопад на востоке Темных берегов, образующий исток Реки Скалистой. Исторически он снабжал окрестный лес основной пресной питьевой водой.",al={"cliffspring falls","cliffwater falls","what is cliffspring falls","водопад скалистый","что такое водопад скалистый"}},{q="Почему вода, текущая из Водопада Скалистого, оскверненная?",a="Подозревают два зловещих влияния: демоническую порчу, просачивающуюся сквозь горы из Оскверненного леса, и присутствие сектантов Сумеречного Молота и враждебных наг в пещерах, питающих водопад.",al={"why is water tainted","cliffspring river corruption","corrupted water","почему вода испорчена","порча реки скалистой","оскверненная вода"}},{q="Кто обитает в пещерах за водопадом?",a="Пещеры над водопадом и за ним кишат враждебными нагами, скользящими по затопленным залам, а также сектантами апокалиптического Сумеречного Молота.",al={"who is in the caves","cliffspring cave mobs","who lives in cliffspring falls","кто в пещерах","монстры пещер водопада скалистого","кто живет в водопаде скалистом"}},{q="Почему Водопад Скалистый так важен для Темных берегов?",a="Река Скалистая пересекает центр северных Темных берегов. Поскольку она — главный источник пресной воды, ее отравление напрямую угрожает животным, древним рощам и жилищам ночных эльфов.",al={"why does darkshore care","cliffspring importance","почему важен водопад","значение водопада скалистого"}}},fp="17,417,16.682.0,26.197.0,49.225.0,42.181.0,51.218.0"}
P.entries["subzone:clockwerk-run"] = {n="Заводной тоннель",s="Заводной тоннель — главный входной коридор в сердце павшего Гномрегана. Этот поврежденный проход между Депо и Залом Шестеренок сильно заражен ядовитыми осадками и наводнен облученными троггами.",h="Заводной тоннель — главный входной коридор в сердце павшего Гномрегана.",kw={"clockwerk run","gnomeregan","hall of gears","irradiated troggs","train depot","troggs","заводной тоннель","гномреган","зал шестеренок","облученные трогги","депо","трогги"},ang={["profession:Engineering"]="Разрушенные механизмы и обвалившиеся конструкции вдоль тоннеля мрачно показывают, что бывает, когда гномьи промышленные механизмы подвергаются катастрофическим взрывам и радиации.",["race:Gnome"]="Путь через Заводной тоннель — горькое напоминание о падении столицы: он воочию показывает, как отчаянная попытка очистить город превратила захватчиков в мутантов вместо того, чтобы уничтожить их."},sec={{t="Разрушенный порог",b="Заводной тоннель, главные врата в Гномреган от внешнего депо, когда-то был оживленной артерией гномьей логистики и перевозок. Когда главный механик Меггакрут приказал выпустить радиоактивные отходы, чтобы остановить нашествие троггов, коридор стал смертельной ловушкой. Взрыв и последовавшие бои обрушили части прохода. Сегодня он забит ядовитыми испарениями и облученными троггами, и любой отряд должен с боем пройти этот опасный рубеж, чтобы добраться до верхнего Зала Шестеренок."}},faq={{q="Куда ведет Заводной тоннель?",a="Заводной тоннель соединяет Депо за пределами глубоких хранилищ с верхними уровнями Зала Шестеренок внутри Гномрегана.",al={"clockwerk run location","where does this hallway go","clockwerk run entrance","где заводной тоннель","куда ведет этот коридор","вход в заводной тоннель"}},{q="Почему здесь так много троггов?",a="Подземные трогги хлынули вверх через нижние ходы Гномрегана во время первого вторжения. Те, что бродят по Заводному тоннелю, впитали большие дозы выпущенных радиоактивных отходов и превратились в свирепых облученных троггов, нападающих на всякого, кто пытается войти в город.",al={"why troggs","clockwerk run enemies","почему трогги","враги заводного тоннеля"}},{q="Почему коридор частично обрушен?",a="Ожесточенные бои во время падения Гномрегана и катастрофический выброс ядовитых средств защиты нанесли тяжелый ущерб конструкциям по всему периметру, и коридор частично обрушился.",al={"clockwerk run collapsed","why is it broken","заводной тоннель обрушен","почему он разрушен"}}},fp="13,248,18.561.0,34.135.0,34.272.0,39.217.0"}
P.entries["subzone:cold-hearth-manor"] = {n="Поместье \"Остывший Очаг\"",s="Поместье «Остывший Очаг» — зараженная ферма к западу от Брилла у главной дороги Тирисфальских лесов. Когда-то это было оживленное гостеприимное имение, известное богатыми урожаями, но вспышка Чумы нежизни истребила его обитателей, и окрестные поля наводнила безмозглая Плеть. Сегодня Отрекшиеся превратили главный дом в форпост и перевалочный пункт для путников.",h="Поместье «Остывший Очаг» — зараженная ферма к западу от Брилла у главной дороги Тирисфальских лесов.",kw={"brill","cold hearth manor","farmstead","forsaken","scourge","tirisfal glades","zombies","брилл","поместье остывший очаг","ферма","отрекшиеся","плеть","тирисфальские леса","зомби"},ang={["faction:Horde"]="Поместье предоставляет надежный наблюдательный пункт на дороге между Бриллом и восточными окраинами Тирисфаля и служит безопасной остановкой для путников в зараженной округе.",["race:Undead"]="Для Отрекшихся возвращение таких мест, как поместье «Остывший Очаг», — горькое напоминание об утраченной смертной жизни: прежние человеческие убежища они превращают в мрачные оборонительные форпосты против Плети и Алого ордена."},sec={{t="Остывший очаг",b="До Третьей войны эта усадьба славилась теплом и гостеприимством и давала богатые урожаи в сердце Лордерона. Когда Чума прокатилась по королевству, вся семья и работники погибли и восстали оболочками, связанными с Плетью. Хотя дикая нежить все еще бродит по разоренным полям, силы Отрекшихся выбили безмозглых мертвецов из главного дома и заняли его под торговый пост и опорный пункт на дороге к восточным лесам."}},faq={{q="Что случилось с людьми, жившими здесь?",a="Фермеры и работники, ухаживавшие за имением, были полностью истреблены, когда Чума нежизни охватила Лордерон. Вместо покоя в смерти они восстали безмозглыми зомби, до сих пор бродящими по окрестным полям.",al={"who lived at cold hearth","manor backstory","what happened to the family","кто жил в остывшем очаге","история поместья","что случилось с семьей"}},{q="Почему поместье называется «Остывший Очаг»?",a="Изначально имение славилось теплой атмосферой и гостеприимными каминами. Мрачное название, вероятно, дали Отрекшиеся как ироничный отсыл к прежней жизни, подчеркивающий, насколько холодной, мертвой и зараженной стала ферма.",al={"cold hearth name meaning","why cold hearth","значение названия остывший очаг","почему остывший очаг"}},{q="Кто сейчас контролирует поместье?",a="Отрекшиеся захватили главный дом и используют его как безопасную остановку для путников и торговцев на дороге от Брилла. Однако открытые поля и амбары вокруг поместья по-прежнему кишат враждебной Плетью.",al={"who owns cold hearth manor","is cold hearth friendly","кому принадлежит поместье остывший очаг","дружелюбен ли остывший очаг"}},{q="Почему Отрекшиеся не очистят поля?",a="Силы Отрекшихся в Тирисфальских лесах растянуты: они отбиваются от остатков безмозглой Плети и отражают натиск воинов Алого ордена. Защита дома и главной дороги дает немедленную пользу, а разбросанные по полям мертвецы остаются скорее помехой, чем угрозой Бриллу.",al={"why are there zombies in the fields","why scourge here","почему на полях зомби","почему здесь плеть"}}},fp="17,390,16.513.0,43.236.0,35.230.0,33.229.0,44.297.0"}
P.entries["subzone:coldridge-pass"] = {n="Туннель Холодной долины",s="Туннель Холодной долины — суровый заснеженный туннель, прорезающий южный горный хребет Дун Морога. Это единственный наземный путь, соединяющий уединенную учебную местность Холодной долины с остальным королевством; он выходит недалеко от оживленного города Каранос. Поскольку проход захватили враждебные трогги, всякому путнику приходится либо прорубаться с боем, либо отчаянно мчаться на другую сторону.",h="Туннель Холодной долины — суровый заснеженный туннель, прорезающий южный горный хребет Дун Морога.",kw={"anvilmar","coldridge pass","coldridge valley","dun morogh","kharanos","mountain pass","trogg","tunnel","старая наковальня","туннель холодной долины","холодная долина","дун морог","каранос","горный проход","трогг","туннель"},ang={["race:Dwarf"]="Для дворфов-горцев и новобранцев путь через Туннель Холодной долины означает ваш уход из начального обучения в Старой Наковальне к активной службе в землях Стальгорна.",["race:Gnome"]="Гномы-изгнанники, желающие помочь Альянсу, должны пробиться через это кишащее троггами узкое место, чтобы добраться до Караноса и верхней дороги к Стальгорну."},sec={{t="Выход из долины",b="Для юных дворфийских новобранцев и гномьих новичков, делающих первые шаги за пределами Холодной долины, Туннель Холодной долины — суровое испытание. Прорубленный прямо в скале, этот туннель — главная связь, направляющая новоиспеченных искателей приключений на восток, к приграничному центру Каранос. Некогда безопасный горный коридор стал опасным узким местом, кишащим агрессивными троггами, которые поднялись из темных глубин и угрожают каждому, кто пытается пройти между укрытой долиной и просторами Дун Морога."}},faq={{q="Куда ведет Туннель Холодной долины?",a="Туннель соединяет Холодную долину на юго-западе с остальным Дун Морогом, выходя на заснеженные холмы к западу от города Каранос.",al={"where does coldridge pass go","coldridge pass destination","how to leave coldridge valley","куда ведет туннель холодной долины","выход из туннеля холодной долины","как покинуть холодную долину"}},{q="Почему в Туннеле Холодной долины трогги?",a="Недавно трогги хлынули из глубоких подземных трещин под Дун Морогом и заняли темные пещеры и туннели по всему региону. Туннель Холодной долины дал им укрытие и удобное место для засады на горных путников.",al={"why are troggs here","coldridge pass monsters","trogg infestation","почему здесь трогги","монстры туннеля холодной долины","нашествие троггов"}},{q="Безопасно ли ходить через Туннель Холодной долины?",a="Нет, это небезопасно. Туннель кишит враждебными троггами, поэтому новобранцам и путникам приходится прорубаться сквозь них или мчаться сквозь тьму к противоположному концу.",al={"is coldridge pass dangerous","can i walk through coldridge pass","опасен ли туннель холодной долины","можно ли пройти туннель холодной долины"}},{q="Кто охраняет или обслуживает туннель?",a="Горные пехотинцы следят за выходами из долины и дороги, но внутри туннеля по-прежнему идут бои, и он не очищен, так что путникам приходится защищаться самим.",al={"dwarf guards at coldridge pass","who controls the pass","дворфы стражи туннеля холодной долины","кто контролирует туннель"}}},fp="14,440,29.541.0,31.157.0,39.231.0,41.190.0,33.179.0"}
P.entries["subzone:coldridge-valley"] = {n="Холодная долина",s="Холодная долина — укромная заснеженная лощина на юго-западных возвышенностях Дун Морога. Она раскинулась вокруг деревни Старая Наковальня и служит учебным лагерем, где молодые дворфы и гномы-беженцы впервые берутся за оружие на службе Стальгорна. Единственный туннель, Туннель Холодной долины, соединяет эту уединенную котловину с остальными горными землями.",h="Холодная долина — укромная заснеженная лощина на юго-западных возвышенностях Дун Морога.",kw={"anvilmar","coldridge pass","coldridge valley","dun morogh","frostmane","ironforge","starting area","troggs","старая наковальня","туннель холодной долины","холодная долина","дун морог","мерзлогрив","стальгорн","стартовая зона","трогги"},ang={["race:Dwarf"]="Традиционное место начала пути для горцев и клириков из Бронзобородов, долина — это первые шаги дворфа за пределы родного очага на службу Высокому трону.",["race:Gnome"]="Для изгнанных из Гномрегана гномов снега Холодной долины — безопасное убежище, где они могут овладевать заклинаниями и механизмами рядом со своими хозяевами-дворфами."},sec={{t="Уединенный полигон",b="Окруженная отвесными горными утесами, Холодная долина почти отрезана от оживленных торговых путей Дун Морога. В ее сердце стоит Старая Наковальня — прочный каменный зал и деревня, где опытные наставники-дворфы и гномы-ученые, лишившиеся дома, обучают новобранцев искусству боя, скрытности и магии. За пределами теплых очагов Старой Наковальни дно долины покрыто толстым снегом, а по нему бродят кабаны и голодные зимние волки, давая новичкам первое настоящее знакомство с жизнью на границе."},{t="Наступающие враги",b="Несмотря на изоляцию, Холодной долине сразу угрожают два неутомимых врага. Местные тролли Мерзлогривы устроили лагеря, например Пещеру Мерзлогривов, где сражаются с горцами и защищают свои исконные владения от вторжения дворфов. Еще хуже то, что свирепые трогги Каменной Челюсти захватили Туннель Холодной долины — природный проход, соединяющий долину с Караносом. Пока эти подземные твари не отброшены, путники и припасы не могут свободно перемещаться между долиной и Высоким троном Стальгорна."}},faq={{q="Как покинуть Холодную долину?",a="Единственный наземный путь из долины ведет через Туннель Холодной долины — заснеженный проход, пересекающий горный хребет на северо-восток. За туннелем дорога идет на восток прямо к городу Каранос, а затем к великим вратам Стальгорна.",al={"exit coldridge","how to get out","path to kharanos","выход из холодной долины","как выбраться","путь в каранос"}},{q="Почему здесь начинают и гномы, и дворфы?",a="После трагического падения Гномрегана под натиском троггов и радиоактивных осадков уцелевшие гномы бежали в Дун Морог как беженцы. Народ главного механика Меггакрута радушно принял король Магни Бронзобород, и многие изгнанные гномы-ученики стали обучаться бок о бок с молодыми дворфами в Старой Наковальне.",al={"gnomes in coldridge","why are gnomes here","gnome starting area","гномы в холодной долине","почему здесь гномы","стартовая зона гномов"}},{q="Какие угрозы тревожат долину?",a="Долине угрожают две главные опасности: враждебные тролли Мерзлогривы, которые возмущены поселениями дворфов на их горной земле, и грубые трогги Каменной Челюсти, выбравшиеся из глубин земли и перекрывшие Туннель Холодной долины. Местные хищники, такие как волки и кабаны, тоже донимают неосторожных путников.",al={"coldridge enemies","valley threats","who is attacking","враги холодной долины","угрозы долины","кто нападает"}},{q="Что такое Старая Наковальня?",a="Старая Наковальня — центральная крепость-приют и поселение в Холодной долине. Здесь находятся наставники классов, мастера кузни и местные офицеры-горцы, которые руководят обороной долины и готовят новоиспеченных искателей приключений к большому миру.",al={"anvilmar town","what is the town here","старая наковальня","что за поселение здесь"}}},fp="16,350,25.508.0,16.522.0,34.256.0,47.293.0,38.283.0,17.249.0"}
P.entries["subzone:corin-s-crossing"] = {n="Перекресток Корина",s="Перекресток Корина — разрушенное человеческое поселение на важном перекрестке в юго-центральной части Восточных Чумных земель. Некогда процветавшая почтовая станция между Стратхольмом, Длань Тира, Дарроуширом и Андоралом, разоренный город теперь полностью захвачен Плетью. В его рушащейся ратуше и кузнице таятся ужасы, в том числе невидимые призрачные стражи.",h="Перекресток Корина — разрушенное человеческое поселение на важном перекрестке в юго-центральной части...",kw={"corin's crossing","corins crossing","eastern plaguelands","infectis scar","lake mereldar","unseen servants","перекресток корина","восточные чумные земли","чумной овраг","озеро мерельдар","невидимые слуги"},ang={["class:Paladin"]="Руины Перекрестка Корина олицетворяют полное осквернение сердца Лордерона и остаются жалким оплотом Плети, глумящимся над священным бастионом Стратхольмом дальше по дороге.",["class:Rogue"]="Не доверяйте здесь своим теням. Невидимые слуги бродят по переулкам, недоступные смертному взгляду, и видят вашу скрытность насквозь, так что неспешная прогулка по городской площади может стать смертельной."},sec={{t="Разрушенный перекресток",b="До Третьей войны Перекресток Корина был важным узлом для путешествий по восточному Лордерону. Лежа между сверкающими водами Озера Мерельдар и ставшим теперь зараженным провалом Чумным оврагом, его дороги некогда несли купцов, гонцов и паломников, идущих между великим оплотом Стратхольмом и южными крепостями. Когда по провинции прокатилась чума, поселение оказалось прямо на пути разрушения и быстро пало под тяжестью авангарда нежити."},{t="Приют Проклятых",b="Сегодня Перекресток Корина полностью потерян для Плети. По грязным улицам бродит нежить, а гниющие громадины и вурдалаки таятся в выпотрошенной кузнице и ратуше. Город особенно опасен для разведчиков: призрачные Невидимые слуги скользят среди руин, недоступные обычному взгляду, пронзая простую скрытность и устраивая засады на всякого, кто пытается незаметно проскользнуть мимо основной орды."}},faq={{q="Чем был Перекресток Корина до чумы?",a="Это был процветающий узловой город в восточном Лордероне. Вокруг ратуши и кузницы он служил остановкой для путников, идущих между Стратхольмом, Длань Тира, Дарроуширом и Андоралом, пока Плеть не уничтожила его население.",al={"corins crossing history","corins crossing lore","what was corins crossing","история перекрестка корина","предания перекрестка корина","чем был перекресток корина"}},{q="Почему Перекресток Корина так опасен для скрытных путников?",a="Город населяют Невидимые слуги — незримые призраки, связанные с Плетью. Эти привидения без труда пронзают магическую и обычную скрытность, застигая врасплох неосторожных разбойников и разведчиков и предупреждая ближайшую нежить.",al={"stealth in corins crossing","unseen servants","rogue corins crossing","скрытность на перекрестке корина","невидимые слуги","разбойник перекресток корина"}},{q="Какие крупные ориентиры окружают город?",a="Перекресток Корина лежит прямо в юго-центральной части Восточных Чумных земель. Рядом находится зараженный овраг Чумной овраг, а по его границе тянется Озеро Мерельдар.",al={"corins crossing location","where is corins crossing","расположение перекрестка корина","где перекресток корина"}},{q="Кто контролирует Перекресток Корина сегодня?",a="Плеть полностью господствует над руинами. Живых защитников в городе не осталось, и все поселение кишит бродячими солдатами-нежитью и духами.",al={"who owns corins crossing","corins crossing faction","кто владеет перекрестком корина","фракция перекрестка корина"}}},fp="16,358,22.539.0,21.419.0,44.228.0,60.222.0,39.180.0,36.169.0"}
P.entries["subzone:corrahn-s-dagger"] = {n="Уступ Коррана",s="Уступ Коррана — второй хребет из четырех горных «пальцев», возвышающихся над северными Предгорьями Хилсбрада. Эта возвышенность служит убежищем для разбойников из Синдиката.",h="Уступ Коррана — второй хребет из четырех горных «пальцев», возвышающихся над северными Предгорьями Хилсбрада.",kw={"corrahn","corrahn's dagger","dagger","four fingers","hillsbrad","syndicate","коррана","уступ коррана","уступ","четыре пальца","хилсбрад","синдикат"},ang={["race:Dwarf"]="Хребет — убежище Синдиката, поэтому путникам-дворфам, пересекающим северные предгорья, следует ожидать скорее бандитов, чем союзников.",["race:Undead"]="Головорезы Синдиката на хребте враждебны Отрекшимся, работающим в Хилсбраде."},sec={{t="Северный опорный пункт",b="Круто поднимаясь на севере Предгорий Хилсбрада, Уступ Коррана — второй из четырех скалистых отрогов, известных местным как пальцы Хилсбрада. Хребет захвачен головорезами Синдиката, которые используют возвышенность, чтобы наблюдать за долиной внизу."}},faq={{q="Кто контролирует Уступ Коррана?",a="Хребтом владеют люди-разбойники из Синдиката, которые держат высоты как убежище.",al={"who is at corrahn's dagger","corrahns dagger faction","who lives here","кто на уступе коррана","фракция уступа коррана","кто здесь живет"}},{q="Что такое пальцы Хилсбрада?",a="Пальцы Хилсбрада — четыре заметных горных хребта в форме пальцев, выступающих на юг от северного горного хребта в долину Хилсбрада. Уступ Коррана — вторая из этих формаций.",al={"four fingers hillsbrad","four ridges hillsbrad","hillsbrad fingers","четыре пальца хилсбрада","четыре хребта хилсбрада","пальцы хилсбрада"}}},fp="16,184,22.271.0,30.86.0,34.205.0"}
P.entries["subzone:craftsmen-s-terrace"] = {n="Терраса Ремесленников",s="Терраса Ремесленников — оживленный квартал мастеров на севере Дарнасса. Это главный торговый и производственный центр столицы ночных эльфов: здесь расположены мастерские, учителя профессий и шумная таверна. В квартале также находятся представительства других сил, включая посольство нейтрального Серебряного Рассвета.",h="Терраса Ремесленников — оживленный квартал мастеров на севере Дарнасса.",kw={"argent dawn","artisans","craftsmen's terrace","craftsmens terrace","darnassus","teldrassil","trainers","серебряный рассвет","ремесленники","терраса ремесленников","дарнасс","тельдрассил","учителя"},ang={["faction:Alliance"]="Представители Альянса считают террасу одним из самых гостеприимных кварталов Дарнасса: здесь есть привычные торговые товары, управление гильдиями и ночлег, а также иноземные представители.",["race:NightElf"]="Для кальдораев терраса — свидетельство самодостаточности их общества на Тельдрассиле: она сочетает древнее мастерство с повседневными нуждами новой столицы."},sec={{t="Ремесленное сердце Дарнасса",b="Терраса Ремесленников раскинулась вдоль северного края города в кронах и объединяет разные ремесла, на которых держится жизнь Дарнасса. Здесь работают плотники, кожевники, алхимики и другие мастера, соединяя традиционные методы ночных эльфов с практичным ремеслом. В квартале есть и необходимые удобства: таверна, гильд-мастер и торговцы хартиями гильдий. Мосты соединяют террасу напрямую с Анклавом Кенария на западе и Террасой Воинов на юге."},{t="Связи с внешним миром и забытые предания",b="Несмотря на давнюю изоляцию кальдораев, на Террасе Ремесленников есть иноземные связи, прежде всего посольство, созданное Серебряным Рассветом для координации действий с северными союзниками против Плети. Гости, осматривающие здешние мастерские, могут наткнуться на разрозненные научные труды: от исторических описаний Войны Древних до хроник Второй войны и тайных трактатов о Древних богах."}},faq={{q="Какие услуги есть на Террасе Ремесленников?",a="В квартале находятся почти все учителя торговых профессий города, торговцы ремесленными материалами, таверна и служба регистрации гильдий. Это торговый центр для путников, желающих освоить или применять практические навыки в Дарнассе.",al={"craftsmen services","what is in craftsmens terrace","darnassus trainers","услуги ремесленников","что есть на террасе ремесленников","учителя дарнасса"}},{q="Почему Серебряный Рассвет находится на Террасе Ремесленников?",a="Серебряный Рассвет держит в квартале посольство, чтобы поддерживать связь с ночными эльфами и привлекать помощь против Плети. Его присутствие служит дипломатическим мостом между силами Альянса на западе и истерзанными войной землями Лордерона.",al={"argent dawn darnassus","argent dawn embassy","why argent dawn here","серебряный рассвет дарнасс","посольство серебряного рассвета","почему здесь серебряный рассвет"}},{q="Как добраться до Террасы Ремесленников?",a="Терраса расположена в северной части Дарнасса. Добраться до нее можно по мостам, ведущим на север от Террасы Воинов или на восток от Анклава Кенария.",al={"how to get to craftsmen terrace","craftsmen terrace location","finding craftsmen terrace","как добраться до террасы ремесленников","где терраса ремесленников","найти террасу ремесленников"}},{q="Какие примечательные книги можно найти возле мастерских?",a="Научные труды лежат по всем мастерским, среди них истории Войны Древних, описание последствий Второй войны и исследование о Древних богах, хранящееся в помещениях Серебряного Рассвета.",al={"craftsmen terrace books","lore books darnassus","books in craftsmens terrace","книги террасы ремесленников","книги преданий дарнасс","книги на террасе ремесленников"}}},fp="19,341,30.508.0,31.454.0,51.235.0,58.239.0,41.160.0,53.199.0"}
P.entries["subzone:crag-of-the-everliving"] = {n="Утес Бессмертных",s="Утес Бессмертных — зеленый пещерный зал в глубине Пещер Стенаний. Здесь господствуют пышная искаженная растительность и хищные растительные существа, а сам зал — владения Повелителя Клыка, лорда Питонаса. В высоких ярусах обитает древнее существо, в честь которого назван утес.",h="Утес Бессмертных — зеленый пещерный зал в глубине Пещер Стенаний.",kw={"barrens","crag of the everliving","deviate shamblers","druids of the fang","lord pythas","lord serpentis","verdan","wailing caverns","степи","утес бессмертных","загадочные шаркуны","друиды клыка","лорд питонас","лорд серпентис","вердан","пещеры стенаний"},ang={["class:Druid"]="Для друидов Кенария вид Утеса Бессмертных — трагический урок: чистая жизненная сила природы и стихийная опека превращены в смертоносные орудия Кошмара.",["profession:Herbalism"]="Неестественно пышная подземная среда утеса питает редкие подземные корни и грибы, которые процветают во влажной, пропитанной сном почве."},sec={{t="Искаженный свод",b="Хотя большая часть Пещер Стенаний высечена в сырой подземной скале, Утес Бессмертных изобилует буйной, искривленной растительностью, питаемой Кошмаром, который искажает сон Наралекса. Высокие поросшие мхом площадки и извилистые тропы забиты загадочными шаркунами — живыми растительными громадами, бродящими в подлеске. Лорд Питонас, один из павших учеников Наралекса, надзирает за центральной частью утеса: он променял благородные обеты друида на ядовитые обряды Друидов Клыка."},{t="Древний страж",b="Зал назван в честь Вердана Бессмертного — огромного первобытного растительного элементаля, обитающего в верхних ярусах утеса. Искаженный Изумрудным Кошмаром, охватившим пещеру, Вердан теперь служит грозной линией обороны, а не мирным стражем природы. За его огромной фигурой скрывается лорд Серпентис, самопровозглашенный глава Повелителей Клыка, наблюдающий за падением секты в змеиное безумие."}},faq={{q="Откуда эта местность получила название?",a="Зал назван в честь Вердана Бессмертного — древнего исполинского растительного существа, обитающего на самых высоких террасах утеса. Когда-то он воплощал вечную жизненную силу природы, но попал под власть Кошмара, поражающего пещеры.",al={"why crag of the everliving","everliving name origin","crag name","почему утес бессмертных","происхождение названия утес бессмертных","название утеса"}},{q="Кто управляет этой частью пещер?",a="Лорд Питонас, один из главных Повелителей Клыка, непосредственно правит утесом. На верхних уступах над ним скрываются Вердан Бессмертный и лорд Серпентис, предводитель Друидов Клыка.",al={"who is in charge here","crag boss","fanglord here","кто здесь главный","босс утеса","повелитель клыка здесь"}},{q="Какие существа чаще всего встречаются на Утесе Бессмертных?",a="Утес наводнен загадочными шаркунами — бредущими растительными чудовищами, рожденными искаженными источниками, — а также искривленными змеями и фанатичными Друидами Клыка.",al={"monsters in crag","crag enemies","what lives here","монстры утеса","враги утеса","кто здесь живет"}},{q="Почему растения так буйно растут глубоко под землей?",a="Подземные источники использовал ночной эльф-друид Наралекс, чтобы возродить Степи. Когда его ритуал оказался в ловушке Изумрудного Кошмара, дикий рост вышел из-под контроля и превратился во враждебную уродливую растительность.",al={"why are there plants underground","why so green","corrupted greenery","почему под землей растения","почему так зелено","искаженная зелень"}}},fp="22,298,18.491.0,20.427.0,34.261.0,38.196.0,64.170.0,47.219.0"}
P.entries["subzone:cragpool-lake"] = {n="Скалистое озеро",ang={["class:Druid"]="Сток, деревянные платформы и разрушения вокруг Скалистого озера — уродливый шрам на теле Когтистых гор, искажающий местную экосистему и вытесняющий коренных животных.",["profession:Engineering"]="Высокие деревянные леса и консольные механизмы над Скалистым озером — наглядный пример гоблинской промышленной сноровки: построено быстро, нагружено до предела и безразлично к природному рельефу."},sec={{t="Industrial Encroachment",b="Nestled within Windshear Crag, Cragpool Lake lies directly beneath the towering logging apparatus built by the Venture Company. An enormous wooden structure spans above the water, serving as the vantage point from which Gerenzo Wrenchwhistle oversees operations across the mountain valley. Venture Company workers occupy the platforms overhead."}},faq={{q="Что за огромная деревянная конструкция нависает над озером?",a="Это промышленная надстройка, возведенная Торговой Компанией для управления обширными лесозаготовками и добычей в Утесе Ветрорезов. Она соединяет платформы и тяжелые механизмы, протянувшиеся прямо над озером.",al={"venture co platform","cragpool scaffolding","cragpool bridge","платформа торговой компании","леса скалистого озера","мост скалистого озера"}},{q="Кто руководит работами у Скалистого озера?",a="Геренцо Терминатрикс, ключевой работник Торговой Компании, устроил свой наблюдательный пункт на высоких лесах, чтобы надзирать за вырубкой и добычей ресурсов по всему Утесу Ветрорезов.",al={"who leads venture co here","who is the boss here","gerenzo wrenchwhistle","кто руководит торговой компанией здесь","кто здесь главный","геренцо терминатрикс"}},{q="What dangers surround Cragpool Lake?",a="The Venture Company operates on the platforms over the lake. Its armed workers make the industrial site dangerous for intruders.",al={"what is in cragpool lake"}},{q="Покинула ли Торговая Компания Скалистое озеро?",a="No. Venture Company workers and Gerenzo Wrenchwhistle occupy the structure above the lake.",al={"is venture company gone","who lives at cragpool lake","ушла ли торговая компания","кто живет у скалистого озера"}}},fp="13,184,23.344.0,59.212.0,45.193.0,36.128.0,48.90.0"}
P.entries["subzone:crossroads"] = {n="Перекресток",s="Перекресток — бьющееся сердце путей Орды через центральный Калимдор, расположенное там, где Золотой Путь с севера на юг пересекается с дорогой от Кабестана к Когтистым горам. Это оживленный торговый форпост, военный плацдарм и транспортный узел для путников между Дуротаром, Мулгором и северными фронтами.",h="Перекресток — бьющееся сердце путей Орды через центральный Калимдор, расположенное там, где Золотой Путь с...",kw={"barrens","crossroads","devrak","gold road","raptors","ratchet","stonetalon","wind rider","степи","перекресток","деврак","золотой путь","ящеры","кабестан","когтистые горы","ветрокрыл"},ang={["faction:Alliance"]="Удар по Перекрестку напрямую перерезает поток подкреплений Орды между Оргриммаром, Мулгором и спорными границами Ясеневого леса.",["faction:Horde"]="Перекресток — главная проверка и перепутье вашего юного народа: он связывает родные земли орков, таурен и троллей и координирует снабжение по всему Калимдору."},sec={{t="Важный узел в саванне",b="Как и говорит название, Перекресток расположен прямо на пересечении Золотого Пути и дороги с запада на восток, ведущей от гоблинского порта Кабестан в Когтистые горы. Несмотря на скромные места для ночлега, форпост служит оживленным региональным узлом. Укротители ветрокрылов, торговцы, кузнецы и учителя постоянно работают под его сторожевыми башнями. Для молодых воинов, отправляющихся из Дуротара или Мулгора, поселение часто становится первым местом, где они видят огромную многофронтовую логистику, скрепляющую новую Орду."},{t="Пограничный форпост в осаде",b="Поддерживать порядок на Перекрестке — непрерывная борьба. Местные животные, включая равнинных ящеров, достаточно наглых, чтобы красть жалованье-серебро из сторожевых башен, — постоянная помеха, а гарпии, свинобразы и племена кентавров непрерывно давят на периметр. Помимо угроз, свойственных Степям, близость к нейтральному Кабестану и спорным чащам Ясеневого леса делает поселение главной целью для наступающих разведывательных отрядов Альянса, что приводит к частым стычкам у его оборонительных баррикад."}},faq={{q="Почему Перекресток так важен для Орды?",a="Он держит главные транспортные артерии центрального Калимдора. Каждый путник, идущий по суше между Дуротаром, Мулгором, Кабестаном, Когтистыми горами или Ясеневым лесом, должен пройти через Перекресток или рядом с ним, поэтому он главный узел снабжения и подкреплений.",al={"why is crossroads important","crossroads purpose","why crossroads matters","почему важен перекресток","назначение перекрестка","чем важен перекресток"}},{q="Кто обеспечивает воздушные перевозки на Перекрестке?",a="Деврак служит распорядителем полетов на Перекрестке: он управляет насестом ветрокрылов поселения и напрямую связывает путников с форпостами по всему Калимдору, включая Оргриммар и Громовой Утес.",al={"crossroads flight master","who has wyverns here","flight master crossroads","распорядитель полетов перекресток","у кого виверны","перекресток полеты"}},{q="Почему Альянс так часто нападает на Перекресток?",a="Поскольку Перекресток — центр транспортных путей Орды и находится в пределах легкой досягаемости как Ясеневого леса на севере, так и нейтрального порта Кабестан на востоке, рейдовые отряды Альянса регулярно нападают на форпост, чтобы нарушить снабжение Орды.",al={"why alliance raids crossroads","alliance pvp crossroads","crossroads attacks","почему альянс нападает на перекресток","пвп альянс перекресток","нападения на перекресток"}},{q="Что случилось с жалованьем форпоста в серебре?",a="Ящеры Степей совершили налет на сторожевую башню Перекрестка и унесли партию серебра, предназначенного для оплаты стражи поселения, рассыпав его по окрестной саванне.",al={"stolen payroll crossroads","who took the silver","crossroads silver stolen","украденное жалованье перекресток","кто взял серебро","украдено серебро перекресток"}}},fp="10,336,32.539.0,28.538.0,48.251.0,48.198.0,58.253.0,46.184.0"}
P.entries["subzone:crown-guard-tower"] = {n="Башня королевской стражи",s="Башня королевской стражи — разрушенная разведывательная башня Лордерона на юге Восточных Чумных земель. Плеть уничтожила ее во время вторжения в Лордерон в Третью войну, и с тех пор ее разбитые камни стоят среди порчи.",h="Башня королевской стражи — разрушенная разведывательная башня Лордерона на юге Восточных Чумных земель.",kw={"crown guard tower","eastern plaguelands","lordaeron","scourge","scout tower","watchtower","башня королевской стражи","восточные чумные земли","лордерон","плеть","разведывательная башня","сторожевая башня"},ang={["faction:Alliance"]="Для Альянса разрушенная Башня королевской стражи напоминает о том, как полностью Плеть сломила оборону Королевства Лордерон."},sec={{t="Павший бастион",b="Когда-то часть обороны Королевства Лордерон, Башня королевской стражи была разведывательной башней, наблюдавшей за землями восточного Лордерона. Когда Плеть захлестнула королевство, башню разрушили и оставили в руинах — одну из нескольких павших башен, разбросанных по нынешним Восточным Чумным землям. Ее обугленные камни стоят в земле, которую по-прежнему удерживает нежить."}},faq={{q="Для чего изначально построили Башню королевской стражи?",a="Она служила региональной сторожевой башней и разведывательным форпостом человеческого Королевства Лордерон до Третьей войны, охраняя дороги от вторжений.",al={"crown guard tower history","why was it built","lordaeron tower","история башни королевской стражи","зачем ее построили","башня лордерона"}},{q="Почему башня разрушена?",a="Башня была уничтожена во время вторжения Плети в Лордерон, когда волны нежити захлестнули оборону королевства и превратили сооружение в груду обломков.",al={"who destroyed crown guard tower","what happened here","кто разрушил башню королевской стражи","что здесь произошло"}}},fp="17,225,16.354.0,48.157.0,24.151.0"}
P.entries["subzone:crusader-outpost"] = {n="Застава Алого Ордена",s="Застава Алого Ордена — укрепленная сторожевая башня на неровных холмах востока Тирисфальских лесов. Ее занимают фанатичные члены Алого ордена; башня охраняет подступы к их оплоту — Монастырю Алого ордена. С этой высоты крестоносцы следят за движением по дороге и готовы отразить любое вторжение Отрекшихся.",h="Застава Алого Ордена — укрепленная сторожевая башня на неровных холмах востока Тирисфальских лесов.",kw={"captain vachon","crusader outpost","scarlet crusade","scarlet monastery","scout tower","tirisfal glades","watchtower","капитан вакон","застава алого ордена","алый орден","монастырь алого ордена","разведывательная башня","тирисфальские леса","сторожевая башня"},ang={["faction:Horde"]="Путешествовать по восточным тропам Тирисфаля нужно осторожно: часовые Алого ордена на этом холме быстро нападут на любого, кто направляется к Монастырю.",["race:Undead"]="Эта сторожевая башня стоит на самой границе земель Отрекшихся и горько напоминает, что фанатичные живые крестоносцы по-прежнему удерживают в лесах собственные владения."},sec={{t="Дозорные над Тирисфалем",b="Застава Алого Ордена, встроенная в утесы над восточной дорогой, служит главным пунктом раннего оповещения Алого ордена. Из своей высокой башни часовые следят за передвижением между Бриллом и восточными окраинами Лордерона, чтобы бродячая нежить и разведывательные отряды были замечены задолго до того, как достигнут ворот Монастыря. Башня также дает гарнизону тактическую возможность ударить с фланга по любому войску, которое попытается пройти по долине к их священному оплоту."},{t="Заноза в боку Темной Госпожи",b="Гарнизон под началом офицеров Алого ордена, таких как капитан Вакон, несет неусыпный дозор. Окрестные леса они считают не суверенной землей Отрекшихся, а оскверненной почвой, украденной у человечества чудовищами. Для путников, верных Подгороду, застава — постоянная засада: арбалетные болты и очищающая сталь ждут каждого, кто подойдет к утесам слишком близко."}},faq={{q="Что такое Застава Алого Ордена?",a="Это укрепленная разведывательная башня Алого ордена на востоке Тирисфальских лесов. Она наблюдает за дорогой внизу и защищает южные подступы к Монастырю Алого ордена.",al={"what is this tower","crusader outpost tirisfal","scarlet watchtower","что за башня","застава алого ордена тирисфаль","сторожевая башня алого ордена"}},{q="Кто управляет этой заставой?",a="Заставу занимают фанатики Алого ордена под командованием капитана Вакона. Всю нежить они считают мерзостью, подлежащей уничтожению на месте.",al={"who owns crusader outpost","who lives here","scarlet crusade outpost","кому принадлежит застава алого ордена","кто здесь живет","застава алого ордена"}},{q="Почему башня стоит на этих холмах?",a="Ее высокое положение дает хороший обзор главной восточной дороги Тирисфальских лесов. Это позволяет крестоносцам заранее заметить передвижение войск Отрекшихся и ударить с фланга по любым силам, пытающимся штурмовать Монастырь Алого ордена.",al={"why build here","outpost location","tactical purpose","почему построили здесь","расположение заставы","тактическое назначение"}},{q="Нападут ли на меня здешние стражи?",a="Да. Алый орден считает всех чужаков — особенно Отрекшихся и их союзников из Орды — растленными врагами, которых нужно очистить священным огнем.",al={"is crusader outpost hostile","are they aggressive","враждебна ли застава алого ордена","они агрессивны"}}},fp="16,340,18.492.0,31.433.0,29.184.0,26.156.0,41.232.0,31.150.0"}
P.entries["subzone:crusader-s-armory"] = {n="Оружейная Крестоносцев",s="Оружейная Крестоносцев — укрепленный внутренний зал в крыле Оружейной Монастыря Алого ордена. Здесь хранятся боеприпасы, порох и пушечные ядра; зал служит плацдармом для фанатиков, охраняющих путь к внутреннему святилищу. За запертой железной дверью находится Зал Защитников.",h="Оружейная Крестоносцев — укрепленный внутренний зал в крыле Оружейной Монастыря Алого ордена.",kw={"armory","crusader's armory","gunpowder","hall of champions","scarlet key","scarlet monastery","оружейная","оружейная крестоносцев","порох","зал защитников","алый ключ","монастырь алого ордена"},ang={["faction:Horde"]="Для Отрекшихся и Орды взрывоопасные запасы Оружейной Крестоносцев — прямая угроза границам Тирисфальских лесов и вратам Подгорода.",["profession:Blacksmithing"]="Накопленное здесь оружие и боеприпасы свидетельствуют о высоком качестве производства и военной дисциплине бывших кузнецов Лордерона, ныне обратившихся к фанатизму."},sec={{t="Арсенал рвения",b="Оружейная Крестоносцев, расположенная между Оружейной пехотинцев и величественным Залом Защитников, демонстрирует полную боевую готовность Алого ордена. В отличие от тренировочных дворов снаружи, эти узкие каменные коридоры доверху забиты ящиками с горючим порохом, сложенными ядрами и тяжеловооруженными крестоносцами, готовыми отразить чужаков. Орден превратил бывший монастырский комплекс в ощетинившуюся крепость, отдав каждый зал орудиям тотальной войны. В дальнем конце оружейной стоит тяжелая запертая железная дверь, закрывающая вход во внутренние покои тому, у кого нет Алого ключа."}},faq={{q="Что такое Оружейная Крестоносцев?",a="Оружейная Крестоносцев — внутренняя часть крыла Оружейной Монастыря Алого ордена. Она служит складом боеприпасов и оборонительным коридором между Оружейной пехотинцев и Залом Защитников.",al={"crusaders armory","what is crusaders armory","monastery armory room","оружейная крестоносцев","что такое оружейная крестоносцев","оружейная монастыря"}},{q="Почему дверь в конце заперта?",a="Дверь в конце Оружейной Крестоносцев охраняет проход в Зал Защитников и покои командира за ним. Алый орден строго следит за ней: чтобы ее открыть, нужен Алый ключ, который находится в библиотечном крыле Монастыря.",al={"locked door armory","how to open armory door","scarlet key armory","запертая дверь оружейной","как открыть дверь оружейной","алый ключ оружейная"}},{q="Почему здесь так много пушечных ядер и ящиков с порохом?",a="Алый орден ведет активную осаду и держит артиллерийскую оборону по всем Тирисфальским лесам. Эта оружейная — главный склад для их пушек и взрывчатых боеприпасов, обеспечивающий войскам снабжение для войны с Плетью и Отрекшимися.",al={"powder crates armory","cannons in monastery","why gunpowder","ящики с порохом оружейная","пушки в монастыре","зачем порох"}},{q="Кто охраняет эту область?",a="Зал защищают опытные солдаты Алого ордена, в том числе пехотинцы, крестоносцы и лучники, расставленные среди боеприпасов, чтобы остановить захватчиков, пытающихся проникнуть глубже в комплекс.",al={"armory mobs","who is in crusaders armory","монстры оружейной","кто в оружейной крестоносцев"}}},fp="17,293,15.621.0,30.194.0,34.252.0,60.275.0,21.196.0"}
P.entries["subzone:crusader-s-outpost"] = {n="Застава Крестоносцев",s="Застава Крестоносцев — укрепленная разведывательная башня Алого ордена на западе Тирисфальских лесов. Она стоит рядом с Фермой Соллидена и является самой западной позицией ордена во всем Лордероне. Из-за большой удаленности от главных оплотов Алого ордена ее гарнизон оказался изолирован в сердце враждебных земель Отрекшихся.",h="Застава Крестоносцев — укрепленная разведывательная башня Алого ордена на западе Тирисфальских лесов.",kw={"crusader's outpost","scarlet crusade","scout tower","solliden farmstead","tirisfal glades","tyr's hand","застава крестоносцев","алый орден","разведывательная башня","ферма соллидена","тирисфальские леса","длань тира"},ang={["faction:Horde"]="Застава горько напоминает о фанатичном отказе Алого ордена уступить Тирисфаль Отрекшимся и их союзникам из Орды.",["race:Undead"]="Для только что восставших Отрекшихся, выходящих из Могильника, эта близкая башня и охраняющие ее фанатики Алого ордена — прямая смертельная угроза у самой границы."},sec={{t="Одинокая сторожевая башня",b="Эта каменная башня, стоящая в западных холмах Тирисфаля к западу от Могильника, — самая дальняя точка влияния Алого ордена в Лордероне. Гарнизон действует вместе с уцелевшими людьми-работниками соседней Фермы Соллидена, пытаясь сдержать наступление нежити. С вершины башни наблюдатели следят за окрестными тыквенными полями и лесными тропами, высматривая как бродячих порождений Плети, так и патрули из Подгорода."},{t="В изоляции за линией врага",b="Удержание западной границы сопряжено с огромным риском. Отрезанные от главных оплотов в Монастыре Алого ордена и далеко на востоке — в Длани Тира, крестоносцы этой заставы не могут рассчитывать на быстрое подкрепление, если нападавшие прорвут частокол. Любая осада со стороны войск Отрекшихся, собирающихся по всему Тирисфалю, означает необходимость держаться самим или погибнуть до прихода помощи."}},faq={{q="Почему Алый орден забрался так далеко, на запад Тирисфаля?",a="Башня служит постом раннего оповещения и оборонительным укреплением в западных холмах Тирисфаля. Она защищает живых фермеров Фермы Соллидена и следит за западными подступами, высматривая как диких созданий Плети, так и передовые разведотряды Отрекшихся.",al={"why are scarlet here","scarlet crusaders tirisfal west","crusader outpost purpose","почему здесь алый орден","крестоносцы алого ордена запад тирисфаля","назначение заставы крестоносцев"}},{q="Может ли подкрепление добраться до этой заставы, если на нее нападут?",a="Нелегко. Застава — самое западное владение Алого ордена в Лордероне. Главные оплоты ордена находятся далеко на востоке — в Монастыре Алого ордена и Длани Тира, поэтому гарнизон окажется полностью отрезанным, если его окружат силы Отрекшихся.",al={"can scarlet reinforce","outpost help","how far is help","может ли алый орден прислать подкрепление","помощь заставе","как далеко помощь"}},{q="Как связаны башня и Ферма Соллидена?",a="Крестоносцы заключили союз с оставшимися фермерами Фермы Соллидена. Солдаты защищают их от ходячих мертвецов, а взамен получают провизию и надежный плацдарм на окраине Лордерона.",al={"solliden connection","why are crusaders at farm","crusaders and farmers","связь с соллиденом","почему крестоносцы на ферме","крестоносцы и фермеры"}},{q="Есть ли в этом регионе другие подобные башни?",a="Да. Эта башня — одна из четырех похожих Застав Крестоносцев, построенных Алым орденом по всем Тирисфальским лесам для наблюдения и патрулирования окрестных земель.",al={"other crusader outposts","more scarlet towers","другие заставы крестоносцев","еще башни алого ордена"}}},fp="18,343,19.496.0,27.411.0,68.253.0,58.229.0,66.221.0,47.160.0"}
P.entries["subzone:crypt-stromgarde-keep"] = {n="Склеп (Крепость Стромгард)",s="Глубоко в руинах Крепости Стромгард, за часовней Святилища, в самом сердце квартала, который удерживают уцелевшие защитники Стромгарда, находится королевский склеп. В нем покоится павший король Торас Троллебой и хранятся фамильные сокровища его династии. Склеп, который тщательно охраняют принц Гален и верные смотрители, остается убежищем королевской чести в разрушенном королевстве.",h="Глубоко в руинах Крепости Стромгард, за часовней Святилища, в самом сердце квартала, который удерживают...",kw={"arathi","crypt","galen","sanctum","stromgarde","thoras","trol'kalar","trollbane","арати","склеп","гален","святилище","стромгард","торас","трол'калар","троллебой"},ang={["faction:Alliance"]="Королевский склеп Стромгарда — один из последних оплотов наследия Альянса в Арати, который упорно обороняют от бандитов, огров и Орды.",["race:Human"]="Для людей Альянса гробница символизирует трагический упадок Стромгарда, одного из семи великих королевств, и священную могилу одного из самых яростных военных предводителей Альянса."},sec={{t="Гробница Тораса Троллебоя",b="Этот подземный склеп скрыт под Святилищем Крепости Стромгард. Здесь упокоен король Торас Троллебой, король-воин, который вел Стромгард через Вторую войну. Несмотря на разруху, охватившую город, который поделили разбойники Синдиката и огры Тяжелого Кулака, уцелевшее ополчение Стромгарда упорно удерживает этот квартал. Принц Гален Троллебой лично охраняет склепы вместе с преданными королевскими смотрителями, чтобы тело и наследие его отца остались нетронутыми мародерами и врагами снаружи."},{t="Хранилище Трол'калара",b="Склеп не только хранит королевских мертвецов, но и оберегает драгоценные реликвии рода Троллебоев. Главная из них — Трол'калар, древний рунный двуручный меч, выкованный много веков назад для убийства троллей. Покои и их сокровища защищены мощными чарами, а охрану доверили смотрителям, таким как Аларик, Невлин и Уэстон. Гален и его сторонники неусыпно стерегут гробницу: они хорошо знают, что соперничающие группировки и враждебные тролли по всему Арати захотят завладеть древней силой клинка."}},faq={{q="Кто похоронен в склепе?",a="Здесь погребен король Торас Троллебой, покойный правитель Стромгарда. Его сын, принц Гален Троллебой, охраняет гробницу посреди разрушенного города.",al={"who is buried here","whose tomb is this","crypt tomb","кто здесь похоронен","чья это гробница","склеп гробница"}},{q="Что такое Трол'калар?",a="Трол'калар — древний фамильный клинок рода Троллебоев. Его имя с древнего языка переводится как «убийца троллей»; изначально его выковали для борьбы с лесными троллями Арати.",al={"trolkalar sword","trollbane sword","what is trolkalar","трол'калар меч","меч троллебоев","что такое трол'калар"}},{q="Кто охраняет склеп?",a="Склеп защищают принц Гален Троллебой и королевские смотрители Стромгарда, среди них Аларик, Невлин и Уэстон. Они оберегают погребальную камеру от наступающих воров Синдиката и огров Тяжелого Кулака.",al={"crypt guards","who defends the crypt","caretakers","стража склепа","кто защищает склеп","смотрители"}},{q="Где находится склеп?",a="Он находится в Крепости Стромгард на Нагорье Арати, в глубине квартала Святилища за часовней крепости, в секторе, который по-прежнему удерживают сторонники Стромгарда.",al={"crypt location","how to find the crypt","where is stromgarde crypt","расположение склепа","как найти склеп","где склеп стромгарда"}}},fp="23,394,28.570.0,23.518.0,27.153.0,19.219.0,21.212.0,27.176.0"}
P.entries["subzone:crystal-shore"] = {n="Хрустальное взморье",s="Хрустальное взморье — полоса песчаного берега на юго-восточной окраине Тернистой долины, омываемая волнами Южных морей. Пляж лежит у подножия крутых прибрежных утесов, к югу от древних Руин Абораза и через воды от Острова Жагуаро.",h="Хрустальное взморье — полоса песчаного берега на юго-восточной окраине Тернистой долины, омываемая волнами...",kw={"crystal shore","jaguero isle","mistvale valley","ruins of aboraz","south seas","stranglethorn vale","wild shore","хрустальное взморье","остров жагуаро","мглистая долина","руины абораза","южные моря","тернистая долина","пустынный берег"},sec={{t="Уединенная прибрежная полоса",b="Хрустальное взморье тянется вдоль юго-восточной границы Тернистой долины и образует естественную границу между густыми тропическими дебрями и открытыми водами Южных морей. Пляж отделен от внутренних джунглей крутыми хребтами, и путникам, идущим между побережьем и глубинной глушью Мглистой долины, остается лишь пара трудных проходов. К северу лежат разрушающиеся постройки троллей — Руины Абораза, а Пустынный берег тянется вдоль южных изгибов мыса. Это тихий, продуваемый ветрами край, далекий от шумных доков Пиратской бухты."}},faq={{q="Где находится Хрустальное взморье?",a="Хрустальное взморье расположено на крайнем юго-восточном побережье Тернистой долины. Оно тянется вдоль вод Южных морей к югу от Руин Абораза и к северо-востоку от Пустынного берега.",al={"crystal shore location","where is crystal shore","crystal shore map","хрустальное взморье расположение","где хрустальное взморье","хрустальное взморье карта"}},{q="Как попасть на Хрустальное взморье из глубины суши?",a="Крутой хребет отделяет пляж от джунглей на материке. Однако через высокие утесы проходит несколько узких естественных проходов, в том числе тропа, ведущая прямо в Мглистую долину.",al={"how to get to crystal shore","path to crystal shore","reach crystal shore","как добраться до хрустального взморья","путь к хрустальному взморью","дойти до хрустального взморья"}},{q="Какие ориентиры есть поблизости?",a="Сразу к северу от взморья стоят древние Руины Абораза, а за проливом на юго-западе находится Остров Жагуаро. Дальше к югу вдоль побережья лежит Пустынный берег.",al={"landmarks near crystal shore","what is near crystal shore","ориентиры у хрустального взморья","что рядом с хрустальным взморьем"}},{q="Живет ли на Хрустальном взморье какая-либо фракция?",a="Ни одна фракция не держит на Хрустальном взморье города или поселения. Это нетронутая полоса пляжа, где властвуют местные животные, древние тролльи руины на севере и бьющие волны Южных морей.",al={"who lives at crystal shore","crystal shore settlement","crystal shore towns","кто живет на хрустальном взморье","поселение хрустальное взморье","города хрустальное взморье"}}},fp="13,270,24.627.0,35.208.0,48.186.0,26.187.0,44.218.0"}
P.entries["subzone:crystal-vale"] = {n="Долина Кристаллов",s="Долина Кристаллов — отдаленный каньон в самом северо-западном углу Силитуса, где высятся зазубренные минеральные шпили и бушуют стихийные силы. По его каменистым равнинам бродят элементали земли и воздуха, охраняя богатые жилы сырой руды. Это также место мощной магии призыва, тесно связанное с древними повелителями стихий.",h="Долина Кристаллов — отдаленный каньон в самом северо-западном углу Силитуса, где высятся зазубренные...",kw={"crystal vale","elementals","highlord demitrian","ravaged twilight camp","silithus","thorium","thunderaan","долина кристаллов","элементали","верховный лорд демитриан","разоренный сумеречный лагерь","силитус","торий","громораан"},ang={["class:Shaman"]="Яростное столкновение духов земли и воздуха напоминает шаманам о необузданном хаосе неукрощенных элементалей по всему Силитусу.",["profession:Mining"]="В скалистых склонах и стенах каньона Долины Кристаллов, как известно, есть ценные жилы богатого тория, поэтому она — выгодное, но опасное место для умелых шахтеров."},sec={{t="Слияние камня и ветра",b="Долина Кристаллов не похожа на бесплодные пустынные пески юга Силитуса. Котловина, окруженная крутыми утесами, заполнена мерцающими кристаллическими образованиями, бродячими земляными элементалями и ревущими вихрями живого воздуха. Богатые залежи тория привлекают отважных старателей, но в долине далеко не тихо. Стихийные существа здесь враждебны ко всем чужакам и охраняют край, пропитанный первозданными конфликтами изначального Азерота."},{t="Сон Покорителя Ветра",b="Помимо минералов и местных духов, Долина Кристаллов имеет глубокое значение для древних стихийных сил. Здесь обитает верховный лорд Демитриан, хранящий тайны принца Громораана, Покорителя Ветра. Тех, кто собрал разорванные стихийные узы павшего принца и редчайшие кованые металлы, направляют в эту долину, где заточенного повелителя воздуха можно вызвать из оков и вступить с ним в открытый бой."}},faq={{q="Где находится Долина Кристаллов?",a="Долина Кристаллов расположена в дальней северо-западной части Силитуса, у горного кольца, окружающего пустыню.",al={"where is crystal vale","crystal vale map","crystal vale location","где долина кристаллов","долина кристаллов карта","долина кристаллов расположение"}},{q="Какие существа населяют эту долину?",a="Каньон населяют в основном агрессивные элементали воздуха и земли, которые парят и топают вокруг минеральных выступов.",al={"crystal vale mobs","what lives in crystal vale","elementals in crystal vale","монстры долины кристаллов","кто живет в долине кристаллов","элементали в долине кристаллов"}},{q="Кто такой верховный лорд Демитриан и почему он здесь?",a="Верховный лорд Демитриан — отшельник, живущий в долине в одиночестве и обладающий глубокими знаниями о принце Громораане. Он помогает героям, способным воссоединить узы Покорителя Ветра, чтобы призвать стихийного принца.",al={"who is demitrian","highlord demitrian crystal vale","demitrian location","кто такой демитриан","верховный лорд демитриан долина кристаллов","где демитриан"}},{q="Что такое Разоренный Сумеречный лагерь?",a="Это развалины лагеря Сумеречного Молота в долине, захваченного и разгромленного свирепыми стихийными обитателями каньона.",al={"ravaged twilight camp crystal vale","twilight camp in vale","destroyed twilight camp","разоренный сумеречный лагерь долина кристаллов","сумеречный лагерь в долине","разрушенный сумеречный лагерь"}}},fp="12,325,30.472.0,29.437.1,34.134.0,35.122.0,45.208.0,34.148.0"}
P.entries["subzone:crystalvein-mine"] = {n="Хрустальная шахта",s="Хрустальная шахта — пещера в центральной части Тернистой долины неподалеку от древних руин Зул'Мамве. Пещера богата ценными «поющими кристаллами», но агрессивные местные василиски полностью заполонили ее и обращают будущих шахтеров в камень.",h="Хрустальная шахта — пещера в центральной части Тернистой долины неподалеку от древних руин Зул'Мамве.",kw={"basilisk","crank fizzlebub","crystalvein mine","singing crystals","stranglethorn vale","venture co","zul'mamwe","василиск","крэнк физзлбаб","хрустальная шахта","поющие кристаллы","тернистая долина","торговая компания","зул'мамве"},ang={["profession:Mining"]="Шахтеры, которых манят поющие кристаллы, должны быть осторожны: местная популяция василисков делает добычу здесь одним из самых опасных занятий в Тернистой долине."},sec={{t="Выгодная ловушка",b="Хрустальная шахта, спрятанная в холмах джунглей близ Зул'Мамве, богата редкими залежами поющих кристаллов — уникального минерала, который высоко ценится в южных торговых портах. Соблазнившись обещанием огромной прибыли, Торговая Компания решила добывать эти жилы. Однако местные обитатели шахты оказались губительны для дела. Василиски поедают странные кристаллы, отчего их чешуя твердеет, а сами они становятся неестественно смертоносными. У входа в пещеру стоят окаменевшие статуи троллей и людей — безмолвное свидетельство неудачных экспедиций Торговой Компании."}},faq={{q="Чем ценна Хрустальная шахта?",a="В шахте есть залежи редких «поющих кристаллов» — выгодного минерала, который встречается только в Тернистой долине. Гоблины, такие как Крэнк Физзлбаб, ценят их за звучание и денежную стоимость, и это толкает старателей отважиться на опасные пещеры.",al={"why is crystalvein mine important","what is in crystalvein mine","singing crystals","почему важна хрустальная шахта","что в хрустальной шахте","поющие кристаллы"}},{q="Почему у входа в шахту стоят каменные статуи?",a="Статуи — это окаменевшие останки несчастных местных троллей и работников Торговой Компании. Местные василиски питаются резонирующими кристаллами, отчего их шкура становится каменной, и обращают в камень всякого, кто глупо вторгнется на их кормовые угодья.",al={"petrified people crystalvein","crystallized trolls crystalvein","stone bodies stranglethorn","окаменевшие люди хрустальная шахта","кристаллизованные тролли","каменные тела тернистая долина"}},{q="Кто сейчас владеет Хрустальной шахтой?",a="Хотя Торговая Компания заявила права на разработку пещеры, на деле она ею не владеет. Нашествие василисков так сильно, что гоблины не смогли наладить добычу в глубине.",al={"who owns crystalvein","crystalvein faction","venture co crystalvein","кто владеет хрустальной шахтой","фракция хрустальной шахты","торговая компания хрустальная шахта"}}},fp="16,265,16.596.0,37.239.0,45.252.0,40.224.0"}
P.entries["subzone:cut-throat-alley"] = {n="Переулок Головорезов",s="Переулок Головорезов — уединенный необитаемый закоулок Штормграда, скрытый за лавками у канала. Он находится за магазином «Тенистая леди» неподалеку от границы Квартала Дворфов и состоит из тихого дворика и пустого жилого дома, отрезанных от обычного городского движения.",h="Переулок Головорезов — уединенный необитаемый закоулок Штормграда, скрытый за лавками у канала.",kw={"cathedral square","cut-throat alley","dwarven district","secret alley","shady lady","stormwind canals","соборная площадь","переулок головорезов","квартал дворфов","тайный переулок","тенистая леди","каналы штормграда"},ang={["class:Rogue"]="Этот тупик, куда можно попасть только через заднюю дверь сомнительной лавки у канала, не патрулируется и служит идеальным укрытием для тех, кто предпочитает держаться подальше от глаз городской стражи Штормграда."},sec={{t="Уединенный уголок",b="Переулок Головорезов — один из самых тихих и скрытных уголков Штормграда. Хотя на картах он значится вместе с Кварталом Дворфов, в нем нет ни ревущих горнов, ни густой сажи этого района. До переулка нельзя добраться ни по одной из главных улиц города: единственный путь ведет через «Тенистую леди» — небольшую лавку у каналов к югу от моста, ведущего от Соборной площади. За дверью лавки находится небольшой мощеный тупик с грудами ящиков, забытыми бочками и единственным пустым двухэтажным домом. Скрытый от стражи и обычных горожан, он хранит полную тишину посреди суеты столицы."}},faq={{q="Как пройти в Переулок Головорезов?",a="Идите к набережной канала на краю Квартала Дворфов, к югу от пешеходного моста к Соборной площади. Найдите лавку «Тенистая леди». Если пройти прямо через ее заднюю часть, вы выйдете в укромный переулок.",al={"find cut throat alley","cut throat alley location","where is cut-throat alley","how to enter cut-throat alley","найти переулок головорезов","где переулок головорезов","как попасть в переулок головорезов","расположение переулка головорезов"}},{q="Почему на карте указан Квартал Дворфов?",a="На обычных картах эта открытая часть относится к району Квартала Дворфов. Название «Переулок Головорезов» появляется на компасе, только когда вы входите в пустой двухэтажный дом в глубине участка.",al={"minimap dwarven district","why does it say dwarven district","cut-throat alley name bug","миникарта квартал дворфов","почему написан квартал дворфов","ошибка названия переулка головорезов"}},{q="Кто-нибудь живет в Переулке Головорезов?",a="Нет. Переулок и его единственный двухэтажный дом совершенно заброшены. Кроме сложенных ящиков и пустых бочек, здесь нет ни жителей, ни торговцев, ни городской стражи.",al={"cut throat alley npcs","who lives in cut throat alley","empty house cut throat alley","персонажи переулка головорезов","кто живет в переулке головорезов","пустой дом переулок головорезов"}},{q="Есть ли в Переулке Головорезов задания?",a="Никаких официальных поручений или городских заданий, ведущих в переулок, нет. Он служит лишь незамеченным уединенным фоном в столице.",al={"cut throat alley quests","cut throat alley storyline","задания переулка головорезов","история переулка головорезов"}}},fp="16,287,15.663.0,35.264.0,48.219.0,37.189.0,41.146.0"}
P.entries["subzone:dabyrie-s-farmstead"] = {n="Усадьба Дабири",s="Усадьба Дабири — лояльное Альянсу сельское поселение на севере Нагорья Арати. В краю, разоренном Третьей войной и наводненном разбойниками Синдиката и троллями Сухокожих, это имение остается стойким оплотом жителей Стромгарда под началом Кенаты Дабири.",h="Усадьба Дабири — лояльное Альянсу сельское поселение на севере Нагорья Арати.",kw={"arathi","callow","dabyrie","fardel","farmstead","kenata","marcel","stromgarde","арати","каллоу","дабири","фардель","усадьба","кената","марсель","стромгард"},ang={["faction:Alliance"]="Для путников Альянса усадьба — редкое и утешительное напоминание о том, что жители Стромгарда еще живы и борются за свою землю среди наступающих врагов.",["race:Undead"]="Для Отрекшихся процветающая усадьба — раздражающее зрелище: живые люди копят добро, награбленное у семей, погибших в Третьей войне."},sec={{t="Оплот в нагорье",b="Усадьба Дабири, расположенная на северных полях Нагорья Арати, — одна из немногих уцелевших человеческих ферм в расколотом королевстве Стромгард. Ею владеет Кената Дабири, работающая вместе с сыновьями Фарделем и Марселем, а земли яростно защищает местное семейное ополчение. Окруженная агрессивными животными, беспринципными бандитами и близким присутствием Отрекшихся на севере, ферма стоит символом стойкости людей в разрушенной земле."},{t="Горькая вражда",b="В Арати выжить без жестокой вражды удается редко. Имение навлекло на себя сильный гнев Отрекшихся, особенно Женави Каллоу, бывшей знатной дамы, потерявшей земли и родных во время Третьей войны. Каллоу обвиняет уцелевший род Дабири в разграблении семейных реликвий в хаосе чумы, и скромная усадьба стала мишенью мстительных наемников Орды, стремящихся свести старые северные счеты."}},faq={{q="Кто живет в Усадьбе Дабири?",a="Ферма — дом Кенаты Дабири и ее сыновей, Фарделя и Марселя. Это жители Стромгарда, лояльные Альянсу, их защищает местное ополчение, принесшее присягу.",al={"who owns dabyrie farm","dabyrie family","kenata dabyrie","кто владеет фермой дабири","семья дабири","кената дабири"}},{q="Почему Орда нацелилась на эту ферму?",a="Отрекшаяся по имени Женави Каллоу затаила злобу на семью Дабири. Она утверждает, что они разграбили имение ее семьи и забрали уцелевшие реликвии, пока ее родные гибли в Третьей войне.",al={"why kill dabyrie","genavie callow quest","horde dabyrie quest","зачем убивать дабири","задание женави каллоу","задание орды дабири"}},{q="Входит ли Усадьба Дабири в Стромгард?",a="Да. Семья Дабири считает себя подданными королевства Стромгард и союзниками Альянса, держась стойко, несмотря на гибель столицы к югу.",al={"is dabyrie alliance","stromgarde farm","дабири альянс","ферма стромгарда"}},{q="Какие угрозы окружают усадьбу?",a="Ферма находится опасно близко к враждебным хищникам нагорья, бродящим головорезам Синдиката и силам Отрекшихся, наступающим с севера.",al={"threats to dabyrie","danger near dabyrie farm","угрозы дабири","опасность возле фермы дабири"}}},fp="19,277,26.482.0,12.437.1,33.168.0,37.215.0,42.184.0,36.162.0"}
P.entries["subzone:dagger-hills"] = {n="Холмы Разбойничьих Кинжалов",s="Холмы Разбойничьих Кинжалов — скалистая гряда на юге Западного Края, прямо за разоренным городком Луноречье. Давно брошенное короной, это каменистое нагорье служит враждебным убежищем для головорезов, бандитов и подкрадывающихся ужасов, угрожающих окрестным равнинам.",h="Холмы Разбойничьих Кинжалов — скалистая гряда на юге Западного Края, прямо за разоренным городком Луноречье.",kw={"dagger hills","defias","grimbooze","leprithus","moonbrook","thunderbrew","westfall","холмы разбойничьих кинжалов","справедливость","мрачнобух","лепритус","луноречье","громовар","западный край"},ang={["faction:Alliance"]="Холмы олицетворяют полный крах закона на юге Западного Края, где Народному ополчению Гриана Камнегрива приходится отвоевывать земли, оставленные из-за отсутствия Штормграда.",["race:Dwarf"]="Одинокое присутствие Мрачнобуха Громовара на этом открытом хребте показывает безграничное упрямство дворфов-пивоваров, ищущих тихое место, чтобы довести свое мастерство до совершенства."},sec={{t="Пристанище бандитов",b="Возвышаясь над обветшалым Луноречьем, Холмы Разбойничьих Кинжалов отмечают зубчатые южные пределы Западного Края. Лишенное официальных королевских патрулей из Штормграда, это засушливое нагорье стало естественной крепостью Братства Справедливости. Кулачные бойцы, следопыты и грабители прячутся среди скалистых гребней и кустарника, нападая на неосторожных путников и наблюдая за подступами к своим твердыням внизу."},{t="Тени на хребте",b="Помимо смертных разбойников, Холмы Разбойничьих Кинжалов в темноте пользуются жуткой славой. Зловещий призрак Лепритус, бродячий вурдалак, замечали на пустынных высотах с наступлением сумерек. Кроме странствующих разбойников и неупокоенных, единственный, кто решается жить на хребте, — Мрачнобух Громовар, дворф-пивовар, который ставит свое перегонное оборудование в суровой глуши, невзирая на опасности."}},faq={{q="Где находятся Холмы Разбойничьих Кинжалов?",a="Холмы Разбойничьих Кинжалов образуют высокую каменистую южную границу Западного Края и стоят прямо за заброшенным Луноречьем.",al={"dagger hills location","where is dagger hills","how to get to dagger hills","где холмы разбойничьих кинжалов","расположение холмов разбойничьих кинжалов","как добраться до холмов разбойничьих кинжалов"}},{q="Кто управляет Холмами Разбойничьих Кинжалов?",a="Братство Справедливости сильно присутствует на хребте: грабители, следопыты и кулачные бойцы охраняют южные холмы.",al={"dagger hills defias","who lives in dagger hills","enemies in dagger hills","справедливость на холмах кинжалов","кто живет на холмах разбойничьих кинжалов","враги на холмах разбойничьих кинжалов"}},{q="Почему дворф варит эль в такой глуши?",a="Мрачнобух Громовар устроил свою перегонную мастерскую на этих одиноких высотах, чтобы готовить крепкие дворфийские напитки, ради хорошей выпивки бросая вызов и бандитам, и зверям.",al={"grimbooze westfall","dwarf in dagger hills","grimbooze thunderbrew lore","мрачнобух западный край","дворф на холмах разбойничьих кинжалов","мрачнобух громовар предание"}},{q="Кто такой Лепритус?",a="Лепритус — печально известный вурдалак, бродящий по скалам Холмов Разбойничьих Кинжалов и пугающий всех путников и бандитов, которым не повезло встретить его в темноте.",al={"leprithus spawn","ghoul in dagger hills","dagger hills undead","лепритус","вурдалак на холмах разбойничьих кинжалов","нежить холмов разбойничьих кинжалов"}}},fp="12,278,14.431.0,20.444.0,35.130.0,30.151.0,36.172.0,18.160.0"}
P.entries["subzone:dandred-s-fold"] = {n="Овчарня Дандреда",s="Овчарня Дандреда — уединенная ферма с усадьбой на туманном северо-западном берегу озера Лордамер в Альтеракских горах. Сейчас она захвачена Синдикатом и служит надежным убежищем для лорда Алидена Перенольда и его сообщников. И Орда, и Альянс пристально следят за этим прибрежным укрытием, но по совсем разным причинам.",h="Овчарня Дандреда — уединенная ферма с усадьбой на туманном северо-западном берегу озера Лордамер в...",kw={"aliden perenolde","argus wake","dandred's fold","dandreds fold","elysa","lordamere lake","nagaz","syndicate","uplands","алиден перенольд","пробуждение аргуса","овчарня дандреда","элиза","озеро лордамер","нагаз","синдикат","высокогорье"},ang={["faction:Alliance"]="Альянс не может мириться с союзом людей-преступников и демонического Пробуждения Аргуса, поэтому мировой судья Генри Малеб приказал нанести по поместью точечные удары.",["faction:Horde"]="Для Орды проникновение в Овчарню Дандреда — дело глубоко личное. Вождь Тралл стремится вернуть ожерелье Тареты Фокстон."},sec={{t="Благородное убежище в руках преступников",b="Овчарня Дандреда расположена на западном краю Высокогорья и имеет собственный выход к водам озера Лордамер. Когда-то это было тихое загородное поместье, вероятно принадлежавшее альтеракскому дворянину по имени Дандред. После падения королевства поместье превратилось в укрепленный оплот Синдиката. Убийцы и головорезы Синдиката патрулируют его ограды и причалы, скрывая павшую знать от глаз властей Южнобережья и Отрекшихся на другом берегу озера."},{t="Узел интриг",b="За закрытыми дверями усадьбы зреют опасные заговоры. Лорд Алиден Перенольд, признанный предводитель Синдиката, устроил в Овчарне Дандреда свою базу вместе с возлюбленной, Элизой. Но преступники здесь не одни: отступник из Совета Теней, орк по имени Нагаз из Пробуждения Аргуса, тоже обосновался здесь и заключает темные сделки с людьми-разбойниками. Из-за этого опасного союза Овчарня Дандреда стала целью и для судей Южнобережья, и для бойцов Орды."}},faq={{q="Кто управляет Овчарней Дандреда?",a="Поместье занято Синдикатом — аристократической преступной сетью, во главе которой стоят низложенные дворяне Альтерака. Убийцы и головорезы Синдиката охраняют территорию, подчиняясь лорду Алидену Перенольду.",al={"who is at dandreds fold","who lives at dandred's fold","dandreds fold mobs","кто в овчарне дандреда","кто живет в овчарне дандреда","мобы овчарни дандреда"}},{q="Почему Орду интересует это поместье?",a="Орда нацеливается на усадьбу, чтобы расправиться с лордом Алиденом Перенольдом и вернуть украденную памятную вещь — фамильное ожерелье, некогда принадлежавшее Тарете Фокстон, спасительнице и наперснице детства Тралла.",al={"horde dandreds fold","why horde go to dandreds fold","орда овчарня дандреда","зачем орде в овчарню дандреда"}},{q="Зачем Альянс посылает сюда искателей приключений?",a="Мировой судья Генри Малеб из Южнобережья направляет сюда агентов Альянса, чтобы уничтожить Нагаза — опасного члена культа Пробуждения Аргуса, сговорившегося с преступниками Синдиката.",al={"alliance dandreds fold","magistrate maleb quest dandreds fold","альянс овчарня дандреда","мировой судья малеб задание овчарня дандреда"}},{q="Кем был Дандред?",a="Кто такой Дандред, неизвестно. Поместье носит это имя, но подтвержденных сведений о его первом владельце нет.",al={"who is dandred","dandred lore","кто такой дандред","дандред предания"}}},fp="14,352,36.473.0,20.477.1,28.201.0,42.198.0,44.172.0,16.121.0"}
P.entries["subzone:dark-portal"] = {n="Темный портал",s="Темный портал — монументальные каменные врата на южной окраине Выжженных земель. Впервые раскрытый совместной магией Медива и Гул'дана, он стал роковым проходом, через который Старая Орда попала в Азерот, положив начало Первой войне.",h="Темный портал — монументальные каменные врата на южной окраине Выжженных земель.",kw={"black morass","blasted lands","dark portal","draenor","great portal","guldan","khadgar","medivh","черные топи","выжженные земли","темный портал","дренор","великий портал","гул'дан","кадгар","медив"},ang={["faction:Alliance"]="Для Альянса портал — торжественный памятник Первой войне и падению древнего Штормграда, и потому маги Крепости Стражей Пустоты несут здесь вечную стражу.",["race:Orc"]="Портал — мучительный порог прошлого вашего народа: врата, через которые Старая Орда шла в рабстве у демонических владык, оставив родной мир ради войны."},sec={{t="Разлом между мирами",b="До его открытия эта область была частью Черных топей — сырой болотистой местности на юге. Все изменилось, когда Медив, одержимый Саргерасом, соединил свою магию Тирисфаля со скверной чародейства Гул'дана на Дреноре. Ритуал поглотил бесчисленные жизни и разорвал ткань реальности. Старая Орда возвела громадное каменное сооружение, чтобы удержать разлом, и провела через него армии, разрушившие королевство Штормград в Первой войне. Эманации скверны портала необратимо исказили окрестные земли, превратив цветущие болота в красные окаменевшие пустоши, какими мы видим их сегодня."},{t="Спящая бдительность",b="После победы Альянса Лордерона во Второй войне верховный маг Кадгар мощной магией разрушил каменную раму, надеясь навсегда отсечь Дренор. Однако пространственный разрыв под ней оказался, по сути, неуничтожимым. Альянс возвел поблизости Крепость Стражей Пустоты, чтобы наблюдать за шрамом, а демоны и остатки Совета Теней по-прежнему проскальзывают по выжженной кальдере. Сегодня врата вновь собраны, но спят — безмолвный шрам между мирами, который ни одна из сторон не решается покинуть."}},faq={{q="Можно ли сейчас пройти через Темный портал?",a="Нет. Каменная рама врат цела, но разлом внутри спит. В настоящее время никто не может пройти через него.",al={"can i enter the dark portal","is dark portal open","portal to outland","можно ли войти в темный портал","открыт ли темный портал","портал в запределье"}},{q="Кто изначально построил Темный портал?",a="Он был создан совместным ритуалом человека-Хранителя Медива в Азероте и чернокнижника Гул'дана на умирающем Дреноре, организовавших вторжение, которое разожгло Первую войну.",al={"who created dark portal","medivh guldan portal","dark portal creators","кто создал темный портал","медив гул'дан портал","создатели темного портала"}},{q="Почему Крепость Стражей Пустоты охраняет его?",a="После того как верховный маг Кадгар разрушил первоначальную раму портала после Второй войны, он убедил Альянс наблюдать за его руинами. Альянс основал Крепость Стражей Пустоты, чтобы постоянно следить за этим местом на случай новых угроз.",al={"why is nethergarde keep here","nethergarde portal watch","why nethergarde","почему здесь крепость стражей пустоты","крепость стражей пустоты охрана портала","зачем крепость стражей пустоты"}},{q="Почему земля вокруг портала красная и бесплодная?",a="Выжженные земли когда-то были плодородным болотом, известным как Черные топи. Огромная энергия скверны, нужная для пролома в реальности, а также порча, шедшая из Дренора, и демонические твари отравили почву и обратили экосистему в камень.",al={"why are blasted lands dead","portal corruption","why is blasted lands red","почему выжженные земли мертвы","порча портала","почему выжженные земли красные"}}},fp="11,264,23.601.0,17.516.0,47.126.0,37.192.0,40.257.0,51.236.0"}
P.entries["subzone:darkcloud-pinnacle"] = {n="Пик Темного Облака",s="Пик Темного Облака — укрепленное поселение тауренов на вершинах нескольких соединенных плато к востоку от Великого Подъемника в Тысяче Игл. Воинственный клан Зловещего Тотема удерживает эту воздушную крепость и использует ее как базу для диверсий в округе и темных дел.",h="Пик Темного Облака — укрепленное поселение тауренов на вершинах нескольких соединенных плато к востоку от...",kw={"arnak grimtotem","darkcloud pinnacle","grimtotem","harb foulmountain","mesa","thousand needles","арнак зловещий тотем","пик темного облака","зловещий тотем","харб оскверненная гора","плато","тысяча игл"},ang={["faction:Horde"]="Зловещий Тотем, занявший это плато, настроен враждебно и угрожает путникам, идущим от Великого Подъемника вглубь Тысячи Игл.",["race:Tauren"]="Вероломное поведение Зловещего Тотема на этих плато резко противоречит единству и миру между племенами, которые стремится сохранить Кэрн Кровавое Копыто."},sec={{t="Крепость на утесе",b="Пик Темного Облака раскинулся на трех главных плато, соединенных веревочными мостами, и господствует над долиной внизу. На вершины можно попасть только по крутому природному склону со дна каньона через деревянные мосты или по высокому переходу возле Курганов Иглошкурых. С этих продуваемых ветрами скал Зловещий Тотем наблюдает за долиной, защищенный от случайных нападений и отрезанный от остальных племен тауренов."},{t="Замыслы на плато",b="Поселением, которым управляют такие вожди, как Арнак Зловещий Тотем и Харб Оскверненная Гора, — это не просто застава. Тайная переписка, найденная на плато, говорит о том, что Зловещий Тотем активно сотрудничает с темными неведомыми силами, преследуя цели, далекие от мира, созданного Кэрном Кровавым Копытом в Громовом Утесе."}},faq={{q="Кто управляет Пиком Темного Облака?",a="Крепость принадлежит клану Зловещего Тотема — воинственной и замкнутой фракции тауренов, открыто враждебной к большинству чужаков и глубоко подозрительной к Орде.",al={"who lives at darkcloud pinnacle","darkcloud pinnacle owners","who is at darkcloud pinnacle","кто живет на пике темного облака","владельцы пика темного облака","кто на пике темного облака"}},{q="Как добраться до Пика Темного Облака?",a="На пик можно подняться по природному пандусу на соседнее плато со дна каньона и пройти по деревянным веревочным мостам либо по мосту возле Курганов Иглошкурых.",al={"how to get up darkcloud pinnacle","darkcloud pinnacle path","entrance to darkcloud pinnacle","как подняться на пик темного облака","путь к пику темного облака","вход на пик темного облака"}},{q="Кто возглавляет Зловещий Тотем здесь?",a="За делами поселения следят видные представители Зловещего Тотема, включая Арнака Зловещего Тотема и Харба Оскверненную Гору.",al={"darkcloud pinnacle leaders","who leads darkcloud pinnacle","grimtotem bosses","лидеры пика темного облака","кто возглавляет пик темного облака","боссы зловещего тотема"}},{q="Что замышляет здесь Зловещий Тотем?",a="Зловещий Тотем на пике поддерживает тайную связь с неведомой темной силой и стремится к туманным целям, угрожающим спокойствию Тысячи Игл.",al={"what is happening at darkcloud pinnacle","grimtotem conspiracy","что происходит на пике темного облака","заговор зловещего тотема"}}},fp="18,273,21.385.0,20.328.1,32.157.0,36.177.0,29.121.0,37.170.0"}
P.entries["subzone:darkened-bank"] = {n="Темный берег",s="Темный берег — северное побережье Сумеречного леса вдоль реки, отделяющей затененные чащи от Элвиннского леса. Он тянется с дальнего запада на восток к Красногорью и отмечает границу между относительной безопасностью севера и темными ужасами леса.",h="Темный берег — северное побережье Сумеречного леса вдоль реки, отделяющей затененные чащи от Элвиннского леса.",kw={"darkened bank","duskwood","elwynn forest","lars","river","shoreline","sven yorgen","темный берег","сумеречный лес","элвиннский лес","ларс","река","берег","свен йорген"},ang={["faction:Alliance"]="Для искателей приключений Альянса, покидающих Элвиннский лес, Темный берег служит первым плацдармом перед походом вглубь населенного призраками сердца Сумеречного леса."},sec={{t="Шаткая граница",b="Темный берег проходит по южному берегу реки напротив Элвиннского леса и образует северный край Сумеречного леса. Он тянется от западных излучин реки на восток к каменному мосту, ведущему в Красногорье. Хотя под вездесущим пологом проклятия Сумеречного леса здесь мрачно, этот берег часто становится первым оплотом для путников, идущих на юг из Элвинна. Возле его дальней западной оконечности стоит временный лагерь, где нашли приют беженцы, среди которых Свен Йорген и Ларс — едва вне досягаемости глубокого леса."}},faq={{q="Где находится Темный берег?",a="Темный берег тянется вдоль всего северного берега Сумеречного леса по реке, прямо напротив Элвиннского леса. Он простирается от дальнего западного края зоны на восток до моста в Красногорье.",al={"darkened bank location","where is darkened bank","darkened bank duskwood","где темный берег","расположение темного берега","темный берег сумеречный лес"}},{q="Кто живет на Темном берегу?",a="На дальнем западном краю берега стоит скромный лагерь беженцев, в котором живут Свен Йорген и Ларс. Изгнанные из прежней жизни в глубине края, они используют этот северный берег реки как хрупкое убежище, ища помощи против угроз Сумеречного леса.",al={"camp on darkened bank","who is at darkened bank","darkened bank npcs","лагерь на темном берегу","кто на темном берегу","персонажи темного берега"}},{q="Как путники обычно добираются до этого места?",a="Travelers can easily reach the western stretch of the Darkened Bank by swimming south across the river from the southwestern reaches of Elwynn Forest, or by following the southern riverbank west from the Redridge bridge.",al={"how to get to darkened bank","getting to darkened bank","как добраться до темного берега","путь к темному берегу"}}},fp="13,306,21.557.0,35.242.0,34.259.0,41.220.0"}
P.entries["subzone:darkmist-cavern"] = {n="Мглистая пещера",s="Мглистая пещера — заброшенная шахта на северо-западе Пылевых топей, полностью кишащая хищными гигантскими пауками. Рассыпающиеся руины снаружи намекают на несчастливое поселение, поглощенное опасностями болота. Местные до сих пор спорят, дала ли пещера имя паукам или наоборот.",h="Мглистая пещера — заброшенная шахта на северо-западе Пылевых топей, полностью кишащая хищными гигантскими...",kw={"darkmist cavern","darkmist spiders","dustwallow marsh","mine ruins","spider mine","swamp eye jarl","мглистая пещера","мглистые пауки","пылевые топи","руины шахты","паучья шахта","ярл болотный глаз"},ang={["profession:Cooking"]="Чудаковатый отшельник Ярл «Болотный Глаз» считает мерзкие глаза мглистых пауков главным ингредиентом сытного болотного рагу, хотя за пределами топей его вкус разделяют немногие.",["profession:Mining"]="Пещеру явно выдолбили прежние шахтеры, но тем, кто захочет разведать ее каменные глубины, сначала придется пробиться через полчища гнездящихся пауков."},sec={{t="Выводок в шахте",b="Мглистая пещера, расположенная на северо-западе Пылевых топей, когда-то, судя по всему, была действующей шахтой. Сегодня следов людей давно нет: остались гниющие разрушенные лачуги у входа и сеть туннелей, забитых плотной паутиной. Пещеру заполонили мглистые пауки — хищные чудовища, чей яд и размеры делают туннели смертельными для неосторожных. Жители топей до сих пор спорят, названа ли пещера по мерзкому выводку внутри или пауки получили имя от самой туманной пещеры."},{t="Кладовая отшельника",b="Несмотря на очевидную опасность, пещера привлекает случайных собирателей и чудаковатых жителей топей. Отшельник Ярл «Болотный Глаз» известен тем, что отправляет путников вглубь паутины за глазами этих чудовищных пауков, уверяя, что из них выходит отличная основа для бульона. Помимо таких странных кулинарных вылазок, большинство здравомыслящих путников обходят заваленный паутиной вход стороной."}},faq={{q="Что такое Мглистая пещера?",a="Это заброшенная шахта на северо-западе Пылевых топей, полностью захваченная гигантскими ядовитыми пауками, известными как мглистые пауки.",al={"what is darkmist cavern","darkmist cave","spider cave dustwallow","что такое мглистая пещера","пещера мглы","пещера пауков пылевые топи"}},{q="Кто жил в руинах возле пещеры?",a="Небольшие деревянные руины говорят о том, что здесь когда-то находилось поселение или шахтерский лагерь, но кто в нем жил, неизвестно.",al={"who lived here","houses outside darkmist cavern","abandoned village darkmist","кто здесь жил","дома у мглистой пещеры","заброшенная деревня мглистая пещера"}},{q="Зачем местные жители идут в Мглистую пещеру?",a="Мало кто идет туда по своей воле, но чудаковатый отшельник Ярл «Болотный Глаз» нанимает смельчаков, чтобы они спускались в туннели и приносили паучьи глаза для его странного болотного рагу.",al={"why go to darkmist cavern","darkmist cavern quest","зачем идти в мглистую пещеру","задание мглистая пещера"}},{q="Что появилось раньше: имя пауков или пещеры?",a="Жители Пылевых топей спорят, назвали ли пауков по пещере или пещеру по паукам. Устоявшихся сведений о том, какое название появилось первым, нет.",al={"spider name origin","why is it called darkmist","происхождение названия пауков","почему называется мглистая"}}},fp="15,322,21.557.0,15.381.0,24.155.0,40.125.0,43.179.0,49.182.0"}
P.entries["subzone:darkshire-town-hall"] = {n="Ратуша Темнолесья",s="Ратуша Темнолесья стоит на западном краю городской площади и является местом местного управления в Сумеречном лесу. Из этих тускло освещенных залов мэр лорд Элло Чернодрев и его совет пытаются управлять поселением, осажденным ползущей тьмой и чудовищной нежитью.",h="Ратуша Темнолесья стоит на западном краю городской площади и является местом местного управления в Сумеречном...",kw={"clerk daltry","council","darkshire","duskwood","ello ebonlocke","town hall","клерк далтри","совет","темнолесье","сумеречный лес","элло чернодрев","ратуша"},ang={["faction:Alliance"]="Для путников из Альянса Ратуша олицетворяет хрупкую власть королевства на южных рубежах и показывает, насколько тонко защита Штормграда растянута по отдаленным поселениям."},sec={{t="Средоточие власти Темнолесья",b="Ратуша расположена к западу от главной городской площади, и именно здесь собирается гражданское руководство Темнолесья, чтобы управлять все более изолированной землей. В ее обветшалых стенах сидит мэр лорд Элло Чернодрев, пытающийся сохранить порядок и защитить население, пока Штормград почти не оказывает военной помощи. Рядом с мэром городские чиновники, такие как Клерк Далтри, ведут местные записи и учет путников, рискующих ехать по опасным дорогам Сумеречного леса, хотя вести книги в актуальном виде в такие опасные времена тяжело и трудно."}},faq={{q="Кто управляет городом из этого здания?",a="Лорд Элло Чернодрев служит мэром Темнолесья и председательствует в городском совете в Ратуше. Он руководит местной обороной и просит помощи у приезжих искателей приключений, так как городок почти не получает подкреплений из столицы королевства.",al={"who is the mayor","who runs darkshire","who is in the town hall","кто мэр","кто управляет темнолесьем","кто в ратуше"}},{q="Какие записи хранятся в Ратуше?",a="Клерк Далтри ведет городские реестры жителей и путников, проезжающих через Темнолесье. Из-за хаоса и частых опасностей в Сумеречном лесу многие его журналы и записи несколько устарели.",al={"clerk daltry records","what does daltry do","town registry","записи клерка далтри","чем занимается далтри","городской реестр"}},{q="Почему Ратуша так важна для выживания Сумеречного леса?",a="Поскольку Сумеречный лес отрезан от прямой военной поддержки Штормграда, Ратуша служит оперативным центром для Ночного Дозора и местных властей. Здесь совет координирует гражданскую оборону и направляет помощь по всему мрачному краю.",al={"why does the town hall matter","darkshire council role","почему важна ратуша","роль совета темнолесья"}}},fp="19,278,21.556.0,38.263.0,43.229.0,57.255.0"}
P.entries["subzone:darkspear-strand"] = {n="Побережье Черного Копья",s="Побережье Черного Копья — участок береговой линии на юге Дуротара, где тролли Черного Копья выбросились на берег после изгнания с Островов Эха. Расположенный рядом с Деревней Сен'джин, этот пляж стал горьким началом убежища племени на материке под предводительством Вол'джина.",h="Побережье Черного Копья — участок береговой линии на юге Дуротара, где тролли Черного Копья выбросились на...",kw={"darkspear","darkspear strand","durotar","echo isles","sen'jin village","vol'jin","zalazane","черное копье","побережье черного копья","дуротар","острова эха","деревня сен'джин","вол'джин","залазан"},ang={["faction:Horde"]="Побережье на юге отмечает место, где тролли Черного Копья закрепились на материке Калимдора рядом со своими союзниками-орками, потеряв островное поселение.",["race:Troll"]="Для троллей Черного Копья ступить на этот берег — значит ощутить боль предательства Залазана и горько-сладкую память о спасении жизни и основании Деревни Сен'джин."},sec={{t="Берег изгнания",b="Когда колдун Залазан сошел с ума и захватил власть на Островах Эха, выжившие тролли Черного Копья были вынуждены покинуть свой островной дом. Отчаявшиеся беженцы пересекли узкий пролив и высадились на этом выбеленном солнцем берегу. Вместо того чтобы рассеяться по враждебным красным пустошам Дуротара, выжившие объединились в нескольких ярдах от береговой линии и построили Деревню Сен'джин. Сегодня побережье тихо напоминает об их изгнании и смотрит через прибой на острова, которые они все еще надеются вернуть."}},faq={{q="Что произошло на Побережье Черного Копья?",a="На этом побережье тролли Черного Копья высадились после бегства с Островов Эха. Когда Залазан обратил темную магию против собственного народа, выжившие переправились через воду и вышли на берег здесь, сразу же собравшись неподалеку, чтобы основать Деревню Сен'джин.",al={"why is it called darkspear strand","darkspear strand lore","what is this beach","почему называется побережье черного копья","побережье черного копья предания","что это за пляж"}},{q="Почему тролли Черного Копья покинули Острова Эха?",a="Колдун Залазан предал своих сородичей и с помощью темного вуду поработил разум соплеменников. Вождь Вол'джин вывел оставшихся незатронутых троллей Черного Копья с островов, чтобы избежать полного порабощения, и они высадились на этом берегу.",al={"why did trolls leave echo isles","zalazane exile","echo isles evacuation","почему тролли покинули острова эха","изгнание залазана","эвакуация с островов эха"}},{q="Какое поселение находится рядом с Побережьем Черного Копья?",a="Деревня Сен'джин находится в нескольких ярдах от пляжа вглубь суши. Ее основали беженцы сразу после высадки на берег, и она служит главным оплотом и духовным центром Черного Копья в Дуротаре.",al={"village near darkspear strand","town next to beach","sen'jin village location","деревня рядом с побережьем черного копья","город рядом с пляжем","где деревня сен'джин"}}},fp="16,286,16.539.0,34.270.0,43.233.0,52.206.0"}
P.entries["subzone:darkwhisper-gorge"] = {n="Теснина Зловещего Шепота",s="Теснина Зловещего Шепота — коварное ущелье, кишащее демонами, в южных возвышенностях Зимних Ключей. Когда Архимонд был уничтожен в кульминации Третьей войны, остатки разбитого Пылающего Легиона бежали вниз по склонам Горы Хиджал и укрепились в этих зубчатых расщелинах. Сегодня могущественные демоны бродят по ее высотам, охраняя древние минералы и темные реликвии иных миров.",h="Теснина Зловещего Шепота — коварное ущелье, кишащее демонами, в южных возвышенностях Зимних Ключей.",kw={"burning legion","darkwhisper gorge","earthcaller franzahl","eye of shadow","hederine","lady hederine","mount hyjal","vi'el","winterspring","пылающий легион","теснина зловещего шепота","призыватель земли франзаль","глаз тени","хедерин","леди хедерин","гора хиджал","ви'эль","зимние ключи"},ang={["class:Warlock"]="Демоны-хедерин, бродящие по этим пещерам, владеют важными планарными компонентами, поэтому теснина — главное испытательное поле для чернокнижников, стремящихся овладеть великими ритуалами призыва, например Стражем Рока.",["profession:Mining"]="Опасные расщелины скрывают обильные залежи истинного серебра и богатые жилы тория, награждая шахтеров, достаточно смелых, чтобы прокрасться мимо элитных демонов."},sec={{t="Оплот Легиона в снегах",b="После поражения Архимонда на вершине Горы Хиджал уцелевшие демоны Пылающего Легиона разбрелись по окрестным горам. Дисциплинированный авангард укрылся в Теснине Зловещего Шепота и превратил южную границу Зимних Ключей в смертоносную крепость. Под предводительством демонов-хедерин, среди которых смертоносные охотники за маной, убийцы и посвященные под началом леди Хедерин, они яростно защищают свои подземные туннели и огненные лагеря. Помимо угрозы от элитных обитателей, в самой нижней точке теснины стоит зловещая запечатанная арка, намекающая на запечатанные проходы выше по священной горе."},{t="Скрытые реагенты и редкие знания",b="Несмотря на огромную опасность, храбрые искатели приключений и дельцы отваживаются спускаться в теснину ради ее исключительных богатств. Ущелья богаты ценными минералами, такими как истинное серебро, и плотными залежами тория. В глубине ее затененных гротов обитают необычные существа: бес-торговец Ви'эль, продающий оскверненные реагенты, такие как оскверненная ткань и кровь Грома, и неуловимый высший эльф Заклинатель земли Франзал, обладающий древними знаниями о металлургии и плавке редкого элементия."}},faq={{q="Почему в Зимних Ключах так много демонов?",a="Демоны в Теснине Зловещего Шепота — выжившие после вторжения Пылающего Легиона на Гору Хиджал во время Третьей войны. После того как Архимонд был убит у Мирового Древа, его разбитые силы отступили в эти расщелины, чтобы перегруппироваться, а не были уничтожены полностью.",al={"why demons here","darkwhisper legion lore","where did the demons come from","почему здесь демоны","легион зловещего шепота предания","откуда взялись демоны"}},{q="Что за запечатанные врата в глубине теснины?",a="В глубине южной части теснины стоят арка с рунами и действующий магический барьер. Он охраняет горный проход, ведущий прямо на Гору Хиджал, и не пускает смертных на священные высоты, пока гора оправляется от демонического нападения.",al={"darkwhisper portal","instance portal winterspring","hyjal gate","портал зловещего шепота","портал подземелья зимние ключи","врата хиджала"}},{q="Кто здесь командует демонами?",a="Лагерем заправляет секта демонических захватчиков, известных как хедерин, по-видимому, под началом леди Хедерин. Они патрулируют ущелья вместе с убийцами, посвященными и гончими Скверны, известными как охотники за маной.",al={"darkwhisper boss","hederine leader","who rules darkwhisper","босс зловещего шепота","вожак хедерин","кто правит зловещим шепотом"}},{q="Зачем искателю приключений отправляться в Теснину Зловещего Шепота?",a="Местность исключительно опасна, и безопасно пройти ее могут лишь слаженные группы. Тем не менее она привлекает чернокнижников, ищущих планарные привязки, жрецов, охотящихся за редким Глазом Тени, кузнецов и шахтеров, ищущих богатые жилы тория, и ученых, разыскивающих скрытого Заклинателя земли Франзала.",al={"why go to darkwhisper","darkwhisper quests","darkwhisper rewards","зачем идти в зловещий шепот","задания зловещего шепота","награды зловещего шепота"}}},fp="17,388,29.628.0,34.498.0,45.261.0,49.257.0,26.211.0,55.285.0"}
P.entries["subzone:darnassus"] = {n="Дарнасс",s="Высоко среди раскидистых ветвей Тельдрассила стоит Дарнасс — столица-убежище кальдораев. Построенный у тихих вод и зеленых рощ, он служит духовным сердцем ночных эльфов и главным оплотом Альянса на севере Калимдора. Отсюда верховная жрица Тиранда Шелест Ветра и верховный друид Фэндрал Олений Шлем ведут свой народ через испытания обретенной смертности.",h="Высоко среди раскидистых ветвей Тельдрассила стоит Дарнасс — столица-убежище кальдораев.",kw={"capital","darnassus","kaldorei","staghelm","teldrassil","temple of the moon","tyrande","столица","дарнасс","кальдораи","олений шлем","тельдрассил","храм луны","тиранда"},ang={["faction:Alliance"]="Для путников из Восточных королевств Дарнасс — уединенная тихая гавань и важнейший оплот Альянса на континенте Калимдор.",["race:NightElf"]="Дарнасс — культурная и политическая столица кальдораев, новое начало и суверенное убежище вашего народа после тяжелых жертв Третьей войны."},sec={{t="Убежище в ветвях",b="Дарнасс был построен после Третьей войны в честь выживания ночных эльфов после утраты бессмертия, которое даровало их священное Мировое Древо, Нордрассил. В отличие от плотных каменных городов вроде Стальгорна или Штормграда, Дарнасс — открытое, тихое поселение из деревянных домов, светящихся святилищ и арочных мостов над хрустальными озерами. Бдительные Часовые, могучие древние воители и друиды, придающие деревьям форму, охраняют дороги, сохраняя мирную тишину природы в пределах города."},{t="Разделенное руководство",b="Хотя Дарнасс воплощает единство кальдораев, в его управлении заметны тонкие разломы. Верховная жрица Тиранда Шелест Ветра ведает гражданскими и военными делами из сияющего Храма Луны в окружении Сестер Элуны. Дела Круга Кенария тем временем находятся в ведении верховного друида Фэндрала Оленьего Шлема, который выступал за посадку Тельдрассила ради возвращения эльфам утраченного бессмертия. Поскольку Малфурион Ярость Бури погружен в загадочный сон глубоко в Изумрудном Сне, напористое видение будущего у Оленьего Шлема часто порождает разногласия с более терпеливым жречеством."}},faq={{q="Кто правит Дарнассом?",a="Верховная жрица Тиранда Шелест Ветра руководит обществом ночных эльфов из Храма Луны и командует Часовыми. Делами друидов ведает верховный друид Фэндрал Олений Шлем, возглавляющий Круг Кенария в отсутствие Малфуриона Ярость Бури.",al={"darnassus leader","who is in charge of darnassus","night elf leader","правитель дарнасса","кто главный в дарнассе","лидер ночных эльфов"}},{q="Как путешественникам добраться до Дарнасса за пределами Тельдрассила?",a="Поскольку Дарнасс расположен на огромных ветвях острова Мирового Древа, корабли и маршруты полета ведут только в Деревню Рут'теран у подножия дерева. Оттуда магический портал переносит посетителей в сам город.",al={"how to get to darnassus","darnassus entrance","getting into darnassus","как попасть в дарнасс","вход в дарнасс","дорога в дарнасс"}},{q="Почему Дарнасс основан так недавно?",a="После разрушений на Горе Хиджал во время Третьей войны ночные эльфы лишились бессмертия и своего древнего уклада. Фэндрал Олений Шлем и его союзники посадили Тельдрассил у берегов Калимдора, и на его ветвях укоренился Дарнасс как новое убежище для их народа.",al={"why is darnassus new","when was darnassus built","darnassus age","почему дарнасс новый","когда построен дарнасс","возраст дарнасса"}},{q="Где Малфурион Ярость Бури?",a="Верховный друид Малфурион Ярость Бури пропал: его дух заперт в глубоком необъяснимом сне в Изумрудном Сне. Из-за его отсутствия руководство Кругом Кенария в Дарнассе полностью лежит на Фэндрале Оленьем Шлеме.",al={"where is malfurion","is malfurion in darnassus","malfurion status","где малфурион","малфурион в дарнассе","судьба малфуриона"}}},fp="9,392,23.569.0,20.599.0,20.268.0,57.227.0,38.291.0,29.213.0"}
P.entries["subzone:darrow-hill"] = {n="Холм Дарроу",s="Холм Дарроу — возвышенная равнина с суровыми лугами на севере Предгорий Хилсбрада, прямо под Мысом. Пока горные львы и олени пасутся на его открытых склонах, дикие йети таятся в Пещерах предгорий, изрывших склон. Богатый жилами Альтеракского гранита, он служит опасным рубежом, где постоянно сталкиваются звери и соперничающие путники.",h="Холм Дарроу — возвышенная равнина с суровыми лугами на севере Предгорий Хилсбрада, прямо под Мысом.",kw={"alterac granite","darrow hill","foothill caverns","headland","hillsbrad foothills","yetis","альтеракский гранит","холм дарроу","пещеры предгорий","мыс","предгорья хилсбрада","йети"},ang={["class:Hunter"]="Холмы служат прекрасными охотничьими угодьями для горных львов и оленей, перемещающихся между опушкой Альтерака и нижними лугами.",["profession:Mining"]="Сети пещер Холма Дарроу, особенно Пещеры предгорий, богаты Альтеракским гранитом и местными рудными жилами — если вы справитесь с йети, гнездящимися поблизости."},sec={{t="Опасный рубеж",b="Холм Дарроу поднимается у подножия северных гор под Мысом и соединяет холмистые пастбища южного Хилсбрада с острыми, более холодными высотами Альтерака. Горные львы и олени бродят в высокой траве, деля скалистые склоны с громадными йети, выходящими из Пещер предгорий. Помимо диких зверей, стены пещер скрывают залежи плотного Альтеракского гранита, и каменотесы, шахтеры и искатели приключений идут прямо навстречу опасности. Из-за спорных притязаний региона тропы остаются крайне опасными для путников обеих фракций, застигнутых врасплох."}},faq={{q="Где находится Холм Дарроу?",a="Холм Дарроу лежит на севере Предгорий Хилсбрада, сразу к югу от скалистых утесов, известных как Мыс, и к востоку от главной горной дороги в Альтерак.",al={"darrow hill location","where is darrow hill","darrow hill map","где холм дарроу","расположение холма дарроу","карта холма дарроу"}},{q="Какие существа угрожают путникам у Холма Дарроу?",a="По открытым склонам бродят олени и горные львы, а свирепые йети обитают вокруг Пещер предгорий и внутри них.",al={"darrow hill mobs","what lives on darrow hill","monsters darrow hill","монстры холма дарроу","кто живет на холме дарроу","мобы холма дарроу"}},{q="Что можно найти в Пещерах предгорий?",a="Пещеры предгорий населены дикими йети, а в их каменных стенах залегают жилы ценного Альтеракского гранита.",al={"foothill caverns","darrow hill cave","what is in the cave","пещеры предгорий","пещера холма дарроу","что в пещере"}},{q="Почему эта местность считается такой опасной для путников?",a="Помимо свирепых зверей и логовищ йети, открытая местность рядом со спорными дорогами сделала Холм Дарроу известным местом стычек, где странники Альянса и Орды часто устраивали друг другу засады.",al={"why is darrow hill dangerous","darrow hill pvp","danger at darrow hill","почему опасен холм дарроу","пвп на холме дарроу","опасность холма дарроу"}}},fp="11,385,22.608.0,29.181.0,53.134.0,46.129.0,55.213.0"}
P.entries["subzone:darrowmere-lake"] = {n="Озеро Дарроумир",s="Озеро Дарроумир — обширное пресноводное озеро на юго-востоке Западных Чумных земель. В его центре лежит островная крепость Каэр Дарроу, в чьих разрушенных залах скрыта жуткая некромантская академия Культа Проклятых — Некроситет.",h="Озеро Дарроумир — обширное пресноводное озеро на юго-востоке Западных Чумных земель.",kw={"barov","caer darrow","darrowmere","darrowmere lake","proudmoore fleet","scholomance","thondroril river","western plaguelands","баровы","каэр дарроу","дарроумир","озеро дарроумир","флот праудмура","некроситет","река тондрорил","западные чумные земли"},ang={["faction:Alliance"]="Для ветеранов Альянса озеро Дарроумир памятно как ключевой морской фронт, где флот Праудмура сражался, чтобы остановить Старую Орду и освободить Стратхольм во время Второй войны.",["race:Undead"]="Озеро отмечает порог Каэр Дарроу, где живые Баровы отдали свой смертный дом Королю-личу, чтобы создать жуткую академию Некроситет."},sec={{t="Легендарное внутреннее море",b="Озеро Дарроумир — одно из крупнейших внутренних водоемов Восточных королевств; его окружают пораженные порчей леса Лордерона, а питают реки Тондрорил и Дарроумир. Во время Второй войны в этих глубоких водах шли ожесточенные морские стычки между Ордой и флотом верховного адмирала Даэлина Праудмура. Транспорты Праудмура перевозили по озеру лидеров Альянса Туралиона и Аллерию Ветрокрылую для освобождения Стратхольма, и именно на этих берегах был захвачен предводитель лесных троллей Зул'джин. Некогда оживленный водный путь и торговая артерия дома Баровых, ныне озеро — мрачная, окутанная туманом котловина в сердце Чумных земель."},{t="Тень на водах",b="Центр озера занимает Каэр Дарроу, некогда гордая родовая обитель семьи Баровых. Под его разрушенными основаниями лежит Некроситет — главная академия Плети по некромантии и темным искусствам. Воды вокруг острова застойны и опасны, отражая мрачное наследие Культа Проклятых. Искателям приключений, пересекающим озеро, приходится противостоять не только опасностям зараженных земель, но и всепроникающему ужасу крепости в его сердце."}},faq={{q="Где находится Озеро Дарроумир?",a="Озеро Дарроумир находится в юго-восточном углу Западных Чумных земель; к северу в него впадает Река Тондрорил, а к югу вытекает река Дарроумир.",al={"darrowmere location","where is darrowmere lake","how to get to darrowmere","где дарроумир","где озеро дарроумир","как добраться до дарроумира"}},{q="Что находится на острове в центре озера?",a="На острове расположен Каэр Дарроу — древнее поселение, некогда управляемое знатным домом Баровых. Под разрушенным городом лежит Некроситет — огромная школа темной магии, которой управляет Культ Проклятых.",al={"island in darrowmere","what is on the island","caer darrow location","остров в дарроумире","что на острове","где каэр дарроу"}},{q="Какую роль озеро Дарроумир сыграло во Второй войне?",a="Озеро было спорным водным путем, где флот Праудмуров сражался с Ордой. Транспорты перевозили по озеру войска Туралиона и Аллерии к Стратхольму, а вблизи его берегов был захвачен троллий предводитель Зул'джин.",al={"second war darrowmere","naval battles darrowmere","darrowmere history","вторая война дарроумир","морские сражения дарроумир","история дарроумира"}},{q="Могут ли корабли до сих пор заходить в озеро Дарроумир?",a="Хотя во время Второй войны по озеру ходили большие флоты, соединяющие его реки теперь имеют крутые водопады и мелководья, не позволяющие большим судам заходить с моря.",al={"darrowmere boat access","can ships reach darrowmere","корабли на дарроумире","могут ли корабли дойти до дарроумира"}}},fp="15,258,20.663.0,24.493.0,33.173.0,48.202.0,53.243.0,42.196.0"}
P.entries["subzone:darrowshire"] = {n="Дарроушир",s="Дарроушир — разрушенная деревня в южных холмах Восточных Чумных земель, некогда мирный хутор Лордерона. Во время Третьей войны ее жители отчаянно и трагично встали против несметных сил Плети. Сегодня среди тишины остались лишь расщепленные бревна, неупокоенные духи и горькие воспоминания.",h="Дарроушир — разрушенная деревня в южных холмах Восточных Чумных земель, некогда мирный хутор Лордерона.",kw={"battle of darrowshire","darrowshire","eastern plaguelands","ghouls","horgus the ravager","lordaeron","marduk blackpool","битва за дарроушир","дарроушир","восточные чумные земли","вурдалаки","хоргус опустошитель","лордерон","мардук блэкпул"},ang={["class:Paladin"]="Трагическая судьба Дарроушира — неизменный призыв для паладинов принести очищающий Свет в Чумные земли, чтобы уничтожать нежить и упокоить измученные души.",["race:Human"]="Для людей Альянса Дарроушир — суровое свидетельство того опустошения, что постигло Лордерон, где простые люди безнадежно встали на защиту своих семей."},sec={{t="Трагическая оборона",b="До того как чума поглотила север Лордерона, Дарроушир был скромным сельским поселением у южных утесов. Когда во время Третьей войны Плеть двинулась на юг, отряд под предводительством рыцаря смерти Мардука Блэкпула и повелителя вурдалаков Хоргуса Опустошителя осадил город. Жители и местные защитники храбро сражались и на время удержали рубеж вопреки невозможным шансам. В конце концов оборона пала, и город был вырезан до последнего человека. Вместо покоя в смерти многие павшие защитники Дарроушира были подняты как вурдалаки, чтобы пополнить ряды Плети, и деревня превратилась в жуткий пустой памятник утраченной доблести."},{t="Отголоски битвы",b="Хотя живые давно покинули Дарроушир, он далеко не пуст. Тяжесть бойни давит на долину, удерживая призрачные остатки жителей среди руин. Путники сообщают о странных явлениях, в том числе о жутких повторениях, когда трагическая битва вновь разворачивается в призрачной тишине. Земля по-прежнему пропитана скорбью и мрачно напоминает о том, что Плеть отняла у королевства."}},faq={{q="Что случилось с Дарроуширом?",a="Дарроушир был разрушен во время Третьей войны, когда на город напала огромная армия Плети. Под предводительством рыцаря смерти Мардука Блэкпула и повелителя вурдалаков Хоргуса Опустошителя нежить смяла защитников, перебила жителей и оставила поселение в руинах.",al={"darrowshire history","why is darrowshire destroyed","what happened here","история дарроушира","почему разрушен дарроушир","что здесь случилось"}},{q="Кто возглавлял нападение Плети на Дарроушир?",a="Нападение возглавили рыцарь смерти Мардук Блэкпул и Хоргус Опустошитель, чудовищный повелитель вурдалаков. Вместе их силы сломили защитников деревни и обрекли поселение.",al={"who attacked darrowshire","darrowshire villains","horgus and marduk","кто напал на дарроушир","злодеи дарроушира","хоргус и мардук"}},{q="Почему в Дарроушире обитают призраки?",a="Бойня была настолько внезапной и ужасной, что духи павших остались привязаны к земле. Помимо призрачных видений в разрушенных зданиях, сама жестокая битва, как говорят, время от времени повторяется в призрачном виде, удерживая мертвых в их последних трагических мгновениях.",al={"darrowshire ghosts","why are there spirits in darrowshire"}},{q="Что стало с жителями, погибшими при защите города?",a="Большинство защитников были перебиты на месте, а многие их тела были подняты некромантами как безмозглые вурдалаки и вынуждены служить той самой армии Плети, что разрушила их дома.",al={"darrowshire villagers","defenders of darrowshire","жители дарроушира","защитники дарроушира"}}},fp="11,321,14.670.0,20.468.0,29.284.0,58.190.0,27.294.0,57.200.0"}
P.entries["subzone:dawning-isles"] = {n="Рассветные острова",s="Рассветные острова — группа низких островков на озере Лордамер у восточной границы Серебряного бора. Некогда идиллические уголки, они поддались заразе Чумы нежизни и теперь кишат агрессивными мурлоками.",h="Рассветные острова — группа низких островков на озере Лордамер у восточной границы Серебряного бора.",kw={"dawning isles","lordaeron","lordamere lake","silverpine forest","vile fin","рассветные острова","лордерон","озеро лордамер","серебряный бор","злобный плавник"},ang={["faction:Alliance"]="Зараженные острова мрачно напоминают о том, как далеко проникла порча Плети в самые живописные воды Лордерона.",["race:Undead"]="Зараженные Рассветные острова лежат на озере Лордамер, в виду западных подступов к Подгороду, а мурлоки Злобного Плавника, которые ими владеют, с каждым годом множатся."},sec={{t="Порча на озере",b="До Третьей войны Рассветные острова были живописными островками на спокойных прозрачных водах озера Лордамер. Когда Чума нежизни прокатилась по Лордерону, порча просочилась в мелководье озера. Растительность поблекла и начала гнить, и идиллический покой исчез. Сегодня племя мурлоков Злобного Плавника владеет илистыми берегами и спутанными зарослями и яростно защищает свои растущие колонии от всех, кто пытается пересечь озеро."},{t="Оплот мурлоков",b="Мурлоки не всегда были единственной опасностью на островах. Рядом с ними по зараженным островкам бродили болотные твари, но теперь они исчезли. Без них численность Злобного Плавника выросла настолько, что мурлоки полностью завладели островами и превратили некогда тихую цепь островков в свой оплот на озере Лордамер."}},faq={{q="Где находятся Рассветные острова?",a="Рассветные острова расположены на озере Лордамер, у восточной границы Серебряного бора, чуть западнее Руин Лордерона.",al={"dawning isles location","where is dawning isles","dawning islands map","расположение рассветных островов","где рассветные острова","карта рассветных островов"}},{q="Какие существа обитают на Рассветных островах?",a="Острова в основном заполонило племя мурлоков Злобного Плавника, которое процветает вдоль оскверненных берегов. Раньше на островках также бродили опасные болотные твари, но они почти исчезли, уступив место многочисленным мурлокам.",al={"mobs on dawning isles","what lives on dawning isles","dawning isle monsters","монстры на рассветных островах","кто живет на рассветных островах","мобы рассветных островов"}},{q="Почему здесь гниют деревья и берега?",a="Острова были осквернены во время Третьей войны, когда Чума нежизни прокатилась по Лордерону. Вода и почва впитали порчу, отравили растительность, и островки стали мутными, болезненными и гнилыми.",al={"why are dawning isles blighted","lake blight dawning isles","почему рассветные острова заражены","порча озера рассветные острова"}}},fp="13,248,18.460.0,19.353.0,36.149.0,41.250.0,42.205.0"}
P.entries["subzone:dawning-wood-catacombs"] = {n="Катакомбы Утреннего Леса",s="Катакомбы Утреннего Леса, вырытые глубоко под Кладбищем Вороньего Холма, — темный лабиринт, кишащий самой свирепой нежитью Сумеречного леса. Тех, кто отважится спуститься в подземные туннели, встречают скопища скелетов-стражей и пожирающих плоть вурдалаков.",h="Катакомбы Утреннего Леса, вырытые глубоко под Кладбищем Вороньего Холма, — темный лабиринт, кишащий самой...",kw={"crypts","dawning wood catacombs","duskwood","ghouls","raven hill cemetery","skeletons","undead","склепы","катакомбы утреннего леса","сумеречный лес","вурдалаки","кладбище вороньего холма","скелеты","нежить"},ang={["class:Paladin"]="Катакомбы — мрачное свидетельство павших королевства, требующее, чтобы священный гнев Света очистил оскверненные гробницы.",["class:Priest"]="Под каменными сводами Вороньего Холма неупокоенные духи и разлагающиеся трупы взывают к последнему покою, и катакомбы становятся мрачным испытанием веры."},sec={{t="Под Вороньим Холмом",b="Задолго до того, как над лесом нависло сумеречное проклятие, Катакомбы Утреннего Леса служили величественным местом упокоения почетных мертвецов Большого Хутора и окрестных усадеб. Теперь эти темные каменные коридоры, погребенные под разрушенным Кладбищем Вороньего Холма, таят самую смертоносную нежить края. В катакомбах два подземных крыла: в западных проходах ряды оживших скелетов охраняют родовые гробницы, а восточные ведут в мерзкое логово, захваченное голодными вурдалаками — разносчиками болезней. Одинокие путники редко выживают в их глубинах."}},faq={{q="Где находятся Катакомбы Утреннего Леса?",a="Катакомбы лежат прямо под Кладбищем Вороньего Холма, на дальнем западном краю Сумеречного леса. Входы ведут вниз с поверхности, среди раскинувшихся надгробий и разрушенных склепов.",al={"catacombs location","where is dawning wood catacombs","how to get to catacombs","расположение катакомб","где катакомбы утреннего леса","как добраться до катакомб"}},{q="Что скрывается внутри катакомб?",a="В катакомбах обитает самая многочисленная и свирепая нежить Сумеречного леса. Западное крыло защищают тяжеловооруженные скелеты-воины, а восточные туннели кишат яростными вурдалаками, зараженными чумой.",al={"catacombs enemies","what is in dawning wood catacombs","catacomb monsters","враги в катакомбах","что в катакомбах утреннего леса","монстры катакомб"}},{q="Зачем вообще построили катакомбы?",a="Когда этот край еще был зеленой Светлой рощей, катакомбы вырыли как величественную усыпальницу для местных семей и знатных людей. Темное проклятие, позже поглотившее лес, подняло погребенных в них мертвецов.",al={"catacombs history","why build catacombs","original purpose of catacombs","история катакомб","зачем построили катакомбы","назначение катакомб"}},{q="Безопасно ли исследовать катакомбы в одиночку?",a="Соваться в катакомбы в одиночку опасно. В тесных туннелях почти некуда отступать, а нежить собирается плотными агрессивными скоплениями, способными одолеть путника-одиночку.",al={"can i solo catacombs","catacombs danger","is catacombs hard","можно ли в катакомбы одному","опасность катакомб","сложные ли катакомбы"}}},fp="22,245,18.602.0,45.180.0,32.215.0,48.221.0,42.206.0"}
P.entries["subzone:dead-acre"] = {n="Мертвая пашня",s="Мертвая пашня — разоренная тлеющая ферма на юго-востоке Западного Края, возле речного моста в Сумеречный лес. Сожженные дотла Братством Справедливости во время восстания по всей округе, почерневшие поля теперь покинуты людьми, и по ним бродят взбесившиеся жнецы-големы.",h="Мертвая пашня — разоренная тлеющая ферма на юго-востоке Западного Края, возле речного моста в Сумеречный лес.",kw={"burned farm","dead acre","defias","farm","harvest watcher","westfall","сожженная ферма","мертвая пашня","братство справедливости","ферма","страж урожая","западный край"},ang={["faction:Alliance"]="Мертвая пашня — мрачное напоминание о пренебрежении Штормграда к Западному Краю, оставившем верных фермеров беззащитными перед жестокими грабежами Братства Справедливости."},sec={{t="Пепел на границе",b="Мертвая пашня находится к северу от дороги, соединяющей Сторожевой холм и Сумеречный лес. Когда-то это было процветающее хозяйство среди хлебных ферм Западного Края. Когда Братство Справедливости подняло мятеж и изгнало местных землевладельцев, эту ферму постигла жестокая участь. Усадьбу и окружающие посевы предали огню, и остались обугленные бревна, дымящаяся земля и бродячие механические Стражи урожая, которые до сих пор жнут бесплодную почву."}},faq={{q="Почему это место называется Мертвой пашней?",a="Братство Справедливости сожгло ферму и окрестные поля дотла, захватывая Западный Край. Мрачное название ферма получила из-за почерневших руин и тлеющей земли, оставшихся после них.",al={"why dead acre","what happened to dead acre","why is it burned","почему мертвая пашня","что случилось с мертвой пашней","почему сожжено"}},{q="Почему здесь бродят механические Стражи урожая?",a="Как и на многих фермах Западного Края, механические жнецы, созданные для ухода за посевами, остались, когда поселенцы бежали или погибли. Испорченные или лишенные присмотра, автоматические Стражи урожая продолжают бесконечно патрулировать выжженные поля и нападают на всех, кто приблизится.",al={"harvest golems dead acre","why are there golems","harvest watchers","жнецы-големы мертвая пашня","почему здесь големы","стражи урожая"}},{q="Где находится Мертвая пашня?",a="Мертвая пашня расположена на юго-востоке Западного Края, чуть севернее главной дороги, возле моста, ведущего в сумрачные земли Сумеречного леса.",al={"dead acre location","where is dead acre","how to find dead acre","расположение мертвой пашни","где мертвая пашня","как найти мертвую пашню"}}},fp="9,279,19.446.0,39.213.0,51.282.0,31.148.0"}
P.entries["subzone:dead-field"] = {n="Мертвое поле",kw={"banshee","dead field","deathstalkers","nightlash","rot hide","silverpine forest","thule ravenclaw","банши","мертвое поле","стражи смерти","ночной хлыст","гнилошкуры","серебряный бор","тул коготь ворона"},ang={["class:Rogue"]="Разведывательные отряды Стражей смерти внимательно следят за фермой; проникнуть в ряды гноллов и ударить по их командованию — важнейшая тактическая задача.",["race:Undead"]="Для Отрекшихся плацдарм Плети на Мертвом поле — прямая угроза дороге между Гробницей и северным Лордероном, требующая скорейшего уничтожения."},sec={{t="Зараженный плацдарм",b="От первоначальной фермы на севере Серебряного бора почти ничего не осталось, а ее прежние живые обитатели давно сгинули в Третьей войне. Сегодня разоренный участок служит базой гноллам Гнилошкурам, охотно служащим Плети. Когда их стало больше, разведчики Стражей смерти, проходившие через край, заметили признаки скорой военной мобилизации, угрожающей линиям снабжения и аванпостам Отрекшихся. Небольшие атаки Отрекшихся на ферму не раз проваливались, отбитые воющим призраком Ночным Хлыстом — банши, являющейся всякий раз, когда ее гноллам-рабам грозит опасность."},{t="Амбиции Когтя Ворона",b="Гнилошкуры действуют не одни. Их действиями на Мертвом поле издалека руководит некромант Тул Коготь Ворона с острова Фенриса. Желая утвердить господство Плети над Серебряным бором и изгнать силы Сильваны из Лордерона, Коготь Ворона посылает на ферму магические видения, чтобы осматривать свою армию нежити и предупреждать вторгшихся Отрекшихся."}},faq={{q="Что такое Мертвое поле?",a="Мертвое поле — это обветшалая, зараженная ферма на севере Серебряного бора. Когда-то это была обычная человеческая ферма, но она лежит в руинах, и теперь ее занимают гноллы Гнилошкуры, союзные Плети.",al={"dead field silverpine","where is dead field","what happened to dead field","мертвое поле серебряный бор","где мертвое поле","что случилось с мертвым полем"}},{q="Почему на ферме гноллы?",a="Эти гноллы Гнилошкуры находятся под властью Плети. Они используют ферму как передовой плацдарм, чтобы собирать силы и готовить нападения на позиции Отрекшихся на севере Серебряного бора.",al={"why rot hide gnolls","rot hides dead field","scourge gnolls","почему гнилошкуры","гнилошкуры мертвое поле","гноллы плети"}},{q="Кто такая Ночной Хлыст?",a="Ночной Хлыст — банши Плети, командующая гноллами Гнилошкурами на ферме. Когда ударные отряды Отрекшихся штурмуют лагерь, она появляется, чтобы защитить своих слуг, и отражает прежние попытки вернуть эти земли.",al={"nightlash banshee","banshee in dead field","who protects the gnolls","ночной хлыст банши","банши на мертвом поле","кто защищает гноллов"}},{q="Кто командует силами Плети здесь?",a="Лагерь подчиняется Тулу Когтю Ворона, могущественному некроманту, действующему с соседнего острова Фенриса. Он руководит гноллами с помощью видений и магического надзора, чтобы мешать расширению Отрекшихся.",al={"who controls dead field","thule ravenclaw dead field","who is in charge","кто управляет мертвым полем","тул коготь ворона мертвое поле","кто главный"}}},fp="10,327,25.616.0,20.386.1,23.196.0,33.202.0,17.220.0,37.198.0"}
P.entries["subzone:deadeye-shore"] = {n="Взморье Мертвого Глаза",s="Взморье Мертвого Глаза — продуваемая ветрами полоса побережья на восточном краю Дуротара, прямо к востоку от Сухой лощины. Названное в память о легендарном вожде клана Кровавой Глазницы Килрогге Мертвом Глазе, бесплодные пески населяют в основном дикие ящеры, скорпиды и свирепые кабаны.",h="Взморье Мертвого Глаза — продуваемая ветрами полоса побережья на восточном краю Дуротара, прямо к востоку от...",kw={"bleeding hollow","deadeye shore","drygulch ravine","durotar","kilrogg deadeye","кровавая пасть","взморье мертвого глаза","сухая лощина","дуротар","килрогг мертвый глаз"},ang={["race:Orc"]="Для орков, строящих новую державу в Дуротаре, это взморье чтит Килрогга Мертвого Глаза и напоминает о древних вождях, определивших историю Орды в войнах на Азероте."},sec={{t="Берег клана Кровавой Глазницы",b="Взморье Мертвого Глаза, раскинувшееся под красными утесами центрального Дуротара, получило имя от Килрогга Мертвого Глаза, одноглазого вождя клана Кровавой Глазницы, сражавшегося в Первой и Второй войнах. Сверху пески и скалистые выступы слабо напоминают череп с пустой глазницей. Хотя крупных поселений и военных застав здесь нет, берег далеко не мирный: песками владеют агрессивные звери, а темные культисты Пылающего Клинка, как известно, спускаются к воде из своих укрытий в ущельях неподалеку."}},faq={{q="Почему оно называется Взморьем Мертвого Глаза?",a="Побережье названо в честь Килрогга Мертвого Глаза, знаменитого вождя клана Кровавой Глазницы. Природный рельеф берега тоже напоминает череп без глаза, повторяя слепую глазницу самого вождя.",al={"who is deadeye","why deadeye shore","origin of name","кто такой мертвый глаз","почему взморье мертвого глаза","происхождение названия"}},{q="Кто живет на Взморье Мертвого Глаза?",a="Постоянных поселений на Взморье Мертвого Глаза нет. Побережье населяют в основном местные звери — ящеры, скорпиды и кабаны, хотя иногда здесь проходят рыбаки и путники, порой сталкиваясь с затаившимися культистами Пылающего Клинка.",al={"who is here","settlements deadeye shore","npcs deadeye","кто здесь живет","поселения взморья мертвого глаза","персонажи взморья"}},{q="Какие опасности встречаются на Взморье Мертвого Глаза?",a="Помимо агрессивных местных зверей, главная опасность исходит от соседней Сухой лощины. Культисты Пылающего Клинка порой спускаются из скалистых каньонов к побережью и устраивают засады на неосторожных путников и рыбаков.",al={"dangers deadeye shore","enemies here","burning blade deadeye","опасности взморья мертвого глаза","враги здесь","пылающий клинок взморье"}}},fp="13,271,34.569.0,31.205.0,30.263.0,44.243.0"}
P.entries["subzone:deadman-s-crossing"] = {n="Перекресток Мертвеца",s="Перекресток Мертвеца — зловещая развилка в унылом ущелье Перевала Мертвого Ветра. Здесь расходятся дороги к Сумеречному лесу, Болоту Печали и населенной призраками башне Каражана; виселицы и предупреждающие знаки делают это место мрачным порогом. Несмотря на жуткий вид, путь остается важной дорогой для путников, идущих через юг Восточных королевств.",h="Перекресток Мертвеца — зловещая развилка в унылом ущелье Перевала Мертвого Ветра.",kw={"deadman's crossing","deadwind pass","duskwood","gallows","hangman's tree","karazhan","signpost","swamp of sorrows","перекресток мертвеца","перевал мертвого ветра","сумеречный лес","виселица","дерево повешенных","каражан","указатель","болото печали"},ang={["faction:Alliance"]="Для гонцов Альянса, идущих из Темнолесья к форпосту Крепость Стражей Пустоты в Выжженных землях, путь мимо Перекрестка Мертвеца — самый быстрый, хотя и самый жуткий.",["faction:Horde"]="Странники Орды, идущие на запад из Каменора к Сумеречному лесу, должны пройти мимо этого мрачного места — первого знакомства с оскверненными землями людей впереди."},sec={{t="Мрачный перекресток",b="Перекресток Мертвеца лежит на восточной развилке Перевала Мертвого Ветра и соединяет тени Сумеречного леса с мутными глубинами Болота Печали, а зловещая тропа на юг поднимается к населенной призраками башне Каражана. Название перекресток получил от искривленного дерева повешенных у развилки дороги: на нем висят два гниющих трупа — суровое предостережение каждому проходящему. Рядом с деревом потрепанные деревянные знаки прямо советуют путникам повернуть назад и оставить надежду. Само ущелье кишит враждебными тварями и темной магией, но тот, кто упорно идет по утоптанной грунтовой дороге, найдет сам перекресток странно нетронутым — если не заберется в проклятые скалы."}},faq={{q="Куда ведет каждая дорога от Перекрестка Мертвеца?",a="Дорога на запад выводит из перевала в населенный призраками Сумеречный лес. Дорога на восток ведет прямо в топи Болота Печали. Извилистая южная тропа уводит вглубь Перевала Мертвого Ветра, к проклятым руинам и величественной башне Каражана.",al={"where do roads go","crossing directions","deadmans crossing paths","куда ведут дороги","направления перекрестка","пути перекрестка мертвеца"}},{q="Кто эти трупы, висящие на дереве?",a="Их имена забыты историей. Перевал Мертвого Ветра за долгие годы забрал множество несчастных странников, разбойников и беженцев, а дерево с виселицей кто-то поставил как жуткий пограничный знак, чтобы отпугивать путников.",al={"hanging bodies","dead bodies on tree","who was hanged","повешенные","трупы на дереве","кого повесили"}},{q="Безопасен ли Перекресток Мертвеца для путников?",a="Как ни странно, да. Хотя окрестные скалы и пещеры Перевала Мертвого Ветра кишат злобными стервятниками, призраками и ограми, сам перекресток и главная дорога с востока на запад свободны. Гонцы и искатели приключений низкого уровня могут безопасно пройти между Сумеречным лесом и Болотом Печали, если не сойдут с проторенной дороги.",al={"is it safe","will i get attacked on the road","danger level","безопасно ли","нападут ли на дороге","уровень опасности"}},{q="Что написано на знаках на перекрестке?",a="Выветренные деревянные указатели несут зловещие предостережения: один прямо велит путникам «Повернуть назад!», другой предупреждает: «Оставь надежду, всяк сюда входящий», — не оставляя сомнений в опасности этой долины.",al={"crossing signpost","what do signs read","abandon hope sign","указатель перекрестка","что написано на знаках","знак оставь надежду"}}},fp="18,369,19.745.0,50.280.0,42.237.0,41.339.0,38.220.0"}
P.entries["subzone:deadmines"] = {n="Мертвые копи",s="Глубоко под пыльным городом-призраком Луноречье лежат Мертвые копи — обширный подземный лабиринт, когда-то дававший треть золотых запасов Штормграда. Заброшенные во время Первой войны и давно слывущие обитаемыми призраками, забытые шахты стали укрепленной штаб-квартирой Эдвина ван Клифа и его мятежного Братства Справедливости.",h="Глубоко под пыльным городом-призраком Луноречье лежат Мертвые копи — обширный подземный лабиринт, когда-то...",kw={"deadmines","defias","edwin vancleef","ironclad cove","juggernaught","lothar","moonbrook","thistlenettle","vancleef","westfall","мертвые копи","братство справедливости","эдвин ван клиф","потайная бухта","колосс","лотар","луноречье","чертополох","ван клиф","западный край"},ang={["class:Paladin"]="Мертвые копи священны для паладинов: сэр Андуин Лотар проник в их самые темные залы во время Первой войны, чтобы вернуть у свирепых огров священный Фолиант Божественности.",["profession:Mining"]="До Первой войны эти шахты были жемчужиной горного дела людей и давали треть золотых запасов Штормграда, пока их не заняли гоблинские механизмы и разбойники Братства Справедливости."},sec={{t="Жила золота и крови",b="До Первой войны Мертвые копи были главным горным предприятием в землях людей, богатым золотом и прочным белокаменным дубом, шедшим на бревна и крепи. Когда орки Орды двинулись на север, копи поспешно бросили. Сэр Андуин Лотар отправился в их опасные глубины, чтобы вернуть священный Фолиант Божественности, и провел двадцать месяцев в плену у подземных огров, пока его не спасли. В смуте после падения королевства шахты затихли и обрели жуткую славу проклятых."},{t="Литейная ван Клифа",b="После бунта каменщиков в Штормграде новообразованное Братство Справедливости захватило подземный комплекс как главное убежище. Когда Лига шахтеров Штормграда под началом Штейгера Чертополоха попыталась вновь открыть туннели, разбойники Братства устроили рабочим засаду и обрушили шахты, и погибшие шахтеры стали неупокоенной нежитью. Сегодня, под защитой огров-головорезов и гоблинов-механиков, Братство превратило глубокие туннели в промышленный военный лагерь вокруг подземной верфи в Потайной бухте."}},faq={{q="Как попасть в Мертвые копи?",a="Главный вход скрыт в Укрытии Братства Справедливости в разрушенном городе Луноречье на юго-западе Западного Края. Спускаясь по подвалам, вы попадете прямо в обширные шахты.",al={"where is deadmines entrance","how to enter deadmines","deadmines location","где вход в мертвые копи","как войти в мертвые копи","расположение мертвых копей"}},{q="Почему копи вообще забросили?",a="Их оставили во время Первой войны, когда Орда захватила южные области королевства. Из-за бушующей войны и огров, поселившихся в глубинах, работы прекратились, и заброшенные туннели быстро прослыли обитаемыми призраками.",al={"why did deadmines close","why are deadmines abandoned","почему закрыли мертвые копи","почему мертвые копи заброшены"}},{q="Что строит здесь Братство Справедливости?",a="Глубоко в затопленной пещере Потайной бухты Эдвин ван Клиф и нанятые гоблины-инженеры строят огромный броненосный колосс. ван Клиф намерен провести этот боевой корабль вдоль побережья, чтобы в отместку обстрелять и осадить Штормград.",al={"what is in the deadmines","vancleef plan deadmines","ironclad cove ship","что в мертвых копях","план ван Клифа мертвые копи","корабль потайная бухта"}},{q="Кто эта нежить, бродящая возле входных туннелей?",a="Это несчастные рабочие Лиги шахтеров под началом Штейгера Чертополоха. Когда Лига попыталась разведать и вернуть копи, головорезы Братства устроили им засаду и обрушили шахты, оставив запертых шахтеров умирать, и они восстали неупокоенными вурдалаками.",al={"undead miners deadmines","foreman thistlenettle deadmines","why are there ghouls in deadmines","нежить шахтеры мертвые копи","штейгер чертополох","почему в мертвых копях вурдалаки"}},{q="Какая связь у Андуина Лотара с Мертвыми копями?",a="Во время Первой войны сэр Андуин Лотар отправился вглубь Мертвых копей в экспедиции за священным Фолиантом Божественности. Его схватили огры, жившие в пещерах, и держали в плену почти два года, пока наконец не спасли.",al={"lothar deadmines","anduin lothar deadmines","лотар мертвые копи","андуин лотар мертвые копи"}}},fp="9,338,24.558.0,18.534.1,34.211.0,48.245.0,50.256.1,55.259.0,57.250.0"}
P.entries["subzone:deathknell"] = {n="Могильник",s="Могильник — укрепленная деревня в уединенной долине на юго-западе Тирисфальских лесов. Здесь пробуждаются недавно освободившиеся нежити, вырвавшиеся из хватки Короля-лича, чтобы присоединиться к Отрекшимся. Осаждаемое безмозглыми остатками Плети, местными фанатиками и свирепыми зверями, поселение — суровое испытание для тех, кто хочет занять место в королевстве Сильваны Ветрокрылой.",h="Могильник — укрепленная деревня в уединенной долине на юго-западе Тирисфальских лесов.",kw={"deathknell","forsaken starting area","mindless ones","night web's hollow","shadow grave","sylvanas","tirisfal glades","могильник","стартовая зона отрекшихся","безмозглые твари","паучья низина","мрачный склеп","сильвана","тирисфальские леса"},ang={["faction:Horde"]="Хотя эта долина изолированная и мрачная, она — врата в королевство Отрекшихся, поставляющие свежих солдат для укрепления позиций Орды в Восточных королевствах.",["race:Undead"]="Каждый Отрекшийся искатель приключений начинает здесь, поднимаясь из холодной земли Мрачного склепа, чтобы после ужаса Чумы обрести цель и приют под началом леди Сильваны."},sec={{t="Колыбель Отрекшихся",b="Могильник скрыт за зубчатыми холмами к северу от границы Серебряного бора, и здесь только что пробудившаяся нежить впервые открывает глаза навстречу мрачной действительности. В отличие от большинства поселений Тирисфальских лесов, сохранивших человеческие названия павшего Королевства Лордерон, Могильник был намеренно переименован захватившей его нежитью. Город рассечен надвое: Отрекшиеся упорно держатся на южных землях вокруг старой церкви, а северная половина, включая деревенскую кузню, захвачена безмозглыми зомби Плети и одичавшими вурдалаками. Элитные Стражи смерти надежно перекрывают узкое ущелье из долины от чужаков, позволяя местным смотрителям принимать новичков на службу Королеве банши."},{t="Долина в осаде",b="Выжить в Могильнике нелегко. На северо-западе Паучья низина — золотой рудник, важный для зарождающейся экономики Отрекшихся, — потеряна из-за чудовищных пауков. На юго-востоке агрессивный лагерь Алого ордена постоянно наблюдает за округой, обменивается гонцами со своими крепостями на востоке и прощупывает оборону долины. Тем временем смотрители деревни должны непрерывно отбиваться от безмозглой нежити, бродящей по северным руинам, и собирать металлолом, инструменты и припасы, чтобы снарядить недавно восставшие души в долгий путь."}},faq={{q="Почему город переименовали в Могильник?",a="Могильник получил новое название, став поселением нежити, в отличие от большинства общин Тирисфаля, сохранивших человеческие названия. Причина нового названия неизвестна.",al={"deathknell name origin","why is it called deathknell","old name of deathknell","происхождение названия могильник","почему называется могильник","старое название могильника"}},{q="Почему северная половина города захвачена нежитью?",a="Не каждый труп, поднятый после Третьей войны, освободился с сохранным разумом. Северная деревенская площадь и кузня кишат «безмозглыми тварями» — одичавшими зомби, вурдалаками и скелетами, которыми все еще движет остаточная воля Плети. Защитники из числа Отрекшихся регулярно зачищают их, чтобы добыть снаряжение и защитить церковь.",al={"why are zombies in deathknell","scourge in deathknell","mindless ones deathknell","почему в могильнике зомби","плеть в могильнике","безмозглые твари могильник"}},{q="Что делает Алый орден возле Могильника?",a="Отряд Алого ордена держит лагерь в холмах к юго-востоку от деревни. Фанатично стремясь уничтожить всю нежить без разбора, они следят за проходом, устраивают засады на только что пробудившихся Отрекшихся и обмениваются разведданными с крепостями Алого ордена в других частях Лордерона.",al={"scarlet camp deathknell","crusaders outside deathknell","scarlet crusade tirisfal valley","лагерь алого ордена могильник","крестоносцы у могильника","алый орден тирисфальская долина"}},{q="Почему Отрекшиеся не могут использовать местный золотой рудник?",a="Паучья низина, золотой рудник в скалах к северо-западу от деревни, полностью захвачена агрессивными пауками. Добыча природных ресурсов, таких как золото, крайне важна для военных усилий Отрекшихся, но пока нашествие не будет устранено, поселение не может разрабатывать жилу.",al={"deathknell mine","night webs hollow","spider mine tirisfal","рудник могильника","паучья низина","паучий рудник тирисфаль"}}},fp="10,405,22.740.0,20.560.0,36.169.0,55.350.0,50.302.0,47.283.0"}
P.entries["subzone:decrepit-ferry"] = {n="Старая переправа",s="Старая переправа — разрушенная пристань на восточном берегу Серебряного бора, откуда когда-то можно было переправиться через Озеро Лордамер на Остров Фенриса. После падения Лордерона паром был уничтожен, его перевозчик убит, а берег захватили нежить и свирепые гноллы из племени Гнилошкуров.",h="Старая переправа — разрушенная пристань на восточном берегу Серебряного бора, откуда когда-то можно было...",kw={"decrepit ferry","fenris isle","ferryman","ghouls","lordamere lake","rot hide","scourge","silverpine forest","старая переправа","остров фенриса","перевозчик","вурдалаки","озеро лордамер","гнилошкуры","плеть","серебряный бор"},ang={["race:Undead"]="Руины напоминают о падении Лордерона. Теперь их захватили бездумные остатки Плети и грязные гноллы, угрожающие операциям Отрекшихся на востоке Серебряного бора."},sec={{t="Оборванная связь",b="До Третьей войны эта пристань жила оживленной ежедневной торговлей через Озеро Лордамер. Местные фермеры привозили к воде свежие продукты и продавали урожай прямо богатому владыке Острова Фенриса и его домочадцам. За скромную плату перевозчик доставлял товары, гонцов и знатных гостей между берегом и замком. Мирная торговля внезапно прервалась, когда Плеть прошла по королевству. Перевозчика жестоко убили, лодки разбили, а пирс обветшал."},{t="Оскверненный берег",b="Сегодня пристань опасна для любого путника на берегу озера. Паром не действует, и Остров Фенриса остался отрезанным за водой, а среди руин кишат вурдалаки, скелеты-воины и бродячие гноллы Гнилошкуры. Некогда упорядоченный транспортный пункт стал еще одним гниющим очагом опасности в Серебряном боре."}},faq={{q="Для чего изначально использовалась Старая переправа?",a="Это была главная переправа между материковой частью Серебряного бора и Островом Фенриса. Местные фермеры возили по ней урожай через Озеро Лордамер, чтобы продать знатному владыке острова, и платили перевозчику небольшую плату за каждый рейс.",al={"ferry history","what was this dock","why is there a ferry here","история переправы","что это за пристань","почему здесь переправа"}},{q="Что случилось с паромом и его перевозчиком?",a="Когда Плеть вторглась в Лордерон, на пристань напали. Перевозчика убили, лодки и снаряжение для переправы уничтожили, а место отдали нежити.",al={"what happened to ferryman","who broke the ferry","что случилось с перевозчиком","кто сломал паром"}},{q="Какие монстры обитают у пристани сейчас?",a="Берег кишит остатками Плети, в том числе вурдалаками и скелетами-воинами, а по соседним берегам рыщут опасные гноллы Гнилошкуры.",al={"decrepit ferry mobs","what lives at the ferry","монстры старой переправы","кто живет у переправы"}},{q="Можно ли отсюда по-прежнему добраться на лодке до Острова Фенриса?",a="Нет. Паром был разрушен во время вторжения и лежит в руинах. Тот, кто хочет попасть на Остров Фенриса, должен переплыть озеро или найти другой путь.",al={"take boat to fenris","how to get to fenris isle","does the ferry work","лодка на остров фенриса","как попасть на остров фенриса","работает ли паром"}}},fp="14,288,20.523.0,21.349.0,48.241.0,44.175.0,46.158.0,51.155.0"}
P.entries["subzone:deep-elem-mine"] = {n="Серебряный рудник",s="Серебряный рудник — выработка в самом сердце Серебряного бора. Когда-то он действовал, но был захвачен, когда темная магия верховного мага Аругала прокатилась по региону и превратила шахтеров в свирепых воргенов.",h="Серебряный рудник — выработка в самом сердце Серебряного бора.",kw={"arugal","dalar dawnweaver","deep elem mine","grimson the pale","silverpine forest","varimathras","worgen","аругал","далар ткач рассвета","серебряный рудник","мрачнон белесый","серебряный бор","вариматрас","воргены"},ang={["profession:Mining"]="Хотя сейчас рудник опасен из-за обитающей в нем звериной стаи, он остается одним из богатейших подземных месторождений руды в Серебряном бору.",["race:Undead"]="Для Отрекшихся захват рудника — и экономическая необходимость, и прямой приказ Гробниц разрушить растущее влияние Аругала в центральной части Серебряного бора."},sec={{t="Логово зверей",b="Серебряный рудник, расположенный в центре Серебряного бора, когда-то служил живым жителям Лордерона обычной рудной жилой. Когда верховный маг Аругал выпустил в лес волчий кошмар, его звериное проклятие проникло глубоко в туннели. Рабочие внутри поддались недугу и превратились в свирепых воргенов, которые бросили кирки и устроили в пещере хищное логово."},{t="Мрачнон и амбиции Отрекшихся",b="Стаей в руднике командует Мрачнон Белесый, бывший начальник рудника, сохранивший хитрость даже после чудовищного превращения. Понимая стратегическую ценность туннелей и руды, Отрекшиеся из Гробниц очень заинтересованы в возвращении рудника. По приказу, подкрепленному властью повелителя ужаса Вариматраса, агенты Отрекшихся стремятся отсечь Мрачнону голову и истребить зверей, чтобы Орда могла завладеть богатствами рудника."}},faq={{q="Что находится в Серебряном руднике?",a="Рудник кишит враждебными воргенами, пораженными магией верховного мага Аругала. Их возглавляет бывший начальник-человек Мрачнон Белесый, который теперь правит стаей в глубине туннелей.",al={"whats in deep elem mine","deep elem mine mobs","who lives in deep elem mine","что в серебряном руднике","монстры серебряного рудника","кто живет в серебряном руднике"}},{q="Почему Отрекшиеся хотят очистить Серебряный рудник?",a="Отрекшиеся стремятся использовать природные минеральные богатства рудника для поддержки военных усилий в Лордероне. Далар Ткач Рассвета и руководство Гробниц намерены завладеть его ресурсами от имени повелителя ужаса Вариматраса, когда воргены будут истреблены.",al={"forsaken mine interest","why clear deep elem mine","who wants the mine","интерес отрекшихся к руднику","зачем зачищать серебряный рудник","кто хочет рудник"}},{q="Кто такой Мрачнон Белесый?",a="Мрачнон был простым смертным начальником, управлявшим работами в Серебряном руднике. После того как звериное проклятие Аругала превратило рабочих, Мрачнон стал хитрым вожаком воргенов и сохранил достаточно разума, чтобы командовать стаей, обитающей в руднике.",al={"who is grimson","grimson the pale lore","deep elem mine boss","кто такой мрачнон","мрачнон белесый предания","босс серебряного рудника"}},{q="Как воргены попали в рудник?",a="Они не были чужаками, которые туда вселились: прежние шахтеры превратились из-за распространения проклятия верховного мага Аругала по Серебряному бору, и рабочие стали чудовищами прямо на месте работы.",al={"why are there worgen in the mine","worgen origin deep elem mine","how did miners turn","почему в руднике воргены","происхождение воргенов серебряный рудник","как шахтеры превратились"}}},fp="14,224,15.397.0,29.457.1,30.188.0,48.257.0,24.243.0,37.196.0"}
P.entries["subzone:deeprun-tram"] = {n="Подземный поезд",s="Подземный поезд — подземное чудо гномской инженерии, соединяющее столицы Альянса Стальгорн и Штормград. Построенный по заказу короля Магни Бронзоборода после Второй войны, он позволяет гражданам и солдатам преодолевать огромные расстояния под землей всего за несколько минут. Закрытые двойные пути проходят под горами и озером и служат важной артерией для военной поддержки и торговли Альянса.",h="Подземный поезд — подземное чудо гномской инженерии, соединяющее столицы Альянса Стальгорн и Штормград.",kw={"deeprun tram","dwarven district","gelbin mekkatorque","magni bronzebeard","subterranean lake","subway","tinkertown","tram","подземный поезд","квартал дворфов","гелбин меггакрут","магни бронзобород","подземное озеро","метро","город механиков","поезд"},ang={["faction:Alliance"]="Поезд служит главной стратегической артерией, соединяющей две самые укрепленные столицы Альянса, и позволяет за считаные минуты перебрасывать войска и совместно обороняться.",["profession:Engineering"]="Вся железная дорога — непревзойденный гномский шедевр: передовые двигатели, герметичное стекло, выдерживающее давление глубин подземного озера, и сложные электрические станции переключения путей."},sec={{t="Чудо подземной инженерии",b="После разрушений Второй войны король Магни Бронзобород все больше раздражался тем, как медленно дворфийская помощь и строительные материалы добираются до Штормграда через горные перевалы. Чтобы решить эту логистическую проблему и гарантировать, что дворфийские солдаты смогут быстро подкрепить человеческую столицу в трудный час, Магни обратился к главному механику Гелбину Меггакруту. Мастер-гном-инженер набросал проект закрытой подземной железной дороги на новейших технологиях. Несмотря на сложности при рытье — туннель прошел прямо через огромное подземное озеро, а работам мешали неутихающие нашествия подземных крыс, — поезд стал венцом достижений Альянса и бесплатно перевез тысячи путешественников между Стальгорном и Штормградом."}},faq={{q="Зачем построили Подземный поезд?",a="После Второй войны королю Магни Бронзобороду требовался более быстрый способ доставлять припасы и дворфийские войска для помощи в восстановлении и защите Штормграда. Он поручил дело главному механику Гелбину Меггакруту, который разработал и осуществил проект подземной железной дороги, надежно связавшей две столицы.",al={"why build the tram","tram purpose","who built deeprun tram","зачем построили поезд","назначение поезда","кто построил подземный поезд"}},{q="Как поезд проходит под водой?",a="При рытье между Дун Морогом и Штормградом гномы-инженеры вскрыли огромное подземное озеро. Вместо того чтобы обходить его, они проложили прямо через глубокую воду герметичный усиленный стеклянный туннель, чтобы пассажиры могли наблюдать, как рядом с путями плавают дикие жесткозубы и акулы.",al={"tram water window","underwater tram","deeprun tram lake","окно с водой в поезде","подводный поезд","озеро подземного поезда"}},{q="Почему вдоль путей так много крыс?",a="Сырые темные подземные шахты — идеальное место для размножения вредителей. Гномьи начальники станций постоянно борются с крысами, чтобы те не перегрызли кабели и не заполонили платформы, и порой полагаются на путешественников и крысоловов вроде Монти, чтобы сократить их число.",al={"deeprun rats","why rats in tram","rat problem","крысы подземного поезда","почему в поезде крысы","проблема с крысами"}},{q="Можно ли ездить на поезде бесплатно?",a="Да. Поезд, открытый гражданский и военный проект властей Стальгорна и Штормграда, ходит круглосуточно и бесплатно для всех граждан и союзников Альянса.",al={"tram cost","tram ticket price","how much to ride tram","стоимость поезда","цена билета на поезд","сколько стоит проезд"}}},fp="12,410,36.774.0,31.306.0,36.317.0,44.293.0,25.192.0"}
P.entries["subzone:deepwater-tavern"] = {n="Таверна \"Большая вода\"",s="Таверна «Большая вода» — оживленный приморский постоялый двор Гавани Менетилов, затерянной в сырых болотах Болотины. Это главное место встреч, пополнения запасов и отдыха для путников и моряков в шумном портовом городке. За крепкими напитками и портовыми слухами посетители часто находят работу или попадают в бурные трактирные драки.",h="Таверна «Большая вода» — оживленный приморский постоялый двор Гавани Менетилов, затерянной в сырых болотах...",kw={"deepwater tavern","first aid trainer","innkeeper","menethil harbor","tapoke slim jahn","tavern brawl","wetlands","таверна большая вода","учитель первой помощи","трактирщик","гавань менетилов","тапоке худой ян","драка в таверне","болотина"},ang={["faction:Alliance"]="Таверна «Большая вода» — незаменимый сборный пункт и пристанище для воинов Альянса, путешествующих между Стальгорном и открытым морем."},sec={{t="Сердце Гавани Менетилов",b="Таверна «Большая вода», стоящая на промокших улицах Гавани Менетилов, дарит путникам желанный приют от вечно моросящих коварных болот снаружи. Моряки, портовые рабочие, торговцы и усталые искатели приключений собираются под ее деревянными балками, чтобы обменяться новостями, погреться у огня и залечить раны. Помимо обычных удобств портового постоялого двора, здесь есть учитель первой помощи и местные торговцы для тех, кто отправляется в опасные болота или в плавание по Великому морю. Атмосфера здесь шумная и порой опасная: из-за пролитого эля быстро вспыхивают ссоры, а известные буяны вроде Тапоке «Худого» Яна нередко развязывают драки на всю таверну."}},faq={{q="Где находится таверна «Большая вода»?",a="Таверна «Большая вода» расположена у набережной Гавани Менетилов, главного портового городка Болотины на западном побережье Каз Модана.",al={"deepwater tavern location","where is deepwater tavern","menethil harbor inn","где таверна большая вода","расположение таверны большая вода","трактир гавани менетилов"}},{q="Какие услуги доступны в таверне?",a="Помимо обычного ночлега и угощений у трактирщика, в таверне есть торговцы и учитель первой помощи, поэтому она важный пункт пополнения запасов и лечения для искателей приключений в болотах.",al={"deepwater tavern services","menethil tavern trainers","what can i find at deepwater tavern","услуги таверны большая вода","учителя таверны менетилов","что найти в таверне большая вода"}},{q="Кто чаще всего затевает драки в таверне?",a="Таверна славится стихийными драками, а подозрительный буян по имени Тапоке «Худой» Ян часто провоцирует потасовки среди шумных посетителей и моряков.",al={"bar brawl menethil","tapoke slim jahn","who starts fights at deepwater tavern","драка в таверне менетилов","тапоке худой ян","кто затевает драки в таверне большая вода"}},{q="Почему в таверне всегда многолюдно?",a="Гавань Менетилов — главные морские ворота, связывающие Каз Модан с Калимдором и северными портами. Как единственный крупный постоялый двор в городе, таверна принимает постоянный поток моряков, наемников и искателей приключений из Альянса, направляющихся в Болотину.",al={"why visit deepwater tavern","why is deepwater tavern popular","зачем идти в таверну большая вода","почему таверна большая вода популярна"}}},fp="16,353,24.710.0,38.146.0,46.202.0,43.163.0,26.239.0"}
P.entries["subzone:defias-hideout"] = {n="Укрытие Братства Справедливости",s="Укрытие Братства Справедливости — неприметный заброшенный дом на южной окраине Луноречья. Хотя он сливается с окружающим разрушенным поселением, на его верхнем этаже скрыт главный наземный вход в обширную подземную сеть Мертвых копей.",h="Укрытие Братства Справедливости — неприметный заброшенный дом на южной окраине Луноречья.",kw={"deadmines","defias","defias hideout","entrance","moonbrook","vancleef","westfall","мертвые копи","братство справедливости","укрытие братства справедливости","вход","луноречье","ван клиф","западный край"},ang={["class:Rogue"]="Укрытие — образец скрытной обороны: замаскировав вход в огромную подземную крепость под неприметным разрушенным особняком, Братство Справедливости скрывает свои истинные масштабы от случайных патрулей Штормграда.",["faction:Alliance"]="Это ветхое поместье — парадная дверь заговора Эдвина ван Клифа, поэтому оно важный плацдарм для искателей приключений из Альянса, желающих покончить с мятежом Братства Справедливости."},sec={{t="Врата в руинах",b="Для беглого взгляда Укрытие Братства Справедливости выглядит как любой другой разграбленный особняк или хутор в Луноречье, заполненный нищими бродягами и головорезами Братства Справедливости. Однако скромная обстановка скрывает нервный центр южных операций Эдвина ван Клифа. На верхнем этаже находится проход, ведущий прямо вниз, в раскинувшийся лабиринт Мертвых копей. Поскольку Братство сосредоточило людей на охране окраин Луноречья и работах глубоко под землей, само укрытие охраняется слабо и служит скорее тщательно наблюдаемым узким местом, чем действующей крепостью."}},faq={{q="Что находится внутри Укрытия Братства Справедливости?",a="Внутри здания находится лестница, ведущая наверх к извилистому туннелю — наземному входу в Мертвые копи. Если не считать бродящих бродяг и разрозненных бандитов, само здание почти пустует и служит главным образом охраняемым входом.",al={"inside defias hideout","hideout entrance","what is here","внутри укрытия братства справедливости","вход в укрытие","что здесь находится"}},{q="Почему внутри укрытие почти не охраняется?",a="Братство Справедливости сосредоточило боевые силы снаружи, на улицах Луноречья, чтобы перехватывать чужаков, не подпуская их близко, а остальные рабочие и головорезы заняты работой далеко внизу, в глубинах копей.",al={"why empty","where are the defias","why so few guards","почему пусто","где братство справедливости","почему так мало стражи"}},{q="Где в Луноречье находится это здание?",a="Укрытие расположено на южной окраине Луноречья на юго-западе Западного Края. Его легко узнать: это большое уцелевшее двухэтажное здание у подножия гор.",al={"how to find hideout","where is defias hideout","hideout location","как найти укрытие","где укрытие братства справедливости","расположение укрытия"}},{q="Кто эти люди, околачивающиеся возле укрытия?",a="Здание и окружающий городок населяют бандиты Братства Справедливости и отчаявшиеся бродяги, собравшиеся в Луноречье: они бежали от нищеты или примкнули к Братству по необходимости.",al={"who are vagrants","moonbrook vagrants","defias people","кто такие бродяги","бродяги луноречья","люди братства справедливости"}}},fp="14,268,17.598.0,34.252.0,47.240.0,44.174.0,48.212.0"}
P.entries["subzone:demon-fall-canyon"] = {n="Каньон Гибели Демона",ang={["race:Orc"]="Каждый орк обязан духовной и телесной свободой битве, которая произошла в этом каньоне, где Гром отдал жизнь, чтобы разбить демонические оковы."},sec={{t="Падение Маннорота",b="Carved into the rugged southern borders of Ashenvale near Felfire Hill and Demon Fall Ridge, this canyon bears the heavy scars of the Third War. It was here that Warchief Thrall and chieftain Grommash Hellscream tracked down the pit lord Mannoroth to break his hold over the Horde. During the fierce duel, Mannoroth incapacitated Thrall, but Grom seized the opening to drive his axe, Gorehowl, straight into the demon's chest. The resulting infernal explosion shattered the pit lord and slew Grom as well, permanently liberating the orcs from their lingering demonic servitude."},{t="Священная, но опасная пропасть",b="Following Mannoroth's demise, the Horde dubbed the canyon to commemorate Grom's final stand, erecting a monument nearby to honor his redemption. Despite the pit lord's destruction, his violent death unleashed raw demonic power that thoroughly tainted the surrounding land. Today, the canyon remains saturated in fel magic and crawls with hostile lingering lesser demons, making any pilgrimage to this hallowed ground a perilous venture."}},faq={{q="Почему это место называется Каньон Гибели Демона?",a="Орда назвала каньон так в память о гибели властелина ям Маннорота, павшего здесь от руки Громмаша Адского Крика.",al={"demon fall canyon name origin","why called demon fall canyon","how did it get its name","происхождение названия каньона гибели демона","почему так называется каньон гибели демона","откуда название"}},{q="Что произошло здесь между Громом и Манноротом?",a="Thrall and Grom confronted Mannoroth together. Thrall was knocked unconscious, but Grom dealt a lethal blow with his axe. The violent explosion of demonic fire released by Mannoroth's demise fatally wounded Grom, freeing his people from the blood curse with his dying breath.",al={"grom death","grom vs mannoroth","how did grom die","смерть грома","гром против маннорота","как погиб гром"}},{q="Почему в каньоне до сих пор бродят демоны?",a="Когда властелин ям Маннорот погиб, мощный выброс демонической энергии навсегда осквернил дно каньона. Оставшаяся скверна притягивает и укрывает младших демонов.",al={"why demons in demon fall","demon fall canyon mobs","why is it fel corrupted","почему здесь демоны","демоны каньона гибели демона","почему осквернен скверной"}},{q="Где находится памятник Грому Адскому Крику?",a="Памятник в честь Грома Адского Крика стоит неподалеку от Каньона Гибели Демона. Сюда приходят паломники из Орды, чтобы почтить воина, освободившего их народ.",al={"grom monument location","hellscream memorial","where is grom's grave","памятник грому","памятник адскому крику","где могила грома"}}},fp="17,274,21.577.0,28.436.0,43.141.0,46.275.0,46.193.0,36.176.0"}
P.entries["subzone:demon-fall-ridge"] = {n="Гряда Гибели Демона",s="Гряда Гибели Демона — оскверненное нагорье на юго-востоке Ясеневого леса, нависающее над каньоном, где пал Маннорот. Гряда кишит младшими демонами и пропитана губительной магией; в ее центре находится оскверненная берлога ночных эльфов, захваченная Пылающим Легионом.",h="Гряда Гибели Демона — оскверненное нагорье на юго-востоке Ясеневого леса, нависающее над каньоном, где пал...",kw={"ashenvale","barrow den","burning legion","demon fall canyon","demon fall ridge","diathorus the seeker","dreadlord","ясеневый лес","берлога","пылающий легион","каньон гибели демона","гряда гибели демона","диаторус искатель","повелитель ужаса"},ang={["class:Druid"]="Берлога, некогда священное убежище Изумрудного Сна, осквернена и занята демонами, поэтому эта гряда — оскорбление для Круга Кенария.",["class:Warlock"]="Присутствием Скверны здесь управляет действующий повелитель ужаса, что дает последователям темных искусств возможность увидеть организованные остатки Легиона в Калимдоре."},sec={{t="Возвышенность над скверной",b="Гряда Гибели Демона поднимается к западу от Каньона Гибели Демона и над ним и хранит следы скверны со времен Третьей войны. Внизу в каньоне произошла катастрофическая схватка Громмаша Адского Крика с властелином ям Манноротом, а эта возвышенность служит плацдармом для уцелевших демонов-захватчиков. Младшие демоны патрулируют скалистые утесы, оскверняют древний лес и угрожают всем путникам на южной границе Ясеневого леса."},{t="Оскверненный курган",b="В склоне гряды находится заброшенная берлога ночных эльфов, выдолбленная и превращенная в оплот темного колдовства. Вместо спящих друидов подземные ходы кишат порождениями Скверны. В глубинах таится Диаторус Искатель, хитрый повелитель ужаса, который правит этим собранием и направляет остатки демонов по всему лесу."}},faq={{q="Где находится Гряда Гибели Демона?",a="Гряда Гибели Демона расположена на юго-востоке Ясеневого леса. Она возвышается к западу от Каньона Гибели Демона и над ним, недалеко от границы со Степями.",al={"ridge location","where is demon fall ridge","ashenvale demon ridge","где гряда","где находится гряда гибели демона","демоническая гряда ясеневого леса"}},{q="Почему на этой гряде есть демоны?",a="Гряда нависает над местом, где во время Третьей войны погиб властелин ям Маннорот. Демоны, пережившие поражение Легиона, рассеялись по окрестным высотам и закрепились на гряде и в заброшенной берлоге.",al={"why demons here","demon fall ridge demons","burning legion presence","почему здесь демоны","демоны гряды гибели демона","присутствие пылающего легиона"}},{q="Кто командует здешними демонами?",a="Конклавом на гряде командует Диаторус Искатель — могущественный натрезим, повелитель ужаса, обитающий в самых глубоких недрах логова в кургане.",al={"who is the boss here","demon leader","diathorus the seeker","кто здесь босс","предводитель демонов","диаторус искатель"}},{q="Что за сооружение высечено в гряде?",a="Это древняя берлога ночных эльфов. Когда-то друиды использовали это святилище для входа в Изумрудный Сон, но оно было заброшено, а затем захвачено и осквернено Пылающим Легионом.",al={"barrow den","demon fall cave","what is the den","берлога","пещера гибели демона","что за берлога"}}},fp="16,252,23.462.0,21.389.0,26.149.0,35.246.0,26.148.0,44.182.0"}
P.entries["subzone:demont-s-place"] = {n="Участок Демонта",s="Участок Демонта — разоренная усадьба на юго-западе Западного Края, к западу от покинутого города Луноречье. Когда-то это был рабочий земельный надел, но ферма пришла в упадок вместе со всей областью и была захвачена разбойниками из Братства Справедливости. Сегодня ее обветшавшие изгороди и пустые поля остаются еще одной жертвой угасающего процветания края.",h="Участок Демонта — разоренная усадьба на юго-западе Западного Края, к западу от покинутого города Луноречье.",kw={"dead acre","defias","defias brotherhood","demont's place","demonts place","farmstead","moonbrook","westfall","мертвая пашня","братство справедливости","участок демонта","усадьба","луноречье","западный край"},ang={["class:Rogue"]="Обширные разоренные участки вокруг Луноречья, включая Участок Демонта, наглядно показывают беззаконную сеть, созданную Братством Справедливости по всей округе.",["faction:Alliance"]="Для путников из Альянса Участок Демонта — мрачное напоминание о том, как далеко от Западного Края отступил порядок: бывшие пахотные земли удерживают разбойники Братства Справедливости прямо под носом у королевства."},sec={{t="Разоренная усадьба",b="Участок Демонта, расположенный в виду Луноречья и гниющей Мертвой пашни, когда-то был одним из частных семейных хозяйств, снабжавших Королевство Штормград. Экономический крах и внезапный рост числа разбойников лишили ферму средств к существованию и вынудили уйти ее первых хозяев. Как и соседние поля, участок превратился в грубое убежище, занятое разбойниками, которые используют его обветшавшие земли как продолжение оплота Братства Справедливости в Луноречье."},{t="Хватка Братства",b="Из-за близости к Луноречью Участок Демонта служит Братству Справедливости опорным пунктом на окраине их областного центра. Головорезы, карманники и согнанные с мест работники слоняются среди изгородей и разрушенных построек и нападают на путников, сворачивающих с южных дорог. Пока Луноречье не отбито, а разбойники не разгромлены, эта земля слишком опасна для возвращения мирного земледелия."}},faq={{q="Где находится Участок Демонта?",a="Участок Демонта расположен на юго-западе Западного Края, сразу к западу от покинутого города Луноречье и недалеко от оскверненных полей Мертвой пашни.",al={"demont's place location","where is demonts place","demonts place map","где участок демонта","участок демонта расположение","участок демонта карта"}},{q="Кому принадлежит Участок Демонта?",a="Скорее всего, ферма принадлежала поселенцу по имени Демонт, пока крестьянские волнения и экономические трудности не охватили эти земли. Первые обитатели давно бежали или погибли, оставив разоренные угодья разбойникам.",al={"who owns demonts place","who is demont","demont farm owner","кому принадлежит участок демонта","кто такой демонт","хозяин фермы демонта"}},{q="Кто сейчас занимает ферму?",a="Усадьбу сейчас заполонили члены Братства Справедливости, которые используют ветхие земли как внешний опорный пункт рядом со своей базой в Луноречье.",al={"who is at demonts place","what enemies are at demonts place","demonts place mobs","кто на участке демонта","какие враги на участке демонта","мобы участка демонта"}},{q="Можно ли восстановить ферму?",a="Не в нынешних условиях. Пока Братство Справедливости прочно закрепилось на юге Западного Края, а Штормград не может выделить гарнизонные войска, усадьба слишком опасна для того, чтобы простые земледельцы могли ее отстроить.",al={"can you fix demonts place","is demonts place abandoned","можно ли восстановить участок демонта","заброшен ли участок демонта"}}},fp="14,374,18.482.0,27.431.0,32.151.0,24.220.0,32.179.0,39.214.0"}
P.entries["subzone:den-of-flame"] = {n="Огненное логово",s="Огненное логово — укрепленная пещера на западе Пылевых топей, к западу от Руин Деревни Каменного Молота. Изначально ее построили огры Каменного Молота как свой курган, но затем ее захватили дракониды черного драконьего рода, служащие Ониксии.",h="Огненное логово — укрепленная пещера на западе Пылевых топей, к западу от Руин Деревни Каменного Молота.",kw={"black dragonflight","den of flame","dragonspawn","dustwallow marsh","onyxia","stonemaul banner","stonemaul ruins","черный драконий род","огненное логово","дракониды","пылевые топи","ониксия","знамя каменного молота","руины деревни каменного молота"},ang={["faction:Horde"]="Огры Каменного Молота — верные союзники Орды; расправа с драконами и возвращение знамени клана из Огненного логова помогает отомстить за разрушенное поселение."},sec={{t="Захваченный курган",b="Огненное логово, построенное ограми Каменного Молота как главный курган и убежище, несет безошибочные черты грубой каменной кладки огров. Однако когда черный драконий род разорил поселение клана Каменного Молота, драконы не просто разогнали огров, но и захватили твердыню себе. Сегодня черные дракониды патрулируют горящие окрестности и вход в пещеру в тени логова Ониксии неподалеку. Несмотря на захват, внутри остались следы прежних хозяев, в том числе брошенное в хаосе знамя клана Каменного Молота."}},faq={{q="Для чего изначально построено Огненное логово?",a="Сооружение изначально построили огры Каменного Молота как главный курган своего клана. Его каменная кладка и планировка повторяют классическую архитектуру огрских кланов.",al={"who built den of flame","den of flame origin","ogre mound dustwallow","кто построил огненное логово","происхождение огненного логова","курган огров пылевые топи"}},{q="Почему этот курган захватили черные дракониды?",a="Великая черная драконица Ониксия устроила логово неподалеку в топях. Ее дракониды изгнали огров Каменного Молота из поселения и захватили пещеру как передовой форпост рода.",al={"why are there dragons here","who lives in den of flame","dragonspawn dustwallow","почему здесь драконы","кто живет в огненном логове","дракониды пылевые топи"}},{q="Смогут ли огры Каменного Молота вернуть пещеру?",a="Уцелевшие огры Каменного Молота, теперь живущие в Деревне Гиблотопь, по-прежнему считают пещеру священной землей. Они ищут храбрых героев, которые проникнут внутрь и вернут у драконидов утраченное знамя клана.",al={"stonemaul banner","reclaiming the den","знамя каменного молота","вернуть логово"}}},fp="12,257,17.590.0,47.161.0,45.194.0,41.210.0"}
P.entries["subzone:dire-maul"] = {n="Забытый Город",s="Забытый Город — руины Эльдре'Таласа, древнего города высокорожденных, скрытого в глуши Фераласа. Город был построен для защиты тайн магии королевы Азшары, а теперь его рушащиеся площади и огромные колизеи поделены между захватившими их ограми Гордок, вторгшимися сатирами и иссохшими остатками первых эльфийских хранителей.",h="Забытый Город — руины Эльдре'Таласа, древнего города высокорожденных, скрытого в глуши Фераласа.",kw={"dire maul","eldre'thalas","feralas","gordok","gordunni","immol'thar","shen'dralar","tortheldrin","забытый город","эльдре'талас","фералас","гордок","гордунни","иммол'тар","шен'дралар","тортельдрин"},ang={["class:Mage"]="В разрушенных библиотеках Шен'дралар хранятся чародейские трактаты и тайны, сохранившиеся со времен до Великого Раскола, под охраной призраков великих чародеев.",["race:NightElf"]="Эльдре'Талас — трагический памятник безудержной чародейской гордыне и демоническим сделкам, сломившим древнюю империю кальдораев."},sec={{t="Эльдре'Талас и Великий Раскол",b="Двенадцать тысяч лет назад Эльдре'Талас был великолепным оплотом любимых чародеев королевы Азшары — Шен'дралар. Когда во время Великого Раскола Источник Вечности рухнул, принц Тортельдрин сплел магический барьер, защитивший город от гибели. Отрезанные от источника магии, уцелевшие высокорожденные заточили огромного демона Иммол'тара под своим святилищем и тысячелетиями вытягивали его демоническую сущность, поддерживая свое бессмертие и чародейскую силу."},{t="Разделенные руины",b="Века изоляции и угасающей силы довели принца Тортельдрина до безумия, и он истребил большую часть своих подданных, чтобы небольшая клика могла завладеть остатками энергии демона. Сегодня внешние районы огромного комплекса заброшены и отданы другим угрозам. Огры Гордунни занимают Палаты клана Гордок и устраивают на арене жестокие гладиаторские игры, а Алззин Перевертень и его оскверненные сатиры изнутри разлагают Квартал Криводревов."}},faq={{q="Как первоначально назывался Забытый Город?",a="Забытый Город изначально был Эльдре'Таласом — роскошным городом ночных эльфов, построенным двенадцать тысяч лет назад сектой Шен'дралар для защиты самых ценных тайных знаний королевы Азшары.",al={"dire maul original name","eldre'thalas history","who built dire maul","первоначальное название забытого города","история эльдре'таласа","кто построил забытый город"}},{q="Кто сейчас живет в Забытом Городе?",a="Комплекс разделен на несколько враждебных зон. Огры Гордунни под властью короля Гордока управляют северными палатами, сатиры и оскверненные древни заполонили восточные сады, а замкнутые остатки чародеев-высокорожденных едва выживают в западных святилищах.",al={"who is in dire maul","dire maul occupants","what monsters are in dire maul","кто в забытом городе","обитатели забытого города","какие монстры в забытом городе"}},{q="Как город пережил Раскол?",a="Когда во время Великого Раскола континент разорвало на части, принц Тортельдрин и его чародеи наложили мощное защитное заклинание, которое уберегло Эльдре'Талас от разрушений, поглотивших окружавшую его империю.",al={"how did eldre'thalas survive","sundering shield dire maul","why wasn't it destroyed","как пережил эльдре'талас","защита раскола забытый город","почему не был разрушен"}},{q="Почему высокорожденные здесь используют демоническую энергию?",a="Когда Источник Вечности был уничтожен, Шен'дралар тяжело страдали от нехватки магии. Чтобы сохранить силу и бессмертие, они подчинили демона Иммол'тара и вытягивали его сущность, чтобы выжить.",al={"immol'thar dire maul","why do shen'dralar drain a demon","demon in dire maul","иммол'тар забытый город","зачем шен'дралар высасывают демона","демон в забытом городе"}},{q="Что происходит на арене Забытого Города?",a="Known as the Maul, the open coliseum in the city center is used by the ogres and slavemasters as a fighting pit for gladiatorial tournaments, blood sports, and challenges to the Gordok throne.",al={"dire maul coliseum","the maul pvp","gladiators dire maul"}}},fp="9,341,36.477.0,14.450.1,37.180.0,27.271.0,39.213.0,48.201.0,39.192.0"}
P.entries["subzone:direforge-hill"] = {n="Зловещий холм",s="Зловещий холм — неприступное нагорье на северо-востоке Болотины, к юго-востоку от Дун Модра и к северо-востоку от Зеленого Пояса. Чернокнижник из дворфов клана Черного Железа Балгорас Нечистый командует вражеским лагерем на его склонах.",h="Зловещий холм — неприступное нагорье на северо-востоке Болотины, к юго-востоку от Дун Модра и к...",kw={"balgaras","balgaras the foul","dark iron dwarves","direforge","direforge hill","dun modr","green belt","wetlands","балгорас","балгорас нечистый","дворфы из клана черного железа","зловещий холм","дун модр","зеленый пояс","болотина"},ang={["class:Druid"]="Друидам, идущим через Болотину, приходится считаться с враждебным лагерем Черного Железа на Зловещем холме.",["race:Dwarf"]="Для дворфов Бронзоборода из Стальгорна вторжение предательского клана Черного Железа в Болотину — особенно под предводительством чернокнижников вроде Балгораса — это возмутительное оскорбление, на которое нужно ответить холодной сталью."},sec={{t="Оплот темной магии",b="Зловещий холм служит крупным лагерем Черного Железа на северо-востоке Болотины. Балгорас Нечистый, чернокнижник из клана Черного Железа, командует враждебными дворфами, занимающими холм к юго-востоку от Дун Модра."},{t="Угроза для Болотины",b="Дворфы из клана Черного Железа, занявшие Зловещий холм, угрожают путникам на северо-востоке Болотины. Враждебным лагерем командует Балгорас Нечистый."}},faq={{q="Где находится Зловещий холм?",a="Зловещий холм находится в северо-восточной части Болотины. Он лежит к юго-востоку от Дун Модра, чуть северо-восточнее поросшего зеленью Зеленого Пояса и северо-западнее скалистых утесов Гряды Ящеров.",al={"direforge hill location","where is direforge hill","direforge wetlands","где зловещий холм","расположение зловещего холма","зловещий холм болотина"}},{q="Кто сейчас контролирует Зловещий холм?",a="Холм занят враждебными дворфами из клана Черного Железа под началом чернокнижника Балгораса Нечистого. Они укрепили высоту баррикадами, сторожевыми башнями и ямами с открытым огнем.",al={"who is at direforge hill","who lives at direforge hill","direforge hill mobs","кто на зловещем холме","кто живет на зловещем холме","монстры зловещего холма"}},{q="Чем важен Зловещий холм для Болотины?",a="Холм — враждебный лагерь Черного Железа на северо-востоке Болотины. Балгорас Нечистый и его дворфы угрожают путникам в окрестностях.",al={"why is direforge hill important","direforge threat","what is happening at direforge hill","почему важен зловещий холм","угроза зловещего холма","что происходит на зловещем холме"}},{q="Кто такой Балгорас Нечистый?",a="Балгорас Нечистый — дворф-чернокнижник из клана Черного Железа, командующий войсками, расположившимися на Зловещем холме. Его порченая магия и агрессивное присутствие в холмах делают его первоочередной целью для защитников болот.",al={"balgaras","balgaras the foul lore","who is balgaras","балгорас","балгорас нечистый","кто такой балгорас"}}},fp="14,211,25.198.0,26.159.0,32.191.0,38.180.0,50.155.0,25.212.0"}
P.entries["subzone:dolanaar"] = {n="Доланаар",s="Доланаар — тихое поселение ночных эльфов в ветвях центрально-восточной части Тельдрассила. Расположенный к юго-западу от Тенистой долины, он служит первым настоящим городом, который встречают юные кальдораи после ухода с защищенных тренировочных земель. Здесь собираются следопыты, друиды и ремесленники, чтобы наставлять новичков и справляться со странными напастями, тревожащими Мировое Древо.",h="Доланаар — тихое поселение ночных эльфов в ветвях центрально-восточной части Тельдрассила.",kw={"darnassus","dolanaar","kaldorei","night elf town","shadowglen","teldrassil","дарнасс","доланаар","кальдораи","город ночных эльфов","тенистая долина","тельдрассил"},ang={["class:Druid"]="Доланаар — важная остановка для посвященных, ищущих наставления о недугах Тельдрассила и учащихся настраивать свой дух на природное равновесие.",["race:NightElf"]="Для юных ночных эльфов Доланаар — первые шаги в большой мир, где их обеты беречь природу подвергаются испытанию, пока они наблюдают растущую порчу на Мировом Древе."},sec={{t="Перекресток ветвей",b="Доланаар, раскинувшийся под пышным пологом к юго-западу от Тенистой долины, — важный перекресток для путников в Тельдрассиле. Дома и платформы построены в традиционном стиле ночных эльфов и гармонично вплетены в лес. Селение дает новичкам первое всестороннее обучение ремеслам, боевым искусствам и природным умениям и стоит на дороге к столице, Дарнассу. Благодаря центральному положению вести об оскверненных животных, агрессивных фурболгах и мерзких мхах из окрестных ветвей неизбежно попадают в совет Доланаара."}},faq={{q="Для чего нужен Доланаар?",a="Доланаар — главный центр заданий и застава для юных ночных эльфов, покидающих Тенистую долину. Он служит административным центром на востоке Тельдрассила: здесь живут ремесленники, обучают боевым и магическим искусствам и есть связь со столицей.",al={"what is dolanaar","dolanaar purpose","why dolanaar matters","что такое доланаар","назначение доланаара","чем важен доланаар"}},{q="Где находится Доланаар?",a="Доланаар лежит в центрально-восточной части Тельдрассила, недалеко по тропе к юго-западу от Тенистой долины и к востоку от столицы, Дарнасса.",al={"dolanaar location","where is dolanaar","dolanaar directions","где доланаар","расположение доланаара","как пройти в доланаар"}},{q="Как отсюда добраться до Дарнасса?",a="В Доланааре нет собственного пункта полетов. Путники идут по лесной дороге на запад через Тельдрассил и пешком доходят до ворот Дарнасса.",al={"travel to darnassus","flight master dolanaar","dolanaar to darnassus","путь в дарнасс","распорядитель полетов доланаар","из доланаара в дарнасс"}},{q="Какие угрозы нависают над Доланааром?",a="Леса вокруг Доланаара страдают от странной порчи, расползающейся по Тельдрассилу: рядом появились больные звери, обезумевшие древни и враждебные племена фурболгов.",al={"trouble in dolanaar","dolanaar problems","dolanaar quests","беда в доланааре","проблемы доланаара","задания доланаара"}}},fp="8,383,22.588.0,32.257.0,26.158.0,44.137.0,29.176.0"}
P.entries["subzone:dormitory"] = {n="Общежитие",s="Общежитие — жилой сектор павшей технологической столицы Гномрегана. Когда-то здесь жили бесчисленные гномы, а теперь он забит радиоактивными осадками и кишит свирепыми облученными троггами.",h="Общежитие — жилой сектор павшей технологической столицы Гномрегана.",kw={"clean zone","dormitory","gnomeregan","hall of gears","punchograph","trogg","чистая зона","общежитие","гномреган","зал шестеренок","перфограф","трогг"},ang={["profession:Engineering"]="Даже при полном отказе биозащиты автоматические терминалы вроде «Матрикс 3005-B» продолжают безупречно обрабатывать алгоритмические перфокарты безопасности.",["race:Gnome"]="Войти в Общежитие для каждого гнома — личное дело: когда-то это был ваш дом, а теперь он превращен в облученные руины и захвачен теми самыми тварями, что изгнали вас."},sec={{t="Захваченный дом",b="Общежитие, расположенное сразу за дезактивационными камерами Чистой зоны, прежде служило домом изобретателям, рабочим и семьям Гномрегана. Когда главный механик Меггакрут запустил аварийный сброс радиации, чтобы сразить орду вторгшихся троггов, этот густонаселенный сектор стал ловушкой. Сегодня его общие залы и жилые блоки полностью покинуты гномами и заняты мутировавшими троггами, процветающими в радиоактивных испарениях. Путники, спускающиеся на нижние уровни города, должны пробиться через это печальное напоминание о катастрофе, чтобы добраться до нижнего Зала Шестеренок."},{t="Перфокарточные терминалы",b="Среди заброшенных жилых помещений до сих пор работают остатки административного аппарата города. Машины «Матричный перфограф 3005-B» обрабатывают перфокарты безопасности. Эти терминалы дают допуск к терминалам данных повышенной защиты в глубине Гномрегана, помогая восстановить важные записи, оставленные гномами при бегстве."}},faq={{q="Для чего использовалось Общежитие до падения?",a="Общежитие служило повседневным жильем для многочисленных изобретателей, рабочих Гномрегана и их семей. Близость к промышленным и гражданским секторам позволяла гномам легко добираться от рабочих мест до коек, пока токсичная радиация не затопила нижние коридоры.",al={"what is dormitory","dormitory purpose","who lived here","что такое общежитие","назначение общежития","кто здесь жил"}},{q="Почему Общежитие кишит троггами?",a="Когда трогги прорвались в город снизу, главный механик Меггакрут затопил город токсичным газом, чтобы их убить. Вместо уничтожения радиация мутировала уцелевших троггов, сделав их более свирепыми и полностью устойчивыми к облученной среде жилых кварталов.",al={"why troggs here","trogg infestation dormitory","irradiated troggs","почему тут трогги","трогги в общежитии","облученные трогги"}},{q="Куда ведет Общежитие?",a="Общежитие находится сразу за санитарными шлюзами Чистой зоны и соединяет верхние уровни с нижним уровнем Зала Шестеренок, поэтому это неизбежное узкое место для всех, кто продвигается вглубь Гномрегана.",al={"dormitory exits","where to go from dormitory","dormitory connections","выходы из общежития","куда идти из общежития","переходы общежития"}},{q="Что за перфографы «Матрикс» стоят здесь?",a="Терминалы «Матричный перфограф 3005-B» обрабатывают перфокарты безопасности. Закодированные карты дают допуск к терминалам повышенной защиты, позволяя восстановить важные данные, оставленные в Гномрегане.",al={"punchograph","matrix punchograph 3005-B","punch cards","перфограф","матрикс 3005-b","перфокарты"}}},fp="9,240,14.610.0,21.331.0,48.302.0,42.294.0,30.221.0,52.202.0"}
P.entries["subzone:drag"] = {n="Тракт",s="Тракт — оживленная, тенистая улица, прорубленная в красной скале Оргриммара. Она соединяет Аллею Силы с Аллеей Чести и Аллеей Мудрости. Во всем Дуротаре Тракт известен как сердце торговли столицы: стены его каньона застроены лавками ремесленников, торговцев и мастеров. Здесь же скрыт пещерный спуск в печально известную Расселину Теней.",h="Тракт — оживленная, тенистая улица, прорубленная в красной скале Оргриммара.",kw={"alchemy","cleft of shadow","drag","leatherworking","nogg","orgrimmar","salvage","tailoring","the drag","алхимия","расселина теней","тракт","кожевничество","ногг","оргриммар","утиль","портняжное дело"},ang={["faction:Horde"]="Каждый путник, проходящий через столицу, рано или поздно ступает на Тракт: он напрямую связывает военное ядро Оргриммара с жилыми и мистическими кварталами.",["profession:Engineering"]="На Тракте находится Механическая мастерская Ногга, где гоблины-механики передают Орде чертежи, взрывчатку и особые инженерные знания."},sec={{t="Улица мастеров",b="Тракт, укрытый глубоко между красными стенами каньона Оргриммара, служит торговым хребтом столицы Орды. Если Аллея Силы отведена под военный сбор и управление, то на Тракте протекает повседневная жизнь города. Улица лежит в тени высоких утесов и шкур, в воздухе стоят запахи дубильных чанов и кипящих алхимических котлов, а шестерни механиков громыхают без умолку. Здесь собрались мастера почти всех ремесел: они занимаются своим делом и обучают начинающих искателей приключений — от кожевничества и портняжного дела до инженерных мастерских гоблинов, таких как Механическая мастерская Ногга."},{t="Перекресток теней и ремесел",b="Помимо торговых лавок и скупок утиля, Тракт занимает непростое место в общественной географии Оргриммара. В стене каньона находится охраняемый вход в подземную Расселину Теней. Поэтому Тракт — неизбежный перекресток, где под тусклыми пыльными скальными навесами каньона встречаются честные торговцы, шаманы, идущие в Аллею Мудрости, и скрытные последователи темных искусств."}},faq={{q="Для чего служит Тракт в Оргриммаре?",a="Тракт — главный торговый квартал Оргриммара. Здесь есть учителя и торговцы припасами для множества профессий, в том числе алхимии, портняжного дела, кожевничества, снятия шкур, наложения чар и инженерного дела, а также торговцы утилем и обычными товарами.",al={"purpose of the drag","what is the drag","what shops are in the drag","назначение тракта","что такое тракт","какие магазины на тракте"}},{q="Куда ведет Тракт?",a="Каньонная улица соединяет Аллею Силы на юге с Аллеей Чести на северо-востоке, а также имеет проходы к Аллее Мудрости. Главное — вход, ведущий вниз, в темные пещеры Расселины Теней, расположен вдоль западного склона Тракта.",al={"drag connections","how to get to cleft of shadow","where does the drag go","пути тракта","как пройти в расселину теней","куда ведет тракт"}},{q="Кто такой Ногг?",a="Ногг — предприимчивый гоблин-инженер, владелец Механической мастерской Ногга на Тракте. Он известный учитель инженерного дела и поставщик приспособлений для Орды.",al={"noggs machine shop","who runs the machine shop","мастерская ногга","кто владеет мастерской"}},{q="Все ли учителя профессий находятся на Тракте?",a="Большинство ремесленных и собирательских профессий держат мастерские на нижнем и верхнем уступах Тракта, но не все. В частности, кузнецы и горняки города предпочитают огненные кузни Аллеи Чести.",al={"where are trainers in orgrimmar","first aid trainer drag","где учителя в оргриммаре","учитель первой помощи тракт"}}},fp="4,367,26.607.0,33.442.0,39.260.0,25.291.0,12.177.0,48.213.0"}
P.entries["subzone:dragonmaw-gates"] = {n="Врата Драконьей Пасти",s="Врата Драконьей Пасти — ряд внушительных укреплений на горной дороге, ведущей вверх от восточной Болотины. Эти тяжелые заграждения построены, чтобы охранять крутой подъем к горной крепости Грим Батол, и преграждают путь на проклятые высоты дворфийских руин.",h="Врата Драконьей Пасти — ряд внушительных укреплений на горной дороге, ведущей вверх от восточной Болотины.",kw={"axtroz","dragonmaw clan","dragonmaw gates","grim batol","mountain pass","red dragonflight","wetlands","акстроз","клан драконьей пасти","врата драконьей пасти","грим батол","горный перевал","красный драконий род","болотина"},ang={["faction:Alliance"]="Альянс настороженно следит за вратами: все, что появится на высокой дороге, угрожает спокойствию всей Болотины.",["race:Dwarf"]="Для дворфов Врата Драконьей Пасти — запечатанный порог Грим Батола, родового дома, оставленного после Войны трех молотов и позднее оскверненного орками клана Драконьей Пасти."},sec={{t="Стражи Грим Батола",b="Врата Драконьей Пасти, высеченные в неприступных пиках на востоке Болотины, перекрывают извилистую дорогу, что поднимается в горы к Грим Батолу. Они названы в честь клана Драконьей Пасти — орков, державших горный город дворфов во время Второй войны, и до сих пор остаются сильно укрепленными пунктами проверки. Всякому, кто пытается подняться на высоты, придется столкнуться с опасностями перевала, где могучие драконы и мрачные напоминания о темной истории клана все еще отбрасывают длинную тень."},{t="Спорный порог",b="Хотя орки Драконьей Пасти были разбиты и рассеяны после уничтожения Души Демона, горная тропа остается исключительно опасной. Возле врат, на извилистых склонах и уступах, замечали могучих красных драконов. Из-за чудовищных драконов и остатков клана Драконьей Пасти, скрывающихся в окрестных холмах, врата остаются прочной преградой для любого путника, дерзнувшего подняться на высоты."}},faq={{q="Куда ведут Врата Драконьей Пасти?",a="Врата перекрывают извилистую горную тропу, поднимающуюся на восток от Болотины прямо к проклятому городу-крепости Грим Батол и окрестным горным высотам.",al={"path past dragonmaw gates","what is behind dragonmaw gates","road past gates","путь за вратами драконьей пасти","что за вратами драконьей пасти","дорога за вратами"}},{q="Почему они называются Вратами Драконьей Пасти?",a="Они получили имя от клана Драконьей Пасти — орков, занявших соседнюю дворфийскую крепость Грим Батол во время Второй войны и с помощью мерзкого колдовства поработивших красных драконов.",al={"why called dragonmaw gates","dragonmaw gate name","dragonmaw orcs wetlands","почему врата драконьей пасти","название врат драконьей пасти","орки драконьей пасти болотина"}},{q="Могут ли путники пройти через врата?",a="Огромные врата наглухо закрыты и надежно защищены, поэтому обычный проход в высокие горы закрыт.",al={"can you open dragonmaw gates","getting through dragonmaw gates","можно ли открыть врата драконьей пасти","как пройти через врата драконьей пасти"}},{q="Кто охраняет дорогу вокруг врат?",a="Дорогу и ближайшие неприступные перевалы населяют свирепые красные драконы и их порождения, а также разрозненные орки и темные угрозы, все еще цепляющиеся за горные склоны.",al={"who is at dragonmaw gates","dragons at dragonmaw gates","axtroz dragonmaw gates","кто у врат драконьей пасти","драконы у врат драконьей пасти","акстроз врата драконьей пасти"}}},fp="15,272,23.504.0,21.430.0,34.164.0,40.178.0,37.107.0,37.177.0"}
P.entries["subzone:dragonmurk"] = {n="Земля Драконов",s="Земля Драконов — обширный опасный участок юга Пылевых топей, кишащий порождениями и детенышами черных драконов. С флангов ее окружают древние руины огров и выжженные пещеры, и она служит враждебным внешним рубежом для выводка Ониксии.",h="Земля Драконов — обширный опасный участок юга Пылевых топей, кишащий порождениями и детенышами черных...",kw={"black dragonflight","den of flame","dragonmurk","dragonspawn","dustwallow marsh","onyxia","stonemaul ruins","whelps","черный драконий род","огненное логово","земля драконов","порождения драконов","пылевые топи","ониксия","руины деревни каменного молота","дракончики"},ang={["faction:Alliance"]="Терамор настороженно следит за Землей Драконов: неподконтрольный выводок черных драконов так близко к крепости легко может обернуться бедой.",["faction:Horde"]="Драконы Земли Драконов изгнали огров Каменного Молота из их деревни и постоянно угрожают экспедициям Орды, уходящим вглубь болот."},sec={{t="Выводок в трясине",b="Земля Драконов тянется по югу внутренней части Пылевых топей и отмечает порог, за которым сырые болота уступают место владениям черного драконьего рода. Водные пути и густая грязь кишат черными драконидами, порождениями драконов и голодными детенышами. Окрестности сильно пострадали от их присутствия: соседние земли, такие как разрушенная деревня Каменного Молота и выжженная пещера, известная как Огненное логово, полностью оказались во власти рода."},{t="Стражи матери выводка",b="Стаи драконов и стражей по всей Земле Драконов — не случайные бродяги. Юг Пылевых топей — главное место гнездования Ониксии, дочери Смертокрыла, в Калимдоре. Драконы яростно патрулируют трясину, уничтожая чужаков и защищая кладку от разведчиков Терамора и ближних лагерей Орды."}},faq={{q="Что такое Земля Драконов?",a="Земля Драконов — южная область Пылевых топей, сильно заселенная детенышами, драконами и драконидами черного драконьего рода.",al={"what is dragonmurk","where is dragonmurk","dragonmurk location","что такое земля драконов","где земля драконов","расположение земли драконов"}},{q="Почему здесь так много черных драконов?",a="На юге Пылевых топей находится логово Ониксии, матери выводка черного драконьего рода. Земля Драконов служит защитным буфером, где ее потомство и слуги могут гнездиться, взрослеть и отражать внешние угрозы.",al={"why black dragons in dustwallow","who leads the dragons here","onyxia dragons dustwallow","почему черные драконы в пылевых топях","кто главный у драконов","ониксия драконы пылевые топи"}},{q="Какие достопримечательности находятся рядом с Землей Драконов?",a="Земля Драконов охватывает и окружает такие важные места, как Огненное логово и Руины Деревни Каменного Молота, оба захвачены и заняты черными драконидами.",al={"dragonmurk landmarks","what is near dragonmurk","places around dragonmurk","достопримечательности земли драконов","что рядом с землей драконов","места вокруг земли драконов"}},{q="Безопасна ли Земля Драконов для путников?",a="Совсем нет. Драконы в Земле Драконов неизменно враждебны и агрессивны, поэтому это одна из самых опасных диких областей юга Калимдора.",al={"is dragonmurk dangerous","can i walk through dragonmurk","опасна ли земля драконов","можно ли пройти через землю драконов"}}},fp="10,237,18.495.0,24.349.1,19.152.0,41.215.0,41.165.0,33.153.0"}
P.entries["subzone:dreadmaul-post"] = {n="Форт Молота Ужаса",s="Форт Молота Ужаса — укрепленное поселение огров в испепеленных пустошах Выжженных земель. Основанный кланом Молота Ужаса, этот холм служит укрепленным оплотом близ Темного портала, где огры обосновались после прибытия из Дренора. Путникам в этих краях придется иметь дело с этими свирепыми громилами и коварной местностью вокруг их лагеря.",h="Форт Молота Ужаса — укрепленное поселение огров в испепеленных пустошах Выжженных земель.",kw={"blasted lands","dark portal","dreadmaul","dreadmaul post","ogre mound","ogres","выжженные земли","темный портал","молот ужаса","форт молота ужаса","холм огров","огры"},ang={["faction:Alliance"]="Для разведчиков Альянса, наблюдающих за Темным порталом, огры Молота Ужаса — укоренившаяся, жестокая угроза, усложняющая любой патруль по южным землям континента.",["faction:Horde"]="Хотя огры когда-то сражались вместе со Старой Ордой, дикие кланы вроде Молота Ужаса давно порвали связи с новым порядком Тралла и считают всех путников враждебными захватчиками."},sec={{t="Наследие Дренора",b="Когда Орда в былые десятилетия хлынула через Темный портал, кланы огров шли вместе с ней в Азерот. Клан Молота Ужаса решил закрепиться у самого прохода, возведя грубые каменные холмы и земляные укрепления по красным пустошам Выжженных земель. Форт Молота Ужаса — один из их главных оплотов: он крепко удерживает бесплодные земли, сражаясь с бродячими зверями и любыми путниками, глупо подошедшими к их владениям."}},faq={{q="Кто живет в Форте Молота Ужаса?",a="Форт Молота Ужаса населяет клан огров Молота Ужаса. Эти громадные громилы перешли из Дренора через Темный портал во время войн и прочно обосновались в безлюдных скалах Выжженных земель.",al={"who is at dreadmaul post","dreadmaul post inhabitants","dreadmaul ogres","кто в форте молота ужаса","жители форта молота ужаса","огры молота ужаса"}},{q="Почему огры до сих пор в Выжженных землях?",a="После краха Старой Орды и запечатывания Темного портала многие огры рассеялись по Азероту. Но клан Молота Ужаса остался рядом с местом своего прибытия, сделав своим домом изуродованную безжизненную равнину вокруг уснувшего разлома.",al={"why dreadmaul here","ogres blasted lands","why ogres near portal","почему молот ужаса здесь","огры выжженные земли","почему огры у портала"}},{q="Кто еще бродит возле форта?",a="Кроме самих огров, возле Форта Молота Ужаса по красной пустыне бродят свирепые местные хищники, такие как скорпиды и василиски.",al={"draenei blasted lands","who is near dreadmaul","creatures dreadmaul post","дренеи выжженные земли","кто рядом с молотом ужаса","существа форта молота ужаса"}}},fp="14,391,19.456.0,28.227.0,45.253.0,40.125.0"}
P.entries["subzone:dreadmaul-rock"] = {n="Скала Молота Ужаса",s="Скала Молота Ужаса — высокая скала с комплексом пещер, поднимающаяся над огненными пустошами Пылающих степей. Это главная база огров Огненного Чрева, живущих в ее извилистых подземных холмах.",h="Скала Молота Ужаса — высокая скала с комплексом пещер, поднимающаяся над огненными пустошами Пылающих степей.",kw={"burning steppes","dreadmaul peak","dreadmaul rock","firegut ogres","ogre mound","пылающие степи","вершина молота ужаса","скала молота ужаса","огры огненного чрева","холм огров"},ang={["faction:Alliance"]="Для сил Альянса, охраняющих пограничные перевалы со стороны Красногорья, агрессивные огры Скалы Молота Ужаса — постоянная жестокая угроза, нависшая прямо за северным хребтом.",["faction:Horde"]="Путникам Орды, идущим по степям к Черной горе, следует осторожно обходить Скалу Молота Ужаса, чтобы не навлечь гнев территориального клана Огненного Чрева."},sec={{t="Оплот Огненного Чрева",b="Скала Молота Ужаса возвышается над выжженными равнинами Пылающих степей — это огромная каменная глыба, изрытая лабиринтом пещер. Хотя название намекает на возможную связь с ограми Молота Ужаса из Выжженных земель, скалой прочно владеет клан Огненного Чрева. Эти грубые огры используют возвышенные тропы, утесы и земляные холмы внутри как укрепленный лагерь, господствуя над окрестными пустошами и угрожая всем, кто пытается пройти по северным склонам к Вершине Черной горы."}},faq={{q="Кто живет на Скале Молота Ужаса?",a="Скала Молота Ужаса — главная база огров Огненного Чрева. Они населяют как внешние тропы на утесах, так и сложную систему пещер внутри скалы.",al={"who is at dreadmaul rock","dreadmaul rock mobs","what ogres are at dreadmaul rock","кто на скале молота ужаса","враги на скале молота ужаса","какие огры на скале молота ужаса"}},{q="Почему она называется Скалой Молота Ужаса, если здесь живут огры Огненного Чрева?",a="Хотя вершиной сейчас владеет клан Огненного Чрева, название ясно указывает, что когда-то она могла принадлежать клану огров Молота Ужаса, который сильно присутствует к югу, в Выжженных землях.",al={"why dreadmaul","dreadmaul or firegut","dreadmaul ogres connection","почему молот ужаса","молот ужаса или огненное чрево","связь огров молота ужаса"}},{q="Как устроена скала?",a="Скала Молота Ужаса состоит из крутых внешних спусков, вьющихся вверх по утесу, и запутанной сети внутренних пещер, полной холмов и жилищ огров.",al={"dreadmaul caves","dreadmaul peak layout","navigating dreadmaul rock","пещеры молота ужаса","план вершины молота ужаса","как пройти по скале молота ужаса"}},{q="Где находится Скала Молота Ужаса?",a="Она находится в Пылающих степях и возвышается заметной горообразной скалой к северу от дороги к Красногорью и к востоку от Черной горы.",al={"dreadmaul rock location","where is dreadmaul rock","burning steppes ogre base","расположение скалы молота ужаса","где скала молота ужаса","база огров пылающие степи"}}},fp="14,233,25.510.0,28.162.0,58.190.0,36.151.0,32.165.0"}
P.entries["subzone:dreadmist-peak"] = {n="Вершина Багрового Тумана",s="Вершина Багрового Тумана — зазубренная безлюдная гора к северо-западу от Перекрестка в Степях. Окутанная неестественным багровым мороком, вершина служит укромным оплотом демонических культистов Пылающего Клинка.",h="Вершина Багрового Тумана — зазубренная безлюдная гора к северо-западу от Перекрестка в Степях.",kw={"barrens","burning blade","dreadmist den","dreadmist peak","jaina proudmoore","miasma","sarilus foulborne","zmodlor","степи","пылающий клинок","пещера багрового тумана","вершина багрового тумана","джайна праудмур","морок","сарилус грязнорожденный","змодлор"},ang={["class:Druid"]="Таурены-друиды из Лагеря Таурахо исследуют источники воды Вершины Багрового Тумана, пытаясь определить неестественные яды, отравляющие газелей и диких зверей равнин.",["faction:Alliance"]="Агенты Альянса, действующие близ Ясеневого леса, прослеживают порочную магию, связанную с оскверненными водными элементалями, до Сарилуса Грязнорожденного — призывателя-нежити, затаившегося на вершине."},sec={{t="Логово порчи",b="Вершина Багрового Тумана возвышается над сухими саваннами Степей как средоточие осязаемого зла. Когда путники поднимаются по скалам, яркое небо заслоняет густая красноватая дымка — остаток морока древнего демонического проклятия. На гребне горы и в ее подземных пустотах тайно действует культ Пылающего Клинка, укрывая чернокнижников, токсикологов и злобных гренделей. Отсюда культисты травят близлежащие грунтовые воды и плетут интриги против молодых держав, устанавливающих власть над центральным Калимдором."},{t="Сплетение замыслов",b="Помимо чернокнижников и их темных обрядов вокруг Пещеры Багрового Тумана, вершина привлекла и других злодеев. Отрекшийся маг-изгой Сарилус Грязнорожденный разбил лагерь на высотах и, подчиняя силы стихий, портил духов воды вплоть до Ясеневого леса. Кроме того, когда мелкий демон Змодлор задумал разжечь открытую войну между Ордой Тралла и Тераморомом, именно здесь леди Джайна Праудмур и Эгвин настигли и изгнали его, прервав катастрофическое кровопролитие."}},faq={{q="Почему воздух вокруг Вершины Багрового Тумана красный и туманный?",a="Красновато-оранжевый туман, окутывающий вершину, — остаточный морок древнего демонического проклятия, поддерживаемый и усиливаемый мерзкими обрядами обитающих здесь чернокнижников Пылающего Клинка.",al={"red mist dreadmist","orange fog dreadmist peak","why is dreadmist red","красный туман багровый","оранжевый туман вершина багрового тумана","почему багровый туман красный"}},{q="Кто контролирует Вершину Багрового Тумана?",a="Гора находится под властью культа Пылающего Клинка, который следит за ее тропами и охраняет Пещеру Багрового Тумана внизу. Ее также занимают темные личности, например мятежный маг-нежить Сарилус Грязнорожденный.",al={"who lives on dreadmist peak","dreadmist peak enemies","burning blade dreadmist","кто живет на вершине багрового тумана","враги вершины багрового тумана","пылающий клинок багровый туман"}},{q="Что произошло здесь между Терамором и Ордой?",a="Через три года после Третьей войны мелкий демон по имени Змодлор использовал Вершину Багрового Тумана как базу, чтобы разжечь вражду между Ордой и Терамором. Леди Джайна Праудмур в сопровождении Эгвин выследила заговор и изгнала демона, едва предотвратив войну.",al={"jaina dreadmist peak","zmodlor dreadmist","theramore war barrens","джайна вершина багрового тумана","змодлор багровый туман","война терамор степи"}},{q="Как добраться до Вершины Багрового Тумана?",a="Идите по главной дороге на север от Перекрестка до развилки к Ясеневому лесу и Когтистым горам. Повернитесь на северо-запад, чтобы увидеть нависающую скалу, затем поднимитесь по спиральной тропе на ее восточном склоне.",al={"getting to dreadmist peak","dreadmist peak location","dreadmist path","как добраться до вершины багрового тумана","где вершина багрового тумана","тропа багрового тумана"}}},fp="14,224,19.572.0,24.503.1,51.189.0,28.206.0,51.266.0,32.195.0"}
P.entries["subzone:dreadmurk-shore"] = {n="Зловещий берег",s="Зловещий берег — туманное побережье и разбросанные острова Пылевых топей к северу, у границы Степей. Здесь господствуют агрессивные мурлоки Болотные Плавники и морские твари, а ныне эти коварные воды стали укрытием для потерпевших кораблекрушение разбойников Братства Справедливости.",h="Зловещий берег — туманное побережье и разбросанные острова Пылевых топей к северу, у границы Степей.",kw={"alcaz island","defias","dreadmurk shore","dustwallow marsh","mirefin","murloc","shipwreck","theramore","остров алькац","братство справедливости","зловещий берег","пылевые топи","болотные плавники","мурлок","кораблекрушение","терамор"},ang={["class:Rogue"]="Уединенные лагеря и затонувшие обломки вдоль берега дают отличную возможность выследить тайные грузы Братства Справедливости и проскользнуть мимо свирепых стражей Болотных Плавников.",["faction:Alliance"]="Обнаружение выживших из Братства Справедливости так близко к Терамору говорит о заговорах, выходящих далеко за пределы Западного Края и прямо угрожающих стабильности Альянса в Калимдоре."},sec={{t="Коварный берег",b="Зловещий берег тянется вдоль северо-восточной окраины Пылевых топей между островом Терамор и крепостью Северной Стражи и представляет собой мрачную полосу илистых отмелей, приливных заводей и туманных островков. Побережье наводнено племенем Болотных Плавников — территориальным кланом мурлоков, которые яростно нападают на всех путников, приближающихся к их прибрежным деревням. В мелководье рыщут морские черепахи и водные хищники, из-за чего берег опасен для передвижения даже без учета окружающих болот."},{t="Лазутчики Братства Справедливости",b="Помимо местных болотных существ, берег привлек пристальное внимание Терамора из-за присутствия людей-преступников. Корабль Братства Справедливости потерпел крушение в водах между берегом и Островом Алькац, высыпав разбойников на песок и островки. Присутствие этих преступников из Восточных королевств так близко к твердыне леди Джайны Праудмур — тревожный поворот, угрожающий хрупкому балансу сил по всей бухте."}},faq={{q="Где находится Зловещий берег?",a="Зловещий берег тянется вдоль северо-восточного побережья Пылевых топей, лицом к Великому морю, между окраинами Острова Терамор и границей Степей близ Крепости Северной Стражи.",al={"dreadmurk shore location","where is dreadmurk shore","где зловещий берег","расположение зловещего берега"}},{q="Почему на этом берегу бандиты Братства Справедливости?",a="Недавно судно Братства Справедливости потерпело крушение в водах у берега между Зловещим берегом и Островом Алькац. Выжившие выбрались на сушу и устроили временные лагеря на пустынном пляже и скалах, пытаясь спасти свой затонувший груз.",al={"defias in dustwallow","why are defias here","shipwrecked defias","братство справедливости в пылевых топях","почему здесь братство справедливости","потерпевшие кораблекрушение братство справедливости"}},{q="Кто такие мурлоки, живущие на берегу?",a="Побережье густо населено племенем мурлоков Болотные Плавники. Они построили грубые рыбацкие поселения на песчаных отмелях и скалистых островках, яростно охраняя свою территорию как от патрулей Терамора, так и от потерпевших кораблекрушение чужаков.",al={"mirefin murlocs","dreadmurk shore murlocs","болотные плавники","мурлоки зловещего берега"}},{q="Находится ли Зловещий берег под властью Терамора?",a="Терамор номинально заявляет права на земли вокруг острова, но Зловещий берег фактически беззаконен. Его болотистые отмели слишком дики и кишат мурлоками и разбойниками, чтобы часовые леди Джайны Праудмур могли вести регулярные патрули.",al={"who owns dreadmurk shore","is dreadmurk shore alliance","кому принадлежит зловещий берег","зловещий берег альянс"}}},fp="15,287,19.482.0,19.463.1,33.188.0,43.250.0,43.228.0,43.254.0"}
P.entries["subzone:dream-bough"] = {n="Сонные Ветви",s="Сонные Ветви — колоссальное Великое Древо на острове в центре Нефритового озера на севере Фераласа. Выращенное из побега Нордрассила, древнее дерево укрывает таинственные врата, напрямую соединяющие Азерот с Изумрудным Сном. Зеленые драконы преданно охраняют святилище, не подпуская незваных гостей к его зеленым ветвям.",h="Сонные Ветви — колоссальное Великое Древо на острове в центре Нефритового озера на севере Фераласа.",kw={"dream bough","emerald dream","fandral staghelm","feralas","great tree","green dragonflight","jademir lake","nordrassil","сонные ветви","изумрудный сон","фэндрал олений шлем","фералас","великое древо","зеленый драконий род","нефритовое озеро","нордрассил"},ang={["class:Druid"]="Сонные Ветви — священная земля, воплощающая жизненно важный мост между дикой природой Азерота и первозданным Изумрудным Сном, о котором заботится ваш орден.",["race:NightElf"]="Выращенное кенарийским кругом из благословенных ветвей Нордрассила, это великое древо воплощает древний долг вашего народа — взращивать и защищать мир природы."},sec={{t="Ветвь Нордрассила",b="Высоко над пологом леса северного Фераласа Сонные Ветви стоят как самое большое дерево в регионе. Его вырастили друиды верховного друида Фэндрала Оленьего Шлема, посадившие черенки Мирового Древа Нордрассила, чтобы закрепить силу природы на континенте. Стоя в безмятежных водах Нефритового озера, величественный страж хранит природный портал в стволе — прямой путь в дикий Изумрудный Сон."},{t="Изумрудные стражи",b="Из-за связи с Изумрудным Сном дерево находится под бдительной защитой зеленого драконьего рода. Дракониды и драконы патрулируют берега Нефритового озера и подступы к огромному стволу. Хотя это прежде всего место размышлений и сна для друидов, странствующих между мирами, путникам следует подходить осторожно: зеленые драконы терпят немногих незваных гостей возле столь важных врат."}},faq={{q="Что такое Сонные Ветви?",a="Сонные Ветви — огромное Великое Древо на острове в Нефритовом озере на севере Фераласа. Выращенное из черенка Мирового Древа Нордрассила, оно служит святилищем с действующими вратами в Изумрудный Сон.",al={"dream bough tree","what is dream bough","jademir lake tree","сонные ветви дерево","что такое сонные ветви","дерево нефритового озера"}},{q="Кто посадил Сонные Ветви?",a="Дерево посадили друиды-ночные эльфы, верные верховному друиду Фэндралу Оленьему Шлему, из ветви Нордрассила, стремясь распространить целительную силу древнего Мирового Древа по всему Калимдору.",al={"who grew dream bough","origin of dream bough","staghelm tree","кто вырастил сонные ветви","происхождение сонных ветвей","дерево оленьего шлема"}},{q="Почему здесь зеленые драконы?",a="Зеленый драконий род — вечные стражи Изумрудного Сна. Поскольку в стволе дерева находятся прямые врата в Сон, драконы и их сородичи несут постоянную стражу, защищая портал от чужаков.",al={"green dragonflight dream bough","dragons at jademir lake","зеленый драконий род сонные ветви","драконы у нефритового озера"}},{q="Могут ли игроки войти в портал в Изумрудный Сон?",a="Вихревой портал в стволе напрямую ведет в Изумрудный Сон, но остается непроходимым для смертных искателей приключений, бодрствующих в физическом мире. Свободно пересекать его границу могут лишь могущественные спящие друиды и Зеленый драконий род.",al={"can i use dream bough portal","enter emerald dream feralas","могу ли я использовать портал сонных ветвей","войти в изумрудный сон фералас"}}},fp="11,346,22.452.0,20.423.0,24.222.0,28.197.0,33.227.0,52.242.0"}
P.entries["subzone:dreamer-s-rock"] = {n="Скала Мечтателя",s="Скала Мечтателя — укромное природное убежище в глубине Пещер Стенаний, за Кричащим оврагом. Здесь спит ночной эльф-друид Наралекс, чья благородная попытка возродить Степи породила живой кошмар. Это одновременно священная склеп-пещера и средоточие порчи, изменяющей окружающую подземную экосистему.",h="Скала Мечтателя — укромное природное убежище в глубине Пещер Стенаний, за Кричащим оврагом.",kw={"barrow den","dreamer's rock","dreamers rock","druids of the fang","emerald dream","mutanus","naralex","wailing caverns","берлога-склеп","скала мечтателя","друиды клыка","изумрудный сон","мутанус","наралекс","пещеры стенаний"},ang={["class:Druid"]="Скала Мечтателя — мрачное напоминание об опасностях Изумрудного Сна: она показывает, как легко благие намерения могут быть искажены спящими ужасами.",["race:NightElf"]="Священная пещера-склеп, оскверненная под засушливыми Степями, — печальное напоминание о трагическом риске, на который пошли Наралекс и его последователи вдали от северных лесов Калимдора."},sec={{t="Сон Наралекса",b="Скала Мечтателя находится в сердце Пещер Стенаний и напоминает наспех устроенную берлогу-склеп. Здесь ночной эльф-друид Наралекс погрузился в глубокий транс, чтобы задействовать подземные источники и направить Изумрудный Сон в сухую почву Степей. Вместо жизни его связь захватили темные силы. Кошмар, искажающий его мысли, теперь изливается в эту пещеру: он уродует местных животных, превращает его последователей в ядовитых Друидов Клыка и порождает жуткие аберрации в мире яви."},{t="Ритуал пробуждения",b="Лишь покончив с порчей Повелителей Клыка, уцелевший ученик Наралекса может прийти к Скале Мечтателя и провести ритуал пробуждения. Он полон опасностей: с началом песнопения оставшийся кошмар Наралекса порождает чудовищ, защищающих его власть над спящим разумом. Вершина этой душевной муки — Мутанус Пожиратель, мерзкая аберрация, возникающая прямо из глубин подсознания мечтателя, чтобы поглотить всех, кто пытается его освободить."}},faq={{q="Кто спит на Скале Мечтателя?",a="Здесь спит Наралекс, могущественный ночной эльф-друид. Он пришел в Пещеры Стенаний, надеясь использовать подземные потоки воды, чтобы вернуть жизнь в Степи, но его единение с Изумрудным Сном захватили страшные кошмары.",al={"sleeping elf","who is asleep here","who is naralex","dreamer identity","спящий эльф","кто спит здесь","кто такой наралекс","личность мечтателя"}},{q="Почему эта пещера называется Скалой Мечтателя?",a="Пещера названа по самому Наралексу, «Мечтателю». Подобно традиционной берлоге-склепу ночных эльфов, она служит физическим пристанищем его телу, пока дух странствует по Сну.",al={"why dreamers rock","dreamers rock name meaning","name origin","почему скала мечтателя","значение названия скала мечтателя","происхождение названия"}},{q="Что происходит, если попытаться разбудить Наралекса?",a="A surviving Disciple of Naralex attempts an awakening ritual after the Fanglords have been defeated. The outcome and manifestations encountered during the ritual are revealed when it is performed.",al={"waking naralex","disciple ritual","naralex event","разбудить наралекса","ритуал ученика","событие наралекса"}},{q="Почему последователи Наралекса стали враждебными?",a="Когда единение Наралекса превратилось в кошмар, темные видения исказили разум его служителей. Отказавшись от клятв Кенарию, они приняли облик змей, стали Друидами Клыка и рьяно охраняют мучительный, нескончаемый сон своего господина.",al={"druids of the fang origin","why are the druids evil","corrupted druids","происхождение друидов клыка","почему друиды злые","оскверненные друиды"}}},fp="14,367,22.553.0,20.496.1,34.254.0,42.199.0,42.196.1,41.259.0"}
P.entries["subzone:drowned-reef"] = {n="Подводный риф",s="Подводный риф — опасный участок прибрежных вод у южных утесов Нагорья Арати. Под волнами лежат древние затонувшие руины, захваченные враждебными нагами Пронзающего Гребня, которые, судя по всему, способны управлять приливами бухты и угрожают проходящим судам.",h="Подводный риф — опасный участок прибрежных вод у южных утесов Нагорья Арати.",kw={"arathi highlands","daggerspine","drowned reef","faldir's cove","maiden's folly","naga","prince nazjak","spirit of silverpine","sunken ruins","нагорье арати","пронзающий гребень","подводный риф","бухта фальдира","причуда девы","наги","принц назжак","дух серебряного бора","затонувшие руины"},ang={["race:NightElf"]="Затопленные залы под рифом и окаменевшие самоцветы на морском дне — печальные напоминания об империи кальдораев, рухнувшей в море десять тысяч лет назад во время Великого Раскола."},sec={{t="Кладбище кораблей",b="Just outside the hidden entrance to Faldir's Cove, the Drowned Reef forms a watery graveyard for navigators. Shattered ships, including the Maiden's Folly and the Spirit of Silverpine, lie submerged beneath the waves. Daggerspine naga led by Prince Nazjak inhabit the reef and appear able to control the bay's tides, dooming crews seeking refuge in the cove."},{t="Затонувший город",b="Те, кто достаточно храбр или безрассуден, чтобы нырнуть в глубокую воду, обнаружат затопленную архитектуру древнего эльфийского города. Среди его утонувших руин остались окаменевшие эльфийские самоцветы."}},faq={{q="Что такое Подводный риф?",a="Подводный риф — опасная морская зона у южного побережья Нагорья Арати, недалеко от Бухты Фальдира. Он известен мелкими мелями, разбивающими корабли, и древними руинами на морском дне.",al={"drowned reef","where is drowned reef","arathi reef","подводный риф","где подводный риф","риф арати"}},{q="Почему здесь так много затонувших кораблей?",a="Риф опасен для кораблей у южного побережья Арати. Его наги Пронзающего Гребня, судя по всему, способны управлять приливами бухты и угрожают командам, пытающимся укрыться в Бухте Фальдира.",al={"why are ships sinking","sunken ships arathi","maidens folly","почему тонут корабли","затонувшие корабли арати","причуда девы"}},{q="Кто управляет Подводным рифом?",a="Риф населяет племя наг Пронзающего Гребня, живущее в затопленных руинах. Местными силами руководит принц Назжак: он приказывает им охотиться на потерпевших крушение моряков и защищать свои подводные владения.",al={"who leads the naga here","prince nazjak","daggerspine naga arathi","кто ведет наг","принц назжак","наги пронзающего гребня арати"}},{q="Что за руины скрыты под рифом?",a="В рифе лежат руины древнего эльфийского города; среди его затонувших остатков есть окаменевшие эльфийские самоцветы.",al={"underwater ruins arathi","elven ruins drowned reef","подводные руины арати","эльфийские руины подводного рифа"}}},fp="12,261,20.358.0,15.177.0,25.229.0,40.187.0,30.228.0,46.108.0"}
P.entries["subzone:drowned-sacellum"] = {n="Затонувшее святилище",s="Затонувшее святилище — погруженный в воду эльфийский храм сразу за входом в Непроглядную Пучину. Его разрушенная кладка, залитая солоноватой морской водой и увитая корнями, теперь наводнена мурлоками и макрурами.",h="Затонувшее святилище — погруженный в воду эльфийский храм сразу за входом в Непроглядную Пучину.",kw={"bfd","blackfathom deeps","drowned sacellum","makrura","murloc","shrine","zoram strand","непроглядная пучина","затонувшее святилище","макруры","мурлок","святилище","зорамское взморье"},ang={["class:Druid"]="Огромные корни по-прежнему пробивают каменный свод с поверхности — доказательство того, что природа выстоит даже в оскверненных подземных водах.",["race:NightElf"]="Древнее священное святилище, затопленное соленой водой и оскверненное мурлоками, — горькое напоминание о священном наследии кальдораев, утраченном под Зорамским взморьем."},sec={{t="Затопленное святилище",b="Шагнув за порог Непроглядной Пучины, исследователи сразу попадают в Затонувшее святилище. Когда-то это была тихая подземная часовня, посвященная Элуне, но она давно обрушилась в омываемую морем бездну под побережьем Ясеневого леса. Соленые лужи поглощают древние мраморные плиты, поросшие морскими звездами, а с потолка пещеры свисают огромные корни. Темные мерцающие огоньки дают единственный тусклый свет во мраке и освещают разрушенную тропу из камней, по которой искателям приключений нужно осторожно пройти к Пруду Аск'ара в глубине храмового комплекса."},{t="Логово падальщиков",b="Давно брошенное ночными эльфами, Затонувшее святилище попало в руки прибрежных падальщиков. Стаи агрессивных мурлоков и крепкобронных макрур живут бок о бок в мутной воде и нападают на всякого, кто тревожит их гнездовья. Более темные, культистские угрозы таятся глубже в храме, но эти хищники образуют первую опасную линию обороны подземных руин."}},faq={{q="Для чего изначально использовалось Затонувшее святилище?",a="Сацеллум — это небольшое святилище или часовня без крыши. В древности, до Раскола, оно служило эльфийским местом поклонения в составе большого подземного храмового комплекса, посвященного богине луны Элуне.",al={"drowned sacellum purpose","what is the drowned sacellum","sacellum history","назначение затонувшего святилища","что такое затонувшее святилище","история святилища"}},{q="Какие существа обитают в этой части пещер?",a="Затопленные руины заняты в основном дикими мурлоками и макрурами. Они процветают в солоноватых соленых прудах и гнездовых расщелинах пещеры.",al={"drowned sacellum mobs","what lives in drowned sacellum","monsters in drowned sacellum","монстры затонувшего святилища","кто живет в затонувшем святилище","враги в затонувшем святилище"}},{q="Как пройти мимо Затонувшего святилища?",a="Путникам нужно осторожно перепрыгивать по рушащимся, наполовину затопленным площадкам и колоннам, поднимающимся из воды, чтобы добраться до туннеля, ведущего к Пруду Аск'ара.",al={"how to get through drowned sacellum","drowned sacellum jump","path to pool of askar","как пройти затонувшее святилище","прыжки в затонувшем святилище","путь к пруду аск'ара"}},{q="Откуда в пещере берется свет?",a="Слабое, жутковатое свечение исходит от темных огоньков, парящих среди толстых искривленных корней, пронзающих потолок из Ясеневого леса наверху.",al={"why is it glowing","wisps in drowned sacellum","drowned sacellum lighting","почему светится","огоньки в затонувшем святилище","освещение затонувшего святилища"}}},fp="16,230,21.592.0,17.434.0,50.210.0,48.149.0,46.172.0,45.165.0"}
P.entries["subzone:drygulch-ravine"] = {n="Сухая лощина",s="Сухая лощина — суровое скрытое ущелье среди скалистых обрывов восточного Дуротара. Попасть в эту изрезанную расселину можно только через неприметный пещерный проход из Каньона Колючего Ветра или спрыгнув сверху. Ее заполонили гнездящиеся гарпии Пыльного Ветра, которые угрожают проезжающим неподалеку торговым караванам.",h="Сухая лощина — суровое скрытое ущелье среди скалистых обрывов восточного Дуротара.",kw={"drygulch ravine","durotar","dustwind harpies","harpy nests","orgrimmar","razorwind canyon","stolen supplies","thunder ridge","сухая лощина","дуротар","гарпии пыльного ветра","гнезда гарпий","оргриммар","каньон колючего ветра","украденные припасы","громовой хребет"},ang={["faction:Horde"]="Зачистка гнездовий лощины и возвращение украденных припасов помогает защитить внутренние торговые пути Дуротара от постоянных разбоев.",["race:Orc"]="Сухая лощина — испытание на выносливость в глуши, где молодые орки доказывают доблесть в схватках со свирепыми гарпиями на скалистых обрывах родной земли."},sec={{t="Разбойничье логово в Красных скалах",b="Сухая лощина, глубоко врезанная в скалы к востоку от Оргриммара, почти полностью отрезана от случайных путников. Единственный наземный вход — тесный естественный туннель, соединенный с Каньоном Колючего Ветра. Эта защищенная низина с небольшой рекой когда-то мирно населялась орками, но дикие звери и гнездящиеся гарпии Пыльного Ветра превратили ее в беззаконный уголок Дуротара. Крылатые падальщицы устраивают гнезда на крутых утесах и копят там добро, украденное из обозов Орды на местных дорогах."},{t="Заноза в боку Дуротара",b="Жизнь в Сухой лощине всегда была ненадежной. Вскоре после Третьей войны сбежавшие громовые ящеры с Громового хребта стали угрожать этим местам, и об этом сообщили вождю Траллу в Оргриммаре. Сегодня главная опасность — гарпии. Их матери яростно защищают кладки яиц на высоких уступах, а разведчики Орды часто посылают туда молодых воинов, чтобы проредить стаю, вернуть похищенные грузы и разрушить власть гарпий над лощиной."}},faq={{q="Как попасть в Сухую лощину?",a="Если не спрыгнуть с высоких утесов и выжить, единственный наземный путь — небольшой вход в пещеру в соседнем Каньоне Колючего Ветра.",al={"drygulch entrance","how to enter drygulch","where is the cave to drygulch","вход в сухую лощину","как попасть в сухую лощину","где пещера в сухую лощину"}},{q="Какие существа живут в Сухой лощине?",a="В лощине господствуют гарпии Пыльного Ветра: они вьют гнезда, откладывают яйца и прячут награбленные припасы караванов на скалистых уступах.",al={"drygulch mobs","what is in drygulch ravine","who lives in drygulch","существа сухой лощины","что в сухой лощине","кто живет в сухой лощине"}},{q="Почему Орду интересует эта лощина?",a="Гарпии Пыльного Ветра нападают на важные торговые тропы Дуротара и копят украденные грузы в ущелье. Власти Орды в Колючем Холме регулярно посылают новобранцев вернуть припасы и проредить стаю.",al={"why kill harpies drygulch","drygulch ravine quests","horde interest in drygulch","зачем убивать гарпий","задания сухой лощины","интерес орды к сухой лощине"}},{q="Нападали ли громовые ящеры на лощину?",a="Да. Через несколько лет после Третьей войны встревоженные громовые ящеры вырвались с соседнего Громового хребта и стали угрожать Сухой лощине, из-за чего местные орки обратились за военной помощью к вождю Траллу в Оргриммаре.",al={"thunder lizards drygulch","drygulch history lizards","громовые ящеры сухая лощина","история сухой лощины ящеры"}}},fp="15,284,31.536.0,25.467.0,36.152.0,39.141.0,42.189.0,43.203.0"}
P.entries["subzone:drywhisker-gorge"] = {n="Теснина Сухоусов",s="Теснина Сухоусов — суровое ущелье в восточных горах Нагорья Арати, к северо-востоку от форпоста Орды Павший Молот. Ущелье и его пещеру удерживает враждебный клан кобольдов, яростно охраняющий богатые залежи руды и древние стихийные реликвии, погребенные глубоко под землей.",h="Теснина Сухоусов — суровое ущелье в восточных горах Нагорья Арати, к северо-востоку от форпоста Орды Павший...",kw={"arathi highlands","drywhisker","drywhisker gorge","hammerfall","kobold","lesser bloodstone ore","princess myzrael","stone shard","нагорье арати","сухоусы","теснина сухоусов","павший молот","кобольд","бедная кровавая руда","принцесса мизраэль","каменный осколок"},ang={["faction:Horde"]="Враждебные кобольды Сухоусы, обитающие сразу за горным хребтом от Павшего Молота, — непредсказуемая угроза на восточном фланге форпоста.",["profession:Mining"]="Шахтеры ценят пещеру Сухоусов как единственный известный источник Бедной кровавой руды — плотного минерала с багровыми прожилками, залегающего глубоко в породе, кишащей кобольдами."},sec={{t="Лабиринт в восточных скалах",b="Теснина Сухоусов, укрытая в горных складках к востоку от Павшего Молота, — главное убежище клана кобольдов Сухоусов. Кобольдов часто считают простыми шахтными вредителями, но Сухоусы в Арати прочно окопались. Они с яростным упорством охраняют свои подземные ходы, добывают редкую Бедную кровавую руду и защищают глубины земли. Их соседство постоянно досаждает оркам Павшего Молота."},{t="Тайны глубокой пещеры",b="Если зайти достаточно далеко за освещенные факелами баррикады и извилистые туннели, пещера откроет тайну мрачнее обычных кирок и свечей. Кобольды Сухоусы, союзные огромным каменным великанам нагорья, ухаживают за частицами древней магии земли. В сердце пещеры лежит загадочный каменный осколок, в котором заключена частица сущности принцессы Мизраэль, древнего земного существа, скованного под землей."}},faq={{q="Кто живет в Теснине Сухоусов?",a="Ущелье и сеть пещер населяет клан кобольдов Сухоусов. Они агрессивно защищают свои земли от чужаков, охраняя и свои шахты, и спрятанные внутри древние реликвии.",al={"drywhisker gorge inhabitants","what is in drywhisker gorge","who controls drywhisker gorge","обитатели теснины сухоусов","что в теснине сухоусов","кто владеет теснина сухоусов"}},{q="Где находится Теснина Сухоусов?",a="Ущелье прорезает скалистые восточные горы Нагорья Арати, прямо к северо-востоку от поселения Орды Павший Молот. Трудная тропа ведет через холмы к востоку от форпоста ко входу в пещеру.",al={"how to get to drywhisker gorge","drywhisker gorge location","where is the cave in arathi","как добраться до теснины сухоусов","расположение теснины сухоусов","где пещера в арати"}},{q="Чем важна пещера внутри?",a="Помимо редких залежей Бедной кровавой руды, в пещере хранится древний каменный осколок. В этой реликвии заключена частица плененной сущности принцессы Мизраэль, могущественного подземного существа.",al={"what is in the cave","drywhisker cave secrets","myzrael shard","что в пещере","тайны пещеры сухоусов","осколок мизраэль"}},{q="Почему кобольды в союзе с горными великанами?",a="Клан Сухоусов связан с местными каменными великанами: они служат и охраняют земные реликвии и стихийные частицы, связанные с оковами принцессы Мизраэль глубоко под Арати.",al={"kobolds and giants","why are drywhiskers with giants","кобольды и великаны","почему сухоусы с великанами"}}},fp="16,304,29.490.0,26.438.1,30.210.0,34.225.0,39.209.0,48.188.0"}
P.entries["subzone:dun-algaz"] = {n="Дун Альгаз",s="Дун Альгаз — укрепленный горный перевал и сеть туннелей, соединяющие Лок Модан с Болотиной. Этот важный торговый путь, за который шли бои во время Второй войны, недавно оказался в осаде орков клана Драконьей Пасти, что прервало сообщение между землями Стальгорна и Гаванью Менетилов.",h="Дун Альгаз — укрепленный горный перевал и сеть туннелей, соединяющие Лок Модан с Болотиной.",kw={"algaz gate","algaz station","dragonmaw","dun algaz","loch modan","menethil harbor","mountain pass","wetlands","врата альгаза","станция альгаз","драконья пасть","дун альгаз","лок модан","гавань менетилов","горный перевал","болотина"},ang={["faction:Alliance"]="Путь через Дун Альгаз критически важен для снабжения Альянса: он обеспечивает сухопутную дорогу, связывающую порт Гавань Менетилов с Лок Моданом и Стальгорном.",["race:Dwarf"]="Для дворфов Дун Альгаз — древняя дорога, прорубленная в хребте Каз Модана. Видеть, как орки Драконьей Пасти занимают дворфийские бастионы и угрожают путям снабжения Гавани Менетилов, — постоянное оскорбление и угроза безопасности."},sec={{t="Узкий проход между королевствами",b="Дун Альгаз существовал еще до Войны трех молотов: через него клан Громового Молота уходил на север после изгнания из Стальгорна. Перевал, глубоко врезанный в зубчатые пики между Лок Моданом и Болотиной, состоит из просторных каменных туннелей, бастионов и сторожевых постов. Его стратегическое значение трудно переоценить: кто владеет Дун Альгазом, тот управляет единственной сухопутной дорогой от сердца земель дворфов к западному морю у Гавани Менетилов."},{t="Возрождение Драконьей Пасти",b="Во время Второй войны Старая Орда отступила в Дун Альгаз после поражения у Дун Модра и превратила его в последний южный оплот против войск сэра Андуина Лотара. Годы спустя Некрос Крушитель Черепов укрыл клан Драконьей Пасти в окрестных пещерах. Хотя Альянс на время вернул перевал, орки Драконьей Пасти вновь захватили крепость, вынудив дворфов-горцев отступить в верхние туннели и превратив горный коридор в смертельную ловушку для путников."}},faq={{q="Почему Дун Альгаз сейчас так опасен?",a="Орки Драконьей Пасти спустились с окрестных гор и захватили нижний перевал и крепость. Дворфов-горцев оттеснили к верхнему перевалу у Станции Альгаз, и главная дорога кишит враждебными орками, устраивающими засады на путников между Лок Моданом и Болотиной.",al={"why are there orcs in dun algaz","dun algaz orcs","who controls dun algaz","почему орки в дун альгаз","орки дун альгаза","кто владеет дун альгазом"}},{q="Почему этот перевал так важен для дворфов?",a="Дун Альгаз — главный сухопутный путь, соединяющий Стальгорн и Лок Модан с Гаванью Менетилов в Болотине. Гавань Менетилов — главные морские врата между Каз Моданом и остальными землями Альянса, поэтому Дун Альгаз — ключевой коридор для припасов, войск и торговли.",al={"dun algaz importance","why does ironforge need dun algaz","значение дун альгаза","зачем стальгорну дун альгаз"}},{q="Играл ли Дун Альгаз роль во Второй войне?",a="Да. После поражения у Дун Модра Орочья Орда отступила через Долину Тандол и сделала Дун Альгаз оборонительным оплотом. Сэр Андуин Лотар приказал штурмовать его, чтобы выбить орков из Каз Модана, но Альянс не смог полностью уничтожить Орду, и крепость осталась одним из ее последних оплотов в регионе.",al={"dun algaz second war","anduin lothar dun algaz","дун альгаз вторая война","андуин лотар дун альгаз"}},{q="Какая связь у Дун Альгаза с дворфами клана Громового Молота?",a="Задолго до Второй войны, во время древней Войны трех молотов, дворфов Громового Молота изгнали из Стальгорна. Они прошли через Дун Альгаз на север, в Болотину, и в конце концов поселились в Грим Батоле.",al={"wildhammer dun algaz","war of the three hammers pass","громовой молот дун альгаз","война трех молотов перевал"}}},fp="9,301,27.477.0,24.503.0,40.320.0,45.296.0,44.336.0,65.229.0"}
P.entries["subzone:dun-garok"] = {n="Дун Гарок",s="Дун Гарок — укрепленный дворфийский горный бастион на юго-востоке Предгорий Хилсбрада. Стойкий гарнизон форпоста под командованием капитана Железная Гора защищает интересы Альянса в регионе и соседние объекты, такие как Лазуритовый рудник, от враждебных вторжений. Для Отрекшихся Мельницы Таррен этот укрепленный оплот дворфов — постоянная военная угроза на границе их владений.",h="Дун Гарок — укрепленный дворфийский горный бастион на юго-востоке Предгорий Хилсбрада.",kw={"azurelode mine","dun garok","dwarf","hillsbrad","ironforge","ironhill","keep","mountaineer","лазуритовый рудник","дун гарок","дворф","хилсбрад","стальгорн","железная гора","крепость","горец"},ang={["faction:Horde"]="Этот хорошо защищенный дворфийский анклав постоянно угрожает расширению Отрекшихся и безопасности границ вокруг Мельницы Таррен, поэтому его гарнизон — приоритетная цель.",["race:Dwarf"]="Дун Гарок — гордый символ влияния Стальгорна в Лордероне, где капитан Железная Гора и его горцы стойко защищают своих союзников-людей."},sec={{t="Бастион в предгорьях",b="Дун Гарок, высеченный в скалистых юго-восточных холмах Предгорий Хилсбрада, — сильно укрепленный оплот горцев и стрелков Стальгорна. Под командованием капитана Железная Гора дворфы держат важный оборонительный рубеж, прикрывая людские поселения Хилсбрада и обеспечивая работу Лазуритового рудника. Прочная каменная архитектура и глубокие укрепления делают его опорой Альянса против ближайших угроз."},{t="Цель Мельницы Таррен",b="Из-за близости к Мельнице Таррен Дун Гарок считается Отрекшимися невыносимым вторжением на их южную границу. Войска Сильваны Ветрокрылой ненавидят присутствие хорошо вооруженных дворфов рядом со своим оплотом и регулярно замышляют проникнуть в крепость, прорвать оборону и уничтожить гарнизон капитана Железная Гора, чтобы закрепить господство Отрекшихся над Хилсбрадом."}},faq={{q="Что такое Дун Гарок?",a="Дун Гарок — укрепленный дворфийский форпост в юго-восточных горах Предгорий Хилсбрада. Его занимают войска Стальгорна, защищающие владения Альянса в регионе.",al={"dun garok location","what is this dwarven keep","hillsbrad dwarf fort","где дун гарок","что за дворфийская крепость","форт дворфов хилсбрада"}},{q="Кто командует Дун Гароком?",a="Оплотом командует капитан Железная Гора: он ведет местных горцев и стрелков, защищающих Хилсбрад и соседний Лазуритовый рудник.",al={"dun garok leader","who leads dun garok","captain ironhill","командир дун гарока","кто руководит дун гароком","капитан железная гора"}},{q="Почему Отрекшиеся хотят уничтожить Дун Гарок?",a="Отрекшиеся считают действующий укрепленный оплот дворфов прямо на их южной границе серьезной угрозой для Мельницы Таррен и активно посылают агентов, чтобы истребить гарнизон.",al={"why horde attack dun garok","forsaken dun garok","tarren mill dun garok conflict","почему орда атакует дун гарок","отрекшиеся дун гарок","конфликт мельницы таррен и дун гарока"}},{q="Какое стратегическое значение Дун Гарок имеет для Альянса?",a="Дун Гарок — ключевой военный оплот в Хилсбраде: он помогает поддерживать безопасность Альянса в регионе и защищает соседний Лазуритовый рудник от вражеского захвата.",al={"why is dun garok important","alliance purpose dun garok","почему важен дун гарок","назначение дун гарока для альянса"}}},fp="9,417,26.450.0,21.400.0,18.195.0,23.151.0,46.186.0,52.169.0"}
P.entries["subzone:dun-mandarr"] = {n="Дун Мандарр",s="Дун Мандарр — заброшенный лагерь дворфов у ледяной пещеры на юго-востоке Зимних Ключей. Основанный дворфом Джероном Гранильщиком, он лежит в руинах: его обитатели бежали от нападения разъяренных местных лунных сов.",h="Дун Мандарр — заброшенный лагерь дворфов у ледяной пещеры на юго-востоке Зимних Ключей.",kw={"blue-feathered amulet","dun mandarr","dwarf camp","jaron stoneshaper","moonkin","wildkin","winterspring","амулет синего пера","дун мандарр","лагерь дворфов","джерон гранильщик","лунная сова","исчадия лунного света","зимние ключи"},ang={["class:Druid"]="Лунные совы, охраняющие Дун Мандарр, яростно оберегают природные и небесные артефакты и жестоко реагируют, когда чужаки тревожат священные реликвии вроде Амулета синего пера.",["race:Dwarf"]="Разрушенный лагерь носит традиционное дворфийское название — суровое напоминание о том, как легко археологические амбиции в древнем Калимдоре оборачиваются бедой."},sec={{t="A Forsaken Camp",b="Дун Мандарр, носящий традиционную дворфийскую приставку «Дун», основал исследователь Джерон Гранильщик как базу в замерзших землях юго-востока Зимних Ключей. Любопытство погубило Гранильщика: он обнаружил реликвию, известную как Амулет синего пера. Потревоженный артефакт вызвал гнев местных исчадий лунного света, и те в неукротимой ярости обрушились на лагерь. Дворфы, разгромленные и изгнанные, оставили лагерь целиком. Ныне среди сугробов не осталось дружелюбных душ: свирепые, ревнивые к своим владениям лунные совы охраняют пещеру и бродят среди разрушенных укрытий."}},faq={{q="Что случилось с лагерем в Дун Мандарре?",a="Дун Мандарр построил дворф-исследователь Джерон Гранильщик. Во время раскопок он нашел загадочный Амулет синего пера. Реликвия сильно разгневала окрестных исчадий лунного света, и те яростно напали на поселение. Джерона и его спутников прогнали, а застава осталась заброшенной и захваченной.",al={"why is dun mandarr abandoned","who built dun mandarr","what is dun mandarr","почему дун мандарр заброшен","кто построил дун мандарр","что такое дун мандарр"}},{q="Почему здесь так много лунных сов?",a="Местные исчадия лунного света считают пещеру и окрестные реликвии священными. Когда Джерон Гранильщик раскопал Амулет синего пера, существа в неистовстве бросились вернуть артефакт и защитить свою территорию: они прогнали чужаков и завладели лагерем.",al={"why are there wildkin here","dun mandarr owlbeasts","why are owlbeasts attacking","почему здесь исчадия лунного света","дун мандарр совы","почему нападают совы"}},{q="Куда ушел Джерон Гранильщик?",a="Изгнанный из лагеря разъяренными лунными совами, Джерон Гранильщик удалился в другую часть Зимних Ключей, чтобы собраться с силами и найти помощь в возвращении похищенных исследований и снаряжения.",al={"where is jaron stoneshaper","jaron stoneshaper location","где джерон гранильщик","местонахождение джерона гранильщика"}}},fp="11,236,15.618.0,41.324.0,35.280.0,31.182.0"}
P.entries["subzone:dun-modr"] = {n="Дун Модр",s="Дун Модр — древний укрепленный дворфийский город на севере Болотины, охраняющий южный подход к Мосту Тандола. Некогда важнейшая крепость, за которую шли споры во многих войнах, он недавно пал под натиском враждебных дворфов Черного Железа.",h="Дун Модр — древний укрепленный дворфийский город на севере Болотины, охраняющий южный подход к Мосту Тандола.",kw={"balgaras the foul","dark iron","dun modr","ironforge","mountaineers","thandol span","wetlands","балгорас нечистый","черное железо","дун модр","стальгорн","горцы","мост тандола","болотина"},ang={["faction:Alliance"]="Падение Дун Модра угрожает важнейшему пути через Мост Тандола и затрудняет сообщение между Стальгорном и северными остатками Альянса.",["race:Dwarf"]="Видеть, как славное горное поселение Бронзобородов попадает в руки вероломного клана Черного Железа, — горькое оскорбление, требующее мести."},sec={{t="Спорный оплот",b="Дун Модр, расположенный на северной окраине Болотины, контролирует главную сухопутную дорогу, соединяющую Каз Модан с северными человеческими королевствами. Из-за этого положения за крепость десятилетиями лилась кровь. Во время Второй войны Орочья Орда захватила дворфийскую крепость и закрепилась в ней, используя ее как передовую базу для набегов и отражения армий Альянса. Воины Стромгарда начали жестокую высадку с Тол Барада, чтобы вернуть ее, но орки нанесли ответный удар, и борьба шла с переменным успехом. Силы Альянса под командованием лорда Андуина Лотара в конце концов отбросили захватчиков на юг через Мост Тандола, вернув оплот дворфам."},{t="Вторжение Черного Железа",b="Внимание Стальгорна было разделено, а многие лучшие горцы служили Альянсу за границей, и Дун Модр остался уязвим. Воспользовавшись этим, захватчики из Черного Железа двинулись на север, взрывчаткой повредили Мост Тандола и затем хлынули в крепость. Под началом чернокнижника Черного Железа Балгораса Нечистого эти лазутчики разгромили защитников города, выгнали гарнизон Бронзобородов и превратили стратегическую заставу во вражеское логово. Окрестные горцы держат мрачный рубеж неподалеку на дороге и отчаянно ищут помощи, чтобы выбить захватчиков."}},faq={{q="Почему Дун Модр так важен?",a="Дун Модр стоит прямо на главной северной дороге Болотины, ведущей к Мосту Тандола. Кто владеет крепостью, тот контролирует все сухопутное движение, линии снабжения и передвижение войск между Каз Моданом и северным континентом Лордерона.",al={"why does dun modr matter","importance of dun modr","dun modr strategic value","почему важен дун модр","значение дун модра","стратегическая ценность дун модра"}},{q="Кто сейчас контролирует Дун Модр?",a="Оплот пал перед кланом Черного Железа, которым на месте руководит чернокнижник Балгорас Нечистый. Горцы Бронзобородов, верные Стальгорну, держат неподалеку лагерь и надеются отбить крепость.",al={"who is in dun modr","who runs dun modr","who lives in dun modr","кто в дун модре","кто правит дун модром","кто живет в дун модре"}},{q="Что произошло с Дун Модром во время Второй войны?",a="Орочья Орда захватила город и превратила его в передовую военную базу. Силы Стромгарда нанесли удар с острова Тол Барад, чтобы отбить руины, и начались ожесточенные схватки, пока войска Альянса Андуина Лотара наконец не вымели Орду из региона.",al={"second war dun modr","orcs in dun modr","did horde take dun modr","вторая война дун модр","орки в дун модре","захватила ли орда дун модр"}},{q="Кто такой Балгорас Нечистый?",a="Балгорас Нечистый — чернокнижник Черного Железа, возглавляющий оккупацию Дун Модра. Под его началом дворфы Черного Железа смогли повредить Мост Тандола и выгнать из крепости местных защитников Стальгорна.",al={"balgaras the foul lore","balgaras who","dark iron leader dun modr","балгорас нечистый","кто такой балгорас","предводитель черного железа дун модр"}}},fp="8,249,19.711.0,23.604.0,29.258.0,32.197.0,48.257.0,25.208.0"}
P.entries["subzone:durnholde-keep"] = {n="Крепость Дарнхольд",s="Крепость Дарнхольд — разрушенная цитадель к востоку от Мельницы Таррен в Предгорьях Хилсбрада. Некогда центр орочьих лагерей для интернированных Альянса и место, где вождь Тралл рос пленным гладиатором, она лежит в руинах и занята преступниками Синдиката.",h="Крепость Дарнхольд — разрушенная цитадель к востоку от Мельницы Таррен в Предгорьях Хилсбрада.",kw={"blackmoore","durnholde keep","hillsbrad","internment","syndicate","taretha foxton","tarren mill","thrall","чернотопь","крепость дарнхольд","хилсбрад","лагеря для интернированных","синдикат","таретта фокстон","мельница таррен","тралл"},ang={["faction:Alliance"]="Некогда опора обороны и правосудия Лордерона, разрушенные стены Дарнхольда ныне служат лишь жалким логовом для преступников и головорезов Синдиката.",["race:Orc"]="Руины Дарнхольда — горнило, где вождь Тралл сбросил оковы, положив конец десятилетиям орочьего плена и положив начало возрождению Орды."},sec={{t="Горнило неволи",b="Дарнхольд, построенный Альянсом, после Второй войны служил штабом, надзиравшим за южными лагерями для интернированных. Им командовал честолюбивый и продажный генерал-лейтенант Аэделас Блэкмур; крепость была и административным центром, и гладиаторской ареной. Именно здесь Блэкмур воспитал осиротевшего младенца Гоэля, назвав его Траллом и обучая сражаться ради забавы и выгоды. С помощью Тареты Фокстон Тралл бежал из плена и позднее объединил разрозненные орочьи кланы под знаменем новой Орды. Вернувшись к Дарнхольду, Тралл осадил крепость, убил Блэкмура и призвал духов земли разрушить ее стены."},{t="В лапах Синдиката",b="С тех пор как крепость Дарнхольд пала еще до Третьей войны, она остается израненной грудой камня. В пустоте, оставленной падением Лордерона, аристократы-разбойники Синдиката нашли приют за ее стенами. Действуя из разрушенного двора и башен, эти лишенные владений дворяне Альтерака и головорезы грабят путников в Предгорьях Хилсбрада, превратив бывшее орудие военного положения в хорошо укрепленную разбойничью заставу."}},faq={{q="Почему Крепость Дарнхольд лежит в руинах?",a="Тралл вернулся в Дарнхольд во главе освобожденной Орды, чтобы победить своего бывшего хозяина, генерал-лейтенанта Аэделаса Блэкмура. Убив Блэкмура, Тралл воззвал к духам земли и разрушил крепость, чтобы она больше никогда не стала клеткой для его народа.",al={"who destroyed durnholde","what happened to durnholde keep","why is durnholde destroyed","кто разрушил дарнхольд","что случилось с крепостью дарнхольд","почему разрушен дарнхольд"}},{q="Кто сейчас занимает Крепость Дарнхольд?",a="Твердыней владеет Синдикат — фракция изгнанных дворян Альтерака, ставших преступниками. Они используют рушащиеся стены как укрепленный оплот для разбоя и нападений по всему Хилсбраду.",al={"who lives in durnholde","durnholde mobs","syndicate at durnholde","кто живет в дарнхольде","мобы дарнхольда","синдикат в дарнхольде"}},{q="Как Тралл был связан с этим местом?",a="Аэделас Блэкмур нашел осиротевшего орка ребенком и вырастил его в Дарнхольде рабом. Тралла обучили тактике и заставляли сражаться гладиатором на арене, пока он не вырвался на свободу с помощью человеческой женщины по имени Тарета Фокстон.",al={"did thrall live here","thrall durnholde history","was thrall a prisoner here","жил ли тралл здесь","история тралла в дарнхольде","был ли тралл здесь пленником"}},{q="Какую роль играла крепость во время Второй войны?",a="Помимо роли оплота Альянса, она служила тюрьмой. Во время конфликта здесь держали в плену военачальника лесных троллей Зул'джина, пока Оргрим Молот Рока не прорвался в крепость, чтобы освободить его.",al={"durnholde second war","what was durnholde used for","дарнхольд вторая война","для чего использовался дарнхольд"}}},fp="14,286,23.665.0,32.442.0,31.269.0,38.203.0,43.258.0,54.214.0"}
P.entries["subzone:dustbowl"] = {n="Знойные Пески",s="Знойные Пески — обширная засушливая равнина на северо-западе Бесплодных земель между аванпостом Орды Каргат и центральной Долиной Клыков. Это суровая пустошь, где гуляют иссушающие пустынные ветра и обитают падальщики, хищные звери и бродячие элементали. Здесь же находится Лагерь Вург, поэтому путники, пересекающие эти земли, часто проходят через него.",h="Знойные Пески — обширная засушливая равнина на северо-западе Бесплодных земель между аванпостом Орды Каргат и...",kw={"badlands","buzzards","camp wurg","coyotes","dustbowl","kargath","rock elementals","valley of fangs","бесплодные земли","канюки","лагерь вург","койоты","знойные пески","каргат","каменные элементали","долина клыков"},ang={["faction:Horde"]="Расположенные сразу за Каргатом Знойные Пески — первая открытая пустошь, которую должны пересечь разведчики Орды, продвигаясь на восток в Бесплодные земли."},sec={{t="Выжженный переход",b="Знойные Пески тянутся по северо-западу Бесплодных земель. Для них характерны сухие овраги, растрескавшаяся глина и неутихающие ветра, поднимающие удушливые облака пыли. Несмотря на бесплодный пейзаж, здесь растут выносливые кактусы и редкие корявые деревья. Открытая равнина постоянно грозит опасностью путникам без проводника: им приходится иметь дело с хищными койотами, кружащими канюками и живыми каменными элементалями, рожденными суровой землей. Среди этих зарослей расположен Лагерь Вург — заметный ориентир посреди безжизненной пустоши."}},faq={{q="Где находятся Знойные Пески?",a="Знойные Пески занимают северо-западную часть Бесплодных земель и лежат между укрепленным лагерем Орды Каргат на западе и Долиной Клыков в центре зоны.",al={"dustbowl location","where is dustbowl","dustbowl badlands map","знойные пески расположение","где знойные пески","знойные пески карта бесплодные земли"}},{q="Какие существа бродят по Знойным Пескам?",a="Здесь рыщут свирепые койоты, а в небе кружат канюки в поисках падали. Путники также встретят опасных каменных элементалей, бродящих по скалистым местам.",al={"dustbowl mobs","what lives in dustbowl","dustbowl beasts","знойные пески монстры","кто живет в знойных песках","знойные пески звери"}},{q="Какие ориентиры есть в Знойных Песках?",a="Самое заметное поселение в Знойных Песках — Лагерь Вург, хорошо видимый ориентир среди засушливой пустыни между Каргатом и центральными равнинами.",al={"camps in dustbowl","camp wurg dustbowl","лагеря в знойных песках","лагерь вург знойные пески"}},{q="Может ли здесь выжить какая-нибудь растительность?",a="Несмотря на сухой и суровый климат, в Знойных Песках есть скудная растительность: в основном выносливые кактусы и редкие засохшие пустынные деревья, приспособленные к бесплодной почве.",al={"dustbowl flora","plants in dustbowl","знойные пески флора","растения в знойных песках"}}},fp="8,379,19.578.0,30.195.0,35.165.0,41.143.0,36.165.0"}
P.entries["subzone:dustfire-valley"] = {n="Выжженная долина",s="Выжженная долина — сухое, продуваемое ветрами ущелье на северной окраине Тлеющего ущелья. Это опаленный подступ к укрепленным воротам Подгорной тропы, которые преграждают горный путь в Лок Модан.",h="Выжженная долина — сухое, продуваемое ветрами ущелье на северной окраине Тлеющего ущелья.",kw={"dustfire valley","loch modan","locked gate","searing gorge","stonewrought pass","valley of kings","выжженная долина","лок модан","запертые ворота","тлеющее ущелье","подгорная тропа","долина королей"},ang={["race:Dwarf"]="Для дворфов эти ворота — сильно укрепленная задняя дверь между безопасным Каз Моданом и опасными землями, которыми правит клан Черного Железа."},sec={{t="Северная граница",b="Выжженная долина лежит на севере Тлеющего ущелья и отличается удушливым пеплом, хрупкой породой и голыми стенами каньона. Главная ее достопримечательность — внушительные запертые дворфийские врата, закрывающие Подгорную тропу. Из-за этих запертых железных дверей путь на север, в Долину Королей и Лок Модан, остается закрыт для обычных путников, и долина превращается в тупик среди сернистых пустошей."}},faq={{q="Куда ведут ворота в Выжженной долине?",a="Ворота закрывают Подгорную тропу — горный проход, прорубленный сквозь возвышенности в Долину Королей в Лок Модане.",al={"dustfire gate","locked door dustfire","where does stonewrought pass lead","ворота выжженной долины","запертая дверь выжженная долина","куда ведет подгорная тропа"}},{q="Можно ли открыть ворота в Лок Модан?",a="Ворота надежно заперты дворфийскими мастерами, чтобы защитить земли Лок Модана от угроз Тлеющего ущелья. Чтобы пройти, нужно достать особый ключ.",al={"how to open gate","open stonewrought pass","key to dustfire gate","как открыть ворота","открыть подгорную тропу","ключ от ворот выжженной долины"}},{q="Почему эта местность называется Выжженной долиной?",a="Название отражает удушливое сочетание вулканического пепла, сухой пыли и застоявшегося жара, свойственное этому каньону у северных горных стен.",al={"dustfire valley name","why dustfire","название выжженной долины","почему выжженная долина"}}},fp="15,239,21.426.0,44.119.0,36.169.0,40.152.0"}
P.entries["subzone:dustwallow-bay"] = {n="Пылевая бухта",s="Пылевая бухта — залив Великого моря между сырым побережьем Пылевых топей и укрепленным портом на острове Терамор. Ее солоноватые прибрежные мели кишат морской жизнью, коварными отмелями и укромными заливами вдали от основных морских путей восточного Калимдора.",h="Пылевая бухта — залив Великого моря между сырым побережьем Пылевых топей и укрепленным портом на острове...",kw={"dustwallow bay","dustwallow marsh","great sea","nat pagle","theramore","tidefury cove","пылевая бухта","пылевые топи","великое море","нат пэгл","терамор","залив яростных волн"},ang={["faction:Alliance"]="Для моряков и путников Альянса, направляющихся в Калимдор, Пылевая бухта — последний отрезок открытого моря перед укрепленной гаванью острова Терамор."},sec={{t="Воды восточных топей",b="Пылевая бухта обозначает береговую границу, где застойные мутные болота Пылевых топей встречаются с открытыми водами Великого моря. С востока к бухте примыкает остров Терамор, и она служит морским подходом для кораблей, идущих к островной гавани леди Джайны Праудмур. Несмотря на оживленное судоходство к докам и от них, окрестное побережье остается диким и опасным: оно усеяно скалистыми выступами, стоянками мурлоков и укромными бухточками, такими как Залив Яростных Волн."},{t="Приют рыбаков",b="Хотя сами топи кишат кроколисками и враждебными тварями, острова и заливы бухты привлекают тех, кто ищет уединения и богатого улова. Небольшие островки у Залива Яростных Волн служат тихим убежищем для рыболовов, и прежде всего для легендарного рыбака Ната Пэгла, которого часто можно увидеть удящим рыбу на скалах вдали от шумного Терамора."}},faq={{q="Где находится Пылевая бухта?",a="Пылевая бухта лежит вдоль восточного побережья центрального Калимдора, прямо между сырыми восточными берегами Пылевых топей и скалистой цитаделью на острове Терамор.",al={"dustwallow bay location","where is dustwallow bay","dustwallow water","пылевая бухта расположение","где пылевая бухта","пылевая бухта воды"}},{q="Кого можно встретить в бухте?",a="Самый известный обитатель внешних районов бухты — Нат Пэгл, прославленный на весь мир рыболов. Он разбил лагерь на небольшом островке в соседнем Заливе Яростных Волн, к юго-западу от острова Терамор.",al={"who is in dustwallow bay","nat pagle dustwallow bay","npcs dustwallow bay","кто в пылевой бухте","нат пэгл пылевая бухта","персонажи пылевой бухты"}},{q="Безопасно ли переплывать Пылевую бухту?",a="Хотя бухта сравнительно близка к безопасному острову Терамор, на ее мелководье и побережье часто встречаются мурлоки, акулы и другие агрессивные водные существа, обитающие на краю топей.",al={"is dustwallow bay dangerous","monsters in dustwallow bay","опасна ли пылевая бухта","монстры в пылевой бухте"}}},fp="14,284,27.483.0,19.377.0,32.180.0,28.195.0,38.196.0"}
P.entries["subzone:dustwind-cave"] = {n="Пещера Пыльного Ветра",s="Пещера Пыльного Ветра — укромная лощина на утесах Каньона Колючего Ветра, к северо-востоку от Колючего Холма. Она служит действующим учебным лагерем и тайным убежищем для новообращенных зловещего культа Пылающего Клинка в Дуротаре.",h="Пещера Пыльного Ветра — укромная лощина на утесах Каньона Колючего Ветра, к северо-востоку от Колючего Холма.",kw={"burning blade","cultists","durotar","dustwind cave","felblood","razor hill","razorwind canyon","пылающий клинок","культисты","дуротар","пещера пыльного ветра","скверна в крови","колючий холм","каньон колючего ветра"},ang={["class:Warlock"]="Чернокнижники Орды узнают темные ритуалы, проводимые в Пещере Пыльного Ветра, хотя Пылающий Клинок направляет свои дары скверны на мятеж, а не на службу новому порядку Тралла.",["faction:Horde"]="Пещера Пыльного Ветра — постыдная и опасная внутренняя брешь: демонические культисты скрываются на расстоянии окрика от Колючего Холма."},sec={{t="Тень в утесах",b="Пещера Пыльного Ветра, нависающая над Каньоном Колючего Ветра, — одна из ближайших и самых опасных угроз для Колючего Холма. Многие считают, что демонические культисты собираются лишь в глубоких подземельях, но здесь Пылающий Клинок обучает новобранцев прямо под носом у властей Орды. Темные культисты наставляют неофитов в запретной темной магии и демонологии, готовя их подорвать молодое орочье государство изнутри, на землях самого Дуротара."},{t="Оскверненная кровь",b="Тем, кто проникает в пещеру, грозит опасность подвергнуться порче культистов. Здешние последователи используют губительные темные искусства, например недуги скверной крови, что показывает, насколько прочно Пылающий Клинок держится за демоническое наследие, которое Тралл так упорно стремился изгнать. Уничтожить здешний культ необходимо, чтобы сохранить хрупкий мир в Дуротаре."}},faq={{q="Где находится Пещера Пыльного Ветра?",a="Пещера Пыльного Ветра расположена высоко на утесах Каньона Колючего Ветра, прямо к северо-востоку от Колючего Холма в Дуротаре.",al={"dustwind cave location","where is dustwind cave","how to find dustwind cave","пещера пыльного ветра расположение","где пещера пыльного ветра","как найти пещеру пыльного ветра"}},{q="Кто обитает в Пещере Пыльного Ветра?",a="В пещере обитают культисты и неофиты Пылающего Клинка — мрачного демонического культа, стремящегося распространять скверну и расшатать Орду.",al={"who is in dustwind cave","dustwind cave enemies","mobs in dustwind cave","кто в пещере пыльного ветра","враги пещеры пыльного ветра","монстры в пещере пыльного ветра"}},{q="Почему здесь действует Пылающий Клинок?",a="Пылающий Клинок использует Пещеру Пыльного Ветра как укромный учебный пункт, где опытные культисты обучают новичков демоническим искусствам вдали от пристальных взглядов стражи Оргриммара и Колючего Холма.",al={"why are cultists in dustwind cave","burning blade purpose durotar","почему культисты в пещере пыльного ветра","цель пылающего клинка дуротар"}},{q="Почему Орда хочет очистить эту пещеру?",a="Культисты, поклоняющиеся демонам и затаившиеся в нескольких шагах от Колючего Холма, представляют недопустимую угрозу для новобранцев в пути и для обороны Дуротара в целом.",al={"why clear dustwind cave","horde threat dustwind cave","зачем очищать пещеру пыльного ветра","угроза орде пещера пыльного ветра"}}},fp="13,245,22.435.0,18.354.0,31.116.0,27.158.0,40.198.0,42.166.0"}
P.entries["subzone:eastern-strand"] = {n="Восточное побережье",s="Восточное побережье — участок южного берега в Предгорьях Хилсбрада, расположенный на юго-востоке у границы с Нагорьем Арати. Некогда мирные берега, пляжи и мелководье захвачены враждебными нагами Пронзающего Гребня, устроившими здесь береговой плацдарм.",h="Восточное побережье — участок южного берега в Предгорьях Хилсбрада, расположенный на юго-востоке у границы с...",kw={"beach","coast","daggerspine","eastern strand","hillsbrad foothills","naga","пляж","побережье","пронзающий гребень","восточное побережье","предгорья хилсбрада","наги"},ang={["faction:Alliance"]="Наги, расположившиеся лагерем на Восточном побережье, представляют прямую угрозу с фланга морской безопасности Южнобережья и ближайших патрулей.",["faction:Horde"]="Любое организованное продвижение нагов от побережья вглубь суши угрожает нарушить передвижения Орды и линии снабжения, проходящие через нижний Хилсбрад."},sec={{t="Враждебный берег",b="Восточное побережье тянется вдоль юго-восточного края Предгорий Хилсбрада и дополняет Западное побережье на другой стороне залива. Хотя этот край известен в основном человеческими фермерскими поселениями и спорами за территорию между Южнобережьем и Мельницей Таррен, эти песчаные отмели и приливные полосы целиком во власти нагов Пронзающего Гребня. Выбираясь из Великого моря, змеиный народ скользит по песчаным косам, обитает среди скалистых выступов и пристально наблюдает за сушей."},{t="Земли Пронзающего Гребня",b="Присутствие Пронзающего Гребня делает берег к юго-востоку от Южнобережья опасным. Их воины и заклинатели бродят по пляжам и близлежащим водам, делая побережье опасным для путников."}},faq={{q="Где находится Восточное побережье?",a="Восточное побережье охватывает прибрежные пески и мелководье в юго-восточном углу Предгорий Хилсбрада и тянется на восток вдоль воды к границам Нагорья Арати.",al={"eastern strand location","where is eastern strand","eastern strand map","где восточное побережье","восточное побережье расположение","восточное побережье карта"}},{q="Какие существа обитают на Восточном побережье?",a="Пляж и ближайшие воды захвачены племенем нагов Пронзающего Гребня: пехотинцами, налетчиками и заклинателями, рыщущими вдоль кромки прибоя.",al={"eastern strand mobs","who lives on eastern strand","eastern strand enemies","восточное побережье мобы","кто живет на восточном побережье","восточное побережье враги"}},{q="Почему наги собираются на этом пляже?",a="Пронзающий Гребень занимает пляжи и воды Восточного побережья. Цели, помимо удержания этой прибрежной территории, в версии Classic не упоминаются.",al={"why are naga in hillsbrad","daggerspine attack plans","what are the naga doing here","почему наги в хилсбраде","планы атаки пронзающего гребня","что делают здесь наги"}},{q="Чем Восточное побережье отличается от Западного побережья?",a="Both strands border the southern coast of Hillsbrad. The Western Strand lies southwest toward Silverpine and is home to Torn Fin murlocs; the Eastern Strand lies southeast toward Arathi and is occupied by Daggerspine naga.",al={"western strand vs eastern strand","two beaches in hillsbrad","западное побережье и восточное побережье","два пляжа в хилсбраде"}}},fp="14,270,19.474.0,21.188.1,36.189.0,42.147.0,41.157.0,59.222.0"}
P.entries["subzone:eastmoon-ruins"] = {n="Руины Восточной Луны",s="Руины Восточной Луны — древнее тролльское археологическое место в восточном Танарисе, к западу от Зияющей бездны. Некогда выстроенные пустынными империями древности, осыпающиеся каменные стены ныне заняты ограми Песчаного Молота, устроившими здесь лагерь в пустыне.",h="Руины Восточной Луны — древнее тролльское археологическое место в восточном Танарисе, к западу от Зияющей...",kw={"darkcaster","eastmoon","eastmoon ruins","gaping chasm","survivalist","tanaris","troll ruins","wastewander","темный заклинатель","восточная луна","руины восточной луны","зияющая бездна","знаток выживания","танарис","тролльские руины","бродяга пустошей"},ang={["class:Rogue"]="Разбитые колонны и разбросанные каменные стены дают множество слепых углов, чтобы проскользнуть мимо огров Песчаного Молота, бродящих по периметру, или устроить им засаду.",["race:Troll"]="Разрушенная кладка тихо напоминает о далеко простиравшейся власти ваших предков над Калимдором до того, как пустынные пески поглотили юг."},sec={{t="Камни в песках",b="Руины Восточной Луны поднимаются над раскаленной пустыней к западу от кишащей насекомыми Зияющей бездны и хранят рушащуюся архитектуру древней тролльской цивилизации. Разрушающиеся колонны, выветренные каменные площади и выбеленные солнцем памятники намекают на время задолго до того, как пески поглотили этот край. Святилища охраняют не ученые и не потомки троллей: место прочно удерживают огры Песчаного Молота, использующие разбитые стены как укрытие и наблюдательный пост над ближними торговыми путями."}},faq={{q="Кто построил Руины Восточной Луны?",a="Архитектура принадлежит древним троллям. Задолго до того, как Танарис стал засушливой пустошью, тролльские цивилизации господствовали на юге Калимдора и оставили каменные постройки, храмы и площади, подобные тем, что медленно разрушаются в Руинах Восточной Луны.",al={"who made eastmoon ruins","eastmoon origin","trolls built eastmoon","кто построил руины восточной луны","происхождение руин восточной луны","тролли построили восточную луну"}},{q="Кто контролирует Руины Восточной Луны сейчас?",a="Руины заняты ограми Песчаного Молота из Танариса. Эти громадные пустынные громилы завладели древними каменными стенами, устроили лагеря и следят за востоком Танариса.",al={"who lives at eastmoon","eastmoon ruins mobs","wastewanders at eastmoon","кто живет в руинах восточной луны","руины восточной луны мобы","бродяги пустошей в руинах восточной луны"}},{q="Где находятся Руины Восточной Луны?",a="Вы найдете их на востоке Танариса, сразу к западу от населенных силитидами ульев Зияющей бездны.",al={"eastmoon ruins location","where is eastmoon","find eastmoon ruins","руины восточной луны расположение","где восточная луна","найти руины восточной луны"}},{q="Есть ли в Руинах Восточной Луны задания?",a="Особых заданий, связанных именно с Руинами Восточной Луны, нет. Это место служит в основном лагерем разбойников и историческим ориентиром для искателей приключений, исследующих глубины пустыни.",al={"eastmoon quests","quests at eastmoon ruins","is there a quest here","задания восточной луны","задания в руинах восточной луны","есть ли здесь задание"}}},fp="14,273,18.492.0,29.225.0,32.174.0,37.130.0,39.185.0"}
P.entries["subzone:eastvale-logging-camp"] = {n="Лесопилка Восточной долины",s="Лесопилка Восточной долины — важное лесозаготовительное поселение в восточных чащах Элвиннского леса, близ границы с Красногорьем. Лагерь поставляет необходимую древесину Штормграду и окрестным поселениям, но его работе постоянно мешают голодные хищники, рыщущие в окрестных лесах.",h="Лесопилка Восточной долины — важное лесозаготовительное поселение в восточных чащах Элвиннского леса, близ...",kw={"eastvale","elwynn","haggard","horses","logging camp","lumber","raelen","timber","tremaind","восточная долина","элвиннский лес","хаггард","лошади","лесопилка","древесина","раелен","бревна","тремейнд"},ang={["faction:Alliance"]="Лесопилка Восточной долины — одно из лучших мест в Элвиннском лесу, где члены Альянса могут купить надежных штормградских скакунов.",["race:Human"]="Для людей Штормграда Восточная долина поставляет необходимую древесину, которая позволяет и дальше отстраивать и поддерживать поселения королевства."},sec={{t="Важное дело в осаде",b="Заказы на древесину непрерывно поступают на Лесопилку Восточной долины от покупателей со всего Королевства Штормград, но уложиться в жесткие сроки — мучительная задача. Густая чаща вокруг лагеря кишит свирепыми волками и бродящими медведями, которые то и дело гонят дровосеков с рабочих мест, оставляя ценные бревна брошенными в лесу. Под руководством Бригадира Раелен лагерь часто полагается на странствующих искателей приключений, которые уничтожают наступающих зверей и возвращают упавшую древесину, пока поставки не отстали от графика безнадежно."},{t="Жизнь на восточной границе",b="Несмотря на удаленность, Восточная долина — не просто лесозаготовительный форпост. Здесь есть несколько жилых домов и оживленные конюшни, где путники могут купить хороших скакунов. Торговля лесом тесно связана со штормградской знатью, включая лорда Джорана Тремейнда, чья семья имеет значительные деловые интересы в заготовке древесины лагеря. На ближнем холме над рабочей площадкой стоит тихая усадьба отставного маршала Хаггарда, бывшего главы Стражи Штормграда, удалившегося на этот простой форпост, чтобы провести отставку вдали от столичной политики."}},faq={{q="Каково основное назначение Лесопилки Восточной долины?",a="Лесопилка Восточной долины — главный источник древесины в восточной части Элвиннского леса для Королевства Штормград. Дровосеки трудятся здесь подолгу и в жестких сроках, чтобы удовлетворить высокий спрос на дерево со стороны строителей и знати по всему королевству.",al={"why is eastvale here","what is eastvale","eastvale lumber role","зачем нужна восточная долина","что такое восточная долина","роль лесопилки восточной долины"}},{q="Почему лесопилка всегда нанимает искателей приключений?",a="Лагерь окружен густым лесом, а агрессивные дикие медведи и бродящие волки постоянно угрожают рабочим. Нападения нередко заставляют дровосеков бежать, бросая заготовленную древесину, и ставят под серьезную угрозу срыв сроков отгрузки.",al={"eastvale problems","why do loggers need help","wolves at eastvale","проблемы восточной долины","зачем лесорубам помощь","волки у восточной долины"}},{q="Кто такой маршал Хаггард?",a="Маршал Хаггард — отставной бывший глава Стражи Штормграда. Несколько лет назад он оставил службу и теперь живет в тихой усадьбе на утесах над Лесопилкой Восточной долины.",al={"haggard","old man near eastvale","marshal haggard elwynn","хаггард","старик у восточной долины","маршал хаггард элвиннский лес"}},{q="Можно ли купить скакунов на Лесопилке Восточной долины?",a="Да. На лесопилке есть действующая конюшня с разведением лошадей, где искатели приключений Альянса могут купить верховых лошадей и обучение верховой езде.",al={"horse vendor eastvale","eastvale horses","buy mount elwynn","продавец лошадей восточная долина","лошади восточной долины","купить скакуна элвиннский лес"}}},fp="21,317,29.561.0,28.585.0,50.232.0,50.259.0,23.203.0,44.137.0"}
P.entries["subzone:eastwall-gate"] = {n="Восточные ворота",s="Восточные ворота — укрепленный боковой вход в окружную стену павшего города Стратхольм. Расположенные на севере Восточных Чумных земель, они дают прямой запасной доступ к руинам внутри Стратхольма в обход хаоса у главных ворот города.",h="Восточные ворота — укрепленный боковой вход в окружную стену павшего города Стратхольм.",kw={"alonsus chapel","eastern plaguelands","eastwall gate","elders' square","key to the city","portcullis","side entrance","stratholme","часовня алонсуса","восточные чумные земли","восточные ворота","площадь старейшин","ключ от города","решетка","боковой вход","стратхольм"},ang={["class:Paladin"]="Пройдя через Восточные ворота, крестоносцы сразу оказываются рядом с часовней Алонсуса — священным убежищем, ныне окруженным пеплом и ужасами Плети.",["class:Rogue"]="Прочный замок Восточных ворот требует высшего мастерства взлома, поэтому мастер-разбойник незаменим, чтобы обойти главный вход без Ключа от города."},sec={{t="Черный ход к руинам",b="Если величественный главный вход Стратхольма ведет прямо на Королевскую площадь, то Восточные ворота пронзают восточные укрепления города. Надежно запертые от чужаков, они ведут прямо на Площадь Старейшин, неподалеку от ступеней часовни Алонсуса. Для тех, кто идет в пылающее сердце оплота Плети, обход передних баррикад может стать разницей между быстрым ударом в глубины города и мясорубкой на передовых линиях нежити."},{t="Сквозь железную решетку",b="Попасть через Восточные ворота нелегко. Они плотно заперты тяжелой железной решеткой, для которой нужен Ключ от города, найденный внутри самого Стратхольма, или исключительно искусный взломщик, способный вскрывать мастерские замки. Оказавшись внутри, путники могут поднять решетку тяжелым механическим рычагом на внутренней стене и открыть надежный путь для союзников."}},faq={{q="Куда ведут Восточные ворота?",a="Ворота открываются на Площадь Старейшин в разрушенном городе Стратхольм. Рядом находится историческая часовня Алонсуса.",al={"where does eastwall gate go","eastwall gate destination","what is behind eastwall gate","куда ведут восточные ворота","восточные ворота назначение","что за восточными воротами"}},{q="Как открыть ворота?",a="Восточные ворота надежно заперты. Их можно открыть с помощью Ключа от города, найденного в Стратхольме, или вскрыть опытным разбойником, овладевшим взломом замков. Оказавшись внутри, поднять ворота вручную можно внутренним рычагом.",al={"how to open eastwall gate","unlock eastwall gate","eastwall gate key","как открыть восточные ворота","взломать восточные ворота","ключ от восточных ворот"}},{q="Почему искатели приключений выбирают этот вход, а не главные ворота?",a="Вход через Восточные ворота позволяет штурмовым отрядам обойти кишащие нежитью передние улицы и начать атаку прямо у Площади Старейшин, быстрее добираясь до отдельных кварталов города.",al={"why use eastwall gate","side entrance benefits","why side gate stratholme","зачем восточные ворота","преимущества бокового входа","зачем боковые ворота стратхольма"}},{q="Можно ли открыть ворота изнутри?",a="Да. Рычаг на внутренней, стратхольмской стороне ворот позволяет любому, кто внутри, поднять ворота и впустить остальных без ключа.",al={"lever inside eastwall gate","open eastwall gate from inside","рычаг внутри восточных ворот","открыть восточные ворота изнутри"}}},fp="13,286,21.492.0,24.432.0,34.133.0,27.219.0,59.212.0,38.143.0"}
P.entries["subzone:eastwall-tower"] = {n="Восточная башня",s="Восточная башня — разрушенная разведывательная башня Лордерона в Восточных Чумных землях близ восточной дороги. Башня была разгромлена в Третью войну, когда Плеть прокатилась по королевству, и теперь ее руины возвышаются над кишащими Плетью пустошами.",h="Восточная башня — разрушенная разведывательная башня Лордерона в Восточных Чумных землях близ восточной...",kw={"eastern plaguelands","eastwall tower","lordaeron","plaguelands tower","scout tower","восточные чумные земли","восточная башня","лордерон","башня чумных земель","разведывательная башня"},ang={["faction:Alliance"]="Для Альянса возвращение Восточной башни чтит павших солдат Лордерона и обеспечивает подступы к Часовне Последней Надежды от вторжений Плети.",["faction:Horde"]="Разрушенная разведывательная башня обозревает дороги через враждебные северные земли."},sec={{t="Разрушенный дозор на границе",b="Построенная как пограничный страж королевства Лордерон, Восточная башня некогда наблюдала за путниками, направлявшимися в дальние края государства. Когда Плеть вторглась в ходе Третьей войны, форпост был сокрушен вместе с окрестными поселениями, оставив разбитые каменные арки и обугленные балки. Теперь, когда армии Короля-лича все еще наводняют край, возвышенное положение башни делает ее незаменимым передовым постом. Ее разрушенные стены обозревают дороги через кишащую Плетью местность."}},faq={{q="Чем была Восточная башня до падения?",a="Восточная башня изначально была оборонительной разведывательной башней, построенной Королевством Лордерон. Она входила в региональную сеть пограничных дозоров и охраняла торговые пути и дальние фермы, пока Третья война не привела к падению Лордерона.",al={"eastwall tower history","who built eastwall tower","what was this place","история восточной башни","кто построил восточную башню","чем было это место"}},{q="Кто разрушил башню?",a="Башню разрушила Плеть во время завоевания принца Артаса Менетила и последовавшего опустошения Лордерона нежитью. Чудовища нежити разбили ее оборону, оставив защитников мертвыми, а строение — в руинах.",al={"how was eastwall tower ruined","what happened to eastwall tower","как разрушили восточную башню","что случилось с восточной башней"}},{q="Чем башня важна стратегически?",a="Даже в руинах башня господствует над высотой вдоль восточных дорог Чумных земель и обозревает кишащую Плетью местность.",al={"eastwall tower importance","eastwall tower position","важность восточной башни","положение восточной башни"}},{q="Безопасно ли отдыхать в башне?",a="Разрушенная башня стоит среди кишащей Плетью местности и не дает надежного укрытия.",al={"can i rest here","friendly guards","можно ли отдохнуть здесь","дружественные стражи"}}},fp="14,232,28.519.0,39.245.0,24.226.0,41.138.0,29.84.0"}
P.entries["subzone:echo-isles"] = {n="Острова Эха",s="Острова Эха — группа тропических островов недалеко от юго-восточного побережья Дуротара. Первоначально их заселили тролли племени Черного Копья, бежавшие с родовых островов, но сейчас архипелагом владеет вероотступник, шаман-колдун Залазан, который темной магией и порабощенными приспешниками изгнал свой народ.",h="Острова Эха — группа тропических островов недалеко от юго-восточного побережья Дуротара.",kw={"darkspear","durotar","echo isles","sen'jin village","trolls","vol'jin","voodoo","zalazane","черное копье","дуротар","острова эха","деревня сен'джин","тролли","вол'джин","вуду","залазан"},ang={["faction:Horde"]="Защита Островов Эха необходима для стабилизации южного побережья Дуротара, охраны Деревни Сен'джин и укрепления границ молодой Орды от морских угроз и отступников-мистиков.",["race:Troll"]="Острова Эха — это и обещанный дом племени Черного Копья в Калимдоре, и горькая боль от предательства Залазана. Их возвращение — вопрос выживания племени и личной чести."},sec={{t="Расколотое убежище",b="После бегства через Великое море вместе с Траллом племя Черного Копья избрало Острова Эха своим новым домом. Их покой не раз нарушался: сначала флотом верховного адмирала Даэлина Праудмура во время вторжения Кул Тираса в Дуротар, а затем изнутри. Вскоре после того как тролли отбросили флот Праудмура, один из их собственных колдунов, Залазан, овладел темными искусствами и поработил разум своих сородичей. Вождь Вол'джин и свободные тролли Черного Копья снова были вынуждены покинуть острова и искали временное убежище через узкий пролив, в Деревне Сен'джин."},{t="Хватка Залазана",b="Сегодня тропические острова наводнены агрессивными хищниками, оскверненными животными и рабами Залазана. С помощью злобных порч, фетишей вуду и куч джу-джу, расставленных по островам, вероломный колдун подчиняет своей воле зверей и плененных троллей. Из лагеря на Побережье Черного Копья разведчики и воины Вол'джина часто совершают вылазки на острова, стремясь найти останки павших и сразить безумного мистика, укравшего их дом."}},faq={{q="Почему тролли племени Черного Копья сейчас не живут здесь?",a="Колдун Залазан предал племя: темной магией он лишил соплеменников свободной воли и превратил их в покорных слуг. Вождь Вол'джин приказал эвакуироваться на материковое побережье Дуротара, где основал Деревню Сен'джин как плацдарм, пока племя борется за возвращение дома.",al={"why abandoned","why did trolls leave","troll home","почему покинуты","почему тролли ушли","дом троллей"}},{q="Кто такой Залазан?",a="Залазан — вероломный колдун племени Черного Копья, восставший против своих. Мощным вуду и темной магией он наложил на острова порчу, осквернил местных животных и превратил собратьев-троллей в безвольных рабов.",al={"who is zalazane","boss on echo isles","witch doctor zalazane","кто такой залазан","босс на островах эха","колдун залазан"}},{q="Какие угрозы есть на островах?",a="Архипелаг кишит дикими ящерами, тиграми и оскверненными зверями, а также кучами вуду Залазана и его троллями-приспешниками под властью разума, в том числе заколдованными троллями и троллями вуду.",al={"echo isles mobs","what is on the islands","echo isles dangers","существа островов эха","что на островах","опасности островов эха"}},{q="Как племя Черного Копья оказалось на этих островах?",a="После того как Тралл и Орда спасли племя Черного Копья от тонущего острова и враждебных наг в Великом море, тролли отправились в Калимдор, и им были даны Острова Эха, чтобы поселиться рядом с союзниками-орками.",al={"how did trolls get here","darkspear origin","echo isles history","как тролли попали сюда","происхождение черного копья","история островов эха"}}},fp="10,320,21.590.0,15.488.0,51.308.0,16.224.0,32.185.0,63.214.0"}
P.entries["subzone:echo-ridge-mine"] = {n="Рудник Горного Эха",s="Рудник Горного Эха — небольшая выработка в северо-западных утесах Долины Североземья. Богатый камнем и рудой, он недавно попал в лапы разрушительного нашествия кобольдов, что остановило местные работы в Североземье.",h="Рудник Горного Эха — небольшая выработка в северо-западных утесах Долины Североземья.",kw={"echo ridge","echo ridge mine","kobold","marshal mcbride","mine","northshire","northshire valley","рудник горного эха","кобольд","маршал макбрайд","рудник","североземье","долина североземья"},ang={["profession:Mining"]="Шахты Горного Эха богаты ранними залежами минералов, но любому старателю, ищущему руду, сначала придется пробиться через орды кобольдов со свечами.",["race:Human"]="Для новобранцев, откликнувшихся на зов Штормграда, очистка Рудника Горного Эха — важное боевое крещение в защите Аббатства Североземья."},sec={{t="Оплот паразитов",b="Рудник Горного Эха, укрытый в холмах над Аббатством Североземья, должен был снабжать долину камнем и металлом. Вместо этого кобольды-оппортунисты наводнили туннели и выгнали местных рабочих. Маршал Макбрайд считает нашествие недопустимой угрозой безопасности Североземья и набору рекрутов, поэтому направляет новичков прямо в туннели, чтобы сократить число кобольдов и вернуть рудник."},{t="Угроза под Североземьем",b="Захват Рудника Горного Эха — часть общей картины вторжения кобольдов, распространяющегося по Элвиннскому лесу. Если не остановить их на северо-западном хребте, эти подземные вредители угрожают нарушить мирные тренировочные земли Североземья и перекрыть поступление важных ресурсов в аббатство."}},faq={{q="Почему кобольды в Руднике Горного Эха?",a="Кобольды — прирожденные землекопы, их влекут темные туннели, богатые минералами. Почувствовав слабую защиту, они захватили Рудник Горного Эха, чтобы искать сокровища и объявить территорию своей.",al={"why kobolds here","echo ridge kobolds","who took the mine","почему здесь кобольды","кобольды рудника горного эха","кто захватил рудник"}},{q="Кто пытается вернуть Рудник Горного Эха?",a="Маршал Макбрайд из Аббатства Североземья руководит усилиями по очистке рудника. Он привлекает недавно прибывших искателей приключений, чтобы они разведали туннели и истребили паразитов, пока те не проникли дальше в долину.",al={"who wants echo ridge back","echo ridge quests","mcbride echo ridge","кто хочет вернуть рудник горного эха","задания рудника горного эха","макбрайд рудник"}},{q="Где находится Рудник Горного Эха?",a="Вход в рудник расположен в северо-западном углу Долины Североземья, прямо в скалистом склоне холма к северу от виноградников аббатства.",al={"echo ridge location","where is echo ridge","find echo ridge mine","где рудник горного эха","расположение рудника горного эха","найти рудник горного эха"}}},fp="15,235,21.427.0,29.298.0,35.177.0,41.203.0,33.146.0"}
P.entries["subzone:elder-rise"] = {n="Вершина Старейшин",s="Вершина Старейшин лежит прямо к востоку от центрального плато Громового Утеса, и к ней ведут длинные подвесные мосты от Высокой вершины и Средней вершины. Это духовное сердце столицы тауренов: здесь расположены Круг Кенария, друиды и жрецы тауренов и правящий Совет старейшин.",h="Вершина Старейшин лежит прямо к востоку от центрального плато Громового Утеса, и к ней ведут длинные...",kw={"cenarion circle","elder rise","hall of elders","hamuul runetotem","magatha grimtotem","mulgore","thunder bluff","круг кенария","вершина старейшин","зал старейшин","хамуул рунический тотем","магата зловещий тотем","мулгор","громовой утес"},ang={["class:Druid"]="Вершина Старейшин — главный дом для друидов Орды: здесь убежище верховного друида Хамуула Рунического Тотема и региональная резиденция Круга Кенария в Калимдоре.",["race:Tauren"]="На вершине находятся Совет старейшин и духовные наставники, которые ведут ваши племена через мир, традиции и сложные реалии Орды."},sec={{t="Святилище веры и совета",b="Вершина Старейшин, соединенная с главными мезами качающимися веревочными мостами, посвящена тихим размышлениям, священной мудрости и управлению общиной. Друиды и жрецы тауренов собираются здесь, чтобы обучать послушников путям природы и духовной преданности. На вершине этой мезы живет верховный друид Хамуул Рунический Тотем, почитаемый вождь, вернувший друидизм народу тауренов и установивший тесные связи с Кругом Кенария. Рядом с этими дикими святилищами стоит Зал Старейшин, где вожди племен собираются, чтобы обсуждать дела своей юной столицы."},{t="Шаткое присутствие",b="Несмотря на роль мирного святилища, над вершиной сохраняется политическое напряжение. Магата Зловещий Тотем, старейшая матриарх скрытного и надменного племени Зловещего Тотема, живет в хижине между двумя мостами. Хотя Кэрн Кровавое Копыто предоставляет гостеприимство и места в совете всем родам тауренов, ее бдительное присутствие постоянно напоминает, что не каждое племя разделяет миролюбивые идеалы Кровавого Копыта и безоговорочный союз с Ордой."}},faq={{q="Для чего нужна Вершина Старейшин?",a="Вершина Старейшин — центр духовного обучения и общественных обсуждений в Громовом Утесе. Здесь находятся друиды Круга Кенария, жрецы тауренов, правящий Совет старейшин и вожди племен.",al={"purpose of elder rise","what is on elder rise","elder rise buildings","назначение вершины старейшин","что на вершине старейшин","здания вершины старейшин"}},{q="Кто возглавляет друидов на Вершине Старейшин?",a="Здесь живет верховный друид Хамуул Рунический Тотем. Близкий друг и советник Кэрна Кровавого Копыта, Хамуул — старший по рангу таурен в Круге Кенария и обучает тех, кто призван идти путем природы.",al={"archdruid thunder bluff","tauren druid leader","hamuul location","верховный друид громовой утес","предводитель друидов тауренов","где хамуул"}},{q="Почему Магата Зловещий Тотем живет здесь?",a="Магата Зловещий Тотем занимает палатку между мостами. Как старейшая провидица и вождь племени Зловещего Тотема, она присутствует на Совете старейшин, представляя свой народ в Громовом Утесе, несмотря на взаимное недоверие между ее кланом и союзниками Кэрна.",al={"where is magatha","magatha grimtotem location","grimtotem on elder rise","где магата","где магата зловещий тотем","зловещий тотем на вершине старейшин"}},{q="Как добраться до Вершины Старейшин?",a="Вершина Старейшин лежит прямо к востоку от центрального плато города. До нее можно добраться по большим деревянным веревочным мостам, соединенным с Высокой вершиной и нижним плато.",al={"getting to elder rise","elder rise bridges","directions elder rise","как добраться до вершины старейшин","мосты вершины старейшин","дорога к вершине старейшин"}}},fp="10,292,30.550.0,21.480.0,28.204.0,35.201.0,37.258.0,28.163.0"}
P.entries["subzone:eldreth-row"] = {n="Ряд Элдрет",s="Ряд Элдрет — возвышающиеся разрушенные внешние залы, образующие западный вход в Забытый Город в Фераласе. Некогда величественный порог древнего Эльдре'Таласа, теперь он зарос и усиленно патрулируется ограми Гордунни.",h="Ряд Элдрет — возвышающиеся разрушенные внешние залы, образующие западный вход в Забытый Город в Фераласе.",kw={"broken commons","dire maul","dire pool","eldre'thalas","eldreth row","feralas","gordunni","warpwood quarter","разрушенный общинный квартал","забытый город","жуткий пруд","эльдре'талас","ряд элдрет","фералас","гордунни","квартал криводревов"},ang={["race:NightElf"]="Вид величественной кладки древнего Эльдре'Таласа, оскверненной грубыми ограми, горько напоминает о падении высокорожденных и Расколе."},sec={{t="Порог Эльдре'Таласа",b="Ряд Элдрет, внешний рубеж древнего Эльдре'Таласа, — внушительная аллея высоких арочных эльфийских построек рядом с внутренними кварталами и Разрушенным Общинным кварталом. Века запустения потрескали каменную кладку, и расползающаяся флора Фераласа отвоевывает колоннады. Сегодня безупречное величие высокорожденных сменилось грубым господством огров Гордунни, которые используют залы как внешний плацдарм, охраняя пути на восток к Кварталу Криводревов и на запад мимо Жуткого пруда."}},faq={{q="Что такое Ряд Элдрет?",a="Ряд Элдрет — внешний входной зал и рубеж Забытого Города в Фераласе, расположенный перед Разрушенным Общинным кварталом и внутренними вратами подземелья.",al={"eldreth row","what is this place","dire maul entrance","ряд элдрет","что это за место","вход в забытый город"}},{q="Кто сейчас контролирует Ряд Элдрет?",a="Область занята и патрулируется кланом огров Гордунни, которые укрепили руины Забытого Города и бродят по его разрушенным аллеям.",al={"who lives here","who controls eldreth row","eldreth row monsters","кто здесь живет","кто контролирует ряд элдрет","монстры ряда элдрет"}},{q="Куда ведет Ряд Элдрет?",a="Аллея ведет вглубь к Разрушенному Общинному кварталу и главным комплексам Забытого Города; вход в Квартал Криводревов находится на ее дальнем восточном фланге, а Жуткий пруд — на западе.",al={"where does this hall go","eldreth row exits","dire maul paths","куда ведет этот зал","выходы ряда элдрет","пути забытого города"}}},fp="11,236,29.554.0,20.148.0,35.133.0,28.191.0"}
P.entries["subzone:emerald-sanctuary"] = {n="Изумрудное святилище",s="Изумрудное святилище — застава Круга Кенария у южного входа в Оскверненный лес. Здесь друиды ночных эльфов и тауренов объединяются, чтобы изучать повсеместную демоническую скверну и пытаться исцелить оскверненные леса.",h="Изумрудное святилище — застава Круга Кенария у южного входа в Оскверненный лес.",kw={"cenarion circle","corruption","druids","emerald sanctuary","felwood","jaedenar","круг кенария","скверна","друиды","изумрудное святилище","оскверненный лес","джеденар"},ang={["class:Druid"]="Для друидов и Дарнасса, и Громового Утеса Изумрудное святилище — важное напоминание об общем призвании, показывающее, что долг исцелять землю выше мирской верности фракциям."},sec={{t="Маяк во мраке",b="Изумрудное святилище, расположенное на южной окраине Оскверненного леса у границы Ясеневого леса, служит главной базой Круга Кенария в этой погубленной глуши. В отличие от ожесточенных конфликтов фракций по всему Калимдору, это святилище — нейтральный оплот, где друиды отбрасывают политику и целиком сосредоточены на восстановлении природы. Отсюда исследователи следят за оскверненной флорой и направляют изыскания к Джеденару, ища любой способ очистить отравленную почву."}},faq={{q="Для чего нужно Изумрудное святилище?",a="Круг Кенария основал лагерь, чтобы изучать и останавливать демоническую скверну, душащую Оскверненный лес. Расквартированные здесь друиды исследуют оскверненные растения, зверей и источники воды, координируя борьбу с культистами Совета Теней, засевшими глубже в лесу.",al={"why is emerald sanctuary here","what do druids do here","emerald sanctuary purpose","зачем изумрудное святилище","что делают друиды здесь","назначение изумрудного святилища"}},{q="Могут ли Альянс и Орда посещать Изумрудное святилище?",a="Да. Круг Кенария — независимая нейтральная организация. Искатели приключений Альянса и Орды желанны, если готовы помогать в очищении глубокой скверны Оскверненного леса.",al={"is emerald sanctuary neutral","horde allowed emerald sanctuary","alliance sanctuary friendly","нейтрально ли изумрудное святилище","орда в изумрудном святилище","альянс святилище дружелюбно"}},{q="Какая угроза больше всего тревожит здешних друидов?",a="Хотя весь лес искажен демонической энергией, оставшейся после Третьей войны, друиды особенно встревожены Джеденаром — обширным пещерным комплексом на севере, где активно гнездится Совет Теней и распространяет скверну.",al={"biggest threat in felwood","what are druids fighting","jaedenar threat","главная угроза оскверненного леса","с чем борются друиды","угроза джеденара"}}},fp="17,247,22.507.0,45.271.0,56.201.0,46.239.0"}
P.entries["subzone:engineering-labs"] = {n="Инженерные лаборатории",s="Инженерные лаборатории — многоуровневый исследовательский и производственный комплекс в глубинах Гномрегана. Этот оживленный центр гномьих изобретений был захвачен во время радиоактивной катастрофы в городе, и теперь в нем кишат обезумевшие лепрогномы и взбесившиеся механизмы.",h="Инженерные лаборатории — многоуровневый исследовательский и производственный комплекс в глубинах Гномрегана.",kw={"engineering labs","gnomeregan","launch bay","leper gnome","punchograph","tinkers court","workshop entrance","инженерные лаборатории","гномреган","пусковая установка","лепрогном","перфограф","двор механиков","вход в мастерскую"},ang={["profession:Engineering"]="Инженерные лаборатории — вершина павшей гномьей автоматизации: среди обломков сохранились действующие автоматические перфографы и брошенные схемы.",["race:Gnome"]="Для изгнанных гномов эти лаборатории — печальное зрелище: некогда бьющееся сердце технологических триумфов их народа, ныне облученные руины, захваченные их искаженными сородичами."},sec={{t="Павший центр изобретений",b="Инженерные лаборатории построены вокруг центральной механической конструкции и состоят из двух основных ярусов, соединенных центральным грузовым подъемником. В лучшие времена Гномрегана здешние механики разрабатывали схемы и совершенствовали заводные изобретения. Сегодня утечки радиации свели оставшихся исследователей с ума и превратили их в безумных лепрогномов, которые бездумно охраняют неисправные машины вместе со взбесившимися механизмами."},{t="Важный перекресток",b="Помимо прежней роли лаборатории, этот зал служит важным транспортным узлом в нижних частях разрушенного города. Проходы ведут к Пусковой установке, Двору Механиков и к черному ходу Входа в мастерскую. На нижнем этаже также находятся терминалы «Матричный перфограф 3005-D» — важные вычислительные блоки, необходимые для расшифровки перфокарт гномов-инженеров."}},faq={{q="Для чего первоначально использовались Инженерные лаборатории?",a="До падения города Инженерные лаборатории были отведены для исследований, сборки и испытаний сложных гномьих механизмов и автоматических устройств. Гномы-инженеры и техники использовали этот огромный двухъярусный зал для разработки чертежей новых технологий.",al={"purpose of engineering labs","what was made here","engineering labs lore","назначение инженерных лабораторий","что здесь делали","предания инженерных лабораторий"}},{q="Какие опасности бродят в Инженерных лабораториях теперь?",a="По обоим ярусам зала бродят облученные лепрогномы и взбесившиеся механические автоматы. Эти оставшиеся обитатели полностью обезумели от радиоактивного газа, выпущенного при падении города, и нападают на любых необлученных чужаков на месте.",al={"who is inside","enemies in engineering labs","monsters here","кто внутри","враги в инженерных лабораториях","монстры здесь"}},{q="Что такое машины «Матричный перфограф 3005-D»?",a="Эти автоматические гномьи терминалы данных находятся на нижнем уровне Инженерных лабораторий. С их помощью инженеры и искатели приключений пробивают закодированные карты данных, повышая уровень допуска и расшифровывая технические архивы, хранящиеся в городе.",al={"punchograph d","matrix punchograph 3005-d","yellow card machine","перфограф d","матричный перфограф 3005-d","машина желтых карт"}},{q="Как эта область связана с остальным Гномреганом?",a="Верхний ярус напрямую соединяется с черным ходом Входа в мастерскую и проходами к Пусковой установке. Нижний ярус ведет к главным коридорам, соединяющим Пусковую установку и Двор Механиков.",al={"where does this lead","engineering labs exits","routes to engineering labs","куда это ведет","выходы из инженерных лабораторий","путь к инженерным лабораториям"}}},fp="16,323,29.404.0,16.387.0,51.240.0,43.246.0,48.255.0,53.198.0"}
P.entries["subzone:ethel-rethor"] = {n="Этель-Ретор",s="Этель-Ретор — древние руины кальдораев на суровом северо-западном побережье Пустошей. Одинокая запечатанная башня все еще возвышается над волнами, а большая часть затонувшего поселения скрыта под водой и захвачена враждебными нагами.",h="Этель-Ретор — древние руины кальдораев на суровом северо-западном побережье Пустошей.",kw={"argent dawn","azore aldamor","desolace","desolace coast","ethel rethor","kaldorei ruins","naga","sunken ruins","серебряный рассвет","азор альдаморт","пустоши","побережье пустошей","этель-ретор","руины кальдораев","наги","затонувшие руины"},ang={["faction:Alliance"]="Путники Альянса, идущие по враждебным землям Пустошей, могут найти возле руин редкое нейтральное дружелюбное лицо — наблюдателя Серебряного Рассвета Азора Альдаморта.",["race:NightElf"]="Для ночных эльфов Этель-Ретор — мрачный памятник их утраченной империи, напоминающий о катастрофическом Расколе и об измененных собратьях, что теперь бродят по затонувшим залам."},sec={{t="Затонувшая реликвия",b="Этель-Ретор, расположенный на пустынном побережье западного Калимдора, — мрачное напоминание о древней цивилизации ночных эльфов, процветавшей до Великого Раскола. Большая часть величественных построек обрушилась в морские глубины, оставив лишь разбитые фундаменты и одинокую обветренную башню, торчащую из прибоя. К запечатанному порталу башни ведет небольшой мост, но сооружение остается наглухо закрытым и от стихий, и от незваных гостей. Затопленные залы и окрестные мели стали оплотом прибрежных нага, и воды здесь опасны для всякого, кто подойдет близко."},{t="Стражи на берегу",b="Несмотря на удаленность и змеиное нашествие, Этель-Ретор привлекает путников, интересующихся забытой историей Калимдора и его нынешними угрозами. Агент Серебряного Рассвета Азор Альдаморт неусыпно наблюдает за руинами, следит за угрозой нага и помогает отважным искателям приключений, готовым нырнуть в затонувшие проходы. Между морскими опасностями у берега и бесплодными пустошами вглубь суши эти руины служат одиноким прибрежным перекрестком."}},faq={{q="Что такое Этель-Ретор?",a="Этель-Ретор — разрушенное прибрежное поселение ночных эльфов на северо-западе Пустошей. Большая часть его построек теперь скрыта под водой, остались лишь одинокая башня в море и затонувшая каменная кладка.",al={"ethel rethor lore","what is this place desolace","ethel rethor ruin","предания этель-ретора","что это за место пустоши","руины этель-ретор"}},{q="Кто управляет Этель-Ретором теперь?",a="Затонувшие руины и соседние рифы заняты нагами. Как и многие древние места кальдораев на побережье, змееподобные создания присвоили затопленные залы и агрессивно патрулируют окрестные мели.",al={"who lives in ethel rethor","ethel rethor monsters","naga at ethel rethor","кто живет в этель-ретор","монстры этель-ретора","наги в этель-ретор"}},{q="Можно ли попасть внутрь башни?",a="К башне, поднимающейся из моря, ведет небольшой мост ко входу, но дверной проем остается наглухо запечатанным. Путники могут осмотреть лишь ее внешнюю часть и нырнуть в затонувшие руины под ней.",al={"open ethel rethor tower","ethel rethor door","inside ethel rethor","открыть башню этель-ретор","дверь этель-ретор","внутри этель-ретор"}},{q="Почему здесь находится Серебряный Рассвет?",a="Представитель Серебряного Рассвета Азор Альдаморт расположился возле руин. Хотя Рассвет в основном занят Плетью на востоке, его агенты по всему Калимдору следят за необычными магическими возмущениями, древними руинами и новыми угрозами, такими как наги.",al={"argent dawn in desolace","azore aldamor ethel rethor","argent dawn npc desolace","серебряный рассвет в пустошах","азор альдаморт этель-ретор","персонаж серебряного рассвета пустоши"}}},fp="12,258,15.616.0,21.466.0,21.210.0,30.219.0,28.204.0,28.258.0"}
P.entries["subzone:everlook"] = {n="Круговзор",s="Круговзор — заметенный снегом торговый форпост в центральных Зимних Ключах, основанный Картелем Хитрая Шестеренка. Расположенный на перекрестке путей снежной долины, он служит нейтральным убежищем для торговцев, старателей и исследователей, мужественно переносящих высокогорный холод.",h="Круговзор — заметенный снегом торговый форпост в центральных Зимних Ключах, основанный Картелем Хитрая...",kw={"everlook","goblin","gregor greystone","snow","steamwheedle cartel","trade outpost","winterspring","круговзор","гоблин","грегор грейстоун","снег","картель хитрая шестеренка","торговый форпост","зимние ключи"},ang={["profession:Engineering"]="Круговзор — крупный центр для инженеров высокого уровня, особенно специализирующихся на гоблинской инженерии: они могут научиться создавать пространственный проходчик, настроенный прямо на это поселение."},sec={{t="Торговля на краю света",b="Круговзор — самое северное предприятие Картеля Хитрая Шестеренка, подобное таким форпостам, как Прибамбасск и Пиратская бухта, но под покровом вечной мерзлоты. Поселение за стенами стоит на пересечении снежных заносов Зимних Ключей и строго соблюдает нейтралитет. Здесь находятся единственный в области действующий банк и общий аукцион, привлекающие и путников Альянса, и Орды в поисках тепла и крова. Город охраняют наемные громилы и защищают от свирепых ледяных саблезубов и йети."},{t="Шестеренки в тундре",b="Под обледенелыми деревянными крышами и причудливыми обоями с пингвинами Круговзор — рассадник технологического любопытства. Здесь есть специализированные инженерные мастерские и передовые алхимические лаборатории, где гоблины-механики раздвигают границы своего ремесла вдали от посторонних глаз. К заиндевевшим воротам стучится и внешняя дипломатия: Серебряный Рассвет недавно направил сюда Грегора Грейстоуна для прямых переговоров с руководством города, чтобы настороженно следить за древними руинами региона и растущими угрозами севера."}},faq={{q="Кто управляет Круговзором?",a="Круговзор принадлежит Картелю Хитрая Шестеренка и управляется им, а местное руководство заведует городом. Именно к ним Серебряный Рассвет направил Грегора Грейстоуна в качестве своего представителя.",al={"who runs everlook","everlook leader","who is in charge of everlook","кто управляет круговзором","глава круговзора","кто главный в круговзоре"}},{q="Почему Круговзор безопасен и для Альянса, и для Орды?",a="Картель Хитрая Шестеренка строго соблюдает торговый нейтралитет. Гоблины-громилы быстро расправляются с каждым, кто затеет насилие в стенах города, чтобы путники любых союзов могли спокойно торговать.",al={"is everlook neutral","can horde and alliance visit everlook","everlook pvp rules","нейтрален ли круговзор","могут ли орда и альянс посещать круговзор","правила pvp круговзора"}},{q="Почему Серебряный Рассвет находится в Круговзоре?",a="Серебряный Рассвет официально присутствует здесь через посланника Грегора Грейстоуна. Он представляет их перед гоблинами-торговцами, обеспечивает доступ к местным припасам и следит за местными угрозами.",al={"what is argent dawn doing here","gregor greystone everlook","argent dawn winterspring","что здесь делает серебряный рассвет","грегор грейстоун круговзор","серебряный рассвет зимние ключи"}},{q="Откуда в Круговзор поступают товары?",a="Круговзор расположен на перекрестке главных торговых путей Зимних Ключей, поэтому товары прибывают торговыми рейсами и наземными караванами по этим дорогам.",al={"everlook smuggling","winterspring trade goods","where do everlook goods come from","контрабанда круговзор","товары зимних ключей","откуда товары в круговзоре"}}},fp="8,266,33.520.0,19.526.0,22.176.0,49.214.0,35.205.0,40.145.0"}
P.entries["subzone:faldir-s-cove"] = {n="Бухта Фальдира",s="Бухта Фальдира — уединенная природная гавань на южном побережье Нагорья Арати. Она богата человеческой историей и считается местом, откуда ранние поселенцы отплыли на юг, чтобы основать Штормград. Сегодня она служит временным укрытием для застрявших Налетчиков Черноводья, чей флот столкнулся с местными опасностями.",h="Бухта Фальдира — уединенная природная гавань на южном побережье Нагорья Арати.",kw={"blackwater raiders","captain o'breen","captain steelgut","draxlegauge","drowned reef","faldir","faldir's cove","harbinger","phizzlethorpe","налетчики черноводья","капитан о'брин","капитан стальное брюхо","дракслгейдж","подводный риф","фальдир","бухта фальдира","предвестник","физзлторп"},ang={["race:Gnome"]="В лагере находятся доктор Дракслгейдж и профессор Физзлторп, применившие изобретательные инженерные устройства для анализа и добычи эльфийских самоцветов из окаменевших прибрежных рифов.",["race:Human"]="Стоя на этих берегах, люди ощущают связь со своим древним наследием: это историческое место, откуда предки жителей Штормграда отплыли от древней Араторской империи."},sec={{t="Врата на юг и пиратское убежище",b="Бухта Фальдира, скрытая за суровыми утесами к югу от Крепости Стромгард, соединена с сушей потайным пещерным туннелем. Бухта чтит память Фальдира, древнего исследователя из Аратора, чья экспедиция отплыла от этих берегов, чтобы пересечь Великое море и основать южное королевство Штормград. Однако сегодня в ее тихих водах обитает совсем иная публика: экспедиция Налетчиков Черноводья из Пиратской бухты под началом капитанов Стальное Брюхо и О'Брина отправилась на север за древними эльфийскими сокровищами, но оказалась в ловушке в этой бухте."},{t="Крушение флота Черноводья",b="Предприятие Черноводья обернулось катастрофой по прибытии к берегам Арати. Странные неестественные приливы, вызванные территориальными нагами с Подводного рифа у берега, разбили два из трех кораблей. Лишь «Предвестник» уцелел и, хромая, добрался до Бухты Фальдира. Нага бродят по водам, а навигационные карты лежат на дне, и выжившие пираты вместе с гномами-исследователями оказались на мели: им остается рассчитывать на нейтральных путников, которые сразятся с морскими чудищами и поднимут затонувший груз."}},faq={{q="Кто такой Фальдир?",a="Фальдир был древним первопроходцем из ранней человеческой Араторской империи. Он и его последователи отплыли из этой прибрежной гавани через море на юг, чтобы основать поселения, которые со временем стали королевством Штормград.",al={"faldir lore","who is faldir","faldir founder","предания о фальдире","кто такой фальдир","фальдир основатель"}},{q="Как добраться до Бухты Фальдира?",a="В бухту можно попасть, найдя потайной туннель к юго-востоку от внешних южных стен Крепости Стромгард. Пройдя по этому подземному туннелю, путники выходят прямо на уединенный берег.",al={"how to get to faldir's cove","faldir cove entrance","cave to faldirs cove","как попасть в бухту фальдира","вход в бухту фальдира","пещера к бухте фальдира"}},{q="Почему здесь Налетчики Черноводья?",a="Капитан Стальное Брюхо и капитан О'Брин возглавили экспедицию на север из Пиратской бухты на поиски затонувших эльфийских сокровищ. Вместе с гномами-изобретателями, создавшими устройства для обнаружения самоцветов, они стремились поднять драгоценные реликвии, окаменевшие в рифах у берега.",al={"why are pirates here","blackwater raiders arathi","what are the pirates doing","почему здесь пираты","налетчики черноводья арати","что делают пираты"}},{q="Что случилось с их кораблями?",a="Два из трех кораблей экспедиции были уничтожены неестественными приливами, поднятыми враждебными нагами, обитающими на Подводном рифе. Лишь флагман «Предвестник» благополучно вошел в порт бухты, оставив команду на мели без затонувших карт.",al={"why are ships wrecked","sunken ships arathi","who sank the ships","почему разбились корабли","затонувшие корабли арати","кто потопил корабли"}}},fp="13,356,34.569.0,33.529.0,15.243.0,31.221.0,36.256.0,29.240.0"}
P.entries["subzone:falfarren-river"] = {n="Река Фалфаррен",s="Река Фалфаррен течет с северо-востока на юго-запад через сердце Ясеневого леса. Она берет начало на склонах горы Хиджал и уходит под землю у северных гор Степей. Река образует естественную границу между владениями кальдораев вокруг Астранаара на западе и наступающими аванпостами Орды на востоке. Путникам следует быть осторожными: тенистые берега и мелководье таят опасных животных и отмечают край открытого конфликта.",h="Река Фалфаррен течет с северо-востока на юго-запад через сердце Ясеневого леса.",kw={"ashenvale river","astranaar","falfarren","falfarren river","felfire hill","splintertree","xavian","река ясеневого леса","астранаар","фалфаррен","река фалфаррен","холм демонического огня","расщепленное дерево","ксавиан"},ang={["faction:Alliance"]="Для ночных эльфов и их союзников переход через Фалфаррен на восток означает шаг прямо на передовую Орды у Заставы Расщепленного Дерева.",["faction:Horde"]="Фалфаррен отмечает западный предел расширения Орды от Заставы Расщепленного Дерева, за которым лежат укрепленные земли ночных эльфов."},sec={{t="Спорная естественная граница",b="Воды Фалфаррена стекают с горы Хиджал, каскадами водопадов спускаются в Ксавиан, а затем вьются между Заставой Расщепленного Дерева и Ночной поляной. Река не очень глубока и в обычную погоду проходима, но служит примерной геополитической границей в центральной части Ясеневого леса. К западу лежат Астранаар и основные владения кальдораев, к востоку — лагеря и лесозаготовки Орды. Переход по деревянным мостам главной дороги ведет путников в спорное сердце леса, где на берегах сталкиваются патрули."},{t="Опасности на мелководье",b="Помимо напряженности между враждующими стражами и грантами, река скрывает под поверхностью естественные и неестественные опасности. Ниже по течению, у Холма Демонического Огня, по илистому мелководью бродят оскверненные болотные звери и агрессивные водные твари. Дожди могут усилить течение, но настоящая угроза таится в густых кронах по обоим берегам, где засады и стычки постоянно перекидываются на реку."}},faq={{q="Где начинается и где заканчивается Река Фалфаррен?",a="Река Фалфаррен берет начало на высотах горы Хиджал и водопадами спускается в озеро у Ксавиана. Оттуда она вьется на юго-запад через Ясеневый лес и уходит в подземные русла под северными горами Степей.",al={"falfarren river source","where does the river go","исток фалфаррена","куда течет река"}},{q="Чем Река Фалфаррен важна для войны в Ясеневом лесу?",a="Она служит примерной границей между землями ночных эльфов и Орды в центральной части Ясеневого леса. Территория ночных эльфов с центром в Астранааре лежит на западе, а орочья Застава Расщепленного Дерева и действующие лесозаготовки Орды — на востоке.",al={"why is falfarren river important","river border ashenvale","почему важна река фалфаррен","граница реки ясеневый лес"}},{q="Каких угроз путникам ждать на берегах реки?",a="На мелководье бродят агрессивные болотные звери, особенно близ оскверненных земель вокруг Холма Демонического Огня. Кроме того, патрули Альянса и Орды следят за мостами и переправами, поэтому безлюдные берега реки — излюбленное место стычек и засад.",al={"monsters in falfarren river","dangers at falfarren","монстры в фалфаррене","опасности фалфаррена"}}},fp="15,448,28.563.0,23.395.0,45.261.0,63.255.0,58.267.0"}
P.entries["subzone:fallen-sky-lake"] = {n="Зеркало Небес",kw={"ashenvale","fallen sky lake","oracle","shadethicket","silverwing outpost","warsong labor camp","wildkin","ясеневый лес","зеркало небес","оракул","чащобные совуны","аванпост среброкрылых","рабочий лагерь песни войны","совуны"},ang={["class:Druid"]="Лунные звери — традиционно священные создания, отмеченные милостью Элуны, поэтому порченые, агрессивные чащобные, заполонившие Зеркало Небес, выглядят тревожно.",["race:NightElf"]="Озеро к югу от Аванпоста Среброкрылых — еще один уголок священного древнего леса, где дикие звери обезумели под нарастающий бой барабанов Орды."},sec={{t="Спорное пристанище",b="Зеркало Небес лежит к югу от Аванпоста Среброкрылых и чуть западнее Рабочего лагеря Песни Войны. Оно дарит мимолетный взгляд на природное великолепие Ясеневого леса, каким оно было до появления орочьих топоров. Берега и небольшой остров посреди озера населяют чащобные совуны — оскверненные или охраняющие свои земли лесные существа, видящие угрозу в любом двуногом чужаке. В центре острова обитает могучий чащобный оракул, чье присутствие удерживает местных лесных существ при роще и неустанно настороженными к проходящим путникам."}},faq={{q="Где находится Зеркало Небес?",a="Зеркало Небес находится в восточной части Ясеневого леса: прямо к югу от Аванпоста Среброкрылых, к западу от Рабочего лагеря Песни Войны и к северо-востоку от Рощи Среброкрылых.",al={"fallen sky lake location","where is fallen sky lake","how to find fallen sky lake","где зеркало небес","расположение зеркала небес","как найти зеркало небес"}},{q="Какие существа живут у Зеркала Небес?",a="Озеро и его берега заполонили чащобные совуны — агрессивные лесные существа, которыми правит грозный чащобный оракул, обитающий на центральном острове.",al={"mobs at fallen sky lake","what is at fallen sky lake","fallen sky lake enemies","мобы у зеркала небес","что у зеркала небес","враги зеркала небес"}},{q="Чем важен чащобный оракул?",a="Чащобный оракул — предводительница местных лесных существ, собравшихся у озера. Путникам и разведчикам Ясеневого леса часто поручают выследить ее на центральном острове, чтобы устранить угрозу со стороны враждебных лесных существ.",al={"oracle at fallen sky lake","shadethicket oracle","who is on the island","оракул у зеркала небес","чащобный оракул","кто на острове"}}},fp="15,303,21.568.0,33.153.0,43.170.0,41.228.0"}
P.entries["subzone:faol-s-rest"] = {n="Могила Фаола",s="Могила Фаола — тихое заброшенное место захоронения в восточной части Тирисфальских лесов, к юго-западу от Монастыря Алого ордена. Она была воздвигнута как усыпальница архиепископа Алонсуса Фаола, почитаемого духовного главы, основавшего Рыцарей Серебряной Длани. Сегодня, лишенная ухода под гнилым пологом, она служит кладбищем для тех, кто погиб рядом с монастырем.",h="Могила Фаола — тихое заброшенное место захоронения в восточной части Тирисфальских лесов, к юго-западу от...",kw={"alonsus faol","church of the holy light","faol's rest","graveyard","scarlet monastery","silver hand","tirisfal glades","алонсус фаол","церковь священного света","могила фаола","кладбище","монастырь алого ордена","серебряная длань","тирисфальские леса"},ang={["class:Paladin"]="Каждый паладин обязан своим призванием архиепископу Фаолу, который первым собрал Утера и его соратников, чтобы объединить воинское искусство со Светом. Стоять перед его неухоженной гробницей — отрезвляющее напоминание о начале ордена.",["class:Priest"]="Будучи верховным главой Церкви Священного Света в годы Второй войны, Фаол был пастырем всех священников Лордерона; разрушенный памятник отражает трагический упадок церкви на севере."},sec={{t="Усыпальница архиепископа",b="До того как Третья война опустошила Лордерон, эта укромная лощина была местом торжественного паломничества. Здесь находится каменная гробница архиепископа Алонсуса Фаола, который вел Церковь Священного Света через темные дни Второй войны и учредил орден паладинов для защиты человечества. Фаол мирно скончался до прихода Плети и был избавлен от смертной муки видеть падение своего королевства. В те светлые годы скорбящие регулярно приходили по дороге из Столицы, чтобы оставить дары и почтить любимого патриарха."},{t="Запустение в тени монастыря",b="Когда Чума нежизни прокатилась по Лордерону, Тирисфаль зачах, а паломники исчезли. Сегодня памятник стоит заброшенным и растрескавшимся в тени высоких утесов Монастыря Алого ордена. Дикий кустарник отвоевал тропы, а сама гробница замерла среди сырого тумана. Для искателей приключений, сражающихся с фанатиками Алого ордена или с остаточными ужасами Тирисфаля, это забытое место упокоения теперь служит в основном тихим порогом, где павшие души ненадолго собираются с силами перед возвращением в бой."}},faq={{q="Кто такой Алонсус Фаол?",a="Алонсус Фаол был архиепископом Церкви Священного Света во время Второй войны. Почитаемый за мудрость и сострадание, он организовал помощь беженцам и основал Рыцарей Серебряной Длани, превратив священников и благочестивых рыцарей в первых паладинов человечества, среди которых были Утер Светоносный и Туралион.",al={"who is faol","alonsus faol lore","who is buried here","кто такой фаол","предания об алонсусе фаоле","кто здесь похоронен"}},{q="Почему этот памятник находится рядом с Монастырем Алого ордена?",a="Земли рядом с Монастырем Алого ордена исторически были важными религиозными владениями Церкви Священного Света на севере Лордерона. Фаола похоронили в этом тихом уголке Тирисфальских лесов до падения королевства, задолго до того, как облаченные в алое фанатики укрепили соседний монастырь.",al={"why near monastery","scarlet monastery connection","location meaning","почему рядом с монастырем","связь с монастырем алого ордена","значение места"}},{q="Ухаживает ли кто-нибудь за гробницей сегодня?",a="Нет. Со времен падения Лордерона под натиском Плети место совершенно заброшено. Алый орден редко спускается в лощину, чтобы ухаживать за ним, а Отрекшиеся мало заинтересованы в почитании святынь старой церкви, поэтому каменные знаки обветшали и заросли.",al={"who tends faol's rest","is it abandoned","tomb upkeep","кто ухаживает за могилой фаола","заброшена ли она","уход за гробницей"}},{q="Какую практическую пользу Могила Фаола приносит путникам?",a="Могила Фаола служит местным кладбищем для духов окрестных земель и Монастыря Алого ордена. Искатели приключений, погибшие при попытке прорваться в монастырь или при переходе через восточные Тирисфальские леса, возвращаются духами к тихому памятнику архиепископа.",al={"graveyard run","what is this place in game","monastery graveyard","бег с кладбища","что это за место в игре","кладбище монастыря"}}},fp="11,371,22.547.0,41.541.0,21.325.0,56.301.0,37.280.0,60.263.0"}
P.entries["subzone:far-watch-post"] = {n="Дальняя застава",s="Дальняя застава — укрепленный аванпост Орды к западу от моста через Реку Строптивую, соединяющего Дуротар со Степями. Как передовая линия обороны орочьей родины, застава охраняет важные торговые караваны от агрессивных стай свинобразов и враждебных вторжений Альянса.",h="Дальняя застава — укрепленный аванпост Орды к западу от моста через Реку Строптивую, соединяющего Дуротар со...",kw={"barrens","burrow","durotar","far watch post","peons","quilboar","southfury river","watchtower","wolves","степи","нора","дуротар","дальняя застава","пеоны","свинобразы","река строптивая","сторожевая башня","волки"},ang={["faction:Alliance"]="Расположенная прямо напротив моста из Дуротара, Дальняя застава служит грозным заслоном, не дающим разведотрядам и диверсантам легко подобраться к орочьей столице.",["faction:Horde"]="Для молодых воинов, впервые покидающих Дуротар, Дальняя застава — последний аванпост знакомых земель перед путешествием в суровое, опасное сердце Калимдора."},sec={{t="Страж границы",b="Дальняя застава расположена у западного подножия моста из Дуротара и служит первым оплотом власти Орды для путников, входящих в обширную засушливую саванну Степей. Поселение спартанское, но функциональное: оно построено для боевой готовности, а не для удобства. Здесь есть крепкая орочья сторожевая башня, нора и заранее пристрелянные осадные катапульты, нацеленные на пыльные равнины. К югу от главной дороги пеоны присматривают за загоном верховых волков, готовых нести гонцов или подкрепление. Дальняя застава существует прежде всего для защиты снабженческой дороги к Перекрестку: она проверяет проезжающих и отражает набеги бродячих племен свинобразов и скрытных разведчиков Альянса."}},faq={{q="Для чего нужна Дальняя застава?",a="Застава служит главным пограничным постом между Дуротаром и Степями. Ее защитники охраняют важные караваны снабжения Орды и следят, чтобы местные опасности, прежде всего агрессивные племена свинобразов и нарушители из Альянса, не пересекли Реку Строптивую и не попали в Дуротар.",al={"why is far watch post here","purpose of far watch","far watch outpost role","зачем здесь дальняя застава","назначение дальней заставы","роль дальней заставы"}},{q="Кто контролирует этот аванпост?",a="Дальняя застава — действующий военный лагерь Орды. Орочьи грунты несут гарнизонную службу на башне и обслуживают осадные орудия, а пеоны присматривают за верховыми волками.",al={"who runs far watch post","far watch post faction","кто управляет дальней заставой","фракция дальней заставы"}},{q="Какие угрозы грозят аванпосту?",a="Застава часто подвергается налетам соседних стай свинобразов, оспаривающих окрестные колючие заросли. Она также стоит на страже от вторжений Альянса, которые могут попытаться ударить через Степи к Оргриммару.",al={"far watch post enemies","dangers at far watch","враги дальней заставы","опасности дальней заставы"}}},fp="14,293,22.683.0,38.265.0,26.175.0,35.233.0"}
P.entries["subzone:fargodeep-mine"] = {n="Рудник Подземных Глубин",s="Рудник Подземных Глубин — заброшенный золотой рудник в центральной части Элвиннского леса, к югу от Златоземья. Когда-то он был богатым источником дохода для Королевства Штормград, но недавно его захватил воинственный клан кобольдов.",h="Рудник Подземных Глубин — заброшенный золотой рудник в центральной части Элвиннского леса, к югу от...",ang={["faction:Alliance"]="Очистка Рудника Подземных Глубин от вредителей жизненно важна для защиты путей снабжения и земель, окружающих Златоземье.",["profession:Mining"]="Хотя туннели Подземных Глубин кишат вредителями, в них остается много доступных медных жил для начинающих шахтеров."},sec={{t="Утраченная жила",b="Рудник Подземных Глубин когда-то стабильно поставлял золото в казну Штормграда, но сокращение военного присутствия Королевства в Элвиннском лесу оставило дальние ресурсы без защиты. Кобольды быстро заполонили темные туннели и устроили под холмами шумное логово. Маршал Дугхан и местные власти Златоземья относятся к нашествию с большой тревогой: дело не только в потерянной руде, но и в том, что осмелевшие твари теперь угрожают соседним фермам — владениям Стоунфилд и Маклюр."},{t="Глубины логова",b="The mine spans multiple levels, with the lower shafts winding deep beneath the forest floor. Kobold laborers and vermin scurry along the wooden scaffolds, fiercely guarding their scavenged wax and gold dust. Deeper within lurks Goldtooth, a particularly cunning kobold leader known for hoarding trinkets pilfered from unwary travelers and surrounding residents."}},faq={{q="Почему Штормград оставил Рудник Подземных Глубин?",a="Рудник был заброшен, так как военные силы Штормграда оказались растянуты по южным землям. Городская стража была занята защитой Златоземья и главных дорог, и подземные выработки остались без охраны, а кобольды смогли туда вселиться и укрепить туннели.",al={"why abandoned","why did humans leave fargodeep","who owned fargodeep mine","почему заброшен","почему люди покинули рудник подземных глубин","кому принадлежал рудник подземных глубин"}},{q="Чем кобольды так опасны для местных фермеров?",a="Рудник Подземных Глубин находится прямо между фермами семей Стоунфилд и Маклюр. Кобольды выбираются из туннелей, чтобы красть скот, инструменты и личные вещи, и донимают всех, кто бродит у входа в рудник.",al={"why are kobolds a problem","kobold threat","stonefield kobolds","почему кобольды проблема","угроза кобольдов","кобольды стоунфилда"}},{q="Who is Goldtooth?",a="Goldtooth is a prominent kobold who nests deep within the lower shafts of Fargodeep Mine. He is notorious for snatching Auntie Bernice Stonefield's prized family necklace.",al={"goldtooth","who is goldtooth","goldtooth location"}},{q="Зачем жителям Златоземья предметы из рудника?",a="Местные торговцы и горожане видят выгоду в уничтожении вредителей: Реми Повторюх скупает добытую золотую пыль, алхимик Вильям Пест использует воск кобольдов для реагентов, а маршалу Дугхану нужно, чтобы нашествие находилось под наблюдением ради безопасности Элвиннского леса.",al={"fargodeep quests","why gather candles","gold dust","задания рудника подземных глубин","зачем собирать свечи","золотая пыль"}}},fp="14,222,11.492.0,20.361.0,41.252.0,55.222.0,17.171.0,52.251.0"}
P.entries["subzone:feathermoon-stronghold"] = {n="Крепость Оперенной Луны",s="Крепость Оперенной Луны — главная военная база ночных эльфов на юге Калимдора, надежно расположенная на острове Сардор у Забытого берега Фераласа. Этим укрепленным форпостом командует генерал Шандриса Оперенная Луна; он проецирует силу Часовых на дикий лес и следит за региональными угрозами.",h="Крепость Оперенной Луны — главная военная база ночных эльфов на юге Калимдора, надежно расположенная на...",kw={"feathermoon","feathermoon stronghold","feralas","forgotten coast","kaldorei","moonwell","sardor isle","sentinels","shandris feathermoon","оперенная луна","крепость оперенной луны","фералас","забытый берег","кальдораи","лунный колодец","остров сардор","часовые","шандрис оперенная луна"},ang={["faction:Alliance"]="Для воинов Альянса, отважившихся на юг Калимдора, Крепость Оперенной Луны дает жизненно важные припасы, маршруты полета и штаб заданий среди враждебной глуши Фераласа.",["race:NightElf"]="Как главный лагерь Часовых к югу от Ясеневого леса, эта крепость воплощает решимость кальдораев защищать Калимдор под руководством генерала Шандрисы Оперенной Луны."},sec={{t="Оплот Часовых на юге",b="Крепость Оперенной Луны, расположенная на острове Сардор через пролив от материковой части Фераласа, служит главной стратегической базой Часовых на юге Калимдора. Построенная среди древних эльфийских рощ и обладающая священным лунным колодцем, крепость вмещает лучников, охотниц и вспомогательный персонал под прямым руководством генерала Шандрисы Оперенной Луны. Из этого островного убежища ночные эльфы распространяют свое влияние на цветущую глубь Фераласа, защищаясь от демонической порчи, враждебных зверей и вторжений Орды."},{t="Безопасное убежище в глуши",b="Поскольку материк Фераласа кишит свирепыми зверями, ограми Гордунни и оскверненными тенями Забытого Города, остров Сардор служит важным оборонительным буфером. Путники из Альянса пользуются паромом с Забытого берега, чтобы добраться до укрепленных причалов, починить снаряжение и собрать сведения. Присутствие Шандрисы Оперенной Луны — приемной дочери верховной жрицы Тиранды Шелест Ветра и ветерана Третьей войны — делает крепость неприступным оплотом против всех врагов кальдораев."}},faq={{q="Где находится Крепость Оперенной Луны?",a="Крепость Оперенной Луны стоит на острове Сардор, лежащем у Забытого берега на западной окраине Фераласа. Путникам нужно пройти на запад через лес к побережью и переправиться на лодке, чтобы добраться до островной крепости.",al={"feathermoon location","where is feathermoon","how to get to feathermoon stronghold","где находится оперенная луна","где крепость оперенной луны","как добраться до крепости оперенной луны"}},{q="Кто командует Крепостью Оперенной Луны?",a="Крепостью командует генерал Шандриса Оперенная Луна, верховный командующий армией Часовых и приемная дочь верховной жрицы Тиранды Шелест Ветра. Из этого форпоста она руководит всеми военными действиями кальдораев на юге Калимдора.",al={"who leads feathermoon","feathermoon leader","shandris feathermoon base","кто командует оперенной луной","лидер оперенной луны","шандрис оперенная луна база"}},{q="Почему крепость расположена на острове, а не на материке?",a="Остров Сардор предлагает естественную морскую защиту от множества опасностей материкового Фераласа, где полно свирепых зверей, огров Гордунни и остаточных тайных и демонических угроз. Размещение крепости на острове дает безопасный порт, контролирующий прибрежные воды, и удерживает материковые угрозы на расстоянии.",al={"why sardor isle","why is feathermoon on an island","почему остров сардор","почему оперенная луна на острове"}},{q="Есть ли в Крепости Оперенной Луны лунный колодец?",a="Да, в Крепости Оперенной Луны есть священный лунный колодец. Он дает духовную опору, силы и святую воду гарнизону ночных эльфов, расквартированному далеко от родины на севере.",al={"feathermoon moonwell","is there a moonwell at feathermoon","лунный колодец оперенной луны","есть ли лунный колодец в оперенной луне"}}},fp="22,307,29.554.0,25.535.0,40.242.0,36.250.0,67.310.0,44.218.0"}
P.entries["subzone:feathermoon-stronghold-classic"] = {n="Крепость Оперенной Луны (Classic)",s="Крепость Оперенной Луны — укрепленный оплот ночных эльфов на острове Сардор у западных берегов Фераласа. Основанная генералом Шандрисой Оперенной Луной, она служит главным плацдармом и военной опорой Альянса на юге Калимдора.",h="Крепость Оперенной Луны — укрепленный оплот ночных эльфов на острове Сардор у западных берегов Фераласа.",kw={"alliance","feathermoon stronghold","feralas","forgotten coast","sardor isle","sentinels","shandris feathermoon","альянс","крепость оперенной луны","фералас","забытый берег","остров сардор","часовые","шандрис оперенная луна"},ang={["faction:Alliance"]="Крепость Оперенной Луны — главное безопасное убежище, торговый пост и плацдарм операций Альянса в глубине юга Калимдора.",["race:NightElf"]="Крепость служит южной военной резиденцией генерала Шандрисы Оперенной Луны и Часовых и является важным стражем древней глуши."},sec={{t="Оплот Часовых на юге",b="Крепость Оперенной Луны, расположенная на острове Сардор недалеко от Забытого берега, — важный оплот ночных эльфов и всего Альянса. Построенная под руководством генерала Шандрисы Оперенной Луны, десять тысячелетий верной помощницы Тиранды Шелест Ветра, она проецирует мощь Часовых вглубь юга Калимдора. Уединенное островное положение защищает ее от зверей, огров и вторженцев из Орды, рыщущих в первобытных джунглях материкового Фераласа."},{t="Спасательная нить через волны",b="Из-за островного положения Крепость Оперенной Луны во многом зависит от морского и воздушного сообщения. Небольшая пассажирская лодка регулярно возит путников через пролив между островом Сардор и причалом на Забытом берегу. Для дальних поездок есть специальный насест гиппогрифов, связывающий крепость с главными центрами Альянса, включая Таланаар на границе Тысячи Игл, Высоту Найджела на нагорьях Пустошей и Аубердин на севере."}},faq={{q="Как добраться до Крепости Оперенной Луны с материка Фераласа?",a="Путники могут сесть на паром, отходящий от причала на Забытом берегу прямо через пролив, или просто переплыть узкий пролив до острова Сардор. Члены Альянса также могут долететь на гиппогрифе, найдя распорядителя полетов.",al={"how to get to feathermoon","feathermoon boat","getting to sardor isle","как добраться до оперенной луны","лодка в оперенную луну","как попасть на остров сардор"}},{q="Кто командует Крепостью Оперенной Луны?",a="Форпостом командует генерал Шандриса Оперенная Луна, высокопоставленный предводитель Часовых и давняя военная подчиненная верховной жрицы Тиранды Шелест Ветра.",al={"who leads feathermoon","feathermoon leader","shandris feathermoon","кто командует оперенной луной","лидер оперенной луны","шандрис оперенная луна"}},{q="Почему крепость расположена на острове, а не на материке?",a="Остров Сардор обеспечивает естественную изоляцию и защиту от многочисленных угроз глуши Фераласа, включая агрессивных зверей, первобытные руины и враждебные силы, позволяя Часовым удерживать неприступный оплот.",al={"why on sardor isle","why island fortress","feathermoon location lore","почему на острове сардор","почему островная крепость","расположение оперенной луны предания"}},{q="Куда ведут маршруты полета из Крепости Оперенной Луны?",a="Распорядитель полетов на гиппогрифах в Крепости Оперенной Луны поддерживает маршруты по западному Калимдору, включая Аубердин в Темных берегах, Высоту Найджела в Пустошах, Таланаар в Фераласе и Крепость Кенария в Силитусе.",al={"feathermoon flight master","where do feathermoon hippogryphs go","распорядитель полетов оперенной луны","куда летают гиппогрифы оперенной луны"}}},fp="32,252,29.474.0,25.443.0,62.243.0,36.175.0,67.226.0,47.198.0"}
P.entries["subzone:fel-rock"] = {n="Пещера Бесов",s="Пещера Бесов — оскверненная пещера, скрытая в лесу к северу от Доланаара, на ветвях Тельдрассила. Некогда тихая лощина, она пала жертвой порчи под влиянием сатира лорда Меленаса и его орды злобных греллов.",h="Пещера Бесов — оскверненная пещера, скрытая в лесу к северу от Доланаара, на ветвях Тельдрассила.",kw={"dolanaar","fel rock","grell","lord melenas","satyr","tallonkai swiftroot","teldrassil","доланаар","пещера бесов","грелл","лорд меленас","сатир","таллонкай гибкий корень","тельдрассил"},ang={["class:Druid"]="Друиды Круга Кенария видят в Пещере Бесов гноящуюся рану на юном мировом древе, которую нужно немедленно очистить, пока демоническая порча не распространилась.",["race:NightElf"]="Для кальдораев присутствие такого сатира, как лорд Меленас, так близко к Доланаару — тревожное оскорбление Тельдрассила, требующее скорого возмездия."},sec={{t="Обитель порчи",b="Пещера Бесов, спрятанная в лесистых холмах к северу от Доланаара, когда-то была обычной мирной пещерой, высеченной в дереве и камне Тельдрассила. Сегодня она служит тревожным напоминанием о ползучей скверне, подступающей к мировому древу. Внутри пещеры царят искривленные корни и неестественные тени, а ее наводняют стаи диких греллов и грелликинов."},{t="Оплот сатира",b="Порча в Пещере Бесов исходит от лорда Меленаса, злобного сатира, превратившего лощину в свой оплот. Из глубины пещеры он распространяет губительную скверну прямо под бдительным взором часовых ночных эльфов. Друиды из Доланаара, в особенности Таллонкай Гибкий Корень, набирают способных защитников, чтобы очистить пещеру и убить Меленаса, пока его мерзкая порча не распространилась дальше по окрестным лесам."}},faq={{q="Где находится Пещера Бесов?",a="Пещера Бесов находится в центральной части Тельдрассила, среди холмов прямо к северу от поселения Доланаар.",al={"fel rock location","where is fel rock","find fel rock","пещера бесов где находится","где пещера бесов","найти пещеру бесов"}},{q="Кто правит Пещерой Бесов?",a="Пещерой повелевает лорд Меленас, мерзкий сатир, сделавший Пещеру Бесов своим логовом и собравший множество греллов, исполняющих его волю.",al={"who is in fel rock","boss of fel rock","lord melenas location","кто в пещере бесов","босс пещеры бесов","где лорд меленас"}},{q="Почему друиды обеспокоены Пещерой Бесов?",a="Присутствие сатира и оскверненных греллов на ветвях мирового древа — непосредственная угроза природному равновесию Тельдрассила. Друиды, такие как Таллонкай Гибкий Корень, посылают искателей приключений убить лорда Меленаса и остановить порчу.",al={"why clean fel rock","fel rock quest","tallonkai swiftroot quest","зачем очищать пещеру бесов","задание пещера бесов","задание таллонкай гибкий корень"}},{q="Какие существа обитают в пещере?",a="В Пещере Бесов вы встретите агрессивных греллов, грелликинов и их темного хозяина — сатира лорда Меленаса.",al={"fel rock mobs","what is inside fel rock","fel rock enemies","монстры пещеры бесов","что внутри пещеры бесов","враги пещеры бесов"}}},fp="8,238,19.354.0,16.468.0,26.110.0,19.133.0,40.244.0,39.111.0"}
P.entries["subzone:felfire-hill"] = {n="Холм Демонического Огня",s="Холм Демонического Огня — оскверненная, кишащая демонами возвышенность в восточной части Ясеневого леса. Земля, пораженная падающими инферналами во время Третьей войны, до сих пор горит демонической силой. Орда держит укрепленные сторожевые посты на мостах, ведущих к холму, защищая свои ближние поселения.",h="Холм Демонического Огня — оскверненная, кишащая демонами возвышенность в восточной части Ясеневого леса.",kw={"ashenvale","burning legion","demons","felfire hill","infernals","splintertree post","warsong lumber camp","ясеневый лес","пылающий легион","демоны","холм демонического огня","инферналы","застава расщепленного дерева","лесозаготовки песни войны"},ang={["class:Warlock"]="Необузданная энергия скверны, оставшаяся там, где приземлились инферналы Легиона, делает этот израненный хребет объектом опасного любопытства для приверженцев темной магии.",["faction:Horde"]="Орда удерживает укрепленные мосты вокруг Холма Демонического Огня, чтобы защитить дорогу между Заставой Расщепленного Дерева и Лесозаготовками Песни Войны от демонических налетов."},sec={{t="Шрам Пылающего Легиона",b="Во время катастрофического вторжения Третьей войны над Калимдором падали пылающие метеоры: Пылающий Легион обрушил своих грозных инферналов. Несколько таких огненных исполинов ударили в этот хребет в Ясеневом лесу, выжгли древние леса и осквернили саму землю. Сегодня опаленный ландшафт по-прежнему пропитан энергией скверны, а по нему бродят демоны, пережившие поражение Легиона на горе Хиджал."},{t="Охрана переправ",b="Холм Демонического Огня расположен к юго-востоку от Заставы Расщепленного Дерева и к юго-западу от Лесозаготовок Песни Войны, неуютно близко к важным объектам Орды. Поскольку остатки демонов грозят вырваться в окрестный лес, силы Орды возвели укрепленные заграждения и сторожевые башни у обоих мостов к холму, удерживая мерзких тварей в их оскверненном убежище."}},faq={{q="Почему Холм Демонического Огня осквернен?",a="Во время Третьей войны инферналы Пылающего Легиона градом упали с неба на этот холм. Удар и последовавшее заражение скверной выжгли нетронутый эльфийский лес, оставив обожженный камень и демоническую энергию, которая так и не рассеялась.",al={"why is felfire hill green","felfire hill lore","what happened to felfire hill","почему холм демонического огня зеленый","история холма демонического огня","что случилось с холмом демонического огня"}},{q="Какие существа живут на Холме Демонического Огня?",a="Холм занимают уцелевшие демоны и инфернальные создания, оставшиеся после вторжения Легиона во время Третьей войны. Они враждебны ко всем смертным, забредающим к их оскверненным границам.",al={"monsters at felfire hill","felfire hill mobs","монстры холма демонического огня","мобы холма демонического огня"}},{q="Почему Орда укрепила здешние мосты?",a="Холм Демонического Огня лежит прямо между Заставой Расщепленного Дерева и Лесозаготовками Песни Войны. Командиры Орды укрепили оба моста, чтобы бродящие демоны не вырвались и не захватили соседние лагеря, обозы снабжения и лесозаготовки.",al={"horde bridge guards felfire","why are orcs guarding felfire hill","стража орды на мостах","почему орки охраняют холм демонического огня"}},{q="Связан ли Холм Демонического Огня с ночными эльфами?",a="Хотя сам холм когда-то был частью священной чащи Ясеневого леса, теперь он зловеще возвышается к северо-востоку от Обители Дор'Данил. Ползущая демоническая скверна и бродящие злодеи — постоянная опасность для близлежащих мест упокоения и окрестных земель.",al={"dor danil felfire hill","barrow den demons","дор'данил холм демонического огня","демоны обители"}}},fp="12,296,28.418.0,22.387.0,30.264.0,36.201.0,43.238.0,45.262.0"}
P.entries["subzone:felpaw-village"] = {n="Деревня Сквернолапов",s="Деревня Сквернолапов — оскверненное поселение фурболгов на дальнем севере Оскверненного леса, охраняющее горную тропу, ведущую прямо к Крепости Древобрюхов. Ее населяет павшее племя Мертвого Леса; хижины и места сборищ отравлены демоническим влиянием и враждебны ко всем чужакам.",h="Деревня Сквернолапов — оскверненное поселение фурболгов на дальнем севере Оскверненного леса, охраняющее...",kw={"corruption","deadwood","felpaw","felpaw village","felwood","furbolg","timbermaw","порча","мертвый лес","сквернолапы","деревня сквернолапов","оскверненный лес","фурболг","древобрюх"},ang={["class:Druid"]="Для друидов, стремящихся восстановить естественный порядок, павшие фурболги Мертвого Леса в Деревне Сквернолапов — трагическое напоминание о неугасающем яде Легиона в священных лесах.",["race:NightElf"]="Ночные эльфы когда-то считали фурболгов верными союзниками, поэтому вид безумия Мертвого Леса и ритуального падения в Сквернолапах особенно горек."},sec={{t="Оплот порчи",b="Деревня Сквернолапов, расположенная на северной окраине Оскверненного леса, служит главным северным оплотом павших фурболгов племени Мертвого Леса. Некогда мирные хранители леса, они пали жертвой демонической порчи, высвобожденной во время Третьей войны, и впали в звериное безумие. Теперь деревня — оскверненный анклав с грубыми хижинами, ритуальными тотемами и враждебными воинами, нападающими на всякого, кто подходит к входу в тоннель Крепости Древобрюхов."},{t="Заноза у Крепости Древобрюхов",b="Близость Деревни Сквернолапов к священному входу в Крепость Древобрюхов делает ее серьезной угрозой для немногих неоскверненных фурболгов региона. Стражи Древобрюхов на северном краю Оскверненного леса смотрят на павших сородичей со скорбью и настороженностью и часто просят путников проредить ряды Мертвого Леса, добыть их ритуальные фетиши и не дать порче просочиться через врата в Лунную поляну и Зимние Ключи."}},faq={{q="Кто живет в Деревне Сквернолапов?",a="Поселение принадлежит фурболгам племени Мертвого Леса — местному племени, полностью павшему под власть демонической порчи, распространяющейся по Оскверненному лесу.",al={"felpaw village inhabitants","who is at felpaw","deadwood furbolgs northern felwood","жители деревни сквернолапов","кто в деревне сквернолапов","фурболги мертвого леса"}},{q="Почему здешние фурболги враждебны?",a="Фурболги племени Мертвого Леса обезумели от демонических энергий, отравляющих почву, воду и животных Оскверненного леса. Они считают всех чужаков врагами, и с ними невозможно договориться.",al={"why do deadwood attack","are felpaw furbolgs friendly","why are bears angry felwood","почему мертвый лес нападает","дружелюбны ли фурболги сквернолапы","почему медведи злы"}},{q="Где находится Деревня Сквернолапов?",a="Она лежит на дальнем севере Оскверненного леса, прямо у дороги, ведущей к главному южному входу в Крепость Древобрюхов.",al={"felpaw village map location","where is felpaw village","how to get to felpaw","деревня сквернолапов на карте","где деревня сквернолапов","как добраться до сквернолапов"}},{q="Как Деревня Сквернолапов связана с Крепостью Древобрюхов?",a="Неоскверненное племя Древобрюхов внимательно наблюдает за Деревней Сквернолапов из своих ближних врат. Поскольку Мертвый Лес угрожает безопасности прохода между Оскверненным лесом, Зимними Ключами и Лунной поляной, Древобрюхи награждают чужаков, которые сокращают число враждебных обитателей деревни и добывают ритуальные перья Мертвого Леса.",al={"timbermaw connection","timbermaw hold reputation felpaw","timbermaw deadwood","связь с древобрюхами","репутация древобрюхов сквернолапы","древобрюхи мертвый лес"}}},fp="14,293,26.455.0,29.465.0,28.152.0,34.187.0,32.124.0,49.295.0"}
P.entries["subzone:felstone-field"] = {n="Поле Джанис",s="Поле Джанис — оскверненная ферма на северо-западе Западных Чумных земель. Некогда процветавшие сельскохозяйственные угодья Лордерона, оно захвачено Плетью и стало опорой чумного котла, изрыгающего ядовитые испарения над разоренной землей.",h="Поле Джанис — оскверненная ферма на северо-западе Западных Чумных земель.",kw={"cauldron lord bilemaw","felstone field","janice felstone","jeremiah payson","lordaeron","ol' emma","plague cauldron","scarlet crusade","western plaguelands","хранитель котла желчень","поле джанис","джанис фелстон","иеремия пэйсон","лордерон","старушка эмма","чумной котел","алый орден","западные чумные земли"},ang={["faction:Alliance"]="Для выживших Альянса в Штормграде такие места, как Поле Джанис, — это потерянные родовые земли и разлученные родичи вроде Старушки Эммы, цепляющейся за права на разоренное северное наследство.",["race:Undead"]="Разоренная ферма — суровое напоминание о жизни, которую Отрекшиеся вели в Лордероне; о ней напоминают родственники вроде Иеремии Пэйсона, уцелевшего лишь благодаря нежизни."},sec={{t="Оскверненная усадьба",b="До Третьей войны Поле Джанис было мирной доходной семейной фермой, кормившей жителей Лордерона. Когда чума прошла по северу, усадьба быстро пала перед Культом Проклятых и Плетью. Сегодня на полях вместо зерна растут мертвые сорняки и ползучая гниль. В сердце угодий стоит огромный чумной котел, непрерывно выпускающий в небо зловонные пары под надзором Хранителя котла Желчень и легионов скелетов-свежевателей, колдунов и голодных вурдалаков."},{t="Задержавшиеся призраки и фанатики",b="Несмотря на оккупацию нежити, в руинах остались следы мира живых. В северо-восточном фермерском доме бродит призрак Джанис Фелстон, скорбно блуждающий по остову своего бывшего дома. Тем временем патрули соседнего Алого ордена обходят границы владений, жестоко уничтожая любую нежить и убивая чужаков, подошедших слишком близко к их крестовому походу."}},faq={{q="Для чего нужен котел в центре поля?",a="Котел — чумная машина Плети, предназначенная пропитывать окрестные земли и воздух мором, портя почву и поднимая мертвых. Его охраняет могущественный надзиратель Плети — Хранитель котла Желчень, а также скелеты-прислужники и вурдалаки.",al={"felstone cauldron","why is there a cauldron","plague cauldron felstone","котел поля джанис","зачем здесь котел","чумной котел поля джанис"}},{q="Кто такой призрак в фермерском доме?",a="Это Джанис Фелстон, бывшая хозяйка фермы, погибшая, когда Плеть захватила эти земли. Не желая или не имея возможности упокоиться, ее дух остается связанным с руинами родного дома.",al={"janice felstone","ghost in felstone house","who is in the house","джанис фелстон","призрак в доме фелстон","кто в доме"}},{q="Почему ферму патрулируют бойцы Алого ордена?",a="Алый орден часто отправляет агрессивные отряды в Западные Чумные земли для уничтожения Плети. Любых путников, забредших на территорию, — Орды или Альянса — они считают возможными разносчиками чумы или врагами и нападают без разбора.",al={"scarlet crusade felstone","crusaders at felstone field","алый орден поле джанис","рыцари ордена на поле джанис"}},{q="Кому на самом деле принадлежит право на Поле Джанис?",a="И Иеремия Пэйсон в Подгороде, и Старушка Эмма в Штормграде утверждают, что получили документ от своей сестры, Джанис Фелстон. Остается загадкой, было ли составлено два документа или хаос чумы безнадежно запутал наследство между живыми и мертвыми родственниками.",al={"felstone field deed","who owns felstone","better late than never deed","документ на поле джанис","кому принадлежит поле джанис","лучше поздно чем никогда документ"}}},fp="14,254,20.508.0,28.408.1,54.264.0,38.204.0,52.246.0,45.291.1"}
P.entries["subzone:fenris-keep"] = {n="Крепость Фенриса",s="Крепость Фенриса — уединенная каменная цитадель на вершине Острова Фенриса посреди озера Лордамер. Когда-то это был стратегический оплот с войсками Лордерона, но теперь он перешел в руки Плети под началом отступника-мага Тула Когтя Ворона.",h="Крепость Фенриса — уединенная каменная цитадель на вершине Острова Фенриса посреди озера Лордамер.",kw={"fenris isle","fenris keep","lordaeron","lordamere lake","rot hide","scourge","silverpine forest","thule ravenclaw","остров фенриса","крепость фенриса","лордерон","озеро лордамер","гнилошкуры","плеть","серебряный бор","тул коготь ворона"},ang={["class:Mage"]="Хозяин Крепости Фенриса Тул Коготь Ворона — мрачное предательство учения Кирин-Тора: он извратил арканные знания Даларана, превратив их в темные искусства Плети.",["faction:Horde"]="Для Орды, и особенно для Отрекшихся, Крепость Фенриса — уцелевший оплот Плети, который необходимо уничтожить, чтобы защитить Серебряный бор и водные пути озера Лордамер."},sec={{t="Павший бастион Лордерона",b="До Третьей войны Крепость Фенриса имела стратегическое значение для Королевства Лордерон: там стоял значительный отряд, охранявший озеро Лордамер. Когда нежить из Плети захлестнула страну, островная крепость пала вместе с остальным королевством. Но она не превратилась в забытые руины: ее захватил Тул Коготь Ворона, предатель и бывший волшебник Кирин-Тора. Он заключил союз с Плетью, подчинил местных гноллов мерзкой некромантией, создав свирепую стаю Гнилошкур, и закрепился в каменных залах крепости."},{t="Плеть на Лордамере",b="Сегодня Крепость Фенриса — средоточие власти Когтя Ворона и неминуемая угроза для Отрекшихся, удерживающих Серебряный бор. Из этого бастиона Тул управляет легионами гноллов Гнилошкур, яростно нападающих на всякого, кто осмелится ступить на остров. Поскольку Остров Фенриса лежит всего в нескольких милях по воде от границы Тирисфаля, Отрекшиеся из Гробницы и Подгорода посылают защитников, чтобы сокрушить оборону крепости и покончить с отступником-некромантом."}},faq={{q="Что такое Крепость Фенриса?",a="Крепость Фенриса — укрепленный каменный замок на Острове Фенриса посреди озера Лордамер. Раньше это был военный оплот павшего Королевства Лордерон, а теперь им владеет нежить из Плети.",al={"fenris keep lore","what is fenris keep","fenris castle","предания крепости фенриса","что такое крепость фенриса","замок фенриса"}},{q="Кто сейчас правит Крепостью Фенриса?",a="Крепостью правит Тул Коготь Ворона, бывший маг Кирин-Тора, предавший живых ради службы Плети. Из крепости он командует армией оскверненных нежитью гноллов Гнилошкур.",al={"who controls fenris keep","fenris keep boss","master of fenris isle","кто управляет крепостью фенриса","босс крепости фенриса","хозяин острова фенриса"}},{q="Почему в Крепости Фенриса гноллы?",a="Местных гноллов подчинил Тул Коготь Ворона с помощью темной магии и болезни, превратив их в гноллов Гнилошкур. Они служат ударными отрядами и верными стражами Когтя Ворона по всему замку и острову.",al={"rot hide gnolls fenris","why gnolls in keep","fenris gnolls","гноллы гнилошкуры фенрис","почему гноллы в крепости","гноллы фенриса"}},{q="Почему Отрекшихся волнует Крепость Фенриса?",a="Крепость Фенриса дает Плети надежную базу на озере Лордамер и прямо угрожает передвижениям Отрекшихся по восточной части Серебряного бора и Тирисфальским лесам. Войска Сильваны не могут оставлять действующего командира Плети без присмотра так близко к своим границам.",al={"why forsaken attack fenris","forsaken fenris keep","undercity fenris","почему отрекшиеся нападают на фенрис","отрекшиеся крепость фенриса","подгород фенрис"}}},fp="11,235,29.591.0,24.473.1,20.194.0,32.187.0,40.238.0,43.262.0"}
P.entries["subzone:feral-scar-vale"] = {n="Долина Свирепого Утеса",s="Долина Свирепого Утеса — скалистое ущелье в Высокогорных дебрях западного Фераласа. Она захвачена территориальными йети Свирепого Утеса, и ее пещерные туннели крайне опасны для путников, сошедших с заросших лесных троп.",h="Долина Свирепого Утеса — скалистое ущелье в Высокогорных дебрях западного Фераласа.",kw={"feral scar vale","feralas","high wilderness","homing robot","oox-22/fe","yeti","долина свирепого утеса","фералас","высокогорные дебри","самонаводящийся робот","йети"},ang={["class:Hunter"]="Громадные йети Свирепого Утеса, бродящие по этим скалам, — серьезное испытание для навыков выслеживания и охоты на крупную дичь среди густых крон Высокогорных дебрей.",["profession:Engineering"]="В туннелях йети застрял гномский самонаводящийся робот; чтобы благополучно вернуть его в цивилизацию, понадобятся рука инженера и аварийный маяк."},sec={{t="Логово йети",b="Среди густой листвы и отвесных скал Высокогорных дебрей находится Долина Свирепого Утеса — главное логово свирепых йети Свирепого Утеса. Хотя йети обычны на заснеженных вершинах Альтерака и Дун Морога, эти первобытные громилы полностью приспособились к диким влажным условиям Фераласа. Они яростно защищают сеть пещер долины, копят костяные трофеи и беспощадно прогоняют всех, кто забредет на их охотничьи угодья."},{t="Диковинки в пещерах",b="Помимо первобытной опасности йети, в глубине Долины Свирепого Утеса скрываются неожиданные странности. Сигналы бедствия гномских инженеров порой приводили в эти темные пещеры, где свирепые звери захватили потерянные исследовательские устройства, например застрявших роботов-разведчиков в виде цыплят, которые ждут активации и вызволения."}},faq={{q="Какие существа живут в Долине Свирепого Утеса?",a="В долине господствуют йети Свирепого Утеса — огромные территориальные хищники, которые гнездятся в скалистых пещерах и патрулируют окрестный лес.",al={"feral scar vale mobs","what is in feral scar vale","vale creatures","мобы долины свирепого утеса","что в долине свирепого утеса","существа долины"}},{q="Где находится Долина Свирепого Утеса?",a="Долина Свирепого Утеса находится в западной части Фераласа, в области под названием Высокогорные дебри, к югу от главной дороги, пролегающей сквозь полог дождевого леса.",al={"feral scar vale location","where is feral scar vale","how to find feral scar vale","расположение долины свирепого утеса","где долина свирепого утеса","как найти долину свирепого утеса"}},{q="Почему в пышном тропическом лесу живут йети?",a="Хотя йети обычно связывают со снежными горами, древние и нетронутые дебри Калимдора населяют особые подвиды, например йети Свирепого Утеса, которые на протяжении поколений процветают в густых лесных долинах.",al={"why yetis in feralas","jungle yetis","feralas yeti lore","почему йети в фераласе","йети джунглей","предания о йети фераласа"}},{q="Что за механический цыпленок в пещере?",a="Глубоко в одной из пещер долины находится самонаводящийся робот OOX-22/FE — автономный механический цыпленок-разведчик, созданный гномами-инженерами, который потерпел крушение и застрял в тылу йети.",al={"oox-22/fe","robot chicken feralas","homing robot feral scar vale","робот цыпленок фералас","самонаводящийся робот долина свирепого утеса"}}},fp="15,232,17.450.0,24.355.0,47.148.0,33.158.0,41.215.0,47.187.0"}
P.entries["subzone:field-of-giants"] = {n="Поля Великанов",s="Поля Великанов — обширная равнина в южных Степях между Лагерем Таурахо и болотами Пылевых топей. Свое название она получила от огромных кодо, громадных ящеров и других гигантских зверей, пасущихся в ее сухих зарослях; недавно регион стал куда опаснее из-за вторжения силитидов.",h="Поля Великанов — обширная равнина в южных Степях между Лагерем Таурахо и болотами Пылевых топей.",kw={"barrens","camp taurajo","field of giants","gold road","kodo","korran","ruga ragetotem","silithid","thunder lizard","степи","лагерь таурахо","поля великанов","золотой путь","кодо","корран","руга тотем гнева","силитиды","громовой ящер"},ang={["class:Hunter"]="Бродячие стада громовых ящеров и огромных кодо делают Поля Великанов одним из лучших охотничьих угодий Степей для тех, кто ищет грозных зверей.",["faction:Horde"]="Появление ульев силитидов так близко к дороге между Лагерем Таурахо и Пылевыми топями угрожает путям сообщения, и лидеры по всем Степям призывают разведчиков."},sec={{t="Дикий рубеж на юге",b="Поля Великанов тянутся вдоль южного участка Золотого Пути; по сравнению с северными Степями это глухой, суровый и слабо защищенный край. Деревянные сторожевые башни у дороги в основном заброшены, но сама земля полна жизни. Огромные стада крупных зверей Калимдора бродят по обширным равнинам, привлекая охотников и натуралистов. Однако безопасности здесь нет: дворфийские раскопщики из Бейл Модана упорно копают к югу, а гораздо более зловещая угроза начала рыть землю под ногами."},{t="Ползущий рой",b="В последнее время по всем Полям Великанов из земли вырвались ульи насекомоподобных силитидов — самое северное из известных появлений этих прожорливых тварей в Калимдоре. Странные холмы и агрессивные рои встревожили Орду. Разведчики вроде тролля Коррана из Перекрестка и воины-таурены вроде Руги Тотема Гнева из Лагеря Таурахо призывают искателей приключений исследовать ульи и выяснить, что привлекло этих подземных чудовищ так далеко от глубоких пустынь."}},faq={{q="Почему это место называется Полями Великанов?",a="Равнина получила название из-за огромных размеров живущих на ней животных. Здесь пасутся большие стада громадных кодо и ящеров, которые вместе с другими крупными зверями Калимдора господствуют над местностью.",al={"field of giants name origin","why field of giants","происхождение названия полей великанов","почему поля великанов"}},{q="Что это за кучи в земле?",a="Это холмы силитидов. Эти насекомоподобные хищники поднялись из глубин земли и создали самые северные из найденных в Калимдоре ульи. Их внезапное появление — серьезная угроза для путников и местных животных.",al={"bug mounds barrens","insects in southern barrens","what are the silithid","холмы в степях","насекомые в южных степях","кто такие силитиды"}},{q="Кто живет рядом с Полями Великанов?",a="На самой равнине мало поселений, но у ее границ стоят видные личности. Шаманка-тауренка Брин живет на южном хребте, а изгнанник Ганн Каменное Копье наблюдает неподалеку, замышляя козни против дворфийских раскопок в Бейл Модане.",al={"who lives here","field of giants npcs","кто здесь живет","персонажи полей великанов"}},{q="Почему сторожевые башни вдоль дороги заброшены?",a="Военное присутствие Орды сосредоточено главным образом на северном участке Золотого Пути вокруг Перекрестка. Южные земли патрулируют гораздо реже, и башни оказались заброшены на фоне растущей угрозы силитидов и агрессивных зверей.",al={"abandoned towers gold road","southern barrens watchtowers","заброшенные башни золотой путь","сторожевые башни южных степей"}}},fp="15,307,28.517.0,18.478.0,37.206.0,40.231.0,35.247.0,49.253.0"}
P.entries["subzone:fire-plume-ridge"] = {n="Вулкан Огненного Венца",s="Вулкан Огненного Венца — действующий вулкан, поднимающийся прямо в центре кратера Ун'Горо. Его раскаленные склоны и подземные каналы магмы питают гейзеры и паровые озера кратера, а также служат домом свирепым элементалям огня.",h="Вулкан Огненного Венца — действующий вулкан, поднимающийся прямо в центре кратера Ун'Горо.",kw={"blazerunner","elementals","fire plume ridge","lava","ringo","ungoro","volcano","яропламень","элементали","вулкан огненного венца","лава","ринго","ун'горо","вулкан"},ang={["class:Shaman"]="Духи огня яростно бушуют на вулкане, давая яркое представление о неукротимых силах стихий, бурлящих под корой Калимдора.",["profession:Mining"]="Скалы и раскаленные склоны вулкана богаты обнаженными минералами, особенно жилами плотного тория, образованного вулканическим давлением."},sec={{t="Очаг кратера",b="Вулкан Огненного Венца возвышается над первозданной котловиной Ун'Горо и резко контрастирует с окружающими буйными джунглями. Лава непрерывно стекает по его обожженным скалистым склонам, создавая ландшафт из пепла и базальта. От вулкана под землей паутиной расходятся подземные магматические русла, питающие бурлящие гейзеры и горячие источники, разбросанные по котловине. Здешняя изнуряющая жара легендарна: по замерам гоблинских приборов, она намного превышает обычную температуру вулканов, и плохо подготовленным исследователям опасно бродить здесь без достаточного запаса воды и тени."},{t="Логово элементалей",b="Вулкан — это стихийная топка, кишащая живым пламенем. Живые сполохи и бродячие элементали огня патрулируют раскаленные потоки, привлеченные скоплением чистого подземного жара. Глубоко в пещере возле вершины вулкана обитает Яропламень — бесспорный повелитель стихийных обитателей Ун'Горо. Подъем на вершину хребта сопряжен со смертельным жаром и переменчивыми духами стихий, которые яростно защищают свои огненные владения."}},faq={{q="Что за вулкан находится посреди кратера Ун'Горо?",a="Это Вулкан Огненного Венца, действующий вулкан в самом центре кратера Ун'Горо. Его каналы с расплавленной породой дают жар, который согревает окрестные джунгли и паровые источники.",al={"ungoro volcano name","volcano in center of ungoro","fire plume ridge location","название вулкана ун'горо","вулкан в центре ун'горо","где вулкан огненного венца"}},{q="Кто повелевает элементалями на Вулкане Огненного Венца?",a="В пещере на вершине обитает Яропламень, самый могущественный элементаль огня в кратере Ун'Горо.",al={"boss of fire plume ridge","blazerunner location","fire elemental boss ungoro","босс вулкана огненного венца","где яропламень","босс элементаль огня ун'горо"}},{q="Почему внутри вулкана застрял исследователь?",a="Искатель приключений Ринго, союзник гоблинов, отправился исследовать вулкан, но в одной из южных пещер его свалило сильное тепловое истощение, и без посторонней помощи ему не выбраться.",al={"who is stranded in fire plume ridge","ringo ungoro","lost guy in volcano","кто застрял в вулкане огненного венца","ринго ун'горо","потерявшийся в вулкане"}},{q="Как вулкан влияет на остальной Ун'Горо?",a="Неглубокие жилы магмы расходятся от Вулкана Огненного Венца под всем дном кратера, согревая землю и порождая многочисленные гейзеры, горячие источники и паровые озера по всей котловине.",al={"why is ungoro so hot","crater geothermal activity","shallow magma veins ungoro","почему в ун'горо так жарко","геотермальная активность кратера","жилы магмы ун'горо"}}},fp="16,228,24.574.0,19.446.0,52.167.0,45.96.0,51.187.0,48.205.0"}
P.entries["subzone:fire-scar-shrine"] = {n="Святилище Огненной Расщелины",s="Святилище Огненной Расщелины — оскверненное святилище ночных эльфов в юго-западных чащах Ясеневого леса. Когда-то оно было мирным местом поклонения, но было осквернено демонами и превратилось в нарыв скверны прямо у порога Астранаара.",h="Святилище Огненной Расщелины — оскверненное святилище ночных эльфов в юго-западных чащах Ясеневого леса.",kw={"akkrilus","ashenvale","astranaar","athrikus narassin","cult of the dark strand","fire scar shrine","ilkrud magthrull","shadow council","аккрилус","ясеневый лес","астранаар","атрикус нарассин","культ темной нити","святилище огненной расщелины","илкруд магтрулл","совет теней"},ang={["class:Warlock"]="Шрамы Скверны и дикие демонические призывы здесь несут явный отпечаток тонких проникновений Совета Теней по всему Калимдору.",["race:NightElf"]="Осквернение Святилища Огненной Расщелины — горькое оскорбление так близко от Астранаара, требующее скорой расплаты любым демонам, оскверняющим лес."},sec={{t="Язва в лесу",b="Святилище Огненной Расщелины находится к юго-западу от Астранаара и к западу от Руин Звездной Пыли. Оно служит мрачным напоминанием о яде Пылающего Легиона, оставшемся в Ясеневом лесу. Святилище подпало под власть демонической порчи, которую питали слуги Культа Темной Нити и Совета Теней. Магия Скверны превратила окрестную землю в обожженный камень, где бродячие демоны открыто собираются, бросая вызов защитникам леса."},{t="Тени Темной Нити",b="Падение святилища во тьму возглавили такие приспешники, как орк-чернокнижник Илкруд Магтрулл, действовавший по приказу Атрикуса Нарассина. Хотя порчу принесли смертные чародеи, призванные демоны теперь беспрепятственно бродят у алтарных камней. Местный разрыв в завесе порой привлекает и более страшных созданий, в том числе исполинского стража Скверны Аккрилуса."}},faq={{q="Где находится Святилище Огненной Расщелины?",a="Святилище Огненной Расщелины находится на юго-западе Ясеневого леса, прямо к юго-западу от главного поселения ночных эльфов Астранаара, к югу от Святилища Эссины и сразу к западу от Руин Звездной Пыли.",al={"fire scar shrine location","where is fire scar shrine","fire scar shrine map","где святилище огненной расщелины","святилище огненной расщелины расположение","святилище огненной расщелины карта"}},{q="Почему в Святилище Огненной Расщелины есть демоны?",a="Святилище было захвачено и осквернено агентами Совета Теней и Культа Темной Нити, в частности орком-чернокнижником Илкрудом Магтруллом. Их темные ритуалы призвали демонов и пропитали священную землю стойкой скверной.",al={"why demons here","what corrupted fire scar shrine","who summoned the demons","почему здесь демоны","что осквернило святилище огненной расщелины","кто призвал демонов"}},{q="Кто такой Аккрилус?",a="Аккрилус — грозный страж Скверны, который время от времени появляется возле Святилища Огненной Расщелины, привлеченный мощной демонической энергией, скопившейся вокруг оскверненных камней.",al={"akkrilus","doomguard at fire scar","rare demon fire scar shrine","аккрилус","страж скверны у огненной расщелины","редкий демон святилище огненной расщелины"}},{q="Как это место связано с Культом Темной Нити?",a="Орк-чернокнижник Илкруд Магтрулл, действовавший здесь, служил Атрикусу Нарассину, предводителю Культа Темной Нити. Они использовали святилище как опорный пункт для демонических призывов и своих темных замыслов в Ясеневом лесу.",al={"cult of the dark strand fire scar","dark strand connection","athrikus narassin fire scar","культ темной нити огненная расщелина","связь с темной нитью","атрикус нарассин огненная расщелина"}}},fp="16,241,22.447.0,26.372.0,34.181.0,41.238.0,16.163.0,68.226.0"}
P.entries["subzone:firewatch-ridge"] = {n="Гряда Огненной стражи",s="Гряда Огненной стражи — высокий вулканический утес на севере Тлеющего ущелья, главный лагерь дворфов Черного Железа. Она нависает прямо над огромной выработкой, известной как Котлован, и сильно укреплена дворфийскими часовыми, механическими големами и гнездящимися огненными пауками. На северо-западе система зловещих пещер выдает укоренившееся присутствие культа Сумеречного Молота.",h="Гряда Огненной стражи — высокий вулканический утес на севере Тлеющего ущелья, главный лагерь дворфов Черного...",kw={"cauldron","dark iron","firewatch ridge","flame spiders","golems","searing gorge","twilight's hammer","котлован","черное железо","гряда огненной стражи","огненные пауки","големы","тлеющее ущелье","сумеречный молот"},ang={["race:Dwarf"]="Для дворфов Стальгорна Гряда Огненной стражи — мрачное напоминание об укоренившейся злобе, железной промышленности и темных союзах их сородичей из Черного Железа в тени Черной горы."},sec={{t="Выжженная смотровая площадка",b="Гряда Огненной стражи, возвышающаяся над промышленной разрухой Котлована, служит важным плацдармом для действий клана Черного Железа в Тлеющем ущелье. Дворфийские стражи, инженеры и големы из расплавленного металла патрулируют скалы, яростно защищая свой оплот вместе с ядовитыми огненными пауками, обитающими на тлеющих камнях. Высота дает дворфам Черного Железа беспрепятственный обзор окрестных пепельных равнин и заблаговременно предупреждает о вторжениях соперников из Стальгорна или Братства Тория."},{t="Тень культа",b="На северо-западе гряды скрывается сеть подземных пещер, занятая Сумеречным Молотом. Эти культисты действуют в тени лагеря дворфов Черного Железа, проводят темные ритуалы и укрывают под скалами могущественных фанатиков-элитников. Их близость и к инфраструктуре дворфов Черного Железа, и к Черной горе отражает всепроникающее, коварное влияние культов стихий и конца света в огненном сердце Тлеющего ущелья."}},faq={{q="Что такое Гряда Огненной стражи?",a="Гряда Огненной стражи — возвышенность в Тлеющем ущелье, где дворфы Черного Железа устроили большой лагерь над местом раскопок Котлована.",al={"what is this place","firewatch ridge info","firewatch ridge overview","что это за место","гряда огненной стражи","гряда огненной стражи обзор"}},{q="Какие враги обитают на Гряде Огненной стражи?",a="На гряде обитают враждебные дворфы Черного Железа, механические големы и местные огненные пауки, а система пещер на северо-западе занята элитными членами культа Сумеречного Молота.",al={"what mobs are here","enemies firewatch","firewatch ridge threats","какие мобы здесь","враги гряды огненной стражи","угрозы гряды огненной стражи"}},{q="Почему здесь Сумеречный Молот?",a="Культ Сумеречного Молота обосновался в северо-западных пещерах гряды, чтобы вести поклонение стихиям и ритуалы конца света вблизи Черной горы и связанных в этом регионе элементалей огня.",al={"twilights hammer firewatch","cultists in cave","northwest cave firewatch","сумеречный молот гряда огненной стражи","культисты в пещере","северо-западная пещера"}},{q="Как Гряда Огненной стражи связана с Котлованом?",a="Гряда Огненной стражи расположена прямо над Котлованом и дает дворфам Черного Железа укрепленный наблюдательный пункт, откуда они следят за добычей и защищают свой карьер от возможных нападений.",al={"firewatch and cauldron","cauldron overlook","why overlook cauldron","гряда огненной стражи и котлован","вид на котлован","зачем смотреть на котлован"}}},fp="15,407,24.518.0,22.461.0,24.153.0,37.195.0,34.235.0,48.191.0"}
P.entries["subzone:foothold-citadel"] = {n="Цитадель",s="Цитадель — центральные военные казармы и командный пункт на острове Терамор. Возвышаясь над укрепленным поселением, она служит обиталищем офицеров и стражей, защищающих главный оплот Альянса на юге Калимдора.",h="Цитадель — центральные военные казармы и командный пункт на острове Терамор.",kw={"barracks","daelin proudmoore","dustwallow marsh","foothold citadel","garran vimes","gustaf vanhowzen","samaul","theramore","казармы","даэлин праудмур","пылевые топи","цитадель","гарран веймс","густав ван склифф","самаул","терамор"},ang={["faction:Alliance"]="Цитадель — главный военный оплот Альянса на юге Калимдора; она координирует оборону от болотных тварей, мародеров Зловещего Тотема и бдительных разведчиков Орды.",["faction:Horde"]="Для Орды Цитадель — место, где Рексар и Тралл положили конец мстительному походу верховного адмирала Праудмура, обеспечив выживание Дуротара."},sec={{t="Сердце тераморской стражи",b="Цитадель, поднимающаяся за укрепленными каменными стенами острова Терамор, — нервный центр местной обороны Альянса. Здесь размещается верховное командование тераморской стражи, включая капитана Гаррана Веймса и командира Самаула, а также полевых медиков, офицеров снабжения и интендантов. Ее суровые каменные залы полны регулярных патрулей и тренировок, благодаря которым силы леди Джайны Праудмур готовы к угрозам, выползающим из окрестных болот."},{t="Отголоски падения адмирала",b="Цитадель хранит мрачную историю, связанную с первыми днями Терамора. Когда верховный адмирал Даэлин Праудмур захватил город, чтобы вести личный крестовый поход против Орды, именно эта крепость стала полем его последней битвы. Союзный отряд Тралла во главе с воином-мок'нафалом Рексаром ворвался в цитадель и сразил адмирала. Сегодня крепость восстановлена и неприступна, но память о кровавом сражении по-прежнему витает над ее каменными стенами."}},faq={{q="Для чего служит Цитадель?",a="Цитадель служит штабом и военными казармами тераморской стражи. Здесь размещаются командиры, тактики, учебные помещения и тыловой персонал, например местный казначей и медики.",al={"foothold citadel purpose","theramore barracks","what is this building","назначение цитадели","казармы терамора","что это за здание"}},{q="Что произошло здесь с верховным адмиралом Даэлином Праудмуром?",a="Во время конфликта после Третьей войны верховный адмирал Даэлин Праудмур захватил Терамор, чтобы воевать с молодой Ордой. Объединенный отряд под предводительством героя Рексара штурмовал цитадель и убил адмирала в его собственном штабе.",al={"daelin death","daelin proudmoore last stand","who killed daelin","смерть даэлина","последний бой даэлина праудмура","кто убил даэлина"}},{q="Кто сейчас командует в Цитадели?",a="Оперативное командование гарнизоном лежит на офицерах, таких как капитан Гарран Веймс и командир Самаул, которые руководят ежедневными патрулями и охраной региона под верховной властью леди Джайны Праудмур.",al={"who leads the citadel","theramore guard commander","citadel leader","кто возглавляет цитадель","командир тераморской стражи","глава цитадели"}},{q="Можно ли получить медицинскую помощь в цитадели?",a="Да. В Цитадели живет Доктор Густав ван Склифф: он лечит раненых стражников и обучает путников из Альянса передовой полевой медицине и сортировке раненых.",al={"citadel doctor","theramore medic","first aid trainer theramore","доктор цитадели","медик терамора","учитель первой помощи терамор"}}},fp="16,233,28.476.0,28.503.0,34.229.0,54.241.0,47.204.0,45.164.0"}
P.entries["subzone:forest-s-edge"] = {n="Лесная опушка",s="Лесная опушка — лесистый клин земли на юго-западной границе Элвиннского леса, окруженный реками, ведущими к Западному Краю. Эту дикую местность, которую с севера охраняет Гарнизон у Западного ручья, опасно захватили гноллы Речной Лапы под началом пресловутого Дробителя.",h="Лесная опушка — лесистый клин земли на юго-западной границе Элвиннского леса, окруженный реками, ведущими к...",kw={"elwynn forest","forest's edge","forests edge","gnolls","hogger","nazferiti river","riverpaw","westbrook garrison","элвиннский лес","лесная опушка","гноллы","река назферити","речная лапа","гарнизон у западного ручья"},ang={["faction:Alliance"]="Для новобранцев, расквартированных в Элвиннском лесу, зачистка Лесной опушки и победа над Дробителем — одно из первых серьезных испытаний, доказывающих перед короной их боевую готовность.",["profession:Herbalism"]="На тихих берегах рек и в тенистых рощах Лесной опушки растут обычные лесные травы, хотя при сборе часто приходится уклоняться от агрессивных патрулей гноллов."},sec={{t="Спорная граница",b="Лесная опушка, затерянная к юго-западу от Штормграда между Садом у Зеркального озера и реками на границе Западного Края, образует естественный лесной полуостров. Несмотря на близость Гарнизона у Западного ручья, малочисленность Армии Штормграда оставила местность уязвимой для диких зверей и разбойничьих шаек. Среди деревьев и по берегам рек бродят кабаны, но главная угроза — гноллы Речной Лапы, сделавшие эти леса своим плацдармом."},{t="Оплот Дробителя",b="Леса Лесной опушки — охотничьи угодья Дробителя, огромного и жестокого вожака гноллов. За его голову Армия Штормграда назначила крупную награду, а Дробитель направляет свою стаю на травлю путников и набеги на окрестные фермы, превращая мирный лес в смертельное испытание для молодых искателей приключений из Альянса."}},faq={{q="Где именно находится Лесная опушка?",a="Лесная опушка расположена в юго-западном углу Элвиннского леса. Она лежит к югу от Гарнизона у Западного ручья, граничит с Садом у Зеркального озера и водными путями, ведущими в Западный Край.",al={"forests edge location","where is forests edge","forest edge map","лесная опушка местоположение","где лесная опушка","лесная опушка карта"}},{q="Почему эта местность так опасна?",a="Большая и агрессивная стая гноллов Речной Лапы заняла лес и угрожает путникам на юго-западной границе. Главная опасность — их вожак Дробитель, исключительно свирепый гнолл, бродящий по этим лесам.",al={"why dangerous forests edge","what is at forest edge","forests edge threats","почему опасна лесная опушка","что на лесной опушке","угрозы лесной опушки"}},{q="Кто такой Дробитель?",a="Дробитель — известный и могучий вожак гноллов, виновный в жестоких нападениях на границы Элвинна. Армия Штормграда назначила щедрую награду за доказательство его смерти и предостерегает искателей приключений от встречи с ним в одиночку.",al={"hogger lore","who is hogger","hogger info","дробитель предания","кто такой дробитель","дробитель информация"}},{q="Почему Гарнизон у Западного ручья не очистил местность?",a="Армия Штормграда крайне растянута по всему королевству. Из-за беспорядков в Западном Крае и угроз со всех сторон гарнизону не хватает людей, чтобы разгромить лагеря гноллов, и эта задача ложится на добровольцев-искателей приключений.",al={"why westbrook garrison not clearing","why stormwind guards not help","westbrook guards","почему гарнизон западного ручья не очищает","почему стража штормграда не помогает","стража западного ручья"}}},fp="13,287,20.464.0,19.341.0,31.181.0,30.221.0,14.212.0,47.232.0"}
P.entries["subzone:forest-song"] = {n="Лесная Песнь",s="Лесная Песнь — древние руины ночных эльфов на северо-востоке Ясеневого леса, рядом с оскверненными лесами Сатирнаара и великим порталом Тенистой Кроны. Сейчас они почти пусты, если не считать бдительного друида Кайнета Штиля, охраняющего восточную границу от новых угроз.",h="Лесная Песнь — древние руины ночных эльфов на северо-востоке Ясеневого леса, рядом с оскверненными лесами...",kw={"ashenvale","bough shadow","eastern ashenvale","forest song","kaldorei ruins","kayneth stillwind","satyrnaar","ясеневый лес","тенистая крона","восточный ясеневый лес","лесная песнь","руины кальдораев","кайнет штиль","сатирнаар"},ang={["class:Druid"]="Тихое присутствие Кайнета Штиля подчеркивает одинокий дозор Круга Кенария в оскверненных пограничных землях, прямо под сумрачным пологом леса близ Великого Древа Тенистой Кроны.",["faction:Alliance"]="Лесная Песнь служит важным одиноким форпостом для искателей приключений из Альянса, идущих через северо-восток Ясеневого леса к Азшаре или в Оскверненный лес."},sec={{t="Одинокий дозор в восточном Ясеневом лесу",b="Лесная Песнь, скрытая в густых лесах северо-востока Ясеневого леса, когда-то была изящным поселением кальдораев. Ныне белые каменные колонны и рушащиеся арки поросли плющом и диким папоротником. Руины лежат к северо-востоку от Сатирнаара и сразу к северу от наступающих Лесозаготовок Песни Войны и тихо, но стратегически выгодно обозревают восточные тропы к Азшаре и Тенистой Кроне. Хотя окрестные леса поражены демонической скверной и набегами Орды, сами руины сохраняют призрачный, безмятежный покой."},{t="Страж границы",b="Лесную Песнь ныне охраняет лишь друид Кайнет Штиль. Из этого разрушающегося форпоста Штиль следит за темными замыслами врагов, проникающих в глушь, включая тревожное присутствие Отрекшихся в восточных лесах. Хотя святилище удалено от Астранаара и лишено гарнизонных укреплений, оно служит важным сборным пунктом для путников из Альянса, идущих по северной дороге в Оскверненный лес или изучающих скверну, расползающуюся под пологом деревьев."}},faq={{q="Кто живет в Лесной Песни?",a="Сейчас в Лесной Песни обитает ночной эльф-друид Кайнет Штиль, в одиночку несущий дозор среди древних руин.",al={"who is at forest song","forest song npcs","forest song inhabitants","кто в лесной песни","персонажи лесной песни","жители лесной песни"}},{q="Какие угрозы есть рядом с Лесной Песнью?",a="Руины опасно близки к Сатирнаару на юго-западе, кишащему оскверненными сатирами, и к Лесозаготовкам Песни Войны на юге. На северо-востоке лежит Тенистая Крона, где зеленый драконий род охраняет Великое Древо, ведущее в Изумрудный Сон.",al={"forest song dangers","enemies near forest song","опасности лесной песни","враги рядом с лесной песнью"}},{q="Почему Кайнет Штиль находится здесь?",a="Кайнет следит за передвижениями врагов в восточных лесах и направляет союзников против местных опасностей, включая зловещие замыслы и болезни, которые распространяют действующие в этих местах Отрекшиеся.",al={"why is kayneth here","kayneth stillwind purpose","почему кайнет здесь","кайнет штиль задача"}},{q="Является ли Лесная Песнь крупным поселением Альянса?",a="Нет. В отличие от Астранаара, Лесная Песнь — в основном неукрепленные руины без действующего гарнизона, торговцев и военной инфраструктуры, поддерживаемые лишь как одинокий передовой наблюдательный пост.",al={"alliance town forest song","is forest song a town","поселение альянса лесная песнь","лесная песнь город"}}},fp="11,297,35.537.0,21.515.0,25.126.0,34.252.0,40.197.0,43.177.0"}
P.entries["subzone:forgotten-coast"] = {n="Забытый берег",ang={["faction:Horde"]="К берегу нужно подбираться осторожно: южная тропа проходит рядом с паромными пристанями ночных эльфов, а северные лесные тропы обеспечивают более безопасный путь к воде."},sec={{t="Край тропического леса",b="Забытый берег, протянувшийся вдоль западной окраины Фераласа, — открытое всем ветрам побережье у просторов Сокрытого Моря. В отличие от густого леса вглубь суши, эта граница открыта стихиям, и здесь властвуют огромные морские великаны и бродящие по прибою водные элементали. Путникам, выходящим из-под полога леса, приходится сталкиваться с этими древними стражами побережья, пробираясь к морю, откуда паромы ходят к оплоту ночных эльфов — Острову Сардор."}},faq={{q="Какие угрозы бродят по Забытому берегу?",a="The shoreline is patrolled by immense sea giants and restless water elementals emerging from the Veiled Sea.",al={"monsters on forgotten coast","forgotten coast dangers","what is on the coast","монстры забытого берега","опасности забытого берега","что на берегу"}},{q="Как добраться отсюда до Крепости Оперенной Луны?",a="Берег — главный материковый пункт отправления через пролив к Острову Сардор, где ночные эльфы держат Крепость Оперенной Луны. Небольшая паромная пристань на берегу обеспечивает безопасный путь по воде в обход опасных морских великанов.",al={"how to get to feathermoon","boat to feathermoon","feathermoon ferry","как добраться до оперенной луны","лодка до оперенной луны","паром оперенной луны"}},{q="Is the Forgotten Coast accessible to the Horde?",a="Yes. While the southern road leads directly toward the night elven crossing to Feathermoon Stronghold, a secondary path cuts down to the coast further to the north, allowing Horde travelers to reach the shore without straying into Alliance sentinels.",al={"horde access forgotten coast","how does horde reach coast","safe horde path forgotten coast"}}},fp="15,180,22.489.0,40.108.0,50.253.0,47.250.0"}
P.entries["subzone:forgotten-pool"] = {n="Забытый пруд",s="Забытый пруд — затопленная пещера в глубине залитых водой коридоров Непроглядной Пучины. Этот тихий тупик за Руинами Лунного святилища служит водным логовом чудовищных глубоководных хищников, таящихся в подземной тьме.",h="Забытый пруд — затопленная пещера в глубине залитых водой коридоров Непроглядной Пучины.",kw={"blackfathom deeps","cavern","forgotten pool","moonshrine ruins","old serra'kis","thresher","underwater","непроглядная пучина","пещера","забытый пруд","руины лунного святилища","старина серракис","молотильщик","под водой"},ang={["faction:Horde"]="Разведчики Орды, отправляющиеся в Непроглядную Пучину, могут найти Старину Серракиса в затопленной тьме пруда, вдали от залов, где поют культисты."},sec={{t="Затопленное логово",b="Чтобы добраться до Забытого пруда, нужно нырнуть в затонувшие подземные водные пути за Руинами Лунного святилища. Отрезанный от суши, пруд — изолированная застойная пещера, целиком залитая темной водой. Вдали от поющих культистов Сумеречного Молота и патрулирующих наг этот укромный уголок служит логовом древнего водного ужаса — Старины Серракиса, скрытого во тьме под водой."}},faq={{q="Где находится Забытый пруд?",a="Забытый пруд — полностью затопленная подводная пещера в глубине Непроглядной Пучины. Чтобы добраться до нее, исследователям нужно проплыть по затопленным туннелям, ответвляющимся за Руинами Лунного святилища.",al={"where is forgotten pool","forgotten pool location","how to find forgotten pool","где забытый пруд","расположение забытого пруда","как найти забытый пруд"}},{q="Что скрывается в Забытом пруду?",a="Пещера служит тайным логовом Старины Серракиса, древнего глубоководного зверя, похожего на молотильщика, который устроил в этом укромном тупике свое логово.",al={"forgotten pool monster","who lives in forgotten pool","forgotten pool boss","монстр забытого пруда","кто живет в забытом пруду","босс забытого пруда"}},{q="Ведет ли Забытый пруд куда-нибудь еще?",a="Нет. Пруд — подводный тупик без дальнейших проходов, служащий исключительно укромным водным гнездом.",al={"is forgotten pool a dead end","where does forgotten pool go","забытый пруд тупик","куда ведет забытый пруд"}}},fp="14,254,16.435.0,36.203.0,37.147.0,43.112.0"}
P.entries["subzone:forgotten-pools"] = {n="Забытые пруды",s="Забытые пруды — самый северный из зеленых оазисов, разбросанных по засушливым Степям, к северо-западу от Перекрестка. Этот яркий уголок с густой растительностью и водой питают подземные источники, и за него ведут ожесточенную борьбу местные животные, бродячие кентавры из племени Колкар и Орда.",h="Забытые пруды — самый северный из зеленых оазисов, разбросанных по засушливым Степям, к северо-западу от...",kw={"barrens","centaur","crossroads","deviate fish","forgotten pools","kolkar","laden mushrooms","oasis","степи","кентавр","перекресток","загадочная рыба","забытые пруды","колкар","грибы-тяжеловесы","оазис"},ang={["class:Druid"]="Быстрый рост мутировавших растений и Загадочной рыбы вокруг этих прудов служит важным свидетельством для исследователей Кенарийского круга, изучающих неестественные перемены в Степях.",["faction:Horde"]="Удержание прудов жизненно важно для безопасности торговых путей, расходящихся от Перекрестка, и не дает Колкару перерезать западные линии снабжения Орды."},sec={{t="Оазис в пустошах",b="Situated off the western road leading out of the Crossroads, the Forgotten Pools offers a stark contrast to the parched savannas that surround it. Thick reeds, palm trees, and unusual flora like Laden Mushrooms cluster around its freshwater shore, drawing plainstriders, snapjaw turtles, and zhevras from miles around. However, the oasis is far from peaceful. Kolkar centaur maintain a constant encampment along the banks, jealously guarding the water supply against travelers and bringing them into direct conflict with Horde travelers from the Crossroads."},{t="Экологические загадки",b="Помимо стратегической ценности водопоя, Забытые пруды отличаются своеобразными особенностями. Это одна из редких поверхностных вод в регионе, где водится загадочная Загадочная рыба, что намекает на глубинную подземную связь со странными преобразующими энергиями, которые меняют грунтовые воды Степей. Натуралисты и разведчики Орды внимательно следят за водой и необычными грибными зарослями по берегам, опасаясь того, что может просачиваться в почву."}},faq={{q="Где находятся Забытые пруды?",a="Забытые пруды лежат на севере Степей, прямо к северо-западу от Перекрестка, чуть севернее дороги, которая ответвляется на запад к Когтистым горам.",al={"forgotten pools location","where is forgotten pools","find forgotten pools","забытые пруды расположение","где находятся забытые пруды","как найти забытые пруды"}},{q="Почему здесь живут кентавры Колкар?",a="В засушливых Степях вода — это жизнь. Колкар агрессивно захватывают каждый оазис, до которого могут добраться, чтобы обеспечивать свои отряды и лишать жизненно важных ресурсов проходящие караваны Орды и ближайшие поселения.",al={"centaur at forgotten pools","why are kolkar here","kolkar forgotten pools","кентавры у забытых прудов","почему здесь колкар","колкар забытые пруды"}},{q="Чем необычны здешние рыба и растения?",a="Оазис — одно из немногих мест на поверхности, где можно поймать Загадочную рыбу, и здесь растут скопления необычных грибов-тяжеловесов. Эти странные мутации указывают на подземные возмущения, влияющие на подземные водоносные слои Степей.",al={"deviate fish forgotten pools","laden mushrooms","why are fish weird here","загадочная рыба забытые пруды","грибы-тяжеловесы","почему рыба странная"}},{q="Проходил ли Тралл через этот оазис?",a="Нигде не записано, в каких оазисах отдыхала Орда Тралла во время долгого перехода через Степи, поэтому неизвестно, были ли среди них Забытые пруды.",al={"thrall forgotten pools","did orcs camp here","warcraft 3 oasis","тралл забытые пруды","стояли ли орки лагерем здесь","оазис warcraft 3"}}},fp="15,303,22.557.0,20.456.0,38.162.0,32.194.0,44.237.0,35.152.0"}
P.entries["subzone:forlorn-cloister"] = {n="Покинутый двор",s="Покинутый двор — призрачное кладбищенское крыло Монастыря Алого ордена. Здесь члены Алого ордена отчаянно сжигают тела павших братьев, чтобы те не восстали нежитью, а неупокоенные духи и шаркающие мертвецы бродят среди гробниц.",h="Покинутый двор — призрачное кладбищенское крыло Монастыря Алого ордена.",kw={"forlorn cloister","graveyard","scarlet crusade","scarlet monastery","thalnos","tirisfal glades","покинутый двор","кладбище","алый орден","монастырь алого ордена","талнос","тирисфальские леса"},ang={["class:Priest"]="Прогулка по Покинутому двору — суровое напоминание о том, что бывает, когда святыни падают во тьму, а священные обряды сменяются лихорадочными кострами и измученными призраками.",["race:Undead"]="Отрекшиеся видят во дворе мрачную иронию: ревностные крестоносцы, клеймящие всю нежить чудовищами, не могут даже помешать собственным братьям вставать у них под ногами."},sec={{t="Поглощенное освящение",b="Когда-то это было мирное святилище, где жрецы и паладины Лордерона предавали земле своих почитаемых мертвецов, но Покинутый двор стал мрачным склепом. Несмотря на фанатичную бдительность Алого ордена, скверна чумы глубоко проникла в землю. Крестоносцы с факелами патрулируют окутанное туманом кладбище и лихорадочно сжигают останки, чтобы остановить гниение. И все же призраки скользят между склепами, а мертвецы выбираются из могил под властью темной магии в глубине владений."},{t="Владыка гробниц",b="Глубоко во дворе скрывается Волшебник Крови Талнос, садистский палач Алого ордена, чья ужасная судьба воплощает трагедию Монастыря. Заразившись чумой, он восстал скелетом-ужасом, принял темный некромантский путь: подчиняет души умерших и убивает всякого, кто осмелится вторгнуться на его оскверненное кладбище."}},faq={{q="Где находится Покинутый двор?",a="Покинутый двор образует открытое кладбищенское крыло Монастыря Алого ордена и расположен в северо-восточном углу Тирисфальских лесов.",al={"forlorn cloister location","where is cloister","graveyard wing","покинутый двор расположение","где двор","кладбищенское крыло"}},{q="Почему крестоносцы Алого ордена сжигают здесь тела?",a="Орден сжигает мертвых в отчаянной попытке не дать чуме Плети оживить павших соратников. Поскольку земля двора уже осквернена, несожженные тела быстро восстают бездумными зомби.",al={"why burn corpses","burning bodies scarlet","what are crusaders doing","зачем жечь трупы","сожжение тел алый орден","что делают крестоносцы"}},{q="Кто правит Покинутым двором?",a="Кладбищем владеет Волшебник Крови Талнос, могущественный маг-нежить, который повелевает бродячими мертвецами и нападает на всех живых чужаков.",al={"cloister boss","who is in charge here","graveyard boss","босс двора","кто здесь главный","босс кладбища"}},{q="Почему кладбище населено призраками, если Монастырем владеет Алый орден?",a="Несмотря на религиозное рвение, крестоносцы потеряли контроль над собственным кладбищем. Неослабевающие некромантские энергии, охватившие Лордерон, подняли погребенных мертвецов, и живой гарнизон оказался в бесконечной борьбе с духами своих бывших соратников.",al={"why are there ghosts","why undead in monastery","is graveyard scourge","почему здесь призраки","почему нежить в монастыре","кладбище плеть"}}},fp="16,270,23.503.0,23.332.0,38.138.0,50.217.0,36.144.0,72.281.0"}
P.entries["subzone:forlorn-ridge"] = {n="Одинокая вершина",s="Одинокая вершина — высокая горная гряда, возвышающаяся над юго-западной частью Азшары. Ее выгодная высота и великолепный обзор побережья привлекли внимание и Альянса, и Орды, и каждый возвел укрепления на ее склонах.",h="Одинокая вершина — высокая горная гряда, возвышающаяся над юго-западной частью Азшары.",kw={"azshara","forlorn ridge","fortifications","mountain","ruins of eldarath","volcano","азшара","одинокая вершина","укрепления","гора","руины эльдарата","вулкан"},ang={["faction:Alliance"]="Удержание высот Одинокой вершины дает раннее предупреждение и тактический обзор передвижений Орды, растекающейся на восток из Степей и Ясеневого леса.",["faction:Horde"]="Для Орды закрепление на Одинокой вершине помогает защитить труднодоступные приграничные земли Азшары к северу от Дуротара от вторжений Альянса."},sec={{t="Спорная обзорная точка",b="Резко поднимаясь над осенними лесами западной Азшары, Одинокая вершина господствует над местностью. Напоминая древний давно уснувший вулкан, она с высоты открывает широкий вид на подходы к побережью и разрушенные эльфийские поместья внизу. Поскольку контроль над этими высотами определяет военное превосходство в округе, и силы Альянса, и силы Орды устроили лагеря и форпосты на горных склонах и настороженно следят друг за другом поверх неровных утесов."}},faq={{q="Что такое Одинокая вершина?",a="Одинокая вершина — заметная горная вершина на юго-западе Азшары, возвышающаяся над окрестной глушью и прибрежными дорогами.",al={"where is forlorn ridge","forlorn ridge azshara","what is this mountain","где одинокая вершина","одинокая вершина азшара","что это за гора"}},{q="Почему Альянс и Орда сражаются за эту вершину?",a="С вершины открывается непревзойденный обзор западной Азшары. Тот, кто владеет высотой, может следить за передвижением войск между прибрежными руинами и внутренними перевалами, поэтому обе фракции укрепили позиции на ее склонах.",al={"why are there camps here","who controls forlorn ridge","alliance vs horde forlorn ridge","почему здесь лагеря","кто контролирует одинокую вершину","альянс против орды одинокая вершина"}},{q="Была ли Одинокая вершина когда-то вулканом?",a="Особая форма и грубый состав горы говорят о том, что в далеком прошлом она могла быть вулканом, хотя давно затихла и заросла.",al={"is forlorn ridge a volcano","volcano in azshara","одинокая вершина вулкан","вулкан в азшаре"}}},fp="13,256,19.496.0,22.133.0,56.230.0,39.176.0"}
P.entries["subzone:forlorn-rowe"] = {n="Покинутая усадьба",s="Покинутая усадьба — зловещий темный холм на северной границе Кладбища Вороньего Холма в Сумеречном лесу. Он известен как мрачное обиталище Морбента Скверна, некроманта, чья злая магия оживляет неупокоенных мертвецов по всему лесу.",h="Покинутая усадьба — зловещий темный холм на северной границе Кладбища Вороньего Холма в Сумеречном лесу.",kw={"cemetery","duskwood","forlorn rowe","morbent fel","necromancer","raven hill","undead","кладбище","сумеречный лес","покинутая усадьба","морбент скверн","некромант","вороний холм","нежить"},ang={["class:Paladin"]="Темные обряды, творимые в Покинутой усадьбе, — оскорбление Света, и чтобы пробить защиту некроманта, нужны освященные реликвии и праведный гнев.",["faction:Alliance"]="Изгнание Морбента Скверна из Покинутой усадьбы крайне важно, чтобы вернуть хоть какую-то безопасность западной границе Сумеречного леса."},sec={{t="Средоточие некромантии",b="Покинутая усадьба возвышается вдоль северного края Кладбища Вороньего Холма и вечно окутана мраком. На вершине стоит дом Морбента Скверна, подобного личу некроманта, ответственного за большинство ходячих мертвецов, населяющих окрестные земли. Скованный мерзкими арканными чарами, хозяин холма управляет скелетами-слугами отсюда, из-за чего весь северо-западный угол Сумеречного леса опасен для путников."},{t="Очищение холма",b="Власть Морбента Скверна над Покинутой усадьбой нельзя сломить обычной сталью. Его темные чары защищают тело от смертного оружия, пока он не ослабнет от особых реликвий священной силы. Чтобы одолеть некроманта и разрушить его власть над лесом, искателям приключений нужно добыть освященное оружие и ударить в самое сердце проклятия, душащего кладбище."}},faq={{q="Где находится Покинутая усадьба?",a="Покинутая усадьба находится на северо-западе Сумеречного леса, прямо на северном хребте над раскинувшимся Кладбищем Вороньего Холма.",al={"forlorn rowe location","where is forlorn rowe","find forlorn rowe","покинутая усадьба расположение","где покинутая усадьба","найти покинутую усадьбу"}},{q="Кто живет в Покинутой усадьбе?",a="Это логово Морбента Скверна, могущественного и злобного некроманта, который с помощью темных арканных обрядов поднимает и ведет легионы нежити, бродящей по Сумеречному лесу.",al={"who is at forlorn rowe","forlorn rowe boss","house on the hill duskwood","кто в покинутой усадьбе","босс покинутой усадьбы","дом на холме сумеречный лес"}},{q="Почему здесь так трудно сражаться с Морбентом Скверном?",a="Морбент Скверн защищается мерзкой магией, и обычные атаки почти бесполезны, пока освященная реликвия, созданная для рассеивания его магии, не лишит его темной защиты.",al={"morbent fel shield","morbent fel immune","how to kill morbent fel","щит морбента скверна","морбент скверн неуязвим","как убить морбента скверна"}},{q="Входит ли Покинутая усадьба в состав кладбища?",a="Да, это возвышенный утес вдоль северной границы Кладбища Вороньего Холма, прямо над могилами и склепами внизу.",al={"is forlorn rowe raven hill","raven hill connection","покинутая усадьба вороний холм","связь с вороньим холмом"}}},fp="12,253,20.441.0,18.396.1,34.140.0,30.158.0,41.184.1,41.141.0"}
P.entries["subzone:fray-island"] = {n="Остров Битв",s="Остров Битв — скалистый остров, обдуваемый всеми ветрами, недалеко от Торгового побережья Степей. На нем находится грубая тренировочная арена, и он известен как нейтральное убежище, где воины со всего Азерота приходят проверить свою доблесть.",h="Остров Битв — скалистый остров, обдуваемый всеми ветрами, недалеко от Торгового побережья Степей.",kw={"affray","barrens","berserker stance","big will","fray island","klannoc macleod","побоище","степи","стойка берсерка","большой уилл","остров битв","кланнок маклеод"},ang={["class:Warrior"]="Остров Битв — важное место для вашего обучения. Кланнок Маклеод и испытание Побоища проверят, достаточно ли у вас дисциплины и силы, чтобы принять стойку берсерка.",["race:Human"]="Кланнок Маклеод — человек, но воинов, собирающихся на его арене, объединяет боевое братство, не знающее расовых границ."},sec={{t="Испытательная площадка для бойцов",b="Остров Битв расположен у восточных утесов Степей, вдали от бдительных глаз Оргриммара и Терамора. Он служит местом обучения воинов всех рас и верований. В его центре находится арена, за которой присматривает Кланнок Маклеод; здесь опытные бойцы и неопытные новобранцы собираются, чтобы участвовать в жестоких схватках."},{t="Испытание Побоища",b="Несмотря на враждебность окружающих вод, центральная арена острова подчиняется простому кодексу боевого поединка. Воины приходят сюда по указанию своих наставников, чтобы принять участие в «Побоище» — изнурительном испытании против волн соперников, которое завершается схваткой с чемпионом Большим Уиллом. Здесь принадлежность к Орде или Альянсу отступает перед грубой силой и воинской дисциплиной."}},faq={{q="Для чего нужен Остров Битв?",a="Остров служит тренировочной площадкой для воинов и местом жестокого боевого испытания — Побоища. Воины обеих фракций приходят сюда, чтобы доказать свою выносливость и освоить продвинутые стойки.",al={"why go to fray island","fray island purpose","what is on fray island","зачем идти на остров битв","назначение острова битв","что находится на острове битв"}},{q="Кто управляет Островом Битв?",a="Ни одно королевство и ни одна фракция не правит им. Остров — место обучения воинов всех рас и верований, а его арена действует под присмотром наставника воинов Кланнока Маклеода.",al={"who runs fray island","who lives on fray island","fray island faction","кто управляет островом битв","кто живет на острове битв","фракция острова битв"}},{q="Как добраться до Острова Битв?",a="Остров Битв лежит в Великом море у восточного побережья Степей, к югу от Кабестана. Чтобы добраться до него, нужно долго плыть от материкового берега через воды, кишащие акулами и безумствующими хищниками.",al={"getting to fray island","where is fray island","how to get to fray island","как добраться до острова битв","где остров битв","путь на остров битв"}},{q="Что такое Побоище?",a="Побоище — испытание на выносливость, проходящее в бойцовской клетке острова. Воин должен встать на решетку и победить волны соперников, а затем одолеть бойца Большого Уилла.",al={"the affray","fray island arena","big will fight","побоище","арена острова битв","бой с большим уиллом"}}},fp="11,225,29.347.0,23.411.0,29.202.0,25.188.0,27.190.0,19.194.0"}
P.entries["subzone:frayfeather-highlands"] = {n="Высокогорье Блеклых Перьев",s="Высокогорье Блеклых Перьев — возвышенная глушь в густых лесах Фераласа. Это отдаленное плато — исконное место обитания и гнездовье диких гиппогрифов Блеклых Перьев. Отважные собиратели и натуралисты нередко рискуют встретиться с их воинственными стаями в поисках целых яиц гиппогрифов.",h="Высокогорье Блеклых Перьев — возвышенная глушь в густых лесах Фераласа.",kw={"eggs","feralas","frayfeather","gadgetzan","highlands","hippogryph","nests","яйца","фералас","блеклые перья","прибамбасск","высокогорье","гиппогриф","гнезда"},ang={["class:Druid"]="Друиды высоко чтят диких зверей Калимдора и видят в нетронутых гнездовьях Высокогорья Блеклых Перьев чистое отражение первозданной жизненной силы леса.",["race:NightElf"]="Ночные эльфы почитают гиппогрифов как священных спутников Элуны, поэтому дикие гнезда в Фераласе — важная природная среда, которую нужно оберегать от безрассудной эксплуатации."},sec={{t="Гнездовье гиппогрифов",b="Rising above the surrounding forest floor of Feralas, the Frayfeather Highlands are dominated by steep slopes and crags where wild hippogryphs raise their broods. The local flocks are notoriously aggressive toward intruders, fiercely defending the scattered nests tucked among the rock shelves. Because these beasts are so well adapted to the rugged cliffs, their nesting grounds have drawn significant interest from outsiders—most notably goblin entrepreneurs in distant Gadgetzan who seek unhatched eggs for study and profit."}},faq={{q="Какие существа обитают в Высокогорье Блеклых Перьев?",a="В высокогорье обитают в основном большие стаи диких гиппогрифов Блеклых Перьев, которые гнездятся на высоких скалах и агрессивно защищают свою территорию от незваных гостей.",al={"frayfeather wildlife","what is here","frayfeather beasts","фауна блеклых перьев","что здесь есть","звери блеклых перьев"}},{q="Почему путешественников интересуют гнезда гиппогрифов?",a="В гнездах лежат редкие яйца гиппогрифов. Искатели приключений собирают пригодные яйца и доставляют их через Танарис в Прибамбасск, где гоблины перерабатывают их в Супер-Яйцо-Матике для исследований и наживы.",al={"hippogryph eggs","egg quest","why steal eggs","яйца гиппогрифов","задание на яйца","зачем красть яйца"}},{q="Где находится Высокогорье Блеклых Перьев?",a="Высокогорье расположено в южной части Фераласа, над основным пологом джунглей, и отличается скалистыми склонами и открытыми гнездовыми уступами.",al={"frayfeather location","where is frayfeather highlands","how to find frayfeather","где блеклые перья","где высокогорье блеклых перьев","как найти высокогорье блеклых перьев"}}},fp="21,293,24.529.0,49.177.0,53.200.0,44.167.0"}
P.entries["subzone:freewind-post"] = {n="Застава Вольного Ветра",s="Застава Вольного Ветра — главный оплот Орды в Тысяче Игл, расположенный высоко на одной из величественных каменных столовых гор каньона. Попасть туда можно в основном на подъемнике тауренов и по извилистым веревочным мостам; застава служит защитным убежищем от военных отрядов кентавров и важным передовым пунктом.",h="Застава Вольного Ветра — главный оплот Орды в Тысяче Игл, расположенный высоко на одной из величественных...",kw={"darkcloud pinnacle","elevator","freewind post","galak","highperch","mesa","tauren","thousand needles","wyverns","пик темного облака","подъемник","застава вольного ветра","галак","скальное гнездовье","столовая гора","таурен","тысяча игл","виверны"},ang={["faction:Horde"]="Застава Вольного Ветра — единственное крупное убежище Орды и пункт полетов между Южными степями и Танарисом, обеспечивающий важную логистическую поддержку в центральном Калимдоре.",["race:Tauren"]="Застава Вольного Ветра демонстрирует архитектурную изобретательность шу'хало: они приспособили высоты мезы, чтобы не пускать традиционных кентавров-мародеров, и при этом ухаживают за древними наездничьими вивернами утесов."},sec={{t="Крепость в небесах",b="Застава Вольного Ветра построена прямо на столовых горах каньона и полагается на изобретательность и высоту для защиты своих жителей. Кентавры Галака господствуют на засушливом дне каньона внизу, но не могут ни взобраться на высокие утесы, ни взять тяжелые деревянные подъемники, поднимающие путников Орды в небо. Лабиринт веревочных и дощатых мостов соединяет Вольный Ветер с соседними шпилями, образуя надежное гнездовье. Помимо отражения набегов кентавров застава сдерживает визгливых гарпий, гнездящихся на утесах, и ухаживает за землями виверн в Скальном гнездовье, где диких яиц отбирают и выращивают верных наездников на ветрокрылах для Орды."},{t="Тени Пика Темного Облака",b="Несмотря на неприступную высоту, Застава Вольного Ветра сталкивается с растущей напряженностью в отношениях с северо-западными соседями: племенем Зловещего Тотема, обосновавшимся на Пике Темного Облака. Прежде терпимые как упрямые приверженцы традиций, Зловещие Тотемы под началом вождя Арнака все чаще прибегают к насилию, похищениям и убийствам. Подозрительные ритуалы и слухи о темной силе окружают соседние вершины. Местные таурены тревожно следят за небом и веревочными мостами, ведь самые опасные враги бродят не по соляным равнинам внизу, а засели по другую сторону каньонных ветров."}},faq={{q="Почему Застава Вольного Ветра построена так высоко на столовой горе?",a="Вертикальная планировка защищает поселение от враждебных отрядов кентавров Галака, патрулирующих дно каньона. Кентавры сильны на ровной местности, но не могут взобраться на отвесные утесы или легко взять механические деревянные подъемники тауренов.",al={"why is freewind post in the sky","why mesa","freewind post elevation","почему застава вольного ветра в небе","почему на столовой горе","высота заставы вольного ветра"}},{q="Как подняться на заставу и спуститься с нее?",a="Большинство путников пользуются большими механическими деревянными подъемниками у подножия главной столовой горы. Есть и запасной путь — опасная цепочка веревочных мостов и деревянных пандусов между соседними скальными столбами, но неосторожный шаг может обернуться смертельным падением на дно каньона.",al={"how to get up freewind post","freewind post elevator","freewind entrance","как подняться на заставу вольного ветра","подъемник заставы вольного ветра","вход на заставу вольного ветра"}},{q="Каковы отношения между Заставой Вольного Ветра и племенем Зловещего Тотема?",a="Отношения крайне напряженные. Зловещий Тотем, занимающий Пик Темного Облака к северо-западу от Застава Вольного Ветра, обвиняют в убийствах, похищениях и беспричинной враждебности к другим тауренам, из-за чего защитники заставы пребывают в тихой настороженности перед соседями-сородичами.",al={"grimtotem freewind post","darkcloud pinnacle freewind","why are grimtotem bad here","зловещий тотем застава вольного ветра","пик темного облака застава","почему зловещий тотем здесь плохие"}},{q="Какое значение имеет Скальное гнездовье для заставы?",a="Скальное гнездовье — исконное гнездовье диких виверн прямо через каньон. Таурены с Заставы Вольного Ветра наблюдают за этими существами и отбирают яйца из гнезд, которые затем выхаживают и выращивают как ездовых ветрокрылов для всей Орды.",al={"why highperch","highperch wyverns freewind","почему скальное гнездовье","виверны скального гнездовья"}}},fp="13,279,21.659.0,31.565.1,48.245.0,41.297.0,65.276.0,48.249.0"}
P.entries["subzone:frostmane-hold"] = {n="Форт Мерзлогривов",s="Форт Мерзлогривов — укрепленный лагерь и пещерный комплекс ледяных троллей из племени Мерзлогривов на западе Дун Морога. Он расположен среди скал к югу от Гномрегана и служит главным сборным пунктом троллей-налетчиков, вторгающихся на земли дворфов. Стальгорнская стража внимательно наблюдает за фортом, оценивая растущую угрозу со стороны троллей.",h="Форт Мерзлогривов — укрепленный лагерь и пещерный комплекс ледяных троллей из племени Мерзлогривов на западе...",kw={"dun morogh","frostmane","frostmane hold","headhunter","hideskinner","ice troll","kharanos","vejrek","дун морог","мерзлогрив","форт мерзлогривов","охотник за головами","свежеватель","ледяной тролль","каранос","веирек"},ang={["race:Dwarf"]="Мерзлогривы веками оспаривают Дун Морог, и зачистка Форта Мерзлогривов стала испытанием для горных пехотинцев, защищающих заснеженное сердце земель Стальгорна.",["race:Gnome"]="Расположенный к югу от Гномрегана, форт — еще один опасный враждебный рубеж рядом с осажденной бывшей столицей гномов."},sec={{t="Оплот троллей в снегах",b="Форт Мерзлогривов, высеченный в промерзших скалах западного Дун Морога, состоит из грубых построек под открытым небом и извилистой системы пещер. Для Племени Мерзлогривов это главный оплот, который плотно охраняют свежеватели и охотники за головами. Отсюда тролли совершают набеги на окрестные долины, проверяют на прочность оборону соседних поселений, например Караноса, и угрожают путникам на горных перевалах."},{t="Заноза для Караноса",b="По мере роста напряженности в Дун Мороге дворфийские командиры в Караносе все сильнее тревожатся из-за масштабов сбора Мерзлогривов. Молодых горцев и искателей приключений регулярно отправляют разведывать внутренние пещеры, наносить на карту укрепления и истреблять отряды, пока племя не собрало силы для организованного нападения на дворфийские форпосты."}},faq={{q="Кто живет в Форте Мерзлогривов?",a="Оплот занимает племя ледяных троллей Мерзлогривов — охотники, свежеватели и охотники за головами, а также их вожди и налетчики.",al={"who is in frostmane hold","frostmane hold mobs","trolls in frostmane hold","кто в форте мерзлогривов","мобы форта мерзлогривов","тролли в форте мерзлогривов"}},{q="Где находится Форт Мерзлогривов?",a="Он лежит в западных горах Дун Морога, к югу от промышленных руин Гномрегана и к западу от Караноса.",al={"frostmane hold location","where is frostmane hold","find frostmane hold","расположение форта мерзлогривов","где форт мерзлогривов","найти форт мерзлогривов"}},{q="Почему дворфов интересует эта пещера?",a="Дворфийские предводители в Караносе опасаются, что Мерзлогривы собираются в таком числе, что смогут устраивать серьезные набеги на поселения, поэтому военачальники посылают разведчиков наносить пещеры на карту и сокращать их ряды.",al={"why scout frostmane hold","kharanos troll quest","зачем разведывать форт мерзлогривов","задание про троллей каранос"}},{q="Есть ли в Форте Мерзлогривов трогги?",a="Нет. В наше время оплот безраздельно принадлежит ледяным троллям Мерзлогривам. Активность троггов в Дун Мороге в основном сосредоточена вокруг их собственных логовищ и руин Гномрегана.",al={"troggs frostmane hold","rockjaw frostmane","трогги форт мерзлогривов","каменная челюсть мерзлогривы"}}},fp="14,338,28.417.0,25.349.0,28.164.0,32.122.0,44.207.0,35.189.0"}
P.entries["subzone:frostmane-hovel"] = {n="Пещера Мерзлогривов",s="Пещера Мерзлогривов — суровое пещерное логово в южных скалах Холодной долины в Дун Мороге. Это укрепленное убежище агрессивных троллей Мерзлогривов, наступающих прямо на тренировочные земли дворфов.",h="Пещера Мерзлогривов — суровое пещерное логово в южных скалах Холодной долины в Дун Мороге.",kw={"anvilmar","coldridge valley","dun morogh","frostmane","hovel","trolls","старая наковальня","холодная долина","дун морог","мерзлогрив","пещера","тролли"},ang={["faction:Alliance"]="Постоянное присутствие Мерзлогривов прямо у Старой Наковальни показывает, что даже сердцу земель Стальгорна приходится непрестанно обороняться от местных врагов.",["race:Dwarf"]="Для молодых новобранцев Бронзобородов, обучающихся в Холодной долине, защита рубежей от враждебного Племени Мерзлогривов в таких пещерах — важное испытание."},sec={{t="Логово троллей в долине",b="Пещера Мерзлогривов, высеченная в южных горах у Холодной долины, дает приют коренным троллям Мерзлогривам, не желающим уступать Стальгорну высокие снега. Из таких грубых пещер тролли непрерывно нападают на местные лагеря дворфов и нарушают снабжение долины."}},faq={{q="Что такое Пещера Мерзлогривов?",a="Пещера Мерзлогривов — природная пещера на юге Холодной долины, которую коренные тролли Мерзлогривы, вторгающиеся на земли дворфов, используют как лагерь на время непогоды.",al={"frostmane hovel","what is this cave","coldridge troll cave","пещера мерзлогривов","что за пещера","пещера троллей холодная долина"}},{q="Почему в Холодной долине есть тролли?",a="Племя Мерзлогривов испокон веков живет на заснеженных вершинах Дун Морога. Будучи заклятыми врагами дворфов Бронзобородов, они постоянно спускаются с высоких хребтов, чтобы грабить тропы снабжения и бросать вызов поселениям дворфов.",al={"why trolls here","dun morogh trolls","frostmane presence","почему здесь тролли","тролли дун морога","присутствие мерзлогривов"}},{q="Кто управляет этой пещерой?",a="Пещеру занимают тролли-налетчики Мерзлогривы, которые используют укрытую расщелину для вторжений через южный уступ долины.",al={"who leads the cave","who lives in frostmane hovel","кто главный в пещере","кто живет в пещере мерзлогривов"}}},fp="15,218,25.313.0,28.167.0,41.227.0,23.139.0"}
P.entries["subzone:frostsaber-rock"] = {n="Уступ Ледопардов",s="Уступ Ледопардов — высокая каменная скала над заснеженными северными просторами Зимних Ключей. Это главное убежище и место обучения благородных ледопардов этого края.",h="Уступ Ледопардов — высокая каменная скала над заснеженными северными просторами Зимних Ключей.",kw={"alliance mount","frostsaber","frostsaber rock","rexxar","rivern frostwind","wintersaber","winterspring","скакун альянса","ледопард","уступ ледопардов","рексар","риверн холодный ветер","зимний саблезуб","зимние ключи"},ang={["class:Hunter"]="Скала и ее склоны — вдохновляющее место для охотников, желающих понаблюдать за самыми свирепыми хищниками северного Калимдора.",["faction:Alliance"]="Герои Альянса, заслужившие доверие Риверна Холодного Ветра на вершине скалы, могут пройти трудный путь обучения, чтобы ездить на знаменитом ледопарде Зимних Ключей."},sec={{t="Насест в тундре",b="Уступ Ледопардов, возвышающийся над промерзшими пустошами севера Зимних Ключей, открывает широкий вид на заснеженные дикие земли. Скала названа в честь свирепых и величественных ледопардов, бродящих по склонам и долинам внизу. На самой вершине живет Риверн Холодный Ветер, одинокий ночной эльф, посвятивший себя воспитанию и уходу за этими зверями. Героям, верным Альянсу, которые готовы выдержать суровые условия и доказать свою преданность, Риверн дарит редкую возможность научиться выращивать, приручать и седлать одного из этих легендарных снежных скакунов."}},faq={{q="Кто живет на вершине Уступа Ледопардов?",a="Риверн Холодный Ветер разбил лагерь на самой вершине скалы. Он обучает обращению с местными ледопардами и наставляет представителей Альянса, желающих обрести ледопарда-спутника.",al={"who is at frostsaber rock","frostsaber rock trainer","rivern location","кто на уступе ледопардов","учитель на уступе ледопардов","где риверн"}},{q="Могут ли игроки Орды обучаться здесь приручению зверей?",a="Нет. Риверн Холодный Ветер предлагает обучение и зверей-спутников только доверенным союзникам Альянса. Путникам из Орды на вершине не рады.",al={"horde frostsaber rock","can horde get frostsaber","rivern horde","орда уступ ледопардов","может ли орда получить ледопарда","риверн орда"}},{q="Какие существа обитают вокруг скалы?",a="Ледяная скала и окрестные плато — дом диких ледопардов, которые бродят по заснеженной местности вместе с другими выносливыми зверями сурового климата Зимних Ключей.",al={"what lives here","frostsaber rock beasts","frostsabers in winterspring","кто здесь живет","звери уступа ледопардов","ледопарды в зимних ключах"}},{q="Бывал ли на этой вершине кто-нибудь известный?",a="Известно, что странствующий укротитель Рексар побывал в Зимних Ключах и поднимался на Уступ Ледопардов во время своих одиноких скитаний по Калимдору.",al={"rexxar frostsaber rock","who visited frostsaber rock","рексар уступ ледопардов","кто посещал уступ ледопардов"}}},fp="15,204,21.551.0,31.203.0,36.160.0,41.172.0,39.154.0"}
P.entries["subzone:frostwhisper-gorge"] = {n="Теснина Ледяного Шепота",s="Теснина Ледяного Шепота — студеный каньон в южном нагорье Зимних Ключей, лежащий прямо к северу от зловещей Теснины Зловещего Шепота. Его ледяное дно и окружающие скалы усеяны древними руинами ночных эльфов, а пропастью владеют могучие великаны Ледяного Молота. Высоко над восточным краем одинокий лагерь дворфа смотрит с обрыва на океан внизу.",h="Теснина Ледяного Шепота — студеный каньон в южном нагорье Зимних Ключей, лежащий прямо к северу от зловещей...",kw={"darkwhisper gorge","frostmaul","frostwhisper gorge","ironforge","winterspring","теснина зловещего шепота","ледяной молот","теснина ледяного шепота","стальгорн","зимние ключи"},ang={["race:Dwarf"]="Высоко на восточном краю расселины неизвестный дворф разбил лагерь с флагом Стальгорна, ружьем и запасом эля, чтобы любоваться бескрайним видом на океан.",["race:NightElf"]="В заснеженных глубинах теснины лежат разбитые остатки древних построек ночных эльфов, по которым теперь бродят великаны Ледяного Молота."},sec={{t="Ледяная расселина руин и великанов",b="Теснина Ледяного Шепота, высеченная в южных горах Зимних Ключей, служит преддверием населенных демонами глубин Теснины Зловещего Шепота. Ее заснеженное дно и скалистые гребни усыпаны забытой каменной кладкой древних поселений ночных эльфов. Ныне теснину занимают огромные великаны Ледяного Молота и их хранители. Спуск в ущелье опасен: великаны яростно защищают промерзшие скалы от любых забредших чужаков."},{t="Восточная смотровая",b="На узкой тихой тропе на вершине восточных утесов теснины скрывается любопытный лагерь. Путники, летящие на наездниках на вивернах или грифонах между Азшарой, Оргриммаром и Зимними Ключами, часто замечают его сверху: одинокий лагерь дворфа на самом краю мира. Под знаменем Стальгорна стоят ящики с припасами, бочки эля, удобное кресло и ружье, прислоненное к спинке, а отсюда открывается несравненный вид на обрыв и Великое море внизу."}},faq={{q="Какие существа обитают в Теснине Ледяного Шепота?",a="Дно каньона и окружающие террасы населяют могучие великаны Ледяного Молота и их хранители.",al={"monsters in frostwhisper gorge","what lives in frostwhisper gorge","frostwhisper mobs","монстры теснины ледяного шепота","кто живет в теснине ледяного шепота","мобы ледяного шепота"}},{q="Где находится Теснина Ледяного Шепота?",a="Она расположена на юге Зимних Ключей, в ледяных скалах к северу от Теснины Зловещего Шепота.",al={"frostwhisper gorge location","where is frostwhisper gorge","frostwhisper map","расположение теснины ледяного шепота","где теснина ледяного шепота","карта ледяного шепота"}},{q="Что за маленький лагерь дворфа на восточных утесах?",a="Tucked away high on the eastern ridge overlooking the gorge is a tranquil campsite flying an Ironforge banner. It consists of a chair, a rifle, supply crates, and copious amounts of booze looking over the cliff edge toward the sea.",al={"dwarf camp winterspring","ironforge flag frostwhisper","eastern cliff camp","лагерь дворфа зимние ключи","флаг стальгорна ледяной шепот","лагерь на восточном утесе"}},{q="Есть ли в теснине руины ночных эльфов?",a="Да. Разрушающиеся колонны и каменная кладка ночных эльфов разбросаны и по дну теснины, и по верхним гребням скал — остатки древних жилищ кальдорай.",al={"elven ruins frostwhisper","night elf architecture winterspring gorge","руины эльфов ледяной шепот","архитектура ночных эльфов теснина зимние ключи"}}},fp="18,371,34.477.0,20.511.0,42.110.0,36.110.0,51.231.0,44.167.0"}
P.entries["subzone:fungal-rock"] = {n="Пещера Лишайников",s="Пещера Лишайников — сырая пещерная впадина в северо-восточных скалах Кратера Ун'Горо. Здесь властвуют агрессивные приматы и густые заросли призрачных грибов, и это одно из самых опасных логовищ обезьян в кратере.",h="Пещера Лишайников — сырая пещерная впадина в северо-восточных скалах Кратера Ун'Горо.",kw={"a-me 01","crater","fungal rock","ghost mushroom","gorilla","u'cha","uhk'loc","un'goro","чи-та 3","кратер","пещера лишайников","призрачный гриб","горилла","у'ча","ухк'лок","ун'горо"},ang={["profession:Herbalism"]="Пещера Лишайников — одно из лучших мест в Кратере Ун'Горо для сбора призрачных грибов, хотя собирателям приходится сражаться со стаями территориальных горилл.",["race:Gnome"]="Гномов может привлечь Пещера Лишайников, чтобы выяснить судьбу Чи-Та 3 — амбициозного прототипа механической обезьяны Карны Сомнамбулер, оставленного у озерца возле входа."},sec={{t="Логово обезьян",b="Пещера Лишайников, скрытая за небольшим водопадом и озерцом на северо-восточном краю Кратера Ун'Горо, — главное логово огромных горилл этих мест. В сырых подземных коридорах среди зарослей редких призрачных грибов бродят могучие топтуны и громовые гориллы Ун'Горо. В глубочайших закоулках обитают территориальные исполины, в том числе могучий седой самец У'ча и неуловимая горилла-альбинос Ухк'лок. Помимо диких обитателей, у входа в пещеру любопытные путники могут наткнуться на рукотворные диковины, например Чи-Та 3 — поврежденную механическую обезьяну, брошенную гномами-исследователями."}},faq={{q="Что такое Пещера Лишайников?",a="Пещера Лишайников — большая система пещер в северо-восточной стене Кратера Ун'Горо. Она известна сыростью, обилием призрачных грибов и плотным населением враждебных горилл.",al={"where is fungal rock","what is fungal rock cave","где пещера лишайников","что за пещера лишайников"}},{q="Кто правит обезьянами в Пещере Лишайников?",a="В пещере господствует У'ча — огромный и сильный седой самец гориллы, живущий в самой глубокой пещере. Также известно, что по этим пещерам бродит редкая белая горилла Ухк'лок.",al={"who is u'cha","boss of fungal rock","fungal rock leader","кто такой у'ча","босс пещеры лишайников","вожак пещеры лишайников"}},{q="Почему у пещеры стоит механическая горилла?",a="Возле озерца у входа стоит Чи-Та 3 — механическая обезьяна, построенная гномом-исследователем Карной Сомнамбулер. Она сломалась во время полевых наблюдений и ждет, пока ее разберут или починят.",al={"what is a-me 01","robot gorilla ungoro","ame 01","что такое чи-та 3","робот горилла ун'горо","чи-та 3"}},{q="Какие ценные ресурсы растут в Пещере Лишайников?",a="Сырой, затененный интерьер пещеры идеален для призрачных грибов, поэтому это одно из немногих мест на юге Калимдора, где травники могут собирать этот востребованный гриб.",al={"ghost mushrooms ungoro","herbs in fungal rock","призрачные грибы ун'горо","травы в пещере лишайников"}}},fp="11,221,11.593.0,20.195.0,38.177.0,51.195.0,44.194.0"}
P.entries["subzone:fungal-vale"] = {n="Грибная долина",s="Грибная долина — глубоко зараженная низина на юге центральной части Восточных Чумных земель, к северу от Башни королевской стражи и Поместья Маррисов. Окутанная мутной дымкой и покрытая темно-фиолетовой землей, долина демонстрирует необузданную, мутирующую силу Чумы нежизни. Здесь кишат бродячие чудовища Плети и смертные служители Культа Проклятых.",h="Грибная долина — глубоко зараженная низина на юге центральной части Восточных Чумных земель, к северу от...",kw={"blight","crown guard tower","cult of the damned","eastern plaguelands","fungal vale","fungus","marris stead","plague of undeath","scourge","скверна","башня королевской стражи","культ проклятых","восточные чумные земли","грибная долина","гриб","поместье маррисов","чума нежизни","плеть"},ang={["class:Druid"]="Грибная долина — высшая насмешка над живой природой: естественный круговорот здесь сменила вечная нечестивая гниль, насаждаемая Плетью.",["profession:Herbalism"]="Зараженная, заросшая грибами земля — суровое предостережение о том, что некромантия делает с местной флорой Лордерона."},sec={{t="Сад гнили",b="Грибная долина, расположенная к северу от Поместья Маррисов, — один из самых глубоко оскверненных уголков Лордерона. Земля здесь приобрела болезненный фиолетовый цвет, вздулась чужеродными грибными наростами и тонет в вечной мутной дымке, которую рождают некротические споры. Чума нежизни не просто уничтожила местную экосистему, а извратила почву, заставив ее взращивать нечестивую флору, которая кормит чудовищных падальщиков и бредущую нежить. Члены Культа Проклятых часто бывают здесь: они ухаживают за зараженными цветами и совершают мерзкие обряды посреди противоестественного распада."}},faq={{q="Что такое Грибная долина?",a="Это оскверненная долина на юге Восточных Чумных земель, лежащая прямо к северу от Башни королевской стражи и Поместья Маррисов. Местность сильно заражена Чумой нежизни, которая превращает обычную растительность в разросшуюся грибную заразу.",al={"where is fungal vale","fungal vale lore","fungal vale overview","где грибная долина","грибная долина предыстория","грибная долина обзор"}},{q="Почему здесь фиолетовая земля?",a="Почва полностью пропитана Чумой нежизни. Вместо того чтобы дать растениям погибнуть окончательно, некротическая зараза превращает землю в плодородное ложе для губительных спор, окрашивая ее в цвет синяка.",al={"why is the ground purple","purple dirt plaguelands","fungal vale ground","почему земля фиолетовая","фиолетовая земля чумные земли","земля грибной долины"}},{q="Кто контролирует эту местность?",a="Грибная долина принадлежит Плети и смертным культистам из Культа Проклятых. Порождения нежити бродят в дымке рядом со служителями, которые пестуют оскверненную грибную экосистему.",al={"who is in fungal vale","fungal vale enemies","cultists fungal vale","кто в грибной долине","враги грибной долины","культисты грибной долины"}},{q="Где она находится относительно местных ориентиров?",a="Она лежит на юге центральной части Восточных Чумных земель, прямо к северу от дороги между Поместьем Маррисов и Башней королевской стражи.",al={"how to get to fungal vale","fungal vale location","near crown guard tower","как добраться до грибной долины","расположение грибной долины","рядом с башней королевской стражи"}}},fp="11,374,15.564.0,24.254.0,30.234.0,23.177.0,48.131.0"}
P.entries["subzone:gadgetzan"] = {n="Прибамбасск",s="Прибамбасск — обнесенный стеной пустынный центр Картеля Хитрая Шестеренка, остров торговли на севере Танариса. Город открыт как для Орды, так и для Альянса и придерживается строго соблюдаемого гоблинского нейтралитета, встречая любого, у кого есть монеты или непыльная работа.",h="Прибамбасск — обнесенный стеной пустынный центр Картеля Хитрая Шестеренка, остров торговли на севере Танариса.",kw={"auction house","gadgetzan","goblin","neutral","steamwheedle cartel","tanaris","wastewander","waterspring field","аукционный дом","прибамбасск","гоблин","нейтральный","картель хитрая шестеренка","танарис","дикие скитальцы","родниковое поле"},ang={["profession:Blacksmithing"]="В городе есть мощные кузницы и наковальни, которые любят опытные металлисты; он служит важным опорным пунктом для членов Ордена Мифрила.",["profession:Engineering"]="Прибамбасск — важный перекресток для изобретателей: здесь есть опытные учителя, редкие схемы и телепортационная площадка прибытия, настроенная специально для гномов-инженеров."},sec={{t="Оплот выгоды среди дюн",b="Окруженный раскаленными песками, Прибамбасск служит региональным центром предприятий Картеля Хитрая Шестеренка на юге Калимдора. Построенный с характерной гоблинской изобретательностью и беспорядочной архитектурой, город располагает независимым аукционным домом, банком, гостиницей и мастерскими для инженеров, кузнецов и алхимиков. Здесь есть и распорядители полетов для обеих основных фракций, что обеспечивает постоянный поток искателей приключений, направляющихся в Танарис, Фералас и дикую котловину Ун'Горо. Превыше всего здесь торговля: пока посетители держат оружие в ножнах, а кошельки открытыми, в стенах города они в безопасности."},{t="Пустынные беды и насаждаемый порядок",b="Мир в Прибамбасске поддерживается не доброй волей, а хорошо вооруженными гоблинскими громилами, которые быстро расправляются с теми, кто угрожает торговле или затевает стычки между фракциями. Но за воротами жизнь опасна. Водная компания Прибамбасска постоянно воюет с бандитами Диких Скитальцев, безжалостной шайкой, занявшей важное Родниковое поле. Вода в Танарисе — жидкое золото, и картель часто нанимает посторонних наемников, чтобы устранить главарей бандитов и вернуть украденные бурдюки с водой, не давая иссякнуть городским резервуарам."}},faq={{q="Могут ли Альянс и Орда нападать друг на друга в Прибамбасске?",a="Нет. Прибамбасск — строго нейтральная территория Картеля Хитрая Шестеренка. Гоблинские громилы усиленно патрулируют город и немедленно нападут на любого, кто нарушит мир или начнет насилие против других путников.",al={"is gadgetzan safe","pvp in gadgetzan","can horde and alliance fight here","безопасен ли прибамбасск","пвп в прибамбасске","могут ли орда и альянс драться здесь"}},{q="Почему вода здесь так важна?",a="Расположенный посреди засушливой пустыни, Прибамбасск целиком зависит от водозаборных башен Водной компании Прибамбасска на Родниковом поле. Бандиты Диких Скитальцев захватили эти колодцы, лишив город основного источника воды и вынудив гоблинов платить награды за украденные бурдюки с водой.",al={"gadgetzan water company","why water pouches","waterspring field conflict","водная компания прибамбасска","зачем бурдюки с водой","конфликт на родниковом поле"}},{q="Кто управляет Прибамбасском?",a="Прибамбасск принадлежит Картелю Хитрая Шестеренка и управляется им — крупнейшей и самой влиятельной торговой гоблинской организацией Азерота.",al={"who runs gadgetzan","gadgetzan faction","what cartel owns gadgetzan","кто управляет прибамбасском","фракция прибамбасска","какой картель владеет прибамбасском"}},{q="Чем особенен здешний аукционный дом?",a="В отличие от фракционных рынков Оргриммара или Штормграда, в Прибамбасске действует нейтральный аукционный дом. Игроки Альянса и Орды могут покупать и продавать друг другу товары, хотя за эту возможность гоблины берут гораздо более высокий сбор.",al={"gadgetzan auction house","neutral auction house","cross faction ah","аукционный дом прибамбасска","нейтральный аукцион","аукцион между фракциями"}}},fp="9,283,32.645.0,34.527.0,54.228.0,41.290.0,23.133.0,42.256.0"}
P.entries["subzone:gahrron-s-withering"] = {n="Пустошь Гаррона",s="Пустошь Гаррона — оскверненная усадьба на восточной границе Западных Чумных земель, у дороги в Восточные Чумные земли. Некогда процветающий участок лордеронских угодий под названием Оживление Гаррона, теперь она занята Плетью и держится на огромном котле, выпускающем в воздух ядовитые чумные пары.",h="Пустошь Гаррона — оскверненная усадьба на восточной границе Западных Чумных земель, у дороги в Восточные...",kw={"cauldron","darrowshire","del gahrron","gahrron","gahrron's withering","joseph redpath","quickening","soulwrath","котел","дарроушир","дел гаррон","гаррон","пустошь гаррона","джозеф редпат","оживление","душегнев"},ang={["class:Paladin"]="Мерзкие испарения из котла Хранителя котла Душегнева и неупокоенные мертвецы на разоренных полях делают эту ферму первоочередной целью для священного очищения.",["faction:Alliance"]="Для ветеранов Альянса ферма имеет мрачное значение: именно здесь павшего героя Дарроушира Джозефа Редпата пришлось добить его же соотечественникам."},sec={{t="От оживления к упадку",b="До того как Третья война погубила королевство Лордерон, это поместье называлось Оживление Гаррона по имени своего хозяина, Дела Гаррона. Его плодородные поля давали зерно всему королевству, пока по земле не прокатились Культ Проклятых и Плеть. Усадьба, переименованная в Пустошь Гаррона в горькую насмешку над былой жизненной силой, ныне разрушена и заброшена. Призрачные видения, воющие привидения и неупокоенные духи бродят среди разрушенных построек под надзором надсмотрщиков Плети, присягнувших Королю-личу."},{t="Котел и гибель Редпата",b="В центре зараженных полей стоит один из огромных чумных котлов Плети, за которым присматривает Хранитель котла Душегнев. Этот котел постоянно изрыгает в воздух ядовитые миазмы, отравляя землю и изгоняя все живое. Помимо распространения заразы, ферма отмечает трагическую развязку соседней трагедии Дарроушира: именно здесь защитники Альянса настигли и сразили капитана Джозефа Редпата, павшего жертвой темной порчи. Разбитый щит воина остался лежать среди проклятой земли."}},faq={{q="Как называлась Пустошь Гаррона до чумы?",a="До падения Лордерона ферма называлась Оживление Гаррона. Это была действующая усадьба Дела Гаррона, пока Плеть не опустошила окрестности.",al={"original name","old name","gahrrons quickening","прежнее название","старое название","оживление гаррона"}},{q="Почему здесь огромный котел?",a="Котел — орудие мора, развернутое Плетью для распространения чумных паров по региону. Хранитель котла Душегнев охраняет устройство, чтобы оно непрерывно заражало землю и воздух.",al={"plague cauldron","what does the cauldron do","pot in field","чумной котел","что делает котел","котел в поле"}},{q="Кем был Джозеф Редпат и почему он важен для этого места?",a="Капитан Джозеф Редпат был защитником соседнего Дарроушира, павшим жертвой скверны во время резни, которую Плеть устроила в городе. Силы Альянса наконец загнали в угол и сразили его оскверненный облик на этой усадьбе, а щит остался лежать в грязи.",al={"redpath shield","captain redpath","darrowshire connection","щит редпата","капитан редпат","связь с дарроуширом"}},{q="Кто сейчас контролирует Пустошь Гаррона?",a="Ферма прочно удерживается Плетью. Ее населяют призрачные духи, воющие мертвецы и жуткие видения, а всеми ими командует могущественный некромант Хранитель котла Душегнев.",al={"who is here","mobs at gahrron","scourge in charge","кто здесь","монстры у гаррона","плеть главная"}}},fp="19,333,24.508.0,36.567.1,54.168.0,35.205.0,51.242.1,43.187.0"}
P.entries["subzone:galardell-valley"] = {n="Долина Галарделл",s="Долина Галарделл — суровый, опасный каньон в северо-восточных возвышенностях Красногорья. Ущелье наводнено агрессивными стаями гноллов и лежит в тени печально известной Башни Илгалара.",h="Долина Галарделл — суровый, опасный каньон в северо-восточных возвышенностях Красногорья.",kw={"fangore","galardell valley","gnolls","morganth","redridge","tower of ilgalar","фангор","долина галарделл","гноллы","моргант","красногорье","башня илгалара"},ang={["faction:Alliance"]="Изнуренная городская стража Приозерья не может обезопасить северо-восточную дорогу, пока стаи гноллов и темное присутствие Морганта удерживают Долину Галарделл."},sec={{t="Логово зверей и тьмы",b="Долина Галарделл, врезанная в северо-восточные утесы Красногорья, полностью вышла из-под контроля защитников Приозерья. Свирепые гноллы Красногорья рыщут по низинам и стоят лагерями на дне каньона под началом жестоких вожаков, таких как лейтенант Фангор. Высоко над ущельями возвышается мрачный шпиль Башни Илгалара, оплота мага-отступника Морганта, из-за чего вся долина постоянно внушает ужас окрестным поселениям."}},faq={{q="Где находится Долина Галарделл?",a="Долина Галарделл лежит в самом северо-восточном углу Красногорья, спрятавшись за высокими скалами за дорогами, ведущими на север от Озера Безмолвия.",al={"galardell valley location","where is galardell valley","how to find galardell valley","расположение долины галарделл","где долина галарделл","как найти долину галарделл"}},{q="Какие существа обитают в долине?",a="Долина наводнена кровожадными стаями гноллов, которые плотными группами патрулируют тропы под началом опасных громил вроде лейтенанта Фангора.",al={"mobs in galardell valley","who lives in galardell valley","galardell enemies","монстры долины галарделл","кто живет в долине галарделл","враги галарделл"}},{q="Что за темная башня возвышается над долиной?",a="Это Башня Илгалара, внушительное каменное строение, служащее опорным пунктом чародея-отступника Морганта.",al={"galardell valley tower","spire above galardell","tower near gnolls redridge","башня долины галарделл","шпиль над галарделл","башня возле гноллов красногорья"}},{q="Кто такой лейтенант Фангор?",a="Лейтенант Фангор — грозный вожак гноллов, стоящий в долине. Известный хитростью и свирепостью, он при вызове воет, призывая на помощь соседние стаи гноллов, и быстро одолевает неосторожных путников.",al={"fangore","lieutenant fangore","galardell valley boss","фангор","лейтенант фангор","босс долины галарделл"}}},fp="16,218,26.483.0,34.167.0,34.139.0,46.128.0,26.213.0"}
P.entries["subzone:gallery-of-treasures"] = {n="Галерея сокровищ",s="Галерея сокровищ — богато украшенный и тщательно охраняемый коридор в залах Монастыря Алого ордена, соединяющий Двор охотника с Атенеумом. Стены галереи увешаны возвращенными картинами, реликвиями и иллюминированными рукописями; она демонстрирует богатство и наследие Лордерона, сохраненные Алым орденом посреди его фанатичной войны с нежитью.",h="Галерея сокровищ — богато украшенный и тщательно охраняемый коридор в залах Монастыря Алого ордена...",kw={"athenaeum","gallery of treasures","library","lordaeron relics","paintings","scarlet monastery","атенеум","галерея сокровищ","библиотека","реликвии лордерона","картины","монастырь алого ордена"},ang={["class:Paladin"]="Артефакты и знамена в этой галерее напоминают об утраченной славе Серебряной Длани и павшего Лордерона, но теперь ими владеют фанатики, превратившие праведную убежденность в неразборчивый фанатизм.",["race:Undead"]="Картины и исторические реликвии, хранящиеся здесь, принадлежали предкам Отрекшихся; их ревниво охраняют живые рыцари ордена, стремящиеся истребить бывших жителей Лордерона."},sec={{t="Хранилище утраченного наследия",b="Галерея сокровищ расположена в глубине библиотечного крыла Монастыря Алого ордена и служит большим залом, соединяющим псарни Двора охотника со священными архивами Атенеума. В отличие от собачьих загонов двора, этот коридор украшен изысканными картинами, историческими артефактами и небольшими комнатами с книгами, спасенными со всего павшего королевства Лордерон. Для Алого ордена эти реликвии — незапятнанное наследие человечества, которое они поклялись защищать и которое яростно охраняют от всех чужаков, посмевших вторгнуться в их святилище."}},faq={{q="Где находится Галерея сокровищ?",a="Она находится в библиотечном крыле Монастыря Алого ордена. Галерея расположена сразу за Двором охотника и является последним украшенным проходом перед Атенеумом.",al={"gallery location","where is gallery of treasures","how to find gallery of treasures","расположение галереи","где галерея сокровищ","как найти галерею сокровищ"}},{q="Что хранится в Галерее сокровищ?",a="В галерее хранятся сохраненные произведения искусства, исторические реликвии, иллюминированные рукописи и картины, спасенные из разрушенного королевства Лордерон; они выставлены вдоль коридора и в соседних читальных комнатах.",al={"what is in gallery of treasures","gallery loot","gallery relics","что в галерее сокровищ","добыча галереи","реликвии галереи"}},{q="Зачем Алый орден собирает эти сокровища?",a="Алый орден считает себя истинным наследником Лордерона. Спасая и накапливая эти произведения культуры, его члены сохраняют память и священное наследие своей родины, очищая земли от того, что считают скверной.",al={"why do scarlet have treasures","crusade relics purpose","зачем алому ордену сокровища","цель реликвий ордена"}},{q="Кто охраняет галерею?",a="Коридор патрулируют разные фанатики Алого ордена, в том числе защитники и послушники, охраняющие путь к Чародею Доану и глубинным архивам монастыря.",al={"gallery mobs","who is in gallery of treasures","монстры галереи","кто в галерее сокровищ"}}},fp="20,342,29.584.0,42.194.0,41.200.0,53.234.0,23.187.0"}
P.entries["subzone:gallows-end-tavern"] = {n="Таверна \"Петля висельника\"",s="Таверна «Петля висельника» — главный постоялый двор Брилла и центр гостеприимства Отрекшихся в Тирисфальских лесах. Помимо крова и выпивки для усталых путников, она служит важным узлом для наставников классов, учителей профессий и тайных допросов.",h="Таверна «Петля висельника» — главный постоялый двор Брилла и центр гостеприимства Отрекшихся в Тирисфальских...",kw={"brill","forsaken","gallows end","gallows' end tavern","innkeeper","scarlet zealot","tirisfal glades","undead","брилл","отрекшиеся","петля висельника","таверна петля висельника","трактирщик","фанатик алого ордена","тирисфальские леса","нежить"},ang={["faction:Alliance"]="Под полом общего зала Отрекшиеся держат пленных разведчиков Альянса и фанатиков Алого ордена для получения сведений и допросов.",["race:Undead"]="Как первый крупный постоялый двор за пределами Могильника, Таверна «Петля висельника» служит культурным и практическим перекрестком для недавно пробудившихся Отрекшихся, выходящих в большой мир."},sec={{t="Место сбора мертвых",b="Таверна «Петля висельника» стоит у дороги в Брилле и служит главным местом сбора недавно пробудившихся Отрекшихся, покидающих Могильник и идущих на юг к Подгороду. Несмотря на свою нежизнь, Отрекшиеся по-прежнему приходят сюда пообщаться, поторговать и найти убежище. В таверне работают наставники разных классов — для юных воинов, жрецов, магов, разбойников и чернокнижников, — а также торговцы и лекари."},{t="Тайны подвала",b="Под скрипучими половицами и смехом таверны скрывается куда более мрачное назначение. В подвалах Отрекшиеся держат связанных и охраняемых военнопленных вдали от посторонних глаз. Среди них — плененный фанатик Алого ордена и дворф-горец; их держат под таверной для допросов и опытов, пока Отрекшиеся защищают свои границы и от фанатичных рыцарей, и от разведчиков Альянса."}},faq={{q="Где находится Таверна «Петля висельника»?",a="Она находится в центре Брилла, главного поселения Отрекшихся к северу от Подгорода в Тирисфальских лесах.",al={"gallows end location","where is gallows end tavern","brill inn location","расположение петли висельника","где таверна петля висельника","таверна брилла"}},{q="Зачем нежити постоялый двор или таверна?",a="Хотя Отрекшимся не нужны сон и обычная пища, такие таверны, как «Петля висельника», поддерживают социальные связи и культурные привычки прошлой жизни. Кроме того, это надежный общественный центр для обучения, торговли и официальных дел.",al={"why do undead drink","why do forsaken need taverns","undead inn lore","зачем нежити пить","зачем отрекшимся таверны","таверна нежити"}},{q="Кто заключен в подвале?",a="В подвалах под таверной Отрекшиеся держат пленных врагов, среди которых фанатик из враждебного Алого ордена и дворф-горец Альянса.",al={"tavern prisoners","who is in the cellar","brill tavern dungeon","узники таверны","кто в подвале","темница таверны брилла"}},{q="Какие услуги и учителя здесь есть?",a="В таверне есть наставники для воинов, жрецов, магов, разбойников и чернокнижников, учителя первой помощи и зачарования, торговцы разными товарами и трактирщик.",al={"gallows end trainers","who trains in brill inn","tavern vendors","учителя петли висельника","кто учит в таверне брилла","торговцы таверны"}}},fp="19,258,30.446.0,21.405.0,41.114.0,40.248.0,34.165.0,45.170.0"}
P.entries["subzone:gaping-chasm"] = {n="Зияющая бездна",s="Зияющая бездна — обширный улей силитидов, вырытый глубоко в песках юго-востока Танариса. Его населяют агрессивные насекомоподобные чудовища выводка Хаззали; он служит мрачным предупреждением о растущей угрозе силитидов, расползающейся за пределы западных пустынь.",h="Зияющая бездна — обширный улей силитидов, вырытый глубоко в песках юго-востока Танариса.",kw={"fizzledowser","gaping chasm","hazzali","hive","sandreaver","scrimshank","silithid","tanaris","рудознатец","зияющая бездна","хаззали","улей","песчаный разоритель","костеглыб","силитиды","танарис"},ang={["profession:Mining"]="В открытых подземных расселинах и просевшей земле улья силитидов порой обнаруживаются богатые залежи руды, но добыча требует отбиваться от десятков свирепых роющих насекомых.",["race:Gnome"]="Печальная гибель младшего геодезиста Костеглыба в бездне — суровое напоминание, что полевые исследования в Калимдоре требуют не только научного любопытства, но и серьезной огневой мощи."},sec={{t="Улей в дюнах",b="Прорезая холмистые просторы Танариса, Зияющая бездна уходит вниз, в кишащий подземный лабиринт туннелей, смолистых холмов и дергающихся панцирей. Этот улей принадлежит Хаззали — агрессивному выводку силитидов, зарывшемуся под пустынные пустоши. Из-за подземных жалоносцев, роев и громадных песчаных разорителей любые путники и искатели сокровищ, глупо спустившиеся в бездну, быстро становятся добычей или оказываются в липких коконах."},{t="Могила геодезиста",b="Растущий улей привлек внимание предприимчивых умов Прибамбасска, и Старший геодезист Рудознатец отправил в яму своего младшего геодезиста Костеглыба, чтобы нанести на карту и измерить геологические сдвиги, вызванные туннелями насекомых. Ожидаемо, экспедиция закончилась катастрофой. Костеглыб встретил мрачный конец среди стрекочущих выводков, оставив после себя разбросанное снаряжение и измерительные приборы, предостерегающие от недооценки угрозы силитидов."}},faq={{q="Какие существа обитают в Зияющей бездне?",a="Бездна целиком заражена силитидами Хаззали. В улье есть множество каст этих насекомых: рабочие трутни, крылатые жалоносцы, неисчислимые рои и огромные песчаные разорители в хитиновой броне.",al={"what lives in gaping chasm","bugs in tanaris chasm","gaping chasm mobs","кто живет в зияющей бездне","жуки в танарисе","монстры зияющей бездны"}},{q="Где находится Зияющая бездна?",a="Бездна лежит на юго-востоке Танариса, вырытая в песках пустыни к югу от Прибамбасска и к востоку от горного хребта, отделяющего Танарис от западной глуши.",al={"where is gaping chasm","gaping chasm location","how to find gaping chasm","где зияющая бездна","расположение зияющей бездны","как найти зияющую бездну"}},{q="Почему гнома-геодезиста отправили в бездну?",a="Старший геодезист Рудознатец из Прибамбасска отправил младшего геодезиста Костеглыба обследовать пещеру и оценить ее геологическую активность. К сожалению, Костеглыба одолели и убили силитиды Хаззали, прежде чем он выполнил задание.",al={"who was scrimshank","fizzledowser surveyor quest","why did scrimshank go there","кто такой костеглыб","задание геодезиста рудознатца","зачем костеглыб пошел туда"}},{q="Связаны ли здешние силитиды с теми, что обитают в других частях Калимдора?",a="Да. Силитиды Хаззали в Танарисе имеют ту же насекомую природу и структуру коллективного разума, что и выводки на юге Степей и в оскверненных пустошах Силитуса на западе, что говорит об опасном, согласованном расширении по югу Калимдора.",al={"are these silithid connected to silithus","why are bugs in tanaris","связаны ли силитиды с силитусом","почему жуки в танарисе"}}},fp="12,257,21.484.0,18.469.0,45.216.0,34.169.0,45.248.1,69.252.0"}
P.entries["subzone:garrison-armory"] = {n="Мастерские Гарнизона",s="Мастерские Гарнизона — рудник Альянса, вырубленный в холмах к юго-западу от Крепости Стражей Пустоты в Выжженных землях. Шахтеры и инженеры разрабатывают подземные жилы и добывают ценные минералы, снабжая одинокую крепость и отправляя сырье в Штормград. Это важнейший промышленный источник жизни в бесплодной выжженной глуши.",h="Мастерские Гарнизона — рудник Альянса, вырубленный в холмах к юго-западу от Крепости Стражей Пустоты в...",kw={"blasted lands","garrison armory","mine","nethergarde","nethergarde engineer","nethergarde keep","nethergarde miner","stormwind","выжженные земли","мастерские гарнизона","рудник","крепость стражей пустоты","инженер крепости стражей пустоты","шахтер крепости стражей пустоты","штормград"},ang={["faction:Alliance"]="Работники Мастерских неустанно трудятся, чтобы Крепость Стражей Пустоты не знала нехватки оружия, брони и товаров для обмена и могла нести свой одинокий дозор.",["profession:Mining"]="В штольнях Мастерских Гарнизона скрыты ценные жилы минералов, вырубленные в камне суровых Выжженных земель, из-за чего этот подземный карьер оспаривают."},sec={{t="Источник жизни в красных пустошах",b="Содержание постоянного гарнизона в засушливых пустошах Выжженных земель требует непрерывного снабжения, а Крепость Стражей Пустоты не может полагаться только на долгие обозы из Штормграда. Мастерские Гарнизона — главная промышленная выработка крепости. Шахтеры крепости под надзором бригадиров и при помощи инженеров трудятся в подземных штольнях, добывая ценные минералы. Добытая здесь руда идет напрямую кузнецам и укреплениям крепости либо отправляется в столицу в обмен на продовольствие, инструменты и припасы, необходимые крепости, чтобы нести дозор у Темного портала."},{t="Уязвимое производство",b="Поскольку мастерские расположены вдали от главных стен Крепости Стражей Пустоты, выработка остается открытой суровым опасностям красной пустыни. Тролли, огры и дикие звери бродят среди окрестных скал, а лазутчики Орды пристально следят за добычей руды в крепости. Работники в туннелях трудятся под вооруженной охраной: они знают, что любой сбой в работе мастерских напрямую угрожает способности крепости нести дозор на выжженном рубеже."}},faq={{q="Для чего нужны Мастерские Гарнизона?",a="Мастерские Гарнизона — горнодобывающий комплекс Альянса, которым управляет Крепость Стражей Пустоты. Рабочие добывают под землей металлы и минералы, чтобы содержать крепость и обменивать их в Штормграде на необходимые продовольствие и снаряжение.",al={"garrison armory purpose","what is this mine","why is there a mine here","назначение мастерских гарнизона","что это за рудник","почему здесь рудник"}},{q="Кто работает в мастерских?",a="Рудник обслуживают шахтеры, инженеры и бригадиры крепости, связанные с Альянсом. Они добывают рудные залежи и поддерживают штольни под надзором командования Крепости Стражей Пустоты.",al={"who is inside","armory npcs","garrison miners","кто внутри","персонажи мастерских","шахтеры гарнизона"}},{q="Зачем Крепости Стражей Пустоты этот рудник?",a="Крепость Стражей Пустоты стоит в изоляции посреди безжизненных Выжженных земель, из-за чего регулярное снабжение затруднено. Добывая собственные металлы, крепость может чинить снаряжение, укреплять оборону и обменивать излишки сырья в Штормграде на жизненно важные припасы.",al={"why nethergarde needs it","armory importance","nethergarde resources","зачем он крепости стражей пустоты","значение мастерских","ресурсы крепости стражей пустоты"}},{q="Могут ли игроки Орды войти в Мастерские Гарнизона?",a="Мастерские заняты враждебными рабочими и стражами Альянса, но искатели приключений из Орды часто отваживаются спускаться вглубь, чтобы добыть богатые рудные жилы в штольнях.",al={"can horde go here","horde in garrison armory","is it safe for horde","может ли орда зайти сюда","орда в мастерских гарнизона","безопасно ли для орды"}}},fp="15,360,28.631.0,19.467.0,37.213.0,24.204.0,41.265.0,44.171.0"}
P.entries["subzone:gates-of-ironforge"] = {n="Врата Стальгорна",s="Врата Стальгорна — монументальный главный вход, ведущий путников из заснеженных горных долин Дун Морога в столицу дворфов. Вырубленные прямо в отвесной каменной стене горы, они охраняются изнутри колоссальной статуей верховного короля Модимуса Старой Наковальни.",h="Врата Стальгорна — монументальный главный вход, ведущий путников из заснеженных горных долин Дун Морога в...",kw={"commons","dun morogh","gates of ironforge","ironforge entrance","ironforge main gate","modimus anvilmar","общинный квартал","дун морог","врата стальгорна","вход в стальгорн","главные врата стальгорна","модимус старая наковальня"},ang={["faction:Alliance"]="Врата Стальгорна — один из самых укрепленных оплотов Альянса, практически неуязвимый для осады со стороны холодных долин Дун Морога.",["race:Dwarf"]="Стоя под величественным изваянием верховного короля Модимуса Старой Наковальни, каждый дворф вспоминает древнюю эпоху, когда все кланы жили под одной горой как единый род."},sec={{t="Порог горы",b="К Вратам Стальгорна поднимаются по извилистому укрепленному пандусу из центральной части Дун Морога, и они предстают величественным фасадом, видимым на большей части заснеженных низин. За огромным порталом посетители попадают в сам город, где их сразу встречает громадная каменная статуя верховного короля Модимуса Старой Наковальни — легендарного правителя, объединившего кланы дворфов до Войны трех молотов. Пройдя через эти врата, вы попадаете прямо в оживленный торговый район — Общинный квартал."}},faq={{q="Куда ведут Врата Стальгорна?",a="Они соединяют внешние горные земли Дун Морога с городом Стальгорн. Пройдя через порог, вы сразу окажетесь в юго-западной части Общинного квартала — оживленного торгового и банковского центра города.",al={"ironforge entrance","where do the gates go","gates of ironforge location","вход в стальгорн","куда ведут врата","где врата стальгорна"}},{q="Кого изображает статуя за вратами?",a="Монументальная скульптура сразу за входом изображает верховного короля Модимуса Старой Наковальни. Это был мудрый и почитаемый монарх, правивший всеми кланами дворфов, пока политические распри не раскололи их на Бронзобородов, Громовых Молотов и Черное Железо.",al={"ironforge gate statue","giant dwarf statue","who is the statue at the gate","статуя у врат стальгорна","гигантская статуя дворфа","кто статуя у врат"}},{q="Как добраться до врат из Дун Морога?",a="Из центральной части Дун Морога направляйтесь на север и поднимитесь по широкому укрепленному каменному пандусу, вырубленному в склоне горы. Пандус ведет прямо к внешнему порогу горной крепости.",al={"how to get into ironforge","path to ironforge gates","ironforge ramp","как попасть в стальгорн","путь к вратам стальгорна","пандус стальгорна"}}},fp="18,283,29.506.0,37.216.0,45.253.0,43.183.0"}
P.entries["subzone:gelkis-village"] = {n="Деревня Гелкис",s="Деревня Гелкис — главный оплот клана кентавров Гелкис, поклоняющихся земле, на юго-западе Пустошей. Поселение построено вокруг неровного ущелья, через которое переброшены деревянные мосты и проложены тропы по скалам, и охраняет южный путь к Фераласу. Оно господствует над главной дорогой с севера на юг, поэтому проход здесь опасен для любого путника, не заслужившего расположения клана.",h="Деревня Гелкис — главный оплот клана кентавров Гелкис, поклоняющихся земле, на юго-западе Пустошей.",ang={["faction:Horde"]="Поскольку поселение Черного Копья — Деревня Ночных Охотников — лежит прямо к западу на побережье, укрепленное присутствие Гелкис постоянно угрожает ближайшим предприятиям Орды.",["race:Tauren"]="Кентавры поколениями изгоняли таурен с их исконных земель; вид Гелкис, засевших в скалистых бастионах, горько напоминает о той неизменной угрозе, которую они представляют для Калимдора."},sec={{t="Крепость в ущелье",b="Gelkis Village sits in a deep, craggy gorge framed by precarious bluffs and rope bridges. Unlike the nomadic raiders of the Barrens, the Gelkis have fortified their ancestral grounds into a permanent settlement, complete with outposts spreading toward the border of Feralas. The heart of the clan's leadership lies within Bolgan's Hole, a cavern carved into the southern cliff face where Khan Shaka oversees his warriors. Travelers trekking south through Desolace must either cut a bloody path through the gorge or tread carefully, as the Gelkis view uninvited wanderers as fair game in their eternal war against their rival centaur brethren."}},faq={{q="Кто живет в Деревне Гелкис?",a="The settlement belongs to the Gelkis clan, one of the warring centaur tribes of Desolace. They are staunch earth-worshipers ruled by Khan Shaka, who resides deep in the cliffside cave known as Bolgan's Hole.",al={"gelkis residents","who controls gelkis village","centaur village south","жители гелкис","кто управляет деревней гелкис","кентавры на юге"}},{q="Почему кентавры Гелкис враждебны к чужакам?",a="Культура кентавров крайне территориальна и агрессивна к чужакам. Однако Гелкис больше всего ненавидят соперничающий клан — Маграм. Искатели приключений, охотящиеся на воинов Маграм, со временем могут заслужить доверие клана Гелкис и безопасно входить в деревню.",al={"why are gelkis attacking","gelkis hostile","can i be friendly with gelkis","почему гелкис нападают","гелкис враждебны","можно ли подружиться с гелкис"}},{q="Где находится Деревня Гелкис?",a="Она находится на юго-западе Пустошей, к востоку и чуть к югу от тролльего поселения — Деревни Ночных Охотников. Ее ущелья примыкают к южному горному склону и выходят на тропу, ведущую прямо на юг, в Фералас.",al={"gelkis location","how to find gelkis village","where is gelkis","расположение гелкис","как найти деревню гелкис","где гелкис"}},{q="Что такое Пещера Болгана?",a="Пещера Болгана — большая пещера, вырубленная в южной скальной стене ущелья и соединенная с остальной деревней высокими мостами и утесами. Это внутреннее святилище и средоточие власти хана Гелкис.",al={"bolgans hole","cave in gelkis village","where is gelkis khan","пещера болгана","пещера в деревне гелкис","где хан гелкис"}}},fp="14,382,24.642.0,28.207.0,48.264.0,32.221.0,22.223.0"}
P.entries["subzone:ghost-walker-post"] = {n="Застава Скитающихся Духов",s="Застава Скитающихся Духов — скромное поселение таурен в самом сердце Пустошей, рядом с древним Кладбищем кодо. Она гораздо сильнее подвержена местным опасностям, чем Деревня Ночных Охотников на западном побережье, и служит передовым оплотом Орды в борьбе с кланами кентавров и Пылающим Клинком.",h="Застава Скитающихся Духов — скромное поселение таурен в самом сердце Пустошей, рядом с древним Кладбищем кодо.",kw={"burning blade","centaur","desolace","ghost walker post","gurda wildmane","horde","kodo graveyard","shadowprey village","tauren","thrall","пылающий клинок","кентавр","пустоши","застава скитающихся духов","гурда буйногривая","орда","кладбище кодо","деревня ночных охотников","таурен","тралл"},ang={["class:Shaman"]="Под началом Гурды Буйногривой здешние шаманы совершают священный труд: говорят с древними духами и помогают умирающим животным перейти в мир духов.",["race:Tauren"]="Лагерь отражает глубокий священный долг таурен перед миром природы: он стоит стражем рядом с родовым местом упокоения кодо."},sec={{t="Дозор в пустошах",b="Застава Скитающихся Духов, расположенная на пыльных равнинах центральной части Пустошей, служит Орде суровым опорным пунктом на враждебной земле. В отличие от защищенной прибрежной рыбацкой гавани — Деревни Ночных Охотников, эта застава напрямую граничит с кочующими кентаврами-мародерами и поклоняющимися демонам сектантами Пылающего Клинка. Удобства здесь спартанские: путникам доступно лишь самое необходимое, а таверны и распорядителя полетов не видно. Несмотря на суровые условия, гарнизон таурен и отряд орков, присланный вождем Траллом, бдительно охраняют эти бесплодные земли."},{t="Стражи кладбища",b="Заставой руководит шаман-таурен Гурда Буйногривая, и ее духовное сердце тесно связано с соседним Кладбищем кодо. Шаманы, живущие здесь, ухаживают за умирающими животными, которые приходят сюда, чтобы испустить дух, помогают им перейти в следующую жизнь и общаются с их задержавшимися духами. Между духовным общением и постоянной боевой готовностью защитники заставы чтят древнюю связь таурен с могучими кодо среди пепла Пустошей."}},faq={{q="Что такое Застава Скитающихся Духов?",a="Это небольшая суровая застава Орды в центральной части Пустошей, основанная в основном тауренами при поддержке орочьего гарнизона.",al={"ghost walker post info","what is this camp","horde camp desolace","застава скитающихся духов","что это за лагерь","лагерь орды в пустошах"}},{q="Кто руководит Заставой Скитающихся Духов?",a="Заставой руководит Гурда Буйногривая, шаман-таурен, которая заботится об обороне лагеря и соседнем Кладбище кодо.",al={"who is in charge","ghost walker leader","gurda wildmane","кто главный","предводитель заставы скитающихся духов","гурда буйногривая"}},{q="Почему застава расположена рядом с Кладбищем кодо?",a="Гурда Буйногривая и другие шаманы-таурены живут здесь, чтобы помогать умирающим кодо переходить в следующую жизнь и общаться с духами павших животных.",al={"why by kodo graveyard","kodo spirits camp","shaman kodo graveyard","почему у кладбища кодо","духи кодо лагерь","шаман кладбище кодо"}},{q="С какими врагами сражается Застава Скитающихся Духов?",a="Гарнизон ведет непрерывную войну с местными враждебными племенами кентавров и зловещими силами Пылающего Клинка, действующими по всем Пустошам.",al={"ghost walker enemies","who attacks ghost walker post","post threats","враги заставы скитающихся духов","кто нападает на заставу","угрозы заставе"}},{q="Можно ли здесь получить путь полета или отдохнуть в таверне?",a="Нет. Застава предлагает искателям приключений лишь самое необходимое, и здесь нет ни трактирщика, ни распорядителя полетов на наездниках на ветрокрылах. Путникам придется искать транспорт в другом месте, например в Деревне Ночных Охотников.",al={"flight master ghost walker","innkeeper ghost walker","fp here?","распорядитель полетов застава","трактирщик застава","пункт полета здесь"}},{q="Чем она отличается от Деревни Ночных Охотников?",a="Деревня Ночных Охотников — защищенный анклав троллей на западном побережье, а Застава Скитающихся Духов расположена вдали от моря, сильно подвержена окрестным угрозам и занята обороной рубежей и духовными обязанностями.",al={"shadowprey vs ghost walker","other horde camp desolace","деревня ночных охотников или застава","другой лагерь орды в пустошах"}}},fp="17,296,21.553.0,26.464.0,26.134.0,28.119.0,48.152.0,42.144.0,47.188.0,42.198.0"}
P.entries["subzone:gnomeregan"] = {n="Гномреган",s="Гномреган был великолепной подземной столицей гномов, известной по всему Азероту механическим мастерством и технологическими чудесами. Сегодня это радиоактивная гробница, захваченная подземными троггами, взбесившимися защитными автоматами и безумными лепрогномами после того, как отчаянная оборона закончилась катастрофой.",h="Гномреган был великолепной подземной столицей гномов, известной по всему Азероту механическим мастерством и...",kw={"dun morogh","gnomeregan","leper gnome","mekkatorque","thermaplugg","tinkers court","trogg","дун морог","гномреган","лепрогном","меггакрут","термоштепсель","двор механиков","трогг"},ang={["profession:Engineering"]="Даже задыхаясь от радиоактивного яда, Гномреган остается крупнейшим в Восточных королевствах собранием схем, редких запчастей и действующих промышленных механизмов.",["race:Gnome"]="Каждый гном несет травму от потери Гномрегана. Вход в облученные залы — торжественное паломничество, чтобы уничтожить узурпатора Термоштепселя и вернуть утраченные механические реликвии."},sec={{t="Чудо инженерной мысли",b="Гномреган, вырубленный в заснеженных скалах западного Дун Морога, был построен много веков назад с помощью дворфов Стальгорна. Внутри огромные паровые шестерни, затейливые медные трубы и просторные сборочные залы составляли интеллектуальное и промышленное сердце гномов. Именно из этих подземных залов гномьи изобретения, летательные машины и сложное вооружение снабжали Альянс на протяжении Второй войны, и город держался даже в осаде Орды Оргрима Молота Рока."},{t="Падение и отравленные залы",b="Во время Третьей войны из глубин земли хлынули полчища троггов и прорвались в нижние залы города. Не желая отвлекать армии Альянса от бойни в Лордероне, главный механик Гелбин Меггакрут попытался справиться с кризисом в одиночку. По совету своего главного инженера Сикко Термоштепселя Меггакрут приказал выпустить радиоактивный газ через нижние залы, чтобы уничтожить тварей. План обернулся ужасным провалом: газ усилил многих троггов и убил почти восемьдесят процентов гномов. Те, кто подвергся облучению, но выжил, превратились в уродливых лепрогномов, а Термоштепсель захватил власть над отравленными руинами."}},faq={{q="Почему Гномреган полон радиации?",a="Когда подземные трогги захватили город, главный механик Меггакрут по совету Сикко Термоштепселя выпустил радиоактивный газ в нижние вентиляционные шахты. Отчаянный шаг должен был уничтожить тварей, но вместо этого погубил тысячи гномов, превратил выживших в лепрогномов и навсегда оставил город зараженным радиацией.",al={"why is it radioactive","gnomeregan toxic gas","what poisoned gnomeregan","почему радиоактивный","ядовитый газ гномрегана","что отравило гномреган"}},{q="Где сейчас выжившие гномы?",a="Выжившие бежали в соседний город дворфов Стальгорн. Король Магни Бронзобород предоставил им убежище во Дворе Механиков, где главный механик Гелбин Меггакрут теперь координирует помощь своему рассеянному народу и планирует возвращение родного дома.",al={"where do gnomes live","gnome refugees","where is mekkatorque","где живут гномы","гномы-беженцы","где меггакрут"}},{q="Кто сейчас управляет Гномреганом?",a="Сикко Термоштепсель, бывший главный советник Меггакрута, провозгласил себя королем Гномрегана. Сведенный с ума отравлением и манией величия, он командует взбесившимися защитными автоматами, облученными лепрогномами и мутировавшими троггами из самых глубин города.",al={"who is the boss of gnomeregan","gnomeregan leader","thermaplugg","кто главный в гномрегане","предводитель гномрегана","термоштепсель"}},{q="Почему Альянс не помог спасти Гномреган во время вторжения?",a="Меггакрут намеренно не стал просить помощи у Альянса. Поскольку человечество рушилось под натиском Плети во время Третьей войны, гномы держали свою подземную борьбу в тайне, чтобы не отвлекать важных защитников от Лордерона.",al={"why alliance no help","why didn't humans help gnomes","gnomes in third war","почему альянс не помог","почему люди не помогли гномам","гномы в третьей войне"}}},fp="10,327,23.491.0,31.662.0,36.338.0,39.260.0,28.256.0,65.251.0"}
P.entries["subzone:goblin-foundry"] = {n="Гоблинская литейная",s="Гоблинская литейная — промышленная мастерская в глубине Мертвых копей, где гоблины-механики изготавливают тяжелые металлические изделия для Братства Справедливости. Зал занимает огромный плавильный котел, а в нем по-прежнему трудятся гоблины-мастера и инженеры под началом Гилнида.",h="Гоблинская литейная — промышленная мастерская в глубине Мертвых копей, где гоблины-механики изготавливают...",kw={"cauldron","deadmines","defias","goblin foundry","vancleef","котел","мертвые копи","братство справедливости","гоблинская литейная","ван клиф"},ang={["faction:Alliance"]="Мастерская Братства Справедливости показывает масштаб промышленных ресурсов Братства под Западным Краем.",["profession:Engineering"]="Литейная демонстрирует гоблинское металлообрабатывающее мастерство и механическую изобретательность: инженеры защищают мастерскую управляемыми по радио големами."},sec={{t="Промышленные амбиции",b="Гоблинская литейная, вырубленная в подземных глубинах Луноречья, дает Братству Справедливости тяжелую производственную мощь. Гоблины-мастера и инженеры работают среди плавилен и железных помостов, изготавливая якоря и ядра."},{t="Мастерская Гилнида",b="Гилнид управляет гоблинскими работниками литейной. Мастера поддерживают производство, а инженеры защищают мастерскую с помощью управляемых по радио големов, из-за чего узкие помосты и расплавленный металл опасны для чужаков."}},faq={{q="Что строили в Гоблинской литейной?",a="Гоблины-мастера изготавливают тяжелые металлические изделия, включая якоря и ядра, для Братства Справедливости.",al={"what are they making here","foundry purpose","deadmines factory","что здесь делают","назначение литейной","фабрика мертвых копей"}},{q="Почему в литейной есть големы?",a="Гоблины-инженеры используют управляемых по радио големов для защиты мастерской от чужаков.",al={"why golems here","foundry robots","mechanical enemies deadmines","почему здесь големы","роботы литейной","механические враги мертвые копи"}},{q="Где гоблины, управлявшие этой мастерской?",a="Гоблины-мастера и инженеры продолжают работать в литейной под началом плавильщика Гилнида.",al={"where are the goblins","foundry engineers","gilnid workers","где гоблины","инженеры литейной","работники гилнида"}},{q="Что за огромное сооружение в центре зала?",a="В центре зала доминирует огромный промышленный плавильный котел, в котором переплавляют руду, добытую в шахтах, для ковки пластин брони и механических корпусов.",al={"foundry center pot","smelting vat","cauldron in deadmines","котел в центре литейной","плавильный чан","котел в мертвых копях"}}},fp="14,271,20.238.0,17.215.0,43.108.0,36.89.0,44.91.0,54.167.0"}
P.entries["subzone:gol-bolar-quarry"] = {n="Карьер Гол'Болар",s="Карьер Гол'Болар — гномий и дворфийский раскоп в заснеженных холмах юго-востока Дун Морога. Некогда оживленные работы по добыче камня и руды остановились: карьер захватили свирепые трогги, хлынувшие из глубин.",h="Карьер Гол'Болар — гномий и дворфийский раскоп в заснеженных холмах юго-востока Дун Морога.",kw={"dun morogh","gol'bolar","mine","prospector gehn","quarry","trogg","дун морог","гол'болар","рудник","геолог генн","карьер","трогг"},ang={["profession:Mining"]="Открытые каменные уступы и соседние туннели богаты рудными жилами, но старателям придется прорываться через окопавшихся троггов.",["race:Dwarf"]="Очистка карьера Гол'Болар — вопрос и экономической необходимости, и гордости клана: Стальгорн не может позволить грубым троггам завладеть богатствами своих гор."},sec={{t="Карьер в осаде",b="Карьер Гол'Болар, расположенный к юго-востоку от Караноса, основали дворфы Стальгорна, чтобы добывать в горах камень и ценные минералы. Однако при глубоких раскопках обнаружились подземные норы, откуда вырвалась орда враждебных троггов и быстро прогнала шахтеров. Сегодня верхний лагерь служит осажденным оплотом, где надсмотрщики, торговцы и геолог Генн собирают дворфов и гномов-добровольцев, чтобы отбросить тварей и вернуть карьер."}},faq={{q="Что такое карьер Гол'Болар?",a="Карьер Гол'Болар — открытая разработка на юго-востоке Дун Морога. Им управляют дворфы Стальгорна: это и место раскопок, и небольшой форпост, где местные искатели приключений находят припасы и работу.",al={"gol bolar","what is this place","quarry info","гол'болар","что это за место","о карьере"}},{q="Почему здесь так много троггов?",a="Дворфы-шахтеры забрались слишком глубоко и пробили подземные туннели, где обитали трогги. Твари хлынули в открытые карьеры и соседние штольни и вынудили шахтеров отступить на верхний край карьера.",al={"why are troggs here","trogg infestation","who attacked the quarry","почему здесь трогги","нашествие троггов","кто напал на карьер"}},{q="Кто такой геолог Генн?",a="Геолог Генн — дворф-надсмотрщик, расквартированный в лагере карьера. Он руководит защитой места раскопок и выдает награды и поручения искателям приключений, готовым сократить число троггов.",al={"who is gehn","prospector gehn","кто такой генн","геолог генн"}}},fp="16,238,20.470.0,25.217.0,34.226.0,23.195.0"}
P.entries["subzone:gol-bolar-quarry-mine"] = {n="Рудник карьера Гол'Болар",s="Рудник карьера Гол'Болар — захваченная шахта в самом сердце карьера Гол'Болар на востоке Дун Морога. Дворфы-шахтеры пробили туннелями подземные пещеры троггов, и вспыхнувшее нашествие захватило все место. Сегодня самые глубокие штольни служат оплотом отряда троггов под началом громилы Молотохребта.",h="Рудник карьера Гол'Болар — захваченная шахта в самом сердце карьера Гол'Болар на востоке Дун Морога.",kw={"dun morogh","gol'bolar","gol'bolar quarry mine","hammerspine","mine","quarry","troggs","дун морог","гол'болар","рудник карьера гол'болар","молотохреб","рудник","карьер","трогги"},ang={["profession:Mining"]="Суровое напоминание об опасностях подземных раскопок: рудник полностью перекрыт враждебными троггами, пока не очищены его глубочайшие туннели.",["race:Dwarf"]="Каждый удар кирки по горе грозит пробудить то, что лежит внизу. Вернуть рудник Гол'Болар — вопрос и экономической необходимости, и гордости дворфов."},sec={{t="Прорыв в глубине",b="Рудник основали дворфы Стальгорна, искавшие камень и богатые залежи руды под скалистыми пиками Дун Морога. Работы резко и жестоко оборвались, когда кирки пробили стену в древнюю систему подземных пещер, населенных троггами. Хлынув из тьмы, подземные твари смяли рабочих, заставили их поспешно отступить и в итоге выплеснулись наружу, захватив и окружающий карьер."},{t="Логово Молотохребта",b="Пока молодые и слабые трогги бродят по залитым солнцем террасам карьера, в самом руднике скрываются сильнейшие бойцы отряда. В глубине тесных туннелей, освещенных факелами, затаился их свирепый вождь Молотохреб. Вернуть ценный карьер — неотложная задача местных горцев, но чтобы выкурить нашествие, нужно спуститься в самые темные глубины рудника и перерезать тварям путь у истока."}},faq={{q="Почему рудник полон троггов?",a="Дворфы-шахтеры случайно пробили при раскопках скрытую подземную пещеру. Спавшие внутри трогги хлынули через пролом, перебили или прогнали рабочих и сделали штольни своим домом.",al={"why are troggs in gol bolar","how did troggs get here","who took over the mine","почему трогги в гол'болар","как трогги сюда попали","кто захватил рудник"}},{q="Кто предводительствует троггами в руднике карьера Гол'Болар?",a="Троггов в руднике возглавляет Молотохреб — огромный громила, который из глубины штолен командует сильнейшими воинами отряда.",al={"mine boss","trogg leader gol bolar","who is hammerspine","главарь рудника","предводитель троггов гол'болар","кто такой молотохреб"}},{q="Отличается ли рудник от остального карьера?",a="Да. В наружном карьере находятся наземные сооружения и более слабые трогги, а рудник — это глубокие, тесные подземные туннели, где обитают самые сильные трогги и их вождь.",al={"quarry vs mine","are the mine troggs harder","карьер или рудник","сильнее ли трогги в руднике"}},{q="Могут ли здесь по-прежнему работать шахтеры?",a="Нет. Добыча полностью прекращена. Это действующая зона боевых действий: дворфы-горцы и искатели приключений истребляют угрозу троггов, а не добывают камень.",al={"is the mine active","are dwarves still mining","работает ли рудник","добывают ли дворфы руду"}}},fp="21,366,20.435.0,19.432.0,31.222.0,50.145.0,50.192.0,27.181.0"}
P.entries["subzone:golakka-hot-springs"] = {n="Горячие источники Голакка",s="Горячие источники Голакка — геотермальная котловина на западе кратера Ун'Горо, к северу от Пути Ужаса. Кипящие бассейны и гейзеры питаются сильной вулканической активностью соседнего Вулкана Огненного Венца. Богатые минералами воды привлекают чудаковатых исследователей, алхимиков в поисках редких реагентов и бродячих водных элементалей — паровых яростей.",h="Горячие источники Голакка — геотермальная котловина на западе кратера Ун'Горо, к северу от Пути Ужаса.",kw={"fire plume ridge","geyser","golakka","hot springs","krakle","spark nilminer","steaming fury","terror run","un'goro","вулкан огненного венца","гейзер","голакка","горячие источники","краккл","искр пустокоп","паровая ярость","путь ужаса","ун'горо"},ang={["class:Shaman"]="Горячие источники показывают мощное взаимодействие огня и воды: столкновение стихий порождает кипящих паровых яростей на минеральных берегах.",["race:Gnome"]="Экстремальная геологическая активность бесконечно увлекает гномов, таких как Искр Пустокоп, которая рискует среди обжигающих паровых жерл, чтобы вблизи изучить геотермальную механику."},sec={{t="Кипящие воды и вулканический пар",b="Горячие источники Голакка, лежащие в западной части кратера Ун'Горо, — прямое следствие подземного жара Вулкана Огненного Венца. Обжигающая вода непрерывно поднимается на поверхность, образуя ступенчатые минеральные террасы и бурно извергающиеся гейзеры. Здесь повсюду бродят паровые ярости — стихийные воплощения, рожденные слиянием подземных вод и вулканического жара. Несмотря на опасность, источники часто привлекают путешественников, травников и исследователей, увлеченных уникальной геологией кратера."},{t="Любопытные обитатели и странная химия",b="Необычные свойства вод Голакка интересуют не только любителей достопримечательностей. Алхимики ценят обогащенную геотермальным теплом воду как мощный катализатор и даже применяют ее в тонких составах, например в любовных зельях. У гейзерного жерла встречаются и чудаковатые гости: Искр Пустокоп сидит на центральном жерле гейзера, а исследователь Краккл пытается понять, как источники напрямую связаны с вулканическим сердцем кратера."}},faq={{q="Почему источники такие горячие?",a="Источники нагревает мощная вулканическая система под кратером Ун'Горо, напрямую связанная с Вулканом Огненного Венца. Магма под дном кратера перегревает подземные запасы воды, и кипящая, богатая минералами вода с паром вырывается через гейзеры и ступенчатые бассейны.",al={"why is water boiling","geothermal heat un'goro","fire plume connection","почему вода кипит","геотермальный жар ун'горо","связь с огненным венцом"}},{q="Какие существа обитают в горячих источниках Голакка?",a="Чаще всего по берегам и бассейнам бродят паровые ярости. Это духи живой воды, которые под палящим жаром вулканических жерл превратились в клокочущий, нестабильный пар.",al={"hot springs elementals","what lives in golakka","steaming fury","элементали источников","кто живет в голакка","паровая ярость"}},{q="Для чего используют воду горячих источников?",a="Насыщенную минералами воду ценят алхимики и чудаковатые зельевары за ее уникальные химические свойства. В частности, чистые образцы из источников ищут как важный реагент для особых составов, в том числе сильных любовных зелий.",al={"golakka water use","hot springs love potion","hot springs reagents","вода голакка","любовное зелье источники","реагенты источников"}},{q="Кто такой Краккл и что он здесь делал?",a="Краккл — исследователь, изучающий геотермальную связь между горячими источниками Голакка и Вулканом Огненного Венца: он собирает наблюдения и замеры температуры у источников.",al={"krakle un'goro","krakle hot springs","researcher at the hot springs","краккл ун'горо","краккл источники","исследователь у источников"}}},fp="19,367,33.552.0,41.474.0,27.272.0,43.209.0,48.258.0,41.177.0"}
P.entries["subzone:gold-coast-quarry"] = {n="Прииск на Золотом Берегу",s="Прииск на Золотом Берегу — открытая разработка в утесах юго-запада Западного Края. Некогда он был ценным источником камня, минералов и золота для Королевства Штормград, а теперь его захватило Братство Справедливости, чтобы подпитывать растущий мятеж.",h="Прииск на Золотом Берегу — открытая разработка в утесах юго-запада Западного Края.",kw={"defias","defias brotherhood","gold coast quarry","mine","people's militia","quarry","stormwind","westfall","братство справедливости","прииск на золотом берегу","рудник","народное ополчение","прииск","штормград","западный край"},ang={["faction:Alliance"]="Возвращение таких мест, как Прииск на Золотом Берегу, жизненно важно для восстановления порядка в Западном Крае, где из-за отсутствия королевских гарнизонов местным добровольцам пришлось взяться за оружие.",["profession:Mining"]="Шахтеры, забредшие в Западный Край, найдут вдоль утесов прииска богатые каменные пласты и рудные жилы, но чтобы добывать их, придется пробиваться через окопавшиеся патрули Братства Справедливости."},sec={{t="Разграбленное богатство",b="Пока королевство не пришло в упадок, Прииск на Золотом Берегу поставлял строительные материалы и драгоценное золото для восстановления Штормграда. Когда королевские войска ушли из Западного Края и оставили земли без защиты, разбойники Братства Справедливости и беглые рабочие захватили разработки. Теперь Братство патрулирует ступенчатые каменные пандусы, пользуясь видом на побережье, и грабит оставшиеся минералы, чтобы платить за мятеж."}},faq={{q="Для чего изначально использовался прииск?",a="Прииск основало Королевство Штормград, чтобы добывать камень, минералы и золото в прибрежных утесах. Значительная часть камня, добытого в Западном Крае, помогла восстановить Штормград после Второй войны.",al={"why is there a quarry here","what did they mine here","gold coast purpose","зачем здесь прииск","что здесь добывали","назначение золотого берега"}},{q="Кто сейчас контролирует Прииск на Золотом Берегу?",a="Прииск контролирует Братство Справедливости. Его бандиты, мародеры и разбойники патрулируют ступенчатые утесы и входы в шахты, не пуская честных поселенцев и добывая ресурсы для своих незаконных дел.",al={"who is at the quarry","who owns gold coast quarry","enemies at the quarry","кто на прииске","кто владеет прииском на золотом берегу","враги на прииске"}},{q="Почему Штормград не послал стражу, чтобы освободить прииск?",a="Король Вариан Ринн пропал, а Дом знати Штормграда не желает оплачивать постоянный военный гарнизон в Западном Крае, поэтому корона бросила этот край. Местному Народному ополчению приходится самому сражаться за такие места, как прииск.",al={"why no stormwind army","where are the guards","why is it abandoned","почему нет армии штормграда","где стража","почему он заброшен"}},{q="Где находится Прииск на Золотом Берегу?",a="Он вырублен в утесах вдоль юго-западного побережья Западного Края, к югу от ферм Сальден и Поместья Алекстона, с видом на Великое море.",al={"quarry location","how to find gold coast quarry","where is it","где прииск","как найти прииск на золотом берегу","где это"}}},fp="17,251,20.444.0,40.227.0,45.216.0,53.258.0,39.159.0"}
P.entries["subzone:gold-road"] = {n="Золотой Путь",s="Золотой Путь — главная артерия с севера на юг, пересекающая засушливые просторы Степей. Он тянется от Заставы Мор'шан на границе Ясеневого леса мимо Перекрестка к южным областям и служит жизненно важной транспортной линией молодой Орды.",h="Золотой Путь — главная артерия с севера на юг, пересекающая засушливые просторы Степей.",kw={"caravan","crossroads","gold road","great divide","highway","mor'shan","the barrens","караван","перекресток","золотой путь","большой разлом","дорога","мор'шан","степи"},ang={["class:Hunter"]="Саванна у дороги кишит равнинными зверями, поэтому ее долгий путь идеален для выслеживания и приручения первых питомцев охотника, таких как львы и ящеры-ловчие.",["faction:Horde"]="Золотой Путь — основа снабжения Орды в Калимдоре: он связывает орочью столицу в Дуротаре с землями тауренов в Мулгоре и северными передовыми лагерями близ Ясеневого леса."},sec={{t="Артерия Степей",b="Золотой Путь — длинная, выжженная солнцем грунтовая дорога, рассекающая центр Степей. На севере он начинается у укрепленной Заставы Мор'шан и Лагеря Мор'шан, которые защищают от вторжений ночных эльфов из Ясеневого леса. На юге он соединяется с восточной дорогой в Дуротар, а затем пересекает оживленное торговое поселение Перекресток. Далее на юг, мимо зеленых оазисов и предгорий у Пещер Стенаний, северный участок дороги доходит до высохшего русла реки, где путники попадают в более опасную южную часть саванны."},{t="Важный и опасный путь",b="Хотя Золотой Путь — основа торговли и передвижения войск Орды между центральными землями Калимдора, он опасен. Караванам и одиноким гонцам постоянно угрожают свирепые племена свинобразов, отряды кентавров, а также бродящие равнинные ходоки и львы. Орда тратит немало сил, размещая вдоль дороги разведчиков и воинов, но путникам советуют оставаться вооруженными и настороженными, покидая безопасные крупные форпосты."}},faq={{q="Где начинается и заканчивается Золотой Путь?",a="Золотой Путь начинается на крайнем севере Степей у Заставы Мор'шан на границе Ясеневого леса. Его северный участок идет на юг через Перекресток до высохшего русла, разделяющего северные и южные Степи, где Южный Золотой Путь продолжается мимо Лагеря Таурахо к Великому Подъемнику.",al={"gold road route","where does the gold road go","gold road length","маршрут золотого пути","куда ведет золотой путь","длина золотого пути"}},{q="Почему Золотой Путь так важен для Орды?",a="Дорога связывает все основные земли недавно образованной Орды в центральном Калимдоре. По ней идут линии снабжения из Дуротара и порта Кабестан к землям тауренов в Мулгоре и к северному военному фронту против ночных эльфов в Ясеневом лесу.",al={"why is gold road important","importance of gold road","почему важен золотой путь","значение золотого пути"}},{q="Какие угрозы бродят у дороги?",a="Путники часто встречают отряды налетчиков-свинобразов из племен Иглогривых и Дыбогривов, бродячих кентавров Колкара и агрессивных диких зверей, например саванных охотников и громовых ящеров. За пределами Перекрестка дорога далеко не безопасна.",al={"is gold road safe","enemies on gold road","gold road dangers","безопасен ли золотой путь","враги на золотом пути","опасности золотого пути"}},{q="Как Золотой Путь связан с Дуротаром?",a="К северу от Перекрестка от Золотого Пути ответвляется восточная дорога, которая по деревянному мосту через Реку Строптивую ведет прямо в Дуротар.",al={"road to durotar","turn off to durotar","дорога в дуротар","поворот на дуротар"}}},fp="9,271,25.633.0,26.464.0,39.318.0,47.263.0,34.250.0,42.153.0"}
P.entries["subzone:golden-plains"] = {n="Золотые равнины",s="Золотые равнины — обширная залитая солнцем низина к юго-востоку от Громового Утеса в центральной части Мулгора. Эти раздольные луга, любимые таурами, служат отличными охотничьими угодьями и важными пастбищами для бродячих стад кодо.",h="Золотые равнины — обширная залитая солнцем низина к юго-востоку от Громового Утеса в центральной части...",kw={"arra'chea","golden plains","hunting grounds","kodo","mulgore","thunder bluff","арра'чея","золотые равнины","охотничьи угодья","кодо","мулгор","громовой утес"},ang={["class:Hunter"]="Обширные открытые просторы и бродящие стада кодо делают эти равнины отличным испытанием для следопытов, ищущих легендарных зверей вроде Арра'чеи.",["race:Tauren"]="Для тауренов Золотые равнины — непреходящий символ щедрости их родины и священные охотничьи угодья в тени Громового Утеса."},sec={{t="Сердце охоты",b="Золотые равнины раскинулись у подножия высоких плато Громового Утеса и составляют дикое сердце Мулгора. Переливающееся море золотой и зеленой травы дает обильное убежище местным животным, поэтому это одно из самых дорогих сердцу традиционных охотничьих угодий кочевых тауренов. По холмистой низине бродят большие стада кодо, а охотники рассказывают истории о легендарной добыче, прежде всего о великом кодо Арра'чее, который тихо бродит среди высоких стеблей."}},faq={{q="Что такое Золотые равнины?",a="Золотые равнины — широкая травянистая низина к юго-востоку от Громового Утеса в Мулгоре. Это любимые тауренами охотничьи угодья с традиционным значением, известные широкими просторами и обилием диких животных.",al={"golden plains mulgore","where are golden plains","золотые равнины мулгор","где находятся золотые равнины"}},{q="Какие животные обитают на Золотых равнинах?",a="Низина славится обильными стадами диких кодо и другими местными существами Мулгора. Самый известный зверь, который, как говорят, бродит по этим лугам, — неуловимый и почитаемый кодо по имени Арра'чея.",al={"golden plains beasts","kodos in golden plains","звери золотых равнин","кодо на золотых равнинах"}},{q="Почему эта местность важна для тауренов?",a="Равнины служат важным источником дичи и шкур, кормят недавно основанные поселения Мулгора и воплощают тауренскую традицию выслеживать добычу и чтить ее.",al={"tauren golden plains","why tauren hunt here","таурены золотые равнины","почему таурены охотятся здесь"}}},fp="13,248,17.476.0,27.198.0,36.204.0,41.199.0"}
P.entries["subzone:gordok-commons"] = {n="Палаты клана Гордок",s="Палаты клана Гордок — укрепленный северный квартал древних руин высокорожденных в Забытом Городе. Под властью короля Гордока этот обширный каменный комплекс служит средоточием власти элитной касты воинов огров Гордунни.",h="Палаты клана Гордок — укрепленный северный квартал древних руин высокорожденных в Забытом Городе.",kw={"dire maul north","eldre'thalas","gordok","gordok commons","king gordok","knot thimblejack","mizzle","tribute run","север забытого города","эльдре'талас","гордок","палаты клана гордок","король гордок","узелок","мизль","сбор дани"},ang={["profession:Engineering"]="Пленный гоблин Узелок Наперсток полагается на находчивых инженеров и мастеровых в Палатах: они добывают припасы, чинят сломанные ловушки и придумывают хитрые отвлекающие уловки против стражей-огров."},sec={{t="Престол короля огров",b="Некогда аристократическое крыло Эльдре'Таласа, Палаты клана Гордок были осквернены и переделаны под вкусы огров. В величественных колоннах и арочных проходах ночных эльфов теперь расположены оружейные, грубые баррикады и тренировочные площадки Гордока — самых свирепых и дисциплинированных бойцов клана Гордунни. В глубине крыла находится Престол Гордока, где король Гордок правит своими громилами силой и запугиванием."},{t="Закон преемственности",b="Культура Гордока целиком держится на жестоком обычае: прав тот, кто сильнее. По традиции клана тот, кто убьет правящего владыку, получает титул короля Гордока и немедленное повиновение уцелевших капитанов и стражей. Сообразительные чужаки пользуются этим обычаем и прокрадываются мимо помощников короля или обманывают их, не убивая. Если претендент убьет только короля, уцелевшие стражи признают власть победителя и принесут щедрую дань, вместо того чтобы мстить за прежнего правителя."}},faq={{q="Где находятся Палаты клана Гордок?",a="Палаты находятся в северном квартале Забытого Города в Фераласе. Чтобы добраться до них, войдите в обширные руины через Разрушенный общинный квартал и пройдите по огромным каменным коридорам к северному входу.",al={"gordok commons location","where is dire maul north","how to find gordok commons","расположение палат клана гордок","где север забытого города","как найти палаты клана гордок"}},{q="Кто такие огры Гордок?",a="Гордок — элитная каста воинов клана огров Гордунни. В отличие от своих разрозненных диких сородичей в глуши Фераласа, Гордок в Палатах организованы, хорошо вооружены и подчинены строгой военной иерархии под началом короля.",al={"who are the gordok","gordok clan","gordunni elite","кто такие гордок","клан гордок","элита гордунни"}},{q="Как устроена власть огров в Палатах?",a="Власть Гордока решается в бою. Тот, кто убьет правящего короля Гордока, мгновенно получает корону. Когда король падает, остальные огры сдаются и признают победителя законным владыкой.",al={"how to become king of gordok","gordok succession","king gordok lore","как стать королем гордока","преемственность гордока","предания о короле гордоке"}},{q="Почему искатели приключений оставляют стражей-огров в живых?",a="Если чужак доберется до короля Гордока и победит его, не убив его помощников, выжившие командиры подчиняются новому королю. В награду за сдержанность и прямой захват трона новый правитель получает ценную дань от гарнизона.",al={"why tribute run","sparing the guards","gordok tribute lore","почему сбор дани","пощада стражей","предания о дани гордока"}}},fp="14,242,21.464.0,17.535.0,36.205.0,25.258.0,45.204.0,47.271.0"}
P.entries["subzone:gordunni-outpost"] = {n="Поселение Гордунни",s="Поселение Гордунни, расположенное в суровых скалах к северу от Павильона Лорисс, служит укрепленным лагерем грубых огров Гордунни в Фераласе. Разрушительное влияние клана иссушило некогда пышную здешнюю природу, и земля вокруг стала сухой, увядшей и бурой.",h="Поселение Гордунни, расположенное в суровых скалах к северу от Павильона Лорисс, служит укрепленным лагерем...",kw={"bigfist","channeler","feralas","gordunni","hillguard","lariss pavilion","ogre","outpost","tamer","большой кулак","чаротворец","фералас","гордунни","страж холмов","павильон лорисс","огр","поселение","укротитель"},ang={["class:Druid"]="Присутствие Гордунни — тяжкое оскорбление природы: оно превращает плодородный полог джунглей в неестественно иссохшую, бесплодную пустошь."},sec={{t="Оскверненный оплот",b="Поселение Гордунни, вырубленное в северных горах над Павильоном Лорисс, резко выделяется шрамом на фоне пышного полога лесов Фераласа. Где бы ни селились огры Гордунни, их безрассудное обращение с магией и разрушительные привычки высасывают жизненные силы природы, оставляя растения мертвыми, а склоны голыми. Поселение состоит из земляных троп, неглубокой пещеры у входа и большего огрского кургана, уходящего вглубь задних скал. Лагерь патрулируют тяжеловооруженные стражи холмов, хитрые чаротворцы и укротители огров, а еще в нем держат опасные трофеи — в том числе плененного снежного человека по имени Большой Кулак, которого держат в грубом загоне возле глубокого логова."}},faq={{q="Почему земля вокруг этого поселения иссохла?",a="Клан Гордунни тяжело и губительно действует на окружающую среду. Их безрассудное колдовство и разрушительное присутствие истощают природные силы почвы, и обычно пышная зелень джунглей вянет, превращаясь в сухие бурые заросли.",al={"why is it brown","dead grass feralas","ogre corruption","почему все бурое","мертвая трава фераласа","порча от огров"}},{q="Какие огры живут в Поселении Гордунни?",a="Поселение защищают стражи холмов Гордунни, чаротворцы Гордунни, владеющие грубой боевой магией, и укротители Гордунни, которые присматривают за лагерем и плененными зверями.",al={"what mobs are here","gordunni types","who lives here","какие враги здесь","виды гордунни","кто здесь живет"}},{q="Кто такой Большой Кулак?",a="Большой Кулак — огромный снежный человек, которого огры Гордунни держат в плену у входа в заднюю пещеру. Укротители огров держат его связанным как трофей или подопытную добычу.",al={"caged sasquatch","who is bigfist","ogre prisoner","снежный человек в клетке","кто такой большой кулак","пленник огров"}},{q="Где находится Поселение Гордунни?",a="Поселение расположено высоко на горном хребте прямо к северу от Павильона Лорисс в восточном Фераласе.",al={"where is gordunni outpost","outpost location","how to get to gordunni outpost","где поселение гордунни","расположение поселения","как добраться до поселения гордунни"}}},fp="16,279,19.654.0,50.247.0,48.165.0,15.170.0,38.103.0"}
P.entries["subzone:grand-vestibule"] = {n="Главный вестибюль",s="Главный вестибюль — монументальный входной зал Монастыря Алого ордена в Тирисфальских лесах. Он обрамлен багровыми колоннами и каменными изваяниями павших крестоносцев и служит порогом, где искатели приключений готовятся проникнуть во внутренние залы монастыря.",h="Главный вестибюль — монументальный входной зал Монастыря Алого ордена в Тирисфальских лесах.",kw={"entrance hall","grand vestibule","scarlet augur","scarlet disciple","scarlet monastery","scarlet sentry","tirisfal glades","входной зал","главный вестибюль","алый авгур","алый послушник","монастырь алого ордена","алый часовой","тирисфальские леса"},ang={["faction:Alliance"]="Вестибюль показывает трагическое разложение бывших священных обителей Лордерона и то, как преданность Свету обернулась слепым, жестоким фанатизмом.",["race:Undead"]="Этот величественный вход, расположенный к северо-востоку от Подгорода, — передовая линия живых фанатиков, открыто угрожающих власти Отрекшихся в Тирисфале."},sec={{t="Порог фанатизма",b="За тяжелыми внешними вратами монастыря лежит Главный вестибюль — просторный мраморный зал, посвященный воинской гордости Алого ордена. Статуи закованных в доспехи защитников стоят на страже у сводчатых каменных колонн, а ревностные часовые, послушники и авгуры патрулируют плиты пола и сражают всякого, кто посмеет войти без багрового табарда ордена. Для незваных гостей это первое знакомство с неумолимой дисциплиной и фанатизмом ордена."},{t="Спорное место встречи",b="Вестибюль находится прямо перед охраняемыми внутренними крыльями монастыря, поэтому служит опасным местом сбора. Под этими высокими арками сходятся и отряды Альянса, посланные на север, и силы Орды, выдвигающиеся из соседнего Подгорода, и пышный вход превращается в хаотичное кровавое поле битвы задолго до того, как кто-либо проникнет во внутренние кельи."}},faq={{q="Что такое Главный вестибюль?",a="Это главный входной зал Монастыря Алого ордена на северо-востоке Тирисфальских лесов, соединяющий внешний двор с четырьмя внутренними крыльями.",al={"what is this room","grand vestibule info","monastery entrance hall","что это за зал","информация о главном вестибюле","входной зал монастыря"}},{q="Какие враги охраняют эту область?",a="Зал защищают действующие члены Алого ордена, главным образом алые часовые, алые послушники и алые авгуры, поставленные не пускать чужаков.",al={"who patrols here","vestibule mobs","crusaders in vestibule"}},{q="Почему Альянс и Орда сражаются здесь?",a="Обе фракции посылают героев в монастырь: Альянс стремится вернуть святыни Лордерона или очистить их от еретиков, а Орда — закрепить Тирисфальские леса за Отрекшимися. Их пути неизбежно сталкиваются в этом общем входном зале.",al={"pvp in vestibule","why are players fighting here","contested vestibule","pvp в вестибюле","почему здесь сражаются игроки","спорный вестибюль"}},{q="Кого изображают статуи в вестибюле?",a="Статуи изображают почитаемых воинов и героев Алого ордена, высеченных в тяжелых латных доспехах как непреходящие символы их непреклонного похода против нежити.",al={"who are the statues","vestibule statues","crusade monuments","кто эти статуи","статуи вестибюля","памятники ордена"}}},fp="15,255,25.455.0,26.369.0,28.149.0,29.154.0,41.249.0,44.177.0"}
P.entries["subzone:great-lift"] = {n="Великий Подъемник",s="Великий Подъемник — огромная система лифтов, построенная тауренами на южной окраине Степей. Это главный путь, по которому путешественники и грузы спускаются на сотни футов в отвесную каньонную котловину Тысячи Игл. Несмотря на стратегическую ценность, наступающие с южных пустошей свинобразы все больше осложняют подход к краю.",h="Великий Подъемник — огромная система лифтов, построенная тауренами на южной окраине Степей.",kw={"brave moonhorn","elevator","great lift","grish longrunner","quilboar","the barrens","thousand needles","храбрец лунный рог","лифт","великий подъемник","гриш выносливый гонец","свинобраз","степи","тысяча игл"},ang={["faction:Horde"]="Подъемник — важная артерия Орды, соединяющая центральный Калимдор с отдаленными землями Тысячи Игл и Мерцающей равниной.",["race:Tauren"]="Подъемник из крепких бревен и противовесов показывает изобретательность вашего народа, умеющего преодолевать суровый рельеф, не оставляя шрамов на земле."},sec={{t="Врата из дерева и веревок",b="Великий Подъемник, перекинутый через отвесный обрыв между южными Степями и дном каньона Тысячи Игл, — образец практичной тауренской постройки. Он сделан из тяжелых бревен, плетеных канатов и блоков с противовесами; его парные платформы безопасно перевозят караваны, гонцов и воинов через пропасть, которая сломала бы любую повозку. На верхней и нижней платформах стоят на страже таурены, такие как Храбрец Лунный Рог и Гриш Выносливый Гонец: они сообщают путникам о дороге впереди и следят за грузами."},{t="Опасности у края",b="Работа подъемника становится все опаснее из-за враждебных земель наверху. Агрессивные племена свинобразов южных Степей все дальше расширяются на юг, перекрывая дорогу к подъемнику и грозя полностью отрезать Тысячу Игл от северных троп. Тем, кто идет на юг, приходится постоянно отбиваться от налетчиков из племени Иглошкурых, прежде чем ступить на деревянные платформы."}},faq={{q="Кто построил Великий Подъемник?",a="Великий Подъемник спроектировали и построили таурены, чтобы преодолеть огромный перепад высот между засушливыми плато Степей и глубоким дном каньона Тысячи Игл.",al={"who made the great lift","great lift builders","tauren elevator origin","кто построил великий подъемник","строители великого подъемника","происхождение тауренского лифта"}},{q="Почему добираться до подъемника опасно?",a="Наступающие свинобразы южных Степей агрессивно расширили свою территорию в сторону края плато. Их отряды налетчиков рыщут на подступах и часто досаждают караванам с припасами и гонцам, направляющимся к платформам подъемника, или прямо нападают на них из засады.",al={"why are there quilboar here","southern barrens danger","lift road blocked","почему здесь свинобразы","опасность южных степей","дорога к подъемнику закрыта"}},{q="Кто охраняет Великий Подъемник?",a="Храбрец Лунный Рог и Гриш Выносливый Гонец несут службу у подъемника: следят за дорогами, помогают путникам Орды и присматривают за окрестными землями.",al={"who guards the lift","lift keepers","tauren at the lift","кто охраняет подъемник","стражи подъемника","таурены у подъемника"}},{q="Куда ведет Великий Подъемник?",a="Спуск на платформах приводит путников на дно каньона Тысячи Игл, а подъем ведет прямо в южные Степи.",al={"where does lift go","what is below the lift","lift destination","куда ведет подъемник","что внизу подъемника","пункт назначения подъемника"}}},fp="10,378,35.548.0,18.430.0,25.180.0,39.252.0,32.153.0,31.143.0"}
P.entries["subzone:green-belt"] = {n="Зеленый Пояс",s="Зеленый Пояс — дикая болотистая местность в восточной Болотине, раскинувшаяся под хребтами Грим Батола. Здесь бродят болотные твари, хищные кроколиски и ядовитые слизи, а охраняет ее в основном одинокий ночной эльф Ретиль Страж Природы.",h="Зеленый Пояс — дикая болотистая местность в восточной Болотине, раскинувшаяся под хребтами Грим Батола.",kw={"bog beasts","dragonmaw","green belt","grim batol","oozes","rethiel","wetlands","whelps","болотные твари","драконья пасть","зеленый пояс","грим батол","слизи","ретиль","болотина","дракончики"},ang={["class:Druid"]="Искаженные слизи и неукротимые болотные твари нарушают природную гармонию топи, и этот край вызывает тревогу у хранителей дикой природы.",["race:NightElf"]="Встретить Ретиль Страж Природы одну в болоте Восточных королевств — неожиданное зрелище, напоминающее о Круге Кенария и о том, как ночные эльфы стремятся исцелять дикие земли, где бы те ни находились."},sec={{t="Дикая и спорная топь",b="Зеленый Пояс, протянувшийся через восточную часть Болотины, — одна из диких низин этого сырого края. Местные животные — от огромных кроколисков до подвижных слизей и неуклюжих болотных тварей — делают путь по мшистым водам опасным. В глубине стоит одинокий сторожевой пост, где несет службу Ретиль Страж Природы, одинокий ночной эльф, изучающий экологию топи и сдерживающий ее враждебных обитателей."},{t="Следы Второй войны",b="Среди грязи разбросаны обломки каравана клана Драконьей Пасти, оставленного после страшной битвы у близлежащего Грим Батола. Багровые дракончики до сих пор бродят вокруг сломанных телег и раздавленных клеток — мрачное напоминание о том, как орочий клан порабощал Алекстразу и ее красных драконов."}},faq={{q="Где находится Зеленый Пояс?",a="Зеленый Пояс занимает восточную половину Болотины и тянется по топким низинам между главной дорогой и предгорьями, поднимающимися к Грим Батолу.",al={"green belt location","where is green belt","green belt wetlands map","расположение зеленого пояса","где зеленый пояс","зеленый пояс болотина карта"}},{q="Кто такой Ретиль Страж Природы?",a="Ретиль — загадочный ночной эльф, стоящий на страже в болотах Болотины. Вдали от родного Калимдора он стремится сохранить равновесие природы в трясине и привлекает путников к борьбе с оскверняющими ее тварями и слизями.",al={"who is rethiel","rethiel the greenwarden","night elf in green belt","кто такой ретиль","ретиль страж природы","ночной эльф в зеленом поясе"}},{q="Почему здесь красные дракончики и сломанные повозки?",a="Это остатки обоза с припасами клана Драконьей Пасти, настигнутого последствиями Второй войны, когда орков выбили из Грим Батола, а их власть над красным драконьим родом рухнула.",al={"dragonmaw caravan","why are there whelps in wetlands","red whelps wetlands","караван драконьей пасти","почему в болотине дракончики","красные дракончики болотина"}},{q="Какие угрозы бродят по Зеленому Поясу?",a="Путники в Поясе часто встречают опасных болотных кроколисков, ядовитых слизей и огромных болотных тварей, сливающихся с сырой растительностью.",al={"green belt mobs","dangers in green belt","what monsters live here","монстры зеленого пояса","опасности зеленого пояса","какие монстры здесь живут"}}},fp="10,257,24.450.0,26.309.0,32.154.0,31.227.0,48.190.0,35.171.0"}
P.entries["subzone:greenpaw-village"] = {n="Деревня Зеленой Лапы",s="Деревня Зеленой Лапы — поселение фурболгов в центральном Ясеневом лесу, между Приютом в Ночных Лесах и Приютом Серебряного Ветра. Это главный дом племени Гиблой Чащи, которым правят вождь Мургут и шаман Дубовая Лапа. Охваченная демонической порчей и осаждаемая внешними силами, деревня — очаг конфликта для путников и Альянса, и Орды.",h="Деревня Зеленой Лапы — поселение фурболгов в центральном Ясеневом лесу, между Приютом в Ночных Лесах и...",kw={"ashenvale","foulweald","furbolg","greenpaw village","murgut","oakpaw","raynewood retreat","silverwind refuge","ясеневый лес","гиблая чаща","фурболг","деревня зеленой лапы","мургут","дубовая лапа","приют в ночных лесах","приют серебряного ветра"},ang={["class:Druid"]="В Деревне Зеленой Лапы друиды воочию видят боль древнего медвежьего народа, у которого равновесие природы сменилось необузданным звериным безумием.",["race:NightElf"]="Для ночных эльфов видеть, как племя Гиблой Чащи поддается порче так близко от Приюта в Ночных Лесах и священных лунных колодцев, — трагичное напоминание о не заживших демонических шрамах Ясеневого леса."},sec={{t="Оскверненное поселение",b="Деревня Зеленой Лапы, лежащая к югу от Приюта в Ночных Лесах и к северо-востоку от Приюта Серебряного Ветра, когда-то была тихим домом медвежьих обитателей леса. После Третьей войны ее жители-фурболги, племя Гиблой Чащи, поддались коварной порче, оскверняющей почву и духов Ясеневого леса. Под властью вождя Мургута и их оскверненного духовного наставника, шамана Дубовой Лапы, племя стало враждебным и неуравновешенным и нападает на всех путников, забредших на его лесные земли."},{t="Под перекрестным огнем",b="Из-за неослабной агрессивности и близости к крупным дорогам Деревня Зеленой Лапы вызывает враждебность со всех сторон. Часовые Альянса и ночные эльфы-друиды стремятся истребить безумных фурболгов, защищая ближние форпосты и священные лунные колодцы. В то же время силы Орды, продвигаясь по Ясеневому лесу, вели кровавые стычки с племенем Гиблой Чащи, пока обе стороны пробивались через древний лес."}},faq={{q="Где находится Деревня Зеленой Лапы?",a="Деревня Зеленой Лапы лежит в центральном Ясеневом лесу, прямо к югу от Приюта в Ночных Лесах, к северо-востоку от Приюта Серебряного Ветра и чуть северо-западнее южного лунного колодца.",al={"greenpaw location","where is greenpaw village","find greenpaw","где зеленая лапа","где деревня зеленой лапы","найти деревню зеленой лапы"}},{q="Кто живет в Деревне Зеленой Лапы?",a="Поселение населяет племя фурболгов Гиблой Чащи, которым правят вождь Мургут и их оскверненный духовный советник, шаман Дубовая Лапа.",al={"who is here","greenpaw mobs","greenpaw furbolgs","кто здесь","монстры деревни зеленой лапы","фурболги зеленой лапы"}},{q="Почему фурболги Деревни Зеленой Лапы враждебны?",a="Как и многие племена фурболгов северного Калимдора, племя Гиблой Чащи пало жертвой демонической порчи, оставшейся после вторжения Пылающего Легиона в Ясеневый лес, и ярость помутила их разум.",al={"why are furbolgs mad","are greenpaw furbolgs corrupt","почему фурболги безумны","оскверненные ли фурболги зеленой лапы"}},{q="Почему Альянс и Орда сражаются здесь?",a="Обе стороны считают агрессивное племя Гиблой Чащи угрозой своим дорогам и поселениям. Ночные эльфы стремятся исцелить или сдержать безумие возле своих лунных колодцев, а силы Орды сталкиваются с фурболгами, продвигаясь по Ясеневому лесу.",al={"greenpaw quests","who attacks greenpaw","задания зеленой лапы","кто нападает на зеленую лапу"}}},fp="16,367,22.495.0,24.405.0,34.157.0,30.152.0,49.210.0,45.239.0"}
P.entries["subzone:greymane-wall"] = {n="Стена Седогрива",s="Стена Седогрива — громадный каменный оплот, протянувшийся вдоль южной границы Серебряного бора. Возведенная королем Генном Седогривом после Второй войны, она отгораживает королевство Гилнеас от внешнего мира неприступными запертыми воротами.",h="Стена Седогрива — громадный каменный оплот, протянувшийся вдоль южной границы Серебряного бора.",kw={"arugal","darius crowley","genn greymane","gilneas","greymane wall","pyrewood","silverpine","аругал","дариус кроули","дженн седогрив","гилнеас","стена седогрива","деревня погребальных костров","серебряный бор"},ang={["faction:Alliance"]="Стена Седогрива — горькое напоминание о предательстве Гилнеаса. Когда Лордерон пал перед Плетью, Седогрив остался глух к бывшим союзникам и бросил их погибать у своих ворот.",["faction:Horde"]="Для Отрекшихся, занявших Серебряный бор, стена образует непроходимую южную границу, скрывающую человеческое королевство, чьи намерения и внутренняя сила остаются совершенно неизвестными."},sec={{t="Памятник изоляции",b="После Второй войны король Генн Седогрив затаил обиду на Альянс Лордерона, особенно из-за налогов на содержание лагерей для орков и строительство Крепости Стражей Пустоты. Решив, что Гилнеас отдал достаточно золота и крови за чужие беды, Седогрив вышел из Альянса и приказал возвести колоссальную преграду поперек начала полуострова. Тем самым он бросил земли лорда Дариуса Кроули, включая Деревню Погребальных Костров и Янтарную мельницу, оставив их по северную сторону стены. Когда Третья война принесла Чуму нежизни и бесчисленных отчаявшихся беженцев к подножию стены, ворота остались безжалостно запертыми."},{t="Цена уединения",b="Хотя стена уберегла полуостров от армий Плети, безопасность обошлась дорого. Гилнеасские войска ненадолго открыли ворота во время войны, чтобы сражаться с нежитью, но были разгромлены. В отчаянии король Седогрив приказал верховному магу Аругалу призвать диких воргенов. Звери отбросили Плеть, но обратились против призвавших. Солдаты Седогрива отступили и снова заперли ворота, однако зараженные бойцы принесли звериную заразу внутрь. За холодной безмолвной стеной внутренний мятеж и подкрадывающееся проклятие разрывают изолированное королевство."}},faq={{q="Что находится за Стеной Седогрива?",a="За стеной лежит полуостровное королевство Гилнеас. Им правит король Генн Седогрив, который до Третьей войны полностью изолировал страну от Лордерона и остального мира, прекратив всякую торговлю и связь.",al={"what is behind the wall","where does greymane wall lead","what kingdom is behind the wall","что за стеной","куда ведет стена седогрива","какое королевство за стеной"}},{q="Можно ли открыть ворота Стены Седогрива?",a="Нет. Массивная решетка и окованные железом двери надежно заперты с южной стороны. Гилнеас прервал все контакты с внешним миром, и никто не входит и не выходит.",al={"how to get past greymane wall","can you open greymane wall","open the gate","как пройти за стену седогрива","можно ли открыть стену седогрива","открыть ворота"}},{q="Почему стену построили здесь, а не южнее?",a="Стена использовала окружающую горную местность как природную преграду. Строительство вдоль этого хребта вынудило королевство бросить северные владения лорда Дариуса Кроули, включая Деревню Погребальных Костров и Янтарную мельницу, и посеяло жестокий раздор внутри Гилнеаса.",al={"why did they build it here","why cut off pyrewood","crowley lands cut off","почему построили здесь","почему отрезали деревню погребальных костров","земли кроули отрезаны"}},{q="Что стало с беженцами, бежавшими сюда во время Третьей войны?",a="Когда Плеть опустошала Лордерон, толпы бегущих людей-беженцев собрались у стены, моля о впуске. Король Седогрив отказался отпереть ворота, защищая свое королевство, и отчаявшихся беженцев в конце концов перебила нежить снаружи.",al={"scourge refugees wall","refugees outside greymane wall","плеть беженцы стена","беженцы у стены седогрива"}}},fp="13,242,23.673.0,22.617.1,35.216.0,44.176.0,53.268.0,65.257.0"}
P.entries["subzone:grim-batol"] = {n="Грим Батол",s="Грим Батол — древняя разрушенная горная крепость дворфов, нависающая над восточным краем Болотины. Построенная кланом Громового Молота, оставленная после темного проклятия во время Войны трех молотов, а позднее занятая орками Драконьей Пасти как логово для разведения драконов, она с запечатанными вратами остается зловещим пятном на нагорье.",h="Грим Батол — древняя разрушенная горная крепость дворфов, нависающая над восточным краем Болотины.",kw={"alexstrasza","demon soul","dragonmaw","grim batol","modgud","nekros","wetlands","wildhammer","алекстраза","душа демона","драконья пасть","грим батол","модгуд","некрос","болотина","громовой молот"},ang={["faction:Horde"]="Гора олицетворяет мрачные высоты Второй войны, когда клан Драконьей Пасти подчинил порабощенных драконов, чтобы завоевать небеса, прежде чем потерпел жестокий крах.",["race:Dwarf"]="Для дворфов Грим Батол — горькое свидетельство Войны трех молотов: некогда гордый город-побратим Стальгорна, навсегда ставший непригодным для жизни из-за колдовства Черного Железа."},sec={{t="Дважды проклятая крепость",b="После древней междоусобной войны трех кланов тан Хардрос Громовой Молот вырубил Грим Батол в неровных горах к востоку от болот. Во время Войны трех молотов колдунья Черного Железа Модгуд осадила крепость. Хардрос сразил ее, но перед смертью Модгуд навлекла на камни злую тень. Остаточная порча сделала залы непригодными для жизни, и уцелевшие дворфы Громового Молота покинули великолепное королевство и ушли на север, во Внутренние земли."},{t="Цепи Королевы драконов",b="Столетия спустя, во время Второй войны, у крепости появилось более мрачное назначение: Оргрим Молот Рока отправил клан Драконьей Пасти занять ее. Под началом чернокнижника Некроса Черепокола орки с помощью древнего артефакта, Души демона, поработили красную Королеву драконов Алекстразу в глубинах горы. Ей пришлось выводить потомство для военных нужд Орды, и она оставалась в цепях, пока небольшой отряд героев не разбил артефакт. Освободившись, разъяренный Аспект драконов испепелил орков внутри, оставив Грим Батол тлеющими пустынными руинами под пристальным наблюдением уцелевших красных драконов."}},faq={{q="Можно ли игрокам войти в Грим Батол?",a="Нет. Колоссальные каменные врата в конце горной дороги надежно заперты и недоступны для путников. Посетить можно только внушительные врата и внешние укрепления в восточных горах Болотины.",al={"can i go inside grim batol","is grim batol open","grim batol gate","можно ли войти в грим батол","открыт ли грим батол","врата грим батола"}},{q="Почему дворфы Громового Молота покинули его?",a="Во время Войны трех молотов колдунья Черного Железа Модгуд наложила на твердыню мерзкое теневое проклятие, прежде чем была убита. Оставшаяся порча сделала крепость непригодной для жизни Громовых Молотов, и они ушли, построив Заоблачный Пик во Внутренних землях.",al={"why did dwarves leave grim batol","wildhammer curse","modgud curse","почему дворфы покинули грим батол","проклятие громового молота","проклятие модгуд"}},{q="Что стало с орками Драконьей Пасти, жившими здесь?",a="Когда маг Ронин и его спутники разбили Душу демона, плененная Королева драконов Алекстраза освободилась от цепей. Разъяренные жестоким пленом, она и ее потомство испепелили Некроса Черепокола и разгромили Драконью Пасть в крепости.",al={"dragonmaw grim batol","what happened to the orcs here","nekros skullcrusher","драконья пасть грим батол","что стало с орками","некрос черепокол"}},{q="Кто сейчас контролирует Грим Батол?",a="Сейчас Грим Батол — заброшенные руины. Хотя остатки клана Драконьей Пасти и дикие звери еще обитают в окрестных скалах, Красный драконий род бдительно следит за проклятой горой, чтобы ее мрачная история не повторилась.",al={"who owns grim batol","who lives in grim batol now","кто владеет грим батолом","кто живет в грим батоле сейчас"}}},fp="10,331,23.518.0,26.609.0,29.218.0,42.280.0,51.264.0,34.242.0"}
P.entries["subzone:grimesilt-dig-site"] = {n="Карьер Грязнули",s="Карьер Грязнули — археологические раскопки в Тлеющем ущелье, начатые дворфами Стальгорна. Захваченный враждебными дворфами Черного Железа, карьер теперь прочно под контролем врага, а уцелевшие участники первоначальной экспедиции пытаются выжить в укрытии.",h="Карьер Грязнули — археологические раскопки в Тлеющем ущелье, начатые дворфами Стальгорна.",kw={"archaeology","dark iron","dorius stonetender","excavation","grimesilt dig site","ironforge","searing gorge","археология","черное железо","дориус хранитель камня","раскопки","карьер грязнули","стальгорн","тлеющее ущелье"},ang={["faction:Alliance"]="Карьер олицетворяет начинание Стальгорна, безжалостно сорванное дворфами Черного Железа: осажденные подданные Альянса ждут эвакуации на опасной территории.",["race:Dwarf"]="Для дворфов Бронзобородов Карьер Грязнули — горькое напоминание об угрозе Черного Железа прямо за горами и об опасностях, грозящих дворфийским древностям и археологам во враждебных землях."},sec={{t="Спорные раскопки",b="Расположенный в покрытых сажей бесплодных землях Тлеющего ущелья, Карьер Грязнули начинался как экспедиция, одобренная учеными Стальгорна, искавшими реликвии под скалами. Предприятие жестоко оборвалось, когда местные дворфы Черного Железа прогнали землекопов и присвоили оборудование. Сегодня котлован кишит стражами Черного Железа, а раненые и разрозненные выжившие из первоначальной стальгорнской команды заперты в карьере и вокруг него."}},faq={{q="Кто изначально основал Карьер Грязнули?",a="Раскопки начали дворфы Бронзобороды из Стальгорна. Их отряд отправили извлечь древние артефакты из-под Тлеющего ущелья, но на него напали и вытеснили.",al={"who dug grimesilt","who made grimesilt dig site","grimesilt founders","кто копал карьер грязнули","кто основал карьер грязнули","основатели карьера грязнули"}},{q="Кто сейчас контролирует раскопки?",a="Раскопки захватил клан Черного Железа. Сейчас он занимает котлованы и охраняет оставшиеся инструменты и территорию от любых попыток Стальгорна вернуть эти земли.",al={"who owns grimesilt","grimesilt enemies","who is at grimesilt","кто владеет карьером грязнули","враги в карьере грязнули","кто в карьере грязнули"}},{q="Остались ли выжившие из первоначальной команды?",a="Да. Несколько рабочих сумели выжить, в том числе раненый землекоп Дориус Хранитель Камня, лежащий у дна котлована, и еще один несчастный товарищ, прячущийся в ближайшем нужнике.",al={"survivors at grimesilt","dorius stonetender","who is trapped at grimesilt","выжившие в карьере грязнули","дориус хранитель камня","кто заперт в карьере грязнули"}}},fp="18,279,22.463.0,50.183.0,30.171.0,47.184.0"}
P.entries["subzone:grimtotem-compound"] = {n="Лагерь Зловещего Тотема",s="Лагерь Зловещего Тотема — укрепленное племенное поселение в глубине дебрей Фераласа, к востоку от эльфийских руин Забытого Города. Лагерь занимает агрессивный и замкнутый клан Зловещего Тотема и использует его как базу для таинственных и разрушительных действий в регионе.",h="Лагерь Зловещего Тотема — укрепленное племенное поселение в глубине дебрей Фераласа, к востоку от эльфийских...",kw={"compound","dire maul","feralas","gnolls","grimtotem","sprite darter","tauren","лагерь","забытый город","фералас","гноллы","зловещий тотем","мотылек-фея","таурены"},ang={["faction:Alliance"]="Зловещий Тотем неустанно враждебен ночным эльфам и их союзникам, и это поселение становится опасной преградой в сердце Фераласа.",["race:Tauren"]="Клан Зловещего Тотема лишь для вида почитает Кэрна Кровавого Копыта, но такие места, как этот лагерь, раскрывают его истинные необузданные амбиции вдали от бдительных глаз Громового Утеса."},sec={{t="Оплот Черного племени",b="Лагерь Зловещего Тотема состоит из двух стоянок к востоку от Забытого Города и дает клану Зловещего Тотема прочный плацдарм в Фераласе. В отличие от таурен, союзных Кэрну Кровавому Копыту в Громовом Утесе, Зловещий Тотем здесь действует независимо и враждебно к чужакам. В южной части поселения они держат пойманных мотыльков-фей в большой деревянной клетке для своих темных целей, а по северной окраине бродят дикие гноллы."}},faq={{q="Кто живет в Лагере Зловещего Тотема?",a="Поселение принадлежит клану Зловещего Тотема — агрессивному и скрытному племени таурен, известному ксенофобией и жестокими методами. Оно действует отдельно от племен Мулгора, союзных Орде.",al={"who is here","grimtotem compound mobs","who controls grimtotem compound","кто здесь","мобы лагеря зловещего тотема","кто контролирует лагерь зловещего тотема"}},{q="Почему в лагере в клетках сидят мотыльки-феи?",a="Зловещий Тотем поймал местных мотыльков-фей и запер их в огромной клетке в южной деревне. Их интерес к этим волшебным существам, по-видимому, связан с темными опытами и использованием природной магической сущности Фераласа.",al={"why are faerie dragons caged","caged sprite darters","grimtotem sprite darters","почему феи в клетках","пойманные мотыльки-феи","мотыльки-феи зловещего тотема"}},{q="Где находится Лагерь Зловещего Тотема?",a="Лагерь расположен в центральной части Фераласа, к востоку от древних руин высокорожденных в Забытом Городе, а к северо-востоку неподалеку стоят лагерем дикие стаи гноллов.",al={"grimtotem compound location","where is grimtotem compound","где лагерь зловещего тотема","расположение лагеря зловещего тотема"}}},fp="18,289,28.475.0,36.203.0,45.238.0,40.153.0"}
P.entries["subzone:grizzled-den"] = {n="Серая берлога",s="Серая берлога — пещера в заснеженных холмах к юго-западу от Караноса. Это известное логово свирепых морозных вендиго, обитающих в Дун Мороге.",h="Серая берлога — пещера в заснеженных холмах к юго-западу от Караноса.",kw={"cave","dun morogh","frost","grizzled den","kharanos","wendigo","пещера","дун морог","мороз","серая берлога","каранос","вендиго"},ang={["profession:Mining"]="Во внешних и внутренних туннелях берлоги есть открытые залежи меди, так что это удобное место для ранней добычи, если вы сумеете отбиться от вендиго.",["race:Dwarf"]="Зачистка Серой берлоги — почти обряд посвящения для юных дворфов-горцев, тренирующихся возле Караноса."},sec={{t="Ледяное логово",b="Глубоко врезанная в скалы к юго-западу от Караноса, Серая берлога известна местным горцам как место гнездования стай вендиго Дун Морога. Эти агрессивные обезьяноподобные звери дышат морозом на незваных гостей и сбиваются в стаи, защищая свои логова. Несмотря на опасность, смелые охотники регулярно спускаются вглубь пещеры за густой гривой вендиго, которая хорошо стоит у мастеров, обивающих холодные кресла и сиденья экипажей утепленным мехом."},{t="Скрытые сокровища",b="Помимо грозных обитателей, извилистые туннели Серой берлоги привлекают искателей наживы, ищущих природные богатства. Старатели часто проходят за внешний вход, чтобы выбивать медные жилы из промерзших каменных стен, а отважные разведчики обшаривают темные углы в поисках брошенных сундуков. Но если зайти слишком глубоко, вы неизбежно встретите самых крупных и свирепых хищников берлоги, затаившихся во мраке."}},faq={{q="Где находится Серая берлога?",a="Серая берлога находится к юго-западу от Караноса в Дун Мороге, укрытая среди заснеженных горных хребтов.",al={"grizzled den location","where is grizzled den","how to get to grizzled den","где серая берлога","расположение серой берлоги","как добраться до серой берлоги"}},{q="Какие существа обитают в Серой берлоге?",a="Пещеру заполонили стаи свирепых вендиго. Эти агрессивные белошерстные звери могут выдыхать леденящий мороз и охотно набрасываются на любого чужака.",al={"what is in grizzled den","grizzled den mobs","creatures inside grizzled den","что в серой берлоге","монстры серой берлоги","существа в серой берлоге"}},{q="Зачем люди отправляются в Серую берлогу?",a="Охотники и искатели приключений идут в берлогу главным образом ради грив вендиго, высоко ценимых для изготовления теплых чехлов на сиденья. Другие спускаются в промерзшие туннели добывать медную руду из стен пещеры.",al={"why go to grizzled den","grizzled den quests","wendigo manes","зачем идти в серую берлогу","задания серой берлоги","гривы вендиго"}}},fp="12,183,20.488.0,16.464.0,34.113.0,40.158.0,44.225.0"}
P.entries["subzone:grizzlepaw-ridge"] = {n="Хребет Седых Лап",s="Хребет Седых Лап — суровый скалистый склон к югу от Телсамара в Лок Модане. Среди местных горцев он известен густой популяцией диких медведей, которых возглавляет легендарный зверь старина Черношкур.",h="Хребет Седых Лап — суровый скалистый склон к югу от Телсамара в Лок Модане.",kw={"bears","grizzlepaw ridge","loch modan","ol' sooty","sooty","thelsamar","медведи","хребет седых лап","лок модан","старина черношкур","черношкур","телсамар"},ang={["class:Hunter"]="Хребет — классическое место для выслеживания диких зверей и схватки с главными хищниками, такими как старина Черношкур.",["race:Dwarf"]="Хребет расположен рядом с Телсамаром, и медведи на нем постоянно досаждают местным горцам и мешают снабжению."},sec={{t="Обитель медведей",b="Хребет Седых Лап нависает над дорогой к югу от Телсамара и граничит на западе с Долиной Камнедробов. Это суровая местность, где господствуют хищные звери. Склоны заняты медведями, охраняющими свои владения и опасными для путников, идущих вдоль гор. В глубине хребта обитает старина Черношкур — огромный и необычайно свирепый медведь, которого боятся местные охотники. Путникам, идущим между поселениями дворфов, нужно внимательно следить за опушкой леса и скалистыми уступами наверху."}},faq={{q="Где находится Хребет Седых Лап?",a="Хребет Седых Лап лежит в центральных холмах Лок Модана, прямо к югу от поселка Телсамар и к востоку от Долины Камнедробов, кишащей троггами.",al={"where is grizzlepaw ridge","grizzlepaw ridge location","how to get to grizzlepaw ridge","где хребет седых лап","расположение хребта седых лап","как добраться до хребта седых лап"}},{q="Какие опасные существа обитают на Хребте Седых Лап?",a="Хребет кишит агрессивными медведями. Самый известный из них — старина Черношкур, исключительно крупный и свирепый зверь, который порой спускается к подножию горы.",al={"bears at grizzlepaw ridge","who is ol sooty","ol sooty loch modan","медведи хребта седых лап","кто такой старина черношкур","старина черношкур лок модан"}}},fp="16,205,17.468.0,34.150.0,50.184.0"}
P.entries["subzone:grol-dom-farm"] = {n="Ферма Гроль'дома",s="Ферма Гроль'дома — скромное орочье хозяйство в северных Степях, у дороги между Дуротаром и Перекрестком. Ферма, где живут Кранал Фисс с семьей, разводит свиней на засушливых равнинах, несмотря на постоянные набеги агрессивных местных свинобразов.",h="Ферма Гроль'дома — скромное орочье хозяйство в северных Степях, у дороги между Дуротаром и Перекрестком.",kw={"barrens","fire totem","grol'dom farm","groldom","kranal fiss","pig farm","razormane","swine","степи","тотем огня","ферма гроль'дома","гроль'дом","кранал фисс","свиноферма","иглогривые","свиньи"},ang={["class:Shaman"]="Для посвященных, идущих путем стихий, Ферма Гроль'дома — важная веха: здесь Кранал Фисс проведет вас через опасные обряды, необходимые для общения с духами огня.",["faction:Horde"]="Хозяйства вроде Фермы Гроль'дома показывают стойкость первых поселенцев Орды, пытавшихся построить устойчивую жизнь в суровых диких Степях."},sec={{t="Свиноферма в саванне",b="Ферма Гроль'дома появилась после заселения Дуротара и отражает первые попытки Орды возделывать сухие просторы Степей. Небольшим хозяйством занимаются орк Кранал Фисс и его дети. Здесь в основном разводят свиней, терпя суровую природу и набеги свинобразов из племени Иглогривых, рыскающих на соседних кряжах. Это одинокий суровый форпост, поставляющий необходимую пищу зарождающейся орочьей нации."},{t="Маяк для юных шаманов",b="Помимо обыденной роли свинофермы, это хозяйство тихо важно для посвященных Орды, идущих духовным путем. Кранал Фисс глубоко знает обряды стихий и играет ключевую роль в наставлении юных шаманов на их испытаниях. Искателей, идущих на запад от Оргриммара, регулярно направляют на эту скромную ферму, чтобы постичь тайны общения с первобытными духами огня."}},faq={{q="Что такое Ферма Гроль'дома?",a="Ферма Гроль'дома — орочья свиноферма в северных Степях. Основанная после возникновения Оргриммара, она служит отдаленным хозяйством, где трудятся орк Кранал Фисс и его дети.",al={"groldom farm info","what is this place barrens","orc pig farm","ферма гроль'дома","что это за место степи","орочья свиноферма"}},{q="Кто живет на Ферме Гроль'дома?",a="Ферму содержит орк по имени Кранал Фисс вместе с детьми. Вместе они ухаживают за загонами, пасут свиней и защищают свой скудный достаток от бродячих зверей и набегов свинобразов.",al={"who is at groldom farm","who lives here","kranal fiss home","кто на ферме гроль'дома","кто здесь живет","кранал фисс дом"}},{q="Почему шаманы приходят на Ферму Гроль'дома?",a="Кранал Фисс знает обряды стихий. Орков и тауренов-шаманов обычно посылают к нему в начале обучения, чтобы они прошли испытания, необходимые для получения Зова Огня и призыва Тотема огня.",al={"shaman fire quest","why come to groldom","kranal fiss shaman","задание шамана на огонь","зачем идти на ферму гроль'дома","кранал фисс шаман"}},{q="Какие опасности грозят ферме?",a="Окрестная саванна кишит свинобразами из племени Иглогривых. Эти агрессивные налетчики постоянно досаждают ферме, угрожая скоту и семье Кранала.",al={"why are there quillboars","who attacks groldom","farm enemies","откуда свинобразы","кто нападает на ферму гроль'дома","враги фермы"}}},fp="13,270,28.428.0,25.401.0,22.195.0,27.199.0,37.222.0,27.188.0"}
P.entries["subzone:grommash-hold"] = {n="Крепость Громмаш",s="Крепость Громмаш — укрепленная резиденция вождя Тралла, высоко в красных скалах Аллеи Мудрости в Оргриммаре. Названная в честь жертвы Громмаша Адского Крика, крепость служит командным центром и политическим сердцем новой Орды.",h="Крепость Громмаш — укрепленная резиденция вождя Тралла, высоко в красных скалах Аллеи Мудрости в Оргриммаре.",kw={"eitrigg","grommash hold","mannoroth","orgrimmar","thrall","thrall's fortress","valley of wisdom","эйтригг","крепость громмаш","маннорот","оргриммар","тралл","крепость тралла","аллея мудрости"},ang={["faction:Horde"]="Это само сердце суверенитета Орды, где заключаются договоры и направляются походы против угроз по всему Калимдору и Восточным королевствам.",["race:Orc"]="Для орков крепость и останки Маннорота у ее входа — величайшее свидетельство освобождения от демонического проклятия крови благодаря жертве Грома Адского Крика."},sec={{t="Резиденция Вождя",b="Крепость Громмаш, расположенная в безмятежной Аллее Мудрости, служит королевским двором и стратегическим убежищем Орды. Ее толстые каменные стены встроены в высокие стены каньона, и внутри заметно сумрачно и прохладно — вождь Тралл намеренно сделал так, чтобы посланники, просители и военачальники во время приемов оставались собранными и трезвыми. Здесь Тралл размышляет об обороне Калимдора; ему помогают опытные советники вроде Эйтригга, а навещают его вожди народов, такие как Вол'джин."},{t="Памятник свободе",b="Сразу за крепостью, на стволе древнего дерева, закреплены разбитые доспехи и рогатый череп властителя преисподней Маннорота. Они размещены в честь Грома Адского Крика, отдавшего жизнь, чтобы убить демона в Ясеневом лесу. Этот памятник — гордый символ освобождения орков от демонического проклятия крови и вечное суровое предостережение не впадать вновь в безрассудную дикость."}},faq={{q="Кто находится в Крепости Громмаш?",a="Вождь Тралл вершит здесь суд вместе с ключевыми вождями и советниками Орды, среди которых орочий старейшина Эйтригг, предводитель племени Черного Копья Вол'джин и воин Назгрел.",al={"who is in the hold","who lives in grommash hold","who rules here","кто в крепости","кто живет в крепости громмаш","кто здесь правит"}},{q="Почему она называется Крепость Громмаш?",a="Она названа в честь Громмаша «Грома» Адского Крика, легендарного вождя клана Песни Войны. Гром убил властителя преисподней Маннорота во время Третьей войны, заплатив жизнью за то, чтобы навсегда освободить орков от демонического рабства.",al={"why grommash hold","who was grommash","named after who","почему крепость громмаш","кто такой громмаш","в честь кого названа"}},{q="Что за гигантские кости выставлены снаружи?",a="Череп и доспехи принадлежат Маннороту, повелителю демонов, чья кровь поработила орков в Дреноре. Останки доставили из Ясеневого леса и закрепили на стволе дерева у крепости как памятник свободе Орды.",al={"demon skull outside","mannoroth skull","bones in front","демонический череп снаружи","череп маннорота","кости перед входом"}},{q="Почему на городских указателях ее называют Крепостью Тралла?",a="Многие орочьи стражи и старые указатели до сих пор называют это строение Крепостью Тралла — по имени Вождя, который вершит в ней суд.",al={"thrall's fortress","thralls fortress","hold vs fortress","крепость тралла","замок тралла","крепость или цитадель"}}},fp="13,255,24.481.0,23.405.0,28.165.0,30.233.0,43.229.0,49.140.0"}
P.entries["subzone:grove-of-the-ancients"] = {n="Роща Древних",s="Роща Древних — священное убежище ночных эльфов среди развалин старого храма на юго-востоке Темных берегов. Эта тихая обитель у Петляющей реки служит местом сбора лесных духов, и за ней присматривает почтенное Древо Мудрости Ону.",h="Роща Древних — священное убежище ночных эльфов среди развалин старого храма на юго-востоке Темных берегов.",kw={"ancient of lore","circle of ancients","darkshore","grove of the ancients","onu","wildbend river","древо мудрости","круг древних","темные берега","роща древних","ону","петляющая река"},ang={["class:Druid"]="Роща — почитаемое природное святилище, дающее друидам прямую связь с мудростью Древа Мудрости Ону и духами леса.",["race:NightElf"]="Окруженная древними развалинами храма и охраняемая лесными духами, роща остается торжественным напоминанием о давней гармонии кальдораев с землей."},sec={{t="Убежище Петляющей реки",b="Роща Древних, укрытая у юго-восточных гор Темных берегов, — мирная обитель среди древних храмовых камней. Через ее сердце течет бурная Петляющая река, дающая тихое прибежище на побережье, все сильнее страдающем от порчи и беспокойных зверей. Роща служит местом встреч Круга Древних, где лесные духи и кальдораи поддерживают хрупкое равновесие леса."},{t="Хранители и стражи",b="Главная фигура рощи — Ону, величественное Древо Мудрости, наблюдающее за переменами судьбы этой земли и делящееся древней мудростью с путниками. Рядом с Ону находят покой странствующие торговцы и спящие друиды под сенью ветвей. Хотя здесь тихо, роща расположена близко к лагерям воинственных фурболгов на юго-востоке, поэтому она — важный пограничный форпост для часовых и друидов Альянса, следящих за югом Темных берегов."}},faq={{q="Где находится Роща Древних?",a="Роща расположена в юго-восточной части Темных берегов, у подножия гор, возле берегов Петляющей реки.",al={"grove of ancients location","where is grove of the ancients","onu location","расположение рощи древних","где роща древних","где ону"}},{q="Кто такой Ону?",a="Ону — Древо Мудрости, обитающее в роще. Он выступает старейшиной-наставником, наблюдает за юго-восточными лесами и советует друидам и путникам, пытающимся восстановить равновесие Темных берегов.",al={"who is onu","ancient in grove of ancients","tree guy darkshore","кто такой ону","древень в роще древних","говорящее дерево темные берега"}},{q="Что такое Круг Древних?",a="Круг Древних — собрание могущественных лесных духов и вековых древней, которые собираются в роще, чтобы общаться, делиться знаниями и обсуждать благополучие диких земель.",al={"circle of ancients","ancients meeting darkshore","круг древних","собрание древних темные берега"}},{q="Есть ли опасности возле рощи?",a="Сама роща — безопасное убежище с дружелюбными стражами и торговцами, но враждебные звери и лагеря воинственных фурболгов находятся сразу за рекой и на юго-востоке.",al={"grove threats","is grove safe","monsters near grove","угрозы роще","безопасна ли роща","монстры возле рощи"}}},fp="21,274,25.440.0,20.434.0,35.138.0,11.195.0,31.177.0,33.182.0"}
P.entries["subzone:growless-cave"] = {n="Промерзшая пещера",s="Промерзшая пещера — холодная пещера в скалах Альтеракских гор, где кишат свирепые горные йети. Она известна прежде всего как место, где находится Пламя Узеля — нечестивый ритуальный костер, связанный с темным некромантством Хелкулара.",h="Промерзшая пещера — холодная пещера в скалах Альтеракских гор, где кишат свирепые горные йети.",kw={"alterac","flame of uzel","frostmaw","growless cave","helcular","skhowl","yeti","альтерак","пламя узеля","морозная пасть","промерзшая пещера","хелкулар","сховл","йети"},ang={["class:Mage"]="Остатки Пламени Узеля — суровое предупреждение о том, что бывает, когда чародейство Кирин-Тора извращается ради некромантии.",["race:Undead"]="Пещера мрачно значима для Отрекшихся, помогающих отомстить Хелкулару: его темные обряды и реликвии до сих пор разбросаны по павшему Альтераку."},sec={{t="Логово зверей и темной магии",b="Промерзшая пещера скрыта на заснеженных высотах над предгорьями и служит прежде всего логовом для свирепых горных йети, бродящих по Альтераку. Путники на опасных склонах обычно обходят ее вход стороной, особенно когда рядом замечен печально известный йети Схоул. Помимо первобытной опасности со стороны зверей, у пещеры мрачное прошлое: внутри находится Пламя Узеля — магическая жаровня, оставленная честолюбивым человеком-магом Хелкуляром. Перед гибелью Хелкуляр собирался использовать этот костер в темном ритуале, чтобы стать личом, и его отвратительное тепло однажды выманило из ледяных пустошей огромного хищника Ледяную Пасть."}},faq={{q="Какие существа обитают в Промерзшей пещере?",a="В пещере живут дикие горные йети, обитающие в Альтераке. Иногда у самого входа бродит опасный редкий йети по имени Сховл.",al={"who lives here","growless cave mobs","what is inside growless cave","кто здесь живет","монстры промерзшей пещеры","что внутри промерзшей пещеры"}},{q="Что такое Пламя Узеля?",a="Пламя Узеля — ритуальный костер, разожженный Хелкуларом, бывшим магом Даларана, ставшим некромантом. Он создал его как часть запретного ритуала, который должен был превратить его в бессмертного лича.",al={"flame of uzel","pyre in growless cave","helcular flame","пламя узеля","костер в промерзшей пещере","пламя хелкулара"}},{q="Кто такая Морозная Пасть?",a="Морозная Пасть — огромный, исключительно свирепый йети, бродящий по вершинам Альтерака. Раньше, если сжечь свежее мясо на Пламени Узеля, ненасытный зверь приходил прямо к пещере.",al={"frostmaw yeti","frostmaw","йети морозная пасть","морозная пасть"}},{q="Зачем путники приходят сюда?",a="Искатели приключений, отваживающиеся войти в пещеру, обычно охотятся на опасных йети ради шкур или ищут оставшиеся некромантические артефакты, связанные с наследием Хелкулара в Альтераке.",al={"why go to growless cave","growless cave quests","зачем идти в промерзшую пещеру","задания промерзшей пещеры"}}},fp="13,244,30.657.0,37.146.0,26.207.0,16.187.0,33.171.0"}
P.entries["subzone:gunther-s-retreat"] = {n="Приют Гюнтера",s="Приют Гюнтера — уединенное островное убежище на Озере Ясноводном в центре Тирисфальских лесов. Это прибежище Гюнтера Чародея, отступника-некроманта, силой воли освободившегося от Плети. Не доверяя чужакам, затворник окружает свой лагерь верными нежитью-слугами, чтобы отпугивать незваных гостей.",h="Приют Гюнтера — уединенное островное убежище на Озере Ясноводном в центре Тирисфальских лесов.",kw={"brightwater lake","gunther arcanus","gunther's retreat","lich","lillith's dinner table","tirisfal glades","undead","озеро ясноводное","гюнтер чародей","приют гюнтера","лич","обеденный стол лиллит","тирисфальские леса","нежить"},ang={["class:Mage"]="Маги оценят редкий подвиг Гюнтера: его магическая воля была достаточно сильна, чтобы полностью разорвать ментальную хватку Короля-лича без посторонней помощи.",["race:Undead"]="Гюнтер Чародей повторяет трагедию самих Отрекшихся: свободный от Короля-лича, он остается подозрительным и настороженным к миру, который, как он полагает, все еще в рабстве у Плети."},sec={{t="Затворник на Озере Ясноводном",b="Приют Гюнтера, скрытый среди туманных вод Озера Ясноводного, — неприметный островной лагерь, который легко принять за очередной оплот Плети. Его хозяин, Гюнтер Чародей, совершил то, на что способны немногие смертные чародеи: после воскрешения в нежити его тайное мастерство позволило ему вырвать душу из железной хватки Короля-лича без чьей-либо помощи. Не доверяя никому, Гюнтер решил, что остальная нежить Лордерона все еще марионетки Плети. Он удалился на этот одинокий остров, чтобы спокойно заниматься своим ремеслом, и выставил зомби-стражей, которые разрывают любого, кто пересечет воду."}},faq={{q="Кто живет в Приюте Гюнтера?",a="Остров населяет Гюнтер Чародей, могущественный некромант, освободившийся от власти Короля-лича собственными силами. Он живет там вместе со свитой нежити-рабов, охраняющих его лагерь.",al={"gunther island","who is on the island","gunther's retreat master","остров гюнтера","кто на острове","хозяин приюта гюнтера"}},{q="Почему нежить на острове враждебна?",a="Гюнтер Чародей считает, что вся остальная нежить в Тирисфале все еще порабощена Плетью. Он ценит свою независимость превыше всего, поэтому его слуги получили приказ нападать на любого, кто приблизится к острову.",al={"why does gunther attack","why hostile","is gunther scourge","почему гюнтер нападает","почему враждебны","гюнтер из плети"}},{q="Союзен ли Гюнтер Отрекшимся?",a="Сначала нет. Хотя Гюнтер, как и Отрекшиеся, — нежить со свободной волей, он полностью замкнулся в себе. Власти Подгорода стремятся доказать ему, что они тоже свободны от хватки Короля-лича, и привлечь его таланты на свою сторону.",al={"is gunther in the horde","gunther forsaken","gunther undercity","гюнтер в орде","гюнтер отрекшийся","гюнтер подгород"}},{q="Что за маленький островок к юго-западу от приюта?",a="У юго-западного края Приюта Гюнтера лежит крошечный безымянный островок, известный как Обеденный стол Лилит, — любопытная и жутковатая достопримечательность в водах Озера Ясноводного.",al={"lillith dinner table","small island near gunther","table island","обеденный стол лиллит","маленький остров у гюнтера","остров-стол"}}},fp="17,338,29.608.0,31.204.0,41.230.0,37.249.0,49.191.0"}
P.entries["subzone:haldarr-encampment"] = {n="Лагерь Халдарр",s="Лагерь Халдарр — оскверненный форпост сатиров в западной Азшаре, к северо-востоку от Святилища Песни Теней и к юго-западу от Храбростана. Густо населенный свирепыми сатирами Халдарр, он остается опасной язвой среди древних эльфийских руин. Здесь же в плену находится раненая часовая ночных эльфов Кельдара Солнечный Клинок.",h="Лагерь Халдарр — оскверненный форпост сатиров в западной Азшаре, к северо-востоку от Святилища Песни Теней и...",kw={"azshara","encampment","haldarr","keldara sunblade","satyr","shadowsong shrine","valormok","азшара","лагерь","халдарр","кельдара солнечный клинок","сатир","святилище песни теней","храбростан"},ang={["faction:Horde"]="Это густое гнездо демонов к юго-западу от Храбростана представляет непосредственную угрозу для разведчиков и линий снабжения Орды, продвигающихся по утесам Азшары.",["race:NightElf"]="Для кальдораев сатиры Халдарр — позорное, неизменное напоминание о падении древних высокорожденных в демоническое безумие, а спасти часовую Кельдару Солнечный Клинок из их лап — долг."},sec={{t="Логово демонических отродий",b="Лагерь Халдарр, расположенный среди разбитых камней западной Азшары, служит местом сбора клана сатиров Халдарр. Эти искаженные создания, древние потомки высокорожденных, проклятых демонической скверной во время Раскола, активно охотятся на всех, кто идет через осенние леса, и досаждают им. Густое поселение постоянно угрожает как силам Орды в соседнем Храбростане, так и редеющим часовым ночных эльфов, пытающимся наблюдать за регионом."},{t="Плененная часовая",b="Среди зловещих обитателей лагеря находится часовая Кельдара Солнечный Клинок, раненая и застрявшая в сердце вражеской земли. Ее присутствие делает Лагерь Халдарр срочной заботой для тех, кто хочет помешать мерзким делам сатиров и выяснить, почему она остается в плену у демонов."}},faq={{q="Что такое Лагерь Халдарр?",a="Лагерь Халдарр — оскверненное поселение в западной Азшаре, находящееся под властью клана сатиров Халдарр. Он лежит к юго-западу от форпоста Орды Храбростан и к северо-востоку от Святилища Песни Теней.",al={"haldarr encampment lore","what is haldarr","who lives in haldarr encampment","предания лагеря халдарр","что такое халдарр","кто живет в лагере халдарр"}},{q="Кто такие Халдарр?",a="Халдарр — свирепая секта сатиров, обитающая в Азшаре. Как и все сатиры, они происходят от древних ночных эльфов, заключивших демонические сделки во время Войны Древних; проклятые, они превратились в козлоногих демонов, служащих воле остатков Пылающего Легиона.",al={"haldarr satyrs","who are the satyrs here","сатиры халдарр","кто здесь сатиры"}},{q="Кто такая часовая Кельдара Солнечный Клинок?",a="Часовая Кельдара Солнечный Клинок — раненая ночная эльфийка, которую держат в Лагере Халдарр; ее окружают враждебные сатиры, не выпускающие ее со своей территории.",al={"keldara sunblade","injured night elf","who is the captive here","кельдара солнечный клинок","раненая ночная эльфийка","кто здесь пленница"}},{q="Чем этот лагерь опасен для путников поблизости?",a="Лагерь густо заселен агрессивными сатирами, которые патрулируют окрестные тропы и угрожают им, подвергая опасности как операции Орды из Храбростана, так и любых одиноких разведчиков в округе.",al={"is haldarr dangerous","why clear haldarr","опасен ли халдарр","зачем зачищать халдарр"}}},fp="18,354,20.474.0,21.324.1,31.196.0,20.256.0,33.164.0,47.194.0"}
P.entries["subzone:hall-of-arms"] = {n="Зал Оружия",s="Зал Оружия — штаб военной мощи Стальгорна и главный арсенал дворфийского королевства. Этот укрепленный комплекс расположен в Военном квартале: здесь обучают дворфийских бойцов и организуют отправку тяжелой брони и воздушных боевых машин.",h="Зал Оружия — штаб военной мощи Стальгорна и главный арсенал дворфийского королевства.",kw={"battlemasters","dwarven army","flying machines","hall of arms","ironforge","military ward","steam tanks","полководцы","дворфийская армия","летающие машины","зал оружия","стальгорн","военный квартал","паровые танки"},ang={["class:Warrior"]="Это здание — главное место сбора дворфийских воинов и ветеранов в столице, где проводится обучение и действует руководство полководцев.",["race:Dwarf"]="Для дворфов Зал Оружия воплощает союз воинской дисциплины и механической изобретательности Каз Модана: здесь размещены танки и воздушные эскадрильи, защищающие горное королевство."},sec={{t="Арсенал сердца горы",b="Зал Оружия находится в юго-восточной части Военного квартала и служит оперативным командным центром вооруженных сил Стальгорна. Помимо опытных наставников для воинов и охотников, этот обширный комплекс является огромным складом и сборным пунктом для механизированной войны. Тяжелые паровые танки собирают и обслуживают прямо здесь, чтобы усилить поля сражений Альянса, а гирокоптеры и летающие машины поднимаются промышленными конвейерами и запускаются через вертикальные шахты в потолке пещеры к Аэродрому Стальгорна наверху."}},faq={{q="Для чего нужен Зал Оружия?",a="Это штаб и командный центр военных сил Стальгорна. Он служит одновременно тренировочной площадкой для воинов и охотников и важным складом, где обслуживают и отправляют боевые машины, такие как паровые танки и гирокоптеры.",al={"what is hall of arms","hall of arms role","why hall of arms exists","что такое зал оружия","роль зала оружия","зачем нужен зал оружия"}},{q="Куда направляются летающие машины, запускаемые через потолок?",a="Дворфийские летающие машины поднимаются конвейерами и запускаются через вертикальные шахты в потолке прямо к Аэродрому Стальгорна на склонах горы. Эта шахта — один из немногих прямых выходов на поверхность из горы, помимо главных ворот.",al={"ceiling shaft ironforge","flying machine tunnel","where do copters go","шахта в потолке стальгорна","туннель летающих машин","куда летят гирокоптеры"}},{q="Кого можно найти в Зале для обучения?",a="В здании находятся наставники воинов и охотников, а также полководцы Альянса, которые организуют передвижение войск и набор на более широкие фронты по всему континенту.",al={"trainers in hall of arms","who teaches here","наставники в зале оружия","кто здесь учит"}},{q="Где находится Зал Оружия?",a="Он расположен в юго-восточной части Стальгорна и замыкает Военный квартал.",al={"hall of arms location","how to get to hall of arms","расположение зала оружия","как добраться до зала оружия"}}},fp="12,275,31.579.0,40.244.0,58.272.0,40.179.0,34.97.0"}
P.entries["subzone:hall-of-arms-northshire"] = {n="Зал Оружия (Североземье)",s="Зал Оружия — военное крыло Аббатства Североземья к югу от Главного зала. Здесь опытные наставники обучают новых рекрутов Армии Штормграда искусству владения мечом, щитом и священному бою.",h="Зал Оружия — военное крыло Аббатства Североземья к югу от Главного зала.",kw={"elwynn forest","hall of arms","northshire abbey","northshire valley","paladin trainer","stormwind army","warrior trainer","элвиннский лес","зал оружия","аббатство североземья","долина североземья","наставник паладинов","армия штормграда","наставник воинов"},ang={["class:Paladin"]="Зал Оружия сочетает священную преданность с воинской закалкой и дает начинающим паладинам основы владения Светом наряду с боевым оружием.",["class:Warrior"]="Для воинов-людей, поступающих на службу, это крыло — место, где вы получаете самые первые уроки стойки, обращения с оружием и воинской дисциплины Армии Штормграда."},sec={{t="Основы стражи",b="Пока клирики и ученые размышляют над древними книгами через двор, в Библиотечном крыле, Зал Оружия звенит от ударов затупленной стали и тяжелого ритма воинских занятий. Эта палата на южной стороне Аббатства Североземья — главный учебный пункт для неопытных людей-бойцов и благочестивых новичков, берущих оружие в ряды Армии Штормграда. Здесь опытные боевые наставники и наставники-паладины учат основным стойкам, дисциплине и основам, необходимым для защиты Элвиннского леса от наседающих кобольдов, бандитов из Братства Справедливости и гноллов-налетчиков."}},faq={{q="Для чего нужен Зал Оружия?",a="Зал Оружия — первое место боевой подготовки в Аббатстве Североземья. Недавно завербованные солдаты, наемники и паладины получают здесь начальное обучение обращению с оружием и боевым приемам, прежде чем отправиться в большое королевство.",al={"what is this room","hall of arms purpose","what happens here","что это за комната","назначение зала оружия","что здесь происходит"}},{q="Кого можно найти в этом крыле?",a="В крыле работают опытные наставники воинов и паладинов, которые от имени Армии Штормграда обучают новобранцев воинской дисциплине, обращению со щитом и основным боевым приемам.",al={"who is in hall of arms","trainers hall of arms","who teaches here","кто в зале оружия","наставники зала оружия","кто здесь учит"}},{q="Где в Аббатстве Североземья находится Зал Оружия?",a="Зал Оружия расположен в южной части Аббатства Североземья, в него можно попасть прямо из центрального Главного зала; через двор аббатства ему симметрично отвечает Библиотечное крыло.",al={"hall of arms location","where is hall of arms","abbey layout","расположение зала оружия","где зал оружия","план аббатства"}}},fp="25,215,23.586.0,40.248.0,34.184.0,58.171.0"}
P.entries["subzone:hall-of-arms-tyr-s-hand"] = {n="Зал Оружия (Длань Тира)",s="Зал Оружия — сильно охраняемое крыло Аббатства Длани Тира на юго-востоке Восточных Чумных земель. Это сборный пункт и казармы для воинского авангарда Алого ордена, расквартированного в крепости. Он расположен напротив библиотеки и вмещает одних из самых фанатичных и хорошо бронированных бойцов ордена.",h="Зал Оружия — сильно охраняемое крыло Аббатства Длани Тира на юго-востоке Восточных Чумных земель.",kw={"abbey","armory","eastern plaguelands","hall of arms","scarlet crusade","tyr's hand","tyrs hand","аббатство","арсенал","восточные чумные земли","зал оружия","алый орден","длань тира"},ang={["class:Paladin"]="Для рыцарей Серебряной Длани вход в Зал Оружия — горькое зрелище: священные традиции святого боя превращены в фанатичную замкнутость.",["class:Warrior"]="Вооружение и дисциплинированная боевая подготовка в Зале Оружия представляют вершину человеческого милитаризма, пусть и служащего фанатизму."},sec={{t="Оплот стали",b="Зал Оружия, расположенный к югу от главного зала аббатства, служит арсеналом и казармой для воинственных сил Длани Тира. Если противоположное крыло хранит архивы и священные тексты, то это посвящено исключительно военному делу. Защитники Алого ордена, облаченные в тяжелые доспехи и поклявшиеся истребить нежить и всех, кого сочтут нечистыми, несут неусыпный караул в своем восточном оплоте, держа оружие заточенным, а щиты начищенными перед лицом окружающих ужасов Чумных земель."}},faq={{q="Где находится Зал Оружия?",a="Зал Оружия находится в Аббатстве Длани Тира — величественной соборной крепости внутри Длани Тира в юго-восточном углу Восточных Чумных земель. Он образует южное крыло комплекса аббатства напротив Библиотечного крыла.",al={"hall of arms location","where is hall of arms","tyrs hand abbey hall of arms","расположение зала оружия","где зал оружия","зал оружия аббатство длани тира"}},{q="Кто занимает Зал Оружия?",a="Крыло полностью занято элитными воинскими силами Алого ордена. Здесь собираются опытные воины, паладины и стражи, которые содержат вооружение и готовятся к бою с Плетью и любыми чужаками, вторгшимися в их убежище.",al={"who lives in hall of arms","hall of arms enemies","scarlet crusade hall of arms","кто живет в зале оружия","враги зала оружия","алый орден зал оружия"}},{q="Чем это крыло отличается от остального аббатства?",a="Если противоположное крыло аббатства посвящено учебе, созерцанию и священным писаниям, то Зал Оружия построен специально для физической обороны, размещения войск и содержания оружия. Он делает священный оплот грозным в военном отношении перед вторжениями Плети.",al={"purpose of hall of arms","what is hall of arms for","назначение зала оружия","для чего нужен зал оружия"}},{q="Могут ли члены Альянса войти туда мирно?",a="Нет. Несмотря на общие человеческие корни и почитание Света, Алый орден в Длани Тира совершенно фанатичен. Орден видит в чужаках возможных переносчиков чумы или пособников зла и нападает на путников как из Альянса, так и из Орды при первой встрече.",al={"is scarlet crusade friendly to alliance","can alliance visit hall of arms","will tyrs hand attack me","дружелюбен ли алый орден к альянсу","может ли альянс зайти в зал оружия","нападет ли длань тира"}}},fp="25,342,18.520.0,34.239.0,30.242.0,67.268.0,45.262.0"}
P.entries["subzone:hall-of-explorers"] = {n="Зал Исследователей",s="Зал Исследователей — обширное археологическое крыло Стальгорна и оживленный штаб дворфийской Лиги исследователей. Отчасти музей, отчасти архив, отчасти командный пункт экспедиций, он собирает реликвии, окаменелости и древние книги со всех уголков Азерота, чтобы восстановить забытое происхождение дворфов.",h="Зал Исследователей — обширное археологическое крыло Стальгорна и оживленный штаб дворфийской Лиги...",kw={"archaeology","explorers' league","hall of explorers","ironforge library","magellas","museum","археология","лига исследователей","зал исследователей","библиотека стальгорна","магеллас","музей"},ang={["race:Dwarf"]="Для дворфов-путешественников зал — главное хранилище наследия их народа: здесь собраны реликвии, помогающие раскрыть ваше древнее происхождение и связь с титанами."},sec={{t="Штаб Лиги",b="Зал Исследователей, занимающий северо-восточную пещеру Стальгорна и порой называемый Собранием исследователей, — нервный центр всех археологических работ, санкционированных Альянсом. Под руководством старшего исследователя Мунинна Магелласа ученые и полевые агенты координируют раскопки в далеких землях, присылая загадочные реликвии, древние механизмы титанов и доисторические кости. Огромная Библиотека в центре зала служит и публичным музеем, и закрытым хранилищем исторических преданий."}},faq={{q="Для чего нужен Зал Исследователей?",a="Это главный штаб и архивный музей Лиги исследователей. Ученые анализируют полевые отчеты, каталогизируют реликвии из раскопок и организуют археологические экспедиции, чтобы выяснить происхождение дворфов и древнего Азерота.",al={"hall of explorers purpose","what happens here","explorers league base","назначение зала исследователей","что здесь происходит","база лиги исследователей"}},{q="Кто руководит работой здесь?",a="Верховный исследователь Мунин Магеллас руководит экспедициями зала, музейной экспозицией и исследовательскими архивами в пределах квартала.",al={"who runs hall of explorers","explorers league leader","high explorer","кто управляет залом исследователей","глава лиги исследователей","верховный исследователь"}},{q="Как это место связано с остальным Стальгорном?",a="Зал Исследователей находится в северо-восточной части города. Арки напрямую соединяют его с Великой кузней на юго-западе, Одинокой пещерой на западе и Городом механиков на юге.",al={"how to get here","hall of explorers exits","where is hall of explorers","как добраться","выходы из зала исследователей","где зал исследователей"}}},fp="17,327,26.517.0,39.239.0,30.127.0,53.195.0"}
P.entries["subzone:hall-of-gears"] = {n="Зал Шестеренок",s="Зал Шестеренок — многоярусный промышленный зал в павшем Гномрегане, сразу за Заводным тоннелем. Некогда оживленный центр механизмов, он лежит в руинах: он затоплен токсичной жижей, по нему бродят слизь и облученные трогги.",h="Зал Шестеренок — многоярусный промышленный зал в павшем Гномрегане, сразу за Заводным тоннелем.",kw={"clean zone","clockwerk run","dormitory","gnomeregan","hall of gears","launch bay","radioactive","troggs","чистая зона","заводной тоннель","общежитие","гномреган","зал шестеренок","пусковая установка","радиоактивный","трогги"},ang={["profession:Engineering"]="Огромный масштаб автоматических передач и приподнятых платформ показывает вершину гномьей инженерии до падения, хотя теперь все сильно разъедено радиоактивными осадками.",["race:Gnome"]="Вид огромных шестерней и мостков, погруженных в облученную жижу, болезненно напоминает об отчаянном решении, которое отравило город и обрекло народ гномов на изгнание."},sec={{t="Разбитая машина",b="Зал Шестеренок, расположенный сразу за Заводным тоннелем, показывает катастрофический крах столицы гномов. Зал разделен на два основных уровня: верхние мостки удерживают агрессивные облученные трогги, прорывающиеся через обрушенные шахты. Внизу пол залит лужами радиоактивных осадков, где в токсичных стоках обитают едкая слизь и живые элементали яда."},{t="Пути через отходы",b="Зал служит важным перекрестком в глубине рабочих кварталов Гномрегана. С верхних мостков пути ведут в зараженные тупики и в относительно безопасные Чистую зону и Общежитие. Спуск в радиоактивные глубины ниже в конце концов выводит путников по извилистым служебным проходам к Пусковой установке, но на любом из этажей придется пробиваться через ужасы, оставшиеся после губительного плана Сикко Термоштепселя по выпуску газа."}},faq={{q="Где находится Зал Шестеренок?",a="Зал Шестеренок находится в глубине подземелья Гномреган, сразу за Заводным тоннелем. Дальше вглубь он соединяется с Чистой зоной, Общежитием и Пусковой установкой.",al={"hall of gears location","where is hall of gears","how to get to hall of gears","зал шестеренок где","где находится зал шестеренок","как добраться до зала шестеренок"}},{q="Почему нижний уровень полон радиоактивной жижи?",a="Когда главный механик Меггакрут приказал выпустить радиоактивный газ, чтобы отразить вторжение троггов, зараженные стоки собрались в низинных машинных залах города и превратили нижний этаж Зала Шестеренок в токсичную пустошь.",al={"why is it green","radioactive waste hall of gears","what is the sludge","почему зеленый","радиоактивные отходы зал шестеренок","что за жижа"}},{q="Какие существа обитают в этом зале?",a="Верхний уровень кишит мутировавшими облученными троггами, лезущими через пробитые туннели. Нижний ярус заполнен радиоактивной слизью, илом и неустойчивыми элементалями яда, возникшими из промышленных стоков.",al={"hall of gears enemies","what lives in hall of gears","hall of gears mobs","зал шестеренок враги","кто живет в зале шестеренок","зал шестеренок мобы"}},{q="Куда ведут выходы отсюда?",a="Верхние мостки ведут на юго-запад к Чистой зоне и Общежитию, а также в тупиковый служебный коридор на юго-востоке. Нижний облученный этаж имеет извилистый проход на запад, ведущий прямо к Пусковой установке.",al={"hall of gears exits","where to go from hall of gears","зал шестеренок выходы","куда идти из зала шестеренок"}}},fp="13,267,19.407.0,26.478.0,35.184.0,50.240.0,36.227.0,34.242.0"}
P.entries["subzone:hall-of-legends"] = {n="Зал Легенд",s="Зал Легенд — элитное военное убежище и казармы офицеров Орды в Аллее Силы Оргриммара. За его защищенным порогом защитники Орды собираются над планами сражений и вооружаются лучшим оружием, добытым в конфликтах по всему Азероту и за его пределами.",h="Зал Легенд — элитное военное убежище и казармы офицеров Орды в Аллее Силы Оргриммара.",kw={"hall of legends","officer barracks","orgrimmar","pvp","spoils of war","stone guard","valley of strength","зал легенд","казармы офицеров","оргриммар","пвп","трофеи войны","каменный страж","аллея силы"},ang={["class:Warrior"]="Для бойцов переднего края вход в Зал Легенд — вершина воинского уважения: он дает доступ к оружию, выкованному в конфликтах во многих мирах.",["faction:Horde"]="Зал Легенд — высшее свидетельство воинских достижений Орды: он дает признание, стратегический совет и ценное вооружение тем, кто проливает кровь за Вождя."},sec={{t="Убежище защитников Орды",b="Зал Легенд, расположенный недалеко от шумных улиц Аллеи Силы, служит закрытым оплотом для заслуженных офицеров Орды. За охраняемым входом стратеги и представители разных фракций, среди которых вождь Землерожденный из Громового Утеса, кровавый страж Хини'вана из племени Черного Копья и советник Виллингтон из Подгорода, совещаются над картами спорных земель и военным положением обеих фракций. Сюда допускаются только воины, проверенные в боях и достигшие звания каменного стража или выше, чтобы получить добычу и вооружение, соответствующие их положению."},{t="Трофеи войны",b="Зал — не просто офицерская гостиная: в нем находятся оружейные с проверенным в боях снаряжением со всего Азерота и разрушенного родного мира орков, Дренора. Многое из этого оружия было взято как трофеи в продолжающихся схватках с Альянсом и другими противниками. Для тех, кто поднимается по военным рангам, он — воплощение чести Орды, воинского мастерства и тяжело доставшейся победы."}},faq={{q="Кому разрешено входить в Зал Легенд?",a="Проход через порог зала открыт только защитникам Орды, достигшим звания каменного стража (6-й ранг) или выше в системе воинской чести. Солдат низших званий и обычных жителей разворачивают у входа.",al={"can i enter hall of legends","hall of legends requirement","rank required for hall of legends","можно ли войти в зал легенд","зал легенд требования","ранг для зала легенд"}},{q="Где находится Зал Легенд?",a="Зал Легенд расположен в Аллее Силы в Оргриммаре, рядом с главными казармами и административным центром города.",al={"where is hall of legends","hall of legends location","how to get to hall of legends","где зал легенд","зал легенд расположение","как добраться до зала легенд"}},{q="Что находится внутри Зала Легенд?",a="Внутри находится центральный стратегический стол, окруженный военными представителями разных рас Орды, а вокруг — карты Азерота и военные записи. Здесь же интенданты держат оружейные и выдают почетное оружие, доспехи и транспорт заслуженным офицерам.",al={"what is in hall of legends","hall of legends interior","что в зале легенд","зал легенд интерьер"}},{q="Есть ли у Альянса подобное место?",a="Да. Аналог Альянса — Зал Защитников в Старом городе Штормграда, который также служит казармами и оружейной для заслуженных бойцов Альянса.",al={"alliance hall of legends","alliance counterpart","зал легенд альянса","аналог для альянса"}}},fp="15,300,28.609.0,17.405.0,42.231.0,37.129.0,35.273.0,46.196.0"}
P.entries["subzone:hall-of-masks"] = {n="Зал Масок",s="Зал Масок — зловещий зал в затонувшем Храме Атал'Хаккара в Болоте Печали. Он украшен гигантскими масками-черепами и изуродован заваленной костями канавой и служит одним из первых порогов вглубь твердыни Атал'ай.",h="Зал Масок — зловещий зал в затонувшем Храме Атал'Хаккара в Болоте Печали.",kw={"atal'ai","broken hall","hall of masks","sunken temple","swamp of sorrows","temple of atal'hakkar","атал'ай","разрушенный зал","зал масок","затонувший храм","болото печали","храм атал'хаккара"},ang={["race:Troll"]="Для троллей Черного Копья этот зал показывает, на какие зловещие крайности шли фанатики Атал'ай в отчаянной погоне за Хаккаром Свежевателем Душ."},sec={{t="Жуткий порог",b="Located just past the staircase descending from the Broken Hall, the Hall of Masks serves as a central junction within the Sunken Temple. The chamber earns its name from the imposing, stylized skull masks mounted along its stone walls. Below them runs a deep trench choked with discarded bones, suggesting a macabre purpose whose exact nature is unknown. Beyond this eerie hall lie passages branching out to the Butchery, the Chamber of Blood, and the Den of the Caller."}},faq={{q="Где находится Зал Масок?",a="Зал Масок — внутреннее крыло Храма Атал'Хаккара, расположенное под водами Озера Слез в Болоте Печали. Вы доберетесь до него, спустившись мимо Разрушенного зала у входа в затонувший комплекс.",al={"hall of masks location","where is hall of masks","find hall of masks","зал масок где","где находится зал масок","найти зал масок"}},{q="Почему он называется Залом Масок?",a="Он получил имя от огромных резных масок-черепов, украшающих стены зала и нависающих над каждым, кто идет по коридорам храма.",al={"hall of masks name meaning","why masks","значение названия зал масок","почему маски"}},{q="Для чего служила канава в полу?",a="The trench is littered with bones, suggesting a macabre function. Its exact purpose is unknown.",al={"why are there bones in the floor","hall of masks bone pit","trench of bones","почему кости в полу","зал масок яма с костями","канава с костями"}},{q="Куда ведут проходы из этого зала?",a="За Залом Масок путь ведет глубже в нижние комплексы храма и напрямую соединяется с такими местами, как Мясницкая, Кровавая палата и Логово Призывателя.",al={"hall of masks exits","where does hall of masks lead","зал масок выходы","куда ведет зал масок"}}},fp="13,242,20.470.0,35.230.0,35.154.0,48.95.0,42.183.0"}
P.entries["subzone:hall-of-mysteries"] = {n="Зал Тайн",s="Зал Тайн, скрытый в Мистическом квартале Стальгорна, — духовное и научное сердце города для тайных искусств и божественного. В его освещенных синим светом стенах гномы и дворфы изучают древние тексты, постигают тайны Света и плетут чародейские чары вдали от лязга Великой кузни.",h="Зал Тайн, скрытый в Мистическом квартале Стальгорна, — духовное и научное сердце города для тайных искусств и...",kw={"hall of mysteries","ironforge","mage","mystic ward","paladin","priest","rohan","silver hand","tome of divinity","зал тайн","стальгорн","маг","мистический квартал","паладин","жрец","рохан","серебряная длань","фолиант божественности"},ang={["class:Paladin"]="Для дворфийских защитников Серебряной Длани зал — основа их призвания: здесь наставники назначают испытания добродетели и открывают доступ к священному Фолианту Божественности.",["class:Priest"]="Верховный жрец Рохан наставляет здесь служителей Света в духовных уроках, а затем отправляет многообещающих жрецов на юг для встречи с руководством в Штормграде."},sec={{t="Храм магии и веры",b="Освещенный особым сине-фиолетовым сиянием, Зал Тайн резко выделяется на фоне остального Стальгорна. Пока город вокруг живет камнем, железом и тяжелыми латами, пять высоких колонн зала укрывают ученых в мягких струящихся мантиях. Он объединяет чародейство и святую преданность и служит штаб-квартирой дворфийского жречества и Ордена Серебряной Длани в Каз Модане. Здесь юные клирики и рыцари изучают священные тексты, например Фолиант Божественности, и получают наставления, прежде чем отправиться в Собор Света Штормграда."}},faq={{q="Для чего нужен Зал Тайн?",a="Зал Тайн — главный центр Стальгорна как для божественной преданности, так и для тайного обучения. Он служит храмом Света и учебным залом, где дворфийские и гномьи жрецы, паладины и маги занимаются своим ремеслом, изучают древние писания и обучают новичков.",al={"what is this place","hall of mysteries purpose","why visit hall of mysteries","что это за место","зал тайн назначение","зачем посещать зал тайн"}},{q="Кто возглавляет здесь духовенство?",a="Верховный жрец Рохан надзирает за жречеством в зале и служит духовным наставником дворфийских служителей Света, наряду с наставниками-паладинами, такими как Вальгар Высокая Кузня, которые направляют рыцарей Серебряной Длани города.",al={"who runs hall of mysteries","priest leader ironforge","who is high priest rohan","кто управляет залом тайн","глава жрецов стальгорн","кто такой верховный жрец рохан"}},{q="Чем он отличается от Собора Света в Штормграде?",a="Если Собор Света Штормграда посвящен исключительно святой вере и торжественным богослужениям, то Зал Тайн гармонично объединяет священное учение и чародейскую науку под одной крышей. Его атмосфера скорее ученая и тихая, чем строго богослужебная.",al={"cathedral of light vs hall of mysteries","is it like stormwind cathedral","собор света или зал тайн","похож ли на собор штормграда"}},{q="Могут ли паладины пройти здесь свои испытания?",a="Да. Дворфийских паладинов направляют в зал изучать Фолиант Божественности под руководством Серебряной Длани: они получают наставления и священные испытания, проверяющие их сострадание, преданность и мужество.",al={"paladin quests ironforge","tome of divinity ironforge","dwarf paladin quests","задания паладина стальгорн","фолиант божественности стальгорн","задания паладина дворфа"}}},fp="17,341,27.605.0,45.289.0,26.230.0,59.266.0,49.211.0"}
P.entries["subzone:hall-of-the-brave"] = {n="Зал Храбрецов",s="Зал Храбрецов — большие казармы воинов на восточных высотах Аллеи Чести в Оргриммаре. Это главный учебный лагерь и дом гильдии для бойцов переднего края Орды, инструкторов и распорядителей боев.",h="Зал Храбрецов — большие казармы воинов на восточных высотах Аллеи Чести в Оргриммаре.",kw={"barracks","battlemaster","hall of the brave","orgrimmar","valley of honor","warrior trainer","warriors guild","казармы","распорядитель боев","зал храбрецов","оргриммар","аллея чести","учитель воинов","гильдия воинов"},ang={["class:Warrior"]="Зал Храбрецов — ваш воинский дом в столице: в нем находятся наставники, открывающие продвинутые стойки и боевые приемы по мере роста вашего мастерства.",["faction:Horde"]="Эти казармы — живая демонстрация дисциплины передовых войск Орды: в них находятся распорядители боев, собирающие войска для сражений по всему континенту."},sec={{t="Бастион воинов",b="Зал Храбрецов, возвышающийся над спокойными водами и тренировочными площадками Аллеи Чести, служит важным военным центром для растущей Орды. Внутри опытные офицеры и закаленные воины обучают новобранцев суровым основам ближнего боя, владению стойками и дисциплине. Зал уставлен тренировочными манекенами и оружием, и в нем находятся распорядители боев, организующие бойцов для крупных военных кампаний по всему Азероту."}},faq={{q="Для чего нужен Зал Храбрецов?",a="Это главные казармы и дом гильдии воинов в Оргриммаре. Здесь воины учатся приемам у опытных наставников, оттачивают удары на тренировочных манекенах и советуются с распорядителями боев о военных назначениях в спорных землях.",al={"what is hall of the brave","what is this building","hall of the brave purpose","что такое зал храбрецов","что это за здание","зал храбрецов назначение"}},{q="Где в Оргриммаре находится зал?",a="Зал Храбрецов расположен на восточной стороне Аллеи Чести, среди красных стен каньона над центральным прудом долины.",al={"where is hall of the brave","hall of the brave location","find warrior trainer orgrimmar","где зал храбрецов","зал храбрецов расположение","найти учителя воинов оргриммар"}},{q="Кого можно найти внутри зала?",a="The hall houses various warrior class trainers, battlemasters coordinating large-scale conflicts, and Horde grunts resting between active patrols.",al={"who is in hall of the brave","hall of the brave npcs","кто в зале храбрецов","зал храбрецов персонажи"}}},fp="17,246,21.443.0,45.254.0,39.151.0,33.146.0"}
P.entries["subzone:hammerfall"] = {n="Павший Молот",s="Павший Молот — главный укрепленный форпост Орды на Нагорье Арати, построенный на руинах печально известного лагеря для военнопленных Альянса. Он назван в честь легендарного бывшего вождя Оргрима Молота Рока, павшего неподалеку в борьбе за освобождение своего плененного народа. Сегодня орки и Отрекшиеся защищают поселение от враждебных огров Тяжелого Кулака, троллей Сухокожих и Лиги Аратора.",h="Павший Молот — главный укрепленный форпост Орды на Нагорье Арати, построенный на руинах печально известного...",kw={"arathi highlands","boulderfist","defilers","hammerfall","internment camp","orgrim doomhammer","thrall","witherbark","нагорье арати","тяжелый кулак","осквернители","павший молот","лагерь для военнопленных","оргрим молот рока","тралл","сухокожие"},ang={["faction:Horde"]="Павший Молот, окруженный враждебными ограми, лесными троллями и остатками Альянса, — единственная крепость Орды, обеспечивающая контроль над центральной частью Нагорья Арати.",["race:Orc"]="Для орков Павший Молот — священная земля: здесь Оргрим Молот Рока отдал жизнь, освобождая плененных соплеменников, и передал бремя вождя Траллу."},sec={{t="Наследие освобождения",b="После Второй войны люди Альянса построили по всему Лордерону огромные лагеря для содержания побежденных орков. Лагерь, стоявший здесь, был одним из крупнейших. Спустя годы Тралл и Оргрим Молот Рока напали на лагерь, чтобы освободить вялых пленников. Во время хаотичного отступления атаковавший рыцарь Альянса пронзил копьем наспинник Молота Рока, смертельно ранив легендарного Вождя. После Третьей войны новая Орда вернула разрушенные земли и основала здесь форпост, назвав его Павшим Молотом в память о погибшем предводителе."},{t="Опорный пункт на нагорье",b="Сегодня Павший Молот служит для Орды путем жизни в Арати. Гарнизон, окруженный враждебными землями, сражается с агрессивными ограми Тяжелого Кулака из Камен'гора и Крепости Тяжелого Кулака, а также с местными троллями Сухокожих. Кроме того, Осквернители из числа Отрекшихся сделали форпост плацдармом, чтобы захватить спорные ресурсы Низины Арати у Лиги Аратора, союзной Альянсу."}},faq={{q="Почему эта база называется Павший Молот?",a="Она названа в честь бывшего вождя Оргрима Молота Рока, который был смертельно ранен на этой земле копьем рыцаря Альянса во время освобождения лагеря для пленных орков.",al={"why hammerfall","hammerfall name origin","who died at hammerfall","почему павший молот","происхождение названия павший молот","кто погиб в павшем молоте"}},{q="Чем был Павший Молот до того, как Орда его отстроила?",a="Это был один из крупнейших лагерей Альянса Лордерона, построенный после Второй войны для содержания пленных орков.",al={"hammerfall history","what was hammerfall before","internment camp arathi","история павшего молота","чем был павший молот раньше","лагерь для военнопленных арати"}},{q="Кто сейчас руководит обороной Павшего Молота?",a="Обороной форпоста руководят такие представители Орды, как Драм Желчный и Сальный: они направляют воинов против наступающих огров Тяжелого Кулака и лесных троллей Сухокожих.",al={"hammerfall leaders","who is in charge of hammerfall","tallow drum fel","руководители павшего молота","кто главный в павшем молоте","сальный драм желчный"}},{q="Почему здесь размещены Отрекшиеся?",a="Осквернители из числа Отрекшихся действуют из Павшего Молота, чтобы добывать жизненно важные припасы в Низине Арати и противостоять Лиге Аратора, союзной Альянсу.",al={"forsaken hammerfall","why are undead in hammerfall","defilers arathi","отрекшиеся павший молот","почему нежить в павшем молоте","осквернители арати"}}},fp="10,390,22.578.0,27.405.0,35.178.0,48.124.0,46.163.0,36.140.0"}
P.entries["subzone:harborage"] = {n="Убежище",s="Убежище — тихое поселение изгнанников из числа уроженцев Дренора на севере Болота Печали. Многие их собратья, пораженные недугом, блуждают по окрестным топям и поддались безумию и первобытной злобе, но обитатели Убежища сумели сохранить рассудок и ясность ума. Они осторожно живут у кромки воды, ища покоя среди сурового и безжалостного захолустья.",h="Убежище — тихое поселение изгнанников из числа уроженцев Дренора на севере Болота Печали.",kw={"broken","draenethyst","harborage","lost ones","magtoor","swamp of sorrows","сломленные","дренетист","убежище","потерянные","магтур","болото печали"},ang={["faction:Alliance"]="Для путников Альянса, спускающихся из безопасного Красногорья в опасные болота, Убежище — одно из немногих мест на севере топи, где встречают не враждебными лицами, а без немедленного кровопролития.",["faction:Horde"]="Присутствие Орды в Каменоре в основном определяет жизнь болота, но эти замкнутые уцелевшие ведут собственное уединенное существование, держась особняком и не принимая ничью сторону в региональных конфликтах."},sec={{t="Приют в трясине",b="Убежище, притаившееся у северных гор Болота Печали, резко отличается от диких племен, бродящих по соседним водам. Этот небольшой лагерь из грубых кожаных шатров, украшенных загадочными подвешенными кристаллами, дает приют изгнанным уцелевшим дренорцам, отказавшимся сдать свой разум. Под руководством старейшин, таких как Магтур, они поддерживают хрупкий цивилизованный оплот, оставаясь настороже перед враждебной глушью, местными хищниками и дикими племенами своих павших братьев, затаившимися сразу за границей поселения."}},faq={{q="Кто живет в Убежище?",a="Убежище — дом для группы изгнанников Дренора: пораженных недугом гуманоидов, попавших в Азерот и сумевших сохранить разум и культуру, в отличие от диких племен в других частях болота.",al={"harborage residents","who is at harborage","who lives here","жители убежища","кто в убежище","кто здесь живет"}},{q="Почему здешние жители мирные, а другие болотные племена нападают?",a="Здешние жители сохранили рассудок и здравое мышление, несмотря на трагические телесные изменения и изгнание. Пока их пораженные недугом собратья по всему болоту теряли разум от одиночества и потрясений, обитатели Убежища сплотились, чтобы сохранить достоинство.",al={"why are they friendly","lost ones friendly","harborage hostile","почему они дружелюбны","потерянные дружелюбны","убежище враждебно"}},{q="Кто возглавляет Убежище?",a="Община полагается на уважаемых старейшин, таких как Магтур, ища у них руководства и совета в борьбе за выживание на чуждом болоте.",al={"harborage leader","magtoor","chief of harborage","предводитель убежища","магтур","вождь убежища"}},{q="Где находится Убежище?",a="Вы найдете его у северных утесов Болота Печали, к востоку от горного прохода, соединяющего топь с Красногорьем.",al={"harborage location","where is harborage","find harborage","где находится убежище","где убежище","найти убежище"}}},fp="9,401,19.591.0,27.199.0,65.274.0,24.125.0,31.154.0"}
P.entries["subzone:hearthglen"] = {n="Дольный Очаг",s="Дольный Очаг — укрепленное поселение в северных холмах Западных Чумных земель, чудом избежавшее полного физического разрушения при падении Лордерона. Сегодня его прочные каменные стены, башни и окружающие фермерские земли служат главным северным оплотом и тренировочной площадкой фанатичного Алого ордена.",h="Дольный Очаг — укрепленное поселение в северных холмах Западных Чумных земель, чудом избежавшее полного...",kw={"andorhal","hearthglen","mardenholde","scarlet crusade","taelan fordring","tirion fordring","western plaguelands","андорал","дольный очаг","марденхольд","алый орден","телан фордринг","тирион фордринг","западные чумные земли"},ang={["class:Paladin"]="Дольный Очаг был домом Тириона Фордринга и стал приютом для остатков Серебряной Длани после падения Лордерона. Пройдя по его подступам, понимаешь, насколько трагичным был раскол ордена и его превращение в фанатичный Алый орден.",["race:Undead"]="Для Отрекшихся Дольный Очаг — смертоносная заноза на севере. Размещенные здесь рыцари питают абсолютную, пылающую ненависть к нежити и активно патрулируют местность, уничтожая любых разведчиков, идущих на север от Андорала."},sec={{t="Бастион среди порчи",b="Пока соседний Андорал лежит в руинах, Дольный Очаг все еще похож на живой город Лордерона: здесь есть лесопилка, сторожевые башни, конюшни и работающий рудник. Исторически им правил из Крепости Марденхольд лорд Тирион Фордринг, и Дольный Очаг славился процветанием и стойкой обороной во время Второй войны. Когда во время Третьей войны Чума нежизни охватила Лордерон, принц Артас Менетил перехватил здесь зараженное зерно, очистил город от пораженных жителей и вместе с Утером Светоносным отразил мощную осаду Плети. Благодаря этому отчаянному вмешательству могучие стены Дольного Очага уцелели."},{t="Под Алым знаменем",b="После того как Серебряная Длань распалась вслед за крушением королевства, сын Тириона Телан Фордринг открыл Дольный Очаг как убежище для уцелевших паладинов. Однако горе и фанатизм, породившие Алый орден, вскоре поглотили крепость. Теперь Дольный Очаг — оплот религиозного экстремизма. Алые рыцари патрулируют подходы и несут стражу на стенах, жестоко казня любого чужака, живого или нежить, вторгшегося на их землю. Верховный лорд Телан Фордринг правит из Крепости Марденхольд, преданный слуга непримиримой войны ордена против Чумных земель."}},faq={{q="Почему Дольный Очаг выглядит таким чистым по сравнению с остальными Чумными землями?",a="Дольный Очаг избежал полного разрушения во время Третьей войны благодаря принцу Артасу и Утеру Светоносному, которые прибыли как раз вовремя, чтобы убить первых жертв чумы и сломить огромную осаду Плети. Позже Алый орден сильно укрепил перевал и долину и постоянно уничтожал наступающую Плеть, не давая порче захватить город.",al={"why is hearthglen intact","hearthglen not destroyed","hearthglen alive","почему дольный очаг цел","дольный очаг не разрушен","дольный очаг жив"}},{q="Кто контролирует Дольный Очаг сейчас?",a="Дольным Очагом владеет Алый орден. Им командует из Крепости Марденхольд верховный лорд Телан Фордринг, сын прежнего лорда и знаменитого паладина Тириона Фордринга.",al={"who rules hearthglen","hearthglen leader","who is in charge of hearthglen","кто правит дольным очагом","предводитель дольного очага","кто главный в дольном очаге"}},{q="Дружелюбен ли Дольный Очаг к посетителям из Альянса и Орды?",a="Нет. Алый орден относится ко всем чужакам с крайней враждебностью и паранойей. Представителей Орды считают чудовищными порождениями, а нейтральных путников из Альянса объявляют разносчиками чумы или еретиками, обреченными на немедленную казнь на месте.",al={"can i go to hearthglen","is hearthglen hostile","hearthglen safe","можно ли в дольный очаг","дольный очаг враждебен","дольный очаг безопасен"}},{q="Что случилось с Тирионом Фордрингом?",a="За годы до Третьей войны Тирион был лишен титула и отлучен Альянсом за защиту благородного орка по имени Эйтригг. Изгнанный в глушь, Тирион был вынужден покинуть Дольный Очаг, и командование Марденхольдом со временем перешло к его сыну Телану.",al={"where is tirion","tirion hearthglen history","why isn't tirion here","где тирион","история тириона в дольном очаге","почему тириона нет здесь"}}},fp="10,343,23.652.0,24.585.0,74.349.0,34.165.0,53.253.0,33.273.0"}
P.entries["subzone:helm-s-bed-lake"] = {n="Озеро Хельмово Ложе",s="Озеро Хельмово Ложе — замерзшее озеро в юго-восточных холмах Дун Морога. Поддерживаемая прорубь в толстом льду дает местным горцам и путникам жизненно важную пресную воду. Однако берег вокруг стал опасным из-за рыщущих зверей, наступающих троггов и враждебных лазутчиков Черного Железа.",h="Озеро Хельмово Ложе — замерзшее озеро в юго-восточных холмах Дун Морога.",kw={"dark iron","dun morogh","helm's bed lake","ice hole","narm faulk","trogg","черное железо","дун морог","озеро хельмово ложе","прорубь","нарм фолк","трогг"},ang={["faction:Alliance"]="Разведчикам Альянса, идущим на восток к Лок Модану, нужно быть здесь начеку: южная тропа проходит неприятно близко к засадам агрессивных дворфов Черного Железа.",["race:Dwarf"]="Для дворфов Стальгорна озеро Хельмово Ложе — и важный источник пресной воды, и досадный провал безопасности: диверсанты Черного Железа и трогги проникают все глубже в сердце Дун Морога."},sec={{t="Коварный берег",b="Озеро Хельмово Ложе тихо лежит под толстым зимним льдом в юго-восточной части Дун Морога. Местные дворфы держат во льду прорубь, чтобы набирать чистую пресную воду. Пересекать замерзшее пространство довольно безопасно, но задерживаться у берегов становится все рискованнее. По краям бродят дикие звери, по хребтам рыщут изгнанные из своих земель трогги, а отряд враждебных дворфов Черного Железа занял заброшенную хижину к югу от озера и яростно устраивает засады на всех проходящих путников."}},faq={{q="Почему посреди замерзшего озера есть прорубь?",a="Прорубь в толстом льду намеренно поддерживают местные дворфы, чтобы иметь постоянный доступ к свежей, незамерзшей воде в морозном климате Дун Морога.",al={"ice hole","water access","why is the ice broken","прорубь","доступ к воде","почему лед разбит"}},{q="Какие опасности таятся вокруг озера Хельмово Ложе?",a="Хотя сама поверхность озера прочна, по берегам охотятся хищные звери и забредшие трогги. На юге лагерь враждебных дворфов Черного Железа занимает старое здание и жестоко отгоняет всех, кто приближается.",al={"threats at helms bed lake","who is attacking here","enemies nearby","угрозы у озера хельмово ложе","кто здесь нападает","враги поблизости"}},{q="Кто такой Нарм Фолк?",a="Нарм Фолк — несчастный дворф, чье тело можно найти на берегу озера Хельмово Ложе: мрачная жертва внезапного роста враждебных угроз и лазутчиков Черного Железа в этой местности.",al={"narm faulk corpse","dead dwarf near lake","dead body at helms bed lake","нарм фолк тело","мертвый дворф у озера","труп у озера хельмово ложе"}},{q="Занимают ли дворфы Черного Железа озеро официально?",a="Само озеро они не захватили, но вооруженный отряд занял заброшенное строение к югу от него и использует его как передовую позицию для стычек в центральной части Дун Морога.",al={"dark irons at the lake","dark iron dwarf lodge","черное железо у озера","хижина дворфов черного железа"}}},fp="15,328,23.514.0,59.157.0,41.227.0,18.193.0,56.188.0"}
P.entries["subzone:heroes-vigil"] = {n="Часовые Вечности",s="Часовые Вечности — тихая священная поляна на центральном острове посреди Озера Каменных Столбов в восточной части Элвиннского леса. В ее центре стоит памятник, известный как Камень Памяти, посвященный павшим в Первой войне. Однако сегодня Штормград почти забросил это святилище, и им завладели опасные волшебники-отступники.",h="Часовые Вечности — тихая священная поляна на центральном острове посреди Озера Каменных Столбов в восточной...",kw={"elwynn forest","henze faulk","heroes vigil","heroes' vigil","rogue wizards","stone cairn lake","stone of remembrance","элвиннский лес","хенз фолк","часовые вечности","волшебники-отступники","озеро каменных столбов","камень памяти"},ang={["class:Mage"]="Волшебники-отступники, расположившиеся на этой священной земле, практикуют опасные, неконтролируемые искусства без дисциплины и одобрения Академии тайных наук.",["race:Human"]="Для людей Штормграда это священное каменное кольцо — горькое напоминание о кровавой цене Первой войны и о том, что королевство теперь не сумело защитить собственное наследие."},sec={{t="Забытый памятник",b="Часовые Вечности были возведены после Первой войны вокруг Камня Памяти — каменного круга с надписями, почитающего солдат и жителей, убитых при разорении Златоземья и окрестных долин Старой Ордой. Когда-то их чтили как священный оплот веры и самопожертвования, но нынешние правители Штормграда постепенно перестали уделять им внимание, и священная земля заросла и осталась без охраны солдат королевства."},{t="Во власти отступников",b="Поскольку королевство оставило остров без гарнизона, памятник захватили изгои. Шайка волшебников-отступников теперь владеет Озером Каменных Столбов и землей вокруг памятника и практикует дикую, недисциплинированную магию вдали от надзора Кирин-Тора и Академии тайных наук. Осквернение выглядит еще горше из-за трагических жертв у камней, среди которых тело Хенза Фолка, и путники гадают, вернется ли святилищу покой."}},faq={{q="Что такое Часовые Вечности?",a="Часовые Вечности — памятник на острове посреди Озера Каменных Столбов в восточной части Элвиннского леса. Он состоит из каменного кольца и мемориала, посвященных памяти жертв Первой войны.",al={"heroes vigil","what is heroes vigil","island shrine elwynn","часовые вечности","что такое часовые вечности","святилище на острове элвиннский лес"}},{q="Что увековечивает Камень Памяти?",a="Камень Памяти установлен в память о павших жителях и защитниках, погибших, когда орки из Орды разорили Златоземье и опустошили восточную часть Элвиннского леса во время Первой войны.",al={"stone of remembrance","monument meaning","what is the stone of remembrance","камень памяти","значение памятника","что такое камень памяти"}},{q="Кто сегодня контролирует Часовых Вечности?",a="Остров и Часовых Вечности захватили враждебные маги-отступники. Эти чародеи действуют вне закона Королевства Штормград и вне надзора признанных магических учреждений.",al={"who is at heroes vigil","heroes vigil enemies","wizards on lake","кто у часовых вечности","враги у часовых вечности","волшебники на озере"}},{q="Почему Штормград забросил Часовых Вечности?",a="Король Вариан Ринн пропал, а королевство перегружено борьбой с внутренними раздорами, разбойниками и нашествиями чудовищ, поэтому отдаленные святилища вроде Часовых Вечности остались без защиты и почти забыты правящим регентским советом.",al={"why is it abandoned","why did stormwind forget it","forgotten shrine","почему оно заброшено","почему штормград забыл о нем","забытое святилище"}},{q="Кто такой Хенз Фолк?",a="Хенз Фолк — погибший путник, чье бездыханное тело лежит возле памятника, печальное свидетельство беспощадной враждебности волшебников-отступников, занявших остров.",al={"henze faulk body","who is the dead guy on the island","тело хенза фолка","кто мертвец на острове"}}},fp="13,356,20.458.0,20.488.0,22.195.0,47.190.0,33.201.0,38.225.0,19.180.0"}
P.entries["subzone:hetaera-s-clutch"] = {n="Гнездо Хетайры",s="Гнездо Хетайры — затонувший храм ночных эльфов, посвященный Элуне, лежащий глубоко под бурными водами Залива Бурь в Азшаре. Некогда священное место поклонения, ныне затопленные руины кишат смертоносными гидрами, выведенными их матерью, Хетайрой. Искатели приключений, отважившиеся спуститься в глубины, найдут древнюю каменную кладку во власти свирепых морских хищников.",h="Гнездо Хетайры — затонувший храм ночных эльфов, посвященный Элуне, лежащий глубоко под бурными водами Залива...",kw={"azshara","bay of storms","elune","hetaera","hetaera's clutch","hetaeras clutch","hydra","sunken temple","temple of elune","азшара","залив бурь","элуна","хетайра","гнездо хетайры","гидра","затонувший храм","храм элуны"},ang={["class:Druid"]="Друидам, исследующим глубины Залива Бурь в водной форме, следует быть осторожными: гидры, завладевшие этим древним святилищем, крайне враждебны к незваным гостям.",["race:NightElf"]="Для ночных эльфов вид священного святилища Элуны, затопленного и оскверненного под гнездо диких гидр, — болезненное напоминание о цивилизации, разрушенной во время Раскола."},sec={{t="Затонувшее святилище",b="До Великого Раскола, разорвавшего древний Калимдор, это строение было величественным храмом, посвященным лунной богине Элуне. Низвергнутые в глубины Залива Бурь, его каменные колонны и священные залы десять тысяч лет провели под водой. Сегодня все следы благоговейного почитания поглотили приливы, оставив лишь суровый памятник утраченной империи кальдораев."},{t="Владения матери выводка",b="Затопленное святилище стало гораздо опаснее: теперь это место гнездования Хетайры, огромной многоголовой гидры, что рыщет в прибрежных водах и среди скалистых островков. Ее многочисленное потомство, Отродья Хетайры, бродит по разрушенным аркам и коридорам затонувшего храма и нападает на любого обитателя суши, осмелившегося нырнуть в залив."}},faq={{q="Для чего изначально построено Гнездо Хетайры?",a="Задолго до того как уйти под воду, это строение было великолепным храмом, посвященным лунной богине Элуне. Его построили на пике могущества древней империи ночных эльфов, а во время Великого Раскола оно было низвергнуто в океан.",al={"what is hetaeras clutch","what was this temple","hetaera clutch lore","что такое гнездо хетайры","что это был за храм","предания гнезда хетайры"}},{q="Где находится Гнездо Хетайры?",a="Гнездо лежит глубоко под водой в Заливе Бурь, у неровного южного побережья Азшары.",al={"where is hetaeras clutch","hetaera clutch location","how to find hetaera clutch","где гнездо хетайры","расположение гнезда хетайры","как найти гнездо хетайры"}},{q="Кто такая Хетайра?",a="Хетайра — свирепая трехглавая гидра, рыщущая в водах Азшары. Ее детеныши заполонили сам затонувший храм, а сама Хетайра обычно плавает чуть севернее Гнезда или греется на ближайших прибрежных островках.",al={"who is hetaera","where is hetaera","what is hetaera","кто такая хетайра","где хетайра","что такое хетайра"}},{q="Какие существа обитают в затопленных руинах?",a="Затонувшие залы кишат выводком Хетайры — свирепыми морскими гидрами, которые защищают свое гнездо от любых чужаков, подплывших слишком близко.",al={"what mobs are in hetaeras clutch","what lives in hetaera clutch","какие монстры в гнезде хетайры","кто живет в гнезде хетайры"}}},fp="16,357,19.389.0,25.356.0,47.240.0,34.108.0,15.238.0,43.152.0"}
P.entries["subzone:hidden-grove"] = {n="Сокрытая роща",s="Сокрытая роща — уединенная кратерная котловина, скрытая за высокими утесами на северо-востоке Зимних Ключей. Некогда мирное убежище арктических зайцев, ныне она перешла во владения свирепо охраняющих территорию диких лунных сов.",h="Сокрытая роща — уединенная кратерная котловина, скрытая за высокими утесами на северо-востоке Зимних Ключей.",kw={"crater","hares","hidden grove","moonkin","winterspring","кратер","зайцы","сокрытая роща","лунные совы","зимние ключи"},ang={["class:Druid"]="Лунные совы, гнездящиеся в кратере, — мрачное напоминание о дикой, необузданной природе, ставшей яростно обороняющейся, и они вызывают глубокий духовный интерес у последователей равновесия."},sec={{t="Уединенное убежище",b="Сокрытая роща, защищенная от пронизывающих воющих ветров Зимних Ключей, представляет собой провалившийся, припорошенный снегом лесной кратер, в который почти невозможно попасть со внешних утесов. Путники, нашедшие его скрытый край, должны отважиться на крутой опасный спуск или пройти по узкому пещерному ходу в юго-восточном хребте. Долина долго была нетронутым домом безобидных белых зайцев, но агрессивные дикие лунные совы заняли поляну и превратили уединенный природный рай в западню для неосторожных странников."}},faq={{q="Как попасть в Сокрытую рощу?",a="Самый безопасный путь в рощу — через скрытую пещеру в юго-восточной стене окружающих утесов. Теоретически можно спрыгнуть вниз по крутому краю утеса сверху, но это сопряжено с высоким риском смертельного падения.",al={"how to enter hidden grove","hidden grove entrance","where is the cave","как попасть в сокрытую рощу","вход в сокрытую рощу","где пещера"}},{q="Какие существа живут в Сокрытой роще?",a="Кратер заполонили дикие враждебные лунные совы, ревностно охраняющие уединенную долину. Пока они не поселились здесь, поляна славилась как мирное убежище, где жили почти одни безобидные белые зайцы.",al={"what is in hidden grove","hidden grove mobs","who lives here","что в сокрытой роще","монстры сокрытой рощи","кто здесь живет"}},{q="Где в Зимних Ключах находится эта роща?",a="Сокрытая роща лежит на крайнем северо-востоке Зимних Ключей, целиком в изолированной чаше высоких каменных утесов.",al={"hidden grove location","where is hidden grove","расположение сокрытой рощи","где сокрытая роща"}}},fp="12,228,20.519.0,37.262.0,40.222.0,44.136.0"}
P.entries["subzone:hidden-path"] = {n="Потайная тропа",kw={"barrens","durotar","hidden path","shaman","spirit rock","valley of trials","степи","дуротар","потайная тропа","шаман","священный камень","долина испытаний"},ang={["class:Shaman"]="Потайная тропа — ваше первое настоящее физическое и духовное восхождение, проверяющее вашу наблюдательность, прежде чем вы начнете общаться с духами земли у Священного Камня.",["faction:Horde"]="Хотя эта тропа священна для шаманов, этот неукрепленный проход — слепое пятно в безопасности над Долиной Испытаний, требующее бдительного присмотра."},sec={{t="Священное восхождение",b="Потайная тропа, вырубленная в красных пиках вокруг Долины Испытаний, намеренно трудна для обнаружения с земли каньона. Наставники направляют сюда молодых шаманов, чтобы те доказали свою наблюдательность и дисциплину, прежде чем общаться с духами у Священного Камня. На самых высоких участках тропы путникам открываются широкие панорамы на запад, к холмистым саваннам Степей."},{t="Стратегическая уязвимость",b="Помимо духовного значения, тропа опасно прорезает природные укрепления, окружающие долину. Низкий перевал на ее пути образует прямой черный ход к Кабестану и дороге на Оргриммар. Поскольку она обходит обычные каньонные заставы, бдительные защитники опасаются, что дерзкие лазутчики Альянса смогут воспользоваться этой тихой тропой и проникнуть прямо на главный учебный полигон Орды."}},faq={{q="Куда ведет Потайная тропа?",a="Тропа поднимается из Долины Испытаний в скалы к Священному Камню, священному месту, где шаманы общаются со стихиями. Она также вьется по горным перевалам, ведущим к Степям и побережью.",al={"hidden path destination","where does hidden path go","hidden path leads to","куда ведет потайная тропа","назначение потайной тропы","потайная тропа ведет"}},{q="Чем тропа важна для шаманов?",a="Начинающим шаманам в Долине Испытаний поручено найти эту уединенную тропу в рамках первых стихийных испытаний. Поднявшись по ней, они достигают Священного Камня и пьют сапту, необходимую для общения с духами.",al={"shaman path valley of trials","spirit rock path","shaman quest path","тропа шаманов долина испытаний","путь к священному камню","задание шамана тропа"}},{q="Могут ли враги использовать Потайную тропу для нападения на Долину Испытаний?",a="Да. Низкие проходы на тропе обходят обычные охраняемые входы в долину. Хитрый отряд Альянса, идущий из Кабестана или с побережья, теоретически мог бы пройти по тропе мимо разведчиков Орды и незамеченным проникнуть на учебную территорию.",al={"hidden path alliance invasion","is valley of trials vulnerable","valley of trials back door","вторжение альянса потайная тропа","уязвима ли долина испытаний","черный ход долины испытаний"}},{q="Что можно увидеть с вершины тропы?",a="В самой высокой точке тропа открывает ясный, возвышенный вид на запад, на обширные равнины Степей, а также широкий вид на красные каньоны Дуротара.",al={"hidden path view","lookout point hidden path","вид с потайной тропы","смотровая площадка потайная тропа"}}},fp="11,276,15.419.0,23.422.0,32.217.0,38.238.0,65.250.0,42.174.0"}
P.entries["subzone:high-rise"] = {n="Высокая вершина",s="Высокая вершина — верхний ярус центральной мезы Громового Утеса, венчающий столицу таурен. Здесь расположены оживленный амфитеатр с общим костром, опытные мастера, торговцы оружием и мастера кулинарии. В отличие от нижних ярусов, эта вершина сообщается с остальным городом только по подвесным веревочным мостам и через насест наездников на ветрокрылах.",h="Высокая вершина — верхний ярус центральной мезы Громового Утеса, венчающий столицу таурен.",kw={"amphitheater","aska's kitchen","bonfire","high rise","mulgore","thunder bluff","wind rider roost","амфитеатр","кухня аски","костер","высокая вершина","мулгор","громовой утес","насест наездников на ветрокрылах"},ang={["profession:Cooking"]="На Высокой вершине находятся Кухня Аски и известные мастера барбекю, поэтому это главное место в Громовом Утесе, где можно оттачивать кулинарное мастерство на открытом огне.",["race:Tauren"]="Высокая вершина — венец вашей столицы, воплощение единства племен: вокруг ее высокого общего костра собираются охотники, шаманы и старейшины."},sec={{t="Вершина мезы",b="Высокая вершина расположена на главном плато Громового Утеса, где открытые ветра гуляют высоко над холмистыми равнинами Мулгора. Это главное место сбора объединенных племен: в центре находятся открытый амфитеатр и очаг, где жители слушают важные объявления племени и судьбоносные решения. В окружающих шатрах и деревянных лавках работают известные торговцы, оружейники и учителя кулинарии, среди них Кухня Аски и Горная рыбалка. Нижние ярусы соединены с прерией Мулгора огромными деревянными подъемниками, а Высокая вершина остается в вышине: сюда можно попасть в основном через насест наездников на ветрокрылах и подвесные мосты, ведущие к соседним Вершине Старейшин и Вершине Охотников."}},faq={{q="Как добраться до Высокой вершины?",a="До Высокой вершины можно добраться через центральное гнездовье наездников на ветрокрылах с нижних ярусов или по подвесным мостам от Вершины Старейшин и Вершины Охотников. Прямого подъемника с равнин Мулгора на этот ярус нет.",al={"how to get to high rise","high rise access","getting up to high rise","как попасть на высокую вершину","доступ на высокую вершину","подъем на высокую вершину"}},{q="Какие услуги есть на Высокой вершине?",a="Этот ярус известен ремесленниками и местами для встреч под открытым небом. Среди заметных заведений — Кухня Аски, где учат готовке, Горная рыбалка со снастями и различные торговцы оружием, например Оружейная Горнего Гнева и Огнестрельное оружие Громового Копыта.",al={"trainers on high rise","shops high rise","what is on high rise","учителя на высокой вершине","магазины высокая вершина","что есть на высокой вершине"}},{q="Для чего используется амфитеатр на Высокой вершине?",a="Открытый амфитеатр окружает центральный костер и служит общим местом сбора. Здесь таурены собираются под открытым небом, чтобы услышать новости, обсудить дела племени и стать свидетелями важных объявлений на вершине мезы.",al={"high rise bonfire","high rise auditorium","tauren meeting place","костер высокой вершины","аудитория высокой вершины","место собраний таурен"}}},fp="9,350,18.713.0,31.224.0,41.258.0,51.248.0"}
P.entries["subzone:high-seat"] = {n="Высокий трон",s="Высокий трон — величественный тронный зал Стальгорна, расположенный между Общинным кварталом и Великой кузней. Из этого возвышенного зала король Магни Бронзобород правит королевством дворфов вместе со своими королевскими советниками и историками. В зале также находится запечатанный проход, ведущий вниз, в древние глубины Старого Стальгорна.",h="Высокий трон — величественный тронный зал Стальгорна, расположенный между Общинным кварталом и Великой кузней.",kw={"archesonus","barin redstone","bronzebeard","high seat","ironforge","magni","throne","аркессон","борин краснокамень","бронзобород","высокий трон","стальгорн","магни","трон"},ang={["faction:Alliance"]="Как резиденция власти дворфов, этот зал имеет решающее значение для снабжения и стратегии высшего уровня Альянса: в нем размещаются посланники, советники и королевские указы.",["race:Dwarf"]="Высокий трон олицетворяет непрерывную преемственность суверенитета Каз Модана, где король Магни Бронзобород по-прежнему ведет свой народ железной волей."},sec={{t="Сердце власти дворфов",b="Высокий трон, возвышающийся над шумными оживленными кольцами Стальгорна, служит королевской резиденцией власти королевства Каз Модан. В этом сводчатом зале король Магни Бронзобород принимает просителей, совещается с советниками и руководит обороной северных бастионов Альянса. По бокам от трона стоят королевские сановники, такие как Королевский историк Аркессон и Сенатор Борин Краснокамень. Высокий трон остается символом непреклонной власти Бронзобородов и стойкости дворфов в тревожные времена, охватившие Азерот."},{t="Врата в Старый Стальгорн",b="За величественным каменным убранством тронного зала находится тяжелая дверь, ведущая в сумрачные просторы Старого Стальгорна. Эти нижние руины — первоначальные, исконные залы, высеченные дворфами до того, как город перестроили вокруг Великой кузни. Охраняемый и закрытый для всеобщего прохода вход напоминает посетителям о глубокой древности и пещерной истории, покоящейся под камнями современной столицы."}},faq={{q="Кто правит с Высокого трона?",a="Король Магни Бронзобород правит Стальгорном с трона в Высоком троне. Он ведет дела клана Бронзобородов, выслушивает подданных и координирует военные и дипломатические вопросы с Великим Альянсом.",al={"who is on the throne","ironforge king","magni throne room","кто на троне","король стальгорна","тронный зал магни"}},{q="Где в Стальгорне находится Высокий трон?",a="Зал расположен в центре Стальгорна и напрямую соединен с внешним кольцом между Общинным кварталом и Великой кузней, что обеспечивает легкий доступ для горожан и посланников.",al={"where is high seat","find high seat","throne room location","где высокий трон","найти высокий трон","расположение тронного зала"}},{q="Что за запечатанный коридор в глубине тронного зала?",a="Большая арка в задней части Высокого трона ведет в Старый Стальгорн — пещерные древние руины, лежащие прямо под современным горным городом. Доступ в эти нижние проходы по-прежнему ограничен.",al={"door behind magni","old ironforge door","high seat basement","дверь за магни","дверь в старый стальгорн","подвал высокого трона"}},{q="Кого еще можно найти здесь среди советников короля?",a="Королю Магни прислуживают видные дворфы, в том числе Королевский историк Аркессон, хранящий записи и реликвии династии Бронзобородов, и Сенатор Борин Краснокамень.",al={"high seat npcs","magni advisors","персонажи высокого трона","советники магни"}}},fp="9,328,21.515.0,24.426.0,29.218.0,44.179.0,59.205.0,45.184.0"}
P.entries["subzone:high-wilderness"] = {n="Высокогорные дебри",s="Высокогорные дебри — обширный дикий участок первобытного леса, покрывающий большую часть западного Фераласа. Граничат с Рекой Вердантис на востоке и Забытым берегом на западе. Под высоким изумрудным пологом здесь обитают разнообразные животные, бродячие древни и опасные звери.",h="Высокогорные дебри — обширный дикий участок первобытного леса, покрывающий большую часть западного Фераласа.",kw={"feralas","forgotten coast","high wilderness","hippogryphs","treants","verdantis river","yetis","фералас","забытый берег","высокогорные дебри","гиппогрифы","древни","река вердантис","йети"},ang={["class:Druid"]="Вековые древни и яркая живность Высокогорных дебрей показывают природную первозданную мощь Калимдора, не тронутую цивилизацией восточных земель.",["class:Hunter"]="Густые популяции свирепых медведей, волков и диких гиппогрифов делают Высокогорные дебри превосходным местом для оттачивания навыков выслеживания и приручения грозных зверей."},sec={{t="Первобытный полог",b="Высокогорные дебри, раскинувшиеся по западной половине Фераласа, — образец дикой природы южного Калимдора. Густая листва и исполинские деревья закрывают большую часть неба, создавая пышные заросли, где кишат волки, медведи, гиппогрифы и йети. Вековые древни бродят среди корней, а агрессивные кланы огров закрепляются на тенистых полянах. Путешествие по этим зеленым просторам требует бдительности: густой кустарник скрывает и природных хищников, и сохранившиеся первобытные опасности."}},faq={{q="Где находятся Высокогорные дебри?",a="Высокогорные дебри охватывают обширные лесные земли западного Фераласа. Они лежат к западу от Реки Вердантис и тянутся до утесов и берегов у Забытого берега.",al={"high wilderness location","where is high wilderness","high wilderness feralas","расположение высокогорных дебрей","где высокогорные дебри","высокогорные дебри фералас"}},{q="Какие существа бродят в Высокогорных дебрях?",a="В лесу водится множество медведей, волков, гиппогрифов и диких йети. Помимо обычных зверей, путешественники регулярно встречают бродячих древней и агрессивных огров, скрывающихся под пологом леса.",al={"high wilderness wildlife","creatures in high wilderness","beasts feralas","животные высокогорных дебрей","существа в высокогорных дебрях","звери фералас"}}},fp="15,303,21.521.0,37.188.0,40.211.0"}
P.entries["subzone:highperch"] = {n="Скальное гнездовье",s="Скальное гнездовье — возвышенное плато в западной части Тысячи Игл, вздымающееся высоко над дном каньона. Оно известно как главное место гнездования диких виверн и всадников ветра. В гнездовье обитают свирепые стаи, защищающие своих детенышей среди продуваемых ветрами скал.",h="Скальное гнездовье — возвышенное плато в западной части Тысячи Игл, вздымающееся высоко над дном каньона.",ang={["class:Hunter"]="Обширное гнездовье дает опытным охотникам возможность вблизи увидеть, как дикие виверны охотятся и охраняют гнезда в естественной, нетронутой среде обитания.",["faction:Horde"]="Всадники ветра, гнездящиеся в Скальном гнездовье, — близкие родичи благородных летающих скакунов, переносящих Орду по Калимдору, поэтому это убежище внушает трепет героям Орды."},sec={{t="Гнездо виверн",b="Rising sharply out of the canyon floor, Highperch is a rugged sanctuary for Kalimdor's native wyverns. The plateau provides natural defense against predators and an unobstructed launch point for their hunting flights across Thousand Needles. Within its reaches, wyvern prides live under the protection of watchful patriarchs and matriarchs, guarding their nests. The beasts fiercely defend their territory against any intruders who manage to climb into their high domain."},{t="Убежище в вышине",b="While hostile to outsiders, the high cliffs occasionally attract travellers and hunters willing to brave the dangerous ascent. The tauren scout Pao'ka Swiftmountain is stranded on these perilous heights and needs help reaching Whitereach Post. For adventurers journeying through the canyon, scaling the ramp to Highperch means contending with dozens of razor-sharp talons and venomous tails."}},faq={{q="Какие существа живут в Скальном гнездовье?",a="Highperch is inhabited exclusively by wild wyverns and wind riders. You will encounter protective patriarchs, consorts, soaring adults defending their clifftop nests.",al={"highperch beasts","what is at highperch","highperch mobs","звери скального гнездовья","что в скальном гнездовье","монстры скального гнездовья"}},{q="Где находится Скальное гнездовье?",a="Скальное гнездовье расположено в западной части Тысячи Игл. Подняться к нему можно по извилистой тропе от южной стены дна каньона.",al={"highperch location","how to find highperch","where is highperch","расположение скального гнездовья","как найти скальное гнездовье","где скальное гнездовье"}},{q="Чем Скальное гнездовье важно для Орды?",a="Виверны, они же всадники ветра, — важные летающие скакуны Орды: они стали союзниками орков во время Третьей войны. Естественные гнездовья вроде Скального гнездовья олицетворяют дикое наследие и процветающую популяцию этих верных зверей.",al={"horde connection to highperch","wyverns and horde","why do orcs care about highperch","связь орды со скальным гнездовьем","виверны и орда","почему оркам важно скальное гнездовье"}},{q="Кто такой Паока Ходячая Гора?",a="Pao'ka Swiftmountain is a tauren scout stranded amidst the deadly wyvern nests on Highperch. He needs an escort to Whitereach Post.",al={"paoka swiftmountain","tauren at highperch","who got trapped at highperch","паока ходячая гора","таурен в скальном гнездовье","кто застрял в скальном гнездовье"}}},fp="9,260,20.471.0,23.391.0,33.166.0,27.138.0,42.232.0,28.131.0"}
P.entries["subzone:hillsbrad-fields"] = {n="Хилсбрадские поля",s="Хилсбрадские поля охватывают возделанные фермерские земли и простое поселение Хилсбрад в западной части Предгорий Хилсбрада. Это одна из немногих уцелевших человеческих общин в бывшем Лордероне, отказавшихся покориться Плети или присоединиться к фанатичному Алому ордену. Теперь ее фермеры и ополчение постоянно подвергаются нападениям соседних Отрекшихся из Мельницы Таррен.",h="Хилсбрадские поля охватывают возделанные фермерские земли и простое поселение Хилсбрад в западной части...",kw={"battle of hillsbrad","darthalia","farmer getz","farmer ray","hillsbrad","hillsbrad fields","magistrate burnside","southshore","tarren mill","verringtan","битва за хилсбрад","дарталия","фермер гетц","фермер рэй","хилсбрад","хилсбрадские поля","мировой судья бернсайд","южнобережье","мельница таррен","верринган"},ang={["faction:Alliance"]="Хилсбрадские поля — важная житница и яркий символ неугасающего духа Лордерона, заслуживающий защиты от истребления Отрекшимися.",["faction:Horde"]="Верховный палач Дарталия требует систематически уничтожать фермы и ополчение Хилсбрада, чтобы обезопасить южную границу для Отрекшихся."},sec={{t="Непокорный оплот Лордерона",b="Хилсбрадские поля, раскинувшиеся среди садов, тыквенных грядок и пастбищ между Холмом Дарроу и Лазуритовым рудником, поставляют необходимые припасы в Южнобережье и уцелевшему сопротивлению Альянса. Хотя большая часть Лордерона пала от чумы нежити, жители Хилсбрада выстояли и с гордостью сохранили королевский табард и геральдику павшего королевства. Городком, находящимся в постоянной осаде, управляет независимый гражданский орган во главе с мировым судьей Бернсайдом и Советом Хилсбрада. Местный кузнец Верринган и его подмастерья вооружают жителей, чтобы каждый фермер и работник был готов защищать свою землю."},{t="Передовая наступления нежити",b="Плодородные поля — главная цель Верховного палача Дарталии и сил Отрекшихся, закрепившихся в Мельнице Таррен. Видя в процветающем человеческом поселении смертельную угрозу на своем южном фланге, Подгород организовал непрерывные набеги на инфраструктуру общины, нацеленные на посевы, скот, советников и мирных фермеров. В ответ защитники Хилсбрада сформировали закаленное ополчение. Местные землевладельцы, такие как фермер Рэй и фермер Гетц, — далеко не беспомощные крестьяне: они устраивают засады и яростно сражаются с вторжениями нежити, защищая свои дома."}},faq={{q="Почему здесь еще работают живые люди?",a="Хилсбрад и соседнее Южнобережье — одни из очень немногих поселений Лордерона, которые избежали полного уничтожения Плетью во время Третьей войны. В отличие от других выживших, бежавших на юг или присоединившихся к фанатичному Алому ордену, эти жители остались, чтобы заново построить свою жизнь и сохранить родную землю.",al={"why are humans in hillsbrad","who lives in hillsbrad fields","are the farmers alive","почему люди в хилсбраде","кто живет на хилсбрадских полях","живы ли фермеры"}},{q="Кто правит городом и полями?",a="Городом и фермерскими землями управляет мировой судья Бернсайд, которому помогают клерк Гораций Белоконь и Совет Хилсбрада из местной ратуши. Окрестными усадьбами управляют землевладельцы, такие как фермер Рэй и фермер Гетц, а местный кузнец Верринган снаряжает городскую стражу.",al={"who leads hillsbrad","hillsbrad leadership","magistrate of hillsbrad","кто правит хилсбрадом","руководство хилсбрада","магистрат хилсбрада"}},{q="Почему Отрекшиеся нападают на фермы?",a="Верховный палач Дарталия из Мельницы Таррен считает Хилсбрад опасным оплотом Альянса на границе Отрекшихся. Приказы Подгорода велят солдатам разорвать линии снабжения людей: уничтожать запасы еды, убивать скот и устранять городских лидеров, чтобы расчистить путь к господству Отрекшихся в предгорьях.",al={"why forsaken attack hillsbrad","battle of hillsbrad reason","tarren mill attacks","почему отрекшиеся нападают на хилсбрад","причина битвы за хилсбрад","нападения мельницы таррен"}},{q="Что случилось с Хилсбрадом во время Второй войны?",a="Во время Второй войны вождь Оргрим Молот Рока приказал нанести по Хилсбраду сокрушительный удар, чтобы сломить моральный дух людей и одновременно собрать силы Орды в районе Южнобережья. Хилсбрад был разрушен в жестокой демонстрации силы, но Альянс изгнал орков, и город впоследствии отстроили заново.",al={"hillsbrad second war","orcs destroyed hillsbrad","history of hillsbrad fields","хилсбрад вторая война","орки разрушили хилсбрад","история хилсбрадских полей"}}},fp="16,358,30.630.0,32.592.0,47.312.0,35.283.0,41.315.0,49.299.0"}
P.entries["subzone:hive-ashi"] = {n="Улей Аши",s="Улей Аши — обширная колония силитидов, господствующая над северными песками Силитуса. Это один из трех крупных гнезд насекомых в регионе: его извилистые туннели и высокие холмы кишат бесчисленными враждебными рабочими, защитниками и жалоносцами.",h="Улей Аши — обширная колония силитидов, господствующая над северными песками Силитуса.",kw={"cenarion","hive ashi","hive'ashi","silithid","silithus","swarming pillar","кенарий","улей аши","силитид","силитиды","силитус","роящаяся вершина"},ang={["class:Druid"]="Пока Круг Кенария следит за оскверненными песками Силитуса, друидам поручено изучать и подавлять насекомую угрозу, исходящую из Улья Аши, пока она не поглотила природную экосистему.",["faction:Alliance"]="Агенты Альянса, действующие в Силитусе, помогают собирать сведения об Улье Аши, чтобы эти агрессивные рои не угрожали соседним землям на юге Калимдора."},sec={{t="Северный холм",b="Улей Аши, расположенный на севере Силитуса, служит главным ульевым комплексом для вновь возрождающихся роев силитидов. Его хитиновые шпили очерчивают особую территорию среди дюн, отправляя рабочих-собирателей и ядовитых защитников на юг и восток, к Роящейся вершине. Всякий, кто пытается постичь странный, согласованный разум, пробуждающийся в пустынных пустошах, неизбежно приходит прямо в опасные гудящие туннели под этими холмами."},{t="Раскрытая угроза",b="Разведчики Круга Кенария, расквартированные по всему Силитусу, пристально следят за Ульем Аши: они нанимают отважных бойцов, чтобы проредить его ряды и добыть донесения разведки из глубин колонии. Глифы и согласованное поведение, описанные в Аши, говорят о том, что эти с виду безмозглые насекомые обладают жуткой единой волей. По мере роста их числа улей грозит выплеснуться за пределы северного Силитуса, поэтому уничтожение его потомства — первоочередная задача для тех, кто охраняет южные границы."}},faq={{q="Что такое Улей Аши?",a="Улей Аши — действующий ульевой комплекс силитидов на севере Силитуса. Здесь обитают тысячи роющих насекомоподобных существ, которые превращают пески пустыни в сеть туннелей и холмов.",al={"ashi hive","hive ashi location","what is ashi","улей аши","где улей аши","что такое аши"}},{q="Какие силитиды живут в Улье Аши?",a="Колонию населяют специализированные касты силитидов, в том числе рабочие Улья Аши, песчаные охотники, ядовитые жалоносцы и тяжело бронированные защитники.",al={"ashi mobs","hive ashi creatures","what silithid are here","монстры аши","существа улья аши","какие силитиды здесь"}},{q="Как Улей Аши связан с Роящейся вершиной?",a="Силитиды, роящиеся вокруг соседней Роящейся вершины, происходят из Улья Аши: это продвижение потомства улья вовне, через пустынную равнину.",al={"swarming pillar connection","ashi and swarming pillar","связь с роящейся вершиной","аши и роящаяся вершина"}},{q="Почему разведчики Кенария изучают этот улей?",a="Круг Кенария стремится понять стремительное возрождение силитидов и то, как согласуются их ульи. Разведчики наблюдают за Аши, чтобы расшифровать странные глифы и отследить, как быстро растет улей.",al={"why scout hive ashi","hive ashi scout report","зачем разведывать улей аши","отчет разведки улья аши"}}},fp="9,240,18.472.0,18.495.0,18.204.0,41.151.0,49.155.0,43.200.0"}
P.entries["subzone:hive-regal"] = {n="Улей Регал",s="Улей Регал — огромный улей силитидов, вырытый на юге Силитуса. Это одна из трех главных колоний насекомых, господствующих в засушливых пустошах, и она кишит агрессивными кастами силитидов, грозящими захлестнуть окрестную пустыню.",h="Улей Регал — огромный улей силитидов, вырытый на юге Силитуса.",kw={"burrowers","hive","hive'regal","regal","silithid","silithus","slavemakers","spitfires","землекопы","улей","улей регал","регал","силитид","силитиды","силитус","рабовладельцы","огнеплевы"},ang={["class:Druid"]="Круг Кенария пристально следит за распространением Улья Регал, видя во вторжении скверны силитидов губительную заразу для пустынной экосистемы."},sec={{t="Южный улей",b="Улей Регал, раскинувшийся по югу Силитуса, — одно из крупнейших скоплений силитидов в Калимдоре. Его высокие смоляные шпили и просторные подземные туннели кишат опасными выводками насекомых: от ядовитых огнеплевов и землекопов до хищных рабовладельцев. Улей действует как единое гнездо: яростно защищает свои границы и собирает органический материал у несчастных путников, подошедших слишком близко."},{t="Подземная сеть",b="Под красными песками лабиринтные ходы Улья Регал уходят глубоко в землю. Странные глифы, выбитые у входа и глубоко в туннелях, говорят о том, что роем управляет организованный разум, а не просто дикий инстинкт. Ученые и разведчики, изучающие угрозу силитидов, полагают, что Улей Регал вместе с родственными ульями входит в состав более крупной возникающей силы, пробуждающейся под пустошами Силитуса."}},faq={{q="Где находится Улей Регал?",a="Улей Регал находится в южной части Силитуса; его отличают высокие холмы насекомых и зараженные красные пески.",al={"hive regal location","where is hive regal","find hive regal","улей регал где","где улей регал","найти улей регал"}},{q="Какие существа живут в Улье Регал?",a="Гнездо населяют различные враждебные породы силитидов, в том числе землекопы, засадники, огнеплевы и рабовладельцы, яростно защищающие улей.",al={"hive regal mobs","what is inside hive regal","hive regal enemies","монстры улья регал","что внутри улья регал","враги улья регал"}},{q="Почему исследователей интересует Улей Регал?",a="Разведчики и ученые изучают улей, чтобы расшифровать странные глифы для общения на его стенах и следить за растущей угрозой роя силитидов на юге Калимдора.",al={"why go to hive regal","hive regal research","hive regal glyphs","зачем идти в улей регал","исследования улья регал","глифы улья регал"}},{q="Чем Улей Регал отличается от других ульев Силитуса?",a="Улей Регал — самая южная из трех крупных колоний Силитуса, наряду с Ульем Аши и Ульем Зора. В каждой колонии обитают свои специализированные касты силитидов, хотя все они, похоже, разделяют единую коварную цель.",al={"other hives silithus","three hives","difference between hives","другие ульи силитуса","три улья","различия ульев"}}},fp="10,250,17.465.0,20.428.0,28.126.0,43.151.0,45.176.0,60.214.0"}
P.entries["subzone:hive-zora"] = {n="Улей Зора",s="Улей Зора — один из трех крупных холмов-колоний силитидов, господствующих над засушливыми просторами Силитуса. Этот кишащий подземный улей расположен на западной окраине пустыни, и в нем обитают агрессивные касты насекомых, служащие великому рою.",h="Улей Зора — один из трех крупных холмов-колоний силитидов, господствующих над засушливыми просторами Силитуса.",kw={"cenarion circle","hive sisters","hive zora","hive'zora","reavers","silithid","silithus","waywatchers","круг кенария","сестры улья","улей зора","разорители","силитид","силитиды","силитус","сторожа троп"},ang={["class:Druid"]="Для друидов Круга Кенария Улей Зора — страшный неестественный всплеск, нарушающий природное равновесие пустынных земель.",["profession:Mining"]="В извилистых туннелях и на окраинах колоний силитидов, таких как Улей Зора, часто встречаются богатые залежи тория и редкие месторождения минералов, покрытые слизью."},sec={{t="Западный рой",b="Улей Зора, поднимающийся из бесплодных песчаных дюн западного Силитуса, — оживленный центр активности насекомых. Огромные пористые каменные шпили и холмы отмечают входы в глубокие подземные туннели, прорытые землекопами-силитидами. Сторожа троп и разорители неустанно патрулируют периметр, а копающие касты и сестры улья роятся в глубинах. Для Круга Кенария и других разведчиков, наблюдающих за пустыней, улей — страшный знак того, что насекомая угроза неуклонно отвоевывает древние рубежи."}},faq={{q="Что такое Улей Зора?",a="Улей Зора — действующий ульевой комплекс силитидов на западе Силитуса. Он состоит из огромных шпилей насекомых на поверхности, соединенных с обширными подземными туннелями.",al={"zora hive","what is hive zora","hive zora silithus","улей зора","что такое улей зора","улей зора силитус"}},{q="Какие существа живут в Улье Зора?",a="Улей целиком занят роем силитидов. Холм населяют разные касты: сторожа троп Улья Зора патрулируют снаружи, тяжелые разорители защищают землю, туннельщики роют землю, а рядом обитают ядовитые сестры улья.",al={"hive zora mobs","what monsters are in hive zora","who lives in hive zora","монстры улья зора","какие монстры в улье зора","кто живет в улье зора"}},{q="Почему Круг Кенария исследует этот улей?",a="Разведчики и исследователи, расквартированные в Силитусе, наблюдают за Ульем Зора, чтобы отслеживать рост и перемещения угрозы силитидов. Посланники изучают их поведение, расшифровывают глифы и сокращают их растущую численность, пока рой не захлестнул регион.",al={"why scout hive zora","cenarion circle hive zora","зачем разведывать улей зора","круг кенария улей зора"}},{q="Чем Улей Зора отличается от других ульев Силитуса?",a="Улей Зора — самый западный из трех великих ульев: Улей Аши удерживает север, а Улей Регал господствует на юге. У каждого улья свой особый выводок, но всех объединяет хищное стремление расширяться по пустыне.",al={"other hives silithus","difference between hives","hive regal hive ashi","другие ульи силитуса","различия ульев","улей регал улей аши"}}},fp="9,243,17.539.0,18.174.0,33.238.0,51.254.0,59.245.0"}
P.entries["subzone:horizon-scout"] = {n="Разведчик горизонта",s="«Разведчик горизонта» — затонувшее судно, лежащее на дне океана в Опустошенном береге у южного побережья Азшары. Пока капитан остается на берегу, несколько членов команды заперты в затопленном корпусе и живы под водой благодаря чарам подводного дыхания.",h="«Разведчик горизонта» — затонувшее судно, лежащее на дне океана в Опустошенном береге у южного побережья...",kw={"azshara shipwreck","azsharite","horizon scout","roland geardabbler","ruined reaches","spitelash","vanessa beltis","кораблекрушение азшара","азшарит","разведчик горизонта","роланд шестеренкин","опустошенный берег","янтарный бич","ванесса белтис"},ang={["faction:Alliance"]="«Разведчик горизонта» — это неудачная морская затея, лояльная Альянсу, в опасных водах Азшары: команда оказалась разделена между берегом и водяной могилой.",["race:Gnome"]="Вся уцелевшая команда обязана дыханием Роланду Шестеренкину, чье неустанное колдовство сдерживает океанские глубины внутри затопленного корпуса."},sec={{t="В ловушке на дне океана",b="Лежа под волнами среди коварных мелей Опустошенного берега, «Разведчик горизонта» нашел жестокий конец у изрезанного берега Азшары. Капитан Ванесса Белтис сумела добраться до суши на соседнем полуострове, а часть команды пошла ко дну вместе с корпусом. Чудом выжившие внутри не утонули: гном по имени Роланд Шестеренкин поддерживает магический пузырь подводного дыхания, который хранит их в обломках. Окруженные враждебными морскими хищниками и кровожадными нага, оставшиеся матросы ждут в темных носовых отсеках, не в силах всплыть сами."},{t="Засада нага",b="Свидетельства на борту намекают на зловещие силы, погубившие корабль. На носовой лестнице лежит небольшой осколок сырого азшарита — загадочного минерала, встречающегося только на этих берегах. Нага из племени Янтарного Бича, рыскающие в водах Опустошенного берега, вероятно, напали на «Разведчика горизонта», чтобы разграбить артефакты или ресурсы экспедиции, и утопили судно, чтобы никто не ушел с секретами или сокровищами побережья."}},faq={{q="Где находится «Разведчик горизонта»?",a="Обломки «Разведчика горизонта» лежат под водой на дне залива в Опустошенном береге, у южного побережья Азшары.",al={"horizon scout location","where is horizon scout","find horizon scout","разведчик горизонта где","где разведчик горизонта","найти разведчика горизонта"}},{q="Как команда еще жива под водой?",a="Гном-инженер или маг по имени Роланд Шестеренкин непрерывно поддерживает ауру подводного дыхания внутри затонувшего корпуса, сохраняя жизнь запертым членам команды в устойчивом пузыре пригодного для дыхания воздуха.",al={"how are they breathing","why crew not dead","roland geardabbler aura","как они дышат","почему команда жива","аура роланда шестеренкина"}},{q="Кто такая капитан Ванесса Белтис?",a="Капитан Ванесса Белтис — командир «Разведчика горизонта». В отличие от матросов, запертых в корпусе, она сумела добраться до безопасного южного полуострова Азшары вместе с несколькими уцелевшими.",al={"vanessa beltis","horizon scout captain","ship captain","ванесса белтис","капитан разведчика горизонта","капитан корабля"}},{q="Что потопило «Разведчика горизонта»?",a="Корабль почти наверняка попал в засаду местных нага из племени Янтарного Бича и был потоплен. Кусок сырого азшарита на нижней палубе говорит о том, что нага напали, чтобы завладеть минеральными богатствами или артефактами, собранными экспедицией.",al={"why did horizon scout sink","who sank horizon scout","what happened to the ship","почему затонул разведчик горизонта","кто потопил разведчика горизонта","что случилось с кораблем"}}},fp="13,293,26.598.0,15.449.0,35.136.0,39.204.0,30.201.0,38.229.0"}
P.entries["subzone:hunter-rise"] = {n="Вершина Охотников",s="Вершина Охотников — одно из возвышенных плато, составляющих город Громовой Утес, к югу от центрального утеса. Это главное место обучения и сбора воинов, охотников, следопытов и снимающих шкуры таурен. На ее продуваемых ветрами площадках молодые воины оттачивают боевые навыки и готовятся к сражениям.",h="Вершина Охотников — одно из возвышенных плато, составляющих город Громовой Утес, к югу от центрального утеса.",kw={"battlemasters","hunter rise","hunter's hall","mulgore","thunder bluff","trackers","военачальники","вершина охотников","зал охотников","мулгор","громовой утес","следопыты"},ang={["class:Hunter"]="Для молодых таурен-охотников эта вершина — естественное сердце вашего призвания в столице: здесь есть обучение, припасы для питомцев и наставления мастеров-следопытов.",["class:Warrior"]="На Вершине Охотников вы найдете тренировочные манекены, боевых наставников и военачальников, готовых испытать вашу силу в непрерывной обороне Орды."},sec={{t="Собрание воинов",b="Вершина Охотников соединена с соседними утесами качающимися веревочными мостами и посвящена боевым традициям таурен. Ее центр — Зал Охотников, где опытные стрелки, следопыты и воины передают свое мастерство молодым поколениям. Вокруг зала расположены тренировочные площадки с манекенами, стойками для оружия и столбами для снятия шкур, и это оживленное место для тех, кто живет копьем, луком и шкурой."},{t="Воинский долг и оборона",b="Помимо охоты на дичь в равнинах Мулгора, жители Вершины Охотников помогают защищать Громовой Утес и всю Орду. Начальники боевых кличей, размещенные на вершине, набирают опытных бойцов для стычек с вторжениями Альянса на спорных полях боя. Это по-прежнему важное место сбора для каждого, кто поклялся защищать стадо."}},faq={{q="Где находится Вершина Охотников?",a="Вершина Охотников находится на южной стороне Громового Утеса. До нее можно добраться по деревянным веревочным мостам, соединяющим ее с плато Нижней и Верхней вершин города.",al={"where is hunter rise","hunter rise location","how to get to hunter rise","где вершина охотников","расположение вершины охотников","как добраться до вершины охотников"}},{q="Кто живет и тренируется на Вершине Охотников?",a="На плато живут таурены-охотники, воины, следопыты, звероловы и кожевники. Помимо учителей классов и профессий, здесь стоят военачальники Орды и набирают бойцов для войн фракции.",al={"who is on hunter rise","hunter rise trainers","what is on hunter rise","кто на вершине охотников","учителя вершины охотников","что есть на вершине охотников"}},{q="Что такое Зал Охотников?",a="Зал Охотников — главный длинный дом на вершине, где собираются опытные охотники и воины. Он служит оружейной, школой и очагом для тех, кто учится выслеживанию, меткой стрельбе и ближнему бою.",al={"hunters hall","hunters lodge thunder bluff","thunder bluff hunter hall","зал охотников","дом охотников громовой утес","зал охотников громового утеса"}},{q="Могут ли представители Альянса посетить Вершину Охотников?",a="Нет. Громовой Утес — крупная столица Орды, а Вершину Охотников охраняют опытные воины-таурены. Любого искателя приключений из Альянса, попытавшегося пересечь ее мосты, немедленно атакует городская стража.",al={"alliance on hunter rise","can alliance go to hunter rise","альянс на вершине охотников","может ли альянс попасть на вершину охотников"}}},fp="11,329,23.447.0,24.382.0,29.178.0,36.217.0,26.218.0,46.203.0"}
P.entries["subzone:hushed-bank"] = {n="Затихший берег",s="Затихший берег — сумрачное западное побережье Сумеречного леса вдоль реки, отделяющей лес от Западного Края. Он тянется от развилки у Трех Углов на юг к Тернистой долине — тихий, но опасный лес, где рыщут хищные звери и таятся мрачные тайны.",h="Затихший берег — сумрачное западное побережье Сумеречного леса вдоль реки, отделяющей лес от Западного Края.",kw={"covered bridge","duskwood","hushed bank","lars","riverbank","sven yorgen","westfall","крытый мост","сумеречный лес","затихший берег","ларс","берег реки","свен йорген","западный край"},ang={["class:Hunter"]="Волки и пауки, населяющие густую листву вдоль берега реки, — классические дикие звери для следопытов, исследующих мрачные уголки леса.",["faction:Alliance"]="Крытый мост у берега служит важным стратегическим проходом, соединяющим фермерские земли Западного Края с осажденным форпостом в Сумеречном лесу."},sec={{t="Рубеж вдоль реки",b="Затихший берег тянется вдоль реки между Сумеречным лесом и Западным Краем и отмечает переход от открытых равнин и залитых солнцем ферм к всепроникающим неестественным сумеркам. Здесь реку пересекает деревянный крытый мост, по которому путники покидают мрачный лес на запад. Берега реки заросли густым подлеском и затянуты стелющимся туманом, а огромные пауки и голодные лесные волки подстерегают неосторожных странников, сошедших с тропы."},{t="Изгои и отшельники",b="В северной части берега одинокие души устроили себе скудную жизнь вдали от подозрительных глаз Темнолесья. Свен Йорген и его спутник Ларс разбили лагерь в этих густых лесах, наблюдая за опушкой и храня горькую обиду из-за мрачных трагедий, постигших край. Их уединенное убежище — один из немногих признаков присутствия живых гуманоидов на этом безлюдном берегу."}},faq={{q="Где находится Затихший берег?",a="Затихший берег образует западный край Сумеречного леса вдоль реки, отделяющей лес от Западного Края. Он тянется от развилки у Трех Углов на севере к южным границам, ведущим в Тернистую долину.",al={"hushed bank location","where is hushed bank","hushed bank map","расположение затихшего берега","где затихший берег","карта затихшего берега"}},{q="Что соединяет Затихший берег с Западным Краем?",a="Деревянный крытый мост пересекает реку у Затихшего берега и позволяет пешим путникам и повозкам безопасно переправляться между солнечными равнинами Западного Края и проклятым мраком Сумеречного леса.",al={"bridge to westfall","westfall bridge duskwood","how to cross river to westfall","мост в западный край","мост западный край сумеречный лес","как перейти реку в западный край"}},{q="Кто живет вдоль Затихшего берега?",a="Свен Йорген и его помощник Ларс устроили лагерь в северном углу берега. Оба живут как уединенные отшельники, бежав от ужасов, погубивших ферму Свена неподалеку.",al={"camp on hushed bank","who is at hushed bank","npcs hushed bank","лагерь на затихшем береге","кто на затихшем береге","персонажи затихшего берега"}},{q="Какие угрозы встречаются вдоль этого побережья?",a="На Затихшем берегу обитают свирепые лесные звери, включая гигантских лесных пауков и хищных сумеречных волков, нападающих на все, что движется в зарослях.",al={"hushed bank mobs","dangers of hushed bank","hushed bank monsters","монстры затихшего берега","опасности затихшего берега","существа затихшего берега"}}},fp="11,301,26.442.0,20.405.1,33.232.0,42.177.0,32.190.0,44.166.0"}
P.entries["subzone:ice-thistle-hills"] = {n="Холмы Ледополоха",s="Холмы Ледополоха — заснеженное нагорье к юго-востоку от гоблинского поселения Круговзор. В этой местности, где преобладает суровая система пещер, хозяйничают свирепые йети Ледополоха, угрожающие всем путникам, свернувшим с главной дороги.",h="Холмы Ледополоха — заснеженное нагорье к юго-востоку от гоблинского поселения Круговзор.",kw={"everlook","ice thistle hills","ice thistle yetis","icecaps","pristine yeti horn","thick yeti fur","winterspring","yeti cave","круговзор","холмы ледополоха","йети ледополоха","ледяной шип","чистый рог йети","густой мех йети","зимние ключи","пещера йети"},ang={["profession:Herbalism"]="Морозные склоны вокруг холмов — отличное место для сбора холодолюбивых растений вроде ледяного шипа; редкие цветы порой встречаются у входа в пещеру.",["profession:Mining"]="Темная пещера в холме — опасное, но выгодное место для опытных горняков, ищущих богатые жилы тория под охраной стай йети."},sec={{t="Логово белого меха",b="Холмы Ледополоха круто поднимаются над центральными сугробами Зимних Ключей и служат основными охотничьими угодьями и местом гнездования агрессивных ледополохских йети этой долины. В центре холмов находится заметная пещера, глубоко вырытая в скале, и эти громадные звери бродят как по каменистым склонам, так и по извилистым туннелям внутри. Из-за близости к Круговзору йети постоянно досаждают гоблинским торговцам и приезжим старателям и угрожают им. Те регулярно нанимают отважных охотников, чтобы истреблять зверей ради ценных плотных шкур и чистых рогов."}},faq={{q="Где находятся Холмы Ледополоха?",a="Холмы Ледополоха находятся прямо к юго-востоку от гоблинского торгового поста Круговзор в центре Зимних Ключей.",al={"ice thistle hills location","where is ice thistle hills","yeti cave location","расположение холмов ледополоха","где холмы ледополоха","пещера йети"}},{q="Какие существа здесь обитают?",a="Склоны и пещера в холмах населены почти исключительно йети Ледополоха — чудовищными белошерстными громилами, яростно защищающими свою территорию.",al={"ice thistle monsters","what is in ice thistle hills","yeti types","монстры ледополоха","что есть в холмах ледополоха","виды йети"}},{q="Почему искатели приключений охотятся на Холмах Ледополоха?",a="Путники и торговцы из Круговзора часто нанимают искателей приключений, чтобы те добывали густой мех и чистые рога йети Ледополоха, которые ценятся при изготовлении снаряжения для выживания в холодной долине.",al={"why kill yetis","yeti fur winterspring","ice thistle quest","зачем убивать йети","мех йети зимние ключи","задание ледополох"}},{q="Какие ресурсы можно собирать вокруг холмов?",a="На открытых склонах растут редкие горные травы, например ледяной шип, а в глубине пещеры йети скрыты богатые залежи минералов, включая жилы тория.",al={"herbs ice thistle","mining ice thistle cave","травы ледополох","добыча руды пещера ледополоха"}}},fp="17,255,18.572.0,40.116.0,25.157.0,49.211.0,48.164.0"}
P.entries["subzone:infectis-scar"] = {n="Чумной овраг",s="Чумной овраг — глубокая неестественная расселина в оскверненной земле Восточных Чумных земель возле Перекрестка Корина. В отличие от природных оврагов, эта рана в земле была разорвана некромантической силой, когда проклятый рунический клинок разбился о дворфийский щит. Скверна, гниющая на дне разлома, остается вечным свидетельством темного колдовства Плети.",h="Чумной овраг — глубокая неестественная расселина в оскверненной земле Восточных Чумных земель возле...",kw={"chasm","corin's crossing","darrowshire","infectis scar","marduk blackpool","pestilent scar","runesword","пропасть","перекресток корина","дарроушир","чумной овраг","мардук блэкпул","моровой овраг","рунный меч"},ang={["class:Paladin"]="Пропасть источает оскверняющие остатки некромантического колдовства и показывает, насколько глубоко проклятые руны могут осквернить землю, отделившись от владельца.",["race:Dwarf"]="Овраг стоит как памятник стойкости дворфов: он возник лишь потому, что щит безымянного дворфийского капитана выстоял против темного рунного клинка рыцаря смерти и сокрушил проклятую сталь."},sec={{t="Рана темной магии",b="Хотя соседние ущелья, такие как Моровой овраг, возникли как природные участки местности, отравленные чумой, Чумной овраг целиком искусственный. Он возник во время ожесточенных схваток Третьей войны возле Перекрестка Корина. Когда пресловутый рыцарь смерти Мардук Блэкпул столкнулся со стойким дворфийским капитаном, проклятый рунный меч Мардука разбился о щит капитана. Отбросив сломанное оружие, Мардук оставил себе рукоять, но отколотый клинок глубоко ушел в землю. Его мерзкие чары яростно разорвали земную кору и создали зазубренную пропасть, которая и сегодня гниет в Чумных землях."}},faq={{q="Как образовался Чумной овраг?",a="Он возник во время битвы возле Перекрестка Корина, когда рунный меч рыцаря смерти Мардука Блэкпула сломался о щит дворфийского капитана. Когда расколотый клинок ударился о землю, его темная магия глубоко проникла в недра и разорвала огромную расселину.",al={"infectis scar origin","how did infectis scar happen","who made the infectis scar","происхождение чумного оврага","как возник чумной овраг","кто создал чумной овраг"}},{q="Чем он отличается от Морового оврага?",a="Моровой овраг изначально был природным ущельем, оскверненным чумой Плети. Чумной овраг не существовал в природе: он целиком возник от злобного колдовства, просочившегося из сломанного рунного клинка Мардука Блэкпула.",al={"difference between infectis and pestilent scar","pestilent scar comparison","разница между чумным и моровым оврагом","сравнение морового оврага"}},{q="Кто такой Мардук Блэкпул?",a="Мардук Блэкпул, известный как Черный, был рыцарем смерти на службе Плети и участвовал в бойне по всему Лордерону, включая нападение на Дарроушир и стычки возле Перекрестка Корина.",al={"marduk blackpool","who is marduk","мардук блэкпул","кто такой мардук"}},{q="Где сейчас меч?",a="Клинок разбитого рунного меча глубоко ушел в дно созданной им пропасти, а Мардук Блэкпул после схватки оставил себе лишь рукоять.",al={"runeblade location","where is the blade","местонахождение рунного клинка","где клинок"}}},fp="13,383,21.624.0,33.262.0,44.251.0,25.211.0,23.155.0"}
P.entries["subzone:iris-lake"] = {n="Озеро Ирис",s="Озеро Ирис — оскверненный водоем на севере центральной части Ясеневого леса, к востоку от Астранаара. Когда-то чистые воды озера стали болезненно желтовато-зелеными из-за демонической порчи, просачивающейся из Оскверненного леса, а по его берегам теперь бродят враждебные болотные твари.",h="Озеро Ирис — оскверненный водоем на севере центральной части Ясеневого леса, к востоку от Астранаара.",kw={"ashenvale","bog beasts","elune's tear","felwood corruption","iris lake","shael'dryn","ясеневый лес","болотные твари","слеза элуны","порча оскверненного леса","озеро ирис","шаэл'дрин"},ang={["class:Druid"]="Искаженные болотные твари и застойные оскверненные воды показывают, какой разрушительный урон наносит природе демоническая энергия, если ее не остановить.",["race:NightElf"]="Озеро Ирис — горький пример расползающейся порчи, угрожающей Ясеневому лесу, но добыча слез Элуны на его загрязненных берегах дает надежду на очищение леса."},sec={{t="Оскверненное убежище",b="Озеро Ирис лежит между Астранааром и лунным колодцем, за которым присматривает Шаэл'дрин, и служит мрачным напоминанием о ранах, нанесенных в годы Третьей войны. Энергии Скверны, дрейфующие на юг с оскверненных высот Оскверненного леса, отравили котловину и превратили ее некогда прозрачные воды в мерзкую желтовато-зеленую топь. Порча исказила местные растения и духов воды и породила агрессивных болотных тварей, которые набрасываются на любого путника, забредшего поблизости."},{t="Слезы богини",b="Несмотря на сильное загрязнение, удушающее озеро, на его краях еще сохранились священные остатки прошлого. На илистых берегах порой можно найти редкие кристаллические камни, известные как слезы Элуны. Хранители эльфийских традиций, такие как Шаэл'дрин, ищут эти святые камни, чтобы очищать оскверненные лунные колодцы и противостоять распространению демонической порчи по Ясеневому лесу."}},faq={{q="Почему вода в озере Ирис зеленая и мутная?",a="Озеро Ирис осквернено демонической порчей, стекающей из соседнего Оскверненного леса. Темная магия отравила грунтовые воды, и озеро превратилось в желтовато-зеленую лужу, которая искажает местных животных, превращая их в агрессивных чудовищ.",al={"why is iris lake green","iris lake water","why is iris lake tainted","почему озеро ирис зеленое","вода озера ирис","почему озеро ирис осквернено"}},{q="Какие существа обитают вокруг озера Ирис?",a="Озеро и его берега кишат оскверненными болотными тварями. Эти элементали растений и грязи обезумели от энергии Скверны и яростно нападают на всех, кто приближается к воде.",al={"iris lake monsters","iris lake mobs","what attacks at iris lake","монстры озера ирис","мобы озера ирис","кто нападает у озера ирис"}},{q="Что такое слезы Элуны?",a="Слезы Элуны — священные светящиеся синие камни, которые находят у берегов озера Ирис. Жрецы и хранители ночных эльфов используют их освященную природу в обрядах очищения, в частности для очистки оскверненных лунных колодцев.",al={"elunes tears","elune tear","what is elunes tear","слезы элуны","слеза элуны","что такое слеза элуны"}},{q="Где находится озеро Ирис?",a="Озеро Ирис лежит на севере центральной части Ясеневого леса. Оно расположено строго к востоку от поселения ночных эльфов Астранаар и к западу от лунного колодца Шаэл'дрин.",al={"where is iris lake","iris lake location","how to get to iris lake","где озеро ирис","расположение озера ирис","как добраться до озера ирис"}}},fp="9,251,16.450.0,20.376.0,46.237.0,37.183.0,23.211.0,27.149.0"}
P.entries["subzone:ironband-s-compound"] = {n="Мастерская Сталекрута",s="Мастерская Сталекрута — укрепленный форпост в заснеженных холмах к югу от озера Хельмово Ложе в восточной части Дун Морога. Прежде здесь жил геолог Стерджи Сталекрут, но лагерь захватили враждебные дворфы Черного Железа, нападающие на всякого, кто подходит слишком близко.",h="Мастерская Сталекрута — укрепленный форпост в заснеженных холмах к югу от озера Хельмово Ложе в восточной...",kw={"dark iron","dun morogh","dwarf","helm's bed lake","ironband's compound","ironforge","sturgy ironband","черное железо","дун морог","дворф","озеро хельмово ложе","мастерская сталекрута","стальгорн","стерджи сталекрут"},ang={["class:Warrior"]="Начинающих воинов сюда отправляют опытные наставники Стальгорна, чтобы они доказали свою доблесть, помогая павшим товарищам и собирая свидетельства присутствия Черного Железа.",["race:Dwarf"]="Для Бронзобородов вид коварных дворфов Черного Железа, окопавшихся в границах Дун Морога, — прямое оскорбление и постоянная опасность для их родины."},sec={{t="Падение под натиском Черного Железа",b="Эту мастерскую к югу от озера Хельмово Ложе основал Стерджи Сталекрут, и она служила опорным пунктом в заснеженной глуши Дун Морога. Все изменилось, когда лазутчики Черного Железа глубоко проникли на земли Бронзобородов и заняли это место. Теперь мастерская кишит враждебными дворфами и служит передовой базой врага, угрожающей путникам и ближайшим поселениям, прямо под носом у Стальгорна."},{t="Угроза для Стальгорна",b="Укрепленный лагерь Черного Железа в границах самого Дун Морога — серьезная провокация. Стальгорн внимательно следит за мастерской и посылает опытных воинов, чтобы подобрать павших разведчиков и добыть важные сведения, подтверждающие масштаб угрозы Черного Железа в горном королевстве."}},faq={{q="Кто изначально построил Мастерскую Сталекрута?",a="Форпост прежде занимал и использовал Стерджи Сталекрут, пока враждебные силы не изгнали его и не захватили это место.",al={"who made this camp","sturgy ironband","who owns ironbands compound","кто построил этот лагерь","стерджи сталекрут","кому принадлежит мастерская сталекрута"}},{q="Кто сейчас контролирует Мастерскую Сталекрута?",a="Лагерь захватила шайка враждебных дворфов Черного Железа, которые охотно нападают на любых странников и патрули Стальгорна, подходящие к нему.",al={"who is here","what enemies are here","dark irons dun morogh","кто здесь","какие враги здесь","черное железо дун морог"}},{q="Где находится Мастерская Сталекрута?",a="Вы найдете ее среди заснеженных холмов восточного Дун Морога, чуть южнее озера Хельмово Ложе.",al={"where is ironbands compound","how to find ironband compound","ironband location","где мастерская сталекрута","как найти мастерскую сталекрута","сталекрут расположение"}},{q="Почему этот лагерь важен для правителей Стальгорна?",a="Укрепленная база вражеского клана так близко к столице дворфов — тревожный провал безопасности. Власти Стальгорна посылают сюда бойцов, чтобы собрать веские доказательства проникновения Черного Железа.",al={"why care about this camp","ironforge response","dark iron threat","почему важен этот лагерь","ответ стальгорна","угроза черного железа"}}},fp="19,261,24.428.0,21.297.0,41.128.0,37.133.0,37.96.0,55.201.0"}
P.entries["subzone:ironband-s-excavation-site"] = {n="Раскопки Сталекрута",s="Раскопки Сталекрута — обширные дворфийские раскопки на юго-востоке Лок Модана, к югу от озера и юго-западу от Приюта Странников. Археологические работы под руководством геолога Сталекрута были внезапно прерваны, когда агрессивные и свирепые трогги захватили траншеи.",h="Раскопки Сталекрута — обширные дворфийские раскопки на юго-востоке Лок Модана, к югу от озера и юго-западу от...",kw={"digsite","excavation site","explorers league","ironband","loch modan","prospector ironband","troggs","раскопки","место раскопок","лига исследователей","сталекрут","лок модан","геолог сталекрут","трогги"},ang={["profession:Mining"]="Карьер и открытые выработки показывают типичные для дворфов методы тяжелой добычи, хотя постоянная враждебность троггов делает любую разведку опасной.",["race:Dwarf"]="Захваченные раскопки — болезненный удар для Лиги исследователей, которая считает возвращение древних реликвий важным для понимания наследия дворфов."},sec={{t="Раскрывая прошлое",b="Стремясь раскрыть свое древнее происхождение от титанов, геолог Сталекрут основал эти обширные раскопки на скалистых обрывах юго-востока Лок Модана. Многообещающие работы быстро обернулись бедой, когда копатели потревожили необычайно свирепую и крупную породу подземных троггов. Существа хлынули из-под земли, оттеснили шахтеров и устроили лагерь среди разбросанных инструментов, сломанных тележек и наполовину раскопанных реликвий."},{t="Руины в красной земле",b="Как и археологические работы в Бесплодных землях, Болотине и Ульдамане, это место застряло в опасной неопределенности. Уцелевшие геологи жмутся к краям периметра, отчаянно пытаясь вернуть украденное снаряжение и защитить открытые артефакты, включая странные древние статуи давно забытых строителей, от разрушения и расхищения прожорливыми троггами."}},faq={{q="Где находятся Раскопки Сталекрута?",a="Раскопки находятся на юго-востоке Лок Модана, строго к югу от озера Лок и к юго-западу от Приюта Странников.",al={"ironband location","where is ironbands digsite","ironband map","расположение сталекрута","где раскопки сталекрута","карта сталекрута"}},{q="Кто такой геолог Сталекрут?",a="Геолог Сталекрут — археолог и исследователь, возглавляющий раскопки от лица дворфийской Лиги исследователей. Он пытается спасти артефакты и отбросить местных троггов.",al={"who is ironband","prospector ironband lore","кто такой сталекрут","геолог сталекрут предыстория"}},{q="Почему раскопки захвачены троггами?",a="Когда дворфы-шахтеры углубились в почву Лок Модана, их туннели вскрыли подземные полости, где обитала крупная и агрессивная порода троггов. Те быстро одолели рабочих и захватили это место.",al={"why are troggs here","who attacked the digsite","ironband troggs","почему здесь трогги","кто напал на раскопки","трогги сталекрута"}},{q="Что дворфы надеялись здесь найти?",a="Как и на многих дворфийских раскопках по всему Каз Модану, шахтеры искали древние реликвии титанов и каменные руины, способные пролить свет на происхождение расы дворфов.",al={"what are they digging for","ironband artifacts","why dig here","что они ищут","артефакты сталекрута","зачем копать здесь"}}},fp="26,280,19.480.0,22.380.0,44.134.0,27.187.0,47.223.0,42.191.0"}
P.entries["subzone:ironbeard-s-tomb"] = {n="Гробница Железноборода",s="Гробница Железноборода — оскверненное дворфийское захоронение к западу от дороги, ведущей на север к Дун Модру в Болотине. Здесь есть кладбище под открытым небом и каменная статуя того, в чью честь названа гробница. Склеп заброшен, а территорию наводнили кислотные слизи. Путники редко заходят в лощину, разве что в поисках вещей, поглощенных слизью.",h="Гробница Железноборода — оскверненное дворфийское захоронение к западу от дороги, ведущей на север к Дун...",kw={"crypt","dun modr","graveyard","ironbeard","ironbeard's tomb","oozes","sida","wetlands","склеп","дун модр","кладбище","железнобород","гробница железноборода","слизи","сида","болотина"},ang={["race:Dwarf"]="Для любого дворфа, идущего по дороге к Мосту Тандола, видеть место последнего упокоения героя клана, заселенное безмозглыми болотными слизями, — горький позор."},sec={{t="Оскверненное место упокоения",b="Гробница Железноборода возвышается над болотами у дороги на север к Дун Модру и свидетельствует о присутствии дворфов в Болотине. Огромная каменная статуя, предположительно изображающая самого Железноборода, охраняет окрестное кладбище. Но торжественный покой здесь больше не царит. Подземный склеп полностью захвачен слизями черных и багровых разновидностей, и гробница заражена. Дворфы больше не привозят сюда своих мертвых, а те, кто достаточно смел, чтобы потревожить склепы, в основном ищут останки, переваренные затаившейся слизью."}},faq={{q="Кем был Железнобород?",a="О самом Железнобороде известно очень мало, но огромная статуя и территория склепа говорят о том, что он был почитаемым дворфом, известным в Болотине. Памятник в его честь возвышается на склоне над кладбищем.",al={"ironbeard lore","who is ironbeard","statue identity","железнобород предыстория","кто такой железнобород","чья статуя"}},{q="Почему гробница заброшена?",a="Склеп полностью захвачен кислотными черными и багровыми слизями. Поскольку захоронения осквернены и кишат опасной слизью, скорбящие семьи перестали привозить сюда своих мертвых.",al={"why abandoned","oozes in tomb","what happened to the crypt","почему заброшена","слизи в гробнице","что случилось со склепом"}},{q="Почему искатели приключений исследуют Гробницу Железноборода?",a="Помимо борьбы с мерзким нашествием, путники часто обыскивают слизь в гробнице в надежде вернуть поглощенные вещи, в первую очередь потерянную сумку Сиды.",al={"why go here","sida bag","tomb quests","зачем идти сюда","сумка сиды","задания гробницы"}},{q="Где находится Гробница Железноборода?",a="Гробница расположена на севере центральной части Болотины, в холме к западу от главной дороги, ведущей на север к дворфийскому оплоту Дун Модр.",al={"tomb location","how to get to ironbeard tomb","ironbeard wetlands map","расположение гробницы","как добраться до гробницы железноборода","гробница железноборода болотина карта"}}},fp="16,359,24.600.0,18.241.0,26.196.0,44.153.0,34.143.0"}
P.entries["subzone:ironclad-cove"] = {n="Потайная бухта",s="Потайная бухта — огромная подземная пещера под Западным Краем, где находятся подземная верфь и причал. Это тайная верфь, на которой Братство Справедливости строит свой боевой броненосец, и она напрямую соединена с морем.",h="Потайная бухта — огромная подземная пещера под Западным Краем, где находятся подземная верфь и причал.",kw={"cookie","deadmines ship","defias cove","edwin vancleef","ironclad cove","juggernaught","shipyard","пирожок","корабль мертвых копей","бухта братства справедливости","эдвин ван клиф","потайная бухта","броненосец","верфь"},ang={["class:Rogue"]="Бухта — вершина мастерства, инженерного таланта и подземной логистики Эдвина ван Клифа, что делает ее легендарной среди воров и изгоев.",["faction:Alliance"]="Полноразмерный военный галеон, спрятанный под Западным Краем, превращает Братство Справедливости из региональной банды разбойников в смертельную военную угрозу для Королевства Штормград."},sec={{t="Скрытая верфь",b="Потайная бухта, расположенная в самой глубокой части Мертвых копей, — величественная морская пещера, превращенная в укрепленную верфь. Здесь Эдвин ван Клиф и Братство Справедливости построили огромный военный корабль, известный как броненосец. В пещере много деревянных лесов, островков и погрузочных мостков, где работают пираты Братства Справедливости, матросы и надсмотрщики. Ее существование показывает истинный масштаб угрозы: ван Клиф намерен не просто грабить фермы Западного Края, а собрать частный флот, способный обстреливать берега самого Штормграда."},{t="Врата в океан",b="В пещере доминируют колоссальные морские врата, укрепленные железом и вделанные в скальную стену. Когда их открывают, они дают прямой выход в Великое море у побережья чуть севернее Тернистой долины. До того как Братство Справедливости захватило бухту, ею владела независимая пиратская команда, которую Братство перебило ради полной секретности. Скрытая от глаз флота Штормграда, бухта дает Братству неконтролируемый путь для провоза контрабанды, организации морских набегов и подготовки морского нападения."}},faq={{q="Для чего строят корабль в Потайной бухте?",a="Броненосец — центральный элемент военных замыслов Эдвина ван Клифа. Братство Справедливости построило этот огромный военный корабль глубоко под землей, чтобы он мог незаметно выйти по подземным водным каналам и ударить по Штормграду с моря.",al={"why is there a ship here","what is the juggernaught","deadmines ship purpose","почему здесь корабль","что такое броненосец","назначение корабля в мертвых копях"}},{q="Куда ведут большие металлические врата в бухте?",a="Огромные врата открываются прямо в океан у южного побережья Западного Края, около границы с северной частью Тернистой долины. Когда их открывают, броненосец может выйти прямо в Великое море.",al={"where do the sea gates open","deadmines iron doors","exit into the ocean","куда открываются морские врата","железные двери мертвых копей","выход в океан"}},{q="Кто контролирует Потайную бухту?",a="Бухтой владеет Братство Справедливости под командованием Эдвина ван Клифа. Сначала уединенной пещерой пользовались независимые пираты, но силы ван Клифа уничтожили их, чтобы занять причалы и сохранить строительство броненосца в полной тайне.",al={"who runs the cove","who lives in ironclad cove","кто управляет бухтой","кто живет в потайной бухте"}},{q="Кто мурлок на борту корабля?",a="Это Пирожок, кок корабля Братства Справедливости. Вооруженный скалкой и котлами, он необычный союзник среди людей и гоблинов-отступников и объявил камбуз своими личными владениями.",al={"cookie the murloc","why is there a murloc pirate","chef cookie","мурлок пирожок","почему здесь мурлок-пират","повар пирожок"}}},fp="13,235,19.576.0,20.553.1,50.256.0,49.204.0,27.252.0,34.197.0"}
P.entries["subzone:ironforge"] = {n="Стальгорн",s="Стальгорн — подземная столица дворфов, высеченная глубоко в камне горы Стальгорн в Дун Мороге. Он раскинулся вокруг ревущей Великой кузни и служит политическим и торговым центром королевства Каз Модан и оплотом Альянса.",h="Стальгорн — подземная столица дворфов, высеченная глубоко в камне горы Стальгорн в Дун Мороге.",kw={"bronzebeard","deeprun tram","dun morogh","great forge","high seat","ironforge","khaz modan","magni","tinker town","бронзобород","подземный поезд","дун морог","великая кузня","высокий трон","стальгорн","каз модан","магни","город механиков"},ang={["race:Dwarf"]="Стальгорн — родовая столица и сердце клана Бронзобородов, где дворфийское мастерство, доблесть и история высечены прямо в живом камне горы.",["race:Gnome"]="Потеряв Гномреган из-за троггов и радиации, гномы сделали Город механиков временным убежищем и плацдармом для попыток вернуть свой дом."},sec={{t="Горная крепость",b="Город, вырубленный в подземных глубинах горы Стальгорн, состоит из концентрических каменных колец, расходящихся от монументальной Великой кузни. Он был основан тысячелетия назад, после того как дворфы пробудились и покинули Ульдаман, и пережил века истории, в том числе древнюю Войну трех молотов, после которой власть осталась только у клана Бронзобородов. Пещерный город, питаемый потоками расплавленной магмы и защищенный огромными каменными вратами, одновременно служит промышленным центром и неприступной твердыней. Помимо дворфийских мастеров и воинов, в его залах живет и множество изгнанных гномов после недавнего падения Гномрегана."},{t="Сердце торговли Альянса",b="В 25 году ПДП Стальгорн — пожалуй, самый оживленный центр торговли и промышленности во всем Альянсе. Король Магни Бронзобород правит Каз Моданом с Высокого трона, а дворфийские рудознатцы, шахтеры и инженеры работают сообща с гномами-беженцами, поселившимися в Городе механиков. Подземный поезд — непрерывная скоростная линия под горами — напрямую связывает Стальгорн со Штормградом, тесно объединяя обе столицы торговлей, переброской войск и взаимной обороной."}},faq={{q="Кто сейчас правит Стальгорном?",a="Стальгорном правит король Магни Бронзобород, который держит двор на Высоком троне. Город является столицей королевства Каз Модан под единоличным руководством клана Бронзобородов.",al={"who is the king of ironforge","ironforge leader","who leads ironforge","кто король стальгорна","правитель стальгорна","кто управляет стальгорном"}},{q="Почему в Стальгорне живет так много гномов?",a="После катастрофического падения и радиоактивного заражения их соседней столицы, Гномрегана, уцелевшие гномы бежали в Стальгорн. Бронзобороды приняли давних союзников и предоставили им убежище в квартале, известном как Город механиков.",al={"why are gnomes in ironforge","gnomes tinker town","where did gnomes come from","почему гномы в стальгорне","гномы город механиков","откуда взялись гномы"}},{q="Как Стальгорн связан со Штормградом?",a="Стальгорн напрямую связан со Штормградом через Подземный поезд — инженерное чудо, построенное гномами, которое идет под землей от Города механиков до Квартала Дворфов Штормграда.",al={"tram to stormwind","how to get to stormwind","subway to stormwind","поезд в штормград","как добраться до штормграда","метро в штормград"}},{q="Что такое Великая кузня в центре города?",a="Великая кузня — огромный горн, питаемый природными реками магмы, проведенными прямо через сердце горы. Это главный центр кузнечного дела и плавки в королевстве Каз Модан.",al={"giant forge in ironforge","what is the great forge","lava in ironforge center","гигантская кузня стальгорна","что такое великая кузня","лава в центре стальгорна"}}},fp="9,278,21.676.0,23.498.0,30.189.0,49.238.0,45.194.0,50.210.0"}
P.entries["subzone:ironforge-airfield"] = {n="Аэродром Стальгорна",s="Скрытая высоко в заснеженных пиках к северо-востоку от Стальгорна, эта удаленная дворфийская взлетная полоса служит испытательной площадкой и базой для гномьих летающих машин и дворфийских горцев. Плато не отмечено на главных дорогах и возвышается над зубчатыми утесами Дун Морога и крутым спуском к Болотине.",h="Скрытая высоко в заснеженных пиках к северо-востоку от Стальгорна, эта удаленная дворфийская взлетная полоса...",kw={"airfield","airstrip","dun morogh","flying machine","frostmane","ironforge","mountaineers","аэродром","взлетная полоса","дун морог","летающая машина","мерзлогрив","стальгорн","горцы"},ang={["profession:Engineering"]="Для механиков взлетная полоса — вершина гномьей авиации: полностью собранные летающие машины стоят здесь в экстремальном морозе.",["race:Dwarf"]="Аэродром — свидетельство дворфийской бдительности на своих землях: горцы Стальгорна стоят на страже даже на самых недоступных высотах Каз Модана."},sec={{t="Тайная твердыня среди утесов",b="Высокогорный аэродром, расположенный далеко над проторенными тропами Дун Морога, — тихое чудо сотрудничества в Альянсе. Горные пики защищают его от ветров, дворфийская кладка укрепляет продуваемые хребты, а гномьи летающие машины стоят на открытых посадочных полосах. Горцы охраняют периметр, а инженеры в лютый мороз возятся с шестеренками и осматривают дымящие паром двигатели."},{t="Пограничные стычки и замерзшие долины",b="Несмотря на отдаленность, аэродром далеко не спокоен. В окрестной долине, где есть замерзшие воды и утесы, хозяйничают тролли Мерзлогривы, живущие в соседних пещерах и постоянно донимающие дворфийских часовых. В тени пиков дворфийские защитники и патрули Грозовой Вершины регулярно сражаются с троллями-налетчиками на льду, и отдаленный пост пребывает в тихом, бдительном противостоянии."}},faq={{q="Как добраться до аэродрома?",a="К долине не ведут ни дороги, ни полеты, ни поддерживаемые туннели из Стальгорна или нижнего Дун Морога. Добраться туда можно, только взобравшись пешком по крутым склонам, обычно по сложным тропам вдоль хребтов, начинающимся в Лок Модане или возле перевалов Дун Морога.",al={"get to airfield","how to climb to airfield","airfield location","airfield path","добраться до аэродрома","как забраться на аэродром","где аэродром","путь к аэродрому"}},{q="Для чего нужно это место?",a="Это высокогорный испытательный полигон и военная застава, где дворфийские горцы и гномьи инженеры обслуживают летающие машины и разведывают высокогорные пограничные земли, разделяющие Дун Морог, Лок Модан и Болотину.",al={"why is there an airstrip","what is ironforge airfield for","зачем здесь взлетная полоса","для чего аэродром стальгорна"}},{q="Кто нападает на дворфийских стражей?",a="Местные тролли Мерзлогривы живут в пещерах на южных утесах долины. Дворфийские горцы регулярно сражаются с ними на замерзшем озере прямо под взлетной полосой.",al={"who attacks airfield","who is fighting on the lake","кто нападает на аэродром","кто сражается на озере"}},{q="Связан ли аэродром с какими-либо заданиями?",a="Обычные задания не отправляют искателей приключений на взлетную полосу. Это малоизвестное удаленное плато, почти не связанное с основной логистикой дворфийского королевства.",al={"any quests here","airfield quests","задания здесь","задания аэродрома"}}},fp="18,304,29.419.0,38.403.0,34.276.0,34.225.0,41.167.0,44.184.0"}
P.entries["subzone:irontree-woods"] = {n="Железнолесье",s="Железнолесье — оскверненная роща на севере Оскверненного леса, некогда любимое ночными эльфами как мирное лесное святилище. Разоренные демонической порчей Третьей войны, ее древние защитники обращены в камень, а среди руин бродят искаженные древни и элементали.",h="Железнолесье — оскверненная роща на севере Оскверненного леса, некогда любимое ночными эльфами как мирное...",kw={"ancients","felwood","hastat","irontree woods","moonwell","petrified trees","stoma","treants","vartrus","древние","оскверненный лес","хастат","железнолесье","лунный колодец","окаменевшие деревья","стома","древни","вартрус"},ang={["class:Druid"]="Искаженные болотные звери и окаменевшие Древние показывают всю разрушительность демонической порчи и взывают к чистым водам лунного колодца, способным пробудить обновление в оскверненной почве.",["race:NightElf"]="Стоять среди окаменевших остовов Хастата, Стомы и Вартруса — горькое напоминание о цене, которую Третья война взяла с ваших священных лесов."},sec={{t="Лес, обратившийся в камень",b="Железнолесье было спокойной лесной поляной, за которой ухаживали кальдораи, но демоническая скверна Пылающего Легиона во время Третьей войны высосала жизнь из ее почвы. Древние-хранители рощи — Хастат, Стома и Вартрус — поддались темной магии и обратились в безжизненные каменные изваяния, которые до сих пор стоят среди оскверненных зарослей. Теперь обезумевшие древни, мерзкие болотные звери и оскверненные водные элементали бродят по искаженной лесной земле и яростно нападают на любого путника, осмелившегося приблизиться."}},faq={{q="Что случилось с гигантскими деревьями?",a="Великие живые деревья ночных эльфов — в частности Древние по имени Хастат, Стома и Вартрус — поддались демонической порче, охватившей Оскверненный лес во время Третьей войны. Темные силы обратили их в камень, оставив замершими безжизненными изваяниями.",al={"why are trees stone","petrified ancients","irontree stone trees","почему деревья каменные","окаменевшие древние","каменные деревья железнолесья"}},{q="Почему существа в этом лесу враждебны?",a="Всепроникающая скверна Пылающего Легиона свела с ума местных обитателей леса. Древни, болотные звери и водные элементали лишились здравого рассудка и обличья и агрессивно относятся ко всему чужому.",al={"angry treants felwood","corrupted elementals irontree","злые древни оскверненный лес","оскверненные элементали железнолесье"}},{q="Сможет ли Железнолесье оправиться от порчи?",a="Роща глубоко искажена, а ее Древние-хранители мертвы и окаменели. Надежда на исцеление связана с друидами, которые стараются очистить демоническую порчу, охватившую весь Оскверненный лес.",al={"healing irontree woods","can felwood be saved","new ancient irontree","исцеление железнолесья","можно ли спасти оскверненный лес","новый древний железнолесья"}},{q="Кто раньше ухаживал за этой рощей?",a="Ночные эльфы и их союзники Древние некогда защищали эту поляну и ухаживали за ней, о чем свидетельствуют кальдорайские каменные постройки, реликвии и окаменевшие деревья-хранители, разбросанные по северу Оскверненного леса.",al={"night elf irontree","who built the statues","ночные эльфы железнолесье","кто построил статуи"}}},fp="14,296,24.509.0,38.267.0,43.239.0,52.193.0,32.207.0"}
P.entries["subzone:isle-of-dread"] = {n="Остров Ужаса",s="Остров Ужаса — пустынный остров в Великом море у юго-западного побережья Фераласа, к югу от острова Сардор. Он известен чудовищными двуглавыми химероками и укоренившимся кланом враждебных наг, скрытых в подземных морских пещерах.",h="Остров Ужаса — пустынный остров в Великом море у юго-западного побережья Фераласа, к югу от острова Сардор.",kw={"chimaerok","feathermoon","feralas","isle of dread","lakmaeran","naga","sardor isle","shalzaru","szallah","химерок","оперенная луна","фералас","остров ужаса","лакмаэран","наги","остров сардор","шалзару","сзаллах"},ang={["faction:Alliance"]="Стражи-ночные эльфы из соседней Крепости Оперенной Луны внимательно следят за островом и ищут отважных героев, чтобы нанести удар по лорду Шалзару и остановить присутствие наг у своих берегов."},sec={{t="Земля чудовищ и приливов",b="Остров Ужаса, поднимающийся из бьющего прибоя Южных морей, оправдывает свое зловещее название. Он окружен отвесными скалами, и во внутреннюю долину можно попасть только по узкой тропе на юго-восточном берегу. В этом замкнутом нагорье бродит смертоносная стая химероков — ненасытных двуглавых зверей, наделенных силой окружающей тайной магии. Их возглавляет чудовищный лорд Лакмаэран, и остров становится смертельной ловушкой для неосторожных путников, пересекающих пролив от острова Сардор."},{t="Северные пещеры",b="Пока внутреннее плато принадлежит химерокам, на северном берегу острова скрыта система пещер, занятая нагами Гребня Ненависти. Под предводительством лорда Шалзару эти змеелюды таятся в глубоких затопленных залах и замышляют зло против стражей-ночных эльфов, расквартированных в соседней Крепости Оперенной Луны. В их подземном логове есть скрытые подводные ходы, ведущие в укромные гроты, — это сильно укрепленный форпост вдали от глаз материка."}},faq={{q="Как попасть во внутреннюю часть Острова Ужаса?",a="Остров окружен высокими отвесными скалами, которые не дают подняться почти с любого берега. Единственный пеший путь на центральное плато — природная тропа на юго-восточной стороне острова.",al={"isle of dread entrance","how to get up isle of dread","climb isle of dread","вход на остров ужаса","как подняться на остров ужаса","подъем на остров ужаса"}},{q="Какие существа обитают на острове?",a="Высокое плато населяют свирепые химероки, в том числе тайные химероки и огромные пожиратели, которыми правит вершина хищной цепи — лорд Лакмаэран. На северном побережье глубокие морские пещеры кишат враждебными нагами Гребня Ненависти.",al={"isle of dread mobs","monsters on isle of dread","chimaeroks feralas","монстры острова ужаса","существа на острове ужаса","химероки фералас"}},{q="Кто предводительствует нагами в морских пещерах?",a="Клан наг, занимающий северный пещерный комплекс, возглавляет лорд Шалзару. Его присутствие — реальная угроза для ночных эльфов в соседней Крепости Оперенной Луны.",al={"isle of dread naga boss","lord shalzaru cave","naga leader feralas island","босс наг острова ужаса","пещера лорда шалзару","предводитель наг фералас"}},{q="Чем так знаменито мясо химероков?",a="Chimaeroks yield exceptionally rich tenderloins prized by master gourmands. Culinary masters like Dirge Quikcleave seek out meat from the island—including the prized carcass of Lord Lakmaeran—to craft legendary feasts.",al={"chimaerok tenderloin","dirge kickin chimaerok chops","isle of dread food"}}},fp="13,283,28.512.0,20.463.0,51.217.0,43.224.0,36.169.0,36.222.0"}
P.entries["subzone:itharius-s-cave"] = {ang={["class:Druid"]="Присутствие зеленых драконидов в болоте делает эту пещеру особенно интересной для друидов, чьи традиции тесно связаны с зеленым драконьим родом и Изумрудным Сном."},sec={{t="Отшельник среди дракончиков",b="Tucked away in the treacherous, moss-draped crags of the southwestern Swamp of Sorrows, this damp cavern shelters the recluse Itharius. Outside its mouth, unruly green whelps wander the mire. Though high elves rarely wander so far south into wild swamps alone, Itharius keeps a watchful eye on these young dragonkin as they grow, living alongside them in quiet isolation."}},faq={{q="Who lives in this cave?",a="The cave is home to Itharius, a mysterious high elf hermit who dwells apart from civilization and watches over the local dragonkin.",al={"who is itharius","cave owner","who lives here"}},{q="Where is Itharius's Cave located?",a="Она спрятана глубоко в юго-западном углу Болота Печали, у горных хребтов к югу от главной дороги.",al={"itharius cave location","where is itharius","how to find cave"}},{q="Почему у пещеры есть зеленые дракончики?",a="The surrounding marsh is inhabited by green whelps. Itharius has taken it upon himself to watch over and protect these unruly young dragons as they grow.",al={"why whelps here","green dragons swamp of sorrows","whelps outside","почему здесь дракончики","зеленые драконы болото печали","дракончики снаружи"}},{q="Почему высший эльф живет в болоте?",a="High elves are rarely seen in these southern bogs, but Itharius remains here specifically to safeguard the green dragonkin of the swamp, keeping to himself in his remote den.",al={"high elf in swamp","why is itharius here"}}},fp="15,237,21.371.0,23.131.0,33.121.0,44.153.0,43.174.0"}
P.entries["subzone:ivar-patch"] = {n="Делянка Ивара",s="Делянка Ивара — зараженная тыквенная ферма на севере Серебряного бора. Некогда процветавшее земледельческое хозяйство Лордерона, оно лишилось всех жителей во время Третьей войны, а они превратились в ненасытных, безмозглых и враждебных вурдалаков.",h="Делянка Ивара — зараженная тыквенная ферма на севере Серебряного бора.",kw={"deathstalkers","ghouls","ivar patch","ivar the foul","pumpkin patch","quinn yorick","rane yorick","silverpine forest","стражи смерти","вурдалаки","делянка ивара","ивар нечистый","тыквенная делянка","квинн йорик","ран йорик","серебряный бор"},ang={["faction:Horde"]="Истребление ненасытных вурдалаков на делянке жизненно важно для безопасности северной дороги между Серебряным бором и Подгородом.",["race:Undead"]="Разоренная ферма — горькое напоминание о Чуме нежизни, разорвавшей Лордерон на части, и показывает ужасную бессмысленную участь, которой чудом избежали Отрекшиеся."},sec={{t="Погубленный урожай",b="До того как Третья война прошла по Лордерону, эта тыквенная делянка была процветающим хозяйством фермера по имени Ивар, у которого работали бойкие батраки и слуги. Когда Плеть распространила по округе Чуму нежизни, ферма была уничтожена полностью. Ивар, его семья и работники не сохранили разум, как свободные Отрекшиеся, а превратились в гниющих диких вурдалаков, обреченных бродить по разоренной земле."},{t="Засада на Стражей смерти",b="Когда Отрекшиеся начали укреплять север Серебряного бора, три Стража смерти — Ран Йорик, Квинн Йорик и Эрланд Маккри — отправились в разведку, чтобы оценить местные угрозы. Проходя через Мертвое поле, дозор попал в засаду дикой стаи у делянки. Квинна жестоко искусал сам Ивар, ныне известный как Ивар Нечистый. Из-за тяжелой раны Квинна Йорики укрепились в старом разрушенном доме на ферме, а Маккри в одиночку двинулся дальше к Саду Мальдена."}},faq={{q="Что случилось с фермой и ее владельцем?",a="Ферму поразила Чума нежизни во время Третьей войны. Фермер Ивар, его семья и работники погибли и восстали вновь дикими гниющими вурдалаками под остаточной властью Плети.",al={"ivar patch history","who was ivar","what happened to ivar","история делянки ивара","кто такой ивар","что случилось с иваром"}},{q="Почему в доме прячутся Стражи смерти?",a="Стражи смерти Ран и Квинн Йорик входили в разведывательный отряд, посланный оценить угрозы в Серебряном боре. Проходя мимо, они попали в засаду вурдалаков, и Квинна тяжело ранил Ивар Нечистый, из-за чего им пришлось укрыться в ветхом фермерском доме.",al={"deathstalkers at ivar patch","why are forsaken here","quinn yorick farmhouse","стражи смерти на делянке ивара","почему здесь отрекшиеся","дом квинна йорика"}},{q="Относятся ли здешние вурдалаки к Отрекшимся?",a="Нет. Вурдалаки, бродящие по тыквенным полям, — безмозглые остатки Плети, созданные Чумой нежизни. У них нет свободной воли, и они нападают на любых живых путников и на Отрекшихся при виде.",al={"are these ghouls forsaken","scourge in ivar patch","why are ghouls hostile","вурдалаки отрекшиеся","плеть на делянке ивара","почему вурдалаки враждебны"}},{q="Где находится Делянка Ивара?",a="Делянка Ивара лежит на севере Серебряного бора, к северу от Мертвого поля и чуть южнее дороги, ведущей к Саду Мальдена.",al={"ivar patch location","where is ivar patch","расположение делянки ивара","где делянка ивара"}}},fp="10,241,16.461.0,23.475.1,40.206.0,52.307.0,41.184.0,32.134.0"}
P.entries["subzone:jadefire-run"] = {n="Холм Нефритового Пламени",s="Холм Нефритового Пламени — сильно укрепленный лагерь сатиров на севере Оскверненного леса. Здесь обитают самые могущественные и хитрые сатиры региона, а сам лагерь служит бастионом демонической порчи в глубине больного леса.",h="Холм Нефритового Пламени — сильно укрепленный лагерь сатиров на севере Оскверненного леса.",kw={"corrupted","demons","felwood","jadefire","jadefire run","satyr","xavaric","осквернение","оскверненный","демоны","оскверненный лес","нефритовое пламя","холм нефритового пламени","сатир","сатиры","ксаварик"},ang={["class:Druid"]="Друиды видят в мерзких ритуалах и присутствии Скверны на Холме Нефритового Пламени открытую рану, отравляющую природных духов Оскверненного леса.",["race:NightElf"]="Для ночных эльфов Холм Нефритового Пламени — чудовищное напоминание о древнем предательстве и демонической осквернении, от которого необходимо очистить священную землю Калимдора."},sec={{t="Бастион обмана",b="Холм Нефритового Пламени, расположенный среди зараженных лесов севера Оскверненного леса, служит крепостью сатиров Нефритового Пламени. В отличие от мелких застав, разбросанных по долине, в этом лагере есть внушительные демонические постройки, а в нем укрываются грозные чародеи и обманщики. Здешние сатиры деятельно замышляют распространить порчу по Калимдору, применяя темное колдовство и подлые уловки против всякого, кто посмеет вторгнуться на их землю."}},faq={{q="Что такое Холм Нефритового Пламени?",a="Холм Нефритового Пламени — крупное поселение сатиров на севере Оскверненного леса. Это главный оплот самых опасных и отборных сатиров, наводнивших лес.",al={"jadefire run info","what is this place felwood","холм нефритового пламени","что это за место оскверненный лес"}},{q="Кто правит на Холме Нефритового Пламени и кто там живет?",a="Лагерь занимают сатиры Нефритового Пламени — оскверненные слуги Пылающего Легиона, которые владеют магией Скверны и обманными иллюзиями и терроризируют окрестный лес.",al={"who lives here","jadefire run mobs","кто здесь живет","монстры холма нефритового пламени"}},{q="Почему Холм Нефритового Пламени так опасен?",a="Здешние сатиры заметно сильнее и организованнее тех, что живут на юге Оскверненного леса. Благодаря демоническим постройкам и мощным чародеям они легко одолевают неподготовленных искателей приключений.",al={"is jadefire run hard","jadefire run danger","сложен ли холм нефритового пламени","опасность холма нефритового пламени"}}},fp="12,226,19.452.0,21.170.0,35.173.0,33.190.0"}
P.entries["subzone:jaedenar"] = {n="Джеденар",s="Джеденар — зараженная лощина в центре Оскверненного леса, построенная на древних руинах ночных эльфов и друидских курганных нор. Названная в гнусную дань демону Кил'джедену, она служит главной базой Совета Теней на севере Калимдора. Сектанты, чернокнижники и призванные демоны прочесывают оскверненную лощину, охраняя подземный спуск в Оплот Теней.",h="Джеденар — зараженная лощина в центре Оскверненного леса, построенная на древних руинах ночных эльфов и...",kw={"barrow dens","deceiver","felwood","jaedenar","kil'jaeden","shadow council","shadow hold","курганные норы","искуситель","оскверненный лес","джеденар","кил'джеден","совет теней","оплот теней"},ang={["class:Druid"]="Джеденар — трагическое осквернение священной земли: его курганы, некогда мирные убежища для единения с Изумрудным Сном, теперь утопают в демонической жиже.",["class:Warlock"]="Чернокнижники Джеденара олицетворяют неизменное присутствие Совета Теней в Азероте: они открыто призывают могучих демонов и владеют нестабильным колдовством Скверны."},sec={{t="Бастион поклонения Скверне",b="Давным-давно в этих лощинах находились священные места ночных эльфов и спали друиды, связанные с Изумрудным Сном. После разрушений Третьей войны мерзкие остатки Совета Теней завладели долиной и назвали ее Джеденар в честь демона Кил'джедена. Здесь собрались чернокнижники — главным образом орки-отступники и Отрекшиеся — вместе с сатирами, суккубами и стражами Скверны. Они занимают как наземные руины, так и глубокие курганные норы, превращая некогда священный лес в мрачный центр демонических призывов."},{t="Врата Оплота Теней",b="На поверхности сектанты собираются в оскверненных местах, таких как Святилище Искусителя, жгут жаровни с мерзким пламенем и проводят ритуалы, чтобы еще сильнее осквернить лес. Под землей находится вход в Оплот Теней — подземную крепость, откуда истинные хозяева Совета направляют свои действия по всему Оскверненному лесу. Изумрудное святилище с глубокой тревогой наблюдает за гниющим анклавом и регулярно привлекает отважных странников, чтобы они разрушали круги призыва и гасили темное пламя, запечатывающее туннели."}},faq={{q="В честь чего назван Джеденар?",a="Джеденар был назван Советом Теней в поклонение Кил'джедену Искусителю, одному из верховных командиров Пылающего Легиона.",al={"jaedenar name origin","why is it called jaedenar","jaedenar namesake","происхождение названия джеденар","почему он называется джеденар","тезка джеденара"}},{q="Кто контролирует Джеденар?",a="Крепость удерживает Совет Теней — коварный заговор смертных чернокнижников, главным образом орков и Отрекшихся, служащих демонической воле Пылающего Легиона вместе с призванными исчадиями и оскверненными сатирами.",al={"who runs jaedenar","jaedenar faction","enemies in jaedenar","кто правит джеденаром","фракция джеденара","враги в джеденаре"}},{q="Что было здесь до прихода демонов?",a="До Третьей войны здесь стояли древние постройки ночных эльфов и мирные друидские курганные норы, где друиды отдыхали, странствуя по Изумрудному Сну.",al={"jaedenar history","who lived in jaedenar","jaedenar barrow dens","история джеденара","кто жил в джеденаре","курганные норы джеденара"}},{q="Что такое Оплот Теней?",a="Оплот Теней — подземная система пещер под Джеденаром. Прежде это были друидские курганные норы, а теперь здесь укрепленная штаб-квартира руководства Совета Теней в Оскверненном лесу.",al={"what is shadow hold","cave in jaedenar","underground jaedenar","что такое оплот теней","пещера в джеденаре","подземный джеденар"}}},fp="8,370,24.534.0,28.529.0,29.132.0,22.210.0,40.165.0,24.191.0"}
P.entries["subzone:jagged-reef"] = {n="Острые рифы",s="Острые рифы образуют суровое северное побережье Азшары, где песчаные пляжи встречаются с зубчатыми каменными выступами и бурным прибоем. Под мелкой водой скрываются коварные скалы, из-за чего морские путешествия невозможны. Пустынный берег населяют в основном бродящие гидры, макруры-падальщики и мурлоки, охраняющие свои земли.",h="Острые рифы образуют суровое северное побережье Азшары, где песчаные пляжи встречаются с зубчатыми каменными...",kw={"azshara","beach","coast","hydras","jagged reef","makrura","murlocs","shallows","азшара","пляж","побережье","гидры","острые рифы","макруры","мурлоки","мелководье"},ang={["class:Hunter"]="Открытые северные пляжи дают множество возможностей изучать или приручать местных земноводных зверей, например гидр и прибрежных ракообразных."},sec={{t="Опасное побережье",b="Острые рифы, протянувшиеся вдоль северного края Азшары, — суровая прибрежная полоса, где разломанные утесы и торчащие каменные выступы делят песчаные берега на уединенные бухты. Под бьющимися волнами лежат затопленные скалы и переменчивые мели, превращающие воды в кладбище для любого корабля, чья команда осмелится подойти близко. На суше дикий берег тоже неприветлив: покрытые солью звери, хищные гидры и свирепые макруры бродят по линии прибоя рядом с укрепившимися мурлоками, которые выискивают в приливах объедки и неосторожную добычу."}},faq={{q="Где находятся Острые рифы?",a="Острые рифы занимают северное побережье Азшары: участки пляжей, скалистые выступы и небольшие морские заливы вдоль северных берегов региона.",al={"jagged reef location","where is jagged reef","где острые рифы","расположение острых рифов"}},{q="Какие существа обитают на Острых рифах?",a="Побережье кишит опасными водными тварями: свирепыми мурлоками, голодными многоголовыми гидрами и бронированными макрурами, обыскивающими и мелководье, и песчаный пляж.",al={"what lives here","jagged reef mobs","monsters in jagged reef","кто здесь живет","существа острых рифов","монстры острых рифов"}},{q="Могут ли корабли плавать в водах у Острых рифов?",a="Нет. Название местность получила из-за множества коварных подводных скал и непредсказуемых мелей: плавание через рифы для любого корабля почти равносильно самоубийству.",al={"can boats sail here","jagged reef shipping","могут ли лодки плыть здесь","судоходство острые рифы"}},{q="Есть ли поселения вдоль рифов?",a="Цивилизованных поселений на Острых рифах нет. Если не считать случайных исследователей и охотников, единственное организованное присутствие — дикие стоянки мурлоков, разбросанные по берегу.",al={"towns near jagged reef","who lives at jagged reef","поселения у острых рифов","кто живет на острых рифах"}}},fp="11,320,20.546.0,33.162.0,39.183.0,53.183.0,41.191.0"}
P.entries["subzone:jaggedswine-farm"] = {n="Свиноферма",s="Свиноферма — скромное скотоводческое хозяйство на севере Дуротара, чуть южнее главного входа в Оргриммар. Она состоит из деревянного склада, просторного загона и грязного водопоя и служит важным источником пищи: здесь выращивают выносливых свиней для близкой столицы Орды.",h="Свиноферма — скромное скотоводческое хозяйство на севере Дуротара, чуть южнее главного входа в Оргриммар.",kw={"boars","durotar","horde provisions","jaggedswine farm","orgrimmar","pig pen","pigs","swine","кабаны","дуротар","провиант орды","свиноферма","оргриммар","свиной загон","свиньи"},ang={["faction:Horde"]="Наладить стабильные поставки мяса в засушливых пустошах Дуротара — вопрос выживания, поэтому такие форпосты, как Свиноферма, жизненно важны для военной мощи Оргриммара.",["profession:Cooking"]="Для поваров Орды, осваивающих ремесло в Дуротаре, обилие свиней у Свинофермы делает ее главным местным источником нежных ребрышек, кусков свинины и жира для готовки."},sec={{t="Провиант для столицы",b="Свиноферма, вырубленная в суровой, выжженной солнцем земле Дуротара, показывает, как нелегко кормить такой городок-крепость, как Оргриммар. Красная почва региона почти не родит, поэтому крепкий скот необходим, чтобы кормить тысячи орочьих воинов и работников. Хозяйство держится на деревянном амбаре, широком загоне и естественном пруду-водопое, где свиней пасут, разводят и забивают, чтобы амбары Орды не пустовали."},{t="Тихий рубеж",b="Хотя на ферме тихо и под сухим зноем она часто выглядит полузаброшенной, здесь регулярно бывают местные свинопасы и патрулирующие Оргриммар грунты. Дикие и взрослые свиньи бродят и в загонах, и за их пределами, порой испытывая терпение стражи неподалеку. Расположенный прямо у подхода к долине столицы, участок остается неприметным, но необходимым звеном в повседневном снабжении Дуротара."}},faq={{q="Для чего нужна Свиноферма?",a="На ферме разводят и содержат свиней, чтобы обеспечить Орду мясом и салом, прежде всего для пропитания жителей и гарнизона соседнего Оргриммара.",al={"what is jaggedswine farm","why is there a pig farm in durotar","jaggedswine farm purpose","что такое свиноферма","зачем свиноферма в дуротаре","назначение свинофермы"}},{q="Где именно находится Свиноферма?",a="Она лежит на севере Дуротара, у южного подхода и больших ворот, ведущих в Аллею Силы в Оргриммаре.",al={"where is jaggedswine farm","how to get to jaggedswine farm","pig farm durotar location","где свиноферма","как добраться до свинофермы","свиноферма дуротар"}},{q="Почему ферма выглядит почти пустой?",a="Орочье скотоводство в Дуротаре утилитарно и непритязательно. Из-за свободно бродящих кабанов и редких деревянных построек в хозяйстве нет больших усадеб, но Орда по-прежнему активно использует его для снабжения.",al={"is jaggedswine farm abandoned","who lives at jaggedswine farm","why no farmers","заброшена ли свиноферма","кто живет на свиноферме","почему нет фермеров"}},{q="Опасны ли здешние свиньи для путников?",a="Домашние свиньи в загонах смирные, но дикие и взрослые кабаны на окраинах могут напасть, если их напугают юные путники или неосторожные собиратели.",al={"are swine hostile","do pigs attack here","swine dangerous","опасны ли свиньи","нападают ли свиньи","свиньи опасны"}}},fp="16,287,26.461.0,16.432.0,40.145.0,42.139.0,41.213.0,41.171.0"}
P.entries["subzone:jaguero-isle"] = {n="Остров Жагуаро",s="Остров Жагуаро — уединенный остров, поросший джунглями, у восточного побережья Пустынного берега в Тернистой долине. Здесь властвуют свирепые дикие пантеры и гориллы, а остров известен как владения огромной гориллы-серебряной спины по имени король Мукла.",h="Остров Жагуаро — уединенный остров, поросший джунглями, у восточного побережья Пустынного берега в Тернистой...",kw={"gorilla","jaguero","jaguero isle","king mukla","panther","princess poobah","stranglethorn","wild shore","горилла","жагуаро","остров жагуаро","король мукла","пантера","принцесса пуба","тернистая долина","пустынный берег"},ang={["class:Hunter"]="Экзотические хищники острова Жагуаро, от крадущихся пантер до самого могучего короля Муклы, становятся неотразимым испытанием для опытных охотников."},sec={{t="Первобытные владения",b="Остров Жагуаро лежит у юго-восточного побережья Тернистой долины, вдали от пиратских лагерей и тролльских руин материка. Остров целиком захвачен дикими животными, в основном пантерами и агрессивными гориллами. Над всеми ними возвышается гигантский примат король Мукла, чья власть над скалистой глубиной острова безраздельна. Немногие моряки по своей воле подходят к его рифам, хотя бутылки, выброшенные на пляжи материка, порой несут отчаянные мольбы о спасении от несчастных, оказавшихся на берегу."},{t="Пленная принцесса",b="Самая необычная и опасная история острова связана с принцессой Пуба, тауренкой, потерпевшей кораблекрушение и плененной королем Муклой. Оказавшись на острове, кишащем хищниками, она сумела отправить послания о помощи в бутылках по волнам Пустынного берега в надежде, что проходящий мимо искатель приключений рискнет навлечь гнев Муклы и поможет ей бежать."}},faq={{q="Где находится остров Жагуаро?",a="Остров Жагуаро лежит в Великом море у юго-восточного побережья Тернистой долины, к востоку от Пустынного берега.",al={"jaguero isle location","where is jaguero","find jaguero isle","где остров жагуаро","расположение острова жагуаро","найти остров жагуаро"}},{q="Кто такой король Мукла?",a="King Mukla is a gigantic, powerful gorilla who reigns over Jaguero Isle. Territorial and aggressive, he dominates the island's interior.",al={"mukla","king mukla gorilla","ape boss stranglethorn","мукла","король мукла горилла","босс обезьян тернистая долина"}},{q="Кто такая принцесса Пуба?",a="Princess Poobah is a stranded tauren trapped on Jaguero Isle far from her home. She casts messages in bottles into the sea in hopes of being rescued.",al={"tauren captive","who is poobah","princess poobah","пленная тауренка","кто такая пуба","принцесса пуба"}},{q="Как начать задание, чтобы посетить остров?",a="Искатели приключений обычно узнают о ее беде, найдя наполовину зарытые в песок бутылки, выброшенные на материковые пляжи Пустынного берега, с аккуратно сложенной запиской с просьбой о помощи.",al={"message in a bottle quest","jaguero island quest","how to get to jaguero","задание бутылка с запиской","задание остров жагуаро","как попасть на остров жагуаро"}}},fp="12,249,15.540.0,20.355.1,30.120.0,18.136.0,23.149.0,47.179.0"}
P.entries["subzone:janeiro-s-point"] = {n="Остров Жанейро",s="Остров Жанейро — небольшой скалистый остров прямо у гавани Пиратской бухты на юге Тернистой долины. Его венчает колоссальная каменная статуя неизвестного гоблина, приветствующего корабли распростертыми руками. Воды и берега острова во власти грозного морского великана Мок'раша Колуна.",h="Остров Жанейро — небольшой скалистый остров прямо у гавани Пиратской бухты на юге Тернистой долины.",kw={"booty bay","goblin statue","janeiro's point","mok'rash","sea giant","stranglethorn","пиратская бухта","статуя гоблина","остров жанейро","мок'раш","морской великан","тернистая долина"},sec={{t="Маяк бухты",b="Остров Жанейро — монументальные врата Пиратской бухты — встречает каждый корабль, идущий в южные моря Тернистой долины. На вершине утеса высится огромное каменное изваяние гоблина с раскинутыми руками — жест радушия и безудержных торговых амбиций. Хотя остров виден морякам и корсарам за много миль, высадка на его берег опасна: скалу объявил своей территорией Мок'раш Колун, жуткий морской великан."}},faq={{q="Что такое остров Жанейро?",a="Остров Жанейро — небольшой скалистый остров недалеко от берега, у гавани Пиратской бухты в Тернистой долине. Он служит ориентиром для кораблей, подходящих к гоблинскому порту.",al={"janeiro point","what is this island","booty bay statue island","остров жанейро","что за остров","остров со статуей пиратской бухты"}},{q="Кого изображает гигантская статуя на острове?",a="Колоссальная статуя изображает неизвестного гоблина с раскинутыми руками. Ее воздвигли, чтобы приветствовать торговые корабли и усталых моряков в торговой гавани Пиратской бухты.",al={"statue identity","who is the goblin statue","who is depicted","личность статуи","кто гоблин на статуе","кто изображен"}},{q="Какое опасное существо живет на острове Жанейро?",a="Остров и окружающие мели — владения Мок'раша Колуна, грозного морского великана, смертельно опасного для любых отважных моряков и пловцов, пытающихся приблизиться к статуе.",al={"sea giant island","who lives on janeiro point","mokrash","остров морского великана","кто живет на острове жанейро","мок'раш"}}},fp="15,342,17.496.0,24.178.0,38.163.0,49.205.0"}
P.entries["subzone:jangolode-mine"] = {s="Рудник Янго — богатая шахта в холмах Западного Края. Когда-то он был важным источником руды и сырья для Штормграда, но теперь его захватили бандиты из Братства Справедливости.",h="Рудник Янго — богатая шахта в холмах Западного Края.",kw={"defias brotherhood","jangolode","jangolode mine","kobold","stormwind","westfall","братство справедливости","рудник янго","кобольд","штормград","западный край"},ang={["faction:Alliance"]="Возвращение ресурсов Западного Края жизненно важно для стабилизации королевства, а изгнание бандитов из Рудника Янго — шаг к возрождению процветания региона.",["profession:Mining"]="Рудник Янго по-прежнему богат залежами меди и олова, что делает его выгодной остановкой для старателей, готовых прорваться через подземных вредителей."},sec={{t="Разграбленное богатство",b="Пока Западный Край не пришел в упадок, Рудник Янго давал стабильный поток металлов, необходимых для восстановления и снабжения Штормграда. Когда порядок рухнул, а королевство вывело гарнизоны, Братство Справедливости захватило рудник для собственных нужд. Теперь бандиты сами разрабатывают богатые жилы и яростно защищают свою подземную добычу."}},faq={{q="Что такое Рудник Янго?",a="Это место добычи в Западном Крае, которое исторически снабжало Штормград необходимыми минералами и металлической рудой. Когда оборона региона ослабла, рудник попал в руки врагов.",al={"jangolode mine info","what is jangolode","jangolode westfall","рудник янго","что такое янго","янго западный край"}},{q="Кто сейчас контролирует рудник?",a="Подземные штольни удерживает Братство Справедливости, изгнав прежних шахтеров ради собственных нужд.",al={"who is in jangolode mine","jangolode mobs","who lives in jangolode","кто в руднике янго","существа рудника янго","кто живет в руднике янго"}},{q="Почему Штормград не вернет себе рудник?",a="Штормград погряз в политических волнениях и с трудом защищает даже основные границы. У королевства нет войск для гарнизонов в дальних рудниках Западного Края, и угрозой занимаются Народное ополчение и местные искатели приключений.",al={"why doesnt stormwind clear jangolode","stormwind garrison westfall","why abandon the mine","почему штормград не очистит рудник янго","гарнизон штормграда западный край","почему бросили рудник"}}},fp="14,217,20.391.0,27.177.0,32.120.0,40.228.0"}
P.entries["subzone:jasperlode-mine"] = {n="Яшмовая шахта",s="Яшмовая шахта — железный и минеральный рудник на севере центральной части Элвиннского леса, когда-то снабжавший Штормград важными ресурсами. Сегодня ее штольни наводнили кобольды и смертоносные гигантские пауки, и королевство, испытывающее нехватку ресурсов, не может вернуть шахту себе.",h="Яшмовая шахта — железный и минеральный рудник на севере центральной части Элвиннского леса, когда-то...",kw={"elwynn forest","fargodeep","gold dust","goldshire","jasperlode","kobold","marshal dughan","mother fang","элвиннский лес","рудник подземных глубин","золотая пыль","златоземье","яшмовая шахта","кобольд","маршал дугхан","мать клык"},ang={["faction:Alliance"]="Добыча сырого металла в Яшмовой шахте жизненно важна для снабжения Штормграда снаряжением, пока границам королевства постоянно угрожает опасность.",["profession:Mining"]="Яшмовая шахта богата рудными жилами и остается заманчивой целью для старателей, готовых пробиться сквозь кобольдовы кирки и паучьи сети, чтобы застолбить участок."},sec={{t="Утраченный ресурс Элвиннского леса",b="Яшмовая шахта исторически была одним из самых продуктивных рудников Штормграда и вместе с соседним Рудником Подземных Глубин обеспечивала стабильный приток минералов. Поскольку армия королевства растянута на защите от внешних угроз и беспорядков, местные гарнизоны не смогли защитить штольни. Кобольды воспользовались случаем, пробрались внутрь, выгнали людей-шахтеров и накопили украденное золото и сальные свечи."},{t="Опасности в глубине",b="Беда Яшмовой шахты не ограничивается обычными вредителями. В самых глубоких и темных коридорах под деревянными опорами обосновалась агрессивная колония шахтных пауков. Ее возглавляет огромная самка, известная местным как Мать Клык. Пауки без труда охотятся и на забредших кобольдов, и на неосторожных старателей, поэтому любая попытка вернуть шахту крайне опасна."}},faq={{q="Почему Яшмовую шахту захватили?",a="Регулярная армия Штормграда растянута по всему королевству, и в сельских аванпостах вроде Златоземья не хватает людей. Кобольды быстро воспользовались ситуацией и заполонили выработки, когда шахтеры лишились охраны.",al={"why are there kobolds","who controls jasperlode","why abandoned","почему там кобольды","кто контролирует яшмовую шахту","почему заброшена"}},{q="Чем Яшмовая шахта отличается от Рудника Подземных Глубин?",a="Рудник Подземных Глубин находится на юге, рядом с фермами Маклюр и Стоунфилд, а Яшмовая шахта лежит на севере, в предгорьях у реки. Оба — крупные месторождения Элвиннского леса, потерянные из-за нашествия кобольдов.",al={"jasperlode vs fargodeep","other elwynn mine","яшмовая шахта или рудник подземных глубин","другая шахта элвиннского леса"}},{q="Что скрывается в глубине шахты?",a="Самые глубокие штольни заполонили хищные шахтные пауки во главе с огромным паукообразным по прозвищу Мать Клык. Даже кобольды-захватчики избегают их паутинных пещер.",al={"spiders in jasperlode","mother fang","what is at the bottom","пауки в яшмовой шахте","мать клык","что в глубине шахты"}},{q="Почему маршал Дугхан не очистил шахту?",a="У маршала Дугхана не хватает солдат для долгой зачистки подземелий. Из-за речных патрулей против Братства Справедливости, набегов гноллов и гарнизонной службы местное ополчение вынуждено полагаться на странствующих искателей приключений, которые разведают шахту и сократят число угроз.",al={"why no stormwind guard","dughan sending soldiers","почему нет стражи штормграда","дугхан отправляет солдат"}}},fp="15,272,25.414.0,19.391.0,31.218.0,56.215.0,35.162.0,43.235.0"}
P.entries["subzone:jerod-s-landing"] = {n="Лагерь Джерода",s="Лагерь Джерода — скромная речная пристань на берегу реки Назферити со стороны Элвиннского леса. Сейчас ее удерживает Братство Справедливости, и лагерь служит тайным пунктом перевалки незаконных грузов, которые провозят по водным путям королевства.",h="Лагерь Джерода — скромная речная пристань на берегу реки Назферити со стороны Элвиннского леса.",kw={"defias dockmaster","jerod's landing","klaven's tower","mathias shaw","nazferiti river","smuggling","snatch and grab","начальник причала братства справедливости","лагерь джерода","башня клейвена","матиас шоу","река назферити","контрабанда","хватай и беги"},ang={["class:Rogue"]="Разбойников, работающих на ШРУ, отправляют в Лагерь Джерода: проверить скрытность, обчистить карманы начальника причала Братства Справедливости и добыть секретные торговые книги.",["faction:Alliance"]="Захват Лагеря Джерода показывает, как основательно Братство Справедливости подчинило внутренние водные пути между Элвиннским лесом и Красногорьем прямо под носом у Штормграда."},sec={{t="Путевая точка контрабандистов",b="Лагерь Джерода, спрятанный на восточных водах реки Назферити, дает выход к реке, соединяющей Элвиннский лес с соседними землями. Прежде это была обычная лодочная пристань, но теперь она прочно оказалась в руках Братства Справедливости. Под присмотром начальника причала Братства разбойники используют пристань как узел для приема товаров, награбленных в Красногорье, и тайно переправляют речные грузы вниз по течению к таким владениям, как Башня Клейвена в Западном Крае."},{t="Глаза в тени",b="Из-за выгодного положения на реке Лагерь Джерода привлек внимание ШРУ, тайной разведывательной службы Штормграда. Агенты, следящие за действиями Братства Справедливости, считают лагерь важным звеном в цепи снабжения синдиката и отправляют туда находчивых разбойников: проникнуть на причалы, выкрасть книги учета речных грузов и раскрыть более широкий заговор, душащий королевство."}},faq={{q="Где находится Лагерь Джерода?",a="Лагерь Джерода находится на востоке Элвиннского леса, на западном берегу реки Назферити, которая служит границей между Элвиннским лесом и Красногорьем.",al={"jerods landing location","where is jerod's landing","jerod dock map","где лагерь джерода","лагерь джерода на карте","пристань джерода"}},{q="Кто контролирует Лагерь Джерода?",a="Лагерь занят членами Братства Справедливости под началом начальника причала, который согласовывает поставки с вооруженными бандитами, охраняющими берег.",al={"who is at jerods landing","defias at jerods landing","jerod landing mobs","кто в лагере джерода","братство справедливости в лагере джерода","мобы лагеря джерода"}},{q="Зачем Братству Справедливости эта пристань?",a="Братство использует пристань как перевалочный пункт для контрабанды: краденые товары и оружие, перехваченные в Красногорье, отправляют в разбойничьи твердыни вроде Башни Клейвена в Западном Крае.",al={"why do defias use jerods landing","defias river smuggling","зачем братство справедливости использует лагерь джерода","речная контрабанда"}},{q="Почему ШРУ интересуется Лагерем Джерода?",a="Мастер Матиас Шоу и его агенты отслеживают поток контрабанды Братства Справедливости через эту пристань, чтобы раскрыть сеть, связывающую Западный Край, Элвиннский лес и Красногорье.",al={"si7 jerods landing","rogue quest jerods landing","шру лагерь джерода","задание разбойника лагерь джерода"}}},fp="15,255,21.490.0,19.384.1,33.175.0,29.163.0,48.194.0,42.163.0"}
P.entries["subzone:kargath"] = {n="Каргат",s="Каргат — укрепленный аванпост Орды в западных Бесплодных землях, ее единственный оплот в Каз Модане. Основанное Экспедиционным корпусом Каргата по приказу вождя Тралла, поселение связывает важные пути через Восточные королевства и служит базой для операций в направлении Черной горы и раскопок в Ульдамане.",h="Каргат — укрепленный аванпост Орды в западных Бесплодных землях, ее единственный оплот в Каз Модане.",kw={"badlands","blackrock mountain","expeditionary force","kargath","kargath bladefist","shattered hand","thrall","uldaman","бесплодные земли","черная гора","экспедиционный корпус","каргат","каргат острорукий","изувеченная длань","тралл","ульдаман"},ang={["faction:Horde"]="Каргат — единственная дружественная Орде крепость во всем Каз Модане, дающая необходимое снабжение, воздушное сообщение и плацдарм для ударов по Черной горе.",["race:Orc"]="Аванпост носит имя вождя Каргата Острорука и напрямую продвигает кампанию Тралла по уничтожению развращенной Темной Орды Ренда Чернорука."},sec={{t="Бастион во вражеских землях",b="Аванпост Каргат назван в честь вождя клана Изувеченная Длань Каргата Острорука и остается единственным поселением Орды в горных землях Каз Модана. Окруженный сухими пустошами, агрессивными зверями и враждебными дворфийскими кланами, гарнизон дает путникам, пересекающим континент, важное убежище на полпути. Его распорядитель полетов соединяет северные владения, такие как Подгород и Павший Молот, с южными оплотами вроде Каменора и Лагеря Гром'гол."},{t="Экспедиционная миссия",b="Экспедиционный корпус Каргата, посланный по прямому приказу вождя Тралла, преследует в регионе две цели. Отряды часто совершают вылазки в древние титанские залы Ульдамана, чтобы выяснить, почему исследователи Стальгорна так дорожат раскопками. Одновременно разведчики прокладывают путь через Тлеющее ущелье к Черной горе, чтобы ударить по ложной «Темной Орде» Ренда Чернорука и справиться с укоренившимися дворфами Черного Железа."}},faq={{q="Почему этот город Орды стоит посреди Бесплодных земель?",a="Вождь Тралл приказал Экспедиционному корпусу Каргата основать аванпост, чтобы закрепиться в регионе, исследовать тайны дворфийских раскопок в Ульдамане и проложить путь вторжения в Черную гору против Темной Орды.",al={"why is kargath here","purpose of kargath","who built kargath","почему здесь каргат","зачем нужен каргат","кто построил каргат"}},{q="В честь кого назван Каргат?",a="Аванпост назван в честь Каргата Острорука, знаменитого вождя орочьего клана Изувеченная Длань.",al={"kargath name origin","who was kargath","kargath bladefist outpost","происхождение названия каргат","кто такой каргат","аванпост каргата острорукого"}},{q="Почему маршруты полетов из Каргата так важны?",a="Каргат служит важным логистическим звеном, соединяющим аванпосты Орды на севере Лордерона, такие как Подгород и Павший Молот, с южными владениями в Тернистой долине и на Болоте Печали.",al={"kargath flight path","why fly to kargath","полеты из каргата","зачем лететь в каргат"}},{q="К борьбе с какой угрозой готовится гарнизон Каргата?",a="Гарнизон регулярно сражается с местными дворфами Черного Железа, изучает присутствие Стальгорна в Ульдамане и готовит наступление на Ренда Чернорука и его соперничающую Темную Орду, засевшую в Черной горе.",al={"kargath enemies","who does kargath fight","враги каргата","с кем воюет каргат"}}},fp="7,349,30.500.0,25.467.0,57.240.0,27.97.0,52.206.0,58.221.0"}
P.entries["subzone:kargathia-keep"] = {n="Крепость Каргатия",s="Крепость Каргатия — укрепленный оплот Орды, защищающий восточный рубеж Лесозаготовок Песни Войны в Ясеневом лесу. Здесь расположена штаб-квартира надсмотрщиков поселения; крепость охраняет границу по реке и обеспечивает быстрое подкрепление прямо из Оргриммара.",h="Крепость Каргатия — укрепленный оплот Орды, защищающий восточный рубеж Лесозаготовок Песни Войны в Ясеневом...",kw={"ashenvale","kargath bladefist","kargathia keep","kargathia outpost","overseer gorthak","southfury river","warsong lumber camp","ясеневый лес","каргат острорук","крепость каргатия","форпост каргатия","надсмотрщик горсак","река строптивая","лесозаготовки песни войны"},ang={["faction:Horde"]="Для защитников Орды Крепость Каргатия — незаменимое убежище на передовой Ясеневого леса, обеспечивающее сохранность ценной древесины, жизненно важной для строительства Оргриммара.",["race:NightElf"]="Для ночных эльфов этот ощетинившийся шипами оплот олицетворяет агрессивное, глубоко укоренившееся вторжение Орды в их священный родовой лес."},sec={{t="Бастион на Строптивой",b="Крепость Каргатия стоит на восточной окраине Лесозаготовок Песни Войны, к западу от реки Строптивая, и служит командным центром лесозаготовок Орды в Ясеневом лесу. Этот укрепленный форпост, усиленный тяжелыми баррикадами с шипами, занимают надсмотрщик Горсак и его офицеры. Благодаря расположению у речной границы клан Песни Войны следит за вторжениями и получает быстрое подкрепление из соседних земель Дуротара и Оргриммара, когда ночные эльфы нападают."},{t="В честь Острорука",b="Как крепость Каргат в Бесплодных землях и Бухта Острорука на побережье Дуротара, этот форпост назван в честь знаменитого вождя Каргата Острорука. Для орков Песни Войны, отважившихся войти во враждебные чащи Ясеневого леса, внушительная классическая архитектура крепости — неизменный символ воинской стойкости и непокорности Орды на земле, захваченной ночными эльфами."}},faq={{q="Где находится Крепость Каргатия?",a="Крепость Каргатия находится в восточной части Ясеневого леса, на восточной окраине Лесозаготовок Песни Войны, к западу от реки Строптивая.",al={"kargathia keep location","where is kargathia keep","kargathia outpost location","где крепость каргатия","расположение крепости каргатия","форпост каргатия"}},{q="Кто командует крепостью?",a="Надсмотрщик Горсак руководит Лесозаготовками Песни Войны из Крепости Каргатия: он управляет заготовкой леса и координирует оборону от нападений Альянса.",al={"who is in charge of kargathia keep","kargathia keep leader","overseer gorthak","кто командует крепостью каргатия","глава крепости каргатия","надсмотрщик горсак"}},{q="Почему крепость назвали Каргатия?",a="Оплот назван в честь Каргата Острорука, легендарного вождя клана Изувеченная Длань; то же имя носят Каргат в Бесплодных землях и Бухта Острорука в Дуротаре.",al={"who is kargathia keep named after","kargath bladefist","why kargathia","в честь кого названа крепость каргатия","каргат острорук","почему каргатия"}},{q="Каково стратегическое назначение этого оплота?",a="Крепость контролирует восточную границу лесозаготовок вдоль реки Строптивая, защищает важный путь снабжения и позволяет быстро переправлять подкрепление из Оргриммара.",al={"why is kargathia keep here","purpose of kargathia keep","kargathia keep importance","зачем нужна крепость каргатия","назначение крепости каргатия","значение крепости каргатия"}}},fp="14,261,26.521.0,22.373.0,32.129.0,19.158.0,33.195.0,49.185.0"}
P.entries["subzone:kodo-rock"] = {n="Дольмен Кодо",s="Дольмен Кодо — природный каменный монумент на равнинах Плато Красного Облака, между Лагерем Нараче и Ежевичной лощиной. Он тихо стоит среди трав Мулгора и служит ранним местом паломничества для молодых шаманов-таурен, учащихся общаться с духами земли. Из-за скромного силуэта на фоне холмистого пейзажа путникам нужно быть очень внимательными, чтобы его заметить.",h="Дольмен Кодо — природный каменный монумент на равнинах Плато Красного Облака, между Лагерем Нараче и...",kw={"brambleblade ravine","camp narache","kodo rock","monument","mulgore","red cloud mesa","shaman trial","tauren shaman","ежевичная лощина","лагерь нараче","дольмен кодо","монумент","мулгор","плато красного облака","испытание шамана","шаман таурен"},ang={["class:Shaman"]="Для начинающих шаманов-таурен, вступающих на духовный путь в Лагере Нараче, Дольмен Кодо — важный ориентир, где они настраиваются на мир стихий.",["race:Tauren"]="Каменное образование служит знакомым ориентиром на равнинах Плато Красного Облака и отражает священную связь Шу'хало со зверями Мулгора."},sec={{t="Ориентир на плато",b="Дольмен Кодо расположен примерно на полпути между Лагерем Нараче и враждебными землями свинобразов в Ежевичной лощине; у его основания виднеется участок истоптанной земли. Хотя ему не хватает величия высоких утесов вокруг Плато Красного Облака, его очертания напоминают почитаемых кодо, бродящих по равнинам. Для странствующих сородичей это тихий природный маяк на продуваемых ветрами равнинах Мулгора."},{t="Духовное значение",b="Для Шу'хало природные образования часто имеют духовный вес. Дольмен Кодо особо почитаем молодыми шаманами-тауренами, вступающими на духовный путь. Новичков направляют сюда на ранние обряды посвящения: одинокий каменный монумент служит священным местом, где они общаются со стихиями и чтят природу, прежде чем отправиться в более опасные края континента."}},faq={{q="Где находится Дольмен Кодо?",a="Дольмен Кодо находится на Плато Красного Облака в Мулгоре. Его можно найти примерно на полпути по прямой между Лагерем Нараче и Ежевичной лощиной; на земле он отмечен небольшой прогалиной голой земли.",al={"kodo rock location","where is kodo rock","find kodo rock","где дольмен кодо","расположение дольмена кодо","найти дольмен кодо"}},{q="Почему Дольмен Кодо трудно найти?",a="Монумент естественно сливается с холмами и травами плато. Он хорошо виден лишь с небольшого расстояния, поэтому путникам нужно внимательно смотреть на местность и искать пятно земли под ним.",al={"cant find kodo rock","kodo rock hidden","не могу найти дольмен кодо","дольмен кодо скрыт"}},{q="Почему Дольмен Кодо важен для шаманов-таурен?",a="Шаманы-таурены приходят к камню во время первых испытаний за пределами Лагеря Нараче. Это мирный священный ориентир для новичков, учащихся настраивать свой дух на землю и стихии Мулгора.",al={"shaman quest kodo rock","why go to kodo rock","задание шамана дольмен кодо","зачем идти к дольмену кодо"}},{q="Какие опасности есть рядом с Дольменом Кодо?",a="Хотя сам участок вокруг Дольмена Кодо обычно спокоен, дальше на северо-восток путь ведет прямо к Ежевичной лощине — каньону, густо населенному воинственными свинобразами Дыбогривами.",al={"is kodo rock safe","enemies near kodo rock","безопасен ли дольмен кодо","враги у дольмена кодо"}}},fp="9,395,22.444.0,22.386.0,27.206.0,30.240.0,45.214.0,32.197.0"}
P.entries["subzone:kolkar-crag"] = {n="Утес Колкара",s="Утес Колкара — выжженное солнцем зазубренное ущелье на юге Дуротара, занятое враждебными кентаврами племени Колкар. Этот оплот под предводительством полководца Колканиса служит плацдармом для организованных набегов на соседние поселения Орды.",h="Утес Колкара — выжженное солнцем зазубренное ущелье на юге Дуротара, занятое враждебными кентаврами племени...",kw={"centaur","durotar","kolkanis","kolkar","kolkar crag","sen'jin village","valley of trials","warlord kolkanis","кентавр","дуротар","колканис","колкар","утес колкара","деревня сен'джин","долина испытаний","полководец колканис"},ang={["faction:Horde"]="Защита южного Дуротара от вторжений кентавров оберегает линии снабжения между Деревней Сен'джин и дорогой к Оргриммару.",["race:Orc"]="Присутствие кентавров так близко к Долине Испытаний угрожает посвящению молодых орков, поэтому усмирение Утеса Колкара — неотложная задача обороны территории."},sec={{t="Заноза в боку Дуротара",b="Утес Колкара, спрятанный в неприступных каньонах южного Дуротара, — опорная база воинственного племени Колкар. Несмотря на засушливую и суровую местность, кентавры укрепили естественные узкие проходы ущелья. Из этой лощины их разведчики и мародеры следят за окрестными равнинами, ища слабые места в землях орков и Черного Копья. Для молодых воинов, тренирующихся в Долине Испытаний или патрулирующих южное побережье, Утес Колкара — ближайший организованный очаг вражды кентавров."},{t="Планы вторжения",b="Кентавры, засевшие на утесе под командованием полководца Колканиса, вынашивают замыслы куда масштабнее мелких стычек. Захваченные планы нападения указывают на цели: Долину Испытаний, Деревню Сен'джин, Колючий Холм и дерзкие удары прямо к вратам Оргриммара. Чтобы остановить эти планы, нужны решительные упреждающие удары вглубь лощины, чтобы убить Колканиса и разбить их сбор, пока боевые отряды не прокатились по долинам."}},faq={{q="Кто живет на Утесе Колкара?",a="Утес Колкара занимает племя кентавров Колкар во главе с полководцем Колканисом. Они используют укрепленный каньон как лагерь и опорный пункт для набегов на форпосты Орды по всему Дуротару.",al={"who is at kolkar crag","kolkar crag inhabitants","who owns kolkar crag","кто на утесе колкара","обитатели утеса колкара","чей утес колкара"}},{q="Почему Орда обеспокоена этой лощиной?",a="Кентавры в ущелье составили планы организованных нападений на важные поселения Дуротара, включая тренировочные земли Долины Испытаний, Деревню Сен'джин, Колючий Холм и сам Оргриммар.",al={"why care about kolkar crag","is kolkar crag dangerous","kolkar threat","чем опасен утес колкара","опасен ли утес колкара","угроза колкаров"}},{q="Кто возглавляет здешних кентавров?",a="Лагерем командует полководец Колканис, свирепый предводитель кентавров, который направляет разведку и составляет боевые планы против орков и троллей.",al={"kolkar crag boss","who leads kolkar crag","warlord kolkanis","босс утеса колкара","кто возглавляет утес колкара","полководец колканис"}}},fp="11,219,25.544.0,19.461.1,25.181.0,45.217.0,27.170.0"}
P.entries["subzone:kormek-s-hut"] = {n="Хижина Кормека",s="Хижина Кормека — уединенное полуразвалившееся жилище посреди бесплодных равнин на севере центральной части Пустошей. Несмотря на унылую обстановку и загадочное название, сейчас в ней живет странная парочка: на удивление миролюбивый культист и гоблин, одержимый добычей костей кодо.",h="Хижина Кормека — уединенное полуразвалившееся жилище посреди бесплодных равнин на севере центральной части...",kw={"bibbly f'utzbuckle","desolace","kodo bones","kormek","kormek's hut","twilight's hammer","willow","биббли футцбакл","пустоши","кости кодо","кормек","хижина кормека","сумеречный молот","уиллоу"},sec={{t="Странный оазис чудаков",b="Эта маленькая лачуга стоит в засушливых пустошах на севере центральной части Пустошей и названа в честь личности, чье местонахождение и имя остаются совершенно неизвестными. Вместо Кормека путники, наткнувшиеся на хижину, встречают необычную пару, живущую в глуши: Уиллоу и Биббли Футцбакла. Внутри хижины сидит Уиллоу, член обычно враждебного и нигилистичного Сумеречного Молота, который, как ни странно, радушно и спокойно относится к чужакам. Снаружи загон, усеянный выбеленными солнцем костями кодо, служит личной танцплощадкой и рабочей площадкой Биббли, непоседливого гоблина, увлеченного коммерческими возможностями сбора костей."}},faq={{q="Кто такой Кормек?",a="Никто не знает. Хижина носит имя Кормека, но ни гоблин снаружи, ни культист внутри не объясняют, кем был Кормек, а сам тезка нигде в пустошах не встречается.",al={"who is kormek","kormek identity","where is kormek","кто такой кормек","личность кормека","где кормек"}},{q="Почему здесь живет дружелюбный культист Сумеречного Молота?",a="Уиллоу живет в хижине и принадлежит к Сумеречному Молоту — культу, обычно враждебному ко всему смертному. По собственным причинам она не проявляет агрессии к путникам, заглянувшим в это уединенное убежище.",al={"willow twilights hammer","why is willow friendly","willow hut","уиллоу сумеречный молот","почему уиллоу дружелюбна","хижина уиллоу"}},{q="Чем занят гоблин снаружи?",a="Биббли Футцбакл целыми днями восторженно пляшет вокруг загона, полного костей кодо. Как и многие предприимчивые гоблины, он в восторге от перспективы превратить древние останки пустыни в чистую прибыль.",al={"bibbly futzbuckle","goblin dancing desolace","why is the goblin dancing","биббли футцбакл","гоблин танцует пустоши","почему гоблин танцует"}},{q="Где находится Хижина Кормека?",a="Хижина расположена на севере центральной части Пустошей, на сухих продуваемых ветрами равнинах к северу от центрального перекрестка и кладбища.",al={"kormek hut location","where is kormek hut","kormek desolace","хижина кормека расположение","где хижина кормека","кормек пустоши"}}},fp="12,278,27.652.0,14.176.0,55.212.0,33.211.0,30.130.0"}
P.entries["subzone:kurzen-s-compound"] = {n="Лагерь Курцена",s="Лагерь Курцена — сильно укрепленное поселение людей в холмах на севере Тернистой долины. Основанный экспедицией, посланной из Штормграда под командованием полковника Курцена, этот форпост превратился в разбойничий лагерь головорезов и диких зверей после того, как их командир впал в безумие.",h="Лагерь Курцена — сильно укрепленное поселение людей в холмах на севере Тернистой долины.",kw={"colonel","compound","kurzen","rebel","stockpile","stranglethorn","полковник","лагерь","курцен","повстанцы","склад","тернистая долина"},ang={["class:Hunter"]="В лагере видны грубые и жестокие попытки приручить диких тернистых пантер и тигров, превратив их в боевых зверей передовой.",["faction:Alliance"]="Экспедиция Курцена была отправлена под знаменем Альянса, поэтому падение форпоста в безумие стало постыдным скандалом, который соседние повстанцы отчаянно стремятся исправить."},sec={{t="Сердце тьмы",b="То, что начиналось как официальная экспедиция в дикие джунгли Тернистой долины, обернулось кошмаром, когда полковник Курцен лишился рассудка. Вместо выполнения задачи Штормграда гарнизон откололся от власти королевства, порвал связи с короной и скатился в тиранию. Сегодня лагерь действует как оплот наемников: здесь есть работающая лесопилка, стойла, где пойманных тернистых пантер и тигров обучают как боевых животных, и обширный пещерный комплекс под названием Склад, где отступники прячут награбленные припасы."},{t="Расколотый полк",b="Не все первоначальные члены экспедиции последовали за командиром в жестокость. Когда безумие Курцена усилилось, часть его людей подняла мятеж и бежала на запад, основав Лагерь Повстанцев, что положило начало жестокой и кровавой вражде в густых джунглях. Из своего укрепленного лагеря Курцен и его верные люди безжалостно выслеживают дезертиров и считают врагом экспедиции любого чужака, ступившего в их джунглевые владения."}},faq={{q="Кто живет в Лагере Курцена?",a="Поселение занимают отколовшиеся остатки экспедиции Курцена. Эти солдаты, бойцы джунглей и наемники подчиняются полковнику Курцену и его лейтенантам, а не законам Штормграда.",al={"who is here","kurzen soldiers","who lives in the compound","кто здесь","солдаты курцена","кто живет в лагере"}},{q="Почему здешние люди враждебны?",a="Полковник Курцен впал в безумие в глубине джунглей и отказался от верности Альянсу. Теперь он и его люди считают смертельной угрозой всех нарушителей, включая силы Альянса и дезертиров из соседнего Лагеря Повстанцев.",al={"why do they attack","kurzen hostile","are kurzen friendly","почему они нападают","курцен враждебны","дружелюбны ли люди курцена"}},{q="Что за пещера в глубине лагеря?",a="Пещерная система позади лагеря известна как Склад. Люди Курцена используют ее как укрепленный склад снабжения для хранения оружия, провизии и контрабанды вдали от джунглевых мародеров и набегов повстанцев.",al={"cave in kurzen compound","the stockpile","kurzen cave","пещера в лагере курцена","склад","пещера курцена"}},{q="Почему здесь есть тигры и пантеры в клетках?",a="Бойцы ловят местных тернистых тигров и пантер и держат их у стойл. Из этих хищников они выращивают свирепых боевых пантер и боевых тигров Курцена, которые защищают лагерь и патрулируют окрестные джунгли.",al={"kurzen animals","caged panthers","war tigers","звери курцена","пантеры в клетках","боевые тигры"}}},fp="17,311,17.583.0,18.424.0,31.204.0,32.243.0,41.200.0,45.226.0"}
P.entries["subzone:lake-al-ameth"] = {n="Озеро Аль'Амет",s="Озеро Аль'Амет — одно из крупнейших пресных водоемов, расположенных высоко в ветвях Тельдрассила, к югу от Доланаара. Некогда это было тихое убежище с одним лишь простым деревянным причалом, но теперь его берега стали опасными из-за яростного возбуждения местных растений.",h="Озеро Аль'Амет — одно из крупнейших пресных водоемов, расположенных высоко в ветвях Тельдрассила, к югу от...",kw={"dolanaar","kaldorei","lake al'ameth","oakenscowl","teldrassil","timberling","timberling seeds","доланаар","кальдораи","озеро аль'амет","дубохмур","тельдрассил","древолюд","семена древолюда"},ang={["class:Druid"]="Дикие древолюды вокруг озера дают друидам возможность на практике изучить неестественную порчу, разрушающую флору и фауну Тельдрассила.",["race:NightElf"]="Для кальдораев Доланаара Озеро Аль'Амет — тревожный признак недугов, поражающих их недавно взращенный дом, и молодым защитникам приходится охранять окрестную дорогу."},sec={{t="Неспокойный берег",b="Озеро Аль'Амет лежит сразу к югу от деревни Доланаар и служит важным природным бассейном в сердце Тельдрассила. Несмотря на безмятежные воды и малочисленные постройки, покоя здесь больше нет. Стаи разъяренных древолюдов и их отростков бродят у кромки воды, обезумев от неестественной болезни, распространяющейся по мировому древу. Друиды и исследователи из Доланаара часто отправляют путников на эти берега собирать семена и истреблять агрессивных существ, пока порча не проникла глубже в окружающий лес."},{t="Корни гнева",b="Враждебность вокруг Озера Аль'Амет напрямую связана с утратой равновесия лесными духами. В ближайших рощах таятся огромные, оскверненные древни, как Дубохмур, а обычные древолюды набрасываются на всякого, кто приблизится. Для Круга Кенария диагностика и лечение гнили вокруг Озера Аль'Амет — срочная проверка того, сможет ли Тельдрассил, лишенный благословения, действительно устоять."}},faq={{q="Где находится Озеро Аль'Амет?",a="Озеро Аль'Амет лежит прямо к югу от поселения ночных эльфов Доланаар в восточной части Тельдрассила.",al={"lake alameth location","where is lake al'ameth","find lake al'ameth","озеро аль'амет расположение","где озеро аль'амет","найти озеро аль'амет"}},{q="Почему существа вокруг Озера Аль'Амет враждебны?",a="Древесные существа и растения на берегах стали жертвами порчи, поражающей Тельдрассил, и ранее безобидные лесные спригганы и древни впали в территориальную ярость.",al={"why timberlings angry","lake alameth enemies","aggressive timberlings","почему древолюды злые","враги озера аль'амет","агрессивные древолюды"}},{q="Какие постройки и ориентиры есть на озере?",a="Озеро в основном дикое и необжитое: на его северном берегу возле тропы из Доланаара есть лишь простой деревянный рыбацкий причал.",al={"lake alameth pier","dock at lake alameth","озеро аль'амет причал","пристань озеро аль'амет"}},{q="Кто такой Дубохмур?",a="Дубохмур — могучий оскверненный древень, затаившийся возле рощ Озера Аль'Амет. Он воплощает яростную гниль, искажающую лесных существ в этих местах.",al={"what is oakenscowl","oakenscowl lake al'ameth","что такое дубохмур","дубохмур озеро аль'амет"}}},fp="13,291,20.551.0,18.386.0,31.96.0,51.198.0,45.136.0,18.173.0"}
P.entries["subzone:lake-elune-ara"] = {n="Озеро Элуне'ара",s="Озеро Элуне'ара — мерцающий священный водоем в сердце Лунной поляны. Озеро, чтящее Богиню Луны Элуну, служит для Круга Кенария местом духовных размышлений, но на его темном дне покоится спящий оскверненный полубог Омен.",h="Озеро Элуне'ара — мерцающий священный водоем в сердце Лунной поляны.",kw={"cenarion circle","dark waters","elune","lake elune'ara","moonglade","nighthaven","omen","круг кенария","темные воды","элуна","озеро элуне'ара","лунная поляна","ночная гавань","омен"},ang={["class:Druid"]="Озеро — важное место друидских ритуалов и испытаний; в его глубоких водах хранятся священные реликвии, помогающие посвященным на их пути.",["race:NightElf"]="Названное в честь Элуны, озеро представляет собой место божественного покоя и историческую память о Войне Древних."},sec={{t="Сердце священной долины",b="Озеро Элуне'ара, окруженное залитыми лунным светом рощами Лунной поляны, обладает безмятежными водами, которые, как говорят, благословила сама Белая Госпожа. Озеро находится в духовном центре друидского убежища, к северу от него лежит Ночная Гавань, а рядом — святилища Круга Кенария. Посвященные издавна погружаются в его спокойные глубины за давно потерянными реликвиями, настраиваясь на течения природы в поисках гармонии с землей."},{t="Сон Омена",b="Несмотря на спокойствие на поверхности, под мягкой рябью таится древняя опасность. Вековые легенды повествуют о двуглавом волке-полубоге Омене, почитаемом древне, оскверненном Пылающим Легионом во время Войны Древних. Побежденный и низвергнутый в озерное дно давным-давно, Омен спит глубоко под темными водами как неизменное напоминание о ранах природы."}},faq={{q="Что такое Озеро Элуне'ара?",a="Это большое священное озеро в центре Лунной поляны. Ночные эльфы и друиды чтят его; оно названо в честь Богини Луны Элуны и окружено святилищами Круга Кенария.",al={"lake eluneara","moonglade lake","where is lake eluneara","озеро элуне'ара","озеро лунной поляны","где озеро элуне'ара"}},{q="Что скрывается на дне озера?",a="В темных глубинах озера спит павший полубог Омен. Некогда благородный древень, он был сведен с ума Пылающим Легионом во время древней войны и низвергнут в озеро после поражения.",al={"what is inside lake elune'ara","omen in moonglade","monster in lake","что в озере элуне'ара","омен в лунной поляне","чудовище в озере"}},{q="Почему друиды приходят к этому озеру?",a="Озеро тесно связано с друидскими испытаниями и общением с духами природы. Молодые друиды часто ныряют в его воды в поисках священных реликвий в рамках обрядов посвящения.",al={"druid quest lake","aquatic form lake","задание друида озеро","водная форма озеро"}}},fp="14,278,24.429.0,19.359.0,23.198.0,37.187.0,32.192.0"}
P.entries["subzone:lake-falathim"] = {n="Озеро Фалатим",s="Озеро Фалатим — тихое озеро среди лесистых холмов западной части Ясеневого леса, к юго-западу от Заставы Мейстры. Его воды день и ночь постоянно освещены лунным светом Элуны, и когда-то оно было любимым местом отдыха ночных эльфов. Однако в последнее время агрессивные мурлоки заполонили его берега, превратив священное убежище в опасное место.",h="Озеро Фалатим — тихое озеро среди лесистых холмов западной части Ясеневого леса, к юго-западу от Заставы...",kw={"ashenvale","elune","falathim","lake falathim","maestra's post","moonlight","murloc","teronis","ясеневый лес","элуна","фалатим","озеро фалатим","застава мейстры","лунный свет","мурлок","теронис"},ang={["faction:Alliance"]="Разведчики Альянса из Заставы Мейстры внимательно следят за Озером Фалатим, опасаясь набегов мурлоков и пытаясь узнать о пропавших учених вроде Терониса.",["race:NightElf"]="Для кальдораев Озеро Фалатим — напоминание о священной природе, находящейся под угрозой: идиллическое озеро, постоянно освещенное лунным светом Элуны, оскверняют дикие племена мурлоков."},sec={{t="Омытое лунным светом",b="Озеро Фалатим, скрытое к юго-востоку от Зорамского взморья, издавна ценилось кальдорай как мирное место для купания и рыбалки. По местным преданиям, мягкое сияние Элуны покоится на этих водах в любое время суток. Несмотря на это священное благословение, свирепые мурлоки хлынули вглубь суши и захватили берега: они гнездятся там во множестве и прогоняют как местных путников, так и ученых."},{t="Исчезновение ученого",b="Внезапное вторжение мурлоков сделало озеро смертельно опасным для одиноких странников. Ученый-ночной эльф Теронис недавно пропал где-то у кромки воды, отправившись туда с целью исследования. Учитывая дикую враждебность земноводных, затаившихся на берегах и на мелководье, Часовые опасаются худшего для всякого, кто в одиночку отправится к освещенному луной водоему."}},faq={{q="Где находится Озеро Фалатим?",a="Озеро Фалатим лежит в западной части Ясеневого леса, среди холмов к юго-западу от Заставы Мейстры и к юго-востоку от Зорамского взморья.",al={"lake falathim location","where is lake falathim","find lake falathim","озеро фалатим где находится","где озеро фалатим","найти озеро фалатим"}},{q="Чем Озеро Фалатим особенно для ночных эльфов?",a="Озеро имеет духовное значение, потому что лунный свет богини Элуны, как считается, вечно касается его вод — днем и ночью. Исторически ночные эльфы приходили на его тихие берега, чтобы ловить рыбу и купаться.",al={"why is lake falathim important","lake falathim lore","moonlight lake ashenvale","чем важно озеро фалатим","предания озера фалатим","лунное озеро ясеневый лес"}},{q="Какие существа обитают в озере?",a="Озеро заполонили враждебные мурлоки, пришедшие из ближних прибрежных областей, из-за чего берег опасен для путников.",al={"lake falathim mobs","what is at lake falathim","lake falathim monsters","озеро фалатим монстры","кто на озере фалатим","существа озера фалатим"}},{q="Кем был Теронис?",a="Теронис — ученый-ночной эльф, отправившийся к Озеру Фалатим и пропавший; его исчезновение приписывают свирепым мурлокам, обитающим в этой местности.",al={"teronis lake falathim","who is teronis","missing scholar lake falathim","теронис озеро фалатим","кто такой теронис","пропавший ученый озеро фалатим"}}},fp="13,369,19.413.0,27.352.0,31.125.0,48.215.0,32.146.0,16.163.0"}
P.entries["subzone:lake-kel-theril"] = {n="Озеро Кел'Терил",s="Озеро Кел'Терил — обширное замерзшее озеро в самом сердце Зимних Ключей. На его скованных льдом берегах стоят древние руины кальдорай, населенные неупокоенными духами, оставшимися там со времен Великого Раскола.",h="Озеро Кел'Терил — обширное замерзшее озеро в самом сердце Зимних Ключей.",kw={"highborne","kel'theril","lake kel'theril","ruins of kel'theril","specters","winterspring","высокорожденные","кел'терил","озеро кел'терил","руины кел'терила","привидения","зимние ключи"},ang={["race:NightElf"]="Трагические привидения, бродящие у Озера Кел'Терил, служат жутким напоминанием о разрушении, вызванном безрассудной надменностью древних высокорожденных."},sec={{t="Ледяная гробница высокорожденных",b="Озеро Кел'Терил окутано вечным холодом, его воды скрыты под толстым слоем льда. На его поверхности и заснеженных берегах разбросаны разбитые колонны и арки древней эльфийской архитектуры. Это остатки Кел'Терила, когда-то форпоста древней цивилизации высокорожденных, до того как Великий Раскол разрушил Калимдор. Вместо упокоения в смерти духи павшей аристократии блуждают по льду как измученные призраки и привидения, навеки привязанные к печальным останкам своего былого величия."}},faq={{q="Почему озеро населено призраками ночных эльфов?",a="Духи, блуждающие у Озера Кел'Терил, — измученные призраки древних высокорожденных. Когда десять тысяч лет назад Великий Раскол разорвал Калимдор, катастрофический крах их цивилизации оставил их души привязанными к ледяным руинам прежнего поселения.",al={"lake keltheril ghosts","why are there spirits here","winterspring lake ghosts","призраки озера кел'терил","почему здесь духи","призраки озера зимние ключи"}},{q="Какие руины стоят на берегах озера?",a="Рушащиеся колонны и каменная кладка принадлежат Руинам Кел'Терила — древнему поселению кальдорай, процветавшему во времена владычества высокорожденных, до Войны Древних.",al={"ruins in the lake","what are the keltheril ruins","руины в озере","что за руины кел'терила"}}},fp="15,206,30.526.0,39.269.0,41.182.0"}
P.entries["subzone:lake-mennar"] = {n="Озеро Меннар",s="Озеро Меннар — тихое пресное озеро среди разрушенных руин Азшары. Оно известно как одно из крайне редких мест за пределами Нордскола, где обитают представители синего драконьего рода. Хотя по краям озера множество охраняющих синих дракончиков, сами его берега на удивление спокойны.",h="Озеро Меннар — тихое пресное озеро среди разрушенных руин Азшары.",kw={"azshara","azuregos","blue dragonflight","dragonspawn","lake mennar","mazthoril","whelps","азшара","азурегос","синий драконий род","дракончики","озеро меннар","маззорил"},ang={["class:Mage"]="Как хранители тайных энергий мира, синие драконы, охраняющие Озеро Меннар, делают эту котловину местом большого интереса и осторожности для практиков тайной магии."},sec={{t="Убежище синего драконьего рода",b="Озеро Меннар расположено среди древних разрушенных земель Азшары и служит уединенным местом сбора синего драконьего рода. Если не считать Маззорила на севере в Зимних Ключах, встретить синих драконов в таком числе в Калимдоре почти невозможно. Синие дракониды неустанно патрулируют хребты и подступы вокруг котловины, яростно охраняя воды. Но для любого странника, достаточно смелого, чтобы проскользнуть через это бдительное кольцо стражей, спокойные воды озера дарят неожиданную тишину, защищенную от волшебных потрясений и бродячих стай зверей, обычных для остальной части полуострова."}},faq={{q="Почему у Озера Меннар есть синие драконы?",a="Озеро Меннар имеет особое тихое значение для синего драконьего рода и является одним из немногих мест его сбора в Калимдоре, не считая Маззорила в Зимних Ключах. Дракончики бдительно патрулируют окрестности, охраняя котловину и не подпуская чужаков к своему потомству.",al={"why blue dragons here","who lives at lake mennar","blue dragonflight lake mennar","почему здесь синие драконы","кто живет у озера меннар","синий драконий род озеро меннар"}},{q="Опасно ли посещать Озеро Меннар?",a="Окрестные гребни и подходы усиленно патрулируют агрессивные синие драконы и дракончики. Однако вода и ближайший берег внутри котловины на удивление спокойны, если вам удастся проскользнуть мимо внешнего кольца стражей.",al={"is lake mennar safe","enemies at lake mennar","безопасно ли озеро меннар","враги у озера меннар"}},{q="Как Озеро Меннар связано с другими гнездовьями синих драконов?",a="На континенте Калимдор Озеро Меннар и Маззорил в Зимних Ключах — основные известные территории, за которыми присматривает синий драконий род. Оба места — редкие форпосты далеко к югу от исконной родины их рода в Нордсколе.",al={"connection to mazthoril","lake mennar winterspring","связь с маззорилом","озеро меннар зимние ключи"}}},fp="11,338,37.610.0,42.284.0,34.239.0,57.234.0"}
P.entries["subzone:lake-mereldar"] = {n="Озеро Мерельдар",s="Озеро Мерельдар — обширный зараженный водоем к югу от Перекрестка Корина в Восточных Чумных землях. Когда-то часть идиллической сельской глубинки Лордерона, его оскверненные воды теперь порождают искаженных элементалей и гниют под не рассеявшейся порчей Плети.",h="Озеро Мерельдар — обширный зараженный водоем к югу от Перекрестка Корина в Восточных Чумных землях.",kw={"blighted surge","corin's crossing","eastern plaguelands","elementals","ferry","lake mereldar","plague ravager","оскверненный прилив","перекресток корина","восточные чумные земли","элементали","паром","озеро мерельдар","чумной опустошитель"},ang={["class:Shaman"]="Существование оскверненных приливов в Озере Мерельдар — мрачное свидетельство того, как гнусная магия Плети искажает даже природных духов стихий, превращая их в безумных свирепых чудовищ."},sec={{t="Отравленное убежище",b="Озеро Мерельдар, лежащее к югу от городка Перекресток Корина, когда-то было мирной частью сельской местности северного Лордерона. По его берегам разбросаны разлагающиеся руины старой усадьбы, заброшенная лачуга и ветхий паром, возивший местных фермеров и путников по спокойным водам. С приходом Плети и чумы нежизни озеро полностью погибло. Окрестная почва засохла, а воды стали гнилыми и ядовитыми."},{t="Искаженные обитатели",b="Неестественная порча, просочившаяся в Озеро Мерельдар, полностью заразила местную экосистему и связанных с ней духов. Оскверненные приливы — испорченные водные элементали, сведенные с ума остатками некромантии, — таятся на мелководье и внезапно всплывают. На заросших водорослями берегах по грязи бродят свирепые звери, такие как чумные опустошители, охотящиеся на любых живых существ, подошедших слишком близко к мертвому берегу."}},faq={{q="Где находится Озеро Мерельдар?",a="Озеро Мерельдар лежит в центрально-южной части Восточных Чумных земель, прямо к югу от разрушенного городка Перекресток Корина.",al={"mereldar location","where is lake mereldar","find lake mereldar","озеро мерельдар где находится","где озеро мерельдар","найти озеро мерельдар"}},{q="Почему в озере есть водные элементали?",a="Здешние водные элементали, известные как оскверненные приливы, были искажены и стали враждебными из-за всепроникающей некромантической порчи, просочившейся в озеро во время падения Лордерона.",al={"blighted surge","water elementals mereldar","corrupted elementals","оскверненный прилив","водные элементали мерельдар","оскверненные элементали"}},{q="Кому принадлежали лачуга и паром на берегу?",a="Они принадлежали местной фермерской усадьбе, основанной до Третьей войны. Когда чума опустошила Восточный Предел, обитатели усадьбы погибли или бежали, оставив дом и паром гнить.",al={"ferry ruins","mereldar house","abandoned dock","руины парома","дом мерельдар","заброшенная пристань"}},{q="Безопасно ли пить воду или плавать в ней?",a="Нет. Озеро сильно загрязнено чумой нежизни, поэтому пить воду, плавать или собирать в ней ресурсы опасно, а в ее водах обитают агрессивные зараженные существа.",al={"can you drink the water","is lake mereldar poisoned","можно ли пить воду","отравлено ли озеро мерельдар"}}},fp="13,275,16.486.0,19.409.0,31.133.0,43.181.0,43.188.0,38.166.0"}
P.entries["subzone:lake-nazferiti"] = {n="Озеро Назферити",s="Озеро Назферити — обширное пресное озеро в густых джунглях северной части Тернистой долины. Его питает большая речная система, тянущаяся далеко на север в горы; в его водах кишат свирепые кроколиски и хищные бешеные рыбы, а на берегах расположен промышленный лагерь гоблинов Торговой Компании.",h="Озеро Назферити — обширное пресное озеро в густых джунглях северной части Тернистой долины.",kw={"crocolisks","frenzies","lake nazferiti","nazferiti","river","stranglethorn vale","venture company","кроколиски","бешеные рыбы","озеро назферити","назферити","река","тернистая долина","торговая компания"},ang={["class:Hunter"]="Берега и глубины Озера Назферити богаты дичью — от агрессивных речных зверей до опасных кроколисков, затаившихся в камышах.",["race:NightElf"]="Промышленные шрамы, оставленные Торговой Компанией у Озера Назферити, показывают, какое чудовищное разорение природе приносит безудержная гоблинская алчность."},sec={{t="Сердце водного пути джунглей",b="Озеро Назферити лежит на реке Назферити — одной из самых длинных непрерывных водных артерий юга Восточных королевств. Река берет начало глубоко в северных высотах, низвергаясь водопадами с Красногорья, и, возможно, начинается еще дальше вглубь суши, у Перевала Мертвого Ветра. В Тернистой долине вода разливается в мутное озеро, где кишат свирепые хищники — речные бешеные рыбы и кроколиски, охотящиеся из засады, — из-за которых даже простое купание смертельно опасно."},{t="Вторжение Торговой Компании",b="Природному равновесию Озера Назферити угрожают гоблины Торговой Компании. Развернув масштабные работы на берегах озера, эти безжалостные барыги истощают лес и ресурсы джунглей с помощью механических пил, буров и бригад лесорубов. Их обширная база загрязняет воды и постоянно сталкивается с местной фауной и бродячими охотниками, отважившимися зайти в долину."}},faq={{q="Откуда Озеро Назферити берет воду?",a="Озеро питает река Назферити — обширная речная сеть, берущая начало высоко в северных горах. Ее подтвержденный исток — водопад, низвергающийся с Красногорья, а неподтвержденные верховья простираются вглубь суши до скал Перевала Мертвого Ветра.",al={"nazferiti river source","where does lake nazferiti come from","water source lake nazferiti","исток реки назферити","откуда берется озеро назферити","источник воды озера назферити"}},{q="Кто контролирует берега Озера Назферити?",a="Торговая Компания, которой управляют гоблины, занимает крупную базу на границах озера. Опираясь на нее, она вырубает окрестные джунгли и добывает ресурсы, размещая вооруженных надсмотрщиков и гоблинские механизмы у кромки воды.",al={"who is at lake nazferiti","goblins at lake nazferiti","venture co lake","кто на озере назферити","гоблины на озере назферити","торговая компания озеро"}},{q="Безопасно ли плавать в Озере Назферити?",a="Плавать в озере опасно. В мутных водах обитают стаи агрессивных речных бешеных рыб и притаившиеся кроколиски, которые быстро нападают на каждого, кто отходит от мелководья.",al={"lake nazferiti monsters","what lives in lake nazferiti","creatures in lake nazferiti","монстры озера назферити","кто живет в озере назферити","существа озера назферити"}},{q="Где находится Озеро Назферити?",a="Озеро Назферити расположено в северной части Тернистой долины, к югу от границы с Сумеречным лесом и к западу от руин Зул'Гуруба, вдоль главной речной магистрали.",al={"lake nazferiti location","where is lake nazferiti","find lake nazferiti","озеро назферити где находится","где озеро назферити","найти озеро назферити"}}},fp="14,333,28.480.0,28.393.0,40.270.0,42.234.0,37.178.0,32.159.0"}
P.entries["subzone:lakeridge-highway"] = {n="Озерный тракт",s="Озерный тракт — старая дорога, проходящая вдоль южного берега Озера Безмолвия в Красногорье. До Первой войны это была важная и оживленная артерия, но теперь она пришла в упадок и заброшена. Сегодня бродячие стаи гноллов и орки клана Черной горы делают путь по дороге опасным для путников.",h="Озерный тракт — старая дорога, проходящая вдоль южного берега Озера Безмолвия в Красногорье.",kw={"gnolls","highway","lake everstill","lakeridge","redridge","road","stonewatch","гноллы","тракт","озеро безмолвия","озерный тракт","красногорье","дорога","каменная стража"},ang={["faction:Alliance"]="Тракт — наглядное напоминание о заброшенных рубежах Штормграда: местные дороги сразу за Приозерьем из-за нехватки подкреплений отданы гноллам и оркам."},sec={{t="Павшая артерия",b="До разорения Первой войны Озерный тракт был оживленным торговым путем через Красногорье, по которому перевозили товары и путешествовали люди вдоль южных берегов Озера Безмолвия. В те мирные дни путники могли ходить между поселениями в долине и восточными возвышенностями под защитой Королевства Штормград. Эта безопасность исчезла, когда через область прошла Орда, оставив восточное Красногорье спорным и опустошенным."},{t="Опасность на дороге",b="После захвата Крепости Каменной Стражи орками клана Черной горы обслуживание и патрули вдоль тракта прекратились полностью. Дорога быстро превратилась в заросшую тропу, за которую борются свирепые стаи гноллов. Поскольку войска Штормграда разбросаны и не могут усилить Приозерье, тракт официально остается небезопасным. Любому путнику, желающему добраться до восточных хребтов, теперь приходится прорубать путь через засады гноллов."}},faq={{q="Куда ведет Озерный тракт?",a="Дорога тянется вдоль южного края Озера Безмолвия и идет на восток от окрестностей Приозерья к предгорьям вокруг Крепости Каменной Стражи и восточным горам Красногорья.",al={"where does lakeridge highway go","lakeridge highway path","where is lakeridge highway","куда ведет озерный тракт","путь озерного тракта","где находится озерный тракт"}},{q="Почему тракт заброшен?",a="Тракт пришел в упадок после Первой войны, особенно когда орки клана Черной горы укрепили Крепость Каменной Стражи. Без людей для охраны дороги Штормград не мог ее содержать, и враждебные гноллы заняли ее и перекрыли путь мирным жителям.",al={"why is it abandoned","why is lakeridge highway empty","lakeridge highway fallen into disuse","почему он заброшен","почему озерный тракт пуст","озерный тракт в запустении"}},{q="Какие угрозы бродят по дороге сегодня?",a="Тракт населяют в основном агрессивные гноллы, нападающие из засады на всех, кто отходит от Приозерья, а также оставшиеся разведчики орков клана Черной горы из восточных оплотов.",al={"dangers on lakeridge highway","mobs on lakeridge highway","who controls lakeridge highway","опасности на озерном тракте","монстры на озерном тракте","кто контролирует озерный тракт"}},{q="Был ли тракт опасным всегда?",a="Нет. В мирную эпоху до Первой войны Озерный тракт был хорошо содержимым, оживленным путем, который безопасно связывал сердце Красногорья с его восточными форпостами.",al={"lakeridge highway history","highway before the war","история озерного тракта","тракт до войны"}}},fp="17,320,15.451.0,17.420.0,38.189.0,29.249.0,35.187.0,33.181.0"}
P.entries["subzone:lakeshire-inn"] = {n="Таверна Приозерья",s="Таверна Приозерья — центр общения и главное убежище в осажденном городе Приозерье. Расположенная в сердце Красногорья, она дарит тепло, эль и безопасный ночлег местным жителям и усталым путникам, сталкивающимся с окрестными опасностями.",h="Таверна Приозерья — центр общения и главное убежище в осажденном городе Приозерье.",kw={"barkeep daniels","darcy parker","innkeeper brianna","lake everstill","lakeshire inn","redridge inn","wiley the black","yorus barleybrew","кабатчик дэниэлс","дарси паркер","трактирщица брианна","озеро безмолвия","таверна приозерья","таверна красногорья","вилли черный","йорус ячменовар"},ang={["faction:Alliance"]="Таверна Приозерья — незаменимый оплот гостеприимства Альянса, место сбора для всех, кто сражается за защиту уязвимого восточного фланга Штормграда.",["profession:Cooking"]="Общий зал — оживленное место, где в горах можно купить основные продукты, местные рецепты и свежие напитки у Кабатчика Дэниэлса."},sec={{t="Островок тепла",b="Стоя на берегу Озера Безмолвия, Таверна Приозерья дарит краткую передышку от банд гноллов и орков клана Черной горы, теснящих город. Несмотря на все более отчаянное военное положение Приозерья, в таверне сохраняется уютная и оживленная атмосфера. Кабатчик Дэниэлс и трактирщица Брианна обслуживают местных и путников, подавая кружки эля, вино и горячие блюда. Это важное место встреч, где горожане обмениваются новостями, топят горе и ищут наемников для защиты восточной границы королевства."},{t="Посетители и слухи",b="Помимо обычных посетителей, потягивающих напитки у стойки, в таверну заходят самые разные колоритные личности. Вилли Черный наблюдает за залом из-за стола, храня свои мысли при себе и следя за опасностями в регионе. Странствующие пивовары вроде Йоруса Ячменовара останавливаются здесь, а Дарси Паркер и другие горожане часто бывают в общем зале. Для искателей приключений, отправляющихся в зубчатые горы или на юг, в Сумеречный лес, таверна — последний оплот цивилизации и безопасности перед спорными дикими землями."}},faq={{q="Какие услуги предоставляет Таверна Приозерья?",a="Таверна служит главным местом отдыха в Красногорье. Трактирщица Брианна привязывает камни возвращения и сдает комнаты усталым путникам, а Кабатчик Дэниэлс предлагает закуски, еду и напитки в дорогу.",al={"lakeshire inn services","what can I do at lakeshire inn","innkeeper lakeshire","услуги таверны приозерья","что можно делать в таверне приозерья","трактирщик приозерья"}},{q="Почему в таверне так многолюдно, несмотря на близкие нападения?",a="Поскольку орки клана Черной горы спускаются с северных скал, а гноллы грабят местные фермы, горожане и беженцы ищут безопасности в центре города. Таверна дает и физический кров, и место, где можно обменяться новостями об обороне.",al={"why is lakeshire inn full","lakeshire refugees inn","redridge tavern crowd","почему таверна приозерья полна","беженцы в таверне приозерья","толпа в таверне красногорья"}},{q="Кто такой Вилли Черный?",a="Вилли Черный — мрачный местный житель, сидящий в таверне. Он внимательно следит за угрозами Приозерью и делится сведениями и поручениями со способными искателями приключений, готовыми отразить натиск врага в Красногорье.",al={"wiley the black","guy in lakeshire tavern","wiley npc","вилли черный","человек в таверне приозерья","вилли"}},{q="Где в Приозерье находится таверна?",a="Таверна стоит у западного въезда в Приозерье на северном берегу Озера Безмолвия, недалеко от главной дороги, ведущей в город из Элвиннского леса.",al={"where is lakeshire inn","lakeshire tavern location","find lakeshire inn","где таверна приозерья","расположение таверны приозерья","найти таверну приозерья"}}},fp="13,263,18.532.0,20.514.0,45.203.0,53.255.0,23.229.0,42.161.0"}
P.entries["subzone:lakeshire-town-hall"] = {n="Ратуша Приозерья",s="Ратуша Приозерья — административный центр Красногорья, стоящий в сердце прибрежного поселения. Внутри Мировой судья Соломон руководит местным управлением, борясь с непрерывными угрозами орков клана Черной горы и гноллов.",h="Ратуша Приозерья — административный центр Красногорья, стоящий в сердце прибрежного поселения.",kw={"blackrock","gnolls","lakeshire","magistrate solomon","redridge","redridge mountains","stormwind","town hall","черная гора","гноллы","приозерье","мировой судья соломон","красногорье","штормград","ратуша"},ang={["faction:Alliance"]="Ратуша Приозерья — восточный рубеж Альянса в Красногорье, осажденный форпост, отчаянно удерживающий линию без королевской поддержки Штормграда.",["race:Human"]="Для людей Штормграда эта обновленная ратуша отражает и непреклонный дух сельских поселений, и горькое чувство брошенности, которое испытывают местные управители, когда столица закрывает глаза."},sec={{t="Центр управления Красногорьем",b="Ратуша Приозерья — старое каменное здание, которое не раз старательно обновляли. Она заметно расположена в Приозерье, и в ней находится Мировой судья Соломон, добрый и преданный гражданский руководитель, отвечающий за порядок на восточных рубежах Королевства Штормград. Поскольку военные ресурсы Штормграда истощены, а королевской помощи мало, ратуша из тихой канцелярии превратилась в действующий командный центр, где ежедневно обрабатываются отчаянные призывы к добровольным защитникам и наемникам."},{t="В осаде и в смятении",b="Набеги гноллов и наступление орков Черной Горы довели Соломона до отчаяния. Помощи мало, и магистрат охотно принимает помощь независимых искателей приключений, заходящих в двери ратуши."}},faq={{q="Кто главный в Ратуше Приозерья?",a="Ратушей руководит Мировой судья Соломон. Это добрый и благонамеренный администратор, главная управляющая власть Приозерья и окрестной долины Красногорья.",al={"who leads lakeshire","magistrate solomon","who is in town hall","кто управляет приозерьем","мировой судья соломон","кто в ратуше"}},{q="Почему ратуша ищет столько помощи извне?",a="Приозерью угрожают серьезные и растущие опасности от местных стай гноллов и враждебных отрядов орков клана Черной горы. Поскольку Штормград прислал минимум подкреплений, Мировому судье Соломону приходится нанимать проходящих искателей приключений для защиты региона.",al={"why does solomon need help","lakeshire problems","why are there so many quests here","зачем соломону помощь","проблемы приозерья","почему здесь так много заданий"}},{q="Почему Соломон принимает помощь путников?",a="Проблемы города с гноллами и орками Черной Горы поставили Соломона в отчаянное положение. Он охотно принимает помощь искателей приключений.",al={"why does solomon accept aid","lakeshire adventurers","town hall help","почему соломон принимает помощь","приключенцы приозерья","помощь ратуше"}},{q="Давно ли стоит Ратуша Приозерья?",a="Да, это старое здание, пережившее неспокойные десятилетия и прошедшее старательный ремонт и обновление, чтобы продолжать служить гражданским центром Красногорья.",al={"town hall age","how old is lakeshire town hall","town hall history","возраст ратуши","как стара ратуша приозерья","история ратуши"}}},fp="19,255,27.550.0,27.207.0,40.183.0,50.234.0,44.141.0,46.170.0"}
P.entries["subzone:land-s-end-beach"] = {n="Пляж на Краю Света",s="Пляж на Краю Света — безлюдный участок побережья на самой южной оконечности Танариса, фактически отмечающий южный край Калимдора. Защищенный высокими горными хребтами и бескрайними водами океана, он остается одним из самых уединенных и недоступных берегов континента.",h="Пляж на Краю Света — безлюдный участок побережья на самой южной оконечности Танариса, фактически отмечающий...",kw={"beach","coast","kalimdor","land's end beach","shore","south seas","tanaris","uldum","пляж","побережье","калимдор","пляж на краю света","берег","южные моря","танарис","ульдум"},sec={{t="Край мира",b="Скрытый за южными горами Танариса и запечатанными титанскими вратами Ульдума, Пляж на Краю Света представляет собой самый южный край материка Калимдора. Он отрезан от сухопутных путей через пустынные дюны, и добраться до этого обдуваемого ветрами берега можно, лишь проплыв по опасным, изнуряющим открытым водам Южных морей. Пляж — бесплодный рубеж бьющего прибоя, зыбучего песка и тихого уединения, почти не тронутый картелями и исследователями пустыни, которые обитают севернее, вокруг Прибамбасска."},{t="Тайны за линией прибоя",b="За полосой прибоя лежат одинокие безымянные островки, отделенные от материка обширными изнурительными глубокими водами. Добраться до этих далеких каменных крупиц достаточно опасно, чтобы довести до предела даже опытных пловцов. Мало кто из смертных имеет причину искать одинокие воды на краю Калимдора, поэтому пляж и окружающие его отмели остаются нетронутыми под палящим южным солнцем."}},faq={{q="Где находится Пляж на Краю Света?",a="Пляж на Краю Света находится на самом южном побережье Танариса, прямо к югу от гор, которые закрывают древние титанские врата Ульдума на крайнем юге Калимдора.",al={"where is lands end beach","lands end beach location","how to find lands end beach","где пляж на краю света","расположение пляжа на краю света","как найти пляж на краю света"}},{q="Как добраться до Пляжа на Краю Света?",a="Поскольку огромные горные хребты преграждают путь по суше из глубины пустыни, путникам обычно приходится плыть вдоль южного побережья от восточного Танариса или огибать опасные открытые воды, стараясь не поддаться усталости в глубоком море.",al={"how do i get to lands end beach","get to lands end tanaris","reach lands end","как добраться до пляжа на краю света","пляж на краю света танарис","дойти до края света"}},{q="Что находится на островах у берега пляжа?",a="Отдаленные безымянные острова лежат далеко от берега за широким проливом глубокого, изнуряющего океана. Это пустынные скалистые косы, которых достигали и исследовали лишь очень немногие путники.",al={"unnamed islands lands end","offshore islands tanaris","islands near lands end","безымянные острова край света","острова у берега танариса","острова у края света"}},{q="Живет ли кто-нибудь на Пляже на Краю Света?",a="На берегу нет крупных поселений. Отрезанный от торговли и цивилизации, он остается бесплодным природным побережьем, продуваемым океанскими ветрами.",al={"who lives at lands end","lands end beach inhabitants","is anyone at lands end","кто живет на краю света","жители пляжа на краю света","есть ли кто на краю света"}}},fp="16,276,21.525.0,18.420.0,34.184.0,34.261.0,50.189.0,37.154.0"}
P.entries["subzone:lariss-pavilion"] = {n="Павильон Лорисс",s="Павильон Лорисс — древнее эльфийское строение в глуши Фераласа, к северу от Лагеря Мохаче. Когда-то это было тихое убежище в классической архитектуре ночных эльфов, но окружающий лес стал опасен из-за порченых дриад, а изгнанный маг-высокорожденный выжидает в его тени.",h="Павильон Лорисс — древнее эльфийское строение в глуши Фераласа, к северу от Лагеря Мохаче.",kw={"azj'tordin","camp mojache","dire maul","dryads","feralas","highborne","lariss pavilion","pusillin","xerash fireblade","азж'тордин","лагерь мохаче","забытый город","дриады","фералас","высокорожденные","павильон лорисс","пузиллин","зераш огненный клинок"},ang={["class:Mage"]="Для знатоков тайной магии одинокий высокорожденный Азж'Тордин — живой реликт древнего, неограниченного колдовства Эльдре'Таласа.",["race:NightElf"]="Ночным эльфам павильон покажется горьким зрелищем: его красота затенена наследием гордыни высокорожденных, а родственные им дриады страдают от темной порчи."},sec={{t="Руины высокорожденных",b="Тихо стоя на утесах к северу от Лагеря Мохаче, Павильон Лорисс демонстрирует изящную каменную кладку и высокие арки древней империи кальдораев. В пору расцвета он принадлежал великому городу Эльдре'Талас, ныне известному как Забытый Город. Сегодня отсюда открывается защищенный вид на густой полог лесов Фераласа, но покой здесь хрупок: некогда кроткие дриады, бродящие по окрестным полянам, впали в безумие и порчу и яростно нападают на всякого, кто приблизится."},{t="Азж'Тордин и тайный проход",b="Самый известный обитатель павильона — неуловимый эльф Азж'Тордин. Порвав с развратным правлением принца Тортелдрина в Забытом Городе, Азж'Тордин бежал из руин через тайный проход, соединяющий павильон с недрами древнего города. Однако его тихое изгнание нарушено: непоседливый бес по имени Пузиллин украл его любимую книгу заклинаний, и изгнанник ищет помощи со стороны, чтобы вернуть ее."}},faq={{q="Где находится Павильон Лорисс?",a="Павильон Лорисс расположен на возвышенной лесистой местности в восточном Фераласе, к северу от аванпоста Орды — Лагеря Мохаче.",al={"lariss pavilion location","where is lariss pavilion","how to get to lariss pavilion","расположение павильона лорисс","где павильон лорисс","как добраться до павильона лорисс"}},{q="Кто такой Азж'Тордин?",a="Азж'Тордин — древний чародей-высокорожденный, бежавший от тирана принца Тортелдрина из Забытого Города. Теперь он расположился в павильоне и ищет искателей приключений, которые помогут вернуть украденную книгу заклинаний у проказливого беса.",al={"azjtordin","who is the elf at lariss pavilion","lariss pavilion quest giver","азж'тордин","кто эльф в павильоне лорисс","персонаж, выдающий задания в павильоне лорисс"}},{q="Почему дриады вокруг павильона враждебны?",a="Дриады, бродящие по лесу возле павильона, поддались порче, расползающейся по дебрям Фераласа, и обычно замкнутые хранительницы природы превратились в свирепых нападающих.",al={"angry dryads","why are dryads attacking","corrupted dryads feralas","злые дриады","почему дриады нападают","порченые дриады фералас"}},{q="Как павильон связан с Забытым Городом?",a="Скрытый черный ход у основания Павильона Лорисс ведет прямо в Забытый Город — это путь побега, которым Азж'Тордин ускользнул от своих собратьев.",al={"dire maul backdoor","dire maul shortcut","secret passage","черный ход забытого города","короткий путь в забытый город","тайный проход"}}},fp="15,312,23.484.0,33.435.0,33.129.0,18.220.0,47.190.0,43.158.0"}
P.entries["subzone:launch-bay"] = {n="Пусковая установка",s="Пусковая установка — подземный аэродром и ангар в глубинах Гномрегана, сразу за Залом Шестеренок. Некогда площадка для гномьих летательных машин и бомбардировщиков, теперь она полностью во власти враждебных лепрогномов и порченых механизмов.",h="Пусковая установка — подземный аэродром и ангар в глубинах Гномрегана, сразу за Залом Шестеренок.",kw={"bomber","dark iron","engineering labs","flying machine","gnomeregan","hangar","launch bay","leper gnome","бомбардировщик","черное железо","инженерные лаборатории","летательная машина","гномреган","ангар","пусковая установка","лепрогном"},ang={["profession:Engineering"]="Ангар демонстрирует вершину гномьей авиации и конструкций шасси, но старателям придется иметь дело с враждебными механизмами, чтобы рассмотреть их вблизи.",["race:Gnome"]="Видеть жемчужины гномьей авиации — летательные машины и бомбардировщики — брошенными и облепленными облученными прокаженными сородичами — горькое напоминание о трагической утрате города."},sec={{t="Аэродром на приколе",b="Пусковая установка — главный ангар воздушного флота Гномрегана — разделена на два яруса. Ее центральная платформа, куда ведут пандусы с верхнего перехода, до сих пор хранит гномьи летательные машины и тяжелые бомбардировщики, не успевшие вылететь до эвакуации города. Вместо опытных пилотов на летных палубах теперь кишат безумные лепрогномы, которые обслуживают и охраняют простаивающие боевые машины."},{t="Перекресток глубинного города",b="Помимо военной роли, Пусковая установка служит важным узлом комплекса. Пандусы из ее юго-восточного коридора спускаются в Инженерные лаборатории, а южный проход нижней палубы заполонили вторгшиеся дворфы Черного Железа. Этот южный туннель — опасный путь к сердцу города, Двору Механиков."}},faq={{q="Для чего использовалась Пусковая установка?",a="Она была задумана как подземный аэродром и ремонтный ангар для гномьих летательных машин и бомбардировщиков. Сегодня она заброшена и приспособлена лепрогномами, обитающими в руинах.",al={"gnomeregan hangar","what is launch bay","launch bay purpose","ангар гномрегана","что такое пусковая установка","назначение пусковой установки"}},{q="Кто сейчас контролирует Пусковую установку?",a="Верхний и нижний уровни заняты лепрогномами и агрессивными механизмами. Дальше, у южных выходов, закрепились и враждебные дворфы Черного Железа.",al={"who is in launch bay","launch bay enemies","who lives here","кто в пусковой установке","враги пусковой установки","кто здесь живет"}},{q="Куда ведет Пусковая установка?",a="Верхний восточный туннель ведет обратно в Зал Шестеренок. Юго-восточные пандусы спускаются в Инженерные лаборатории, а южный нижний туннель уходит глубже в Гномреган, к Двору Механиков.",al={"launch bay exits","how to leave launch bay","launch bay directions","выходы пусковой установки","как выйти из пусковой установки","пусковая установка маршрут"}},{q="Работают ли здешние летательные машины?",a="Несколько гномьих летательных машин и бомбардировщиков стоят на центральных платформах, но простаивают без присмотра среди хаоса падения города.",al={"can i fly the planes","flying machines gnomeregan","hangar planes","можно ли летать на самолетах","летательные машины гномрегана","самолеты в ангаре"}}},fp="10,302,19.415.0,27.339.0,32.191.0,32.198.0,31.201.0,41.149.0"}
P.entries["subzone:library-ironforge"] = {n="Библиотека (Стальгорн)",s="Библиотека, расположенная в восточном крыле Зала Исследователей, — главное хранилище исторических знаний, археологических реликвий и древних преданий Стальгорна. Ею заботливо управляет Лига исследователей: здесь собраны обширные исторические труды и редкие артефакты, найденные при раскопках по всему Азероту.",h="Библиотека, расположенная в восточном крыле Зала Исследователей, — главное хранилище исторических знаний...",kw={"books","curator thorius","explorers league","hall of explorers","ironforge","library","mae paledust","museum","книги","куратор ториус","лига исследователей","зал исследователей","стальгорн","библиотека","мэй бледнопыль","музей"},ang={["faction:Alliance"]="Библиотека — ценнейший стратегический архив для Альянса: в ней хранятся важные записи Альянса Лордерона и свидетельства очевидцев Второй и Третьей войн.",["race:Dwarf"]="Для дворфов этот зал воплощает стремление короля Магни Бронзоборода раскрыть их происхождение от Титанов: здесь хранятся сами рассказы о Пробуждении и Войне трех молотов."},sec={{t="Сердце Лиги исследователей",b="Occupying a massive chamber within the Hall of Explorers, the Library is where dwarven scholars sift through the relics and field reports recovered by adventurers across the world. Administered by the Explorers' League, the shelves are packed with foundational chronicles detailing the War of the Three Hammers, the ancient Troll Wars, and the origins of the dwarven race. Inquiries regarding rare books or archival locations are directed to Librarian Mae Paledust."},{t="Музейные экспозиции",b="За рядами плотных книжных полок библиотека служит еще и действующим музеем под руководством куратора Ториуса. Здесь изучают, сохраняют и выставляют образцы, добытые при глубоких раскопках, в заброшенных руинах и на дальних берегах. Хранители Лиги собирают все — от грубых идолов мурлоков и резных ножей до загадочных реликвий, найденных во льдах севера, — и каталогизируют каждую находку, чтобы восстановить скрытую историю Титанов и раннего Азерота."}},faq={{q="Для чего нужна Библиотека в Стальгорне?",a="Это главный исследовательский архив и музей Лиги исследователей. Ее члены приносят сюда найденные артефакты, тома и полевые записи, чтобы их каталогизировали, расшифровали и сохранили для дворфов и Альянса.",al={"ironforge library purpose","what is this place","hall of explorers library","библиотека стальгорна","что это за место","библиотека зала исследователей","зачем нужна библиотека"}},{q="Кто управляет здешними коллекциями?",a="Письменные собрания библиотеки и поиск по архивам находятся в ведении библиотекаря Мэй Бледнопыль, а музейное крыло и его исторические артефакты хранит и опекает куратор Ториус.",al={"who runs the library","ironforge librarian","museum curator","кто управляет библиотекой","библиотекарь стальгорна","хранитель музея"}},{q="Какие книги здесь можно прочесть?",a="В библиотеке хранятся основополагающие труды о древних и недавних событиях: о Древних богах, драконьих родах, войнах с троллями, Войне трех молотов, возвышении Орды и создании Альянса Лордерона.",al={"ironforge books","readable tomes","what lore is here","книги стальгорна","книги для чтения","какие предания здесь"}},{q="Где в Стальгорне находится Библиотека?",a="Библиотека занимает восточное крыло Зала Исследователей, расположенного в северо-восточной части Стальгорна.",al={"ironforge library location","how to find the library","где библиотека стальгорна","как найти библиотеку"}}},fp="19,321,30.465.0,19.470.0,48.230.0,33.202.0,36.239.0,42.115.0"}
P.entries["subzone:library-wing-tyr-s-hand"] = {n="Библиотечное крыло (Длань Тира)",s="Библиотечное крыло — уединенный зал внутри Аббатства Длани Тира, расположенный в сильно укрепленном оплоте Алого ордена в Восточных Чумных землях. Когда-то оно служило священным занятиям и размышлениям, а теперь его полки заполнены жесткими догмами и пропагандой фанатичного ордена. Члены ордена собираются здесь, чтобы изучать писания и охранять священные реликвии святилища.",h="Библиотечное крыло — уединенный зал внутри Аббатства Длани Тира, расположенный в сильно укрепленном оплоте...",kw={"abbey","eastern plaguelands","holy water","library wing","propaganda","scarlet crusade","tomes","tyr's hand","аббатство","восточные чумные земли","святая вода","библиотечное крыло","пропаганда","алый орден","тома","длань тира"},ang={["class:Paladin"]="Паладины видят в этом крыле извращение изначальных научных традиций Серебряной Длани, где преданность Свету сменилась воинственным фанатизмом.",["class:Priest"]="Для служителей Света Библиотечное крыло — горькое свидетельство того, как божественное созерцание можно исказить до узколобого экстремизма и паранойи."},sec={{t="Святилище фанатичных преданий",b="Библиотечное крыло находится у центрального нефа Аббатства Длани Тира напротив воинских помещений и отражает идейную сердцевину Алого ордена. В этих тихих каменных альковах жрецы и крестоносцы погружаются в богословские трактаты, воинственные доктрины и тексты, искаженные годами непрерывной войны с Плетью. Вместо того чтобы хранить открытое знание, здешние тексты питают паранойю ордена и укрепляют его убежденность, что все чужаки несут на себе скверну."},{t="Сосуды Света",b="Помимо собрания пристрастных свитков и писаний, Библиотечное крыло служит хранилищем священных предметов, которые оберегает жречество Алого ордена. В задних комнатах крыла крестоносцы держат освященные припасы, в том числе чаши с чистой святой водой для обрядов высших чинов. Чтобы пробиться в эти внутренние святилища, нужно одолеть элитных защитников Алого ордена, для которых библиотека — одновременно оплот веры и неприступная крепость."}},faq={{q="Где находится Библиотечное крыло?",a="Библиотечное крыло расположено внутри Аббатства Длани Тира, в анклаве Алого ордена — Длани Тира — на юго-востоке Восточных Чумных земель. Внутри аббатства оно находится к югу от главного входного зала, напротив Зала Оружия.",al={"library wing location","where is the library wing","how to find library wing tyr's hand","расположение библиотечного крыла","где библиотечное крыло","как найти библиотечное крыло длани тира"}},{q="Какие книги здесь хранятся?",a="На полках стоят богословские труды о Свете, а также воинственные доктрины и тщательно отобранная фанатичная литература Алого ордена, оправдывающая его нескончаемый поход против нежити и чужаков.",al={"what books are in the library","tyr's hand library tomes","what is stored in the library wing","какие книги в библиотеке","тома библиотеки длани тира","что хранится в библиотечном крыле"}},{q="Кто контролирует эту часть аббатства?",a="Библиотечное крыло прочно удерживают элитные силы Алого ордена, в том числе клирики, ученые и тяжеловооруженные защитники, охраняющие догматические тексты и освященные припасы.",al={"who is in the library wing","who controls the library wing","кто в библиотечном крыле","кто контролирует библиотечное крыло"}},{q="Опасно ли посещать Библиотечное крыло?",a="Да, здесь исключительно опасно. Библиотека находится в глубине Длани Тира — элитного оплота Алого ордена, населенного фанатиками высокого уровня, которые нападают на чужаков без предупреждения.",al={"is the library wing safe","tyr's hand library difficulty","безопасно ли библиотечное крыло","сложность библиотеки длани тира"}}},fp="25,379,23.516.0,20.463.0,34.235.0,34.213.0,36.198.0,39.175.0"}
P.entries["subzone:loading-room"] = {n="Погрузочный зал",s="Погрузочный зал — промышленное складское помещение в обширном механическом комплексе Гномрегана. Сейчас эта подземная площадка находится в глубине оскверненной павшей столицы, опасно близко к взбесившимся механизмам, таким как Техбот.",h="Погрузочный зал — промышленное складское помещение в обширном механическом комплексе Гномрегана.",kw={"dun morogh","gnomeregan","loading room","techbot","tinkertown","train depot","дун морог","гномреган","погрузочный зал","техбот","город механиков","железнодорожное депо"},ang={["profession:Engineering"]="Взбесившийся Техбот и оставшиеся в Погрузочном зале механизмы дают инженерам наглядный урок о том, что случается, когда автоматическая защита выходит из строя без обслуживания.",["race:Gnome"]="Для гномов, возвращающих свой город, Погрузочный зал — горькое напоминание о том, как привычная городская инфраструктура была в спешке брошена во время вторжения троггов и токсичной катастрофы."},sec={{t="Промышленный склад в осаде",b="До падения Гномрегана Погрузочный зал был оживленным транзитным пунктом и грузовым отсеком, связанным с подземными транспортными сетями столицы механиков. Сегодня, как и весь разрушенный город, он погрузился в хаос. Радиоактивные осадки, вторгшиеся трогги и неисправные механизмы сделали это место крайне опасным. Окрестности охраняет взбесившийся механизм Техбот, представляющий серьезную угрозу для выживших гномов и отважных бойцов Альянса, пытающихся отвоевать периметр."}},faq={{q="Для чего использовался Погрузочный зал?",a="Исторически он служил промышленным погрузочным отсеком и грузовым пунктом, связанным с внутренним транспортом и поездами Гномрегана. После падения города он стал еще одним потерянным сектором, захваченным опасностями.",al={"loading room purpose","what is loading room","what was loading room","назначение погрузочного зала","что такое погрузочный зал","чем был погрузочный зал"}},{q="Какие угрозы можно встретить в Погрузочном зале?",a="В Погрузочном зале обитает вышедший из строя механический защитник Техбот, а также повсюду радиоактивное заражение и неисправные механизмы в глубинах города.",al={"who is in loading room","loading room bosses","techbot location","кто в погрузочном зале","боссы погрузочного зала","где техбот"}},{q="Безопасно ли исследовать Погрузочный зал?",a="Нет. Весь этот район — спорная территория среди руин Гномрегана. Любой ударный отряд Альянса, идущий в эту часть комплекса, столкнется с враждебными механизмами и ядовитой средой.",al={"is it safe","can alliance go here","безопасно ли","может ли альянс пройти сюда"}}},fp="12,252,28.525.0,34.220.0,46.194.0,36.199.0"}
P.entries["subzone:longshore"] = {n="Бескрайний берег",s="Бескрайний берег — обширное песчаное побережье, тянущееся вдоль всего западного края Западного Края. Несмотря на простор и живописность, берег известен своей опасностью из-за множества агрессивных мурлоков и разбросанных у побережья обломков кораблей.",h="Бескрайний берег — обширное песчаное побережье, тянущееся вдоль всего западного края Западного Края.",kw={"aquatic form","daphne stilwell","longshore","murloc","old murk-eye","shipwrecks","westfall","westfall lighthouse","водяной облик","дафна стилвелл","бескрайний берег","мурлок","старый мрачноглаз","кораблекрушения","западный край","маяк в западном крае"},ang={["class:Druid"]="Друидам Альянса приходится погружаться в глубины у северо-запада Бескрайнего берега, чтобы найти сундук, спрятанный у затонувшего корабля, и собрать подвеску, необходимую для водяного облика.",["class:Paladin"]="Паладины, следующие указаниям Даториана Ралла в Штормграде, отправляются на юг, на ферму Дафны Стилвелл на Бескрайнем берегу, и доказывают свою доблесть, защищая невинную фермершу от налетчиков Братства Справедливости."},sec={{t="Коварное побережье",b="Бескрайний берег тянется по всей западной границе Западного Края и является одним из самых широких непрерывных пляжей Восточных королевств. Но путникам он почти не дает покоя. Прибрежные мурлоки властвуют в прибое под предводительством таких грозных тварей, как Старый Мрачноглаз, а на мелководье лежат остатки затонувших судов, включая разрушенные эльфийские эсминцы. Ближе к югу одинокие поселенцы вроде Дафны Стилвелл борются с разбойниками Братства Справедливости, находясь в виду Маяка в Западном Крае через воду."}},faq={{q="Почему Бескрайний берег так опасен?",a="Берег кишит агрессивными племенами мурлоков, которые беспрепятственно бродят по пескам и нападают из засады на всякого, кто подойдет слишком близко к прибою. Помимо мурлоков, южную оконечность пляжа беспокоят разбойники Братства Справедливости, грабящие прибрежные усадьбы.",al={"why are there so many murlocs","longshore hazards","is longshore safe","почему так много мурлоков","опасности бескрайнего берега","безопасен ли бескрайний берег"}},{q="Кто такая Дафна Стилвелл?",a="Дафна Стилвелл — одинокая поселенка, живущая на уединенной ферме на юго-западе Бескрайнего берега. Из-за ее уязвимого положения на нее часто нападает Братство Справедливости, и Рыцари Серебряной Длани отправляют ей на защиту послушников-паладинов.",al={"daphne stilwell","stilwell farm","woman on the beach","дафна стилвелл","ферма стилвелл","женщина на пляже"}},{q="Что за кораблекрушения лежат у побережья?",a="У Бескрайнего берега под водой лежит множество обломков — от торговых судов до эльфийских эсминцев, погибших в прошлых морских сражениях. Эти подводные руины привлекают мародеров, мурлоков и искателей приключений, ищущих реликвии, потерянные под волнами.",al={"elven destroyers westfall","sunken ships longshore","shipwrecks","эльфийские эсминцы западный край","затонувшие корабли бескрайний берег","кораблекрушения"}},{q="Почему друиды приходят на Бескрайний берег?",a="Друиды Альянса проходят обряд, известный как Испытание морского льва, чтобы овладеть водяным обликом. Для этого нужно найти подводный сундук у затонувшего корабля у берега на северо-западе Бескрайнего берега и достать из него Половинка подвески Выносливости водяного облика.",al={"druid quest longshore","strange lockbox westfall","half pendant of aquatic endurance","задание друида бескрайний берег","странный сундук западный край","половинка подвески выносливости водяного облика"}}},fp="9,255,23.513.0,34.260.0,23.284.0,44.239.0,34.262.0"}
P.entries["subzone:lordamere-internment-camp"] = {n="Лордамерские выселки",s="Лордамерские выселки — бывший лагерь заключения времен Второй войны, стоящий на возвышенности над кратером Даларана. Некогда построенный для содержания вялых орков, лагерь теперь занят уцелевшими магами и стражами Даларана, а также вероломной группой беглецов из числа Отрекшихся.",h="Лордамерские выселки — бывший лагерь заключения времен Второй войны, стоящий на возвышенности над кратером...",kw={"alterac","belamoore","bloodstone","dalaran","internment","kegan darkmar","lordamere","orcs","альтерак","беламур","кровавый камень","даларан","выселки","кеган мракмар","лордамер","орки"},ang={["race:Orc"]="Для орков посещение этого лагеря — мрачное напоминание о временах после Второй войны, когда тысячи их сородичей чахли в плену, пока Тралл не сплотил их народ.",["race:Undead"]="Дезертиры, засевшие в Лордамере, — прямое предательство Темной Госпожи. Выследить Кегана Мракмара и вернуть кровавые камни необходимо, чтобы тайны Отрекшихся не попали в руки людей."},sec={{t="От тюрьмы до исследовательского форпоста",b="После Второй войны Альянс построил лагеря для интернированных по всем северным королевствам, чтобы содержать побежденную орочью Орду. Лордамер был уникален как единственный лагерь в Альтеракских горах, находившийся под юрисдикцией Даларана. Много лет назад принц Артас Менетил и леди Джайна Праудмур, будучи юными, как известно, тайком пробрались мимо сторожевых башен, чтобы взглянуть на пленных орков и поспорить о нравственности их заключения. Теперь, когда орки давно освобождены или бежали, лагерь под началом тюремщицы Беламур служит форпостом для остатков Даларана, изучающих опасные магические реликвии."},{t="Беглецы из Отрекшихся",b="Лагерь оказался втянут в политику нежити Лордерона. Четверо отрекшихся-ренегатов — Кеган Мракмар и его соратники — похитили из Подгорода могущественные артефакты из кровавого камня и бежали сюда, обменяв их у тюремщицы Беламур на убежище за линиями Даларана. Маги охотно приняли артефакты для изучения тайной магии, а палачи в Мельнице Таррен посылают верных агентов Орды выследить перебежчиков и вернуть похищенные кровавые камни, пока Даларан не открыл их силу."}},faq={{q="Для чего изначально был построен этот лагерь?",a="Его основал Альянс после Второй войны, чтобы держать в заключении пленных орков, впавших в вялость после потери демонической жажды крови. Даларан нес службу на сторожевых башнях и надзирал за лагерем из-за его близости к городу магов.",al={"internment camp history","why is there a camp here","what is this place","история лагеря","почему здесь лагерь","что это за место"}},{q="Кто контролирует лагерь сейчас?",a="Лагерь удерживают тюремщица Беламур и отряд стражей и магов Даларана. Хотя сам Даларан сильно пострадал и укрыт защитным куполом в соседнем кратере, эти уцелевшие продолжают исследования с укрепленного холма.",al={"who lives here","who runs the camp","who is warden belamoore","кто здесь живет","кто управляет лагерем","кто такая тюремщица беламур"}},{q="Почему внутри лагеря есть Отрекшиеся?",a="Это дезертиры из Подгорода под предводительством Кегана Мракмара. Предав королеву Сильвану и украв священные артефакты из кровавого камня, они обменяли реликвии тюремщице Беламур на защиту Даларана от возмездия Отрекшихся.",al={"undead here","kegan darkmar","forsaken deserters","нежить здесь","кеган мракмар","дезертиры отрекшихся"}},{q="Какая связь у этого места с Артасом и Джайной?",a="За годы до того, как Плеть обрушилась на Лордерон, принц Артас Менетил и леди Джайна Праудмур однажды ночью проскользнули мимо стражи лагеря, чтобы увидеть пленных орков. Джайна глубоко посочувствовала заключенным семьям, а Артас считал лагеря суровой необходимостью.",al={"arthas jaina camp","arthas visit","jaina camp","артас джайна лагерь","визит артаса","джайна лагерь"}}},fp="25,274,31.595.0,18.501.1,40.265.0,32.224.0,46.240.0,57.294.0"}
P.entries["subzone:lordamere-lake"] = {n="Озеро Лордамер",s="Озеро Лордамер — одно из крупнейших пресноводных озер Восточных королевств; оно граничит с Тирисфальскими лесами, Серебряным бором и Альтеракскими горами. Когда-то оживленное водное сердце человеческой цивилизации на севере, теперь его холодные воды и острова населяют некроманты Плети, одичавшие мурлоки и расползающаяся тень нежити.",h="Озеро Лордамер — одно из крупнейших пресноводных озер Восточных королевств; оно граничит с Тирисфальскими...",kw={"alterac mountains","dawning isles","fenris isle","lake lordamere","lordamere lake","silverpine forest","thule ravenclaw","tirisfal glades","vile fin","альтеракские горы","рассветные острова","остров фенриса","озеро лордамер","лордамер","серебряный бор","тул коготь ворона","тирисфальские леса","злобный плавник"},ang={["race:Human"]="Тихие, туманные воды Лордамера — мрачное напоминание о разрушенном величии северных человеческих королевств, которые некогда свободно торговали на его берегах.",["race:Undead"]="Для Отрекшихся озеро Лордамер — одновременно оборонительный ров, защищающий Тирисфаль, и действующая линия фронта, где необходимо уничтожить остатки Плети на Острове Фенриса."},sec={{t="Сердце павших королевств",b="В золотой век Альянса Лордерона озеро Лордамер лежало на перекрестке человеческого могущества. Его северные берега охраняла Столица Лордерона, у южной оконечности поднимался город-государство магов Даларан, а гористый восточный край занимал Альтерак. Торговые суда и рыбацкие лодки когда-то без страха пересекали его широкую, окутанную туманом гладь. После разорения Третьей войны озеро превратилось из центра торговли в естественную преграду, отделяющую земли Отрекшихся — Тирисфаль и Серебряный бор — от коварных высот Альтерака."},{t="Спорные просторы",b="Сегодня плавание по темным водам Лордамера полно опасностей. В центре озера лежит Остров Фенриса, где некромант Плети Тул Коготь Ворона и его мертвые прислужники держатся против Отрекшихся, а по окрестностям рыщут свирепые воргены. Дальше к востоку находятся Рассветные острова, полностью захваченные агрессивными мурлоками Злобного Плавника. От руин вокруг Даларана до берегов Подгорода озеро больше не мирный путь, а затопленный рубеж, за который борются уцелевшие чудовища и армии мертвых."}},faq={{q="Какие королевства исторически граничили с озером Лордамер?",a="В пору расцвета Альянса Лордерона озеро Лордамер граничило с тремя крупными человеческими королевствами: Королевством Лордерон на севере и западе, Даларан на юге и Альтерак на восточных горных склонах.",al={"who lived on lordamere lake","lordamere lake history","kingdoms around lordamere","кто жил у озера лордамер","история озера лордамер","королевства вокруг лордамера"}},{q="Кто управляет Островом Фенриса посреди озера?",a="Остров Фенриса сейчас удерживают агенты Плети под командованием некроманта Тула Когтя Ворона, хотя им приходится отражать неослабевающие атаки Отрекшихся и постоянный натиск голодных воргенов.",al={"who is on fenris isle","fenris island lordamere","fenris isle ruler","кто на острове фенриса","остров фенриса лордамер","правитель острова фенриса"}},{q="Что такое Рассветные острова?",a="Рассветные острова — группа небольших островов в восточной части озера Лордамер, к востоку от Острова Фенриса. Их захватили и заняли враждебные мурлоки Злобного Плавника.",al={"dawning isles location","islands in lordamere lake","dawning isles monsters","расположение рассветных островов","острова озера лордамер","монстры рассветных островов"}},{q="Как озеро получило свое название?",a="Озеро названо по соседней Столице и королевству Лордерон, которые получили имя от древнего человеческого полководца Лордена.",al={"lordamere name origin","why is it called lordamere","происхождение названия лордамер","почему озеро называется лордамер"}}},fp="14,349,28.598.0,19.525.0,51.222.0,51.207.0,27.184.0,30.150.0"}
P.entries["subzone:lost-fleet"] = {n="Погибший Флот",s="Погибший Флот — разбитые деревянные остовы Третьей флотилии Кул Тираса, затонувшие у северного побережья Болотины в Бухте Барадин. Уничтоженные во время Второй войны красными драконами, порабощенными кланом Драконьей Пасти, обломки теперь населяют неупокоенные проклятые моряки-нежить, привязанные к ним таинственным проклятием.",h="Погибший Флот — разбитые деревянные остовы Третьей флотилии Кул Тираса, затонувшие у северного побережья...",kw={"baradin bay","bluegill marsh","derek proudmoore","doomed fleet","eye of paleth","fitzsimmons","halyndor","intrepid","lost fleet","snellig","third fleet","wave mistress","wetlands","бухта барадин","болота синежабрых","дерек праудмур","обреченный флот","око палета","фитсиммонс","халиндор","неустрашимый","погибший флот","снеллиг","третья флотилия","повелительница волн","болотина"},ang={["faction:Alliance"]="Остовы — мрачное напоминание о тяжелой цене, которую заплатили Кул Тирас и Альянс во Второй войне; они требуют уважения к павшим и конца их проклятых мук.",["profession:Blacksmithing"]="Кузнецы Альянса часто слышат рассказы о затонувшем флоте: другой корабль той же эскадры, «Летящий орлан», пошел ко дну с редкими слитками светокованого железа."},sec={{t="Трагический конец во Второй войне",b="Во время Второй войны Третья флотилия Кул Тираса находилась под командованием Дерека Праудмура, старшего сына лорда-адмирала. В бою с флотом орков корабли Альянса были атакованы с воздуха красными драконами, порабощенными кланом Драконьей Пасти. Драконье пламя быстро охватило флотилию, и гордые корабли, такие как «Повелительница волн» и «Неустрашимый», разбились на мелях и рифах северных Болот Синежабрых. Почти весь экипаж утонул или сгорел, и единственным выжившим стал Первый помощник Фитсиммонс."},{t="Проклятие Палета",b="Водная могила не стала концом для моряков Третьей флотилии. Глубоко в затонувшем трюме «Неустрашимого» лежал запретный артефакт — Проклятое Око Палета, которое копил жадный командир корабля капитан Халиндор. Темная реликвия осквернила утонувших моряков и привязала их души к расщепленным доскам в облике безумной проклятой нежити. Лишь призрак первого помощника Снеллига сохранил подобие рассудка и бродит по болотистому берегу, пока его бывшие товарищи яростно набрасываются на всех, кто приближается к обломкам."}},faq={{q="Что такое Погибший Флот?",a="Погибший Флот — обломки нескольких боевых кораблей Кул Тираса из Третьей флотилии, лежащие у северного побережья Болотины в Бухте Барадин. Они были уничтожены во время Второй войны, и теперь их населяет нежить из бывших экипажей.",al={"lost fleet","what is this place","wetlands shipwrecks","third fleet","погибший флот","что это за место","кораблекрушения болотины","третья флотилия"}},{q="Как были уничтожены эти корабли?",a="Во время Второй войны флотилию атаковали с воздуха и сожгли порабощенные красные драконы орков из клана Драконьей Пасти. Яростное драконье пламя превратило корабли в горящие остовы, севшие на мель вдоль побережья.",al={"who sank the ships","how did they sink","what destroyed the fleet","кто потопил корабли","как они затонули","что уничтожило флот"}},{q="Почему моряки здесь стали нежитью?",a="Их души остаются привязанными к обломкам проклятием. Первый помощник Фитсиммонс ищет помощи, чтобы выяснить, почему они не могут обрести покой.",al={"why are they ghosts","undead sailors","curse of paleth","почему они призраки","моряки-нежить","проклятие палета"}},{q="Кто-нибудь выжил при гибели флота?",a="Первый помощник Фитсиммонс с «Повелительницы волн» — единственный известный выживший в катастрофе. Он сумел добраться до безопасного места и теперь живет в Гавани Менетилов.",al={"any survivors","did anyone live","fitzsimmons","выжившие","кто-нибудь выжил","фитсиммонс"}},{q="Кто командовал Третьей флотилией?",a="Третьей флотилией командовал Дерек Праудмур, старший сын верховного адмирала Даэлина Праудмура. Дерек погиб на вороньем гнезде своего флагмана, когда драконы охватили флотилию пламенем.",al={"who commanded the fleet","fleet captain","derek proudmoore","кто командовал флотом","капитан флота","дерек праудмур"}}},fp="10,323,30.561.0,19.546.1,23.230.0,31.209.0,32.122.0,48.160.0,37.197.0"}
P.entries["subzone:lost-point"] = {n="Разрушенная башня",s="Разрушенная башня — обветшавшая деревянная сторожевая башня на западе Пылевых топей, изначально построенная силами Терамора как передовой разведывательный пост. Она пришла в упадок и вышла из-под контроля стражи леди Джайны Праудмур, а теперь служит убежищем для дезертиров-изгоев.",h="Разрушенная башня — обветшавшая деревянная сторожевая башня на западе Пылевых топей, изначально построенная...",kw={"balos jacken","dustwallow marsh","lost point","scout tower","theramore deserters","балос хакен","пылевые топи","разрушенная башня","разведывательная башня","дезертиры терамора"},ang={["faction:Alliance"]="Для верных Альянсу Разрушенная башня — горький символ падающей дисциплины в рядах Терамора и логово отступников, хранящих мрачные тайны о военной измене."},sec={{t="Заброшенный форпост",b="Построенная экспедиционными силами Терамора для наблюдения за движением и угрозами из Степей, Разрушенная башня давно пережила свое военное назначение. Застава обветшала от неумолимой сырости топей, дерево гниет, а оборону оставили регулярные войска. Вместо часовых гарнизона башню и ее ближайшие окрестности занимают человеческие дезертиры, ушедшие со службы в Тераморе и нашедшие приют в глухой глуши вдали от дисциплины городских командиров."},{t="Логово дезертиров",b="Дезертиры, засевшие в Разрушенной башне, подчиняются Балосу Хакену, недовольному бывшему солдату, сплотившему этих изгоев. Их присутствие — далеко не просто военное неповиновение. Хакен и его приспешники хранят важные сведения об изменниках в рядах Терамора, включая участие рядового Хендела в опасном заговоре, который тянется до высших кругов Альянса."}},faq={{q="Что такое Разрушенная башня?",a="Разрушенная башня — полуразвалившаяся сторожевая башня, построенная людьми Терамора в западных топях Пылевых топей. Она предназначалась как передовая разведывательная вышка, но военные ее бросили, и ее заняли дезертиры.",al={"lost point overview","what is this tower","about lost point","обзор разрушенной башни","что это за башня","о разрушенной башне"}},{q="Кто сейчас живет в Разрушенной башне?",a="Башню и окружающий лагерь сейчас населяют дезертиры из Терамора. Эти солдаты-отступники нарушили присягу Тераморе и действуют под началом Балоса Хакена.",al={"who is at lost point","lost point enemies","lost point mobs","кто в разрушенной башне","враги разрушенной башни","мобы разрушенной башни"}},{q="Кто такой Балос Хакен?",a="Балос Хакен — главарь дезертиров из Терамора, прячущихся в Разрушенной башне. Несмотря на преступный статус, он обладает важными сведениями о тревожных делах в рядах Терамора.",al={"balos jacken","deserter leader","who leads lost point","балос хакен","главарь дезертиров","кто управляет разрушенной башней"}},{q="Почему Терамор бросил башню?",a="Пылевые топи враждебны, и снабжать их трудно. Когда боевой дух гарнизона упал, а дисциплина ослабла, изолированная застава пришла в упадок и стала идеальным убежищем для солдат, желающих уклониться от службы, не бежав на территорию Орды.",al={"why abandoned","why is lost point ruined","why run down","почему заброшена","почему разрушенная башня в руинах","почему обветшала"}}},fp="10,298,18.537.0,16.431.1,19.221.0,34.198.0,20.194.1,36.246.0"}
P.entries["subzone:lost-rigger-cove"] = {n="Бухта Сорванных Парусов",s="Бухта Сорванных Парусов, укрытая у восточных утесов Танариса, служит главной базой пиратов Южных морей в этом районе. Защищенная с трех сторон высокими пустынными горами, эта скрытая гавань располагает причалами, укрепленными лагерями и действующей верфью, где строят новые пиратские суда.",h="Бухта Сорванных Парусов, укрытая у восточных утесов Танариса, служит главной базой пиратов Южных морей в этом...",kw={"freebooter","gadgetzan","lost rigger cove","shipyard","southsea pirates","tanaris","флибустьеры","прибамбасск","бухта сорванных парусов","верфь","пираты южных морей","танарис"},ang={["class:Rogue"]="Раскинувшийся пиратский лагерь полон карманов для обчистки, личных сундуков и головорезов, знающих все грязные приемы морского разбоя.",["race:Gnome"]="Для гномов-изобретателей пиратский сухой док — грубая, но показательная демонстрация трофейных механизмов и краденых деталей и постоянная угроза каждому торговому судну южных морей."},sec={{t="Пираты и горные стены",b="Естественно укрепленная отвесными скалами почти со всех сторон, Бухта Сорванных Парусов дает Флибустьерам Южных морей идеальный морской оплот на юго-восточной окраине Калимдора. Здесь пираты-головорезы, портовые рабочие и разбойники таскают добычу и собирают новые корпуса прямо под носом у властей Прибамбасска. Из бухты Южные моря могут проецировать силу через Великое море, совершая набеги на торговые пути между Кабестаном, Пиратской бухтой и прибрежными поселениями."},{t="Соперники на пороге",b="Пираты владеют бухтой не без помех. Гоблины Прибамбасска и соседнего Порта Картеля возмущены налетчиками на своем пороге и платят наемникам, чтобы те убивали пиратов, редили их ряды и срывали их операции."}},faq={{q="Кто управляет Бухтой Сорванных Парусов?",a="Бухтой владеют пираты Южных морей — известный морской синдикат, действующий по всему Калимдору и в Южных морях. Эту естественную гавань они используют для ремонта флота и постройки новых боевых кораблей.",al={"who owns lost rigger cove","who lives in lost rigger cove","lost rigger cove factions","кому принадлежит бухта сорванных парусов","кто живет в бухте сорванных парусов","фракции бухты сорванных парусов"}},{q="Кто сражается здесь с пиратами?",a="Гоблины Прибамбасска и Порта Картеля, недовольные налетчиками на своем пороге, нанимают проезжих искателей приключений, чтобы те наносили удары по пиратскому оплоту и сокращали ряды Южных морей.",al={"gnome goblin camp tanaris","why are gnomes here","why fight the pirates","лагерь гоблинов танарис","почему здесь гномы","зачем сражаться с пиратами"}},{q="Где находится Бухта Сорванных Парусов?",a="Она лежит на восточном побережье Танариса, к юго-востоку от Прибамбасска. В нее ведет извилистая тропа по каньону, прорезающему прибрежную горную преграду.",al={"where is lost rigger cove","how to get to lost rigger cove","lost rigger cove map","где бухта сорванных парусов","как добраться до бухты сорванных парусов","карта бухты сорванных парусов"}},{q="Что пираты строят в бухте?",a="Пираты Южных морей держат в центре бухты действующий сухой док и верфь, где плотники и разбойники заняты сборкой корпуса большого океанского боевого корабля.",al={"shipyard lost rigger cove","pirate boat construction","верфь бухта сорванных парусов","постройка пиратского корабля"}}},fp="16,310,26.461.0,22.235.0,30.201.0,33.178.0,34.154.0,42.180.0"}
P.entries["subzone:lushwater-oasis"] = {n="Цветущий оазис",s="Цветущий оазис — один из трех животворных водоемов в засушливых Степях, расположенный к югу от Перекрестка. Несмотря на пышный вид, оазис полон опасностей: он кишит агрессивными кентаврами из племени Колкар и скрывает вход в Пещеры Стенаний. Его оскверненные воды хорошо известны рыболовам, ищущим необычную загадочную рыбу.",h="Цветущий оазис — один из трех животворных водоемов в засушливых Степях, расположенный к югу от Перекрестка.",kw={"crossroads","deviate fish","kolkar","lushwater oasis","the barrens","wailing caverns","перекресток","загадочная рыба","колкар","цветущий оазис","степи","пещеры стенаний"},ang={["class:Druid"]="В Цветущем оазисе наблюдается тревожный неестественный рост растительности, вызванный искаженными энергиями, вырывающимися из соседних Пещер Стенаний.",["profession:Cooking"]="Эти пруды — одни из немногих водоемов, где рыболовы могут выловить загадочную рыбу — ценный по всему Калимдору ингредиент для приготовления вкусных загадочных блюд."},sec={{t="Ненадежное убежище",b="Цветущий оазис, лежащий в недолгом переходе к югу от Перекрестка, дарит обманчивую передышку среди выбеленных солнцем просторов Степей. Пальмовые кроны и свежие источники привлекают жаждущих зверей со всей саванны, а кентавры Колкар занимают берега и подстерегают как дичь, так и неосторожных путников. Оазис также служит вратами в Пещеры Стенаний, чьи обширные подземные ходы просачиваются порочной энергией в пруды наверху, порождая неестественных существ и причудливые мутации."}},faq={{q="Где находится вход в Пещеры Стенаний?",a="Вход в систему пещер Пещер Стенаний вырублен в природных скалах, нависающих над восточной стороной Цветущего оазиса.",al={"where is wc","wc cave entrance","wailing caverns entrance","где пс","вход в пещеры","вход в пещеры стенаний"}},{q="Кто контролирует Цветущий оазис?",a="Кентавры Колкар господствуют по всему оазису: они используют густую растительность, чтобы охотиться на проходящих зверей и нападать на путников, идущих от Перекрестка.",al={"who lives at lushwater oasis","lushwater enemies","centaur at the oasis","кто живет в цветущем оазисе","враги цветущего оазиса","кентавры в оазисе"}},{q="Почему здешняя рыба странная?",a="Глубинные энергии, просачивающиеся из Пещер Стенаний, осквернили водоемы оазиса, из-за чего местная рыба мутирует в необычную загадочную рыбу.",al={"deviate fish location","why deviate fish","mutated fish oasis","где найти загадочную рыбу","почему загадочная рыба","мутировавшая рыба в оазисе"}},{q="Проходила ли здесь Орда Тралла?",a="Во время Долгого марша орков через Степи вместе с таурен Тралл вел своих воинов через разбросанные по региону оазисы, чтобы обеспечить их питьевой водой, отбиваясь от непрестанных засад кентавров.",al={"thrall long march oasis","orcs in barrens oasis","долгий марш тралла оазис","орки в оазисе степей"}}},fp="15,364,22.501.0,53.138.0,29.174.0,30.153.0,39.206.0"}
P.entries["subzone:maclure-vineyards"] = {n="Виноградники Маклура",s="Виноградники Маклура — обширное сельскохозяйственное поместье на юге Элвиннского леса, принадлежащее семье Маклюров. Оно известно виноградом и вином для королевства Штормград, но не менее печально известно затяжной ожесточенной враждой с соседней семьей Стоунфилдов.",h="Виноградники Маклура — обширное сельскохозяйственное поместье на юге Элвиннского леса, принадлежащее семье...",kw={"boars","elwynn","gerard","maclure","maybell","stonefield","vineyard","wine","кабаны","элвинн","джерард","маклюр","мейбелл","стоунфилд","виноградник","вино"},ang={["faction:Alliance"]="Поместье служит важной житницей и виноградником, снабжающим соседние поселения Златоземье и Штормград продовольствием и спиртным.",["race:Human"]="Для людей Штормграда вражда на виноградниках — классический пример деревенского упрямства: она напоминает путникам, что даже в сердце королевства соседи грызутся из-за заборов, пока над ними нависают большие опасности."},sec={{t="Горький урожай",b="Виноградники Маклура, укрывшиеся в зеленых холмах юга Элвиннского леса, должны были бы стать мирным оплотом виноделия и земледелия. Но повседневный труд омрачен жестоким давним соперничеством со Стоунфилдами, живущими неподалеку. Обвинения в воровстве и застарелая злоба глубоко засели между семьями, и страсти не утихают, даже когда общие беды — голодные бродячие кабаны и наступающие кобольды — угрожают обоим хозяйствам."},{t="Запретная любовь",b="Несмотря на яростную вражду двух глав семейств, юная любовь преодолела границы. Мейбелл Маклюр и Томми Джо Стоунфилд тайно влюбились и встречаются в укромных рощах вдали от подозрительных глаз родителей. Те, кто проходит через виноградники, нередко оказываются втянуты в доставку тайных посланий, улаживание мелких обид и попытки помочь юной паре выйти из тени семейной вражды."}},faq={{q="Почему Маклюры и Стоунфилды враждуют?",a="Это давняя деревенская вражда, выросшая из многолетнего недоверия, мелких обвинений и упрямой гордости. Ни одна семья ни на йоту не доверяет другой: они винят друг друга в пропаже товаров и скота, хотя явных доказательств злого умысла нет ни у одной из сторон.",al={"maclure stonefield feud","why do they hate each other","family feud","вражда маклюров и стоунфилдов","почему они ненавидят друг друга","семейная вражда"}},{q="Кто такая Мейбелл Маклюр?",a="Мейбелл — дочь семьи Маклюров. Она тайно влюбилась в Томми Джо Стоунфилда, не считаясь с горькой ненавистью своей семьи к соседям, и надеется найти способ быть вместе с ним.",al={"maybell","maclure daughter","мейбелл","дочь маклюров"}},{q="Какие угрозы есть у виноградников?",a="Помимо семейных споров, виноградники страдают от прожорливых диких кабанов, вытаптывающих посевы и лозы, а также от бродячих кобольдов, совершающих набеги на ближние поля из окрестных золотых копей.",al={"vineyard dangers","boars at maclure","опасности виноградников","кабаны у маклюров"}},{q="Что производят здесь Маклюры?",a="Семья Маклюров выращивает виноград, поставляя вино и свежие фрукты трактирщикам и торговцам по всему Элвиннскому лесу и Штормграду.",al={"what grows here","maclure crops","что здесь растет","урожай маклюров"}}},fp="17,281,16.441.0,19.440.1,46.246.0,23.216.0,35.187.0,34.148.0"}
P.entries["subzone:mage-quarter"] = {n="Квартал магов",s="Квартал магов — магическое сердце Штормграда, расположенное за каналами в юго-западном углу столицы. Над его мощеными улицами и необычными лавками возвышается Святилище волшебника, где заклинатели королевства оттачивают мастерство. Под ученой поверхностью района скрываются и темные закоулки, где обитают приверженцы куда более мрачных искусств.",h="Квартал магов — магическое сердце Штормграда, расположенное за каналами в юго-западном углу столицы.",kw={"arcane","blue recluse","canals","mage quarter","slaughtered lamb","stormwind","wizard's sanctum","тайная магия","синий отшельник","каналы","квартал магов","забитый ягненок","штормград","святилище волшебника"},ang={["class:Mage"]="Этот район — ваш главный дом в Штормграде: в Святилище волшебника есть мастера-наставники и реагенты для заклинаний.",["class:Warlock"]="Под публичным обликом таверны «Забитый ягненок» скрыт тайный ковен, где последователи темных искусств собираются, чтобы обучаться и втайне призывать приспешников."},sec={{t="Святилище тайной магии",b="Квартал магов, до которого можно добраться по мостам через каналы от Соборной площади или Торгового квартала, целиком обслуживает мистические нужды Альянса. Вокруг шпиля Святилища волшебника собираются люди и союзные заклинатели, изучающие плетение тайной магии и обучающие учеников. Окрестные улицы полны торговцев тканями для портняжного дела, реагентами, алхимическими припасами и зачарованными посохами; это замкнутый район, посвященный исследованиям и защите королевства."},{t="Тайны под поверхностью",b="Не вся магия, практикуемая в квартале, одобрена верховными чародеями королевства. Если такие заведения, как «Синий отшельник», дарят ученым тихое убежище, то печально известная таверна «Забитый ягненок» скрывает тайный ковен чернокнижников в подземных склепах. Там, вдали от городской стражи и священных глаз Соборной площади, демонологи изучают запретные обряды Скверны и подчиняют потусторонние сущности, прячась за общей терпимостью района к мистическим аномалиям."}},faq={{q="Что такое Святилище волшебника?",a="Святилище волшебника — заметная башня, господствующая над Кварталом магов. Это главная академия, библиотека и учебная площадка магов Штормграда; здесь живут ученые, мистические наставники и защитные заклинатели, которым поручена охрана столицы.",al={"mage tower","wizards sanctum","mage sanctum stormwind","башня магов","святилище волшебника","святилище магов штормград"}},{q="Где в Квартале магов могут учиться чернокнижники?",a="Чернокнижники тайно собираются под «Забитым ягненком» — неприметной таверной в квартале. В ее склепах и тайных подвалах последователи магии Скверны могут изучать темные ритуалы, призывать демонов и учиться вдали от надзора городской стражи.",al={"warlock trainer location","slaughtered lamb basement","stormwind warlock trainers","учитель чернокнижников","подвал забитого ягненка","учителя чернокнижников штормград"}},{q="Какие лавки есть в Квартале магов?",a="Район полон специализированных лавок для заклинателей и ремесленников. Здесь есть портняжные мастерские, такие как «Ткани Дункана» и «Одежда Ларсона», торговцы алхимическими товарами и травами, зачарователи, поставщики пиротехники и торговцы посохами.",al={"mage quarter vendors","what shops are here","stores in mage quarter","торговцы квартала магов","какие здесь лавки","магазины квартала магов"}},{q="Как добраться до Квартала магов?",a="Квартал магов занимает юго-западный угол Штормграда. Попасть в него можно напрямую, пройдя по мостам через каналы от Торгового квартала или Соборной площади.",al={"where is mage quarter","how to get to mage quarter","directions to mage quarter","где квартал магов","как добраться до квартала магов","дорога до квартала магов"}}},fp="12,378,21.510.0,27.491.1,29.257.0,45.246.0,43.254.0,34.193.0"}
P.entries["subzone:magic-quarter"] = {n="Магический квартал",s="Магический квартал — северо-восточный район Подгорода, центр изучения тайной магии и темного чародейства Отрекшихся. В квартале, над которым возвышается зловещий Храм Проклятых, обитают практики как тайных, так и магии Скверны.",h="Магический квартал — северо-восточный район Подгорода, центр изучения тайной магии и темного чародейства...",kw={"forsaken","mage","magic quarter","portal trainer","tailoring","temple of the damned","undercity","warlock","отрекшиеся","маг","магический квартал","учитель порталов","портняжное дело","храм проклятых","подгород","чернокнижник"},ang={["class:Mage"]="Магический квартал — сердце чародейства Отрекшихся: здесь обучают тайным искусствам и сетям телепортации, связывающим Подгород с остальной Ордой.",["class:Warlock"]="В темных нишах Храма Проклятых чернокнижники призывают демонических прислужников и оттачивают магию Тьмы вдали от осуждающих глаз Альянса."},sec={{t="Средоточие темных искусств",b="Магический квартал занимает северо-восточную четверть подземного города. Здесь Отрекшиеся хранят свое тайное наследие и погружаются в более темные методики. Центр района — возвышающийся Храм Проклятых, архитектурная реликвия, построенная Плетью и перепрофилированная свободной нежитью. Под его сводчатыми сумрачными потолками маги тонко управляют магическими энергиями, а чернокнижники общаются с демонами, что делает квартал средоточием интеллектуальной мощи и оккультных исследований в Лордероне."},{t="Ученые, ткачи и призыватели",b="Помимо изучения чистой магии вызова и призыва, Магический квартал служит важным общественным центром для заклинателей. Учителя порталов поддерживают сообщение между землями Орды, а мастера-портные работают с напитанными магией тканями, создавая робы и покровы. В отличие от Даларана, где строго разделены академическое волшебство и запретная магия, Отрекшиеся открыто сочетают в этих залах тягу к тайному знанию и силу Скверны, чтобы закрепиться среди множества врагов."}},faq={{q="Для чего нужен Магический квартал?",a="Магический квартал — центр изучения тайной магии и магии демонов у Отрекшихся. Здесь находятся учителя классов для магов и чернокнижников, мастера порталов, соединяющих с другими городами, и портные, ткущие зачарованную ткань.",al={"what is magic quarter","magic quarter purpose","undercity magic district","что такое магический квартал","назначение магического квартала","магический район подгорода"}},{q="Почему в Подгороде есть Храм Проклятых?",a="Когда Плеть вырыла Подгород под руинами Столицы, она возвела такие сооружения, как Храм Проклятых. Когда Сильвана и ее свободные Отрекшиеся захватили подземный комплекс, они заняли эти готовые здания и приспособили их для своих заклинателей.",al={"temple of the damned undercity","why temple of the damned here","scourge building undercity","храм проклятых подгород","почему здесь храм проклятых","постройка плети в подгороде"}},{q="Кого можно обучить в Магическом квартале?",a="Учителя магов, чернокнижников и повелителей демонов обучают практиков в квартале, а мастера порталов и портные дают обучение перемещению и ремеслу.",al={"trainers in magic quarter","who trains here","magic quarter classes","учителя в магическом квартале","кто здесь обучает","классы магического квартала"}},{q="Где находится Магический квартал?",a="Он расположен в северо-восточной четверти Подгорода, напротив Апотекариума через центральное кольцо.",al={"where is magic quarter","magic quarter location","find magic quarter","где магический квартал","расположение магического квартала","найти магический квартал"}}},fp="13,245,23.561.0,32.481.0,41.233.0,53.301.0,40.165.0,35.117.0"}
P.entries["subzone:magram-village"] = {n="Деревня Маграм",s="Деревня Маграм — поселение клана кентавров Маграм среди зловонных желтых прудов на юго-востоке Пустошей. Это главная база Маграмов в их беспощадной войне с ненавистными соперниками — Гелкисами.",h="Деревня Маграм — поселение клана кентавров Маграм среди зловонных желтых прудов на юго-востоке Пустошей.",kw={"centaur","desolace","gelkis","magram","magram village","pools","кентавр","пустоши","гелкис","маграм","деревня маграм","пруды"},ang={["race:Tauren"]="Дикость кентавров терзает племена Калимдора на протяжении поколений, поэтому любое поселение этих кочевых грабителей тревожно напоминает о былом кровопролитии."},sec={{t="Оплот в трясине",b="Деревня Маграм раскинулась на островах и берегах вокруг стоячих сернистых прудов на юго-востоке Пустошей. Это грубое поселение из кое-как сколоченных деревянных мостков и шатров из шкур. Кентавры Маграм живут здесь в постоянной бдительности по отношению к соседним кланам. Известные жестокостью и глубокой враждой к южному клану Гелкис, Маграмы терпят чужаков, лишь если те докажут свою ценность, перебив их врагов Гелкисов."}},faq={{q="Кто живет в Деревне Маграм?",a="В деревне живет клан Маграм, один из нескольких враждующих племен кентавров Пустошей. Они живут под грубыми навесами из шкур на островах, соединенных неказистыми мостками.",al={"who is here","magram residents","centaur village","кто здесь живет","жители маграма","деревня кентавров"}},{q="Можно ли войти в Деревню Маграм, не подвергшись нападению?",a="Поначалу кентавры Маграм враждебны ко всем чужакам. Однако путники могут завоевать их доверие, выслеживая и убивая их заклятых врагов — кентавров Гелкис, и тем повысить свою репутацию у клана.",al={"are magram friendly","magram hostile","how to visit magram village","дружелюбны ли маграмы","маграмы враждебны","как посетить деревню маграм"}},{q="Почему пруды вокруг деревни желтые?",a="Пруды в деревне и вокруг нее загрязнены серой и минеральными стоками, типичными для бесплодных земель Пустошей, из-за чего вода стоячая, мутная и отравленная.",al={"yellow water","polluted pools","magram water","желтая вода","загрязненные пруды","вода маграма"}},{q="Почему Маграмы воюют с Гелкисами?",a="Кланы кентавров Пустошей давно славятся кровожадным соперничеством. Кланы Маграм и Гелкис особенно ожесточенно воюют за господство над югом пустынных земель уже многие поколения.",al={"magram vs gelkis","centaur blood feud","centaur war","маграм против гелкис","кровная вражда кентавров","война кентавров"}}},fp="14,232,24.482.0,28.176.0,50.201.0,44.169.0,39.210.0"}
P.entries["subzone:main-hall-northshire"] = {n="Главный зал (Североземье)",s="Главный зал — центральный входной зал Аббатства Североземья в Элвиннском лесу. Это главный перекресток, соединяющий территорию аббатства с его верхней башней, Залом Оружия и Библиотечным крылом. Здесь новоприбывшие люди-герои являются за первыми поручениями на службе Королевства Штормград.",h="Главный зал — центральный входной зал Аббатства Североземья в Элвиннском лесу.",kw={"abbey","elwynn","hall of arms","library wing","main hall","northshire","stormwind","аббатство","элвиннский лес","зал оружия","библиотечное крыло","главный зал","североземье","штормград"},ang={["race:Human"]="Для людей королевства Главный зал Аббатства Североземья знаменует начало пути на службе Штормграду и Свету."},sec={{t="Сердце аббатства",b="Пройдя через величественные арки Аббатства Североземья, посетители попадают прямо в Главный зал. Как центральный узел здания, он направляет прибывающих новобранцев и клириков между разными частями аббатства: воинским Залом Оружия с одной стороны, ученым Библиотечным крылом с другой и лестницей, ведущей в башню аббатства. Тишину зала нарушает непрекращающаяся борьба в долине: офицеры собирают здоровых новичков на защиту границ королевства."}},faq={{q="Для чего нужен Главный зал?",a="Главный зал служит центральным приемным залом и перекрестком Аббатства Североземья. Он направляет новобранцев, священников и посетителей в Зал Оружия, Библиотечное крыло и верхнюю башню аббатства.",al={"what is main hall","northshire main hall use","что такое главный зал","назначение главного зала североземья"}},{q="Кто направляет здесь новобранцев?",a="Офицеры и клирики обороны Штормграда, находящиеся в Главном зале, оценивают прибывающих героев и дают им первые боевые приказы — очистить окрестности аббатства от угроз.",al={"who gives quests here","abbey commander","кто дает задания","командир аббатства"}}},fp="22,334,18.494.0,37.202.0,30.208.0"}
P.entries["subzone:maker-s-terrace"] = {n="Терраса Творца",s="Терраса Творца — обширные открытые раскопки на севере Бесплодных земель, прямо перед входом в древнее хранилище титанов Ульдаман. Путникам, идущим на юг из Лок Модана, приходится пробираться по ее неровной окраине, занятой враждебными дворфами из клана Черного Железа. Раскопки — спорный порог между пустошами на поверхности и тайнами титанов, погребенными внизу.",h="Терраса Творца — обширные открытые раскопки на севере Бесплодных земель, прямо перед входом в древнее...",kw={"badlands","dark iron","excavation","maker's terrace","makers terrace","titans","uldaman","бесплодные земли","черное железо","раскопки","терраса творца","титаны","ульдаман"},ang={["profession:Mining"]="Обширные карьеры и земляные работы, прорезанные в песчаниковых утесах, ясно свидетельствуют об интенсивной добыче руды дворфийскими землекопами.",["race:Dwarf"]="Для дворфов Стальгорна видеть Террасу Творца в руках вероломного клана Черного Железа горько: Ульдаман хранит глубочайшие тайны происхождения дворфов."},sec={{t="Порог хранилища",b="Терраса Творца раскинулась на северных утесах Бесплодных земель и служит внешним плацдармом для подземных залов Ульдамана. Еще до спуска в подземные руины путникам приходится иметь дело с опаленными солнцем земляными работами, лесами и каменными траншеями этих грандиозных раскопок. Она лежит прямо у перевала, ведущего из Лок Модана, и потому первой встречает любого, кто решится отправиться в засушливые пустоши. Терраса кипит жестокой деятельностью: враждующие стороны ищут путь к древним тайнам под скалами."},{t="Оккупация Черного Железа",b="Раскопки твердо удерживает клан Черного Железа, патрулирующий рвы и границы с враждебной бдительностью. Привлеченные запахом реликвий титанов и жаждой подземного господства, эти подземные дворфы неустанно роют склон холма в поисках оружия, записей и земных реликвий, оставленных древними Творцами. Всякий, кто попытается пройти в глубокие залы Ульдамана, не разобравшись с укрепленными дозорными, быстро окажется разгромлен."}},faq={{q="Где находится Терраса Творца?",a="Терраса Творца находится на дальнем севере Бесплодных земель, возле долинного перевала, соединяющего эту зону с Лок Моданом. Она окружает внешний вход в древний комплекс Ульдаман.",al={"maker's terrace location","where is makers terrace","how to find makers terrace","где терраса творца","расположение террасы творца","как найти террасу творца"}},{q="Кто управляет Террасой Творца?",a="Место занято и патрулируется враждебными дворфами из клана Черного Железа, которые ведут активные раскопки и яростно охраняют внешние подступы к Ульдаману от чужаков.",al={"who is at makers terrace","makers terrace enemies","who controls makers terrace","кто на террасе творца","враги террасы творца","кто владеет террасой творца"}},{q="Для чего ведутся раскопки?",a="Дворфы клана Черного Железа раскапывают древний комплекс титанов Ульдаман. Они стремятся добыть реликвии, мощные механизмы и древние тайны титанов, погребенные в подземных хранилищах, прежде чем их заберут соперники.",al={"why are they digging here","makers terrace dig","what are dark irons looking for","почему здесь копают","раскопки террасы творца","что ищет черное железо"}},{q="Является ли Терраса Творца частью Ульдамана?",a="Да, Терраса Творца — внешний открытый раскоп, ведущий прямо в подземелье и пещеры Ульдамана.",al={"is this uldaman","makers terrace vs uldaman","terrace connection to dungeon","это ульдаман","терраса творца и ульдаман","связь террасы с подземельем"}}},fp="15,402,22.586.0,20.471.0,37.203.0,33.169.0,38.225.0,35.127.0"}
P.entries["subzone:malaka-jin"] = {n="Малака'джин",s="Малака'джин — небольшой лагерь Орды в предгорьях Когтистых гор, к югу от Заставы Зловещего Тотема. Его населяют в основном охотники-тролли из племени Черного Копья; поселение служит простой станцией и охотничьим форпостом для путников, поднимающихся в суровые горы из Степей.",h="Малака'джин — небольшой лагерь Орды в предгорьях Когтистых гор, к югу от Заставы Зловещего Тотема.",kw={"darkspear","grimtotem","horde","hunters","malaka'jin","outpost","stonetalon","trolls","черное копье","зловещий тотем","орда","охотники","малака'джин","форпост","когтистые горы","тролли"},ang={["faction:Horde"]="Малака'джин — самый южный рубеж Орды в Когтистых горах, важная станция на тропе между Степями и северными горными оплотами.",["race:Troll"]="Для троллей Черного Копья Малака'джин — гордое свидетельство самостоятельности троллей и их искусства выслеживания: они обустроили дом в суровых высотах вдали от тропических берегов Калимдора."},sec={{t="Убежище охотников",b="Малака'джин, укрытый возле главной тропы в Когтистые горы, — желанное убежище для странников Орды, отправляющихся в спорные высоты. В деревне живет отряд суровых троллей-охотников, добывающих пропитание на утесах и в зарослях. Живя скромно, эти охотники предлагают припасы, обменивают свежую дичь усталым путникам и настороженно следят за враждебными горными животными и воинственными тауренами Зловещего Тотема, скрывающимися выше по тропам."},{t="Опора в горах",b="Малака'джин, шатко стоящий у границы Степей, — одно из первых мест, где Орда закрепилась в Когтистых горах. Хотя он мал и тих по сравнению с большой крепостью Приют у Солнечного Камня дальше на севере, он служит важной опорной базой: следопыты Орды наблюдают за племенными волнениями и защищают извилистые дороги от наступающих угроз."}},faq={{q="Что такое Малака'джин?",a="Малака'джин — небольшая деревня и форпост Орды на юге Когтистых гор. Его населяет община троллей-охотников из племени Черного Копья, дающая кров, торговлю и припасы путникам, поднимающимся из Степей.",al={"where is malakajin","what is this place","malakajin stonetalon","где малака'джин","что это за место","малака'джин когтистые горы"}},{q="Кто живет в Малака'джине?",a="Поселение почти целиком населено троллями-охотниками. Они живут охотой на горную дичь и торгуют мясом и кожей с проходящими путниками.",al={"malakajin npcs","who is here","trolls in stonetalon","персонажи малака'джина","кто здесь живет","тролли в когтистых горах"}},{q="Какие угрозы нависают над лагерем?",a="Помимо свирепых горных хищников, деревня расположена прямо к югу от враждебной Заставы Зловещего Тотема, и небольшой лагерь троллей постоянно настороже перед агрессией враждебного племени тауренов.",al={"malakajin enemies","who attacks malakajin","враги малака'джина","кто нападает на малака'джин"}},{q="Есть ли здесь распорядитель полетов?",a="Нет. В это время в Малака'джине нет распорядителя полетов. Путникам в Когтистых горах приходится пользоваться распорядителем полетов в Приюте у Солнечного Камня дальше на северо-запад или идти по дороге пешком.",al={"malakajin flight path","fly to malakajin","полеты малака'джин","долететь до малака'джина"}}},fp="10,305,17.479.0,25.373.0,19.227.0,24.169.0,27.211.0,30.203.0"}
P.entries["subzone:malden-s-orchard"] = {n="Сад Мальдена",s="Сад Мальдена — разрушенная ферма на севере Серебряного бора, названная по имени хозяина-человека, который бежал во время вторжения Плети в Лордерон. Давно заброшенный сад зарос темными вечнозелеными деревьями, а по его территории рыщут свирепые черные воргены-волки. Развалившийся домик сада стал временным убежищем для отрезанного от своего отряда разведчика Отрекшихся.",h="Сад Мальдена — разрушенная ферма на севере Серебряного бора, названная по имени хозяина-человека, который...",kw={"cottage","erland mckree","ivar patch","malden","malden's orchard","maldens orchard","silverpine","worgs","домик","эрланд маккри","делянка ивара","мальден","сад мальдена","серебряный бор","ворги"},ang={["faction:Horde"]="Путникам, идущим на юг от Гробницы или от границы Тирисфаля, следует осторожно обходить сад из-за агрессивных стай воргенов-волков, поселившихся на ферме.",["race:Undead"]="Для Отрекшихся сад напоминает о гибели людей и является спорным участком севера Серебряного бора, который разведчики Стражей смерти должны защищать от диких зверей."},sec={{t="Зараженный урожай",b="До Третьей войны эта усадьба снабжала свежими фруктами города Лордерона; за ней ухаживал фермер по имени Мальден. Когда Плеть прошла по королевству, Мальден бросил свою землю и бежал от чумы. С тех пор сад задыхается в темных наступающих туманах Серебряного бора. Вечнозеленые деревья не подрезаны, а плоды гниют несобранными на зараженных ветвях, и участок полностью отвоевали дикие хищники."},{t="В ловушке в домике",b="Заросший сад стал охотничьими угодьями территориальных черных воргенов-волков, и пройти здесь по северу Серебряного бора опасно. Во время разведывательного задания для Стражей смерти разведчик Эрланд Маккри был послан осмотреть местность, но оказался в окружении зверей. Несколько дней он пролежал взаперти в полуразрушенном домике Мальдена и дожил лишь до того, как подкрепление Отрекшихся прорвалось сквозь стаю и проводило его обратно к товарищам-разведчикам в Делянке Ивара."}},faq={{q="Кто такой Мальден?",a="Мальден был фермером-человеком, жившим здесь до падения Лордерона. Он бросил сад и бежал, спасая жизнь, когда Плеть вторглась в королевство во время Третьей войны.",al={"malden lore","who owned the orchard","who is malden","мальден","кто владел садом","кто такой мальден"}},{q="Почему в саду полно воргенов-волков?",a="Когда не осталось живых хозяев, способных защитить ферму, дикие черные воргены-волки, бродившие по Серебряному бору, сделали густую рощу и заброшенный двор территорией своей стаи.",al={"why are there worgs here","malden orchard dogs","worg infestation","почему здесь ворги","сад мальдена собаки","нашествие воргов"}},{q="Кто заперт в домике?",a="В домике заперт страж смерти Эрланд Маккри. Посланный Отрекшимися в разведку, он попал в засаду воргенов-волков сада и отсиживался внутри, пока не пришла помощь.",al={"cottage scout","who is in the house","deathstalker in the cabin","разведчик в домике","кто в доме","страж смерти в хижине"}},{q="Собирает ли кто-нибудь теперь фрукты в этом саду?",a="Нет. За темными деревьями не ухаживали годами, и их плоды гниют на ветвях среди порчи, расползающейся по Серебряному бору.",al={"is the fruit edible","malden's orchard harvest","can you pick fruit","съедобны ли фрукты","урожай сада мальдена","можно ли собирать фрукты"}}},fp="16,362,18.448.0,22.486.1,15.174.0,33.159.0,34.186.0,48.140.0"}
